window.HIKAM_SEED=[{"id":"m1","text":"لا تعدن عدة لا تثق من نفسك بإنجازها.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص3"},{"id":"m2","text":"لا يغرنك المرتقى السهل إذا كان المنحدر وعرا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص3"},{"id":"m3","text":"عواقب الأعمال من جنسها، فالعمل الصالح عاقبة صالحة، والعمل الخبيث عاقبته خبيثة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص3"},{"id":"m4","text":"اللهم إنا نعوذ بك من بلاء ليس معه ثواب، ونسألك عافية معها ثواب.","kind":"hikma","topic":"الإيمان والعبادة","note":"دعاء","source":"شذرات المطوع، ص3"},{"id":"m5","text":"اللهم إنا نعوذ بك من فقر ليس معه صبر، ونسألك غنى معه شكر.","kind":"hikma","topic":"الإيمان والعبادة","note":"دعاء","source":"شذرات المطوع، ص3"},{"id":"m6","text":"الخضاب شاهد زور.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص3"},{"id":"m7","text":"إذا كان الكثير كرما، كان الأكثر منه إسرافا، والأقل منه بخلا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص3"},{"id":"m8","text":"من كانت حوائج الناس إليه، فهي نعمة من الله عليه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص3"},{"id":"m9","text":"أفضل المال ما أكسب أجرا، وقهر فقرا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص3"},{"id":"m10","text":"أكرم الناس من أعطى من لا يرجوه، وأنال قبل السؤال.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص3"},{"id":"m11","text":"قال محتضر : الرجوع إلى من يرجى عفوه، ويطمع في خيره، خير من البقاء مع من لا يؤمن شره، ولا يرجى عفوه.","kind":"hikma","topic":"الإيمان والعبادة","note":"«محتضر» ترجيح من «حمتض» في المصدر","source":"شذرات المطوع، ص3"},{"id":"m12","text":"من شاب شعره فقد مات بعضه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص3"},{"id":"m13","text":"من أكثر من استماع الحكمة أوشك أن ينطق بها.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص3"},{"id":"m14","text":"أربعة لا يستحي من خدمتهم : السلطان والوالد والضيف والدابة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص3"},{"id":"m15","text":"إذا جعلك الأمير من خواصه فلا تكثر الملق والدعاء، وعظمه ووقره عند الناس.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص3"},{"id":"m16","text":"رب كلمة تقول لقائلها : دعني.","kind":"mathal","topic":"الكلام والصمت","source":"شذرات المطوع، ص3"},{"id":"m17","text":"العصبية : أن يرى الرجل شرار قومه خيرا من خيار قوم آخرين. وأن يرى باطل قومه أحق من حق قوم آخرين.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص3"},{"id":"m18","text":"من محاسن النوم أن فيه إعراض عن الأعراض.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص3"},{"id":"m19","text":"لعل الفرج قريب وأنت لا تدري.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص4"},{"id":"m20","text":"من أساء إليك فقد مكنك من لذة الذم والغيبة، ومن أحسن إليك فقد حرمك لذة الذم ومزمزة الغيبة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص4"},{"id":"m21","text":"إذا زرت البخيل أعانك على الذم، وإذا زرت الكريم حرمك لذة الذم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص4"},{"id":"m22","text":"ناموس المشايخ قلة المزح وكثرة الصمت، وناموس الشباب كثرة المزح وقلة الصمت.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص4"},{"id":"m23","text":"نسبة الصواب إلى قائله أحمد من التفرد بالادعاء.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص4"},{"id":"m24","text":"من لم يسخط نفسه في شهوته، لم يرض ربه في طاعته.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص4"},{"id":"m25","text":"لو اطلع ابن آدم على ما بقي من أجله، لزهد في طول ما يرجو من أمله.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص4"},{"id":"m26","text":"هب المسيء قد عفي عنه، أليس قد فاته ثواب المحسنين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص4"},{"id":"m27","text":"رفاهة العيش ومحبة النساء والأولاد توهي العزم، وتكسر حمية الشجاعة، وتحبب السلامة، وتباعد من ركوب المخاطر.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص4"},{"id":"m28","text":"ليس مع الاستئثار محبة، ولا مع المواساة بغضة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص4"},{"id":"m29","text":"الملك الذي يطلب طاعة رعيته بالإحسان والمودة، أحمد عاقبة وأفضل عافية من الذي يطلبها بالقهر والاستطالة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص4"},{"id":"m30","text":"إذا غضبت على من تعاطى ما يغضبك، فاجعل بين غضبك ورضاك مدة بقدر ما تردعه عن تعاطي ما يغضبك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص4"},{"id":"m31","text":"لو أن أحدا قليل العلم عمل بعلمه لكان جديرا بالنجاة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص4"},{"id":"m32","text":"لو أن أحدا كثير العلم لم يعمل بعلمه لكان جديرا بالهلاك.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص4"},{"id":"m33","text":"تعودوا الخير فإنما الخير عادة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص4"},{"id":"m34","text":"السحاب فحل الأرض.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص5"},{"id":"m35","text":"إذا كان لك أكثري فتجاف عن أقلي.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص5"},{"id":"m36","text":"الدرهم يزرع، والسيف يحصد.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص5"},{"id":"m37","text":"إن لم ترهب فأرغب.","kind":"mathal","topic":"السياسة والقيادة","source":"شذرات المطوع، ص5"},{"id":"m38","text":"اشبع من تخشاه فإن لم تشبعه أكلك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص5"},{"id":"m39","text":"استدم النعم بالشكر، والمقدرة بالعفو، والطاعة بالتألف، والنصر بالتواضع، والرحمة بالرحمة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص5"},{"id":"m40","text":"اطلب الرحمة بالرحمة، والستر بالستر، وتفريج الكرب بتفريج الكرب، والتجاوز بالتجاوز، والسماح بالسماح، والرفق بالرفق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص5"},{"id":"m41","text":"اطلب كل شيء من الله تعالى بأن تعمل مثله مع عباده.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص5"},{"id":"m42","text":"إذا أردت أن يكون الله سبحانه معك كما تريد، فعامل عباده كما يريد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص5"},{"id":"m43","text":"ما تريده من الله تعالى اطلبه بأن تفعله مع عباده.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص5"},{"id":"m44","text":"إذا وضحت الحجة ثقل استماع المنازعة فيها.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص5"},{"id":"m45","text":"أول طريق الحكمة اتهام الرأي، واحتقار النفس، ومعوقاتها الإعجاب بالرأي وتعظيم النفس.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص5"},{"id":"m46","text":"أقدار الله تعالى تأتي على كل حال : فقير يستغني، وغني يفتقر، وشيخ يعمر، وطفل يموت، وطبيب يهلك، ومريض يعيش، فلا تأمن في أي حال.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص5"},{"id":"m47","text":"الطاعات تخفف من كربة الموت، والمعاصي تزيدها.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص5"},{"id":"m48","text":"من اشتغل بالطاعات أحب لقاء الله فخف عليه مجيء الأجل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص5"},{"id":"m49","text":"من اشتغل بمعاصي الله كره لقاء الله، فثقل عليه مجيء الأجل.","kind":"hikma","topic":"الإيمان والعبادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m50","text":"المبادرة في إثابة المحسن تعدل التثبت في عقوبة المسيء.","kind":"hikma","topic":"السياسة والقيادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m51","text":"إذا عم الشر فخير الناس النومة ( الخامل ).","kind":"hikma","topic":"العلاقات والناس","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m52","text":"استرجع شارد النعمة بالتوبة والاستغفار، واستدم راهنها بالشكر وكرم الجوار.","kind":"hikma","topic":"الإيمان والعبادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m53","text":"الشكر يزرع، والكفر يحصد.","kind":"hikma","topic":"الإيمان والعبادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m54","text":"من أطعمه التراب أكله التراب.","kind":"hikma","topic":"المال والاقتصاد","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m55","text":"من كثر جده ثقل، ومن كثر هزله رذل، وليكن مقدار المزاح في الكلام، مقدار الملح في الطعام.","kind":"hikma","topic":"الكلام والصمت","note":"في المصدر «هزل» بلا هاء؛ الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m56","text":"آفة الأمن التفريط، وثمرة الخوف الحزم.","kind":"hikma","topic":"العقل والحكمة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m57","text":"حاجة الحكيم إلى السفه حاجة العجين إلى الملح.","kind":"hikma","topic":"العقل والحكمة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m58","text":"حاجة الحليم إلى الغضب حاجة الدواء إلى السم.","kind":"hikma","topic":"الأخلاق والآداب","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m59","text":"الذي يقرأ القرآن إنما يحدث عن ربه.","kind":"hikma","topic":"الإيمان والعبادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m60","text":"على ألافها الطير تقع.","kind":"mathal","topic":"العلاقات والناس","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m61","text":"الذكر صابون القلوب، والاستغفار صابون الذنوب.","kind":"hikma","topic":"الإيمان والعبادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m62","text":"السفر يعطل العادات، ويكسب المستجدات.","kind":"hikma","topic":"الحياة والزمن","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m63","text":"من بادر بالإنكار مخطئا وهو لا يعلم، أعذر ممن بادر بالإقرار مصيبا وهو لا يعلم.","kind":"hikma","topic":"العقل والحكمة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m64","text":"الإقرار بعد الإنكار أيسر من الإنكار بعد الإقرار.","kind":"hikma","topic":"الكلام والصمت","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m65","text":"من سلب نعمة غيره، سلب غيره نعمته.","kind":"hikma","topic":"الأخلاق والآداب","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m66","text":"مريض يشتهي أرجى من مريض لا يشتهي.","kind":"mathal","topic":"الصحة والنفس","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m67","text":"عدل السلطان صلاح العمران.","kind":"hikma","topic":"السياسة والقيادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m68","text":"جور السلطان خراب العمران.","kind":"hikma","topic":"السياسة والقيادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m69","text":"إصلاح الموجود مقدم على انتظار المفقود.","kind":"hikma","topic":"العقل والحكمة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m70","text":"غاية الاحتمال تمكين الفرصة.","kind":"hikma","topic":"الصبر والشدائد","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m71","text":"العمل يحتاج إلى الإرادة، والإرادة تحتاج إلى العلم، والعلم يحتاج إلى العقل، والعقل يحتاج إلى التجارب، والتجارب لا تتم إلا بمزاولة العمل، إذا العمل يحتاج إلى العمل.","kind":"hikma","topic":"النجاح والإبداع","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m72","text":"تجويد العمل لا يتم إلا بكثرة مزاولة العمل.","kind":"hikma","topic":"النجاح والإبداع","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m73","text":"غاية الاستمرار بالعمل كثرة الجودة والمهارة، وقلة الوقت والمجهود.","kind":"hikma","topic":"النجاح والإبداع","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m74","text":"مشقة العمل بالمكابدة والمقاومة تقل وتخف، وبالتواني والتراخي تزيد وتثقل.","kind":"hikma","topic":"النجاح والإبداع","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m75","text":"ضرب الوالد للولد كضرب المنجد للقطن، يضربه لإصلاحه وتجديده.","kind":"hikma","topic":"التربية والأسرة","note":"في المصدر «كضب» و«بضبه»؛ الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m76","text":"الستر رداء الرذائل، والإخلاص رداء الفضائل.","kind":"hikma","topic":"الأخلاق والآداب","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m77","text":"ما نجا مجاهر، ولا هلك مستور.","kind":"hikma","topic":"الأخلاق والآداب","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m78","text":"الرذيلة المستورة كالفضيلة المنشورة.","kind":"hikma","topic":"الأخلاق والآداب","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m79","text":"ستر المثالب خير من نشر المناقب.","kind":"hikma","topic":"الأخلاق والآداب","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m80","text":"مقاربة العامة بلين الكلام، وخفض الجناح، وسكون الطائر.","kind":"hikma","topic":"السياسة والقيادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m81","text":"مقاربة الخاصة ببسط اليد، ورفع الحجاب، وطلاقة الوجه.","kind":"hikma","topic":"السياسة والقيادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m82","text":"لتمزيق عرض البخيل حلاوة لا توجد في مدح الكريم.","kind":"hikma","topic":"العلاقات والناس","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m83","text":"اللهم إنا من فضلك، نسألك بفضلك، من فضلك.","kind":"hikma","topic":"الإيمان والعبادة","note":"دعاء؛ الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m84","text":"في الاغتراب يزيد الاقتراب، فابن البلد كابن الولد.","kind":"hikma","topic":"العلاقات والناس","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m85","text":"قبل أن تحسو ذق.","kind":"mathal","topic":"العقل والحكمة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m86","text":"العقل صديق لا يطاع، والهوى عدو يطاع.","kind":"hikma","topic":"العقل والحكمة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m87","text":"الرعية تنقاد للحاكم والأمراء، والحاكم والأمراء ينقادون لأهل الرأي والعقلاء.","kind":"hikma","topic":"السياسة والقيادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m88","text":"أهل الرأي والعلم يحكمون على الناس، بواسطة الأمراء والكبراء.","kind":"hikma","topic":"السياسة والقيادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m89","text":"قبح الخطأ أظهر جمال الصواب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص8"},{"id":"m90","text":"سمعنا من يبرئ الأكمه والأبرص، وما سمعنا من يبرئ الأحمق.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص8"},{"id":"m91","text":"من يعلم أنه جاهل أفضل ممن يجهل أنه جاهل.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص8"},{"id":"m92","text":"الجاهل الذي لا يجهل أنه جاهل أفضل من الجاهل الذي يجهل أنه جاهل.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص8"},{"id":"m93","text":"من لا يعلم ويعلم أنه لا يعلم خير ممن لا يعلم ولا يعلم أنه لا يعلم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص8"},{"id":"m94","text":"الأحمق المتعاقل كالجاهل المتعالم، والشيخ المتصابي كالصبي المتشايخ.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص8"},{"id":"m95","text":"إن المستشير معان فهو بين صواب يفوز بثمرته، وخطأ يشارك في مكروهه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص8"},{"id":"m96","text":"لا تستشر بخيلا فيحسن لك البخل، ولا مبذرا فيحسن لك التبذير، ولا جبانا فيحسن لك الجبن، ولا متهورا فيحسن لك التهور، ولكن استشر عالما مستقيم الرأي، مجربا خبيرا بما تستشيره به.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص8"},{"id":"m97","text":"المستشار ليس بضامن، والرأي ليس بمضمون.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص8"},{"id":"m98","text":"من استخار ربه، وشاور نصيحه، واجتهد رأيه، فقد أدى ما عليه، ويقضي الله تعالى ما يشاء.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص8"},{"id":"m99","text":"ليردعك عن الناس ما تعرف من نفسك، ولا تجد عليهم فيما تأتي.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص8"},{"id":"m100","text":"لا عقل كالتدبير، ولا ورع كالكف.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص8"},{"id":"m101","text":"آفة النصيحة الفضيحة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص8"},{"id":"m102","text":"لا تحتقر شرا فإن قليله كثير.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص9"},{"id":"m103","text":"أميطوا عن النصيحة قبح العلانية، وزينوها بالستر.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص9"},{"id":"m104","text":"اتق الأنس بالسلطان، إن رفع عنك الاحتشام، فزده من الإعظام.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص9"},{"id":"m105","text":"كلما زادك السلطان بسطا فزده هيبة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص9"},{"id":"m106","text":"من شغلته حلاوة الدنيا فاجأته مرارة الآخرة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص9"},{"id":"m107","text":"من صبر على مرارة الدنيا نال حلاوة الآخرة.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص9"},{"id":"m108","text":"لن تدرك ما تحب إلا بالصبر على ما تكره.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص9"},{"id":"m109","text":"لن تنال حلاوة الشفاء إلا بتجرع مرارة الدواء.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص9"},{"id":"m110","text":"ذكر الله والاستعانة به عند القيام وعند القعود هون علي ضعف الشيخوخة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص9"},{"id":"m111","text":"الشيخ أقوى من الشاب، لأن الشاب ينهض بحوله، والشيخ ينهض بحول الله.","kind":"hikma","topic":"الإيمان والعبادة","note":"في المصدر «بحول» بلا هاء","source":"شذرات المطوع، ص9"},{"id":"m112","text":"الضعيف أقوى من القوي، لأن الضعيف يعتمد على الله، والقوي يعتمد على قوته.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص9"},{"id":"m113","text":"ثمن الحكمة حسن الاستماع.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص9"},{"id":"m114","text":"لا تصغر أمر من حاربت أو عاديت، فإنك إذا ظفرت لم تحمد، وإذا عجزت لم تعذر.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص9"},{"id":"m115","text":"قال كريم : لأن أخطئ باذلا أحب إلي من أن أصيب باخلا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص9"},{"id":"m116","text":"احذروا دمعة اليتيم، ودعوة المظلوم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص9"},{"id":"m117","text":"لو كان للذنوب رائحة لما طاب ريح أحد، ولما جلس أحد إلى أحد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص9"},{"id":"m118","text":"من طلب حاجة إلى غير صديقه فقد شانه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص9"},{"id":"m119","text":"طرحنا الحشمة فيما بيننا وبين حفظتنا طرح من لا يؤمن أنهم معه يعلمون ما يقول ويفعل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص9"},{"id":"m120","text":"من عير أخاه بذنب قد تاب منه ابتلاه الله به.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص9"},{"id":"m121","text":"احذر صولة الانهماك، في بغضك وهواك، فإنها تؤدي إلى الهلاك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص9"},{"id":"m122","text":"رب مكروه أنفع من محبوب.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص10"},{"id":"m123","text":"اللهم ارزقنا من الخير أكثر مما نرجو، واصرف عنا من الشر أكثر مما نخاف.","kind":"hikma","topic":"الإيمان والعبادة","note":"دعاء","source":"شذرات المطوع، ص10"},{"id":"m124","text":"الأسى على الفائت تضييع وقت ثان.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص10"},{"id":"m125","text":"لا تسبوا الغوغاء، فإنهم يطفئون الحريق، ويخرجون الغريق، ويسدون البثوق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص10"},{"id":"m126","text":"لن تنال ما تهوى إلا بترك ما تشتهي.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص10"},{"id":"m127","text":"كن حلو الصبر عند مر النازلة.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص10"},{"id":"m128","text":"عذر جميل خير من مطل طويل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص10"},{"id":"m129","text":"أمارات الوجه : الصفرة للفرق، والحمرة للخجل، والإشراق للسرور، والكمد للحزن، والسكون للبراءة، والاضطراب للريبة، وجحوظ العين للإنكار، وغورها للقبول، وترددها في الجانبين للمكر.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص10"},{"id":"m130","text":"مثل الذي يوصي مثل الذي يهدي إذا شبع.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص10"},{"id":"m131","text":"حسن الخلق نصف الدين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص10"},{"id":"m132","text":"من أرجأ غداءه خسر عشاءه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص10"},{"id":"m133","text":"من بكر بغدائه استلذ بعشائه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص10"},{"id":"m134","text":"إذا كان المكروه ممن فوقك كان حزنا.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص10"},{"id":"m135","text":"وإذا كان المكروه ممن دونك كان غضبا.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص10"},{"id":"m136","text":"الثناء بعد البلاء، والاختيار بعد الاختبار، والشهادة بالإحسان بعد الامتحان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص11"},{"id":"m137","text":"إذا زللت فارجع، وإذا ندمت فأقلع، وإذا أسأت فاندم، وإذا منيت فاكتم، وإذا قريت فأفضل، وإذا منعت فأجمل.","kind":"hikma","topic":"الأخلاق والآداب","note":"«منيت» كما في المصدر، ولعلها «مننت»","source":"شذرات المطوع، ص11"},{"id":"m138","text":"اللهم إن كنا عصيناك فقد تركنا من معاصيك أبغضها إليك، وهو الإشراك بك، وإن كنا قصرنا في طاعتك، فقد تمسكنا بأحبها إليك توحيدك والإيمان برسولك.","kind":"hikma","topic":"الإيمان والعبادة","note":"دعاء","source":"شذرات المطوع، ص11"},{"id":"m139","text":"هدية الأحياء إلى الأموات الدعاء والاستغفار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص11"},{"id":"m140","text":"الموت تحفة المؤمن.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص11"},{"id":"m141","text":"الكريم يرى حق اللفظة، وحرمة اللحظة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص11"},{"id":"m142","text":"لا تعص الله اليوم لخوف الغد، ولا العام لخوف القابل، واستعن بتقوى الله تعالى.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص11"},{"id":"m143","text":"نعم الصديق من يغفر الزلل، ويسد الخلل، ويقبل العلل.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص11"},{"id":"m144","text":"آفة الحزم ترك الاستعداد، وآفة الرأي سوء الاستبداد.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص11"},{"id":"m145","text":"لذة العفو أطيب من لذة التشفي.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص11"},{"id":"m146","text":"عاقبة العفو محمودة، وعاقبة التشفي مذمومة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص11"},{"id":"m147","text":"الحلم قرين العقل، والسؤال مفتاح التثبت، وفي المشورة وضوح الرأي.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص11"},{"id":"m148","text":"أخطأ من ظن أن ابن آدم لا يخطئ.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص11"},{"id":"m149","text":"من قال : لا أعلم، فقد علم أنه لا يعلم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص11"},{"id":"m150","text":"أوثق ما توصلت إليه من العلم وأصدقه، علمي بأني لا أعلم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص11"},{"id":"m151","text":"من الأجدى على العليل أن يداوى بعشبة أرضه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص12"},{"id":"m152","text":"لو قنع الناس بأرزاقهم كقناعتهم بأوطانهم، ما اشتكى عبد رزقه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص12"},{"id":"m153","text":"من لم يؤدب في صغره لم يفلح في كبره.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص12"},{"id":"m154","text":"المساجد سوق الآخرة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص12"},{"id":"m155","text":"الكريم يذكر إذا وعد، وينسى إذا أوعد.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص12"},{"id":"m156","text":"الهدية السحر الحلال.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص12"},{"id":"m157","text":"التعاون على البر وسيلة لاتفاق الآراء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص12"},{"id":"m158","text":"اتفاق الآراء وسيلة لتحقيق المراد.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص12"},{"id":"m159","text":"خير الناس للناس، أنفع الناس للناس.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص12"},{"id":"m160","text":"شر الناس للناس، أضر الناس للناس.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص12"},{"id":"m161","text":"من عجز عن تقويم نفسه، فهو عن تقويم غيره أعجز.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص12"},{"id":"m162","text":"عدم التصديق بقول غيرك إخبار عن نفسك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص12"},{"id":"m163","text":"التكذيب بقول غيرك حكم على غيرك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص12"},{"id":"m164","text":"التصديق بقول غيرك لا يلزمك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص12"},{"id":"m165","text":"التكذيب بقول غيرك من غير بينة ظلم.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص12"},{"id":"m166","text":"التصديق بقول غيرك من غير بينة غفلة وسذاجة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص12"},{"id":"m167","text":"لا تملي على حافظيك شرا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص12"},{"id":"m168","text":"لا تسقط الكلفة بينك وبين حافظيك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص12"},{"id":"m169","text":"من ذهب ماله هان على أهله.","kind":"hikma","topic":"المال والاقتصاد","note":"في المصدر «مال» بلا هاء","source":"شذرات المطوع، ص12"},{"id":"m170","text":"من استغنى كرم على أهله.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص12"},{"id":"m171","text":"سوط الفقر موجع.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص12"},{"id":"m172","text":"من ابتلي بالفقر، ولم يتزين بالعفاف، وتنكب طريق الحلال، فقد جمع على نفسه فقرين : فقر الدنيا وفقر الآخرة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص12"},{"id":"m173","text":"كثرة مال المتوفى شطر التعزية.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص13"},{"id":"m174","text":"حذق المرء وذكاؤه محسوب عليه من رزقه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص13"},{"id":"m175","text":"من فوائد المال : يقرب الأصدقاء ويغيظ الأعداء، ويجلب الرخاء، ويدفع البلاء، ويدني الإخوان، ويطرد الأحزان، ويحقق رجاء المؤمل، ويصلح حال القاصد، ويقضي به الدين، ويوصل به الرحم، ويسترضي به الكاشح، ويصان به الوجه، ويعين على المروءة، ومكارم الأخلاق، وتنفس به الكربة، ويغاث به اللهفان، وييسر به على المعسر، وبه تكسب المحامد، وتضاعف الحسنات، وتدرك الدرجات، وفيه مهر الكريمة، ورقوء الدم، وهو مادة السخاء، وعمود الجود، فالمال فيه خير الدنيا والآخرة، لمن وفقه الله في جمعه وإنفاقه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص13"},{"id":"m176","text":"سافروا تغنموا.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص13"},{"id":"m177","text":"لو يعلم المسافر ما له عند الله من الرحمة لما أحب أن يقطع سفره.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص13"},{"id":"m178","text":"الحركة ولود، والسكون عاقر.","kind":"mathal","topic":"النجاح والإبداع","source":"شذرات المطوع، ص13"},{"id":"m179","text":"ليس الناس بشيء من أقسامهم أقنع منهم بأوطانهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص13"},{"id":"m180","text":"من أدناه الأمير من نفسه فقد جعله شافعا عنده، وذريعة لقضاء حوائج الناس لديه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص13"},{"id":"m181","text":"إذا منعت فاعذر وقل لم أوافق قدرا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص13"},{"id":"m182","text":"إذا سألت الأمير أو الكريم فعاوده فإن الله يقلب القلوب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص13"},{"id":"m183","text":"إذا ردك الكريم فلا تيأس فإن طباع الجود أولى به.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص13"},{"id":"m184","text":"الأجل آفة الأمل.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص13"},{"id":"m185","text":"زكاة الجاه أن تنصر به مظلوما، أو تنفس به عن مكروب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص15"},{"id":"m186","text":"من المعروف أن تعين بجاهك من لا جاه له.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص15"},{"id":"m187","text":"الخلق عيال الله، فأحبهم إلى الله أنفعهم لعياله.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص15"},{"id":"m188","text":"إذا سألت شريفا فاستعن عليه بشرفه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص15"},{"id":"m189","text":"زكاة الجاه رفد المستعين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص15"},{"id":"m190","text":"الدعاء إحدى الصدقتين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص15"},{"id":"m191","text":"لؤم الاكتساب يمنع من الانتساب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص15"},{"id":"m192","text":"الثناء بأكثر من الاستحقاق ملق، والتقصير عن الاستحقاق عي أو حسد.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص15"},{"id":"m193","text":"لا تعاجل الذنب بالعقوبة، واجعل بينهما للاعتذار طريقا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص15"},{"id":"m194","text":"اللهم إن رجاءنا بعفوك أعظم من ذنوبنا، وجودك بعفوك أعظم من رجائنا، فاغفر بعظيم عفوك عظيم ذنوبنا، فإنه لا يغفر الذنب العظيم إلا الرب العظيم.","kind":"hikma","topic":"الإيمان والعبادة","note":"دعاء","source":"شذرات المطوع، ص15"},{"id":"m195","text":"المصائب مفاتيح الأجر.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص15"},{"id":"m196","text":"المصيبة مع الجزع مصيبتان.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص15"},{"id":"m197","text":"من أتاه المكروه ممن فوقه أثار حزنا، ومن أتاه المكروه ممن دونه هيج غضبا.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص15"},{"id":"m198","text":"إذا استأثر الله بشيء فاله عنه.","kind":"mathal","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص15"},{"id":"m199","text":"المودة قرابة مستجدة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص15"},{"id":"m200","text":"صاحب من ينسى معروفه عندك، ويتذكر حقوقك عليه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص15"},{"id":"m201","text":"تقاربوا في المودة، ولا تتكلوا على القرابة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص15"},{"id":"m202","text":"القرابة توجب المودة ولا توجدها.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص15"},{"id":"m203","text":"الأقلام مطايا الكلام.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص15"},{"id":"m204","text":"الخط للقريب والبعيد، واللفظ للقريب فقط.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص16"},{"id":"m205","text":"الخط للشاهد والغائب، واللفظ للشاهد فقط.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص16"},{"id":"m206","text":"ما تساب اثنان إلا غلب ألأمهما.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص16"},{"id":"m207","text":"ذاكر غائبا تره.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص16"},{"id":"m208","text":"إذا لم تسمع فألمع. ( فأشر )","kind":"mathal","topic":"الكلام والصمت","source":"شذرات المطوع، ص16"},{"id":"m209","text":"من أحسن إلى أحد فبنفسه بدأ، ومن أساء على أحد فبنفسه بدأ.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص16"},{"id":"m210","text":"لقاء الأحبة مسلاة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص16"},{"id":"m211","text":"الأدب رفعة، والرفعة يمن.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص16"},{"id":"m212","text":"الجود رداء العيوب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص16"},{"id":"m213","text":"الأدب حلة زاهية الألوان.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص16"},{"id":"m214","text":"العلم ثوب الوقار.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص16"},{"id":"m215","text":"التقوى رداء الورع.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص16"},{"id":"m216","text":"الصحة ثوب الجمال.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص16"},{"id":"m217","text":"الغنى قميص العز.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص16"},{"id":"m218","text":"أملِ على الناس ما تحب أن يذكروك به بعد حياتك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص16"},{"id":"m219","text":"أملِ على جليسك ما تحب أن يذكرك به بعد غيابك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص16"},{"id":"m220","text":"أملِ على أولادك ما تحب أن يذكروك به بعد رحيلك.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص16"},{"id":"m221","text":"أعني على شكرك بالإحسان إلي.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص16"},{"id":"m222","text":"أعني على الإحسان إليك بشكرك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص16"},{"id":"m223","text":"اقطع لسان الذم عنك بالإحسان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص17"},{"id":"m224","text":"حرك لسانه بالثناء عليك بالإحسان إليه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص17"},{"id":"m225","text":"حب الناس لك في يدك : إن أحسنت إليهم أحبوك، وإن أسأت إليهم أبغضوك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص17"},{"id":"m226","text":"نماء الحب بالإحسان، ونماء البغض بالإساءة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص17"},{"id":"m227","text":"اقتلع البغضاء من قلوب الناس بالإحسان إليهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص17"},{"id":"m228","text":"لا تطلب من الناس أن يحبوك، ولكن أحسن إليهم فيحبوك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص17"},{"id":"m229","text":"لا تطلب من الناس ألا يكرهوك، ولكن أحسن إليهم فيحبوك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص17"},{"id":"m230","text":"تعلم من الكريم أن تكون كريما، وتعلم من البخيل ألا تكون بخيلا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص17"},{"id":"m231","text":"تعلم من الأمين أن تكون أمينا، وتعلم من الخائن ألا تكون خائنا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص17"},{"id":"m232","text":"تعلم من أهل الخير الخير، وتعلم من أهل الشر الخير، بأن لا تكون مثلهم، فإذا فعلت فأنت الرجل الكامل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص17"},{"id":"m233","text":"لا تطلب العلم بالجهل، فلا تقصد العالم في غير وقته، ولا تتخطى إليه الرقاب، ولا تتعنت في السؤال، ولا تقل له قال فلان غير قولك، لا تذم عنده العلماء، ولا تغتب عنده أحدا.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص17"},{"id":"m234","text":"كتاب الرجل أمارة علمه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص17"},{"id":"m235","text":"من قرأ كتابا فقد جالس مؤلفه من غير كلفة واحتشام.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص17"},{"id":"m236","text":"تغاب عما لا يتضح لك من أخيك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص17"},{"id":"m237","text":"من نم لك نم عليك، وأصدقهم أخبثهم.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص17"},{"id":"m238","text":"أردع النمام بقولك : أتحب أن نقبل منك ما قلت فيه، على أن نقبل منه ما يقول فيك ؟","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص17"},{"id":"m239","text":"الغموم التي تعرض للقلوب كفارات للذنوب.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص17"},{"id":"m240","text":"السرور في الدنيا ربح، لأن مبناها على الغموم.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص17"},{"id":"m241","text":"إذا اشتد الغم انقطع الدمع.","kind":"hikma","topic":"الصحة والنفس","note":"سبقها في المصدر رقم «71» وهو رقم الصفحة 17 معكوسا","source":"شذرات المطوع، ص18"},{"id":"m242","text":"الحزن يبلى كما يبلى الثوب، ولو بقي الحزن على أحد لقتله.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص18"},{"id":"m243","text":"المؤمن أكثر هما، لأنه يكابد هم المعاش، وهم المعاد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص18"},{"id":"m244","text":"ثلاثة أشياء ترد القضاء البكاء والاستغفار والدعاء.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص18"},{"id":"m245","text":"ليس الخائف الذي يبكي، إنما الخائف الذي يترك ما يخاف أن يعاقبه الله عليه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص18"},{"id":"m246","text":"إن أحبكم إلينا قبل أن نراكم أحسنكم اسما، فإذا رأيناكم فأحسنكم سمتا، فإذا تكلمتم فأحسنكم منطقا، فإذا عملتم فأحسنكم عملا، وسرائركم بينكم وبين الله تعالى.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص18"},{"id":"m247","text":"الحق الذي لا يقبل من قائله، مدحه نفسه بالحق.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص18"},{"id":"m248","text":"الصدق الذي لا يقبل، ثناء المرء على نفسه بما هو أهله.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص18"},{"id":"m249","text":"عجب الشكر مأمور به، كأن يعظم الإنسان نعم الله عليه، ويحدث بها.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص18"},{"id":"m250","text":"عجب الكبر منهي عنه، كأن يفتخر الإنسان بما حققه وجمعه ويستطيل به.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص18"},{"id":"m251","text":"جهر النبي بعجب الشكر، وأسقط استطالة الكبر، فقال : ( أنا سيد ولد آدم ولا فخر ).","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص18"},{"id":"m252","text":"لله دره، أي علم بين جنبيه، وأي لسان بين فكيه، وأي يقين بين ضلوعه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص18"},{"id":"m253","text":"لو لم يصف الطبيب منافع دوائه للمتعالجين لما قصده طالب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص18"},{"id":"m254","text":"نظر عمر بن العزيز إلى علوي يمشي مشية منكرة، فقال : يا هذا، إن الذي شرفت به لم تكن هذه مشيته.","kind":"hikma","topic":"الأخلاق والآداب","note":"كذا في المصدر، ولعله: عمر بن عبد العزيز","source":"شذرات المطوع، ص18"},{"id":"m255","text":"من تكبر على من دونه، ذل لمن فوقه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص18"},{"id":"m256","text":"من تواضع لمن دونه، لم يذل لمن فوقه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص19"},{"id":"m257","text":"لو أن العالم كلما قال أصاب، وكلما عمل أحسن، أوشك أن يعجب بنفسه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص19"},{"id":"m258","text":"ثمرة المشاورة الصواب، وثمرة الهدايا المحبة، وثمرة الكبر المقت.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص19"},{"id":"m259","text":"لا تلعن إبليس في العلانية، وتصادقه في السر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص19"},{"id":"m260","text":"رب بعيد أقرب من قريب في نفعه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص19"},{"id":"m261","text":"رب قريب أبعد من بعيد في عدم نفعه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص19"},{"id":"m262","text":"إذا غلب العقل الهوى صرف المساوئ إلى محاسن، فجعل البلادة حلما، والحدة ذكاء، والمكر فطنة، والهذر بلاغة، والعي صمتا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص19"},{"id":"m263","text":"شاور من جرب، فإنه يمنحك صواب رأيه الذي بلغه بالمعاناة وأنت تأخذه وأنت وادع.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص19"},{"id":"m264","text":"حاجة العقل إلى التجربة حاجة العلم إلى المذاكرة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص19"},{"id":"m265","text":"استخراج الرأي الجليل كاستخراج اللؤلؤ الثمين، بعد الجهد والمعاناة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص19"},{"id":"m266","text":"يقول الغزال للكلب لن تلحقني، قال : لم ؟ قال : لأني أعدو لنفسي، وأنت تعدو لصاحبك.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص19"},{"id":"m267","text":"من حرص على الرياسة لم يسلم من الحسد والبغي والطغيان.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص19"},{"id":"m268","text":"لا تحدث بالحكمة إلا لمن ألقى إليك السمع وهو شهيد.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص19"},{"id":"m269","text":"ثمن الحكمة طلبها، فمن طلبها فقد دفع ثمنها، فاستحق أن يسمعها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص20"},{"id":"m270","text":"أجرأ الناس على الفتيا أقلهم علما باختلاف العلماء.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m271","text":"اختلاف العلماء يردع عن التسارع في الفتيا.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m272","text":"من أراد أن يأكل الخبز بالعلم لا يوثق بعلمه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m273","text":"مجالسة العلماء تجلي القلوب.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m274","text":"من أراد أن يصقل قلبه ويذهب بصدأه، فعليه بمجالسة العلماء.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m275","text":"من اتخذ علم الدين تجارة فلا أربح الله تجارته.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m276","text":"أدنى العلم ما كان على اللسان، وأرفعه ما كان في الجنان.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m277","text":"علم اللسان لا يجاوز البيان، وعلم الجنان يظهر على الجوارح والأركان.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m278","text":"بالعلم يشرف الوضيع، ويعز الذليل، ويناطح الصغير الكبير، ويمكن الضعيف من مخاطبة القوي بمثل قول « أحطت بما لم تحط به ».","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m279","text":"أشتهي أن أرى عالما زاهدا أو زاهدا عالما.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m280","text":"ما أكثر الشجر، وليس كلها بمثمر، وما أكثر الثمار، وليس كلها بمطعوم، وما أكثر المطعوم، وليس كله بمشتهى، وما أكثر المشتهى، وليس كله بمقدور عليه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص20"},{"id":"m281","text":"ما أقل العلماء، وليس كلهم بعاملين، وما أقل العاملين، وليس كلهم بزاهدين، وما أقل الزاهدين، وليس كلهم بمخلصين.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m282","text":"خذ من كل علم بطرف، فإن من جهل شيئا عاداه، ومن عادى علما فقد حقر نفسه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m283","text":"إن الله تعالى ذم الذين يطلبون العلم بالجهل، فقال : « إن الذين ينادونك من وراء الحجرات أكثرهم لا يعقلون ».","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص21"},{"id":"m284","text":"لا تصحبن عاقا، فإنه لن يصلك وقد عق والديه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص21"},{"id":"m285","text":"لا تتوخى الإحسان من قاطع رحم، فإنه لن يحسن إليك وقد قطع رحمه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص21"},{"id":"m286","text":"استكثروا من العيال، فإنكم لا تدرون بمن ترزقون.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص21"},{"id":"m287","text":"صاحب العيال أعظم أجرا، والفار من عياله كالعبد الآبق.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص21"},{"id":"m288","text":"النعمة تقول : كفرت، والأمانة تقول : أكلت، والرحم تقول : قطعت.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص21"},{"id":"m289","text":"أمران يشوبها الكذب : المواعيد والاعتذار.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص21"},{"id":"m290","text":"شر الناس المثلث، الذي يسعى بصاحبه إلى سلطانه، فيهلك نفسه وصاحبه وسلطانه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص21"},{"id":"m291","text":"صاحب الدرهمين أشد حسابا يوم القيامة من صاحب الدرهم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص21"},{"id":"m292","text":"من ولد في الفقر أبطره الغنى.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص21"},{"id":"m293","text":"من ولد في الغنى لم تزده النعمة إلا تواضعا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص21"},{"id":"m294","text":"الفقر والذكر شعار الصالحين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص21"},{"id":"m295","text":"الغنى والغفلة شعار المنافقين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص21"},{"id":"m296","text":"أشقى الأشقياء من جمع عليه فقر الدنيا وعذاب الآخرة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص21"},{"id":"m297","text":"بئس المذلان : الفقر والجهل.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص21"},{"id":"m298","text":"نعم المعزان : الغنى والعلم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص21"},{"id":"m299","text":"من حفظ ماله فقد حفظ الأكرمين : دينه وعرضه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص21"},{"id":"m300","text":"المال عز للمؤمن، يصون به وجهه عن ذل السؤال.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص21"},{"id":"m301","text":"المال سلاح المؤمن يقي به دينه وشرفه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص22"},{"id":"m302","text":"من كان له مال فليصلحه وينميه ليكون به اليد العليا، ولا يكون اليد السفلى.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص22"},{"id":"m303","text":"قال محتضر : ما أكره أن يذهب بي إلى من لم أر الخير إلا منه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص22"},{"id":"m304","text":"إن الموت قد أفسد على أهل النعيم نعيمهم، فالتمسوا نعيما لا موت فيه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص22"},{"id":"m305","text":"اشتر نفسك من الله تعالى ببعض ما وهبك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص22"},{"id":"m306","text":"أشقى الولاة من شقيت به رعيته.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص22"},{"id":"m307","text":"جور السلطان خير من ضعفه، لأن جوره يخص، وأما ضعفه فيتواثب الناس فيتفشى الشر والظلم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص22"},{"id":"m308","text":"من شارك السلطان الظالم في عز الدنيا، شاركه في ذل الآخرة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص22"},{"id":"m309","text":"من تأدب وجد بغيته.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص22"},{"id":"m310","text":"ذكر عمر أزرى بالولاة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص22"},{"id":"m311","text":"ذاكر الله في الغافلين، كالشجرة الخضراء في وسط الأشجار اليابسة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص22"},{"id":"m312","text":"ذاكر الله في الغافلين كالمقاتل المقبل بين المدبرين الفارين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص22"},{"id":"m313","text":"لا تحقرن أحدا من المسلمين، فإن صغيرهم عند الله كبير.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص22"},{"id":"m314","text":"إن لم تجد حكيما ترسله فكن رسول نفسك.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص22"},{"id":"m315","text":"ربما كان التقالي من كثرة التلاقي.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص22"},{"id":"m316","text":"الإكثار ممل، والإقلال مخل.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص22"},{"id":"m317","text":"بالبشر والبر تقبل عليك قلوب الرجال.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص22"},{"id":"m318","text":"أجلس علي الحسن والحسين على سريره، وأجلس محمد بن الحنفية في الحضيض وقال : يا بني أنت ابني، وهذان ابنا رسول الله.","kind":"hikma","topic":"التربية والأسرة","note":"«أجلس علي» أي علي بن أبي طالب","source":"شذرات المطوع، ص22"},{"id":"m319","text":"أطعمنا من أحاديثك الطريفة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص22"},{"id":"m320","text":"أطعم آذاننا من أحاديثك الشيقة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص22"},{"id":"m321","text":"ابن الثمانين حبيس الله.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص22"},{"id":"m322","text":"من بلغ الثمانين فهو أسير الله في أرضه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص23"},{"id":"m323","text":"قيل لحكيم مالك تمسك العصا، ولست بمريض ولا كبير ؟ قال : لأرى أني مسافر.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص23"},{"id":"m324","text":"خير شبابكم من تشبه بكهولكم، وليس خير كهولكم من تشبه بشبابكم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص23"},{"id":"m325","text":"صحبة الأخيار تورث حسن الظن.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص23"},{"id":"m326","text":"صحبة الأشرار تورث سوء الظن.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص23"},{"id":"m327","text":"نية المؤمن خير من عمله، وعمله لا يبلغ نيته.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص23"},{"id":"m328","text":"نية المنافق شر من عمله، وعمله لا يبلغ نيته.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص23"},{"id":"m329","text":"شح البخيل على قدر ماله، فكلما زاد ماله زاد شحه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص23"},{"id":"m330","text":"كرم الجواد على قدر ماله، فكلما زاد ماله زاد كرمه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص23"},{"id":"m331","text":"أتوسل إليك بك، واستشفع بك عندك، ليجتمع شكري لك، ولا يتفرق على غيرك.","kind":"hikma","topic":"الإيمان والعبادة","note":"دعاء","source":"شذرات المطوع، ص23"},{"id":"m332","text":"صلاح ذات البين تعمر الديار.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص23"},{"id":"m333","text":"فساد ذات البين خراب الديار.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص23"},{"id":"m334","text":"الصبر على طاعة الله أهون من الصبر على عذابه.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص23"},{"id":"m335","text":"اعمل وكل، فإن الله يحب من يعمل ويأكل، ولا يحب من يأكل ولا يعمل.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص23"},{"id":"m336","text":"رأس مال الدلال الكذب، وأول من دل إبليس حيث قال : « هل أدلك على شجرة الخلد وملك لا يبلى ».","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص24"},{"id":"m337","text":"الفرق بين النكاح والسفاح : الوليمة، والغناء، والدف، والإعلان.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص24"},{"id":"m338","text":"الكريم يطعم فمك، والحكيم يطعم أذنيك.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص24"},{"id":"m339","text":"الكريم يملأ بطنك، والحكيم يملأ عقلك.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص24"},{"id":"m340","text":"إذا جالست حكيما فأطعم أذنيك من أطايب كلامه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص24"},{"id":"m341","text":"إذا خرج الكلام من جلجلان القلب، أفرغ في قمع الأذن ( حبة القلب )","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص24"},{"id":"m342","text":"إذا خرج الكلام من حماطة القلب، بلغ صماخ الأذن. ( حبة القلب )","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص24"},{"id":"m343","text":"قال عمر : إنا إذا خلونا قلنا ما يقول الناس في بيوتهم.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص24"},{"id":"m344","text":"الدعاء للسائل إحدى الصدقتين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص24"},{"id":"m345","text":"صاحت عصافير بطنه، ونقت ضفادعه. ( جاع )","kind":"mathal","topic":"الصحة والنفس","source":"شذرات المطوع، ص24"},{"id":"m346","text":"فلان شدق وعلق وحدق : لقمة في شدقه، ولقمة في يده، ولقمة في ناظره.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص24"},{"id":"m347","text":"ليس شيء أحب إلي من الضيف، رزقه على الله، وأجره لي.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص24"},{"id":"m348","text":"كل شيء ينقص في ابن آدم، إلا الحرص والأمل يزيدان.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص24"},{"id":"m349","text":"لو تفكر ابن آدم في الأجل، لقصر في الأمل.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص24"},{"id":"m350","text":"ابن آدم قصير الأجل، طويل الأمل، ضعيف العمل.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص24"},{"id":"m351","text":"لا يكون العمران حيث يجور السلطان.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص24"},{"id":"m352","text":"عدل السلطان عمار للأوطان.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص24"},{"id":"m353","text":"إذا أرهق الملك رعيته بجباية الأموال، كان كمن يعمر سطح بيته، بما يقتلع من قواعد بنائه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص24"},{"id":"m354","text":"من طال عدوانه زال سلطانه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص24"},{"id":"m355","text":"احذروا دمعة اليتيم، ودعوة المظلوم، ونهر السائل، وإذلال الغريب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص24"},{"id":"m356","text":"أصبحا يتكاشحان ولا يتناصحان، ويتكاشران ولا يتعاشران.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص24"},{"id":"m357","text":"إياك أن تعادي من إذا شاء خلع ثيابه، ودخل مع الملك في لحافه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص24"},{"id":"m358","text":"إلى متى هذا الغرور، ويحكم، أما تمشون بين القبور.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص24"},{"id":"m359","text":"إذا تفقه الشريف تواضع، فأفشى السلام، وصافح العوام، وجالس المساكين، وعاد المرضى، وشيع الجنائز.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص24"},{"id":"m360","text":"إذا تفقه الوضيع تكبر، فأمر بالمعروف، ونهى عن المنكر، ووعظ الشريف، وأخذ في الحسبة، وأم أهل محلته، واحتد على من رد عليه، ورأى أن له فضيلة على كل أحدٍ.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص24"},{"id":"m361","text":"لا تقل ما في خير، فإن فيك التوحيد والإخلاص، ولكن قل لقد خشيت أن يهلكني ما في من الشر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص24"},{"id":"m362","text":"ما رأيت عاقلا يلم به أمر، إلا كان معوله على لحيته.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص24"},{"id":"m363","text":"يقال للجميل : أنت يوسف زمانك.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص24"},{"id":"m364","text":"من رأى النبي فقد اقتبس من وجهه نورا.","kind":"hikma","topic":"الإيمان والعبادة","note":"لعل رمز الصلاة على النبي سقط في الاستخراج","source":"شذرات المطوع، ص24"},{"id":"m365","text":"أقبح من عجوز يوم طلاقها.","kind":"mathal","topic":"الحياة الزوجية","source":"شذرات المطوع، ص24"},{"id":"m366","text":"صحبة فاجر حسن الخلق، أدوم وأحب من صحبة عابد سيء الخلق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص24"},{"id":"m367","text":"الفاسق إذا حسن خلقه خف على الناس وأحبوه، والعابد إذا ساء خلقه ثقل على الناس ومقتوه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص24"},{"id":"m368","text":"إذا اقترن حسن الخلق بالفاسق قدم، وإذا اقترن سوء الخلق بالعابد أخر.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص24"},{"id":"m369","text":"المتقلب كثير الألوان يقال له : أبو رياح، وقوس السماء.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص24"},{"id":"m370","text":"يباعدك من غضب الله ألا تغضب.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص24"},{"id":"m371","text":"أعدى أعدائك الغضب، لأنك تفعل في غضبك، ما تندم عليه في رضاك.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص24"},{"id":"m372","text":"من أطاع الغضب أضاع الأدب.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص24"},{"id":"m373","text":"الحلم أحمد عاقبة من الانتقام.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص24"},{"id":"m374","text":"لست عن نفسي راضيا فكيف أعيب الناس.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص24"},{"id":"m375","text":"من ترك الغيبة أحرز حسناته.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص24"},{"id":"m376","text":"لا تسلط الغيبة على حسناتك، فإن لم تفن تنقص.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص24"},{"id":"m377","text":"لا تشغل نفسك بذكر الفاسق المجاهر، ولا تعود لسانك الغيبة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص24"},{"id":"m378","text":"استعذ بالله من الشيطان الرجيم، ولا تلعنه حتى لا تعود لسانك على اللعنة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص24"},{"id":"m379","text":"إذا كان عاملان من قبيلة واحدة، فلا تفاضل بينهما، حتى لا توغر صدورهما.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص24"},{"id":"m380","text":"إذا أردت أن تظلم أو تغتاب، فاذكر القطن إذا وضعوه على عينيك وفي فمك وأنفك وأذنيك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص24"},{"id":"m381","text":"زين إبليس لحوم الناس للناس، فكانت أطيب من الدجاج والدراج.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص24"},{"id":"m382","text":"سامع الغيبة أحد المغتابين.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص24"},{"id":"m383","text":"أهدى الحسن البصري إلى مغتابه طبقا من رطب، وقال : أهديت إلي حسناتك، فأردت أن أكافئك.","kind":"hikma","topic":"الأخلاق والآداب","note":"في المستخرج «على مغتابه» والأرجح «إلى»","source":"شذرات المطوع، ص24"},{"id":"m384","text":"ترك الذنوب استغفار، ولا يغني عن الاستغفار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص24"},{"id":"m385","text":"أمارة المدينة وجود الحائك والمعلم.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص24"},{"id":"m386","text":"ليس حسن الجوار كف الأذى، ولكن حسن الجوار بذل الندى، والصبر على الأذى.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص26"},{"id":"m387","text":"كان أبو بكر وعمر وزيري رسول الله ﷺ، وحليتيه، يتزين بهما في يوم عيد أو قدوم وفد، أبو بكر عن يمينه، وعمر عن يساره.","kind":"hikma","topic":"الإيمان والعبادة","note":"رمز الصلاة على النبي ساقط في المستخرج","source":"شذرات المطوع، ص26"},{"id":"m388","text":"منزلة أبي بكر وعمر رضي الله عنهما من الرسول في حياته، كمنزلتهما بعد الحياة وهما ضجيعاه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m389","text":"أبو بكر رضي الله عنه ثاني اثنين في الإسلام، وفي الغار، وفي المشورة يوم بدر، وفي القبر، والخلافة، والجنة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m390","text":"المؤمن مألفة، ولا خير فيمن لا يألف ولا يؤلف.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص26"},{"id":"m391","text":"الحرفة مع العفة، خير من الغنى مع الفجور.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص26"},{"id":"m392","text":"حركة الإقبال بطيئة، وحركة الإدبار سريعة، لأن المقبل كالصاعد من مرقاة إلى مرقاة، والمدبر كالمقذوف من علو إلى أسفل.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص26"},{"id":"m393","text":"عند تقلب الأحوال تعرف معادن الرجال.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص26"},{"id":"m394","text":"إذا ذكرنا الموتى حييت قلوبنا، وإذا ذكرنا الأحياء ماتت قلوبنا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m395","text":"إن الكريم إذا خادعته في مال انخدع.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص26"},{"id":"m396","text":"إذا عصاني من يعرفني، سلطت عليه من لا يعرفني.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m397","text":"إن الله أفرح بتوبة عبده من المضل الواجد، والظمآن الوارد، والعقيم الوالد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m398","text":"الإمرة تذهب الحفيظة، وحقد السلطان عجز.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص26"},{"id":"m399","text":"« فإنه كان للتوابين غفورا » أي : يذنب ثم يتوب ثم يذنب ثم يتوب.","kind":"hikma","topic":"الإيمان والعبادة","note":"نص الآية «للأوابين»؛ أبقيت ما في الأصل","source":"شذرات المطوع، ص26"},{"id":"m400","text":"إياكم ومحقرات الذنوب، فإن محقرات الأعواد تنضج الطعام.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m401","text":"البر زيادة في العمر « وأما ما ينفع الناس فيمكث في الأرض » .","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m402","text":"سبحان من حلمه أوسع من جهل عباده، وعفوه أعظم من ذنوبهم، وجوده أوسع من حوائجهم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m403","text":"سبحان من يدعو المدبرين عنه، فكيف بالمقبلين عليه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m404","text":"قنوطكم أعظم من ذنوبكم، ويأسكم أعظم من جرمكم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m405","text":"اتقوا الله وكونوا من حيث شئتم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m406","text":"لو أن العبد أحسن الإحسان كله ثم أساء إلى دجاجة عنده لم يكن من المحسنين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص26"},{"id":"m407","text":"أعبد الناس رجل اجترح الذنوب، فكلما ذكر ذنبه احتقر عمله.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m408","text":"إذا أقدرك الله على خصمك، فقد صنع لك ما أحببت، فاصنع له ما أحب : العفو.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص26"},{"id":"m409","text":"من علم أنه مسيء فقد أحسن، ومن ظن أنه محسن فقد أساء.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص26"},{"id":"m410","text":"لا تأمن الرجال على النساء، ولا تأمن النساء على الرجال.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص26"},{"id":"m411","text":"لا توجد فتنة أشد على الرجال من النساء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص26"},{"id":"m412","text":"النمائم تنبت السخائم.","kind":"mathal","topic":"الكلام والصمت","source":"شذرات المطوع، ص26"},{"id":"m413","text":"أمارة وفاء الرجل حنينه إلى أوطانه، وبكاؤه على ما مضى من زمانه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص26"},{"id":"m414","text":"تجارها فجارها إلا من أتى بشاهدي عدل : الصدق والأمانة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص26"},{"id":"m415","text":"لا تعاتب صديقك إن أفشى سرك، لأنك كنت أحق بصيانته.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص26"},{"id":"m416","text":"القلب صندوق الأسرار، واللسان مفتاحه.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص26"},{"id":"m417","text":"البراطيل تنصر الأباطيل. ( الرشوة )","kind":"mathal","topic":"المال والاقتصاد","source":"شذرات المطوع، ص26"},{"id":"m418","text":"من صانع بالمال لم يحتشم من طلب الحاجة. ( المصانعة : الرشوة )","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص26"},{"id":"m419","text":"صب في قنديله زيتا. ( رشاه، والمصانعة : قندلة )","kind":"mathal","topic":"المال والاقتصاد","note":"ترتيب الأقواس مضطرب في المستخرج","source":"شذرات المطوع، ص26"},{"id":"m420","text":"لا يأخذ أحد من أحد إلا ذل له، وأنا أكره لنفسي أن أذل لغير الله.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص26"},{"id":"m421","text":"الطمع فقر حاضر، واليأس غنى عاجل.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص28"},{"id":"m422","text":"من يئس من شيء استغنى عنه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص28"},{"id":"m423","text":"قيل للنعامة احملي، قالت : أنا طائر، فقيل لها طيري، قالت : أنا بعير، ( التعلق بالعلل )","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص28"},{"id":"m424","text":"من كرم الله تعالى أنه يأخذ ليعطي، ويبتلي ليجزي.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص28"},{"id":"m425","text":"الحية سمها في أولها، والعقرب سمها في آخرها، والدنيا سمها في أولها وآخرها.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص28"},{"id":"m426","text":"الدنيا مطية المؤمن، يبلغ بها بالخير إلى الخير، ومطية المنافق يبلغ بها بالشر إلى الشر.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص28"},{"id":"m427","text":"الليل والنهار يعملان فيك ما لا ترجو عقباه، فاعمل فيهما ما ترجو عقباه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص28"},{"id":"m428","text":"يا ابن آدم إذا بلغت الأربعين فالليل والنهار يعملان فيك ما يسوء، فاعمل فيهما ما يحسن.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص28"},{"id":"m429","text":"عمر الإنسان ما بين الذكريات والأمنيات.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص28"},{"id":"m430","text":"الدنيا خمر الشيطان للإنسان، فمتى يفيق ؟","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص28"},{"id":"m431","text":"مهر الآخرة طلاق الدنيا، ومهر الدنيا طلاق الآخرة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص28"},{"id":"m432","text":"لا تترك الدنيا فتكن كلا على الناس، ولا تأخذها أخذا يضر بآخرتك.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص28"},{"id":"m433","text":"الشمس قطيفة المساكين، وتكنى بأم شملة.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص28"},{"id":"m434","text":"توقوا البرد في أوله، وتلقوه في آخره.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص28"},{"id":"m435","text":"البرد يفعل في الأبدان ما يفعله في الأغصان.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص28"},{"id":"m436","text":"البرد أوله يحرق، وآخره يورق.","kind":"hikma","topic":"الصحة والنفس","note":"في المستخرج «الربد أول حيرق» والأرجح «أوله»","source":"شذرات المطوع، ص28"},{"id":"m437","text":"الشتاء ذكر، والصيف أنثى.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص28"},{"id":"m438","text":"قال لمؤدب ولده : علمه العوم، وقلة النوم.","kind":"hikma","topic":"التربية والأسرة","note":"ينتهي في الأصل بفاصلة","source":"شذرات المطوع، ص28"},{"id":"m439","text":"علمه العوم قبل الكتابة، لأنه يجد من يكتب له، ولا يجد من يعوم عنه.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص28"},{"id":"m440","text":"إذا دخلت المساجد رأيت الراكع والساجد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص28"},{"id":"m441","text":"إذا دخلت السوق فاستعذ من الفسوق.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص28"},{"id":"m442","text":"أمارة القرية صياح الديكة ونباح الكلاب.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص28"},{"id":"m443","text":"إذا عدل السلطان في رعيته، سهل عليهم الطاعة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص28"},{"id":"m444","text":"إذا جار السلطان في الرعية، فتح لهم باب المعصية.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص28"},{"id":"m445","text":"العدل ميزان الحق، والجور ميزان الباطل.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص28"},{"id":"m446","text":"إذا زهد الملك في العدل زهدت الرعية في الطاعة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص28"},{"id":"m447","text":"إذا عقلك عقلك عما يشين عقلك فأنت عاقل.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص28"},{"id":"m448","text":"هذا كلام يتقاطر عسله.","kind":"mathal","topic":"الكلام والصمت","source":"شذرات المطوع، ص28"},{"id":"m449","text":"رخص الأشياء من كثرتها، وغلاءها من ندرتها، إلا العقل والعلم فغلاءهما من كثرتهما.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص28"},{"id":"m450","text":"كل شيء إذا كثر رخص، إلا العلم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص30"},{"id":"m451","text":"الطفل إذا جاع بكى، وإذا شبع سكت، ويطلب الثدي حين يحتاج إليه ويدعه حين يقضي حاجته منه، فهو يعرف مقادير احتياجاته.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص30"},{"id":"m452","text":"الحلم يستر، والعقل يقطع، والصبر يحمل، والكبر يحط، والتواضع يرفع.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص30"},{"id":"m453","text":"لا رأي لمن استبد برأيه. ( تفرد )","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص30"},{"id":"m454","text":"إذا أشكل الرأي فهو كاللؤلؤة التي تسقط في الرمل، فيجمع ما حول مسقطها ثم يلتمسها صاحبها، وكذلك استخلاص الرأي السديد، واستبعاد الآراء الضعيفة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص30"},{"id":"m455","text":"ثلاثة لا يستغنون عن ثلاثة : العاقل عن الاستشارة، والدابة الفارة عن السوط، والمرأة الحسناء عن الزوج.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص30"},{"id":"m456","text":"الرجال ثلاثة : رجل رجل، ورجل نصف رجل، ورجل لا رجل : فالأول : ذو الرأي والمشورة، والثاني : له رأي ولا يشاور، أو يشاور ولا رأي له، والثالث : لا رأي له ولا يشاور.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص30"},{"id":"m457","text":"عمر مفتاح الأمصار، لأنه الذي فتح أكثرها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص30"},{"id":"m458","text":"مما يشد أركان الملك : التودد إلى الخاصة، والعدل في العامة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص30"},{"id":"m459","text":"ينبغي للوالي أن يتفقد أمر خاصته كل يوم، وأمر عامته كل شهر.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص30"},{"id":"m460","text":"من أخلاق الملوك حب التفرد، وكراهية المشاركة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص30"},{"id":"m461","text":"خير نساءكم الحصان الهلوك.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص30"},{"id":"m462","text":"المغبون لا محمود ولا مأجور.","kind":"mathal","topic":"المال والاقتصاد","source":"شذرات المطوع، ص30"},{"id":"m463","text":"إن الكريم ليجر ذيله على الخدائع في ماله.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص30"},{"id":"m464","text":"إن الجواد لا يكون ماكسا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص30"},{"id":"m465","text":"إذا ذكرنا الموت حييت قلوبنا، وإذا ذكرنا الحياة ماتت قلوبنا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص30"},{"id":"m466","text":"جمال طبعك فاق طابع جمالك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص30"},{"id":"m467","text":"فلان حتف على الأعداء، وربيع للأصدقاء.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص30"},{"id":"m468","text":"صدور الأحرار قبور الأسرار.","kind":"mathal","topic":"الكلام والصمت","source":"شذرات المطوع، ص30"},{"id":"m469","text":"أجمل من رخص الأسعار، وهطول الأمطار.","kind":"mathal","topic":"المال والاقتصاد","source":"شذرات المطوع، ص30"},{"id":"m470","text":"رخص الأسعار من هطول الأمطار.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص30"},{"id":"m471","text":"غلاء الأسعار من قلة الأمطار.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص30"},{"id":"m472","text":"لولا الرسوم لضاعت العلوم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص30"},{"id":"m473","text":"المباني مطية المعاني.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص30"},{"id":"m474","text":"المبتدي بالخير خير من المقتدي.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص30"},{"id":"m475","text":"من أجسر أيسر، ومن هاب خاب.","kind":"mathal","topic":"النجاح والإبداع","source":"شذرات المطوع، ص30"},{"id":"m476","text":"العلقة خرقة، والحب عذاب.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص32"},{"id":"m477","text":"الأمثال مصابيح الأقوال.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص32"},{"id":"m478","text":"لا ينصف اللسان في وصف الإساءة والإحسان.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص32"},{"id":"m479","text":"دون النجاح مشقة النطاح.","kind":"mathal","topic":"النجاح والإبداع","source":"شذرات المطوع، ص32"},{"id":"m480","text":"رب نظرة أثمرت صبابة.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص32"},{"id":"m481","text":"القريب من قرب بره، وإن كان بعيدا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص32"},{"id":"m482","text":"البعيد من بعد بره، وإن كان قريبا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص32"},{"id":"m483","text":"كن جميل الصبر عند قبح المصيبة.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص32"},{"id":"m484","text":"قيل للعجلة ما كنيتك ؟ قالت : أم الندامة.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات المطوع، ص32"},{"id":"m485","text":"قيل للتؤدة ما كنيتك ؟ قالت : أم السلامة.","kind":"mathal","topic":"العقل والحكمة","note":"في المستخرج «أم السالم» والأرجح «السلامة»","source":"شذرات المطوع، ص32"},{"id":"m486","text":"إن المحسن معان، والمسيء مهان.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص32"},{"id":"m487","text":"يا أنيس المنفردين، حططنا رحلنا بفنائك، لا نلوذ بالمعذرة، بل نعول على المغفرة.","kind":"hikma","topic":"الإيمان والعبادة","note":"دعاء","source":"شذرات المطوع، ص32"},{"id":"m488","text":"الإفراط في توقي الخطأ خطأ.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص32"},{"id":"m489","text":"الاقتصاد في العمل أدوم للعمل.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص32"},{"id":"m490","text":"الجمال في المرأة أظهر، والجلال في الرجل أظهر.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص32"},{"id":"m491","text":"جلال الجمال في المرأة، يعدل جمال الجلال في الرجل.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص32"},{"id":"m492","text":"أجمل ما يكون الجميل إذا قارن القبيح.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص32"},{"id":"m493","text":"جمال الخط يبرز الحق.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص32"},{"id":"m494","text":"كثرة الحسن في الملامح والأعضاء جمال.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص32"},{"id":"m495","text":"الجمال قيد النظر.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص33"},{"id":"m496","text":"الأم ترى ابنها جميلا لأنها تحبه.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص33"},{"id":"m497","text":"الزوج يحب زوجته لأنه يراها جميلة.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص33"},{"id":"m498","text":"الجمال موهوب، وهو أول السعادة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص33"},{"id":"m499","text":"الجمال مفتاح القلوب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص33"},{"id":"m500","text":"الجمال يخطب المودة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص33"},{"id":"m501","text":"الجمال يثير الغيرة، ويدعو إلى الحسد.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص33"},{"id":"m502","text":"الجمال محط الأنظار، ومطمع الآمال.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص33"},{"id":"m503","text":"الجمال يفتح الأبواب المغلقة، ويستدعي الكلمات المؤنقة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص33"},{"id":"m504","text":"الجمال يشفع لصاحبه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص33"},{"id":"m505","text":"الجمال يدرك من أول وهلة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص33"},{"id":"m506","text":"اجتمع فيه جمال الطبع، وطابع الجمال.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص33"},{"id":"m507","text":"طابع الجمال يسبق جمال الطبع.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص33"},{"id":"m508","text":"كنت أرى فيه طابع الجمال، فلما خالطته رأيت فيه جمال الطبع.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص33"},{"id":"m509","text":"جمال الطبع يزيد في طابع الجمال.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص33"},{"id":"m510","text":"الرجل لا يمكن أن يكتم حب المرأة يوما واحدا، ويمكن أن يكتم بغضها أعواما.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص33"},{"id":"m511","text":"المرأة لا يمكن أن تكتم بغض الرجل يوما واحدا، وتكتم حبه أعواما.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص33"},{"id":"m512","text":"أجلست عبدي فاتكأ.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص33"},{"id":"m513","text":"التسلط على الضعيف دناءة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص33"},{"id":"m514","text":"من كرم الرجل سوء أدب غلمانه.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص36"},{"id":"m515","text":"أضيع من قمر الشتاء.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص36"},{"id":"m516","text":"إذا طلع القمر طاب السفر.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص36"},{"id":"m517","text":"انحط من الثريا إلى الثرى.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص36"},{"id":"m518","text":"المطر بعل الأرض.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص36"},{"id":"m519","text":"الليالي حبالى، ليس يدرى ما تلد.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص36"},{"id":"m520","text":"دع من الثياب المحتقر والمشتهر.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص36"},{"id":"m521","text":"جمال الثياب يزيد من جمال الشباب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص36"},{"id":"m522","text":"بينهما سوق السلاح.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص36"},{"id":"m523","text":"نعم الواقي من الخطر الحاضر أجل غائب.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص36"},{"id":"m524","text":"كفى بتأخير الأجل واقيا.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص36"},{"id":"m525","text":"لا ترفع عصاك عن أهلك. ( كناية عن التأديب بالتخويف ).","kind":"mathal","topic":"التربية والأسرة","source":"شذرات المطوع، ص36"},{"id":"m526","text":"عصا الجبان أطول.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص36"},{"id":"m527","text":"علق عصاك حيث يراها أهلك.","kind":"mathal","topic":"التربية والأسرة","source":"شذرات المطوع، ص36"},{"id":"m528","text":"لا تدخل بين العصا ولحائها.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص36"},{"id":"m529","text":"هو لين العصا. إذا كان رفيقا.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص36"},{"id":"m530","text":"فلان ألقى عصاه. إذا أقام.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص36"},{"id":"m531","text":"طارت عصاهم شققا. أي : تفرقوا.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص36"},{"id":"m532","text":"ليس في عصاه سير. أي : ما به حركة.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص36"},{"id":"m533","text":"قشرت له العصا. أي : كاشفته.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص37"},{"id":"m534","text":"أقرب من عصا الأعرج.","kind":"mathal","topic":"الحياة والزمن","note":"في الأصل «عصاه الاعرج»","source":"شذرات المطوع، ص37"},{"id":"m535","text":"هم عبيد العصا. إذا استذلوا.","kind":"mathal","topic":"السياسة والقيادة","source":"شذرات المطوع، ص37"},{"id":"m536","text":"الدار الضيقة العمى الأصغر.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص37"},{"id":"m537","text":"أبطأ فيض الدلاء أملؤها.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات المطوع، ص37"},{"id":"m538","text":"عفو الله أكثر من ذنوب عباده.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص37"},{"id":"m539","text":"لا تنس الموت، فإنه لا ينساك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص37"},{"id":"m540","text":"العافية ملك خفي.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص37"},{"id":"m541","text":"تاجروا الله بالصدقات تربحوا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص37"},{"id":"m542","text":"ربما أتى البلاء من فرط الحب، فيوسف أحبه أبوه - عليهما السلام - فحسده إخوته، وألقوه في الجب، وأحبته امرأة العزيز فلبث في السجن بضع سنين.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص37"},{"id":"m543","text":"استعيذوا بالله من كيد النساء، وكونوا من ثقاتهن على حذر.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص37"},{"id":"m544","text":"قيل للحسن : أيكذب المؤمن ؟ فقال : أنسيتم إخوة يوسف.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص37"},{"id":"m545","text":"للملوك بدوات.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص37"},{"id":"m546","text":"الملك يبقى على الكفر، ولا يبقى على الظلم.","kind":"hikma","topic":"السياسة والقيادة","note":"في الأصل «يتبىق»","source":"شذرات المطوع، ص37"},{"id":"m547","text":"عفو الملك أبقى للملك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص37"},{"id":"m548","text":"الحمد يشترى، والذم بالمجان.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص37"},{"id":"m549","text":"قصد رجل رجلا ذا جاه وكرم، فقال له : من أنت ؟ فقال : أنا الذي أحسنت إليه، فقال : مرحبا بمن توسل إلينا بنا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص37"},{"id":"m550","text":"لذة العفو خير من لذة العقوبة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص37"},{"id":"m551","text":"صيانة العلم ببذله لأهله.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص37"},{"id":"m552","text":"حفظ العلم بإنفاقه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص37"},{"id":"m553","text":"إذا كثرت الأمطار قلت الأسعار.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص38"},{"id":"m554","text":"إذا قلت الأمطار ارتفعت الأسعار.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص38"},{"id":"m555","text":"تقول النخلة لجارتها أبعدي عني ظلك، لأحمل حملي وتحملي حملك.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص38"},{"id":"m556","text":"أول الربح حفظ رأس المال.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص38"},{"id":"m557","text":"الأسواق موائد الله في أرضه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص38"},{"id":"m558","text":"من اشترى الدون، رجع وهو مغبون.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص38"},{"id":"m559","text":"الكفالة ندامة.","kind":"mathal","topic":"المال والاقتصاد","source":"شذرات المطوع، ص38"},{"id":"m560","text":"لا تشتر كل ما تشتهيه، يكفيك أن تشتري بعض ما تشتهيه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص38"},{"id":"m561","text":"طعام المطاعم مستطاب.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص38"},{"id":"m562","text":"إذا سلمت الأرواح، خفت خسارة الأرباح.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص38"},{"id":"m563","text":"من لم يحترف، لم يعتلف.","kind":"mathal","topic":"المال والاقتصاد","source":"شذرات المطوع، ص38"},{"id":"m564","text":"ليس في البيت إلا البيت.","kind":"mathal","topic":"المال والاقتصاد","source":"شذرات المطوع، ص38"},{"id":"m565","text":"القبح حارس المرأة.","kind":"mathal","topic":"الحياة الزوجية","source":"شذرات المطوع، ص39"},{"id":"m566","text":"خير المناكح الأبكار.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص39"},{"id":"m567","text":"قيل لحكيم : مالك تمسك العصا ؟ ولست بمريض ولا كبير، فقال: حتى لا أنسى أني عابر سبيل.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص39"},{"id":"m568","text":"لا تكثر الوعد، فإنه فيه شائبة رق.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص39"},{"id":"m569","text":"كل كثير عدو الطبيعة. ( الأكل الكثير، والسهر الكثير وحمل الأثقال الكثيرة).","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص39"},{"id":"m570","text":"العاقل يترك بعض ما يحب، ليحرز نفسه عن بعض ما يكره.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص39"},{"id":"m571","text":"إذا اشتهى المريض الطعام فبشره بالصحة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص39"},{"id":"m572","text":"من أكل ما لا يشتهيه، حرم مما يشتهيه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص39"},{"id":"m573","text":"الغم مرض الروح، والألم مرض البدن.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص39"},{"id":"m574","text":"ربما أضر بالشيخ الجارية الحسناء، والطباخ الحاذق.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص39"},{"id":"m575","text":"قبلة الوالدين بر، وقبلة الأولاد عطف، وقبلة الأخ صلة، وقبلة الزوجة عاطفة، وقبلة القادم شوق، وقبلة العالم توقير، وقبلة الملك طاعة، وقبلة الحجر الأسود إتباع، وقبلة المصحف تعظيم، وقبلة آل البيت قربة، وقبلة المكاشح مخادعة، وقبلة الصغير ملاطفة، وقبلة الكبير تقدير، وقبلة الضيف إيناس.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص39"},{"id":"m576","text":"من خدم السوقة فهو خادم من جميع الجهات.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص40"},{"id":"m577","text":"من خدم الملك فهو خادم من جهات، وملك من جهة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص40"},{"id":"m578","text":"السلطان إذا غضب كالبحر إذا هاج، فتوقاه بالابتعاد عنه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص40"},{"id":"m579","text":"ادن من السلطان دنوك من النار، عند الحاجة، ثم ابتعد.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص40"},{"id":"m580","text":"السلطان العادل كالغيث، يحيي البلاد وينعش العباد.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص40"},{"id":"m581","text":"السلطان الجائر كالنار تحرق البلاد، وتهلك العباد.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص40"},{"id":"m582","text":"أحق الناس بالإحسان من جاز حكمه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص40"},{"id":"m583","text":"استكثروا من الحمد بالحلم والجود، فإن الذم قل من ينجو منه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص40"},{"id":"m584","text":"إذا أقبلت عليك الدنيا فلير آثارها على من حولك.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص40"},{"id":"m585","text":"الكريم يطلب المال لينفقه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص40"},{"id":"m586","text":"لن تبلغ مرتبة الشرف حتى تطأ طرف السرف.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص40"},{"id":"m587","text":"إذا أردت أن تطفئ الفتنة، فلا تحرك ساكنا وسكن كل متحرك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص40"},{"id":"m588","text":"من أراد أن يثير الفتنة حرك الساكن، ولم يسكن المتحرك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص40"},{"id":"m589","text":"من وفى لمن لا يرجى كان لمن يرجى أوفى.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص41"},{"id":"m590","text":"قال الرشيد لمعن بن زائدة : سلني، قال : يدك بالعطية أطلق من لساني بالمسألة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص41"},{"id":"m591","text":"أسوس الملوك من كان له في نفوس رعيته هيبة، وفي قلوبهم محبة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص41"},{"id":"m592","text":"الناس لا يصلحون إلا على الشدة واللين، والعفو والعقاب، والبذل والمنع، فإذا كان الأمر كذلك، عاد المنع عطاء، والمكروه محبوبا، بحسب المآل.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص41"},{"id":"m593","text":"وصى ملك ابنه فقال : لا تمكن الناس من كثرة رؤيتهم لك، فإن أجرأ الناس على الأسد أكثرهم له رؤية.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص41"},{"id":"m594","text":"كل كثير عدو للطبيعة ( البرد الكثير، الحر الكثير، الرياح الكثيرة، المطر الكثير ).","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص41"},{"id":"m595","text":"الناس أتباع من غلب.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص41"},{"id":"m596","text":"النفس عيوف شغوف.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص41"},{"id":"m597","text":"ما عاب الرجل الكريم كنفسه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص41"},{"id":"m598","text":"والمرء يصلحه الجليس الصالح.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص41"},{"id":"m599","text":"من لم يحسن إلى نفسه كيف يحسن إلى غيره ؟.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص41"},{"id":"m600","text":"ناقل القبيح أقبح من قائله.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص41"},{"id":"m601","text":"وجه المحرش أقبح.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص41"},{"id":"m602","text":"أنت فيهم كالرأس في البدن، والعين في الرأس، والإنسان في الحدقة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص41"},{"id":"m603","text":"كيف لا أستحي، وأنا ملتحي.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص41"},{"id":"m604","text":"يحلب تيسا من شهوة اللبن.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات المطوع، ص41"},{"id":"m605","text":"أخفق حالب التيس.","kind":"mathal","topic":"العقل والحكمة","note":"تكرر في الصفحة السابقة بخلل استخراج فأثبت هنا","source":"شذرات المطوع، ص42"},{"id":"m606","text":"القرد قبيح مليح.","kind":"mathal","topic":"الحياة والزمن","note":"تكرر في الصفحة السابقة بصيغة «القدر» بخلل استخراج فأثبت هنا","source":"شذرات المطوع، ص42"},{"id":"m607","text":"الكافي الخائن خير من العاجز الأمين.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m608","text":"أين الكفاة الخونة ؟.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m609","text":"ينبغي للملك أن يرفق بعدوه، كالزجاج يرفق بالزجاجة حتى يضعها على حد الكسر ثم يكسرها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m610","text":"الفرار في وقته انتصار.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m611","text":"ربما نتج الاقدام من الاحجام.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m612","text":"الإدبار في حينه إقبال.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m613","text":"الفر في وقته كالكر في وقته.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m614","text":"التأخر قبل التندم خير من التندم بعد التقدم.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص42"},{"id":"m615","text":"ينبغي للملك أن يختار الحال المناسبة مع عدوه : المقاربة والملاينة، أو المساترة والمخافتة، أو المكاشفة والمحاربة. ويتوخى سيرة الرسول.","kind":"hikma","topic":"السياسة والقيادة","note":"لعل الصلاة على النبي سقطت بعد «الرسول»","source":"شذرات المطوع، ص42"},{"id":"m616","text":"يستحسن في الحرب ما يستقبح في السلم : الخديعة والمكر والكذب، والتبذير والجهل والتهور، وترك النظر في العواقب والعنف والكيد.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m617","text":"الجهل في الحرب خير من العقل، والمحرض خير من المقاتل.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m618","text":"الحرب يقدمها الكلام.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m619","text":"الحرب سجال، وعثراتها لا تقال.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m620","text":"المكيدة أبلغ من النجدة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m621","text":"المكر حيلة من لا حيلة له.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص42"},{"id":"m622","text":"الليل جنة الهارب.","kind":"mathal","topic":"السياسة والقيادة","source":"شذرات المطوع، ص43"},{"id":"m623","text":"الهارب لا يعرج على صاحب.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص43"},{"id":"m624","text":"الفر في حينه كر.","kind":"mathal","topic":"السياسة والقيادة","source":"شذرات المطوع، ص43"},{"id":"m625","text":"اتقوا الله، وكونوا أبناء من شئتم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص43"},{"id":"m626","text":"ألذ الأشياء ما كان بعد الحرمان : ألذ الطعام ما أعقب الجوع الشديد، وألذ الشراب ما أعقب الظمأ، وألذ النوم ما أعقب السهر، وأطيب النكاح ما كان بعد عزوبة، وعلى هذا جميع ملاذ الدنيا.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص43"},{"id":"m627","text":"من رأى وجهه جميلا، فلا يشنه بقبيح من فعله.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص43"},{"id":"m628","text":"من رأى وجهه قبيحا، فليحسن فعله، ولا يجمع بين قبيحين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص43"},{"id":"m629","text":"الشرف في التغافل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص43"},{"id":"m630","text":"التغافل من عادات الملوك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص43"},{"id":"m631","text":"أهل المروءات ينخدعون للسؤال.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص43"},{"id":"m632","text":"من كمال مروءة الرجل أن يجر ذيله على الخدائع.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص43"},{"id":"m633","text":"من صفات سيد القوم التغابي.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص43"},{"id":"m634","text":"من أمارات العاقل أن لا يكثر نظره في محقرات الأمور، لأنها تشغله عن جلائلها ومهماتها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص43"},{"id":"m635","text":"من خدم الملوك خدم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص43"},{"id":"m636","text":"من نصح في خدمته، نصح في مكافأته.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص43"},{"id":"m637","text":"قليل التوفيق أجدى عليك من كثير الاجتهاد.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص43"},{"id":"m638","text":"اللهم إن أعنتنا فوفقنا، وإن خذلنا فلا تحرمنا.","kind":"hikma","topic":"الإيمان والعبادة","note":"دعاء","source":"شذرات المطوع، ص43"},{"id":"m639","text":"لا تقل كل ما لديك في أول الجلسة، حتى لا تجد موضعا للمزيد.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص44"},{"id":"m640","text":"لا تمنح صديقك معروفك كله، ودع للمزيد موضعا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص44"},{"id":"m641","text":"لا تبذل المجهود كله، ودع شيئا للطوارئ والطوارق.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص44"},{"id":"m642","text":"لا تجالس المسخوط عليه، ولا الظنين، ولا صاحب نحلة هو بها ضال، إلا أن تكون ناصحا أو مصلحا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص44"},{"id":"m643","text":"حسن الاستماع يميل نحوك قلب المتحدث إليك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص44"},{"id":"m644","text":"سوء الاستماع يبين عنك قلب المتحدث إليك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص44"},{"id":"m645","text":"الزكمة سيئة الجوار.","kind":"mathal","topic":"الصحة والنفس","source":"شذرات المطوع، ص44"},{"id":"m646","text":"المريض يعاد ولا يجالس، ويسأل عنه، ولا يسأل.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص44"},{"id":"m647","text":"وعد البخيل مزاح، ومزاح الكريم وعد.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص44"},{"id":"m648","text":"وعيد الجبان مزاح، ومزاح الشجاع وعيد.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص44"},{"id":"m649","text":"موائد الملوك للتشريف لا للتشبيع.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص44"},{"id":"m650","text":"إذا حضر طعام، فلا تسافر يدك على الخوان، ولا ترعى عشب الجيران، ولا تبادر هتك الألوان.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص44"},{"id":"m651","text":"جودة الأكل إنما تحسن مع من لا يحتشم منهم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص44"},{"id":"m652","text":"قلم أظافرك، ونظف كمك، وصغر لقمتك، وكل مع من شئت.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص44"},{"id":"m653","text":"ما سكن الغضبان، ولا استعطف السلطان، ولا سلت السخائم، ولا وضعت المغارم، ولا استميلت القلوب، ولا توقي المرهوب، بمثل الهدايا والهبات.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص44"},{"id":"m654","text":"الحرب تقع بين حوارين : حوار يتصاعد يسلم إلى الحرب، وحوار يتنازل يسلم إلى السلم. وكذلك الخصومات، والاختلافات. على هيئة الذي يرقى جبلا أو قبة، يبدأ من الحضيض ثم السفح ثم القمة، ثم من القمة إلى السفح ثم الحضيض.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص45"},{"id":"m655","text":"مادح البخيل يحرث الماء، ويطحن الهواء.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص45"},{"id":"m656","text":"مادح الكريم يهز الأشجار المثمرة، ويلتقط الثمار اليانعة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص45"},{"id":"m657","text":"لا تسترضعوا الحمقاء، فإن اللبن يفسد النسب.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص45"},{"id":"m658","text":"والمرء يفسده الجليس الفاسد.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص45"},{"id":"m659","text":"من أساء إلى نفسه كيف لا يسيء إلى غيره.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص45"},{"id":"m660","text":"الحرب تبدأ بالكلام، وتنتهي بالكلام.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص45"},{"id":"m661","text":"الحرب والسلم يبدأن بالكلام.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص45"},{"id":"m662","text":"اتق دعوة اليتيم والغريب، والأرملة والضعيف، ومن لا حيلة له.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص45"},{"id":"m663","text":"خير العلم ما لاكته بلسانك، ووعاه قلبك.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص45"},{"id":"m664","text":"من أبدى لنا زيا حسنا، أحسنا به الظن، فيما غاب به عنا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص45"},{"id":"m665","text":"من أبدى لنا زيا سيئا، أسأنا به الظن، فيما غاب به عنا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص45"},{"id":"m666","text":"ترك الفخر أبقى للثناء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص45"},{"id":"m667","text":"أسرع جرم عقوبة البغي.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص45"},{"id":"m668","text":"من سوء الأدب كثرة العتاب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص45"},{"id":"m669","text":"المسألة أرذل المكسبة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص45"},{"id":"m670","text":"الانقباض يكسب المقت.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص46"},{"id":"m671","text":"الاسترسال يدعو جليس السوء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص46"},{"id":"m672","text":"كن في الناس بين المنقبض والمسترسل.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص46"},{"id":"m673","text":"الغريب بكل مكان ذليل.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص46"},{"id":"m674","text":"العزة مع الكثرة، والذلة مع القلة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص46"},{"id":"m675","text":"من يبحث العيب يجده.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص46"},{"id":"m676","text":"نفى اللوم عن نفسه الرسول.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص46"},{"id":"m677","text":"الشر يبدؤه صغاره.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات المطوع، ص46"},{"id":"m678","text":"المكثار كحاطب ليل.","kind":"mathal","topic":"الكلام والصمت","source":"شذرات المطوع، ص46"},{"id":"m679","text":"خير الكلام ما يستعاد.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص46"},{"id":"m680","text":"الأنس يذهب المهابة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص46"},{"id":"m681","text":"تناءوا في الديار، وتواصلوا في المزار.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص46"},{"id":"m682","text":"من طاب فعله، طاب ذكره.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص46"},{"id":"m683","text":"طيبوا أخباركم بحسن أعمالكم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص46"},{"id":"m684","text":"لن ترى في ولدك ما تحب، حتى ترى في نفسك ما تكره.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص46"},{"id":"m685","text":"من أسعده ولده، أشقاه بدنه.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص46"},{"id":"m686","text":"لا تكثر الوعد، فإن فيه شائبة رق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص47"},{"id":"m687","text":"المرض ضعف عارض، والهرم ضعف مقيم.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص47"},{"id":"m688","text":"من أكل ما يشتهيه فقد أكل، ومن أكل ما لا يشتهيه فقد أكل.","kind":"hikma","topic":"الصحة والنفس","note":"لعل الثانية: أُكل","source":"شذرات المطوع، ص47"},{"id":"m689","text":"من جاد لك بمودته، فقد جعلك عديل نفسه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص47"},{"id":"m690","text":"توق الإفراط في المحبة، فإن الإفراط يدعو إلى التقصير.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص47"},{"id":"m691","text":"المحبة المتنامية خير من المحبة المتناهية.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص47"},{"id":"m692","text":"اقتصد في حبك وبغضك، فإنك لا تدري متى تتغير الأحوال.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص47"},{"id":"m693","text":"من أكثر العتاب لم يكترث بسخطه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص47"},{"id":"m694","text":"تناس مساوي الإخوان، يدم لك ودهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص47"},{"id":"m695","text":"التواصل يحتاج إلى التغافل.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص47"},{"id":"m696","text":"العاقل فطن متغافل.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص47"},{"id":"m697","text":"تثمير المال يعين على اصطناع الرجال.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m698","text":"من استصلح عدوه، زاد في أصدقائه، وانقص من أعدائه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص48"},{"id":"m699","text":"تستصلح الأعادي بحسن الأيادي.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص48"},{"id":"m700","text":"ذكروا عباد الله، بإحسان الله وإنعامه، فإن الناس لا يحبون إلا من أنعم عليهم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص48"},{"id":"m701","text":"السخي قريب من الله، قريب من الناس، قريب من الجنة، بعيد من النار.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m702","text":"البخيل بعيد من الله، بعيد من الناس، بعيد من الجنة، قريب من النار.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m703","text":"سادات الناس في الدنيا الأسخياء، وفي الآخرة الأتقياء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص48"},{"id":"m704","text":"الحرص : المبالغة في طلب الشئ. والشره : الاستكثار لغير الحاجة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص48"},{"id":"m705","text":"مثل الاقتصاد والإسراف مثل الصديق والعدو.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m706","text":"الإسراف : ما زاد عن الحاجة. والتبذير : ما كان لغير حاجة فالتبذير أشد من الإسراف.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m707","text":"كل سرف بإزائه حق مضيع.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m708","text":"في إعطاء من لا يستحق، حرمان من يستحق.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m709","text":"البذل الجائر يعدل المنع الجائر.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m710","text":"الإسراف يهدر الحقوق، والاقتصاد يحفظها.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m711","text":"حسن الظن قبل التجربة غرر، وسوء الظن قبل التجربة حذر.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص48"},{"id":"m712","text":"ترك الإسراف يحفظ الأكرمين : الدين والعرض.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m713","text":"من اتخذ التبذير رداء خرج من بحبوحة الحلال.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m714","text":"الاقتصاد يصون ماء الوجه، والتبذير يبذل.","kind":"hikma","topic":"المال والاقتصاد","note":"لعلها: يبذله","source":"شذرات المطوع، ص48"},{"id":"m715","text":"المسرف لا يسعه الحلال، والمقتصد لا يضيق عليه الحلال.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m716","text":"من تمام السخاء أن لا تستشرف نفسك إلى ما في أيدي الناس.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص48"},{"id":"m717","text":"شر النكاح نكاح الغلمة.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص49"},{"id":"m718","text":"لقاء الإخوان جلاء الأحزان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص49"},{"id":"m719","text":"الغريب من ليس له حبيب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص49"},{"id":"m720","text":"الأضداد لا تتفق، والأشكال لا تفترق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص49"},{"id":"m721","text":"التشاكل قرابة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص49"},{"id":"m722","text":"مراتب الإخاء : التجانس ثم المواصلة ثم المؤانسة، ثم المصافاة ثم المودة ثم المحبة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص49"},{"id":"m723","text":"رب صديق أقرب من شقيق.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص49"},{"id":"m724","text":"اسبر تخبر.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات المطوع، ص49"},{"id":"m725","text":"الرجل يعرف من فعله لا من كلامه، ومن عينه لا من لسانه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص49"},{"id":"m726","text":"يظن بالمرء ما يظن بقرينه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص49"},{"id":"m727","text":"مصارمة قبل اختبار، خير من مؤاخاة على اغترار.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص49"},{"id":"m728","text":"لا تثق قبل الخبرة، ولا تتقدم قبل القدرة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص49"},{"id":"m729","text":"المدح والذم بعد التجربة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص49"},{"id":"m730","text":"زيادة العقل بمجالسة العقلاء.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص49"},{"id":"m731","text":"العاقل يعاشر بالمعروف من لم يجد من معاشرته بدا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص49"},{"id":"m732","text":"خيار كل شئ قليل.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص49"},{"id":"m733","text":"أول مراتب الإخوة التجانس والمشاكلة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص49"},{"id":"m734","text":"فساد الزمان وأهله، يوجب شكر من قطع شره، ومنع خيره.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص49"},{"id":"m735","text":"صلاح الزمان وأهله، يوجب ذم من قطع شره، ومنع خيره.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص49"},{"id":"m736","text":"أقسام الإخوان أربعة : منهم يعين ويستعين، ومنهم لا يعين ولا يستعين، فهذان سواء، فهذه بتلك. ومنهم من يستعين ولا يعين، فهذا أرذلها. ومنهم من يعين ولا يستعين، فهذا أفضلها.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص50"},{"id":"m737","text":"التارك للإخوان متروك، والمعتزل معزول.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص50"},{"id":"m738","text":"العاقل لا يزهد في الصديق لخلق أو خلقين، إذا رضي سائر أخلاقه وحمد أكثر شيمه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص50"},{"id":"m739","text":"يكفيك من أخيك أكثره.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص50"},{"id":"m740","text":"نفسك التي بين جنبيك، لا تعطيك قيادها في كل ما تريد، فكيف بنفس غيرك؟","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص50"},{"id":"m741","text":"أدوم الأعمال أيسرها.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص50"},{"id":"m742","text":"الجمال والقبح إذا اقترنا زادا، وإذا افترقا نقصا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص50"},{"id":"m743","text":"الجمال والجمال إذا اقترنا نقصا، وإذا افترقا زادا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص50"},{"id":"m744","text":"كل مقيم شاخص، وكل زائد ناقص.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص50"},{"id":"m745","text":"أسمى درجات التفكير في مسائل القدر ترك التفكير.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص50"},{"id":"m746","text":"التسليم في مسائل القضاء والقدر أجدى على الإنسان من التفكير.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص50"},{"id":"m747","text":"في مسائل القضاء والقدر الإعراض عن التفكير تفكير.","kind":"hikma","topic":"الإيمان والعبادة","note":"في المستخرج: الأعراض","source":"شذرات المطوع، ص50"},{"id":"m748","text":"الطير أكثر توكلا من الإنسان في قضية الرزق.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص50"},{"id":"m749","text":"الحيوان أسعد من الإنسان في قضية الإيمان بالقضاء والقدر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص50"},{"id":"m750","text":"الحيوان أعقل من الإنسان في مسائل القضاء والقدر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص50"},{"id":"m751","text":"ترك التفكير تفكير، وترك الرأي رأي.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص50"},{"id":"m752","text":"ليس السعي في طلب المعاش من طلب الدنيا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص51"},{"id":"m753","text":"إذا كان في البيت بر فتعبد، وأن لم يكن فأطلبه بالعمل.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص51"},{"id":"m754","text":"يا بن آدم حرك يديك ورجليك، يفتح لك باب من رزق.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص51"},{"id":"m755","text":"ليس من إيثار الدنيا على الآخرة، اكتساب ما يصون العرض، ويحفظ ماء الوجه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص51"},{"id":"m756","text":"السلطان قد يفسد، وما يصلح الله به أكثر، فإن عدل فله الأجر، وعليكم الشكر، وإن جار فعليه الوزر، وعليكم الصبر.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص51"},{"id":"m757","text":"إذا أحب الله عبدا حببه إلى خلقه، فاعرف منزلتك من الله تعالى بمنزلتك من الناس.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص51"},{"id":"m758","text":"مالك عند الله، مثل ما لله عندك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص51"},{"id":"m759","text":"من اتقى الله، أطاعه في خلقه، وطاعته في خلقه تبعث على محبته، فكانت محبتهم له أمارة على محبة الله له.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص51"},{"id":"m760","text":"أخش الله في الناس، ولا تخش الناس في الله.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص51"},{"id":"m761","text":"بئس الزاد إلى المعاد، العدوان على العباد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص51"},{"id":"m762","text":"إذا انحاز المختلفان إلى العدل، لم يحتاجا إلى القوة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص51"},{"id":"m763","text":"إذا قصد المتنازعان الإصلاح منحا التوفيق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص51"},{"id":"m764","text":"نية الإصلاح تجلب التوفيق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص51"},{"id":"m765","text":"إرادة الإصلاح أمارة التوفيق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص51"},{"id":"m766","text":"ينال التوفيق على قدر إرادة الإصلاح.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص51"},{"id":"m767","text":"من أراد الله أن يوفقه هداه إلى أحمد السبل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص52"},{"id":"m768","text":"ويبقى الائتلاف ما بقي الإنصاف.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص52"},{"id":"m769","text":"أول درجات الائتلاف الإنصاف.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص52"},{"id":"m770","text":"العدل ميزان الله في أرضه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص52"},{"id":"m771","text":"حلية العالم قلة الطمع وكثرة الورع.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص52"},{"id":"m772","text":"أشتهي أن أرى عالما قليل الطمع كثير الورع.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص52"},{"id":"m773","text":"إذا رأيت الرجل يداري الناس كلهم، فاعلم أنه تام العقل.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص52"},{"id":"m774","text":"دار الناس كلهم فأنت في دار المداراة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص52"},{"id":"m775","text":"معرفة مقدار النعمة منوط بمقاساة ضدها.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص52"},{"id":"m776","text":"عندما ابتليت، علمت أن الله لم يبتلني قبل ذلك، ولا أكثر من ذلك، ولا في غير ذلك، ورجوت أن يرفعه عني، فأعانني ذلك على الصبر، وصرت من الشاكرين لا الشاكين.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص52"},{"id":"m777","text":"إذا كثر المطر، كثر الخصب، وإذا كثر الخصب كثر الغنى، واذا كثر الغنى، كثرت الأمانة والسخاء.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص52"},{"id":"m778","text":"جمع خير الدنيا والآخرة في التقى والغنى، وجمع شر الدنيا والآخرة في الفقر والفجور.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص52"},{"id":"m779","text":"الفرق بين الآمال والأماني ترك العمل.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص52"},{"id":"m780","text":"الدنيا مقلوبة، فإذا انقلبت استوت.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص52"},{"id":"m781","text":"لا ترج من الناس الطاعة، ونفسك تمنعك الطاعة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص52"},{"id":"m782","text":"إذا عصاك هواك، فكيف تطمع أن يطيعك من يهواك.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص52"},{"id":"m783","text":"من تفكر أبصر.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص52"},{"id":"m784","text":"الولد ثمرة الفؤاد، وهو به أنوط.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m785","text":"شر الأبناء للآباء من دعاه التفريط للعقوق.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m786","text":"شر الآباء للأبناء من دعاه البر إلى الإفراط.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m787","text":"إن الله تعالى رضي الآباء للأبناء، فحذرهم فتنتهم، ولم يوصهم بهم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m788","text":"إن الله تعالى لم يرض الأبناء للآباء، فأوصاهم بهم، وحذرهم من الإساءة إليهم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m789","text":"حق الوالد أعظم، وبر الأم ألزم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m790","text":"ولد الولد الصفوة.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m791","text":"رحم الله امرأ أعان ولده على بره.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m792","text":"البعيد قريب بمودته، والقريب بعيد بعداوته.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص53"},{"id":"m793","text":"العقوق ثكل من لم يثكل.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m794","text":"امش وراء الأسد، ولا تمش وراء المرأة.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص53"},{"id":"m795","text":"إن صاحبت غير المحمود، لم يصحبك المحمود.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص53"},{"id":"m796","text":"قال حكيم لأبنائه : قد أحسنت إليكم قبل أن تولدوا، قالوا : كيف ذلك ؟ قال : أحسنت اختيار أمكم وأخوالكم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m797","text":"أول إحسان الأب لأولاده، اختيار أمهم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m798","text":"أنجب النساء الفروك.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص53"},{"id":"m799","text":"ولد الغيرى لا ينجب.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص53"},{"id":"m800","text":"إذا أكره الرجل المرأة، وهي مذعورة، ثم أذكرت أنجبت.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص53"},{"id":"m801","text":"الجاه بالبذل ينمي ويزيد، وبالكف ينقص ويبيد.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص54"},{"id":"m802","text":"الخلق عيال الله وأحب خلق الله إليه، أحسنهم صنيعا إلى عياله.","kind":"hikma","topic":"الإيمان والعبادة","note":"في المستخرج: عيال","source":"شذرات المطوع، ص54"},{"id":"m803","text":"اصنع الخير عند إمكانه يبق لك حمده عند زواله.","kind":"hikma","topic":"الأخلاق والآداب","note":"في المستخرج: زوال","source":"شذرات المطوع، ص54"},{"id":"m804","text":"أحسن والدولة لك، يحسن إليك والدولة عليك.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص54"},{"id":"m805","text":"اجعل زمان رخائك عدة لزمان بلائك.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص54"},{"id":"m806","text":"من أمارات تحسين الحال اصطناع الرجال.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص54"},{"id":"m807","text":"بذل الجاه أحد الحباءين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m808","text":"ليس حسن الجوار كف الأذى، بل الصبر على الأذى.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m809","text":"من أحسن إلى جاره فقد دل على حسن نجاره.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m810","text":"أشبه أفعال الناس بأفعال الله تعالى، الإحسان إلى الناس.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m811","text":"من أمرك لأداء الفرائض، أمرك بمداراة الناس.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص54"},{"id":"m812","text":"إن الله تعالى أمر بالعبادة، وأمر بحسن الخلق.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص54"},{"id":"m813","text":"لا تقطع أخاك إلا بعد نفاد الحيلة في استصلاحه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص54"},{"id":"m814","text":"في الخير البادئ خير من المكافئ، وفي الشر المكافئ أعذر من البادئ، وان كان الصفح أجمل وأنبل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m815","text":"من فعل ما شاء لقي ما لم يشأ.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m816","text":"اعتزل الشر يعتزلك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m817","text":"أقرض الناس من عرضك ليوم فاقتك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص54"},{"id":"m818","text":"العاقل الكريم صديق كل أحد إلا من ضره.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص54"},{"id":"m819","text":"الجاهل اللئيم عدو كل أحد إلا من نفعه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص54"},{"id":"m820","text":"شر ما في الكريم أن يمنعك خيره.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m821","text":"خير ما في اللئيم أن يكف عنك شره.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m822","text":"أعداؤك داؤك، وفي البعد عنهم شفاؤك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص54"},{"id":"m823","text":"من شرف الكريم تغافله عن اللئيم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m824","text":"إذا سلم الناس منك، فلا عليك ألا تسلم منهم، فإنه قلما اجتمعت هاتان النعمتان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص54"},{"id":"m825","text":"نماء المودة بكثرة التعاهد.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص54"},{"id":"m826","text":"لا تهجر صديقك الأول، فلا يطمئن لك الثاني.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص54"},{"id":"m827","text":"العفو والعقوبة، كالجود والبخل، فاختر أيهما شئت.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m828","text":"إذا جفاك أخوك لملل لا لزلل، فدعه على ملله، حتى يمل الجفاء كما مل الإخاء، فيعود لسابق عهده.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص54"},{"id":"m829","text":"كل ما أصميت، ودع ما أنميت.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات المطوع، ص55"},{"id":"m830","text":"لا تمثلوا بنامية الله.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص55"},{"id":"m831","text":"إن أساء إليك أخوك، ثم ظهر ندمه، وبان خجله، فاجعل ندمه اعتذارا، ولا تكلفه ذل الاعتذار.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص55"},{"id":"m832","text":"آخر ما نزل من القرآن : ( واتقوا يوما ترجعون فيه إلى الله ثم توفى كل نفس ما كسبت وهم لا يظلمون ).","kind":"hikma","topic":"الإيمان والعبادة","note":"سقطت «لا» من المستخرج فأثبتت من نص الآية","source":"شذرات المطوع، ص55"},{"id":"m833","text":"وآخر ما نزل من التوراة : إذا لم تستح فاصنع ما شئت.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص55"},{"id":"m834","text":"وآخر ما نزل من الإنجيل : شر الناس من لا يبالي أن يراه الناس مسيئا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص55"},{"id":"m835","text":"وآخر ما نزل من الزبور : من يزرع خيرا يحصد زرعه غبطة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص55"},{"id":"m836","text":"من خان هان.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص55"},{"id":"m837","text":"من يذنب ويشعر بالندم، خير ممن يذنب ولا يشعر بالندم ومن يذنب ولا يشعر بالندم، خير ممن يذنب ويتباهى بالذنب. فالأول يرجى له والثاني يرجى له ويخشى عليه، والثالث يخشى عليه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص55"},{"id":"m838","text":"لا يحملنكم إبطاء الرزق، على أن تطلبوه بمعاصي الله تعالى، فإن الله لا يدرك ما عنده إلا بطاعته.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص56"},{"id":"m839","text":"إذا لم يشق المرء إلا بما عمل فقد سعد.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص56"},{"id":"m840","text":"من حسن ظنه بمن لا يخاف الله فهو مخدوع.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص56"},{"id":"m841","text":"يسير المال مع حسن التدبير، أجدى نفعا من كثيره مع سوء التدبير.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص56"},{"id":"m842","text":"المضارب في مال كالباذر في أرضه إذا روعي يسيره زكا، وإن أهمل كثيره اضمحل.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص56"},{"id":"m843","text":"لا تكن على أحد كلا، فتزداد ذلا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص56"},{"id":"m844","text":"الكاسب خير من الوارث، لأن الكاسب ينفع غيره، والوارث ينتفع من غيره.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص56"},{"id":"m845","text":"أحفظ ماء وجهك بالقناعة واذكر الله تعالى في كل ساعة، فنعمت البضاعة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص56"},{"id":"m846","text":"إن استطعت أن لا يكون بينك وبين الله ذو نعمة فافعل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص56"},{"id":"m847","text":"لا تكن عبد غيرك وقد جعلك الله حرا، فإن اليسير من الله تعالى أكرم وأعظم من الكثير من غيره، ويسير الله تعالى أكثر من كثير غيره.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص56"},{"id":"m848","text":"قدم لحاجتك، بعض لجاجتك، فإنه لا يظفر بحاجته إلا الملح الصبور.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص57"},{"id":"m849","text":"رق الدين أيسر من رق الإفضال.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص57"},{"id":"m850","text":"من ألف المسألة ألف المنع.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص57"},{"id":"m851","text":"العاقل إن منع عذر، وإن منح شكر.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص57"},{"id":"m852","text":"الخير كثير، وقليل فاعله.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص57"},{"id":"m853","text":"أصحاب المال والاقتدار كثيرون، والمعين منهم قليل.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص57"},{"id":"m854","text":"كريم الطبع يساعد، ولئيم الطبع يعاند.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص57"},{"id":"m855","text":"المخذول من كانت له إلى اللئام حاجة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص58"},{"id":"m856","text":"من أوغرت صدره، استدعيت شره.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص58"},{"id":"m857","text":"لا تطلب الحوائج من غير أهلها، ولا تطلبها في غير حينها، ولا تطلب ما لست له مستحقا، فإنك إن فعلت ذلك كنت حقيقا بالحرمان.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص58"},{"id":"m858","text":"كل شيء يحتاج إلى العقل، والعقل يحتاج إلى التجارب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص58"},{"id":"m859","text":"قليل الحيلة أجدى عليك من كثير الشدة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص58"},{"id":"m860","text":"قليل التأني أنفع من كثير العجلة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص58"},{"id":"m861","text":"المستشير معان، والمستشار مؤتمن.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص58"},{"id":"m862","text":"الخيرة في ترك الطيرة، وكفارتها التوكل على الله، وان يقول : اللهم لا يأتي بالخير إلا أنت، ولا يدفع الشر إلا أنت، ولا حول ولا قوة إلا بالله.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص58"},{"id":"m863","text":"إن البلاء موكل بالمنطق. شكا يوسف عليه السلام طول الحبس، فأوحى الله تعالى إليه : يا يوسف أنت حبست نفسك، حيث قلت : ( رب السجن أحب إلي) ولو قلت العافية أحب إلي لعوفيت.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص58"},{"id":"m864","text":"العقل يأمرك بالأنفع، والمروءة تأمرك بالأجمل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص58"},{"id":"m865","text":"لا تصغرن هممكم، فإني لم أر أقعد عن المكرمات من صغر الهمم.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص58"},{"id":"m866","text":"الهمة راية الجد.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص58"},{"id":"m867","text":"علو الهمة يدعو إلى الرفعة، ويأنف من الضعة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص58"},{"id":"m868","text":"اتقوا الإفراط في الأكل، فإنه يؤدي إلى السمنة، والسمنة تخفي جمال البدن.","kind":"hikma","topic":"الصحة والنفس","note":"«السمنة» و«تخفي» على الترجيح من «السمىن» و«ختيف»","source":"شذرات المطوع، ص58"},{"id":"m869","text":"السمنة راية الخمول.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص58"},{"id":"m870","text":"من طال كسله، خاب أمله.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص58"},{"id":"m871","text":"عاجز تزوج كسلانه، ورزق منها ببنتين، حسرة وندامة، وابنين : تعبان وخايب.","kind":"mathal","topic":"الحياة الزوجية","source":"شذرات المطوع، ص58"},{"id":"m872","text":"شرف النفس مع صغر الهمة، خير من علو الهمة مع دناءة النفس.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص58"},{"id":"m873","text":"من علت همته واتضعت نفسه، منع ما يجب عليه وطلب ما لا يستحقه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص58"},{"id":"m874","text":"من شرفت نفسه وصغرت همته، أعطى كل ما يجب عليه، وترك بعض ما يستحق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص58"},{"id":"m875","text":"المروءة : مراعاة المرء لأقوال وأفعال وأحوال ليبلغ بنفسه أفضل منازلها، وينفي عنها القبيح والذم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص58"},{"id":"m876","text":"أحب العفاف إلى الله تعالى : عفاف الفرج، واللسان والبطن.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص58"},{"id":"m877","text":"عار الفضيحة أربى على لذتها.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص58"},{"id":"m878","text":"النظرة بعد النظرة، تزرع في القلب الشهوة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص58"},{"id":"m879","text":"العيون سهام الشيطان، يصطاد بها الغافل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص58"},{"id":"m880","text":"العاقل الحازم من ملك نفسه، حين يرغب وحين يرهب وحين يشتهي وحين يغضب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص58"},{"id":"m881","text":"الشهوة تخدع العقل، فتحسن له القبيح وتزين الباطل بالمديح.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص59"},{"id":"m882","text":"ما أمر الله تعالى بشيء إلا وأعان عليه، ولا نهى عن شيء إلا وأغنى عنه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص59"},{"id":"m883","text":"الفتنة نائمة فمن أيقظها صار طعاما لها.","kind":"hikma","topic":"السياسة والقيادة","note":"في المستخرج «ممن»","source":"شذرات المطوع، ص59"},{"id":"m884","text":"كل خاطب كلامه يشوبه الكذب.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص59"},{"id":"m885","text":"إن كان الكلام ترغيبا فاقرنه باللين واللطف، وإن كان ترهيبا فاقرنه بالخشونة والعنف.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص59"},{"id":"m886","text":"الاعراض عن الفحش احد النكيرين","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص59"},{"id":"m887","text":"لا تتعجل هما لم يات، فإن أكثر الهموم كاذبة.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص59"},{"id":"m888","text":"من قوى صبره لم يفارقه رأيه، ومن ضعف صبره، عزب عنه رأيه.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص59"},{"id":"m889","text":"أشد البلاء المفاجئ، وأهونه المنتظر.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص59"},{"id":"m890","text":"التوقع يخفف التوجع.","kind":"hikma","topic":"الصبر والشدائد","note":"في المستخرج «يفف»","source":"شذرات المطوع، ص59"},{"id":"m891","text":"المنح والمحن لا تتحرر في الدنيا، ويشوب بعضها بعضا.","kind":"hikma","topic":"الحياة والزمن","note":"«تتحرر» كما في المستخرج، وربما كانت «تتجرد»","source":"شذرات المطوع، ص59"},{"id":"m892","text":"اذكروا أهل البلاء، فتعظم نعم الله في قلوبكم، ويتجدد شكركم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص59"},{"id":"m893","text":"أقروا النعم بالشكر، ولا تنفروها بالجحود.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص59"},{"id":"m894","text":"دعوا الأضغان مدفونة، ولا تبعثوها بالتذكر.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص60"},{"id":"m895","text":"دعوا الدموع قارة في مآقيها ولا تستفزوها بالتذكر.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص60"},{"id":"m896","text":"تذكر الاشجان يبعث الاحزان.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص60"},{"id":"m897","text":"من ترك المشورة فقد ودع الحزم.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص60"},{"id":"m898","text":"إنما يستشار ذو الرأي الناصح، وذو العقل الراجح، وأهل الخبرة، وأصحاب التجارب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص60"},{"id":"m899","text":"تنجيز الأعمال يحتاج إلى العزم، والعزم يحتاج إلى المشورة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص60"},{"id":"m900","text":"المشورة حصن من الندامة وأمان من الملامة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص60"},{"id":"m901","text":"أمر الله تعالى نبيه صلى الله عليه وسلم بمشاورة أصحابه، ( وشاورهم في الأمر ) في الشئون المهمة، تألفا لهم، وتطيبا لأنفسهم، ولبيان فضل المشاورة، وليستن به ولاة الأمر، والمسلمون، ولتنقية الرأي من الشوائب، وتزكيته.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص60"},{"id":"m902","text":"من استشار قبل الشروع، فقد أحرز شطر النجاح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص61"},{"id":"m903","text":"نعم المؤازرة المشاورة، وبئس الاستعداد الاستبداد.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص61"},{"id":"m904","text":"المشاورة والمناظرة يجليان الرأي، وينفيان عنه الشوائب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص61"},{"id":"m905","text":"من اتهم رأيه شاور، ومن أعجب برأيه لم يشاور.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص61"},{"id":"m906","text":"من استبد برأيه، أخطأ طريق الصواب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص61"},{"id":"m907","text":"من ابتدأ عمله بالاستشارة، فقد وضع قدمه على أول الطريق.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص61"},{"id":"m908","text":"من لم يشاور فهو يرى أول عمله، ومن شاور فهو يرى أول وآخره.","kind":"hikma","topic":"العقل والحكمة","note":"«أول وآخره» كما في الأصل، ولعلها «أوله وآخره»","source":"شذرات المطوع، ص61"},{"id":"m909","text":"من استبد برأيه عميت عليه العاقبة، ومن استشار اتضحت له العاقبة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص61"},{"id":"m910","text":"من استشار أمن من العثار، ومن استغنى برأيه لم يأمن الأخطار.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص62"},{"id":"m911","text":"إذا أعجبتك قدرتك على المخلوق، فاذكر قدرة الله عليك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص62"},{"id":"m912","text":"اذا قدرت على خصمك، فقبل الانتقام والعقاب، اذكر الذي أنت بين يديه، أذل منه بين يديك، والذي هو أقدر على عقابك منك على عقابه، فإذا أنت يستهويك العفو.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص62"},{"id":"m913","text":"علاج قسوة القلب : تشييع الجنائز، وزيارة القبور، عيادة المرضى، كفالة اليتيم، مجالسة المساكين وفقراء المسلمين، كثرة ذكر هادم اللذات، حضور مجالس العلم، وحلق الذكر، قراءة الرقائق، عدم الإكثار من أكل اللحوم، الصيام، مسح رأس اليتيم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص62"},{"id":"m914","text":"كان أحد الملوك يردع غضبه، بان يلقي بين يديه مفاتيح قبور الملوك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص62"},{"id":"m915","text":"من أكثر من ذكر الموت رضي من الدنيا باليسير.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص62"},{"id":"m916","text":"ليس من عادة الكرام سرعة الانتقام.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص62"},{"id":"m917","text":"ليس من شروط الكرم قطع النعم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص62"},{"id":"m918","text":"ذو المروءة قدره فوق ذنبه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص62"},{"id":"m919","text":"إدراك ما عند الله بالعفو، أرجى من العقوبة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص62"},{"id":"m920","text":"إن عاقبت من ظلمك فلك نظير، وإن عفوت عنه فلا نظير لك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص62"},{"id":"m921","text":"برك وإحسانك قرب منك المحسن، وشجع المسئ على الاعتذار.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص62"},{"id":"m922","text":"الكذاب لص العقول، لأن اللص يسرق مالك، والكذاب يسرق عقلك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص62"},{"id":"m923","text":"من اشتهر صدقه كثر صديقه، ومن قل صدقه قل صديقه.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص62"},{"id":"m924","text":"رب صدق أربى على الكذب، في القبح والمعرة، والأذى والمضرة، كالغيبة والنميمة، والسعاية والوشاية.","kind":"hikma","topic":"الكلام والصمت","note":"في المستخرج «والمضة»","source":"شذرات المطوع، ص62"},{"id":"m925","text":"الغيبة مرعى اللئام.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص63"},{"id":"m926","text":"الغيبة فاكهة النساء.","kind":"mathal","topic":"الكلام والصمت","source":"شذرات المطوع، ص63"},{"id":"m927","text":"الغيبة شرُ لا خير فيه : شرُ لقائلها، ولا خير فيها لمن قيلت فيه.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص63"},{"id":"m928","text":"سئل رجل : ما الشر الذي لا خير فيه ؟ فقال : ما ضرني ولم ينفع غيري، أو ضر غيري ولم ينفعني.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص63"},{"id":"m929","text":"قيل في موارد الحكم : لا تبد من العيوب، ما ستره علام الغيوب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص63"},{"id":"m930","text":"اللئيم إذا غاب عاب، وإذا حضر اغتاب.","kind":"mathal","topic":"الكلام والصمت","source":"شذرات المطوع، ص63"},{"id":"m931","text":"ازرع المحبة في قلوب الناس بالتحية والسلام، واسقها بالهدايا ولين الكلام.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص63"},{"id":"m932","text":"المؤمن يغبط، والمنافق يحسد.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص63"},{"id":"m933","text":"احذروا فضول المنطق.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص63"},{"id":"m934","text":"تجنب في كلامك، ما يسخط السلطان ويوحش الإخوان.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص63"},{"id":"m935","text":"مقتل الرجل بين فكيه.","kind":"mathal","topic":"الكلام والصمت","source":"شذرات المطوع، ص63"},{"id":"m936","text":"استحي من الله تعالى، استحياءك من ذوي الهيبة من قومك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص63"},{"id":"m937","text":"احتمال السفيه خير من التحلي بصورته.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص63"},{"id":"m938","text":"الإعراض عن الجاهل خير من مشاكلته.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص63"},{"id":"m939","text":"ما أفحش حليم، ولا أوحش كريم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص63"},{"id":"m940","text":"قيل لملك : فلان يطعن فيك، فلو عاقبته، فقال : هو بعد العقوبة أعذر في طعني، فكان هذا تفضلا وتأليفا منه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص64"},{"id":"m941","text":"من خاصمك إن كان فوقك، فاعرف له قدره، وان كان دونك، فارفع قدرك عنه، وان كان نظيرك فتفضل عليه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص64"},{"id":"m942","text":"أحمق الناس من ظن أنه أعقل الناس.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص64"},{"id":"m943","text":"أعقل الناس من لم يتجاوز الصمت في عقوبة الجهال.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص64"},{"id":"m944","text":"قال الشعبي : ما أدركت أمي فأبرها، ولكن لا أسب أحدا فيسبها.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص64"},{"id":"m945","text":"في إعراضك صون أعراضك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص64"},{"id":"m946","text":"اردع السفيه بالحلم، والظالم بالعفو، والقاطع بالوصل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص64"},{"id":"m947","text":"أكرم الشيم أرعاها للذمم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص64"},{"id":"m948","text":"من أتسع غضبه ضاق كيده.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص64"},{"id":"m949","text":"غضب الجاهل في قول، وغضب العاقل في فعله.","kind":"hikma","topic":"العقل والحكمة","note":"«قول» كما في المستخرج، ولعلها «قوله»","source":"شذرات المطوع، ص64"},{"id":"m950","text":"أبلغ جواب على السفيه الصمت.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص64"},{"id":"m951","text":"الحلم ضبط النفس عند هيجان الغضب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص64"},{"id":"m952","text":"أكرموا سفهاءكم، فإنهم يقونكم العار والشنار. ( العيب ).","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص64"},{"id":"m953","text":"لا يعدم مسئ مكافئا، ولا يعدم محسن مجازيا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص64"},{"id":"m954","text":"دخل بيتا ما خرج منه. أي : إن خرج منه خير دخله خير، وإن خرج منه شر دخله شر.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص64"},{"id":"m955","text":"من كثر شططه كثر غلطه. ( الشطط : مجاوزة الحد )","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص65"},{"id":"m956","text":"في إغضائك راحة أعضائك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص65"},{"id":"m957","text":"الغضب يتحرك من داخل الجسد إلى خارجه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص65"},{"id":"m958","text":"الحزن يتحرك من خارج الجسد إلى داخله.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص65"},{"id":"m959","text":"الحادث عن الغضب السطوة والانتقام، وهو لا يقتل صاحبه لبروزه وخروجه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص65"},{"id":"m960","text":"الحادث عن الحزن المرض والأسقام لاستقراره، وقد يقتل صاحبه، أو يذهب ببصره لكمونه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص65"},{"id":"m961","text":"يا ابن آدم اذكرني حين تغضب، أذكرك حين أغضب.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص65"},{"id":"m962","text":"الغضب يتناقص قبل الحزن، والحزن يتزايد ثم يتناقص.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص65"},{"id":"m963","text":"موارد تسكين الغضب : ذكر الله تعالى، الاستعاذة، الوضوء، تغيير المكان، تغيير الهيئة من قيام إلى الجلوس مثلا، التذكير بقدرة الله تعالى، التذكير بفضل العفو وثواب التجاوز، التذكير بمغبة الغضب، وما يلحقه من الندم.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص65"},{"id":"m964","text":"العجب ثمرة التفوق والكبر ثمرة العجب، والكفر ثمرة الكبر.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص65"},{"id":"m965","text":"آفة التفوق العجب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص65"},{"id":"m966","text":"أول الكفر التكبر، وأول التكبر العجب، وأول العجب التميز.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص65"},{"id":"m967","text":"الكبر من المنزلة، والعجب من الفضيلة.","kind":"hikma","topic":"الأخلاق والآداب","note":"في المستخرج «املنلة»","source":"شذرات المطوع، ص65"},{"id":"m968","text":"الإنسان ابن التراب، ويأكله التراب.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص65"},{"id":"m969","text":"قابل المدح كمادح نفسه.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص65"},{"id":"m970","text":"لما وصفت بالكرم سررت مع علمي بأني لست بكريم.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص66"},{"id":"m971","text":"لما وصفت بالبخل، حزنت مع علمي بأني بخيل.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص66"},{"id":"m972","text":"إياكم والتمادح فإنه الذبح الخفي.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص66"},{"id":"m973","text":"النفس يستهويها الثناء، وتميل إلى استماع المدح.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص66"},{"id":"m974","text":"الإنسان بطبعه يحب المدح وان لم يوافق الحق. ويكره القدح وإن وافق الحق.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص66"},{"id":"m975","text":"لم يكد يسلم مادح ولا قادح من شوائب الكذب في ثنائه وتعداده.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص66"},{"id":"m976","text":"عاشر أهلك بأحسن أخلاقك، فإن الثواء فيهم قليل.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص66"},{"id":"m977","text":"من حسنت أخلاقه كثر أصدقاؤه، وقل أعداؤه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص66"},{"id":"m978","text":"حسن الخلق وحسن الجوار تعمران الديار، ويزيدان في الأعمار.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص66"},{"id":"m979","text":"من تاه في ولايته، ذل في عزله.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص66"},{"id":"m980","text":"من ولي فقد عزل، لأن العزل لا يكون إلا بعد ولاية.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص66"},{"id":"m981","text":"الولاية حلوة الرضاع، مرة الفطام.","kind":"mathal","topic":"السياسة والقيادة","source":"شذرات المطوع، ص66"},{"id":"m982","text":"جند الله الأعظم : الفقر والمرض والهم والهرم والموت، يذل الله بهم كل جبار عنيد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص66"},{"id":"m983","text":"لولا أن الله أذل ابن آدم بثلاث ما طأطأ رأسه لشيء : الفقر والمرض والموت","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص66"},{"id":"m984","text":"إذا أقبلت عليك جيوش الهموم، فادفعها بجيوش الرجاء.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص67"},{"id":"m985","text":"إذا أحدق بك الغم، وأحاط بك الحزن، فاطرده بجميل الأمنيات.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص67"},{"id":"m986","text":"إذا تتابع البلاء، فقعقع له باب الدعاء.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص67"},{"id":"m987","text":"الأماني رأس مال المفلس.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات المطوع، ص67"},{"id":"m988","text":"زينة الحياة : الصحة والشباب.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص67"},{"id":"m989","text":"من كساه الحياء ثوبه لم ير الناس عيبه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص67"},{"id":"m990","text":"افعل ما تحب أن تراه من غيرك، واجتنب ما تكره أن تراه من غيرك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص67"},{"id":"m991","text":"من هتك ستر الله عنه فلا غيبة له.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص67"},{"id":"m992","text":"من خلع جلباب الحياء فلا غيبة له.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص67"},{"id":"m993","text":"الإحسان رق، والمكافأة عتق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص67"},{"id":"m994","text":"السخاء حسن الفطنة، واللؤم سوء التغافل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص67"},{"id":"m995","text":"من بذل ماله أدرك آماله.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص67"},{"id":"m996","text":"بالإحسان يسترق الإنسان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص67"},{"id":"m997","text":"من بذل مرافقه أحبه مرافقه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص68"},{"id":"m998","text":"تهوى الرجل حيث يهوى القلب.","kind":"mathal","topic":"الصحة والنفس","source":"شذرات المطوع، ص68"},{"id":"m999","text":"قال المسئول للسائل : أعدك اليوم، وأحبوك غدا، لتذوق حلاوة الأمل، وأتزين بثوب الوفاء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص68"},{"id":"m1000","text":"قيل لكريم أتعد وأنت قادر على الإنجاز ؟ فقال :إن الحاجة إذا لم يتقدمها وعد يرجى، لم يعظم سرورها.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص68"},{"id":"m1001","text":"الإنجاز بعد الوعد، كالطعام بعد الذوق، فليس من فاجأه الطعام، كمن يجد ريحه وطعمه ثم ينال منه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص68"},{"id":"m1002","text":"دع الحاجة تختمر بالوعد، ليكون لها طعم عند الممنوح.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص68"},{"id":"m1003","text":"لطف الله بالمخلوقات، سبق الآباء والأمهات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص68"},{"id":"m1004","text":"من كثر حياؤه كثر أحباؤه، ومن قل حياؤه قل أحباؤه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص68"},{"id":"m1005","text":"البشر ولين الكلام أيسر مبذول، لاكتساب الأصدقاء، والوقاية من الأعداء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص68"},{"id":"m1006","text":"من فتح له باب خير فلينتهزه، فإنه لا يدري متى يغلق عليه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص68"},{"id":"m1007","text":"الكريم يستر معروفه، وينشر معروف غيره.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص68"},{"id":"m1008","text":"لا خير في معروف يعدَّد.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص68"},{"id":"m1009","text":"المن يفسد المعروف، كما يفسد الخلُّ العسل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص68"},{"id":"m1010","text":"الإنسان أسير الإحسان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص68"},{"id":"m1011","text":"الشكر أبقى للنعم، والكفر يزيلها.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص68"},{"id":"m1012","text":"المحراث مفتاح خزائن الأرض.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص68"},{"id":"m1013","text":"انتظار الفرج من الله بالصبر عبادة.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص68"},{"id":"m1014","text":"من رضي من الله بالقليل من الرزق، رضي الله منه بالقليل من العمل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص68"},{"id":"m1015","text":"قد يعصي العبد خالقه ليدرك الغنى، ويهرب من الفقر، ولا ينعكس.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص68"},{"id":"m1016","text":"يعصى الله لطلب الغنى، ولا يعصى لطلب الفقر.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص68"},{"id":"m1017","text":"من جمع الفضول حسابه يطول.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص68"},{"id":"m1018","text":"إن المكروه يسهل بالتمرين.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص68"},{"id":"m1019","text":"من أراد الله به خيرا، جعل شهوته منقادة له.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص68"},{"id":"m1020","text":"من لم يرد الله به خيرا جعله منقادا لشهوته.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص68"},{"id":"m1021","text":"إذا أراد الله أن يرذل عبده سلط عليه شهوة البطن والفرج.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص68"},{"id":"m1022","text":"لن يفلح من كان همه في شهوة بطنه وفرجه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص68"},{"id":"m1023","text":"المال آلة للمكارم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص68"},{"id":"m1024","text":"نعم العون على المجد اليسار.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص68"},{"id":"m1025","text":"المال يكسب صاحبه الهيبة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص68"},{"id":"m1026","text":"الفقر مخذلة، والغنى مجذلة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص68"},{"id":"m1027","text":"من أحسن الظن بربه أراح قلبه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص68"},{"id":"m1028","text":"الرجاء حسن الظن، والقنوط إساءة الظن.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص68"},{"id":"m1029","text":"قتل القنوط صاحبه.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص68"},{"id":"m1030","text":"الدنيا إن بقيت لك، لا تبقى لها.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص68"},{"id":"m1031","text":"من حسن عزاء الورثة، كثرة ما خلف لهم ميتهم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص68"},{"id":"m1032","text":"الغنى البخيل كالقوي الجبان.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص68"},{"id":"m1033","text":"كف بصرك عن عورات الناس، ولسانك عن عيوبهم، فإن لك فيها شغلا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص68"},{"id":"m1034","text":"القناعة عز المعسر، والصدقة حرز الموسر.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص70"},{"id":"m1035","text":"القناعة حلية الفقر، والشكر حلية الغنى.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص70"},{"id":"m1036","text":"من رضي بالكفاف تزين بالعفاف.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص70"},{"id":"m1037","text":"من رضي برزقه قرَّت عينه، وطابت نفسه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص70"},{"id":"m1038","text":"خير الرزق ما كان فوق الإقتار، ودون الإبطار.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص70"},{"id":"m1039","text":"الأدب مكتسب، ولكل قوم مواضعة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص70"},{"id":"m1040","text":"قيل لحكيم : من أدبك ؟ فقال ما أدبني أحد، ولكني رأيت في الناس خصالا حميدة فحاكيتها، وخصالا رذيلة فجانبتها.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص70"},{"id":"m1041","text":"من أدب أبناءه، فقد أدب أحفاده.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص70"},{"id":"m1042","text":"الأدب أدبان : تأديب الوالدين لأولادهم في الصغر، ثم تأديب الأولاد لأنفسهم في الكبر.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص70"},{"id":"m1043","text":"أثني على أحفاد حكيم في أدبهم وأخلاقهم، فقال : أنا أدبتهم وعلمتهم، فقيل له : كيف وأنت لم تساكنهم وتخالطهم، فقال : أنا أدبت آباءهم، وآباؤهم أدبوهم، فكأني أدبتهم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص70"},{"id":"m1044","text":"الأدب يورث.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص70"},{"id":"m1045","text":"بادروا بتأديب الأطفال، فطينتهم لينة، سريعة القبول.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص70"},{"id":"m1046","text":"تداركوا تعليم الأطفال قبل تراكم الأشغال.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص70"},{"id":"m1047","text":"اتهم نفسك، ولا تجعلها موضع ثقة منك، إذا زينت لك وطوعت.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص70"},{"id":"m1048","text":"احترز من نفسك، كما تحترز من عدوك، فهي أعدى أعدائك.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص70"},{"id":"m1049","text":"كيف يسلم الإنسان من عدو بين ضلوعه ؟.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص70"},{"id":"m1050","text":"( نعوذ بالله من شرور أنفسنا، ومن سيئات أعمالنا ) رقية الاحتراز من غوائل النفس.","kind":"hikma","topic":"الإيمان والعبادة","note":"دعاء","source":"شذرات المطوع، ص70"},{"id":"m1051","text":"من رضي عن نفسه كثر الساخطون عليه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص70"},{"id":"m1052","text":"الشديد من غلب نفسه، والقوي من غلب هواه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص70"},{"id":"m1053","text":"لا تغتر بثناء من يجهل سرك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص70"},{"id":"m1054","text":"من أشرك أو تكبر فقد حجب نفسه عن رحمة الله تعالى.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص70"},{"id":"m1055","text":"من أطاع الله تعالى فقد استقبل الجنة، ومن عصى الله فقد استدبرها.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص70"},{"id":"m1056","text":"لا يغرك ثناء من يخفى عليه سرك، عمن لا يخفى عليه سرك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص70"},{"id":"m1057","text":"قال حكيم : فلان أدب أولاد أولاده بعد رحيله، قيل له : كيف ذلك ؟ قال : هو أدب أولاده، وأولاده أدبوا أولادهم، فكأنه هو الذي أدبهم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص70"},{"id":"m1058","text":"ينشأ الكبر من الشعور برفعة المنزلة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص70"},{"id":"m1059","text":"ينشأ العجب من الشعور بالأفضلية.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص70"},{"id":"m1060","text":"الكبر يكسب المقت، والعجب يكسب الاحتقار.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص70"},{"id":"m1061","text":"أصلح نفسك لنفسك يكن الناس أتباعا لك.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص72"},{"id":"m1062","text":"أفضل الملوك من أبقى بالعدل ذكره، واستعمله الناس بعده.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1063","text":"من غلب نفسه غلب غيره ومن غلبته نفسه غلبه غيره.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص72"},{"id":"m1064","text":"كن من مباح الشهوات بين منع وتمكين، لتضبط شهوتك، وتنال لذتك.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص72"},{"id":"m1065","text":"من قوي على نفسه عظمت قوته ومن صبر على شهوته عظمت مروءته.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص72"},{"id":"m1066","text":"الإستئثار يدعو إلى البغضة، والمواساة تدعو إلى المحبة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص72"},{"id":"m1067","text":"ما أحببت أن توصف به فأته، وما كرهت أن توصف به فاجتنبه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص72"},{"id":"m1068","text":"عدل الوالي يعدل خصب الزمان.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1069","text":"من ستر زلته، حفظ هيبته، ومن عرفت زلته نقصت هيبته.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص72"},{"id":"m1070","text":"الدين يصلح سرائر القلوب، ويمنع من ارتكاب الذنوب، ويبعث على العدل والتناصف، ويدعو إلى الألفة والتعاطف.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص72"},{"id":"m1071","text":"أي بلد كثرت ثماره ومزارعه، استقل بخيره، وفاض على غيره، فصارت الأموال إليه تجلب، والأقوات منه تطلب.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص72"},{"id":"m1072","text":"أطوار الدولة : تبدأ بقوة وبطش لحمل الناس على الطاعة والانقياد، ثم تتوسط باللين والاستقامة، لاستقرار الأمر واستتباب الأمن، ثم تختم بإنتشار الجور والضعف والاضمحلال.","kind":"hikma","topic":"السياسة والقيادة","note":"في الأصل «واستباب»","source":"شذرات المطوع، ص72"},{"id":"m1073","text":"من عمر بيت المال من ظلم رعيته، كمن طين سطحه من قواعد بيته.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1074","text":"أحسنوا إلى المزارعين، فإنكم لا تزالون سمانا ما سمنوا.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1075","text":"سعادة الرعية في طاعة الوزراء، وسعادة الوزراء في طاعة الملك، وسعادة الملك في طاعة ملك الملوك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1076","text":"الجند أعداء ينتقم بهم من أعداء. أي أعداء إن فسدوا، وينتقم بهم من أعداء إذا صلحوا.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1077","text":"قال حكيم لملك : جنودك أعداؤك، وأعداء أعدائك. قال كيف ذلك : قال إن أسأت إليهم وأهملتهم فهم أعداؤك، وإن أحسنت إليهم وراعيتهم فهم أعداء أعدائك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1078","text":"من تنعم بإحسانك، أشفق على سلطانك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1079","text":"المطالب بحقه جرئ، وصاحب الحاجة أرعن.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص72"},{"id":"m1080","text":"لا يكون الظلم علة لوجود الصلاح.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1081","text":"لا يكون العدل علة لوجود الفساد.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1082","text":"لا يستغنى الملك عن الكفاة ولا الكفاة عن الإفضال، ولا الإفضال عن المادة، ولا المادة عن العدل.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1083","text":"من غفلة السلطان، الرضا عمن يستوجب السخط، والسخط على من يستحق الرضا.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص73"},{"id":"m1084","text":"العينان دليلان، والأذنان مخبران، واللسان ترجمان، واليدان آلتا معالجة وعمل، والرجلان آلتا مواصلة وحمل، والعقل آلة كف ولجام، والبطن وعاء الوقود والطاقة، والحواس أجهزة استكشاف وتعرف، والقلب ملك الجوارح.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص73"},{"id":"m1085","text":"من أعتمد على كفاة السوء، فسد رأيه، وكذب ظنه، وطمع فيه عدوه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص74"},{"id":"m1086","text":"التغاضب أحمد مغبة من الغضب، لأن المتغاضب يملك نفسه، ويقف عند الحد المطلوب، والغضبان لا يملك نفسه، ولا يقف عند الحد المطلوب.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص74"},{"id":"m1087","text":"عقوبة الأدب محمودة، وعقوبة الغضب مذمومة.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص74"},{"id":"m1088","text":"بالصبر على المكروهات، تدرك المرغوبات.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص74"},{"id":"m1089","text":"لن تنال ما تحب، حتى تصبر على ما تكره.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص74"},{"id":"m1090","text":"الحوائج تطلب بالعناء، وتدرك بالقضاء.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص74"},{"id":"m1091","text":"يجب على الناصح الاجتهاد ولا يجب عليه ضمان النجح، لأن أقضية الله خافية.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص74"},{"id":"m1092","text":"المستشار مؤتمن وليس بضامن.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص74"},{"id":"m1093","text":"من لام المشير، بقي بلا مشير.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص74"},{"id":"m1094","text":"لو علم الملوك، مقدار حاجتهم إلى أهل الرأي والعلم، لما كان عجبا أن ترى مواكب الملوك على أبواب العلماء.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص74"},{"id":"m1095","text":"الطبيب الذي يرحم عليله من مرارة الدواء، كالأب الذي يرحم ابنه من عناء التعليم، فكلاهما يضر من حيث يرى أنه ينفع.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص74"},{"id":"m1096","text":"الفضائل والأخلاق لها مقادير ومواضع، فإن صادفت مقاديرها وحلت في مواضعها حمدت، وإن لم تصادف مقاديرها أو لم تحل في مواضعها لم تحمد.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص74"},{"id":"m1097","text":"روادع الظلم والاعتداء : • الوازع الديني : التقوى والخوف من الله تعالى، والخوف من العقاب الأخروي. • الوازع الأخلاقي : المحافظة على سمعته، وسمعة عشيرته، وعلى مكانته في المجتمع. • العجز فلا يستطيع أن يظلم، وعدم القدرة من العصمة. • الخوف من العقوبات، وإقامة الحد الشرعي، والخوف من بطش السلطان.","kind":"hikma","topic":"الأخلاق والآداب","note":"في الأصل «وسمعت عشيرته»","source":"شذرات المطوع، ص74"},{"id":"m1098","text":"شرعت العقوبات، والحدود والتعزيرات، للقادر الذي ليس لديه رادع من نفسه، و ليس لديه وازع ديني، ولا وازع أخلاقي.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص74"},{"id":"m1099","text":"عقوبة الأدب أحمد عاقبة من عقوبة الغضب.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص74"},{"id":"m1100","text":"تعطيل الحدود، وإهمال العقوبات، يثير المفسدين، ويجرئ المجرمين.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص74"},{"id":"m1101","text":"الرأفة لا تحمد، إذا أفضت إلى ترك الحدود، وإضاعة الحقوق.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص76"},{"id":"m1102","text":"الحزم : أن تحذر المكروه الذي يمكن حدوثه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص76"},{"id":"m1103","text":"العجز : أن تأمن المكروه الذي يمكن حدوثه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص76"},{"id":"m1104","text":"تجاوز الحد نقص في المحدود. مثال : الكرم إذا جاوز حده صار إسرافا، فيصير نقصا في صفة الكرم.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص76"},{"id":"m1105","text":"من عادة الملوك أن لا تعد ولا تتوعد، لأنها قادرة على ثواب المحسن، وعلى عقاب المسئ في الحال.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص76"},{"id":"m1106","text":"الملوك تستغني بالفعل عن القول، وإذا قالت فإنما هي تأمر بتنجيز الفعل فمآل أقوالها أفعال حاضرة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص76"},{"id":"m1107","text":"الخيرة في ترك الطيرة.","kind":"mathal","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص76"},{"id":"m1108","text":"من أصلح نفسه أرغم أنف عدوه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1109","text":"أصلح نفسك لنفسك، تكن متبوعا.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1110","text":"إذا كان الزهد يضعف صاحبه، عن الطاعات وإتيان القربات، كان الزهد في الزهد هو الزهد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص76"},{"id":"m1111","text":"إذا كان الزهد يضعف عن فعل الطاعات أو يؤدي إلى الرياء، كان ترك الزهد هو الزهد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص76"},{"id":"m1112","text":"الزهد يمنع من المباح، والحمية تمنع من الطيب، والحياء يمنع من القبيح.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص76"},{"id":"m1113","text":"الإفراط في الأكل، يؤدي إلى البطنة، والبطنة داعية للسقم والكسل.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1114","text":"نعم الدواء الوقاية.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1115","text":"نعم الدواء تقدير نسب الغذاء.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1116","text":"نعمت الحمية الاقتصاد في الأكل.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1117","text":"إطعام الطعام حلية المروءة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص76"},{"id":"m1118","text":"موائد الكرام مقابر العيوب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص76"},{"id":"m1119","text":"ما رأيت أستر للعيوب، من إطعام البطون، وملء الجيوب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص76"},{"id":"m1120","text":"رب أكلة أضرت بالآكل، وحرمته أطيب المآكل.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1121","text":"يكفيك من الطعام ما ملأ ثلث بطنك.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1122","text":"من أكل بثلث بطنه، أمن البطنة والكسل، ومن أمن من البطنة والكسل، لازمته الصحة والعمل.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1123","text":"اتق لبستين : المشهورة، والمحقورة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص76"},{"id":"m1124","text":"ليس العزة في حسن البزة.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص76"},{"id":"m1125","text":"جنبوا ثيابكم العري الفادح، والزي الفاضح.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص76"},{"id":"m1126","text":"البس من الثياب ما يخدمك، لا ما يستخدمك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص76"},{"id":"m1127","text":"البس من الثياب ما يقيك لا ما تقيه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص76"},{"id":"m1128","text":"نومة الصبحة معجزة منفخة مكسلة، مورمة مفشلة منساة للحاجة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1129","text":"قليل الرقاد يعين على تحقيق المراد.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص76"},{"id":"m1130","text":"الليل أجمع للفكر، وأخطر للخاطر.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص76"},{"id":"m1131","text":"من كثر اعتباره، قل عثاره.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص76"},{"id":"m1132","text":"طوبى لمن تأمل في أفعال غيره، فاقتدى بأحسنها، وتجنب سيئها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص76"},{"id":"m1133","text":"نفسك مطيتك فأرفق بها، ولا تتعبها ، حتى تبلغك غايتك.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1134","text":"ربما كان حكم الإنسان على غيره، أصوب من حكمه على نفسه، لأن حكمه على نفسه لا ينفك من هوى النفس، ومن حسن الظن بها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص76"},{"id":"m1135","text":"طلب ما لا يدرك عجز.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص76"},{"id":"m1136","text":"إذا هممت بأمر ففكر في عاقبته، فإن كان رشدا فأمضه، وإن كان غيا فانته عنه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص76"},{"id":"m1137","text":"لا تجاهر الناس بالمخالفة فيعادوك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص78"},{"id":"m1138","text":"من عرف عيوبه، فلا يلم من عابه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص78"},{"id":"m1139","text":"من أعمل جده بلغ أمنيته.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص78"},{"id":"m1140","text":"كفى بما يعتذر منه تهمة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص78"},{"id":"m1141","text":"شفيع المذنب إقراره، وتوبته اعتذاره.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص78"},{"id":"m1142","text":"من لم يقبل توبة من أساء، فقد أساء .","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص78"},{"id":"m1143","text":"عفو الكريم أوسع من ضيق المعذرة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص78"},{"id":"m1144","text":"من كانت أغلب خصاله الحدة، فلا تغتر منه بالمودة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص78"},{"id":"m1145","text":"المحسن على المسئ أمير.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص78"},{"id":"m1146","text":"الكف عن الإساءة إحدى التوبتين، والإقلاع عن الباطل أحد العذرين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص78"},{"id":"m1147","text":"وقوف المرض أحد البرءين، وكفه عن الزيادة إحدى الصحتين.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص78"},{"id":"m1148","text":"من سقم منه عضو من أعضاءه، فإن لم يعالجه، سرى السقم إلى الأعضاء الصحيحة وإن عالجه سرت الصحة إلى العضو السقيم.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص78"},{"id":"m1149","text":"من سل سيف البغي كان غمده.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص78"},{"id":"m1150","text":"تسامحوا في الحقوق، فإن الاستيفاء موحش، والاستقصاء منفر.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص78"},{"id":"m1151","text":"جبلت النفوس على مقت من شاحها وشاقها، وعلى حب من ياسرها وسامحها.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص78"},{"id":"m1152","text":"أولى الأمور بالشرف والمروءة، استعطاف النفوس بالمياسرة والمسامحة، وتألفها بالمقاربة والمساهلة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص78"},{"id":"m1153","text":"عبدي حرك يديك ورجليك، أكسو بدنك، وأطعم شفتيك.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص78"},{"id":"m1154","text":"من عاشر الناس بالمسامحة، أمن شرهم، ونال ودهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص78"},{"id":"m1155","text":"من المروءة التغابن للضعيف.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص78"},{"id":"m1156","text":"إذا كان البائع ضعيفا، دع الاستقصاء في السوم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص78"},{"id":"m1157","text":"الآداب ميراث الأشراف.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص78"},{"id":"m1158","text":"إذا أراد الحاكم أن تطاوعه الرعية على شيء من الحق، فعليه أن يبسط لهم شيئا من الدنيا.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص78"},{"id":"m1159","text":"إذا أردت أن تطاع في إخوانك وتحترم، فاسلك بهم طريق الجود والكرم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص78"},{"id":"m1160","text":"إن الله تعالى أحسن إلى الناس قبل أن يأمرهم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص78"},{"id":"m1161","text":"صونوا أحسابكم بأموالكم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص78"},{"id":"m1162","text":"ذبوا بأموالكم عن أحسابكم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص78"},{"id":"m1163","text":"منزلة المال من العرض، منزلة الخادم من المخدوم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص80"},{"id":"m1164","text":"اقطع لسان الشاعر بالمال.","kind":"mathal","topic":"المال والاقتصاد","source":"شذرات المطوع، ص80"},{"id":"m1165","text":"بر الشاعر من بر الوالدين، حتى لا يتعرض لهما بسوء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص80"},{"id":"m1166","text":"من صنف كتابا أو عمل ديوانا، فقد استهدف، فإن أحسن فقد استعطف، وان أساء فقد استقذف.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص80"},{"id":"m1167","text":"من استعان بأصاغر رجال، على أكابر أعمال، فقد ضيع العمل، وأوقع الخلل.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص80"},{"id":"m1168","text":"بالمعالجة يصلح الفاسد، وبالإهمال يفسد الصالح.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص80"},{"id":"m1169","text":"عذل يكفك عن سوء، خير لك من ثناء يجعلك تتمادى في السوء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص80"},{"id":"m1170","text":"من ملك نفسه عند الشهوات والشبهات والهفوات، فقد حاز شطر المروءة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص80"},{"id":"m1171","text":"الحصر خير من الهذر، لأن الحصر يضعف الحجة والهذر يتلف المهجة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1172","text":"فوائد الصمت : يكسبك صفو المحبة، ويؤمنك سوء المغبة، ويلبسك ثوب الوقار، ويكفيك مؤونة الاعتذار.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1173","text":"قال حكيم : ندمت على الكلام، ولم أندم على السكوت.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1174","text":"كلام المرء يعبر عن عقله.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1175","text":"الأصل في الإنسان الصمت، والكلام عارض للحاجة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1176","text":"الكلام بالقصد والمعالجة، والسمع بلا معالجة، وقد يحصل بلا قصد.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1177","text":"كلام الرجل رسول عقله، ووافد أدبه.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1178","text":"من كثر كلامه، ظهر خلله، وبان زلله، إلا أن يكون ملهما مفوها.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1179","text":"الصمت نوم، والكلام يقظة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1180","text":"ما أشبه الجاهل الصامت بالحكيم الساكت.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1181","text":"من رام الإكثار، لم يأمن العثار.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1182","text":"من لم يكن كلامه حكما فهو لغو.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1183","text":"ومن لم يكن سكوته تفكرا فهو سهو.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1184","text":"ومن لم يكن تفكره اعتبارا فهو لهو.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص80"},{"id":"m1185","text":"من تكلم ورام الإكثار لم يأمن الإضجار.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1186","text":"كثرة الأيمان من قلة الإيمان.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1187","text":"دع ما يسبق إلى القلوب إنكاره، وإن كان عندك اعتذاره.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص80"},{"id":"m1188","text":"أعظم الخطايا اللسان الكذوب.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1189","text":"يجب مراعاة التناسب بين المعاني والمباني وطريق الأداء.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1190","text":"في الوعد والترغيب يراعى عذوبة الكلام، ولين الصوت.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1191","text":"في الوعيد والترهيب يراعى غلظة الكلام، وجهارة الصوت.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1192","text":"لا توعد على ذنب بأكثر من عقوبته، لأنك إن فعلت أثمت، وإن تركت كذبت.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1193","text":"إذا غضب الرجل ذهب شطر عقله، فلا يأمن من الزلل.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص80"},{"id":"m1194","text":"من لم يقبل التوبة، فهو أحوج إلى التوبة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص80"},{"id":"m1195","text":"إن أردت السعادة وراحة البال، فلا تقف عند كل مقال، ولا تجعل من كل موقف نزاع، ولا تُمعن النظر في زلّات من حولك، ولا تكشف ما سُتر، ولا تفتح ما أُقفل، ولا تُفتّش عن النوايا، ولا تُرهق نفسك بتفاصيل لا تنفع، خذ من الناس ظاهر خيرهم، ودع خفاياهم لربهم، وسِرْ في الحياة مطمئنَّ القلب، واسع البال، قليل النقد والتعليق والمقال، لين العريكة سهل الطبيعة والطريقة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1196","text":"الرحمةُ والتواضعُ والكلمةُ الطيبةُ، زادُ القلوبِ الطاهرة، وأجملُ ما يتركهُ الإنسانُ في أرواحِ الآخرين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1197","text":"اقتراحُ الشيءِ على الكمالِ شيء سهلٌ، لكنَّ إيجاده على ذلك صعبٌ، فالتمنّي صفاءُ النَّفس، وأمّا نيلُ المُتمنّى فهو صفاءُ العَقل مع الجِدِّ، إذ بين الحُلمِ والبلوغِ مسافةُ جِدٍّ، لا يقطعُها إلا من جمعَ نُورَ الرؤيةِ إلى صبرِ السعي.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1198","text":"الوقاية خير من العلاج والاحتياط خير من الألم والندم والعياط.","kind":"hikma","topic":"الصحة والنفس","note":"قالها تعقيبًا على حديثي تغطية الإناء وإيكاء السقاء","source":"شذرات (ملف وورد)"},{"id":"m1199","text":"‏التدقيقُ في كلِّ صغيرةٍ وكبيرة، والمحاسبةُ على النقيرِ والقطمير، والمقاصّةُ في كلِّ موقفٍ وكلمة، تُفسدُ صفوَ العِشرة، وتُبدِّدُ وُدَّ الأزواجِ والأصحاب. فالسكوتُ أحمدُ عاقبة، والتغافُلُ عقلُ الحكماءِ، يُطفِئُ نارَ الشرِّ، ويُبقي على نورِ المودَّة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1200","text":"اجماع العلماء حجة قاطعة، واختلافهم رحمة واسعة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1201","text":"قليلُ الخبرةِ يسقطُ في الحفرة وقليلُ الحيلةِ حبالهُ قصيرة وقليلُ البصيرةِ تضلُّهُ المسيرة وقليلُ التدبيرِ يسقطُ في البير قليل الهمة لا يبلغ القمة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1202","text":"العلم نور والجهل ظلمات","kind":"mathal","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1203","text":"بالعلم ترقى الأمم وبالأخلاق تبلغ القِمم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1204","text":"أركان الشكر: شكر القلب: بتصور النعمة من الله. شكر اللسان: بالثناء والحمد على الله. شكر الجوارح: ألا يستعملها في معصية الله. وهذه كلها تجتمع بقول (الحمد لله)","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1205","text":"الحرية الإيجابية تاجٌ على الرؤوس، لا يُقدَّر بثمن ولا يُشترى بذهب، بها يُشرق الوجه وتزدهر الحياة. فإذا أُسرت الأرواح خلف القضبان، ضاقت الأرض بما رحبت، وغدت القيود حدودًا وسدودًا، تكسر الإرادة وتُطفئ الشعلة. الحرية حياة ونشاط، والسجن موتٌ بطيء، فمن عاش بلا حرية فكأنما عاش بلا نفس ولا وجود.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1206","text":"منهجُ القرآن دقيقُ البناء، بديعُ الأسلوب، يجمع بين التحفيز والترهيب في توازنٍ لا يختلّ؛ فهو يحفزك على عمل الصالحات لتكون من أهل الجنات، ويرسم لك طريق الرحمة والرضوان، ويُزجرك عن المعاصي والسيئات صيانةً لك من العذاب والهوان، فمنهجه قائمٌ على الترغيب والترهيب؛ ترغيبٍ يفتح أبواب الأمل، وترهيبٍ يغلق سُبل الزلل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1207","text":"إذا ابتُليت بجار السوء، فادعُ الله له في سجودك: ( اللهم أسعده وأبعده، اللهم أدخله الجنة )","kind":"hikma","topic":"العلاقات والناس","note":"تعقيب على حديث الشاكي من جاره","source":"شذرات (ملف وورد)"},{"id":"m1208","text":"نبي الله يوسف عليه السلام، لم يتعجل الخروج من السجن، وإن فُتحت له الأبواب، حتى يُعلن للناس براءته أولًا، فيخرج طاهر السيرة نقي السريرة، أراد أن يغادر القيدَ مرفوع الرأس والهامة، لا مطأطأه، وأن يخرج بعزّ الحق لا بعفو السلطان، ليبقى مثالًا لمن آثر الكرامة على العجلة، والبراءة على الحرية الناقصة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1209","text":"الصغير بالقرآن كبير","kind":"hikma","topic":"الإيمان والعبادة","note":"تعقيب على قصة عمرو بن سلمة في إمامته قومه صغيرًا","source":"شذرات (ملف وورد)"},{"id":"m1210","text":"ما خاب من استخار ولا ندم من استشار ولا ضَلَّ من سأل ولا جهل من تعلم ولا زاغ في الظلماء من شاور الحكماء ولا عَلِقَ في الطين من سأل المجربين ولا ضاع في الصحراء من عرف نجوم السماء.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1211","text":"وهكذا كثير من الناس، يرفضون الفكرة لا لخطئها، بل لأن قائلها بلا لقب بارز مشهور، ولو جاءت الفكرة الخاطئة من مشهور لقبلها، بدون تفكير ولا تدبر.","kind":"hikma","topic":"العقل والحكمة","note":"تعقيب على قصة الأعرابي والحمل","source":"شذرات (ملف وورد)"},{"id":"m1212","text":"إذا أردت أن يختفي العيب والشيب، ويكون العدو صديقا، والبعيد قريبا، فأخرج ما في المحفظة والجيب، فتجلب الثناء في المحافل والحضور والغيب.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1213","text":"لا تُصَدِّقِ المَدْحَ لِحَلاوَتِهِ، ولا تُكَذِّبِ القَدْحَ لِمَرارَتِهِ، ولكنِ اجتهِدْ لِتَكونَ أَهْلًا لِلمَدْحِ، وتَنْفِيَ عنكَ أَسْبابَ القَدْحِ، فخيرُ الثناءِ ما صدّقه العملُ.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1214","text":"اطْلُبْ مَحَبَّةَ الناسِ بالإحسانِ إِلَيْهِم، وتَوْقيرَهُم باحترامِهِم، وثناءَهُم بإكرامِهِم، فالكلمةُ الطيبةُ صدقةٌ، وأَسْرَعُ طريقٍ إلى القلوبِ حُسْنُ الخُلُقِ.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1215","text":"ما تَتَمَنّى عِندَ حُضُورِ أَجَلِكَ لو أَنَّكَ فَعَلْتَهُ، فافعَلْهُ الآن، وما تَتَمَنّى لو أَنَّكَ أَقْلَعْتَ عنهُ، فاقْلَعْ عنهُ الآن، فالعُمْرُ ظلٌّ زائل، والسعيدُ من تابَ قبلَ الفواتِ.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1216","text":"إن الله ضمن للطيور أرزاقها، فوهب لها الأجنحة وحاسة الشم والبصر، كي تهتدي إلي أرزاقها، وغدوها ورواحها أنفع لها ولصحتها، من أن يرزقها في أعشاشها، لأنه سيؤول بها إلى العجز والخمول والوهن، فمن وهب الطير الجناحين، فقد أمره قدرا بالغدو والرواح، ليسعى على نفسه وفراخه، وهكذا تسير عجلة الحياة، وفق الحكمة الإلهية.","kind":"hikma","topic":"الإيمان والعبادة","note":"تحت عنوان: تعرف على حكمة الله من مخلوقاته","source":"شذرات (ملف وورد)"},{"id":"m1217","text":"المعنى واحد، لكن الأسلوب والصياغة تصنع الفارق البين، في التعبير ووقع الكلام على نفس ومشاعر السامع.","kind":"hikma","topic":"الكلام والصمت","note":"عبرة قصة الملك ومعبّرَي الرؤيا","source":"شذرات (ملف وورد)"},{"id":"m1218","text":"لا تعتمدوا على الوتساب في اقتراح العلاجات والوصفات، فالوتسابُ يُحاول أن يُقتعك في توصيف العلاجات والتوصيات، لكنه رديءٌ في تشخيص الحالات والتوقعات؛ يُجيد النصح من بعيد، ويُخفق عند الاختبار والنتائج غالبا، فاحذروا وصفات الوتساب، ولا تبادروا في تطبيقها.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1219","text":"لا تُرِي زوجك اللحمَة النيَّة، ولا الزبدةَ الطريَّة","kind":"mathal","topic":"الحياة الزوجية","note":"فإنهما بعد الطبخ ينكمشان، فيظنّ بك ظنَّ السوء، ويحسبُ أنكِ أرسلتِ بعضَهما إلى أمكِ أو أُختك.","source":"شذرات (ملف وورد)"},{"id":"m1220","text":"شينُة النساء زينُة الرُمَّان","kind":"mathal","topic":"العقل والحكمة","note":"أي إن تشقّقَ قدمِ المرأةِ عيبٌ يُذم، وتشققَ قشرِ الرمانِ حُسنٌ يُحمَد.","source":"شذرات (ملف وورد)"},{"id":"m1221","text":"الدنيا غنيمة الأكياس الفطنون، وغفلة الجهال السادرون، لم يعرفوها حتى أُخرجوا منها، فسألوا الله الرجعة فلم يُرجعوا، فخسروا أنفسهم، وذلك هو الخسران المبين.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1222","text":"رسالتي لكل من تصدّر للدعوة إلى الإسلام: اجعل خُلقك قبل حُجّتك، وأدبك قبل منطقك، ولينك قبل برهانك. أَشعِر من تُحاور أنك تُريد له الخير لا الغلبة، واهدأ في دعوتك؛ فمَن وُلِدَ على معتقدٍ ونشأ عليه لا يُغيِّره الجدال بسهولة، بل يُليّنه الحِلم، ويهديه الصدق، ويجذبه حُسن الخلق، إذا بدأت بها، ودمت عليها، مع النقاش الهادئ، والبرهان الساطع.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1223","text":"زلةُ قدمٍ يتبعُها ندم، وزلةُ لسانٍ تَجرُّ نَدماً أشدَّ وألزم، فلا تُبادرْ بالقناعةِ لما تسمعُ من رأي، حتى تسمعَ من يُعارِضُهُ في الفِكرِ والمَسعى. فبالاختلافِ يتبيَّنُ الصواب، وبتصادمِ الحُجَجِ يَنجَلي الضباب، ومن سمعَ وجهًا واحدًا، رأى نصفَ الحقيقة، ومن سمعَ الوجهين، أبصرَ الحكمةَ على وجه الصواب والحقيقة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1224","text":"لا تَكرهي زوجك لتقصيره وعيوبه، واصبري واحتسبي، ولا تَكره زوجتك لتقصيراتها وعيوبها، فاصبر واحتسب، فما من بشرٍ إلا وفيه نقص، والمعروض من النوعين غالبًا غير كاملٍ ولا مُرضي، فمن رضي عاش هانئًا، ومن دقّق تعب، ومن صبرَ ظفر، ومن شكرَ استبشر.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1225","text":"احترموا كبيركم، واعطفوا على صغيركم، ووقروا عالمكم، وأطيعوا أميركم، وأنعشوا فقيركم، وأشفقوا على يتيمكم، وصِلوا أرحامكم، ولا تحتقروا غريبكم وضعيفكم، وحافظوا على أخلاق دينكم، تكسبوا رضا ربكم، ومحبة الناس وأهلكم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1226","text":"العالِم مُبصر ولو كان أعمى، والجاهل أعمى ولو كان مبصرا، فأعينوا أولادكم على طلب العلم، فما ضاع من مالك ما أنفقته على تعليم عيالك.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1227","text":"من أراد كنوزَ الحكمة، فعليه بالقرآن، فهو نبعُها الصافي، ومعدنُها الوافي. ومن أراد كنوزَ العلم، فعليه بالقرآن، فهو بحرٌ لا يُدرك له شاطئ، ولا يُنزف له معين. ومن أراد كنوزَ مكارمِ الأخلاق، فعليه بالقرآن، ففيه تزكو النفوس، وتتهذّب القلوب، وتسمو الأرواح. ومن أراد كنوزَ معرفةِ أبوابِ الخير، فعليه بالقرآن، فهو الدليلُ الهادي، والنورُ البادي، والطريقُ إلى رضوانِ ربِّ العالمين. ومن أراد كثرة الحسنات، بقدر حبات رمال الصحراء، وقطرات ماء السماء، فعليه بالقرآن، فإن له بكل حرف حسنة، والحسنة بعشر أمثالها. فمن أقبل عليه فُتِحت له الأبواب، ومن أعرض عنه، حُجِب عن الأنوار والأسرار،","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1228","text":"من أعاجيب الإنسان المدهشة! وغفلته الموحشة، يبذل جهده، ويسخّر ما أنعم الله به عليه لتزيين دنياه الفانية وزخرفتها، ويغفل كلية عن آخرته الباقية، فيبالغ هنا ويقصّر هناك، كمن يُجيد ويتفنن في تزيين وتجميل فندقه الذي سيمكث فيه يومين فقط، ويُهمل بيته الذي سيقيم فيه عمره كلّه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1229","text":"التجارة في الدنيا لا تخلو من مخاطر وكساد، ومن خسارةٍ أو غشٍّ أو احتيال. أمّا التجارة مع الله، فهي تجارةٌ لا تبور، مضمونةُ الأرباح، مأمونةُ العواقب، محفوظةٌ من السوس واللصوص، ومن الحوادث والكوارث والوارث. لا تحتاج إلى مستودعات ولا تأمينات، ولا حراساتٍ ولا إجراءات. بل يكفي فيها نيةٌ صادقة، ويدٌ منفقة، وقلبٌ مُخلِص. وفوق هذا وذاك، أرباحها مضاعفةٌ مضمونة، تُخزَّن في ميزانٍ لا يضيع، وتُؤتى أحوجَ ما يكون العبدُ إليها، يوم تُوزن الأعمال، وتُقرّر الأحوال. فأكثروا من الصدقات والوقفيات والمشاريع الخيرية، فطوبى، ثم طوبى، لمن تاجر مع الله، وبذل الأموال في سبيل رضاه، ويلقى الثواب يوم يلقاه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1230","text":"كنت مطأطئ الرأس أراقب نملةً تمضي في طريقها، فتعلمت منها أن العمل أبلغ من القول، وأن النظام سرّ النجاح، وأن الصمت أهيب من الضجيج بما أُنجز. ومن يومها، أيقنت أن من تعلّم من النملة، علّمته كيف يكون عظيمًا في صغره، كبيرًا في أثره، وأيقنت أن من تعلم من النملة، وفقه الله في إنجازاته وجمع شمله وأشتاته.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1231","text":"وطنوا أنفسكم على أن تتحملوا من الناس: الجحود والصدود والسدود والبرود، فلا تغيروا عاداتكم الجميلة لتصرفاتهم القبيحة، فلنجعل الفضيلة تنتصر على الرذيلة، والأخلاق الحميدة تدحر الأخلاق القبيحة، فتجملوا بالأخلاق والآداب، قبل أن تتجملوا بالزينة وفاخر الثياب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1232","text":"التلميح يُغني عن التصريح، واللبيب بالإشارة يفهم","kind":"mathal","topic":"الكلام والصمت","note":"ورد في قصة (حرب السفن)","source":"شذرات (ملف وورد)"},{"id":"m1233","text":"حين يتقدّم بك العمر ستندم على قسوتك، حين وجب اللين، وعلى صمتك حين وجب القول، وعلى وقتٍ ضاع بين مالٍ وعمل، وعلى والِدَين وأولاد لم تنعم بقربهم، وعلى خيرٍ أخّرته حتى فات، ياليت الزمان يعود يوما، لأتدارك ما فاتني دوما.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1234","text":"الوتساب كسوق الجمعة؛ يزدحمُ فيه الغثُّ والسَّمين، فيه الزهرة تعبقُ بالعطر، وفيه البعرة تفوحُ بالنتن، تجول فيه الإشاعاتُ والوهم، كما تجولُ فيه الحقائقُ والبَيِّنات، فلا تُصدِّقْ كلَّ ما يُعرَض عليك، ولكن الزم ميزانَ العقل واليقين، ولا تنطقْ إلا صدقًا، ولا تنشرْ إلا خيرًا، صونًا للعرض والدين، فالكلمة سَهم، إن خرجَت من فمك لم تعُد إليك، فاحذر أن تُصيبَ بها بريئًا أو تُشعلَ بها فتنةً، وتحسبونه هينا وهو عند الله عظيمة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1235","text":"فلا تُبادر بالاتفاق حتى تضيق الآفاق","kind":"hikma","topic":"العقل والحكمة","note":"خلاصة قصة من خرج من عيادة الطب النفسي","source":"شذرات (ملف وورد)"},{"id":"m1236","text":"من أولويات الحكومات أن تراعي مصالح شعوبها، وعند تعارض مصلحة العامة مع الخاصة تُرجح مصلحة العامة، مع الاهتمام بمصلحة الخاصة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1237","text":"وفي الفتاوى الشرعية عند تساوي الحكمين، يُرجح التيسر على الورع، لأنه أوفق لطبيعة التشريع، وللضعف البشري، ولأن الورع للخاصة والتيسير للعامة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1238","text":"رُبَّ رجلٍ يعدل ألفَ رجل","kind":"mathal","topic":"العلاقات والناس","note":"قالها في د. عبدالرحمن السميط رحمه الله","source":"شذرات (ملف وورد)"},{"id":"m1239","text":"النظافة من الإيمان، والقذارة من إهمال الإنسان الكسلان، وتثبيط الشيطان.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1240","text":"الندرة أصل الاقتصاد، فكل ما ندر غلا، وكل ما كثر رخص.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1241","text":"العرض والطلب ميزان السوق، يرفع الأسعار أو يخفضها.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1242","text":"الوقت رأس مال خفي، من ضيّعه خسر أرباحه دون أن يشعر.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1243","text":"المال إذا لم يُستثمر تآكل، فالجمود عدو القيمة.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1244","text":"الادخار وقاية، والاستثمار نماء.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1245","text":"المخاطرة بقدر الخبرة تُثمر، وبقدر الجهل تُفقر.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1246","text":"الثقة رأس مال معنوي، إذا فُقد انهارت التجارة.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1247","text":"الاحتكار يفسد السوق، والمنافسة تنعشه.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1248","text":"الاستهلاك بلا وعي يُولّد الفقر، والإنتاج الواعي يُنبت الثراء.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1249","text":"لا تُنفق كل ما تملك، ولا تُقرض من لا تثق.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1250","text":"الربح العاجل قد يُنسي الخسارة الآجلة.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1251","text":"من راقب ميزانيته ملك قراره.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1252","text":"الاقتصاد في المعيشة نصف الغنى.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1253","text":"الديون سلاح ذو حدين: ترفع حين تُحسن إدارتها، وتُسقط حين تُهمل.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1254","text":"الاستقرار المالي ثمرة الانضباط لا الصدفة.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1255","text":"الثروة ليست لمن جمعها، بل لمن أنفقها في مرضاة الله تعالى، فصانها من السوس واللصوص، والحاسد المنحوس، والحرق والغرق، والحوادث والكوارث.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1256","text":"الوتساب ليس قناة إخبارية، أو محطة رياضية، أو نشرة صحية، أوجامعة علمية، فالتكرار غالبا يُولد الملل والنَّفَار، الوتساب سوق أو مجمع تجاري أو جمعية، فيه العطور والذهب، وفيه الفحم والحطب، وفيه الخوخ والرمان وفبه البصل والباذنجان، فالوتساب لجميع الآراء والأحباب، باللين والحب والآداب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1257","text":"في القرونِ الأولى، كان الهمُّ الأكبرُ ترسيخَ أركان الإيمان، وتهذيبَ النفس بفقه العبادات والمعاملات، وصقلَ أخلاقِ الإنسان. أمّا في عصرنا، فقد انصرف كثيرٌ من الخلق إلى فقهِ الشراب والطعام، وإلى ملاذِّ الأجسام ومتاعِ الأنام، حتى صار ما يُشبِع البطون مقدّمًا على ما يُحيي القلوب والعقول. فيا لها من مفارقةٍ تُنبّه، وحقيقةٍ تُؤسّف، وتذكيرٍ بأنّ الدين أولى وأعلى، وأنّ العاقل من أقام ميزانَه بين غذاء الروح وغذاء البدن؛ فلكلٍّ قدرُه، ولكلٍّ مقامُه.","kind":"hikma","topic":"الإيمان والعبادة","note":"تحت عنوان: فقه الطعام وفقه الإسلام","source":"شذرات (ملف وورد)"},{"id":"m1258","text":"إن لم تستطع أن تجود على الناس بمالك، فجد علىهم بكلامك، فاجعل على عَذْبَة لسانك لُعاب النحل، وكن لين العريكة، سهل الطريقة، سمح الطبيعة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1259","text":"إذا تعاون أعضاء القروب، فبشرهم بتآلف القلوب، ووضوح الدروب، ورفع الكروب، وحلول السلام بدل الجدال والحروب، وبدل النزاع والمكروه، يحل الحب والمحبوب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1260","text":"ليست العلّة في عدم زيادة الرواتب فحسب، بل في موجة الأسعار التي تواكب الزيادة، فترتفع كلما ارتفعت الرواتب، تغذّيها شهيةُ التجار وجشعُهم. فالمواطن هو الجسر التى تمر عليه زيادة الرواتب، لتنهال في جيوب التجار الجشعين. فإذا اجتمع ضعف الدخل مع جشع السوق، ضاق العيش على أهله، فلا نجاة إلا بحكمةٍ في النفقة، ورقابةٍ تُلجم الطمع، واقتصادٍ يكبح سَعَارَ الارتفاع.","kind":"hikma","topic":"المال والاقتصاد","note":"بعنوان: زيادة الرواتب","source":"شذرات (ملف وورد)"},{"id":"m1261","text":"لم يبق من العمر كثر ما فات، فلا متسع للعتابات، شبنا فاخترنا الحكمة والسكينة، وقللنا اللوم والملاحظات، وهجرنا كثرة التفاصيل والانتقادات، واستبدلناها بالتسامح وقلة الموآخذات، إبقاء على حسن العلاقات والمودات، وصفاء النفوس من الفضائل والمكرمات، وهي دماء تجري في عروق أهل المروآت، والتوفيق يُطلب ويُدرك من رب الأرض والسماوات، وكل داء له دواء إلا الهرم والحماقات.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1262","text":"بعضُ أزماتِ المجتمع إنما تُولدُ حين نجاوز هديَ الإسلام، بينما دواؤها مبثوثٌ في شرعه المستقيم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1263","text":"القرآنُ نزلَ في الحجاز، وقُرئ في مِصرَ بالتجويد والإعجاز، وحُمِل في الصدور، وسار في الأمصار، وطُبِّق في القرون الأولى، بلا تقصيرٍ ولا انحياز، فصار هدايةً لكل العصور، يُبدد الظلام وينشر النور.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1264","text":"كان الشعر في الجاهلية له نور يسطع، وسطوة تُخضع، وسلطان يُخيف ويُقنع، فلما نزل القرآن، خَبَا نوره، وخَفَت ضياؤه، وزالت شوكته وسطوته، وذابت منزلته وهيبته، وانحنى أمام نورٍ أعظم، وبيانٍ أبلغ، ووحيٍ أبهى ضياءً وسناءً، فانحنى له الشعراء، وخضع له الأدباء، وأقرت له العلماء، في التفوق والعلياء، فالقرآن العظيم كنز العلوم والمعارف، والأسرار والأخبار، تفوق البحار والأنهار، في الوفرة والكثرة، فهو مفتاح العلوم، وكنز الأخبار والأسرار، لا تنقضي عجائبه على مَرِّ العصور وتتابع الدهور، ولا يخلق على كثرة الرد والتكرار، في الليل النهار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1265","text":"زكاة نعم الله الكثيرة، الجود على الفقير والفقيرة. زكاة قوة الأبدان، مساعدة الضعفاء من بني الإنسان. زكاة علوم الدين، تعليم الناس والطالبين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1266","text":"الرقابةُ الشعبيّةُ على أداء الحكومة، أو على طائفةٍ من الناس، إذا جاءت في وقتهاومحلها، وبأسلوبٍ رفيعٍ يخلو من التجريح تصريحًا وتلميحًا، ومن الإسفاف والاستخفاف والإلحاف؛ كانت رقابةً راشدةً تُصلح ولا تفضح، وتُقَوِّم ولا تُهَدِّم. فهي رقابةٌ إيجابيّةٌ ذاتُ أثرٍ نافع، تعصم مسيرةَ الدولة من التمادي في السلبيات، والانجرار إلى المخالفات. وما أحوج الأمم إلى صوتٍ ناصحٍ يحمل الحق بأدب، والصدقَ بميزان، وبأسلوب راقٍ في التوضيح والبيان.","kind":"hikma","topic":"السياسة والقيادة","note":"بعنوان: الرقابة الشعبية","source":"شذرات (ملف وورد)"},{"id":"m1267","text":"الحرب قتال بين طائفتين من الشباب، يقتل بعضهم بعضا، ولا يعرف بعضهم بعضا، بأوامر فريقين من الشيوخ، يعرف بعضهم بعضا، ولا يقتل بعضهم بعضا.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1268","text":"الرئاسة مشغلة ومسؤولية، وهموم وتقييد حرية، وإكراه لمجاوزة القانون، والمحاباة والحيف، لصالح أقربائك وأصدقائك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1269","text":"بعض التجار مثل الآلة الحاسبة، ما عندها ضمير، ولجمع المال كل شيء يصير.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1270","text":"النفوسُ تُقبِل وتُدبِر؛ فإذا أقبلت فاغتنموها بالصالحات والوقفيات والتبرعات، وإذا أدبرت فأمسكوها على الفرائض والواجبات؛ فبها النجاة، وعند الله عظيم الثواب والهبات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1271","text":"لو ربَّى الناسُ أبناءهم جميعًا على القيادة، فمن يُقاد؟ ولو طلبوا لأنفسهم ذروةَ التعليم، فمن ينهض بأعمال الحفر والبناء، والهدم والكشط، والنظافة وتسليك المجاري، وسائر المهن الشاقة والخطرة؟ إن سنّة الله في خلقه التنوعُ والتكاملُ؛ فلا تستقيم الحياةُ إلا بالغني والفقير، والعالم والمتعلّم، والرئيس والمرؤوس… يقوم بعضُهم بحاجات بعض، ويُكمل بعضُهم بعضًا، في نسقٍ محكم، وحكمةِ عليمٍ خبيرٍ رؤوفٍ رحيم.","kind":"hikma","topic":"العقل والحكمة","note":"بعنوان: حكمة الله في التنوع","source":"شذرات (ملف وورد)"},{"id":"m1272","text":"هؤلاء القُصّاص لا تُؤخَذ عنهم معالمُ الدين؛ غيرُ مُؤتمنين، يخلطون الواهي بالصحيح، ويرون المخترَع الذي لا أصل له، ويُلبِسون على الناس بأحاديثَ ضعيفةٍ تُعَكِّر صفوَ اليقين وصريحَ الشرع، وما كان هكذا فلا يُستقى منه، ولا يُعوَّل عليه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1273","text":"أفضل هدية تقدمها إلى أهلك، وأنت قادم من السفر، هي صحتك وسلامتك","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1274","text":"لا تفعل ما لا تريده، ولا تريد ما لا غاية له، ولا تكون الغاية صائبة إذا صدرتَ عن عاطفة جياشة تُعميك عن تبعات القرار. فحرّر نفسك أولًا من اندفاع الهوى المُضلل، والحماس الطائش، ثم انظر بعقلك فيما سيؤول إليه اختيارك، من سلبيات وإيجابيات، واحتطْ لتجنّب أسوأ الظنون، ليصدر فعلُك عن بصيرة لا عن جزاف، وحماس أهوج أعور أعرج.","kind":"hikma","topic":"العقل والحكمة","note":"بعنوان: اتخاذ القرار","source":"شذرات (ملف وورد)"},{"id":"m1275","text":"الحياة هي المدرسة الكبرى، فمسيرة الحياة مليئة بالتجارب، فيها الصواب وفيها الخطأ، والصواب ابن الخطأ، ونتيجة التجارب لا تُخطئ، ودلالتها يقينية، فاطلب العلم النظري من علمائه، واطلب العلم العملي والصناعي والتجريبي من علمائه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1276","text":"ما أروع وأبدع منشورات الصالحين، وتغريدات العلماء والحكماء والملهمين، في وسائل التواصل الاجتماعي وغيرها، هذا يذكرك بآية، وآخر بحديث، وثالث يهديك فائدة، ورابع ينصحك ويرشدك، وهلم جرَّا. فبدونهم لا طعم للمواقع ولا فائدة من المنشورات،","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1277","text":"لا تجعل كل اهتماماتك في جمع الثروة، وتنمية الأموال، وتصريف البضاعات، ولكن اجعل بعض اهتماماتك في دينك وآخرتك وعبادتك، لتربح الدارين، وتكسب الحياتين.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1278","text":"لا تفرح كثيرا بالأموال الهائلة، التي تأتيك من طرق مشبوهة، ومن طريق الغش والسحت والإختلاس والحرام، فإن عاقبة الحرام وخيمة، واحذر المحق الخفي، فحبل الحرام قصير، وحسابه طويل.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1279","text":"النقاشُ والتلقينُ ركنان في بناءِ العلم؛ فالنقاشُ يفتحُ الآفاق، ويوقظ العقول، والتلقينُ يُؤسِّسُ الأصول، ويُثبِّتُ المعلومةَ في محلّها. وكثيرٌ من الناس يُهوِّنون شأنَ التلقين، وهم لا يعلمون أنّه الجذرُ الذي يسبقُ الثمر، وأنّ النقاشَ بلا أصلٍ كغصنٍ بغير جذر، وأنّ العقولَ لا تُشرق إلا إذا اجتمع لها غرسٌ راسخ وفهمٌ نافذ وسؤالٌ مُستنير. والتلقين يسبق النقاش، وبالأخص في تربية الصغار، ومع غير العالم، وفي من هو خالي الذهن عن الموضوع. هكذا يكتمل نور المعرفة، ويبدو العلمُ في أحسن صوره.","kind":"hikma","topic":"العلم والثقافة","note":"بعنوان: النقاش والتلقين","source":"شذرات (ملف وورد)"},{"id":"m1281","text":"البلدان المتحاربان كلاهما خاسر؛ يخسران الرجال والمال، ويغرقان في التدمير بدل التعمير، فتتعطل مسيرة التقدم والعمران. ومن يُعدّ رابحًا فيهما، إنما ربحه نقصان خسارته، لا تمام نصره. ولو رَجعا إلى التفاهم، وقَبِلا بشيءٍ من التنازل، لجنّبا أنفسهما الخسران، وحفظا للأمة أمنها وعمرانها وسلامتها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1282","text":"إن عجزتم أن تردوا الجميل بالأجمل أو بالجميل، فردوه بالشكر والدعاء والثناء الجزيل، والفضل للمبتدي ولو أجاد المقتدي.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1283","text":"موتُ الأبِ سقوطُ عمودِ خيمةِ الأبناء، وانهيارُ صرحِ البناء، وتصدّعُ جدرانِ الفناء، وتنحلُّ عُرى ترابطِ الأُسرة، ويزدادُ الحزنُ والحسرة، ويغيبُ الحِمى، ويضعف الإخاء، ويتسعُ جُرحُ الرجاء، تخفتُ الملامح، وتبهتُ الصور، وتضيقُ في العيونِ السماء، فالأبُ ليس رجلاً فحسب، بل هو أُنسُ الحياةِ وثوبُ الدفءَ والهناء، ومهد الأرض وظل السماء. فعلي الاولاد أن يتواصلوا ويتعاونوا ويتفاهموا ويتسامحوا.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1284","text":"نصائح وضوابط المعاملة مع رئيسك في العمل: نفذ أوامره التي تلزمك في العمل. احترمه دون تزلّف. بادر قبل أن يَطلب منك. كن صادقًا لا مداهنًا. لا تنقل إليه ولا تُنِمّ. اجعل همَّك العمل، لا مجرد نيل الرضا. افعل ما يجعله يثق بحسن تصرفك وامانتك. وفي المقابل سوف يتعاون معك، ويثق بك، ويقدمك في الترشيحات والمميزات التي في صالحك، لأنك تستحق ذلك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1285","text":"المحافظة على الرياضةِ قوّةٌ في الأبدان، ونشاطٌ في الأركان والأذهان. وتقليلُ الطعامِ صفاءٌ للأذهان، وتخلّصٌ من الدهون، وجمالٌ للأبدان.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1286","text":"لا يَحسُن بالآمر بالمعروف والناهي عن المنكر أن يُكرِه الناس على اجتهاده، أو يُلزمهم بمذهبه، فإنما وظيفته أن يُبيّن الحق بدليله، ويُرشد برفقه ولينه، ويُغيّر ما أُجمِع على إنكاره، أو ثبت بالنص تحريمه وإحداثه، أمّا المختلف فيه فمجاله السعة، وميدانه العذر، ومقامه الرحمة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1287","text":"لو اجتمع جملٌ من فجر الإنسانيّة بجملٍ من عصرنا، لما رأيتَ بينهما كبير اختلاف؛ فطبعه واحد، وصبره واحد، وقوّته واحدة، وقدرته على احتمال القحط لم تتبدّل، فيألف أحدُهما الآخر سريعًا. ذلك لأن الله خصّ الإنسان بتعليم الأسماء، فجعلها أصل المعرفة، ومفتاح التفكير، وسرّ التطوّر والتراكم الحضاري، أمّا الحيوان فهدايته غريزيّة محدودة، لا تنمو ولا تتجاوز حدّها، ليبقى مسخَّرًا للإنسان، لا مزاحمًا له في العقل ولا منافسًا في البناء. وهذا من عظيم فضل الله على الإنسان، الذي فضله الله علي كثير من خلقه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1288","text":"القول إن حفظ القرآن لا يتم إلا في ظلّ المشكلات، قول غير دقيق؛ فالحفظ في الصغر أيسر وأرسخ، مع خلو القلب من الهمّ، وصفاء الذهن، وقوة الذاكرة. أما الكبار، فالمشكلات قد تحرّكهم، لكنها لا تُعينهم، بل تشتتهم وتُضعف قدرتهم على التركيز. فالحفظ لا يُربط بالمحن، بل بالعزيمة والانضباط. وكل مرحلة عمرية صالحة، متى وُجدت الهمّة، وصحّ القصد، والصغر أفضل مرحلة للحفظ.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1289","text":"فالصغير أصغر عقلا لكنه أقل شغلا، والكبير أكبر عقلا لكنه أكثر شغلا.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1290","text":"كن عظيمًا ودودًا، قبل أن تكون عِظامًا ودودًا. كن كريمًا وجوادًا، قبل أن تصير رُفاتًا وجمادًا. كن حيًّا شاهدا، قبل أن تصير ميتًا غائبًا.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1291","text":"لا تجعل أُذُنَك قِمْعاً تُبادر بقبول الكلام، من غير ان تتحقق وتتيقن، من سؤال شايبين أصلعين عالمين متخصِّصَين.","kind":"hikma","topic":"الكلام والصمت","note":"القِمْع: ما يُصَبُّ فيه السوائل.","source":"شذرات (ملف وورد)"},{"id":"m1292","text":"دموع النساء أقوي من عضلات الرجال الأقوياء، لأن تأثير العضلات على الأبدان، وتأثير الدموع على الجَنَان.","kind":"hikma","topic":"العلاقات والناس","note":"الجَنَان: القلب.","source":"شذرات (ملف وورد)"},{"id":"m1293","text":"كفرانُ العشيرِ: ثمرةُ لحظةٍ غلبت فيها العاطفةُ الذاكرة؛ فيغيب تاريخُ الإحسان بزلةٍ حاضرة، ويُقاس العمرُ بالموقف الحاضر، فإذا ثقلت التوقّعات واشتدّ الضغط، ضاق ميزانُ العدل، فرُئي النقصُ وغاب الفضل، والعلاجُ تذكيرُ العقل بما نسيه الشعور.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1294","text":"تَسْعد النفوس بالخروج إلى البرّ الواسع لأسبابٍ: سعة البر تُوسّع الصدر وتخفّف الكدر. جمال الطبيعة يُهدّئ النفس ويذهب ضغوط الحياة. البساطة والفطرة تجلب التوازن والطمأنينة. الابتعاد عن الضجيج يستدعي التأمّل والسكينة. اجتماع الأصدقاء يزيد في الأُنس والمودّة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1295","text":"الطبيعة خَلْقُ الله قبل آدم، وآيةُ التوحيد قبل الرسل؛ تشهد للخالق ذاتًا وصفاتٍ، ويُحال إليها في القرآن دعوةً للإيمان. فهي أولُ داعيةٍ إلى الله، وآخرُ من يطوي عروش الملوك وقصورهم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1296","text":"ما استُعمل قوي، وما أُهمل ضَعُف. والاعتدال هو سرّ السلامة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1297","text":"لكل طريق طويل لوكيشن فلوكيشن الجنة السُّنَّة فمن ضيع السُّنَّة فقد أخطأ طريق الجنة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1298","text":"يكثر الغش في المدن أكثر من القرى؛ لأن القرى تضبطها السمعة، والمدن تحكمها المصلحة. ففي القرى تردعك العيون، وفي المدن تُغريك الظنون؛ هناك تُعرف فتُحاسَب، وهنا تُجهل فتُغرَى. فإذا غابت الرقابة وضعف الضمير، استشرى الغش واستوطن الخداع والتحايل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1299","text":"من خالفَ السُّننَ الكونيّة، والقواعدَ الصحيّةَ البدنيّة، وأراد أن يُنقِصَ وزنَه بسرعة؛ فقد أخطأ الطريق، وخالف الحكمة. فما بناهُ الجسدُ على مَهَلٍ، لا يُهدمُ في عَجَل، وما تراكمَ في سنين، لا يزولُ في أسابيع. ومن طلبَ النتائجَ بلا مُقدِّمات، حصدَ العواقبَ بلا سلامة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1300","text":"الصوابُ ابنُ الخطأ، والتجاربُ مُعلِّمٌ لا يُخطئ، والحِكمةُ بنتُ الصبر، والعجلةُ أختُ الندامة. والتغييرُ الحقيقيُّ ليس قفزةً عابرة، بل مسيرةٌ ثابتة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1301","text":"البَعرةُ تدلُّ على البعير، والأثرُ يدلُّ على المسير، فسماءٌ ذاتُ أبراج، وأرضٌ ذاتُ فِجاج، وبحارٌ ذاتُ أمواج؛ ألا تدلُّ على اللطيفِ الخبير؟","kind":"mathal","topic":"الإيمان والعبادة","note":"قالته العرب في أوضح براهين العقل","source":"شذرات (ملف وورد)"},{"id":"m1302","text":"فالعقلُ لا يَخلقُ الإيمان، لكنه يدلُّ عليه، ولا يُنشئُ الهداية، لكنه يُرشدُ إليها، ولا يستغني عن الوحي، ولا يستغني الوحيُ عن عقلٍ يفهمه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1303","text":"السياسةُ وجهان: مُعلَنٌ للناس، وخفيٌّ يُدار خلف الأستار، وعودُها تُقال، وأسرارُها تُكتم، وما يُظهَر فيها جسورٌ لما يُبطَن، ورسائلُ تُفهَم بقدر ما يُراد لها. تُحاك في الغرف المظلمة، وتُنفَّذ في الساحات المعلَنة، ويخالطها المكرُ طلبًا للغَلَبة والمطامع، والله أعلم بما فيها من الكبد والفظائع.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1304","text":"عند طلب الحقوق، ابدأ باللين والرجاء، واطرق الباب بالأدب والحياء، فإن لم يُفتح، فأَعِد الطرق بالإلحاح والمساءلة، فإن أُغلق في وجهك، فاصدع بالمحاججة، واطلبه بالضجيج والجعجعة، فبعض الحقوق لا تُهدى، بل تُنتزع بالمخاشنة بعد المحاولة والملاينة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1305","text":"السياسة الحكيمة شطر النصر.","kind":"hikma","topic":"السياسة والقيادة","note":"عبرةٌ ختم بها حديثه عن فتح عمرو بن العاص مصر","source":"شذرات (ملف وورد)"},{"id":"m1306","text":"فقه العقول قبل قوة العضلات.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1307","text":"فما أُخذ بالحيلة والحكمة، لم يُحتج فيه إلى القتال وسفك الدماء.","kind":"hikma","topic":"السياسة والقيادة","note":"من تعليقه على فتح مكة","source":"شذرات (ملف وورد)"},{"id":"m1308","text":"إيّاكَ والمبالغةَ في الأعشاب للصحة والعلاج ولو في الجرجير؛ فإنّ الاعتدالَ في كلّ شيءٍ هو منهجُ الحكيمِ والبصير، وبه تُحفَظُ الصحّةُ وتَسْلَمُ المعدة والمصير.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1309","text":"الأصلُ أنَّ الرجلَ راعٍ مُوجِّه، والمرأةَ متلقِّية، لذا خوطب الرجالُ بقوله تعالى: {فَعِظُوهُنَّ}. فإذا وقع النشوزُ أو الخطأُ بدأ بالوعظِ قبلَ غيره؛ إذ الحكمةُ أن يبدأ بالأخفِّ قبلَ الأشدِّ، وباللينِ قبلَ الحزمِ، وبالنصحِ قبلَ العتابِ؛ فذلك أرجى للقبولِ، وأليقُ بأمانةِ القِوامة.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1310","text":"جيل العقاد والرافعي كان التنافس في الثقافة والقلم والجيل الذي بعدهم أصبح التنافس في الكرة والقدم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1311","text":"لا تقترض لتبدأ مشروعًا. اقترض فقط لتكبير مشروع ناجح.","kind":"hikma","topic":"المال والاقتصاد","note":"من «قواعد اقتصادية»","source":"شذرات (ملف وورد)"},{"id":"m1312","text":"إن لم يربح المشروع وهو صغير، فلن يربح وهو كبير.","kind":"hikma","topic":"المال والاقتصاد","note":"من «قواعد اقتصادية»","source":"شذرات (ملف وورد)"},{"id":"m1313","text":"احسب الربح نقدًا لا على الورق. الربح الذي لا يدخل حسابك وهم.","kind":"hikma","topic":"المال والاقتصاد","note":"من «قواعد اقتصادية»","source":"شذرات (ملف وورد)"},{"id":"m1314","text":"اجعل مصروفاتك أقل من دخلك دائمًا، حتى لا تقع في فخ الديون.","kind":"hikma","topic":"المال والاقتصاد","note":"من «قواعد اقتصادية»","source":"شذرات (ملف وورد)"},{"id":"m1315","text":"ارفع السعر قبل أن تكثر البيع. الكثرة مع هامش ضعيف تُهلكك.","kind":"hikma","topic":"المال والاقتصاد","note":"من «قواعد اقتصادية»","source":"شذرات (ملف وورد)"},{"id":"m1316","text":"احفظ رأس المال قبل أن تبحث عن الربح.","kind":"hikma","topic":"المال والاقتصاد","note":"من «قواعد اقتصادية»","source":"شذرات (ملف وورد)"},{"id":"m1317","text":"لا تدخل تجارة لا تفهمها.","kind":"hikma","topic":"المال والاقتصاد","note":"من «قواعد اقتصادية»","source":"شذرات (ملف وورد)"},{"id":"m1318","text":"لا توسّع حتى تستقر.","kind":"hikma","topic":"المال والاقتصاد","note":"من «قواعد اقتصادية»","source":"شذرات (ملف وورد)"},{"id":"m1319","text":"الدخل الواحد خطر. ابحث عن مصدر ثانٍ ولو صغير.","kind":"hikma","topic":"المال والاقتصاد","note":"من «قواعد اقتصادية»","source":"شذرات (ملف وورد)"},{"id":"m1320","text":"الديون للضرورة لا للرفاهية.","kind":"hikma","topic":"المال والاقتصاد","note":"من «قواعد اقتصادية»","source":"شذرات (ملف وورد)"},{"id":"m1321","text":"غالبا الوتساب يدهشك بالوصفات العلاجية، ويخذلك بالنتائج الصحية.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1322","text":"الطفل يرضع من أُمه سنتين، ويشرب بقية عمره من البقرة سبعين عاما، فالحمد لله على نعمه التي لا تُحصي، وعلى فضائله التي لا تفنى.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1323","text":"كثيرٌ من الأسماء في العربية ليست اعتباطية، بل بين اللفظ ومعناه نَسَبٌ ووشيجة، وهذا من دقائق حكمة هذه اللغة وجمالها.","kind":"hikma","topic":"العلم والثقافة","note":"خلاصة باب موافقة الاسم للمسمّى في العربية","source":"شذرات (ملف وورد)"},{"id":"m1324","text":"لم تُشرَعِ الحُدودُ لتُقام على المستتر، وإنما شُرعت لزجرِ المُجاهر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1325","text":"فالتفاحةُ الفاسدة تُفسِدُ السَّلَّة، والدجاجةُ المريضة تُعدي الحظيرة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1326","text":"لهذا شُرعت الحُدود: وقايةً قبل أن تكون عقوبة، وحمايةً قبل أن تكون إيلامًا، ورحمةً بالمجتمع قبل أن تكون شدّةً على الفرد. فهي لم تُشرَع لِتُكثِر التنفيذ، بل لِتُقلِّل الجريمة؛ إذ إن إقامةَ حدٍّ واحدٍ أبلغُ في الردع من ألف موعظة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1327","text":"صانعُ الشيء أدرى بما يُصلحه ويصونه.","kind":"hikma","topic":"العقل والحكمة","note":"قالها عقب قوله تعالى: ﴿أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ اللَّطِيفُ الْخَبِيرُ﴾","source":"شذرات (ملف وورد)"},{"id":"m1328","text":"أفضل صفات المتقاعد: 1.الرِّضا: يقبل مرحلته الجديدة بلا تذمّر ولا تحسّر. 2.القَصْد: يُحسن تدبير وقته وماله بلا إسراف ولا تقتير. 3.النَّشاط: لا يترك نفسه للفراغ والكسل. 4.الحِكمة: يُحوِّل خبرته إلى نُصحٍ وإرشاد. 5.العِفّة: يترفّع عن سؤال الناس والتعلّق بما في أيديهم. 6.التوازن: لا ينعزل ولا يضيع وقته في اللهو. 7.الشُّكر: يرى التقاعد نعمةَ فراغٍ لا نقمةَ فراغ.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1329","text":"اتَّقِ ظنَّ المتقي، فإنَّ الله جعل الحقَّ على لسانه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1330","text":"من عرف الله أحبَّه، ومن عرف الدنيا زهد فيها، ومن عرف الآخرة رغب فيها وعمل لها.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1331","text":"التفكُّر قبل العمل يرفع هيبة البديهة وحيرتها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1332","text":"إذا ناقشنا كل الآراء، لم يَبقَ لنا وقتٌ للعمل.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1333","text":"نحن لا نُحب هذا الذئب، لأنَّ ذئبًا أكل نعجتنا، لاتفاقهما في الطبع؛ فالأول أكلها، والثاني عنده استعدادٌ غريزيٌّ ليفعل مثله.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1334","text":"إذا أغلقتَ عليك بابك، فأنت أميرُ نفسك.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1335","text":"(وصايا الملك لابنه الذي سيخلفه) 1. ابدأ بالعدل وإنصاف المظلومين، فالعدل أساس المُلك. 2.قدِّم الخدمات قبل أن تطلبها، فالسلطة تكليف لا تشريف. 3.قدِّم الأكفأ لا الأقرب. فالدولة تُدار بالقدرات لا بالمودّات. 4.اسمع كثيرًا وتكلّم قليلًا. فكثرة السمع تقلّل الزلل. 5.راقب البطانة قبل الرعيّة، فساد الخاصّة أسرع إلى هدم الدول. 6.احفظ المال العام كما تحفظ مالك، فالخيانة فيه خيانة للأمّة. 7.قدِّم الأمن والعدل على الرخاء والرفاهية، فلا عمران بلا أمن ولا عدل. 8.تأنَّ في القرار، حتي يتبين لك الصواب، ثم اعزم بعده، فالتردّد ضعف، والعجلة ندامة. 9.أمسك بالقوّة، ولا تستخدمها إلا في الحق. فالهيبة بلا ظلم، تجلب لك المحبة والطاعة. 10.اذكر أنك راحل والمُلك باقٍ، فأحسن الأثر يُخلِّد لك الذكر في الدنيا، وتُرفع درجاتك في الآخرة. 11.وأفضل ما يخلد لك الذكر الطيب هو: العمران الكبير الذي يخدم الشعب، وبالأخص الفقراء والضعفاء.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1336","text":"أعظم نعمة بعد الإيمان العافية، والعلاج الطبيعي أفضل من العلاج الكيميائي","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1337","text":"نصيحة فاعليتها صحيحة كوب ماء دافئ على الريق، وآخر قبل النوم: يوقظ الأمعاء، ويُليّن الإخراج، يقاوم الإمساك بلطف وأمان، إن ما نفعك ما ضرك.","kind":"hikma","topic":"الصحة والنفس","note":"فيها المثل: إن ما نفعك ما ضرك","source":"شذرات (ملف وورد)"},{"id":"m1338","text":"آداب المحاورة: المحاورة تقوم على حسن القصد، وصدق القول، واحترام المخالف، وترك المكابرة، وطلب الحق لا الغلبة، واللين وعدم المخاشنة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1339","text":"العقل الصحيح لا يعارض الشرع الصريح؛ لأن مصدرهما واحد، فالله خلق العقل وأنزل الشرع، وإنما الخلل في الفهم لا في الأصل.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1340","text":"التجارة تقوم على الحساب لا على التمنّي، والربح الحقيقي يُصنع عند الشراء لا عند البيع، وحفظُ رأس المال مقدَّم على تنميته، والسيولة روحُ المشروع، ومن لا يُحسن الأرقام يخسر ولو كثرت مبيعاته.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1341","text":"عوامل تقييم الوزير: تحقيق الأهداف، كفاءة الأداء، رضا المواطنين، النزاهة والشفافية، التطوير المستدام، فتح الأبواب لا غلقها، إنصاف المظلوم، والمتابعة الدقيقة لسير العمل.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1342","text":"إذا أردت أن تُقنع غيرك برأيك، فكن صادقًا في قولك، واضحًا في حجّتك، هادئًا في نبرتك، عارفًا بمن تخاطب، مستندًا إلى برهان واضح، ومحركًا للعقل والعاطفة معًا؛ فإن الإقناع لا يكون بالصوت العالي، ولا الحماس المتعالي، بل بالحجة والفطنة، والثقة ووضوح الأسلوب، وبيان الأدلة والدروب.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1343","text":"شبهات حول الوزير: كثرة المقرّبين من أقاربه ومحيطه الخاص، تنامي أرصدته بشكل لافت، غياب المتابعة الدقيقة لسير العمل، التراخي في المحاسبة، وتفضيل الولاء على الكفاءة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1344","text":"قواعد تربية الأطفال المهمة الإيحاء السلوكي: كن كما تحب أن يكونوا، لأنهم يقلدوك، والتقليد باب عظيم من أبواب العلم، ونقل المعارف والعادات واللغة، واللغة وعاء الفكر. الحنان والانضباط: مزيج من الحب والحزم. الاستماع والتفهم: أصغِ لمشاعرهم واحتياجاتهم باهتمام. التشجيع لا التوبيخ: امدح السلوك الجيد بدل التركيز على السلوك السيئ. الوضوح والثبات: ضع قواعد وضوابط واضحة وثابتة وميسرة. التعليم باللعب والتسلية: التعلم الممتع أخف وأرسخ. الاحترام المتبادل: عامله باحترام ليحترمك ويحترم الناس. تنمية القيم: الدين، الصدق، الأمانة، التعاطف رويدا رويدا، لطرد السآمة. تحفيز الاستقلالية: علّمه الاعتماد على الله ثم على نفسه، مع الاستعانة بالخبير الناصح. الدعاء: ورافق كل هذا بدعاء صادق. الإستمرار على كل ما تقدم ليصبح عادة له، فيخف عليه الإلتزام الدائم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1345","text":"إذا أردت أن ينشأ أطفالك أذكياء، فاحكِ لهم قصصًا قصيرة، بعباراتٍ يسيرة، ومعانٍ مثيرة، تنبض بالحكمة، وتمتلئ بالفطنة، وتزدان بالأخلاق الزكية، والمواقف الذكية، تُغذي عقولهم، وتُنمي معارفهم، وتُشعل خيالهم، وتُقوّي لغتهم، وترتقي بذوقهم، وتصقل شخصياتهم السوية، لتغدو قويةً نقيّةً فتية.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1346","text":"نصائح للمبتدئ بقيادة السيارة تأنَّ قبل التحرك، وركّز عند المفترق، ولا تُسرع عند الزحام، ولا تتردد عند اللزوم، اجعل المرايات عيونك، والإشارات إرادتك، والحذر رفيقك، ويدك على المِقود لا على الهاتف، والزم اليمين إلا للعبور، فسلامتك وسلامة الناس في اتباع الإرشادات ويقظة الحواس، وأفضل هدية تُقدمها إلى أهلك، أن ترجع إليهم سالما.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1347","text":"اقتراحُ الكمالِ يسيرٌ على اللسان، وتحقيقُه عسيرٌ في الميدان، فالكلام لا يُكلفُ جهدا ومالاً، أما الفِعال فتحتاجُ عَزماً ومالا ورجالاً، فليس كلُّ من أشار أجاد، ولا كلُّ من تمنى أنجز وأفاد.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1348","text":"في أول لقاء للمخطوبة، كن خفيف الظل، لطيف القول، بعيدًا عن التكلّف والجدال، وابدأ بالسلام، وعرّف بنفسك باحترام. تحدّث عن القيم والهوايات، لا عن المكاسب والماديات، واسأل عن الطموحات لا عن العقارات والبنايات، واختر من الكلام أعذبه، ومن السؤال ألطفه. واجعل الابتسامة عنوانك، والصدق ميزانك، وحسبك من المديح تلميح بلا تصريح، وأظهر جميل الطباع، فأول لقاء يصنع أقوى انطباع.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1349","text":"ميزان ردود الأفعال: يقاوم الإنسان ردود أفعاله القوية، سواء أإيجابية أم سلبية، عبر ثلاث وسائل جوهرية: 1.الوعي الذاتي: أن يُدرك مشاعره فور نشوئها، ويميز بين ما هو طبيعي وما هو مفرط. فالإدراك أول خطوة للتحكم. 2.ضبط النفس: بالتريث قبل الاستجابة، والتنفس العميق، وذكر الله في النفس، لكبح التسرع والانفعال. 3.إعادة التقييم العقلي: بأن يُعيد تفسير الموقف، فلا يبالغ في الفرح، ولا يُستفز بالحزن أو الغضب، بل يُوازن بين العاطفة والعقل. فالسيطرة لا تعني كبت المشاعر، بل توجيهها بطريقة ناضجة ومناسبة للمقام.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1350","text":"أثر الأذان في النفس والناس الأذانُ يُحيي القلوب بعد غفلة، ويُطمئن الأرواح بعد وحشة، ويبعث في النفس الطمأنينة، ويجعل للوقت بركة وسكينة. هو نداءُ التوحيد والوحدة، وسِرُّ الاجتماع والألفة، به تجتمع الأمة، وتتوحد الكلمة، وتعمّ البركة والرحمة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1351","text":"تقوية الإيمان: أن تجالس وتصاحب من هم أقوى منك إيمانا، وأكثر منك خشوعا، وأوسع منك علما وفقها. فالصاحب ساحب، والرفيق من يسايرك في طريق الحياة، بالرفق والنصح والتوفيق، والمرء يُحشر مع خليله، فلينظر أحدكم من يُخالل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1352","text":"الأذانُ صوتُ السماء، ودعوةُ الصفاء، وفيه إعلان التوحيد، وبثُّ روحِ التجديد. يُرهبُ الشيطان، ويرضي الرحمان، ويُنعشُ الإيمان، وينبه الغفلان، ويربطُ الأرضَ بالسماء، والعبدَ بحب الربّ دون عناء. المؤذِّنُ لسانُ الإسلام، وجنديُّ السلام، أجرُه عظيم، وذِكره كريم. فهو نداءُ الفلاح، وسراجُ الأرواح، يُصلح النفس، ويجمع الناس، ويجعل في المجتمع نورًا وانسجامًا. ويوحد القلوب والأرواح، ويشرح الصدور ويجلب الخشوع والفلاح.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1353","text":"أن النصر مع الصبر، وأن الأخذ بالأسباب لا ينافي التوكل، وأن الغاية النبيلة تستحق التضحية، وأن قلوب المؤمنين تتلاقى على نصرة الحق، ولو تباعدت الأوطان والأعراق.","kind":"hikma","topic":"الإيمان والعبادة","note":"من عِبر الهجرة النبوية","source":"شذرات (ملف وورد)"},{"id":"m1354","text":"مِلْءُ الوِعاء الفاضي أيسر من مِلْءِ الوعاء المَلْيان، كذلك اقناع الذهن الخالي أيسر من اقناع الذهن المَلْيان بالشبهات والضلالات والسفاهات، لأن الثاني يحتاج أولا إلى ابطال الشبهات والضلالات، ثم اقتاعه بالحقائق والمسلمات.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1355","text":"من بالغ في التدقيق حُرِم التوفيق، تغافل تُسْعَد، وتجاوز تُحَب، فليس كل فعل يُفسَّر، ولا كل قول يُحاسَب، ولا كل زلّة تُعاتب، أجمل الرد: الصمت، وأكمل العقل: الحِلم والعفو، فمحبة الناس كنز عظيم فلا تزهد فيه، ولا تفرط فيه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1356","text":"البيوت تُبني على مكارم الأخلاق، ومحاسن العادات، وجمال الطباع، وحلاوة اللسان، وسخاء الأيدي، والتسامح والتغافل، والتجاوز والعفو، وغض الطرف.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1357","text":"الأبُ عزٌّ لا يُجارى، وسندٌ لا يُبارى، هو نورُ الدار، ودرعُ الأخطار، رضاهُ فوز، ودعاؤه لأولاده مستجاب، وكلامه لأبنائه نصح وصواب، وصمته وقار وهيبة لأهل الدار، ولكل ابن مطيع بار.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1358","text":"الأم مهبط الرحمات، ومعراج الدعوات، وموطن البركات، ومصدر السعادات، دعاؤها يصعد إلى السماء، ويُرفع به البلاء، ويُستجلب به الرزق والشفاء، رضاها فلاح، وخدمتها نجاح، وقربها جنّات، وبُعدها حسرات وندامات.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1359","text":"لا تُصغِ لكل مُرجف، ولا تقبل كل شائعة، فالأراجيف كثيرة، فلا تأخذ إلا ما جاءك من جهةٍ موثوقة مسؤولة، وإذا أتاك اليقين فعض عليه بالنواجذ، ودع عنك قول المُهوّلين والمشعوذين.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1360","text":"الاعتماد على الله ثم على النفس، هي البداية الصحيحة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1361","text":"أداء الواجب له الصدارة في التقديم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1362","text":"القناعة شطر السعادة، والشطر الثاني تحقيق الأهداف.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1364","text":"من لا يُجَرِّب لا يُخطئ، ومن لا يُخطئ لا يتعلم، ومن لا يتعلم يتخلف عن ركب الحضارة، ومن يتخلف عن ركب الحضارة، يجد نفسه معزولا وحيدا فريدا شريدا.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1365","text":"يكسب الموظف تقدير رئيسه له بحسن سلوكه وتصرفاته من خلال: الصدق والإخلاص في العمل. الاحترام والأدب في التعامل. المبادرة وتحمل المسؤولية. الهدوء والانضباط في المواقف الصعبة. الحرص على التطوير والتعاون بروح الفريق.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1366","text":"من اتقى الله في طلاق زوجته، وهبه الله خيرا منها، ومن لم يتق الله في طلاق زوجته، لم يبدله الله بخير منها.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1367","text":"الزوج المثالي: هو من يتّقي الله في زوجته، كريم الخلق، يحسن عشرتها، ويعطيها حقها، صبورٌ في الشدة، شكورٌ في الرخاء. يُشاورها، ويُقدّرها، ويكون لها أمانًا وحنانًا، يعينها على الطاعة، ويقودها بحكمة لا بقسوة. ويعوضها عن حنان أبويها، وعن العش الذي فيه درجت، والبيت الذي فيه تربت، والحب الذي به تدثرت.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1368","text":"تسعة أشياء بُعْدهم دواء: وَزْنُكَ الزّائِد، أثاثك البائِد، ماؤك الراكد، مالك الكاسد، جارُكَ الحاسِد، قَرِيبُكَ الحاقِد، شريكك المعاند، صديقك الجاحد، ضِرسك الفاسد.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1369","text":"فاذا دعوتم الله فاقرنوا دعاءكم بالصلاح، واشترطوا الفلاح.","kind":"hikma","topic":"الإيمان والعبادة","note":"خلاصة قصة سادن الكعبة","source":"شذرات (ملف وورد)"},{"id":"m1371","text":"يُولد الأطفال مزوّدين بالحواس الخمس: السمع البصر اللمس الذوق الشم، وهي نوافذهم إلى الإدراك، وجسورهم إلى الفهم والمعرفة. فواجب الوالدين أن يُشبِعوا هذه الحواس بما ينفعهم في دينهم ودنياهم، وفي أخلاقهم وآدابهم، وبما يقربهم من الله، ويرفع شأنهم عند الناس.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1372","text":"من أكل أكثر من احتياج جسده، خزن الزائد طاقة في بدنه على هيئة شحم ودهون. ومن أكل أقل من احتياجه، كمَّل احتياجه من مخزون طاقته،الذي هو الشحم والدهون. ومن أكل بقدر احتياجه فقد حافظ على وزنه.","kind":"hikma","topic":"الصحة والنفس","note":"تحت عنوان: فلسفة الريجيم – العلاج بالضد","source":"شذرات (ملف وورد)"},{"id":"m1373","text":"الرأيُ بلا بيِّنةٍ وهمٌ، والحُكمُ بلا حجَّةٍ ظلم.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1374","text":"الظنُّ لا يُغني، والوهمُ لا يَبني.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1375","text":"الحُكمُ على الشكِّ باطل، والرأيُ بلا دليلٍ عاطل.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1376","text":"الخيالُ لا يُقيمُ ميزانًا، ولا يُثبتُ برهانًا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1377","text":"الأوهامُ لا تُثمرُ أحكامًا، ولا تُقيمُ نظامًا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1378","text":"من بنى حُكمَه على الهوى، جارَ في القَضا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1379","text":"العقلُ لا يركنُ إلى الحُلم، والعدلُ لا يميلُ إلى الوهم.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1380","text":"الدليلُ سلطان، والهوى خُذلان.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1381","text":"الأحكام لا تبنى على الأحلام.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1382","text":"أحكام الدين لا تثبت إلا باليقين، واليقين لا يثبت إلا بالدليل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1383","text":"طِبُّ الضدّ: هو علاجُ الشيءِ بضدّه. يعني: تُعالج السُمنة بتقليل الطعام، والهزالَ بتكثيره، والخمولَ بالحركة، والحزنَ بالفرح، والقلقَ بالإيمان والاطمئنان، والكسلَ بالحركة والنشاط. وهو أصلٌ قديم في الطبّ، ومنهجٌ بسيط في تقويم صحة الإنسان، فبطب الأضداد تحقق التوازن بالأجساد، فالصحة والعافية هي أعظم نعمة بعد الإيمان.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1384","text":"الزوجة المثالية: هي من تجمع بين الدين، والعقل، وحسن الخلق، تحفظ زوجها في نفسها وماله، وتكون له سكنًا ورحمة، تؤازره في الشدة، وتشاركه في الرخاء، وتعينه على الطاعة، وتُدخل على قلبه السكينة والسعادة.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1385","text":"تداركُ زلَّةِ الصمت أهون من استدراك زلَّة النُّطق.","kind":"mathal","topic":"الكلام والصمت","note":"مقتبس من وصية علي بن أبي طالب رضي الله عنه لابنه الحسن","source":"شذرات (ملف وورد)"},{"id":"m1386","text":"حِفظ ما في الوعاء بشدِّ الوِكاء.","kind":"mathal","topic":"المال والاقتصاد","note":"مقتبس من وصية علي بن أبي طالب رضي الله عنه لابنه الحسن","source":"شذرات (ملف وورد)"},{"id":"m1387","text":"ما في يدك محفوظ خيرٌ مما في يد غيرك مأمول.","kind":"mathal","topic":"المال والاقتصاد","note":"مقتبس من وصية علي بن أبي طالب رضي الله عنه لابنه الحسن","source":"شذرات (ملف وورد)"},{"id":"m1388","text":"مرارة اليأس أهون من مذلَّة السؤال.","kind":"mathal","topic":"الأخلاق والآداب","note":"مقتبس من وصية علي بن أبي طالب رضي الله عنه لابنه الحسن","source":"شذرات (ملف وورد)"},{"id":"m1390","text":"ما أعظم توفيق الله لعبده أن يمدَّ في عمر والديه، ويهديه لبرِّهما، فتزداد حسناته، ويتضاعف أجره، ويكونان سببًا لتوفيقه في دنياه، ورفعة درجاته في أخراه، ويرزقه الله ذريةً صالحةً تبره وتصله، فبرُّ الوالدين دينٌ مسترد، والسعيد من وفَّقه الله في الدارين: عملًا صالحًا وثوابًا جزيلًا.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1391","text":"رُبَّ كلمة طيبة أغلقت باب عداوة، وفتحت باب صداقة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1392","text":"من حسُنت أخلاقه طابت عشرته.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1393","text":"من كسب الناس بحسن خُلُقه، طوعهم لمحبته.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1394","text":"أثقل ما يُوضع في الميزان بعد الإيمان حسن الخُلُق.","kind":"hikma","topic":"الأخلاق والآداب","note":"في معنى حديث نبوي","source":"شذرات (ملف وورد)"},{"id":"m1395","text":"ما عُبد اللهُ بشيء بعد الإيمان، أحسن من حُسن الخُلق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1396","text":"حسنُ الخلُقِ ستر للفقراء، وزينة للأغنياء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1397","text":"أول لقاء بين المدرس والطلاب: يُعرِّف بنفسه بهدوء وهيبة، ويُوضح أهداف المقرر وأسلوب التدريس. ويضع قواعد الانضباط والتعامل بوضوح، ويزرع الثقة ويُحفز الطلاب على المشاركة، ويبدأ بمعلومة مشوقة أو قصة تجذب الانتباه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1398","text":"الحريةُ الشخصيةُ أن تختار قهوتك أو شايك، مُحلىً أو مُرًّا، ساخنًا أو فاتِرًا، أمّا فرائضُ الدين وثوابتُ اليقين، فامضِ فيها مستقيمًا كما أُمرت، لا ميلَ فيها ولا تبديل لهوى ولا شَطَط ولا تعليل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1399","text":"س:كيف نتعامل مع الأطفال لاكتساب التميز والتفوق؟ ج: بالحب والقدوة. بالتحفيز والسؤال واشراكهم بالقراءة معهم ومناقشتهم. بتوجيه حواسهم إلى الملاحظة والتجربة. بتقوية الفضول وتشجيع الأسئلة. بضبط السلوك باللين والحزم. بتوسيع مداركهم بالقصص والأمثال. وبالدعاء لهم دائمًا بالتوفيق. حبّب إليه العلم، وعلّمه كيف يتعلم. وبالاستهواء السلوكي في العادات الحسنة، والأخلاق الحميدة، والذوق الجميل والأدب النبيل.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1400","text":"إذا استقام القلب، طاب القولُ والفعل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1401","text":"من أصلح ما بينه وبين الله، أصلح اللهُ ما بينه وبين الناس.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1402","text":"لا تركن إلى الأماني، فما حُرثت أرضٌ بالأحلام.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1403","text":"سكوت الحكيم حكمة، وصمت الجاهل حلية.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1404","text":"من خاف اللهَ لم يَخَفْ أحدًا، ومن رجاه لم يَرجُ غيرَه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1405","text":"كُن خفيفَ الظلِّ، طيّبَ القولِ، حسنَ الفعلِ، عميقَ الأثرِ الصالح.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1406","text":"فالأرض لا تأكل ولا تشرب ولا تموت ولا تمرض ولاتشيخ ولا تهرم، لكنها قد تنام طويلًا إن لم تحسن اختيارها، وتعرف مستقبلها.","kind":"hikma","topic":"المال والاقتصاد","note":"من كلامه عن التجارة في الأراضي","source":"شذرات (ملف وورد)"},{"id":"m1407","text":"الصبر مع التحسين يزيد الربح","kind":"hikma","topic":"المال والاقتصاد","note":"خلاصة أنواع تربص الفرص لبيع الأرض بثمن أعلى","source":"شذرات (ملف وورد)"},{"id":"m1408","text":"كنتَ في ريعان شبابك تسابق الأيام (بسأفعل وسوف أفعل) وتغرس الأحلام في حقول الغد، حتى غدوت شيخًا كُنْتِيًّا، لا تطرق باب حديثك إلا بـ(كان) و(كنا)، تسترجع الأمس وتُحصي ما ولّى. فاعلم أنّ الأعمار ظلّ زائل، وأنّ الحلم بلا عملٍ وهمٌ عاطل، فاعمل لدنياك كأنك تعيش أبدًا، واعمل لآخرتك كأنك تموت غدًا، ولا تجعل (سوف) ذريعةً للتسويف، ولا (كان)حسرةً على التفريط.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1409","text":"بعد زواج البنت، وانتقالها لبيت زوجها، يكون مبدأ الشوق، ومهوى الوَلَه، ومطلع اللهفة، ومورد السعادة الغامرة… إذ تعود في الزيارات لتلتقى بأمِّها وأخواتها وعائلتها، في العشِّ الذي فيه ترعرعت، ومنه درجت، وفي زواياه ذكرياتٌ ندية، وأحاديثٌ دافئة، وحنينٌ لا يزول.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1410","text":"الاتجار في المواشي: مالٌ يأكل المال، والاتجار في الطعام: مالٌ يفسد بطول الزمان، وأما الاتجار في الأراضي: فمالٌ لا يأكل المال، ولا يفسده طول الأزمان، بل يزيده بالأثمان.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1411","text":"من يطلب الزرع فعليه أن يحرث الأرض ويرويها بالماء، ومن يطلب الحرية فعليه أن يطلبها بالاجتهاد والعناء.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1412","text":"من لا يتابع الأخبار لا يعلم، ومن يتابعها لا يعرف أين الحقيقة؟","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1413","text":"إذا أردت أن تُقَيِّم إنسانا، فاجعله رئيسا على رأس عمل.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1414","text":"افعل كل ما تستطيع من خير، في كل زمان ومكان، فهذه هي صفة الإنسان المتصف بصفات الإنسانية.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1415","text":"من عمرَ وقتَه بالذكر، عمرَ اللهُ قلبَه بالإيمان والفكر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1416","text":"من طاب أصلُه، طابَ فرعُه، ومن زكا سِرُّه، زكا علنُه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1417","text":"القلوب أوعيةٌ، وألسنةُ الناس مغارفُها، فانظر ماذا تَغْرِف مِمَّا تعرف.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1418","text":"من خافَ اليومَ أَمِنَ الغد، ومن أصلحَ سرَّه أصلحَ اللهُ علانيتَه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1419","text":"إذا ضاقت بك الدنيا والفضاء، فاتَّسِع بالصبرِ والذكر والدعاء.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m1420","text":"من جالسَ الحكماءَ رقَّ قلبُه، ومن صاحبَ الأتقياءَ صفا لُبُّه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1421","text":"واعظُ اللهِ في قلبِ المؤمن إذا تفكر، خيرٌ من ألفِ ناصحٍ بلسانه إذا عَبَّر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1422","text":"كن كالنحلة، فالنحلة تقع على الأزهار، فمنها العسل نشتار ( نجني ) ولا تكن كالذبابة، فالذبابة تقع على الأقذار، فتنشر الوباء والأضرار.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1423","text":"الوقت نفحة من العمر، والعمر أنفسُ من أن يُهدر، فلا تُبدّد دقائقك في همٍّ مقيم، أو حزنٍ عقيم، ولا في سفاسف الأقوال والأفعال، فما مضى منه لا يُشترى، وما بقي رأسُ مال، لا يُقدر بأثمان، واستعن بالله الرحيم الرحمن.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1424","text":"رجلٌ افتتح مطعمًا يلقى رواجًا وإقبالًا، فقال له صديقٌ له: إن عمّالك يسرقونك. فقال: أعلم. قال: فلِمَ لا تستبدلهم؟ قال: أولًا، هم يُرَبِّحونني رغم ما يأخذون، وثانيًا، لا أضمن أن من يأتي بعدهم يكون أصلح منهم، فدعك من هذه المغامرة الفاشلة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1425","text":"الصقور تُعرَف بحدّة بصرها وسرعة انقضاضها، لا بزُخرُف ألوانها ولا ببهاءِ هيئتها. وكلاب الصيد تُمدَح ببأسها وسرعتها وخَطْفها، لا بجمال خِلقتها. والأسود تُهاب بأنيابها ومخالبها، لا بجلودها ولَبَدِها. والرجال تُكرَم بسخائها ومروءتها، وسموّ أخلاقها ونُبل سجاياها، لا بجمال مظهرها وهندامها.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1426","text":"تاجرٌ كبير يملك معرضًا عامرًا بالبضائع الواردة إليه من كل صوب، وله مديرٌ ناصحٌ أمين، بارعٌ في عمله غاية البراعة، يدفع له صاحب المعرض مليون دينار في السنة. فعجب أصحابه من كِبَر الأجرة، فقال لهم: إنه يُكسبني في العام أحد عشر مليونًا وأنا مطمئنٌ مستريح، فأدفع له مليونًا، وأحظى بعشرة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1427","text":"وصية ذهبية لتربية الذرية تُغنيك عن المجلدات التربوية إن نشأ الطفل العربي في بيتٍ صيني تشبَّع بلسانهم وأخلاقهم وعاداتهم، وإن نشأ الصيني في بيت عربي تشبَّع بلسانهم وأخلاقهم وعاداتهم، تلقائيا من غير معاناة ولا تكلف ولاقصد. العبرة: تربية الذرية خُلطَةُ ومعاشرة ومساكنة، ومحاكاةٍ، واقتباسٍ، واستهواءٍ سلوكيّ. النتيجة: تربية الأولاد تبدأ من تربية الوالدين، فإذا كان الوالدان مستقيمين استقام الأولاد، وإذا كانا منحرفين انحرف الأولاد، فأحسنوا تربية أولادكم باستقامتكم وحسن أخلاقكم. فباستقامة الوالدين يَستقيم الأولاد، وبانحرافهما ينحرف الأولاد.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1428","text":"فالتقليد باب كبير وعظيم لنقل المعارف والثقافات بطريق مُعَبَّد ومُيسر.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1429","text":"اجتماع العائلة الأُسبوعي: يُكسب الأبناء مهارات الحوار والإصغاء واحترام الرأي. ينقل القيم والأعراف والعادات الطيبة بين الأجيال. يربطهم بهوية العائلة وأصولها وجذورها، الذي يقوي عوامل التواصل وأواصر القربى، وصلة الرحم. يفتح لهم أبواب الآداب والأخلاق والأعراف والتجارب.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1430","text":"زار صديقَه الذي افتتح محلًا لبيع الأحذية، فوجده يشكو كساد السوق، وفتور البيع. فألقى نظرةً على الأسعار، فإذا هي زهيدة لا تثير في النفس قيمةً ولا رغبة. فقال له: ارفع الأسعار! فلما زاره بعد شهرين، وجده مسرورًا مُبتهجًا، والبضاعة تُصَرَّف. وهنا يتجلى السِّرُّ: فبعض الناس لا يلتفتون إلى الرخيص، ويظنون أن انخفاض السعر علامة ضعفٍ وقلّة جودة، فإذا ارتفع السعر ارتفعت القيمة في أعينهم، واطمأنوا إلى جودة المعروض فاشتروه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1431","text":"دخل مدير المشتريات لديوان أميرٍ إلى محل بخور، فقال للبائع: أريد أطيب بخورٍ عندك. فأخرج له بخورًا سعر التولة منه ثمانون دينارًا. فقال المدير: أريد ما هو أطيب وأندر. فقال البائع: غدًا يصلني بخورٌ فاخر، لم أعرضه بعد. فلما جاءه في الغد، وانتظر حتى خرج الزبائن البسطاء، فتح البائع خزانةً مقفلة، وأخرج منها وعاءً أنيقًا، فيه البخور نفسه، وقال: هذا التولة بمئتي دينار. فاشترى المدير عشر تولات راضيًا. وما تغيّر البخور ولا نوعه، إنما تغيّر الوعاء، وحُجب عن الأعين، والدهاء في العرض، فغلا ثمنه عند من يظن أنه للأمير أطيب وأثمن.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1432","text":"زلة العالم يُضرب بها الطبل، ويُبخر بها أهل السوق، ويُنفخ بها في البُوق، وتَسير بها الركبان والنوق، وزلة الجاهل كضياء شمعة بعد الشروق.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1433","text":"المرأة تترقب من زوجها كلمات الحب والإعجاب في كل مناسبة وفي كل لحظة.","kind":"ghazal","source":"شذرات (ملف وورد)"},{"id":"m1434","text":"عندما علَّم الله تعالى آدم عليه السلام الأسماء، اكتسب آدم صفة قابلية التَّعَلُّم، وعندما أمره أن يُعلم الملائكة عليهم السلام الأسماء، اكتسب صفة التعليم ونشر العلم، فَوَرَّثْهما لأولاده، فصارتا فَطرة في ذريته. فالطفل في فصل الربيع، إذا وجد فراشة زاهية بألوانها، يراقبها ويتتبعها، فهذه صفة طلب العلم والمعرفة. ثم يرفع صوته: سعد نوح وداد، تعالوا انظروا إلى هذه الفراشة، فهذه صفة نشر العلم والتعليم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1435","text":"ليس كل خطيبٍ مِصْقَع، ولا داعيةٍ بليغ، ولا واعظٍ مؤثر، ولا مثقف فصيح، ولا مفكرٍ إسلامي مُلهم، أهلًا أن يتصدر للفتوى الشرعية؛ فإن لكل علمٍ رجاله، ولكل فنٍ أهله، ولكل مقامٍ مقال، واحترام التخصص واجب عقلي وعلمي واجتماعي، فالعلم تخصص عمودي عميق، والثقافة تخصص أُفقي شامل.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1436","text":"الطريق المستقيم لهداية الملحدين، إلى الإيمان برب العالمين، ومحاورتهم بالعلم والبرهان المبين، ومناقشتهم بالحلم واللين، والاستعانة بدعاء الرحمن الرحيم، فهو الهادي إلى الصراط المستقيم، وكرر المحاولة لعل الله يهديه ولو بعد حين، فتنال مثل ثواب أعماله يوم الدين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1437","text":"الصيد رزقٌ لمن جاع، لا لهوٌ لمن شبع. أباحه الله تعالى لحاجةٍ ونهى عنه لعبثٍ.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1438","text":"يا من أسقط حمامةً بريئةً بلا جوعٍ ولا ضرورة، أتدري أنك تُسهم بتخرب ميزان الطبيعة بطلقةٍ عابثة؟ الصيد الجائر يقتل أجيالًا ويُفني أسرابًا، وما أكثر المخلوقات التي ذهبت ضحية العبث والتفاخر! فاتق الله، ودع ما لا تأكله حيًّا في مأواه، يُسبّح مولاه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1439","text":"إذا أردت أن تُقَيِّمَ قولا أو فعلا، فتفاعل مع القول، ولا تتفاعل مع القائل، فقد يُبهجك الصغير، ويخذلك الكبير.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1440","text":"مقاولو البناء، يقتات بعضهم على جهل الناس بتفاوت الأسعار وجودة المواد، فيسوقون الحيلة ويزرعون الخداع.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1441","text":"لا تتعامل إلا مع مقاول مشهود له بالجودة والأمانة والصدق في المواعيد، ولو كان سعره أغلى، فهو أولى، وعاقبته أحمد وأحلى.","kind":"hikma","topic":"المال والاقتصاد","note":"في سياق الحديث عن مقاولي البناء","source":"شذرات (ملف وورد)"},{"id":"m1442","text":"من حسن اللقاء التحية والاستبشار، ومن حسن الفراق: الدعاء والمحافظة على الأسرار.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1443","text":"اختلاف وجهات النظر ظاهرة صحية، يتقبلها ذوو النفوس النقية، والطباع السوية، والعقول الذكية.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1444","text":"تتعرّف على شخصية الإنسان من خلال: دينه وأخلاقه: لتعرف ظاهره وباطنه. كلامه: فحديثه يكشف فكره وطباعه. سلوكه: فالأفعال أصدق من الأقوال. تعامله مع الآخرين: خصوصًا مع من دونه، ومع من لا مصلحة له معهم. رده في المواقف الصعبة: فالشدة تكشف المعادن. اختياره لأصدقائه: فالمرء على دين خليله.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1445","text":"إن عزمت على الزواج، فالتمس الخُلق والأدب والدين. وإن هممت بالبناء، فالتمس المقاول الأمين الناصح المنجز بشهادة من بنى لهم من العالمين. وأما دينه وعمله وتصرفاته فحسابها عليه، لا عليك. فخذ منه ما صفا لمقاصدك، ودع له ما كدر لنفسه لا لك.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1446","text":"الفقه الإداري، في التعامل المثالي إن كنت جديدا في موقع عمل، كيف تستطيع أن تُعطي فكرة إيجابية عن نفسك: لرؤسائك وزملائك ولم دونك؟ مع رؤسائك: كن منجزًا ودقيقًا، استمع جيدًا، نفّذ بذكاء، واطرح أسئلة تدل على فهمك واهتمامك. مع زملائك: كن متعاونًا، لبقًا، مُبادرًا بالمساعدة، وتجنب الغيبة والنزاعات. مع من دونك: عاملهم باحترام، شجّعهم، قِدْهم بالقدوة، وكن عادلًا ولينًا في آنٍ معًا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1447","text":"نصيحة للمتقاعد: اشغل وقتك بذكر الله، وبما تُحب وينفعك، ولا تعتزل الناس والمشي والجديد، حتى تواكب العصر.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1448","text":"أسباب شيطانية لمن يعبد الحجر أو البقر أو الشمس والقمر، ويكفر بالله رب المخلوقات والبشر، ورب السماوات والأرض والنجوم والقمر، إما جهلًا أو تقليدًا، أو هوًى، أو استكبارًا، أو هروبًا من الحق خشية التكاليف والقيود، أو طلبا للمحرمات والشهوات وانتهاك الحدود.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1449","text":"الوتساب ما يُحب التغريدات الطويلة ولا الكتاب، يُحب الشذرات والنتف من أولي العقول والفهم والألباب.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1450","text":"الرجل أوتي بنية جسدية أقوى، وصبرا على المشقة، وميلا للاقتحام والمخاطرة، فكان أقدر على الكسب والسعي. والمرأة جُبلت على الرقة، والصبر، والحنان، وحسن الاحتواء، فكانت أقدر على التربية ورعاية شؤون البيت. فسبحان من أعطى كل نفس هداها، وأعانها على القيام بشؤون دينها ودنياها.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1451","text":"بعض الكلاب أوفى من بعض الأصحاب","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1452","text":"أصعب ما يواجه الحُرُّ أن يُقنع من عاش عبدًا دهرا أنه يستطيع أن يكون حرًّا. لأن العبد حين يصدق أنه عبد، يريح نفسه من همّ القرار والتفكير. فيطمئن للقيد أكثر من خوفه من الحرية. وهكذا يصير التكيّف نعمة حين يُسكِّن الألم، ونقمة حين يُسكِت صوت الحرية. فيحتاج إلى مهلة لإقناعه أنه حُرٌّ، مع بيان مساوئ العبودية، ومحاسة الحرية.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1453","text":"الاستعجال في اتخاذ القرارات الجسيمة، والمبادرة إلى الأفعال العظيمة، وأنت في أتون انفعالٍ جامحٍ، قبل رويةٍ ونظرٍ في العواقب، سبيلٌ إلى الندامة ومظنّةٌ للحسرة. فالعجلة أمُّ الندامة، وبنتُ الخيبة، والقرار ابنُ الرويّة، وثمرةُ التأني والبصيرة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1454","text":"فكّر إذا هممت، وتأنَّ إذا عزمت، فما ندم متأنٍّ قط، ولا سلم مستعجلٌ اشتط.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1455","text":"أفضل وقت لشراء العقار هو أمس.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1456","text":"لا تنتظر لشراء العقار، اشتر العقار ثم انتظر.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1457","text":"الأرض لا تأكل ولا تموت.","kind":"mathal","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1458","text":"اشتر العقار لأولادك الصغار.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1459","text":"اشتر الأراضي فسوف تبيعها وأنت راضي.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1460","text":"ما أعظم نعم الله على الإنسان وما أعظم غفلة الإنسان عن الحمد والشكر الشمس تُضيء العالم في جميع الزمان بالمجان الحمد لله ثم الحمد لله.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1461","text":"الهداياُ الغاليةُ تفتحُ الأبوابَ الموصدة، وتقرِّبُ القلوبَ النائيةَ، وتُلَيِّنُ النفوسَ النافرة، وتُحيي الودَّ، وتزرعُ البسمةَ، فهي مفاتيحُ القلوب، ورسائلُ حبٍّ بلا حروف، تُحَسِّنُ الظنَّ، وتزيل الصدود.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1462","text":"التصرّف الأمثل للزوج إذا غضب، أو للزوجة إذا زعلت: كظمُ الغيظ قبل أن يستفحل، وضبطُ اللسان قبل أن يزل، وحُسنُ الظن إذا اختلطت الظنون، ولينُ الخطاب إذا اشتدّ العتاب. بادرْ بالصلح، ولو كنتَ المُحقّ، فإن الشيطان يُؤجّج، ويُوسوس، ويُفرّق. لا تُنشر الغسيل خارج البيت، فالستر أكرم، وأحكم. وتذكّر لها من المحاسن أجملها، ومن المواقف أطيبها، لتبقى المودّة موصولة، والقلوب صافية، والبيت محفوظًا عامرًا بالعفو والعافية.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1463","text":"بعض الزوجات تشتري فستانا من المعارض بمائة دينار من مال زوجها لتتزين به للناس، وتشتري من البسطات فستانا بعشرة دنانير لتلبسه لزوجها. والواعية تلبسه أولا لزوجها مرة أو مرتين، وتشكره وتدعو له، لِتَسُرَّ خاطره وتُسعده.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1464","text":"اليد هي التطبيق العملي للحضارات والثقافات والتقدم والرقي.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1465","text":"فالإسلام يحرص على تأليف القلوب، ويرفض كل ما يُشعل العداوة، أو يَزرع البغضاء، ويأمر بالتواصل، والتهادي، والتعاون بين ذوي القربى.","kind":"hikma","topic":"الإيمان والعبادة","note":"في سياق تحريم الجمع بين المرأة وعمتها أو خالتها","source":"شذرات (ملف وورد)"},{"id":"m1466","text":"إذا كانت جنةُ المتقين عَرضُها السماواتُ والأرضُ، فكم يكون طولُها؟ وإذا كان لكل مؤمن فيها نصيبٌ، فكم يبلغُ نصيبُه؟ وعلى قدر سعيك يكون نصيبك. جنةٌ بهذه السَّعة، ألا تستحقُّ أن نُسارِع إليها سَعيًا، لا مشيًا؟ بادر قبل أن يُحال بينك وبين الطاعات، فإن الجنة عظيمة، والسعي يزيد في نصيبك منها.","kind":"hikma","topic":"الإيمان والعبادة","note":"تأمل في قوله تعالى: (وسارعوا إلى مغفرة من ربكم وجنة عرضها السماوات والأرض)","source":"شذرات (ملف وورد)"},{"id":"m1469","text":"القروب الذي يخلو من التعليق والتعقيب، والثناء والتصويب، والمشاركة والمناقشة، والفائدة والشاردة، والمثل والحكمة، والفكاهة والبسمة؛ قروب خامد كجمرٍ هامد، باهت كصدى خافت، كسول كمريض شاحب هافت.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1470","text":"ما عجزتَ عن جلبه من رزقٍ أتاك كما يأتيك المطر، لأنك لا تقدر على إنزاله فهو يأتيك. وما قدرتَ عليه فلا يأتيك وأنت قاعدٌ حتى لا تُصاب بداء العجزة. فمن وهبك العقل واليدين والرجلين فقد أمرك بالسعي لطلب الرزق أمرًا قدريًا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1471","text":"السعيُ مفتاحُ الرزق، فمن سعى رُزق، ومن لزم البيت حُرم الخبزَ والتمرَ والزيت، ومن قنع استراح، ومن طمع لم يسلم من الانتقاد والجراح.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1472","text":"من جدَّ وجد.","kind":"mathal","topic":"النجاح والإبداع","note":"من «عشر حكم» أوردها","source":"شذرات (ملف وورد)"},{"id":"m1473","text":"من صبر ظفر.","kind":"mathal","topic":"الصبر والشدائد","note":"من «عشر حكم» أوردها","source":"شذرات (ملف وورد)"},{"id":"m1474","text":"قليل دائم خير من كثير منقطع.","kind":"mathal","topic":"النجاح والإبداع","note":"من «عشر حكم» أوردها","source":"شذرات (ملف وورد)"},{"id":"m1475","text":"لا تؤجل عمل اليوم إلى الغد.","kind":"mathal","topic":"الحياة والزمن","note":"من «عشر حكم» أوردها","source":"شذرات (ملف وورد)"},{"id":"m1476","text":"الصدق منجاة.","kind":"mathal","topic":"الأخلاق والآداب","note":"من «عشر حكم» أوردها","source":"شذرات (ملف وورد)"},{"id":"m1477","text":"لكل مقام مقال.","kind":"mathal","topic":"الكلام والصمت","note":"من «عشر حكم» أوردها","source":"شذرات (ملف وورد)"},{"id":"m1478","text":"الكذب حبله قصير","kind":"mathal","topic":"الأخلاق والآداب","note":"من «عشر حكم» أوردها","source":"شذرات (ملف وورد)"},{"id":"m1479","text":"القناعة كنز لا يفنى.","kind":"mathal","topic":"المال والاقتصاد","note":"من «عشر حكم» أوردها","source":"شذرات (ملف وورد)"},{"id":"m1480","text":"من فوائد الحكمة: تعينك على ترتيب الأولويات. تجعلك تحسن اتخاذ القرار. تحفظك من الزلل والعجلة. تبصّرك بعواقب الأمور. تكسبك احترام العقلاء. تهديك إلى خير الأقوال والأفعال. تقيك الندم وسوء العاقبة. تنير لك دروب الحياة. تزيدك وقارًا وهيبة. تقرّبك من رضا الله ثم رضا الناس. علموا أولادكم الحكمة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1481","text":"إنَّ اللهَ امتنَّ على الإنسان بنعمةِ العقل، وأعضاءٍ متينة، ومفاصلَ مرنة، بها يُحسن التصرّف ويتكيَّف مع المستجدات، فيسعى لجلب المنافع والمصالح، ويجتهد في دفع المضار والمفاسد. فسبحان الله المُنعم المُتفضل على جميع مخلوقاته، بجليل النِّعم، وعظيم المِنَنِ","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1482","text":"طلب الرزق طاعة وعبادة إذا اقترن بالوجه المشروع والنية الصالحة، وإلا فهو غريزة من الغرائز يشترك فيها الإنسان وسائر المخلوقات والحيوان.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1483","text":"مَن حُرِمَ الانتفاعَ بعلمِه، وقعَ أسيرَ ضررِ جهلِه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1484","text":"فِقهُ الاقتصادِ في الإسلام قائمٌ على بَسطِ الثروةِ وتوسيعِ دائرتها بين الناس، بفرائضَ محكمةٍ كالزكوات، ونوافلَ جليلةٍ كالصدقات، وكفّاراتٍ مُطهِّرة، ومواريثَ مقسومة، ووصايا مشروعة، وغنائمَ مقسَّمة، وأوقافٍ دائمة، ليظلَّ المالُ دُولةً بين أفرادِ المجتمع، لا حِكرًا على أغنيائِه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1485","text":"ربو أولادكم بتربية أنفسكم، منذ نعومة أظفارهم، فهم يحاكونكم فطرة، ويقلدونكم طبيعة، فعيونهم ترقبكم لتفعل مثل فعلكم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1486","text":"التقليد والمحاكاة من أقوى وأوسع وأيسر أبواب العلم، التي أودعها الله في المخلوقات، وجعلها فطرة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1487","text":"المرأة كالفراشة الرقيقة، والزهرة الناعمة، فتعامل معها بلطفٍ ولينٍ ورقّة، وابتعد عن كل ما يجرحها أو يخدش كبرياءها وحياءها. فهي تزهر بالودّ والاحتواء، وتذبل بالقسوة والجفاء.","kind":"ghazal","source":"شذرات (ملف وورد)"},{"id":"m1488","text":"أفضل وأيسر طريق لتحويل العدو لصديق: كظم الغيظ، والعفو عن الزلات، وإظهار الإحسان عند القدرة، ومقابلة السيئة بالحسنة، مع الصدق والثبات على ذلك حتى يرحل الجفاء ويحل محله التقارب والود والوفاء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1489","text":"فالقلب يفتح بالمحبة، والعقل يقتنع بالبرهان، والروح تهتدي إذا اجتمعا مع النصح والصبر.","kind":"hikma","topic":"الإيمان والعبادة","note":"خلاصة كلامه في أفضل طريقة لمناقشة الملحد لهدايته","source":"شذرات (ملف وورد)"},{"id":"m1490","text":"أهم صفات علماء السوء: ١-بيع الدين بعرض من الدنيا. ٢-ليّ النصوص لخدمة السلطان أو الهوى. ٣-كتمان الحق وتزيين الباطل. ٤-حب الظهور والجدال للرياء. ٥-الانشغال بالشهرة والمال عن العلم والعمل.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1491","text":"بعض القنوات لا تستضيف إلا أهل الأهواء، وعلماء السوء والشذوذ، لتُزيّن الباطل وتستدرّ المشاهدين، وتجعل من الانحراف بضاعة، ومن الفتنة صناعة، ومن تضليل العقول وسيلة لبلوغ غاياتها الربحية والمادية والكسبية، إنهم ينشرون التشكيك في اليقينيات، ويثيرون الشبه حول المسلمات.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1492","text":"أقوى بواعث العناد والعصيان، والجحود والكفران: الجهل، واتباع الهوى، وإغراء الشهوات، والاغترار بالدنيا، وتأثير رفقاء السوء، وكبرياء النفس عن الحق، ووسوسة الشيطان… وهذه تجتمع فتغشي البصيرة، وتجرّ صاحبها لمعاداة طريق السلامة، وهو الإسلام.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1493","text":"إن أطلقْتَ لسانَك بغير حقّ، كَثُر عليك الخصام، وزاد عليك الملام، وسَخِطَ عليك الملكُ العلّام، واضطرب قلبُك وقلَّ الأمان، أمّا إن نطقتَ بالحقّ ابتغاءَ وجهِ الرَّحمن، فلك الثواب والأمان، من الكريم المنان، وأثنى عليك الأنام.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1494","text":"أخطر أنواع الصراع هو الصراع الداخلي، حين يتنازع الإنسان مع نفسه بين ما يعرفه حقًا وما يفعله باطلا، أو بين ما يريده وما يخاف منه، أو بين قناعاته وواقعه، وبين نوازع الخير ونوازع الشر، بين الأنسان وبين قرينه الشيطان، هذا نزاع دائم ولاينقطع، فاستعن عليه بذكر الله تعالى، والأذكار المأثورات والمعوذات، ومصاحبة الأخيار والصالحين من الأفراد والمجموعات.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1495","text":"القناعة رأس السعادة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1496","text":"الأمانة تاج الصيانة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1497","text":"النزاهة سبيل العزة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1498","text":"الشجاعة عزّ المناعة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1499","text":"الصدق نعم الرفيق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1500","text":"الحِلم زينة العلم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1501","text":"العدل عماد الحُكم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1502","text":"الصبر مفتاح الظفر.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m1503","text":"الكرم عنوان الشِّيَم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1504","text":"الوفاء أصل الصفاء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1505","text":"التواضع سبب المحبة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1506","text":"من صور التعاون والتكامل بين الشعب والحكومة: 1.التشريع والتنفيذ: الحكومة تضع القوانين وتنفذها، والشعب يلتزم بها ويشارك في تطويرها. 2.الأمن والاستقرار: الحكومة توفر الحماية، والشعب يتعاون بالانضباط والوعي. 3. النهضة والاقتصاد: الحكومة تهيئ الفرص والموارد، والشعب يسهم بالعمل والإنتاج.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1507","text":"تربية الأطفال على المشاركة في أعمال المنزل حسب أعمارهم. مشاركته تزيده في تحمل المسؤولية والترقي شيئا فشيئا. جهد يمنحه القوة والنماء. تعاون يغرس المودة والصفاء. نظام يورثه الهِمّة والارتقاء واستعداد يبني المستقبل بالرقي والاستعلاء. وغيرها كثير من الخصال الجليلة، والأعمال النبيلة، والصفات الكريمة، فتصبح له عادة فتخف على نفسه مزاولتها والقيام بها.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1508","text":"كثيرٌ من الناس إذا سمع بفاكهة أو عصير فيه فوائد، بالغ في تناوله كما وكيفًا، حتى تنقلب الفائدة ضررًا؛ والنصيحة: خذ من الطعام والشراب بقدر، ولا تُسرف فتجلب الضرر؛ فالاعتدال دواء، والإفراط خطر وداء.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1509","text":"الزوجة وعموما المرأة، متقلبة الأطوار، وسريعة في اتخاذ القرار، ولا تقدر على حفظ الأسرار. فالنصيحة: خالطها بالحلم، ودارها بالحكمة، وأحطها بالمودة، فإن صبرك عليها دواء، وحلمك شفاء، ورفقك بها بقاء.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1510","text":"عند الاضطراب الأمني يُخزّن الناس حاجاتهم في البيوت، أما في حال الأمن، فاعتبروا كل ما في الجمعيات ملكًا لكم، يصل إليكم بالهاتف متى شئتم. فلا داعي للمبالغات في كثرة الثلاجات- والفريزرات- وكثرة المعاناة، وفساد بعض المخزونات.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1511","text":"النصيحة الذهبية للموظف الجديد: أخلص العمل، واضبط الوقت، وأتقن المهام، وتعلّم بعينيك ولسانك وأُذنيك، واطلب العون بلطف، واحترم النظام، وحافظ على الأخلاق، ووسّع علاقاتك الإيجابية، وكن صبورًا مثابرًا، فهذه مفاتيح النجاح والرفعة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1512","text":"من أرقى صور العدالة وحسن التدبير، أن تُشرك الحكومةُ مواطنيها على مختلف طبقاتهم، في كل ما يمس حياتهم، من قوانين وعقوبات وقرارات ومزايا. فتعرضها على نُخبة منهم؛ لتستضيء بآرائهم، وتستفيد من ملاحظاتهم، فتضمن العدل في مضمونها، والقبول في تطبيقها، والاستمرار في أثرها. فالإشراك في الرأي، فطنةٌ وكياسة، وهو من حق المواطن وواجب الحكومة، وعدم الإشراك مزلة قدم، يعقبها حسرة وندم، وطعن في الأمانة والذمم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1513","text":"اكسب ودَّ زوجتك بلين الكلام، وطيب المعاملة والسلام، وحسن الدلال وترك الملام، وصِدق الوفاء مع الاحترام، وإشعارها بالمودة والاهتمام، فإن القلب يُملك بالرحمة والحب على الدوام.","kind":"ghazal","source":"شذرات (ملف وورد)"},{"id":"m1514","text":"كثير من الناس ميّالون إلى التهويل والمبالغة والتفخيم، فيعرضون آراءهم في صورة قطعية إلزامية، لا تقبل نقاشًا ولا تدقيقًا، ولا تعقيبًا ولا تمحيصًا، وعند المراجعة والتدقيق، يظهر الأمر خلاف ذلك، فعلى الإنسان أن يجعل له خط رجعة ومراجعة، ولا يُبالغ في الجزم، وفوق كل ذي علم عليم.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1515","text":"أعنِ الشاب المنطوي بالرفق واللين والاحتواء، وإشعاره بالأمان والسلامة والاهتمام، وجذبه بلطف الحديث والكلام، ومشاركة اهتمامات الأنام، حتى يألف الانبساط والخروج من طي الظلام، شيئًا فشيئًا بسلام.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1516","text":"اكسب ودَّ جارك بالسلام والابتسام، وبذل السلامة والإهداء والإكرام، وكفِّ الأذى وتحمّل الخطأ، والمشاركة في السرّاء والضرّاء، فإن القلوب تأسرها المودة والاحترام.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1517","text":"أيها المسلمون، المسلم أخو المسلم، ينصره ولا يخذله، فنصرةُ المظلومين منكم فريضة واجبة، ولكلٍّ قدرُه ونصيبُه؛ فالمدني بالدعاء والتبرع والكلمة والمقاطعة. والحكومات بما أُوتيت من سياسة واقتصاد وإعلام ودبلوماسية ومقاطعة وسلاح وجنود. فللنصرة أبوابٌ شتى، وعلى المسلمين جميعًا، حُكّامًا ومحكومين، أن يسعوا إليها بكل وسيلة متاحة، حتى تُرفع المظلمة وتُبرأ الذمّة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1518","text":"الحاجة أمُّ الاختراع، والمضطر يركبُ الخطر، والشدّة تُلهمُ الحيلة، والفاقةُ تُخرجُ الحلول الدخيلة.","kind":"hikma","topic":"الصبر والشدائد","note":"يتضمن المثل المعروف: الحاجة أم الاختراع","source":"شذرات (ملف وورد)"},{"id":"m1519","text":"فلسفة الريجيم: من أكل أكثر من احتياج بدنه فهو يبني، ومن أكل أقل من احتياج بدنه فهو يهدم، ومن أكل بقدر احتياج بدنه فهو لا يبني ولا يهدم.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1520","text":"ثمرة التجارب لا تكذب، فنتائجها يقينية، ودروسها واضحة، وثمرتها مرضية، توفر عليكم الوقت والمال والمعاناة المضنية، فاغتنموها ولا تفرطوا بها، أقل مجهودا، وأكثر علما، وأوثق نتائجا. فجالسوا كبار السنِّ من العلماء والخبراء والأتقياء، لتستفيدوا من تجاربهم وخبراتهم ونصائحهم.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1521","text":"القوانين التي وُلدت في ظروف استثنائية أو تحت ضغط الانفعال وردود الأفعال، أحوج ما تكون إلى مراجعة هادئة متأنية، إذ العجلة تورث الخلل، والانفعال يطغى على ميزان العقل. وما شُرع في ساعة اضطراب قد لا يصلح لزمن استقرار، فالمراجعة هنا ليست نقضًا ولا نقصا، بل تصويبٌ وعدلٌ ورحمة بالناس، وحُسنُ سياسةٍ يرفع الحرج ويعيد الأمور إلى نصابها، والنفوس إلى قناعتها واستقرارها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1522","text":"الماضي أقدارٌ قد خُطّت، وأيامٌ قد مضت، لا يُعاد زمانها، ولا يُسترجع فقدانها، فلا تذرف دمعًا على ما لا يعود، ولا تُشغل قلبك بندم لا يُجدي، واجعل من عِبر الأمس سُلَّمًا للغد، ومن حكمة التجربة نُورًا للطريق. فمن اتخذ الندم مركبًا، طال مسيره وتاه مصيره، ومن جعل الحكمة زادَه، والعبرة دليله، رَسَت سفينته، وبلغ مأمنه، وأدرك غايته.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1523","text":"تكسبُ الأصدقاءَ بحُسن الخُلُق، ولين الطبع، وسلامة الصدر، وعذوبة اللسان، وصدق المعاملة، وكفِّ الأذى، وبذلِ الندى، وتقديم المساعدة عند الشدائد، وإظهار الشكر عند الموائد، وقلة الجدال، وترك الفضول من الكلام، وغض الطرف عن الزلل، والثناء على محاسن العمل، والحفاظ على المودة والتجاوز عن الخطأ والخلل.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1524","text":"اختلاف وجهات النظر نعمةٌ جليّة، وسنة بشرية، وسمة انسانية، لا يعي قدرها إلا ذوو النفوس الزكيّة، والطباع السويّة، والعقول الذكيّة. فهي بابُ آفاقٍ بهيّة، وجسورُ روابط قويّة، وثمارُ نتائج مرضيّة، ومدخلُ حلولٍ عصريّة، تحفظ الحقوق الشرعيّة، وترعى المصلحة العليّة. فطوبى لمن جعل الخلاف وسيلةً سويّة، ورحمةً خفيّة، وحكمةً ربّانيّة، وأخلاق ذهبية، وهداية لأفضل الآراء السنية.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1525","text":"أفلح من جمع بين الخوف والرجاء، والطاعة والإخلاص، والتوبة والاستغفار، والعزة والتواضع، وحسن الظن والحذر، والصبر والشكر، والعدل والإحسان، والعلم والعمل، والقناعة والرضا، والزهد والورع، والرحمة والرفق، والشجاعة والحلم، والحياء والكرم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1526","text":"( العزائم والرخص ) الدين مبني على العزائم، لصيانة أحكامه من التفريط، واتقاء الشبهات، والاحتياط من التساهل في التطبيق. والرخص يُلجأ إليها لرفع الحرج عند المشقات، وكلا الاتجاهين صحيح إذا استندا إلى الدليل، وإنما الخطأ في الإفراط أو التفريط.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1527","text":"الأمر إذا ضاق اتسع، وهذه قاعدة محكمة، دلّ عليها قول الله: وما جعل عليكم في الدين من حرج. فمنها: المشقة تجلب التيسير، و الضرورات تبيح المحظورات، و الحاجة تنزل منزلة الضرورة، والحرج مرفوع، و ما لا يدرك كله لا يترك جله، وغيرها. فالشريعة جاءت بالعدل والرحمة، لا بالعنت والمشقة، فإذا ضاقت السبل فتح الله باب الرخصة، وإذا زالت المشقة عاد الحكم إلى أصله.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1528","text":"كُلْ في بيت أخيك، ولا تنم عنده. ونَمْ في بيت أُختك، ولا تأكل عندها.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1529","text":"اشتر الجار قبل الدار.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1530","text":"طِيب الدار من طِيب الجار. سُوء الدار من سُوء الجار.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1531","text":"لولا طِيب جاري لبعت داري. لولا سُوء جاري لما بعت داري.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1532","text":"طِيب الجار يزيد في ثمن الدار. سُوء الجار يُنقص من ثمن الدار.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1533","text":"اسأل عن الجار قبل الدار.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1534","text":"جاري كَرَّهَني في داري. جاري حَبَبَ إلى داري.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1535","text":"الدين أصول ثابتة نصوصها قطعية، تصون الملة من التغيير والتبديل، وله فروع قائمة على القياس والاجتهاد، لا تعارض الأصول ولا تخرج عنها. فالأصول حصن راسخ لا يزول، والفروع مرنة تمكنه من مواكبة الزمان والمكان وتحقق المصالح المأمولة. ومن ثم فالدين صالح لكل عصر، باقٍ على مر الدهور، مهما تطور الإنسان وطال الزمان.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1536","text":"البيت يقوم على أساس متين، وأركان راسخة، وعُمد مسلّحة بالحديد تحفظ بنيانه من السقوط، وعلى جدران وحواجز قابلة للتغيير والتحريك وفق الحاجة. وكذلك الدين: أصول قطعية ثابتة، تحفظ الملة وتصون حقيقتها، وفروع اجتهادية عقلية منبثقة من تلك الأصول، تواكب النوازل والحاجات، وترسم الحدود والأحكام المستنبطة من النصوص. فالدين ثابت بأصوله، متجدد بفروعه واجتهاداته، مستمدة دومًا من ينابيعه الصافية؛ صالح لكل إنسان، ولكل زمان ومكان.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1537","text":"ولأن النصوص محدودة، وحاجات الناس غير محدودة، شُرع الاجتهاد والقياس ليستنبط العلماء من الأصول ما يحقق المصلحة، ويحفظ المقاصد، ويصون الحقوق، ويرفع الحرج والعنت عن الناس.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1538","text":"طوبى لمن لازم الذكرَ والدعاءَ والاستغفار، في الليلٍ والنهار، فقد أحاط نفسَه بحصنٍ حصين، يقيه كيدَ الشيطان وشرَّ الأشرار، وفوق هذا هو جليس الوهاب المَنَّان، وتظلله ملائكة الرحمن.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1539","text":"الأطفال جُبلوا على حبّ المعرفة، وولِدوا بشغف الاكتشاف والفهم، فلا يزالون يكثرون من السؤال والاستفسار، ويغترفون من التفهيم والتلقين، ويتعلمون بالمحاكاة والتقليد، ثم يترقَّون بالحوار والنقاش، والتجربة والشرح، حتى يكتمل العقل، ويصفو الإدراك، ويشرق القلب بنور الفهم. ومن ثَمّ، فواجب الأبوين أن يفتحوا أمامهم الأفق، ويُرووا عطشهم، ويُغذّوا شغفهم؛ فإنها الخطوة الأولى إلى النبوغ، ومفتاح العبقرية، وبذرة التميّز في قادم العمر.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1540","text":"الكلُّ حكيمٌ ما دامتِ القصةُ ليست قصتَه، وكريمٌ ما دام المالُ ليس مالَه، وصبورٌ ما دامتِ المصيبةُ ليست مصيبته، وبطلٌ ما دامتِ المعركةُ ليست معركته. فلا تحكمْ قبل أن تتخيل نفسك في الظروف نفسها، ولا تذمْ غريقاً وأنت على اليابسة، فلا تَلوم الناسَ وأنت تجهلُ ظروفهم. واعلمْ أن سعادةَ غيرك لا تُنتقصُ من سعادتك، وغناه لا يحرمُك رزقك. فكن عادلاً تقياً، عاقلا سخيا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1541","text":"من الغُبن والجَور أن نُقيم ندوةً نُهوِّل فيها سلبيات الخدم ونتعامى عن إيجابياتهم، ونذمُّ من نستقدم ونبذل في سبيلهم المال، بلا صوتٍ يُدافع عنهم، ولا ندوةٍ تُبين سلبيات المخدومين، وهم الأشد تقصيرًا والأعظم تجاوزًا؛ فذلك ظلمٌ بواح، وحكمٌ غير راجح ولا راشد، إن الله لا يُحب الظالمين، ويكره المعتدين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1542","text":"آفة الكذَّاب النسيان.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1543","text":"الصدق يُنجي صاحبه والكذب يفضح صاحبه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1544","text":"الصدق طُمأنينة والكذب ريبة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1545","text":"الكذَّاب يحتاج إلى ذاكرة قوية.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1546","text":"الكذَّاب يفقد ثقة الناس به، ويخسر سمعته.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1547","text":"الكذاب لا يصلح أن يقود الجماهير.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1548","text":"الحياة مدرسةٌ كبرى، دروسها التجارب، والإنسان فيها يتعلّم من نجاحه كما يتعلّم من إخفاقه؛ فكل تجربة تزيده خبرة، وتمنحه عبرة، وتقوّي عزيمته. ثم يجعلها الله سبيلاً لتيسير أمره، وشرح صدره، وتعويضه خيرًا مما فاته أو أُخذ منه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1549","text":"فلسفة المخالفات والعقوبات، تقوم على التناسب، فالعقوبة وسيلة للردع والتقويم، لا للانتقام أو الجباية، فتقدّر بقدر جسامة الفعل وخطره. ووجه عدم التناسب، إذا زادت العقوبة كثيرًا عن حجم الضرر، صارت ظلمًا أو وسيلة ابتزاز، وفقد القانون هيبته وصار مثارًا للسخط. وإذا نقصت العقوبة كثيرا عن حجم الضرر، صارت وسيلة لارتكاب المخالفات، وعدم المبالات. الخلاصة: العدل في العقوبات أن تردع المخالف بلا ظلم، وتؤدبه لمنع الاستهتار بالقوانين والنظام، ويتقبلها العقلاء وعامة الأنام. وأن لا يُقرر المُشَرِّع العقوبة وهو متأثر بردود الأفعال، فيرجح عاطفة الحماس على حكمة العقل، فيقع في الزلل والخلل والقصور في ثمرة العمل.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1550","text":"بعض ضعاف النفوس إذا أرهقته بالعقوبات المالية، سوف يتجه إلى الطرق الملتوية، ليسد الفجوة المالية، فالكلب إذا حُوصر عقر.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1551","text":"الحكمة الشرعية والكونية من مشروعية صلاة الكسوف والخسوف: تذكيرٌ للعباد بقدرة الله وعظمة سلطانه، وأن هذه الآيات الكونية الجارية على نواميسٍ محكمة سنَّها الخالق سبحانه، وسخَّرها لمنافع خلقه، إنما يجعلها الله تخويفًا لعباده وتنبيهًا لقلوبهم، ليهرعوا إلى الصلاة والذكر والدعاء والخشوع والتوبة، فيزداد يقينهم، وتعلّقهم بمسبب الأسباب وخالقها جل شأنه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1552","text":"( فَنُّ التعامل مع الزوجة ) إذا غيرتْ لون شعرها، ثم قالت لك: ما رأيك؟ لا تخبرها برأيك لأنها لا تريد رأيك، بل تريد أن تقول: أنت جميلة والآن أصبحت أجمل. إذا أردت أن تسافر يومين، فقلت: ماذا تريدين مني هدية؟ قالت: لا داعي للهدية، معناها: لازم تأتيني بهدية. إذا قالت: قل رأيك بصراحة، ما أزعل، لا تقل رأيك، بل قل ما تحب أن تسمعه هي. إذا شعرتَ أنها حزينة، فسألتها فقالت: أنا زينة، فاسكت، ولا تحاول أن تنكشها.","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1553","text":"زوج ابنتك صهرك، وهو ستر وغطاء لابنتك، فأكرمه واحترمه، ليحفظ لك ذلك في إكرام ابنتك، ولا تُخاشنه أو تحتقره فينعكس وبال ذلك على ابنتك، فِلْذَةُ كَبِدِك.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1554","text":"من طابت قهوتُه، وعَبِقَت رائحتُها، وسطع شذا بخورِه، وحَسُن ترحيبُه وحضورُه، وتهللت أساريرُه ووجوهُ زُوَّاره، عَمُرَ ديوانُه، وكثر إخوانُه وخِلَّانُه، ودامت له المحبةُ والبركة، وتتابع عليه الخير والنعمة المشتركة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1555","text":"اجعل زيت الزيتون والعسل جزءًا ثابتًا من غذائك، لكن لا تعتمده كعلاج مباشر أو سريع، بل كوسيلة وقاية ودعم للصحة العامة.","kind":"hikma","topic":"الصحة والنفس","note":"بعنوان: النصيحة الذهبية","source":"شذرات (ملف وورد)"},{"id":"m1556","text":"الأطعمة كلها فيها منافع، لكن العافية في الاعتدال، والتنوع مفتاح السلامة، وما زاد عن الحد انقلب إلى الضد، فخذوا من كل شيء بقدر، تهنؤوا بالصحة وتغنموا العافية.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1557","text":"القرآن هو الموسوعة الكونية العلمية الإلهية الخالدة، جمع كمال البيان مع كمال البرهان، أتى بأقصى المعاني في أوجز الألفاظ، وبأيسر النطق في أبلغ الجمل، وفي تلاوته جمال يملأ القلوب جلالًا، جمع بين الهداية والتشريع، والبلاغة والإعجاز، والعلم والنور، فهو كتاب الحياة، ومرجع الهداية، وحبل الله المتين، ومعجزة الدهر المبين، والحمد لله تعالى.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1558","text":"أربع أكلات موبقات مهلكات: أكلُ مال اليتيم ظلمًا، وأكلُ الربا حربًا لله ورسوله، وأكلُ لحم أخيك غيبةً ونميمة، وأكلُ أموال الناس بالباطل غصبًا وظلمًا. هي نارٌ تحرق الحسنات، وتورد صاحبها موارد المهلكات والمحرقات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1559","text":"لو نُصرت البوسنة أول أمرها، ما تجرّأ العدو على فلسطين بعدها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1560","text":"لو نهيت الأولى لما كانت الثانية.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1561","text":"لو أُطفئ الشَّرار، لما احترق من في الديار.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1562","text":"لو أُقيم على الظالم حدّه يوم بَغى، ما تجبّر حتى طغى، ولكف غيره من الورى.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1563","text":"لو وُئدت الفتنة في مهدها، ما استحكمت في عهدها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1564","text":"كل ما تشتهي، والبس ما يعجب الناس.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1565","text":"يراعى في اللباس: الشرع - المناخ - العرف.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1566","text":"القيادة لا تستقيم بالقوة وحدها، بل لا بد أن تؤازرها الحكمة، ويعضدها العدل، وتزينها السياسة الرشيدة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1567","text":"وإذا تعارضت العدالة والصداقة، فقدم العدالة، وحاول أن تحفظ الصداقة فلا تخسرها.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1568","text":"وإذا تزاحمت الحزبية ومصلحة الأمة، فدع الحزبية وراء ظهرك، وامضِ بمصلحة الأمة، فهي الأَولى والأجدر.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1569","text":"لكل جديد لذة، ولكل قديم حرمة. هذا في الناس.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1570","text":"لكل جديد لذة، ولكل قديم زتة. هذا في الأجهزة والأثاث.","kind":"hikma","topic":"الحياة والزمن","note":"زتة: رمي وطرح بالعامية الكويتية","source":"شذرات (ملف وورد)"},{"id":"m1571","text":"الأمة العربية والإسلامية ليسوا على قلب رجل واحد، لو كانوا كذلك لهابتهم الأمم، ولو من غير حرب ولا سلاح، لخوفهم على مصالحهم ومنافعهم.","kind":"hikma","topic":"السياسة والقيادة","note":"جاءت تعليقًا على حديث التحريش بين المصلين","source":"شذرات (ملف وورد)"},{"id":"m1572","text":"حب الدنيا فطرة، وحب الآخرة إيمان، ولولا حب الدنيا لخربت الدنيا ولم تعمر، وحب الدنيا لا يلحقه ذم ولا إنكار، لكن إيثار الدنيا على الآخرة هو المنهي عنه والمذموم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1573","text":"المال يُهلكه الإسراف، والتباهي بالمظاهر، ويُنميه الاقتصاد والاقتصار على الحاجات، فدعوا المظاهر الخدَّاعة، وعُودوا للبَساطة والقناعة، فالعاقل من ملك حاجاته، لا من ملكته الكمالياتُ والمباهاةُ.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1574","text":"لا تجعلوا جُلَّ همّكم تتبّع أخبار الناس: ماذا قالوا، وماذا فعلوا، وماذا لو فعلوا، ولا تنشغلوا بالأخبار المحلية والعربية والعالمية، ثم تُعرضوا عن ذكر الله تعالى؛ فالذِّكر روحُ العبادات وغايتُها، وما شُرعت العبادات إلا لإقامته، وهو الباقي في الجنة دون سائر الطاعات. وهو عبادة الملائكة الأطهار وحملة العرش الكبار، عبادةٌ لا يحدّها زمان، ولا يقيدها مكان، ولا تحتاج إلى هيئة مخصوصة، بل يؤديها العبد في كل أحواله وتقلباته. وهو البلسم الشافي للقلوب من همومها وغمومها، والدَّواء الناجع لأدواء النفوس وأمراض الأرواح، وبه تطمئن القلوب، وتسكن النفوس، ويعظم الرجاء، فهو خير دواء لكل داء، وسلاح أمضى على شياطين الإنس والجن الأشقياء.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1575","text":"الكتاب المفيد غذاءٌ للعقل، ودواءٌ للجهل، والقراءة عمرٌ ثانٍ يُضاف إلى العمر، بها تنفتح الآفاق، وتسمو المدارك، ويصفو الفكر، ويستنير البصر والبصيرة. هي سلوى للنفس، وأنسٌ للروح، وفرارٌ من رتابة الأيام إلى بساتين العلم ومفاهيم المعرفة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1576","text":"الموت خاتمة دارٍ فانية، دارِ ابتلاءٍ وامتحان، ينجو فيها من آمن وعمل صالحًا، ويهلك فيها من كفر وأعرض. وهي في الوقت نفسه فاتحة دارٍ باقية، دارِ جزاءٍ وعدل وفضل، يُكرم الله فيها المتقين بالجنة والرضوان، ويُذلّ فيها الجاحدين بالهوان والخزي والنيران.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1577","text":"رُبَّ ضارةٍ نافعة، ورُبَّ حسنةٍ لمنزلتك رافعة، تُقَدِّمها فتكون لك شافعة، فلا تيأسوا من رحمة الله، ولا تقنطوا من عفوه ورضاه، ففرجُه قريب، وتدبيرُه عجيب، وهو السميعُ المجيب.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m1578","text":"يا بُنيّ، اعلم أنّ لكلِّ عالِمٍ زلّة، ولكلِّ حكيمٍ هفوة، ولكلِّ بصيرٍ غفوة، ومن ادّعى العصمة فقد أوقع نفسَه في أعظم سقطة. والخطأ طبعُ البشر، والصواب هبةُ الله خالق البشر، والرجوع إلى الحق فضيلة، والتمادي في الباطل رذيلة. ومن لم يعتبر بعثراته أعاد كرّاته وعَبَراته، فإنّ الصواب ثمرة التجربة، والتجربة طريق الصواب، ومن سار على الطريق بلغ الهدف على التحقيق.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1579","text":"لولا السلبيات ما أدركنا قيمة الإيجابيات، وبضدها تتميز الأشياء: لولا المرض ما عرفنا قيمة الصحة. لولا الخوف ما عرفنا قيمة الأمن. لولا الظلم ما عرفنا قيمة العدل. لولا الجهل ما عرفنا قيمة العلم. لولا الفقر ما عرفنا قيمة الغنى. لولا القسوة ما عرفنا قيمة الرحمة. لولا الشتات ما عرفنا قيمة الوحدة. وبضدها تتميز الأشياء.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1580","text":"إذا أراد اللهُ بعبدِه خيرًا، فتح له أبوابَ طاعتِه، وصرف عنه شَرَّ نفسِه وهواه، وغرس في قلبه محبّةَ الإيمان، وهيّأه لطاعةِ الرحمن، ووفّقه لعملِ الصالحات، وبذلِ الصدقات، وإطعامِ الجياع والفقراء، ورعايةِ الأيتام والمساكين والضعفاء، وألهمه التمسّك بالدين، والعطف على المحتاجين والمكروبين، لا يطلب جزاءً ولا شكورًا، إنما ابتغاءَ وجهِ ربِّ العالمين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1581","text":"التفكير خارج الصندوق، يفتح مغاليق العقول، ويكشف حقائق المستور، ويجلي المعارف المخبوءة، ويوسّع المدارك الضيّقة، ويقرّب الغايات البعيدة، ويضم الصغائر المبعثرة، ويجمع متناثرها، ويصوغ من الفكرة اليتيمة كنوزًا ثمينة، تبدعها العقول المستنيرة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1582","text":"الأخلاق تاجُ المرء، بها يعلو مقامه، وبدونها يسقط احترامه، هي جواز المرور إلى القلوب، وميزان التفاضل بين الشعوب، فالأخلاق ترفع الضعيف، وتُسقط القويّ إن حاد عن الطريق، فهي ميراث الأنبياء عليهم السلام، وزينة العقلاء، ورأس مال الحكماء، من تزين بها أكرمه الخالق، وأحبّه واحترمه الخلق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1583","text":"فالحكمةُ أن يبدأَ بالأخفِّ قبلَ الأشدِّ، وباللينِ قبلَ الغلظة، وبالنصحِ قبلَ العتابِ، فذلك أدعى للقبولِ، وأليقُ بكرامةِ المسؤوليةِ التي حمّله اللهُ إياها.","kind":"hikma","topic":"الحياة الزوجية","note":"في سياق وعظ الرجل لأهله","source":"شذرات (ملف وورد)"},{"id":"m1584","text":"الأم: حاضنةٌ تُدفئ، ومرضعةٌ تُروِي، ومربيةٌ تُهذِّب، ومعلِّمةٌ تُؤدِّب، ومدرسةٌ تُخرِّج الأجيال، ومُلهمةٌ تُوقِد العقول والآمال، هي نبعُ الحنان، ومصدرُ الأمان، وسرُّ الإيمان، وصانعةُ الإنسان، إن نظرتَ إليها أبصرتَ الجنةَ بين عينيها، وإن قبلتَ يدَها مسَّت أناملك بركةَ السماء، فسلامٌ على قلبٍ وسِعَ من حوله حبًّا وحنانًا وأمنا وسلاما.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1585","text":"فالتنويع حياةٌ للنفس، وتجديدٌ للعقل، وطردٌ للملل، وجلبٌ للنشاط. ومن أدرك سرّ التنويع، فقد ملك مفاتيح الجمال والإبداع.","kind":"hikma","topic":"النجاح والإبداع","note":"من خاطرة عن التنويع في مجموعات الواتساب","source":"شذرات (ملف وورد)"},{"id":"m1586","text":"الأمومة حنان وتضحية وصبر، تحفظ الحياة وتغرس الفضيلة، هي سِرُّ الوجود، ومصنع الخلود، بدعائها تُفتح السدود، ويُشرع الباب الموصود، ويُحْيَى الأمل المفقود، تبذل لأبنائها الكبير والمولود، وتُعطي بلا حساب ولا حدود، ولا تنتظر جزاءً ولا مردود، فبرها يهدي إلى جنات النعيم والخلود.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1587","text":"فعلى الرجل أن يكون لطيفا ودودا معها، ويقدر أُنوثتها ورقتها وعاطفتها، فهي ريحانة وليست قُهرمانة.","kind":"hikma","topic":"الحياة الزوجية","note":"القهرمانة: وكيل الملك أو رئيس التجار","source":"شذرات (ملف وورد)"},{"id":"m1588","text":"الشعب المثقف الواعي، يعصم الحكومة من ارتكاب الخطأ، لأنه يراقبها وينتقدها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1589","text":"الصمت سلاح الحكيم ضد السفيه.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1590","text":"تعاليم الدين والأخلاق يعصمان المجتمع من الانزلاق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1591","text":"جميلٌ أن نختلفَ بأدب، ونعتذرَ باعتراف، ونعاتبَ برفق، ونلتقي بمودّة، ونفترقَ بسلام، ونجتمعَ ببشاشة، وننصحَ بلين، ونُنكرَ بلطف، ونغضبَ بحِلم، ونطلبَ بتواضع، ونردَّ بحكمة، ونُجيبَ بتؤدة، ونستأذنَ بحياء، ونُعاتبَ بحنان، ونحاورَ بهدوء، ونأمرَ برفق، ونُكرمَ بصمت، ونُعبّرَ ببصيرة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1592","text":"التعاليم السماوية منسجمةٌ مع الفطرة الإنسانية، لاتحاد المصدر الإلهي، وسلامة النهج من الزلل والقصور. فإذا جرى تطبيق التعاليم السماوية في الأفراد والمجتمعات، استقام الميزان واعتدل البنيان. والأب مسؤولٌ عن إقامتها في أهل بيته، كما أن وليَّ الأمر مؤتمنٌ على تطبيقها في رعيته.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1593","text":"ربما بثَّ الآباء في آذان الأبناء قولًا مشحونًا بالحكمة والضياء، ونثروا عليهم من النصح ما لو عقلوه لنجوا من الشقاء، لكنّهم لم يدركوا معانيه إلا بعد أن مسّهم البلاء، فيا أيها الآباء، اعذروا أبناءكم، فبعض دروس الحياة لا تُقرأ في الكتب، ولا تُفهم بالعقل المجرد، بل تُتلى على صفحات التجارب، ويُشرح معناها بمداد العناء.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1594","text":"تركُ المهارات يُضعف القدرات. فداومْ على ما تُتقن، وجدِّد مهاراتك، فإنَّ القدرة تُولد من الممارسة، وتموت بالإهمال.","kind":"hikma","topic":"النجاح والإبداع","note":"خلاصة قصة (العصفور الذي نسي الطيران)؛ له صيغة أخرى","source":"شذرات (ملف وورد)"},{"id":"m1595","text":"بالحواسّ يدرك العقل ما حوله، وباللسان يُفصح عمّا وعاه. فحركةُ الحواسّ من الخارج إلى الداخل، وحركةُ اللسان من الداخل إلى الخارج؛ تلك تجلبُ المعنى، وهذا يُخرجهُ إلى الوجود.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1596","text":"حركة الحب عند الرجل من الداخل إلى الخارج، وحركته عند المرأة من الخارج إلى الداخل، فالرجل يمنح الحب، والمرأة تتلقاه.","kind":"ghazal","source":"شذرات (ملف وورد)"},{"id":"m1597","text":"المرأة تُفضِّل الحب المعلن على الحب المكنون، فهي لا تكتفي بالإحساس، بل تريد اللمسة واللفظة والنظرة.","kind":"ghazal","source":"شذرات (ملف وورد)"},{"id":"m1598","text":"والنجاح في الحياة الزوجية أشبه بـ البندول، لا بد أن يُسمِعها كلَّ أربع ساعات كلمةً أو يُريها تصرفًا يحمل في طيّاته نبض الحب ودفء المودة.","kind":"ghazal","source":"شذرات (ملف وورد)"},{"id":"m1599","text":"مفاتيح أبواب الرزق: ١- سؤالُ الله تعالى ودعاؤه بإلحاح. ٢- الأخذُ بالأسباب مع صدق التوكل. ٣- كثرةُ الاستغفار، فهو يمحو الذنوب ويجلب الأرزاق من علام الغيوب. ٤- صلةُ الأرحام، فإنها سبب في بسط الرزق وطول العمر. ٥- الإنفاقُ في وجوه الخير، فالعطاء باب يجلب العطاء. ٦- البعدُ عن المعاصي، فالمعصية تُغلق أبواب البركة. ٧- أداءُ الأمانة، والصدقُ في المعاملة. ٨- برُّ الوالدين، ودعاؤهما من مفاتيح الرزق. ٩- التوكلُ الصادق مع الرضا بالمقسوم. ١٠- السعي في أول النهار ( اللهم بارك لأُمتي في بكورها ) ١١- الأمانة غنى، لأن من اشتهر بالأمانة، كثر زبائنه، وصاروا يروجون له.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1600","text":"تداركُ تقصير الصمت أيسر من تقصير النطق.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1601","text":"حفظ ما في يديك أولى من طلب ما في يَدَيْ غيرك.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1602","text":"مرارة الحرمان خير من ذِلة الطلب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1604","text":"صدرُك أحفظ لسِرِّك، فلا تُفْشِ سِرَّك لغيرك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1605","text":"من أكثر أهْجَرَ، ومن تفكر أبصر.","kind":"hikma","topic":"الكلام والصمت","note":"أهجر: هذى","source":"شذرات (ملف وورد)"},{"id":"m1606","text":"صاحب أهل الخير تكن منهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1607","text":"اترك الشرَّ يتركك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1608","text":"اترك اهل الشرَّ فلا تكن منهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1609","text":"بئس الطعام الحرام، فهو بوابة للنار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1610","text":"العقل حفظ التجارب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1611","text":"التاجر مُخاطر، والمتاجرة مُخاطرة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1612","text":"من يأتي الحكمَ وحده يَثْلُج.","kind":"mathal","topic":"العقل والحكمة","note":"أثلج الأمرُ صدرَه: أسعده وأفرحه","source":"شذرات (ملف وورد)"},{"id":"m1613","text":"إذا خلطت بين الإحسان والإساءة، فاحرص على أن يكون الإحسان آخرا، وأكثر من الإساءة كما وكيفا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1614","text":"ذَبْحُ الرجلِ ذكر مناقبه ومدحه وتزكيته في وجهه.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1615","text":"أبلغ الجواب ما كان حاضرا، مع ابراز المعنى وإيجاز اللفظ، وبلوغ الهدف، فيكون حسما للمعارضة والمجادلة","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1616","text":"من ظن بك خيرا فصدق ظنه أو بعضه، ولا تُقنطه من جودك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1617","text":"لا يكن أهل بيتك أشقى الناس بك، فتكن لئما.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1618","text":"العاقل يتعظ بالآداب، والبهائم لا تتعظ إلا بالضرب على الإيهاب.","kind":"hikma","topic":"العقل والحكمة","note":"الإيهاب: الجلد","source":"شذرات (ملف وورد)"},{"id":"m1619","text":"الهوى شريك العمى، فلا يميز بين الخير والشر.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1620","text":"ليس كل من رمى أصاب، وليس كل من قال صدق. وليس كل من أحب نال.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1621","text":"اشتكى استاذ جامعي إلى مدير الجامعة: بأنه رأي حمارا يدخل من باب الجامعة، فقال المدير: دخول الحمار في الجامعة لا يُسبب مشكلة، لكن خروج الحمار من الجامعة هو المشكلة بعينها.","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1622","text":"الدجاجُ المعاصرُ صناعيٌّ أكثرُ منه طبيعيّ، شأنُهُ شأنُ كثيرٍ من المأكولاتِ اليوم، وهي ظاهرةٌ مؤسفةٌ تُلقي بظلالِها السلبيةِ على صحّةِ الإنسان: النفسية والبدنية.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1623","text":"قال رجلٌ لزوجته: خلقكنَّ اللهُ جميلات، لكنكنَّ ناقصاتِ عقل. فابتسمتْ وقالت: خلقنا اللهُ جميلاتٍ لتميلوا إلينا، وناقصاتِ عقلٍ لنميلَ إليكم، فتكتمِل الأُلفة والمحبّةُ بين الطرفين.","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1624","text":"( 14 ) شيء كثيرها كثير وقليلها كثير النار والمرض والعدو والدَّين والملح والفلفل والسم والشرك والسكر والدواء والإهانة والعقوق وغدر الصديق والبوز على الريق.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1625","text":"المشقة في تنظيف البيت ليست إلا دليلاً على نعم الله التي تحيط بنا. الأواني المتسخة تعني أننا وجدنا ما نأكله، وغرفة المعيشة التي تحتاج كنسًا تدل على اجتماعنا حول مائدة واحدة. وغرف الأطفال التي نرتبها تشهد على ضحكاتهم ومرحهم، والمطبخ الذي تفوح منه رائحة الطعام يثبت أننا نطعم أبناءنا. حتى الأطباق في الحوض تحكي قصة أطفال ناموا شبعى، وغرفة الضيوف التي رتبناها تومئ إلى لقاء قريب بأحبابنا. فما نعدّه تعبًا، هو في الحقيقة نعمة تستحق الشكر، والبيت الذي لا يحتاج ترتيبًا وجهدا، قد فقد بعض الضروريات والحاجيات، وشيئًا من الأنس والفرح والمسرات.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1626","text":"تهادوا بالورود والريحان، فالوردُ يشرحُ الصدور بشذا يفوقُ البخور وينشرُ في النفسِ سرورًا ويكسو الأيّامَ حُبورًا ويُحيي القلبَ نورًا ويطردُ الهمَّ دُحورًا ويبعثُ في الروحِ حضورًا ويجعلُ العيشَ سرورًا","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1627","text":"دخل الزوج على زوجته وهو في غاية الحزن والكآبة، فقالت له: سلامات! خير إن شاء الله، قال لها بصوت حزين: ضاع الحمار، فقالت له: لا تحزن، فوالله لدخلتك علينا سالما أحسن من ألف حمار.","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1628","text":"احذر دعوةَ المظلوم، فإنها تُرفع بين السماء والأرض بلا حجاب.","kind":"hikma","topic":"الإيمان والعبادة","note":"في معنى حديث نبوي","source":"شذرات (ملف وورد)"},{"id":"m1629","text":"لن تستطيع أن تخدع جميع الناس في جميع الأوقات.","kind":"hikma","topic":"العلاقات والناس","note":"قول مشهور يُنسب إلى أبراهام لينكولن","source":"شذرات (ملف وورد)"},{"id":"m1630","text":"قاموس الحب والإعجاب للشباب المقبلين على الزواج: وجهك منور، عيونك ذباحة، شعرك يجنن، ريحتك حلوة، جسمك يعجبني، مشيتك تفتن، صوتك موسيقى، ابتسامتك حلوة، خدودك تفاح، نظرتك تسعدني، أسلوبك رقيق، كلامك عسل، ضحكتك تجنن، عقلك كبير، قلبك طيب، رقتك حنان، أخلاقك راقية، أحبك من قلبي، ما أستغني عنك، وجودك راحة لي، أنتِ حياتي، جمالك مستحيل، يا جميلة، تسلمين يا غالية، طبخك لذيذ، لمساتك رقيقة، ترتيبك ذوق، ذكية ونبيهة، الله يحفظك، أنتِ بركة بيتنا، ما قصرتي، خَسَّيْتِ، يا بعد قلبي، يا روحي، يا عمري، يا أجمل هدية، يا ألطف إنسانة، يا عيوني أنتِ","kind":"ghazal","source":"شذرات (ملف وورد)"},{"id":"m1631","text":"سبحان من جعلك تُبصر بشحم، وتسمع بعظم، وتتكلم بلحم، وتنبض بعضلة، وتفكر بمضغة، وتتحرك بعصب، وتُرزق من غير حولٍ ولا طول، وتُحاط بنِعَمٍ لا تُعدّ ولا تُحصى، وتُحفظ بعينٍ لا تنام، وتُستر بسترٍ لا يُرام، وتُمهل على زلل، وتُوفّى على عمل، وتُسقى بماءٍ عذب، وتُغذى برزقٍ عجب، وتُكفى الشرّ قبل أن يقع، وتُرحم قبل أن تضرع، يا أكرم الأكرمين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1632","text":"فلسطين اليوم تدفع ثمن الأمس؛ يومَ تقاعست الجيوش العربية والإسلامية والجامعة العربية عن نصرة المستضعفين، في أفغانستان والبوسنة وفي بقاع الأرض، بجميع أنواع النصر، فأصبح الطريق ممهّدًا لهذه الكارثة وغيرها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1633","text":"قُدراتُ الناسِ تَختلِفُ في الفَهمِ والاستِيعابِ للأُمورِ، ومِن فِقهِ العالِمِ أنْ يُحدِّثَ كلَّ فَرْدٍ وكلَّ جَماعةٍ بما تَستوعِبُه عقُولُهم ولا تَنفِرُ منه أفهامهم.","kind":"hikma","topic":"الكلام والصمت","note":"جاءت شرحًا لأثر علي رضي الله عنه: حدثوا الناس بما يعرفون، وقد تكون منقولة من شرح","source":"شذرات (ملف وورد)"},{"id":"m1634","text":"بعض صور المقاطع الشنيعة في التواصل الاجتماعي ما ودك أن تُرسل وتظهر، لأنها تُحزن نفس الإنسان، وتجلب الأحزان، وتُؤلم الجَنان، بمجرد أن تُبصرها العينان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1635","text":"مهارة التذكر: استخدم التكرار الذهني الواعي: حين تضع المفتاح في مكان ما، قُل لنفسك بتركيزٍ وسكون: “وضعت المفتاح على الطاولة”مثلا، فالكلمة المسموعة تُثبّت الفعل في الذاكرة كما يُثبّت الختم على الورقة. استعن بحاسةٍ أخرى تُعين الذاكرة على التوثيق: المس الشيء أو تأمّله بعينيك لحظة وضعه، فالحواسّ إذا تعاونت تآزرت، وإذا تآزرت أثمرت، فيرسخ المشهد في الذهن رسوخ النقش في الحجر.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1636","text":"العمر قصير، والرب كبير، والناقد بصير، فلا تُهدروا الأوقات فيما لا ينفع ولا يجلب الخير الكثير. فكم من الناس يضيعون الساعات الطوال في تتبع الأخبار أو الفن أو الرياضة، بينما يغفلون عن عبادة الرحمن، وقراءة القرآن، وذكر الله المنان، وفعل الخيرات والمعروف قبل الممات.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1637","text":"إذا أردت أن تعرف نِعم الله عليك: زُرْ المقابر لتعرف نعمة الحياة. زُرْ المستشفيات لتعرف نعمة الصحة. زُرْ السجن لتعرف نعمة الحرية. زُرْ عيال القاضي لتعرف نعمة الأسرة والعائلة والأرحام والأصهار والقبيلة. زُرْ معهد الصم والبكم والعمي لتعرف نعمة جواهر الوجه. زُرْ الأيتام والأرامل والفقراء لتعرف نعمة المال. زُرْ المجانين والمعتوهين لتعرف نعمة العقل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1638","text":"انظروا إلى من دونكم في الدنيا، وانظروا إلى من فوقكم في الدين، فحري أن تشكروا الله وتستغفروه.","kind":"hikma","topic":"الإيمان والعبادة","note":"مستوحى من معنى حديث نبوي","source":"شذرات (ملف وورد)"},{"id":"m1639","text":"الطفل في مرحلة الاستهواء السلوكي، والتفهيم والتلقين والتوجيه، وليس في مرحلة تبني الآراء والنقاش.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1640","text":"اطلب من أبيك الإرشادات، تنفعك في الحياة وبعد الممات. اطلب من أُمك الدعاء يرفع الله قدرك في الأرض وفي السماء. اطلب من العلماء الفقه في الدين، يقربك من رب العالمين.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1641","text":"اعتذارك عن الخطأ يرفع قدرك، وتقبلك لأعذار الآخرين دليل أدبك، والتغاضي عن الزلات سماحة نفس، ومراعاة المشاعر كمال خُلق، وصون الود وفاء. وما تقدمه من خير يعود إليك أضعافًا، فلا تحرم نفسك جمال الأخلاق وحسن التعامل، فتُحرم بركتهما.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1642","text":"سأجلس ساعة من الزمان، أتأمل ماضٍ كان، حين كنت في كنف أمي وأشعر بالأمان، أيامٌ مضت كالحلم تلاشت كالدخان، لكن الرزق لا يأتي للكسلان، فلابد من السعي بعزم وإتقان، فالكسل بابٌ للخسران، والعمل طريقٌ للمجد والاطمئنان.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1643","text":"من رحمة الله وعدله أنه لا يُؤاخذ العبد على مشاعره التي لا يملك دفعها، فلا عذاب بدمع العين ولا بحزن القلب، بل الحساب على ما ينطق به اللسان ويستقر في الجَنان، فالكلمات مَوزونة، والنيات مَحسوبة، والعبد بين رحمة الله أو عقابه، بحسب اختياراته وترجيحاته.","kind":"hikma","topic":"الإيمان والعبادة","note":"تعقيب على حديث","source":"شذرات (ملف وورد)"},{"id":"m1644","text":"سأل أحدهم أبا بدر: ماذا تفعل بعد التقاعد؟ فأجاب: أعمل في معالجة المياه، وتحسين جودة الزجاج والألمنيوم، ومعادن أخرى، تحت إشراف خبراء مختصين. ومراقب للتيارات والطاقة الكهربا ئية، والشبكات والتدفقات المائية. فقال السائل: ما شاء الله، تبارك الله، لقد غلبتنا يا أبا بدر. وبعد قليل، ذهب الأب لبعض شؤونه، فسأل الرجل ابنه: ماذا يعمل والدك الآن؟ فأجاب: يغسل الصحون مع أمي، ثم يتمم على الأنوار والصنابير.","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1645","text":"الشيء قد يكون بسيطا، لكن طريقة العرض والوصف تصنع الفروق الشاسع، بين الحقيقة والخيال.","kind":"hikma","topic":"الكلام والصمت","note":"خلاصة قصة ملء الفراغ بعد التقاعد","source":"شذرات (ملف وورد)"},{"id":"m1646","text":"كانت رائعة الجمال، في ريعان الشباب، فتقدَّم لها من قومها ثريٌّ مليٌّ أجنبي، فَسَأَلَتْهُ عن عمره، فقال: سبعون! فوافقت. فلما تزوَّجته، اكتشفت أنه في الخمسين، فثارت وغضبت، وطلبت منه الطلاق، إذ لم تكن تهوى شخصه، بل ترجو رحيله وميراثه!","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1647","text":"المقارنات تكشف الحقائق البينات: تطبخ في بيتها، مستعبدة، تطبخ في المطاعم حرة عاملة. تربي أبناءها مقيدة بالتقاليد، ترعى أبناء الحضانة، مستقلة مساهمة. تنظف بيتها مسحوقة، تنظف في الفنادق وغيرها مكافحة. تتحجب مكبلة. تتبرج متحررة. يقوم زوجها بنفقتها، ضعيفة، تكافح وتنفق على نفسها مستقلة. تبتعد عن الاختلاط، متخلفة، تختلط وتتأذى متقدمة. هذا ما أراده الإسلام للمسلمة، وما يراد لها باسم الحرية والديمقراطية.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1648","text":"المسلمون لا يكرهون غير المسلمين المسالمين، بل يرجون لهم الهداية. وهم يكرهون الظلم وأهله، أيًّا كان دين الظالم، فلا يحابون مسلمًا بظلمه، ولا يجحدون عدل غير المسلم بإنصافه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1649","text":"في أوائل شهر رمضان سترون وجوها جديدة في المساجد، فتبسموا في وجوههم، ولا يرون في وجوهكم الاستنكار أو الاستغراب، ولا تسألوهم أين كُنْتُم وما نراكم في المساجد إلا في شهر رمضان، فلا تعاتبوهم ولا تسخروا منهم، واحمدوا الله على نعمة الهداية.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1650","text":"المؤمن حقًا لا يضعف عزمه ولا ينهار يقينه، فهو بالله قوي، وبه منتصر، ومن استعان بربه أعانه، ومن توكل عليه كفاه. لا ييأس من روح الله، ولا يقنط من نصره، فمن سعى بصدق وجِدٍّ، وعلى قدر النية والجُهد يكون العون، وعلى قدر العزيمة يكون الجزاء، سواء أأدرك غايته أم لم يدركها، فحسبه شرف السعي، وأجر الاجتهاد، ورضا رب العباد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1651","text":"بلغ بدر العشرين ربيعا، فاستيقظ ذات صباح يتمطَّى، فسألته أمه: ما بك؟ قال: أريد الزواج. فزوجوه. لم تمضِ إلا أيام حتى لاحظت أخته نادية تغيره العجيب؛ تهذّبت أخلاقه، وانضبطت مواعيده، وحسن مظهره وسلوكه. وبعد حين، استيقظت نادية تَتَمَطَّى، فسألتها أمها: ما بك؟ فأجابت مبتسمة: فيَّ مثل الذي في أخي بدر. ففهمت أمها مرادها فزوجوها.","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1652","text":"خريف العمر أقبل، وربيع الشباب أدبر، فبتنا نغفو بلا اختيار، ونمشي بخطاً بلا اقتدار، فأدركنا أننا قد كنا في نِعم عظيمة، وهبات جسيمة. فالصحة أدبرت وولَّت، والأمراض أقبلت وحلَّت، فالحياة ماضية، والآجال آتية، وباب التوبة مفتوح، والاستغفار مطروح، فالسعيد من بادر بالصدقات، وعمل الصالحات، لينال حسن الخاتمة، والسعادة الدائمة.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1653","text":"العواطف والمشاعر خادم مطيع إن ضُبطت وكانت في موضعها، وسيد جائر إن تَحَكَّمت ولم تكن في موضعها.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1654","text":"عندما تُروض الحصان، تتعامل معه باللطف واللين، فإذا استجاب لك تُكافئه بجزرة أو سكرة، وإن لم يستجب ترفع السوط، أو تضربه ضربة خفية ناعمة. ومن باب أولى وأجدر أن تتعامل مع الإنسان، باللطف واللين، وإن خاشنك فلا تخاشنه، بل ادفع بالتي هي أحسن، فيصبح العدو صديقا، والنافر أليفا، والخشن لطيفا.","kind":"hikma","topic":"العلاقات والناس","note":"تحت عنوان: ادفع بالتي هي أحسن فيصير العدو صديقا","source":"شذرات (ملف وورد)"},{"id":"m1655","text":"الذكر هو روح العبادات والطاعات.","kind":"hikma","topic":"الإيمان والعبادة","note":"من قائمة فضائل ذكر الله تعالى","source":"شذرات (ملف وورد)"},{"id":"m1656","text":"الفلوس تُسعد النفوس، وتذهب العبوس، وترفع الرؤوس، وتُضحك الضروس، وتظفر بالعروس، وتزين الملبوس، وتبعد النحوس، وتكثر الثمار في الحقول بالفؤوس، وتكثر المواشي في الحضائر والجاموس، وأفضلها ما كان من حلال، وبُذل في الطاعات والقربات.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1657","text":"بداية الكمال البشري هو: عدم ارتكاب الكبائر، والاستغفار بعد الصغائر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1658","text":"يا من تبنون ثرواتكم على مآسي المنكوبين! أتسرقون قوت الجائعين، وتتاجرون بعذابات المكروبين؟ أما تخشون دعوة المظلومين، وعذاب رب العالمين؟ إن كان ضميركم قد مات، فعدالة رب السموات، سوف تنتقم منكم على جميع التجاوزات.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1659","text":"الأمانة رأس مالنا، والمال يُعوض، أما السمعة فلا تُعوض.","kind":"hikma","topic":"الأخلاق والآداب","note":"على لسان تاجر كويتي في قصة عن أمانة التجار الكويتيين","source":"شذرات (ملف وورد)"},{"id":"m1660","text":"من طال عمره إن سلم من الأسقام لم يسلم من الهرم، والهرم داء لا دواء له.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1661","text":"لا تُطِلْ الموعظة، فإن الكلام يُنسي بعضُه بعضا، وليس لك من موعظتك إلا ما فُهم وحُفظ عنك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1662","text":"أكثر الناس طاعة أشدهم للمعصية كرها.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1663","text":"للكون ربٌّ عظيم حكيم، يقوم عليه بحسب علمه ومشيئته وقدرته، وهو متصف بكمال الحلم والرحمة، ورحمته غلبت غضبه، وحلمه سبق عقابه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1664","text":"ما أبلغ لغة الضاد والأضداد.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1665","text":"نشر الضلال والفساد في الأرض، ثمرة الإعراض عن دين الله وهدايته، فكما تدل الثمرة على الشجرة. فالضلال ثمرة الإعراض عن آيات الله الكونية والقرآنية، الدالة على وحدانيته وكماله وتنزّهه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1666","text":"كلما أوجدت بابا من أبواب الرزق، أغلقت بابا من أبواب السجن. كلما كفيت عددا من الفقراء وأصحاب العوز، قللت عدد نسب الجرائم والسجون. كلما يسرت شروط الكسب وسهلتها، قللت نسب الجرائم، ولم تحتج إلى زيادة السجون.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1667","text":"إذا جلستَ في مجلس واحتدم الحديث عن جيوش الدول وقوتها، وعن العتاد والسلاح وما تملكه من بأس، فذكّرهم بعظمة الله الذي بيده ملكوت كل شيء، وبطشه الذي لا يُرد، وكبريائه الذي لا يُجارى. قل لهم: إن الدنيا بما فيها، بجيوشها وأساطيلها، بجبروتها وقوتها، لا تزن عند الله جناح بعوضة. أخرِج من قلوبهم رهبة المخلوق، واملأها بعظمة الخالق، القوي المتين، الجبار المتكبر، الذي إذا أراد شيئًا قال له: كن فيكون.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1668","text":"المرأة العاقلة الرزينة، إن أرادت أن تنعم بجنة الدنيا في حياتها الزوجية، وجنة الآخرة، فعليها بسباعية السعادة: سايريه بحكمة، ياسريه بلطف، ساهليه بكرم، سامحيه بجود، سانديه بثبات، ساسريه بحب، وسلفيه بجميل العطاء. فبهذه السباعية، تُبنى البيوت، وتدوم المودة، ويهنأ العيش.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1669","text":"يمدح الناس اليابانيين لإبداعهم في صناعة السيارات، مع أن أيديهم لا تصنعها مباشرة، بل الآلات هي التي تقوم بذلك، غير أن الفضل يعود إليهم لأنهم هم من صنعوا تلك الآلات. وكذلك الإنسان، آلة مُسخّرة بعقلٍ وجوارح، ولكن خالقها هو الله. فكل إبداع يصنعه الإنسان، وكل إنجاز يحققه، فالله أحق بالثناء والمدح، فهو الذي خلقه، وأودع فيه العقل والإرادة والقدرة على الإبداع.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1670","text":"تخيّلوا شركة ترسل جهازًا بالغ الأهمية لتوليد الطاقة، وتبعث معه دليلًا يشرح تفاصيل تشغيله وصيانته، ثم ترسل مهندسًا خبيرًا ليُبيّن لهم كيفية استخدامه على الوجه الصحيح. الجهاز هو الإنسان، والكتاب هو القرآن، والرسول هو الهادي لتطبيق ما في القرآن، ولله المثل الأعلى، ولقوله وكتابه ورسوله الإيمان والتوقير.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1671","text":"المتر مقياس الأطوال، واللتر معيار الأحجام، والكيلوغرام مقياس الأوزان، والسنة النبوية ميزان الأعمال. فالنبي صلى الله عليه وسلم هو الأُنموذج البشري الكامل، في جميع الأخلاق والصفات والشمائل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1672","text":"عقول الدهماء مولعة بتصديق الغرائب والعجائب، ولو كانت باطلة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1673","text":"بعض الشعوب مولعة بتقديس عظمائها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1674","text":"احترام التخصص واجب علمي، وفريضة عقلية. لا تأخذوا عن النجار حديثه في الحدادة، ولا عن الحداد رأيه في النجارة. ولا تصغوا إلى الطبيب في شؤون الهندسة، ولا إلى المهندس في أمور الطب. ولا تركنوا إلى المثقف حين يخوض في الدين والفقه، فإنه كحاطب ليل، يجمع مع الحطب العقارب والثعابين.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1675","text":"الحقيقة بنت البحث، المعرفة بنت التجربة، نمو العقل بزيادة المعرفة، الصواب ابن الخطأ، اليقين ابن الشك، اللغة بنت الاجتماع، السياسة بنت الاقتصاد، الاقتصاد ابن العمل، العمل ابن الصحة، الصحة بنت الاعتدال والنظافة والوقاية.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1676","text":"إن شعرتِ بأن زوجكِ يسعى للتنصل من مسؤولياته وإلقائها على عاتقكِ، فتسلحي ببعض كلمات حاسمة: لا أعلم – لا أُحسن – أخاف - وما شاكلها.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1677","text":"الذكاء ليس في الهروب من المشكلة فقط، بل في تحويلها إلى وسيلة للخلاص.","kind":"hikma","topic":"العقل والحكمة","note":"عبرة قصة: ذكاء الحمار الذي سقط في البئر","source":"شذرات (ملف وورد)"},{"id":"m1678","text":"في زمن الغوص، قبل اكتشاف البترول، عمّ الفقر والعوز. جلست بعض النساء عند أبواب المساجد وأطراف السوق يلتمسن العون، فقبض عليهن الشرطة لمخالفتهن قانون منع التسول. سُئلن عن أسمائهن، فتملصن بأسماء مستعارة، حتى قالت إحداهن مازحة: “اسمي قماشة، وسويتونا طماشة، وكل واحد يعطيني من معاشه!” فضحك الشرطة وأطلقوا سراحهن.","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1679","text":"الوتساب والتويتر للنتف والشذرات، والقراظات والتغريدات، لا للرسائل والمذكرات، والكتب والمطولات.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1680","text":"من فعل ما لا يُرضي ربه، لقي ما لا يُرضي نفسه.","kind":"hikma","topic":"الأخلاق والآداب","note":"عبرة قصة اللص والأبناء الخمسة","source":"شذرات (ملف وورد)"},{"id":"m1681","text":"بعض النساء، مع طول العِشرة، يغفلن عن اللطافة واللباقة، ويتخلين عن الرقة والحياء، فتفقد مشيتهن وضحكتهن وعاداتهن اليومية شيئًا من الأنوثة، حتى يصبحن أقرب إلى الجفاء دون أن يشعرن. ثم يشتكين: “زوجي تغيَّر، لم يعد كما كان، غاب القرب والدفء والإعجاب.” على الزوجة أن تصون أنوثتها، وتحافظ على رقتها ونعومتها، وسحر كلماتها ونظراتها، وعذوبة صوتها وخطواتها، في كل شأن من شؤونها، لتبقى في عين زوجها كما كانت، مصدرًا للحب والإعجاب.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1682","text":"الابتسامة: تحية عالمية، وفاكهة اللقاء، وبريد المودة، وخِطبة تعارف، وتجلب ابتسامة، وعرض صداقة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1683","text":"ابتسامتك في أحزانك صبر وتجلد، وفي أحزان غيرك فرح وشماتة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1684","text":"التمر في البئر","kind":"mathal","topic":"النجاح والإبداع","note":"أي أن جودة ووفرة التمر تعتمد على الجهد المبذول في سقي النخيل؛ يضرب هذا المثل للتأكيد على أن النتائج مرتبطة بمدى الاجتهاد في العمل.","source":"شذرات (ملف وورد)"},{"id":"m1685","text":"الاختلاف في الرأي عند العقلاء لا يُفسد في الود قضية، ولا يمنع من الابتسامة والتحية، والمشاركة في اللقمة الهنية، والمرافقة في الأسفار والطلعات البرية، والمجالسات في الدوانية، والمشاركة في الأحاديث الندية، وبقاء الصداقات والأخوية.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1686","text":"القرابات أولى بالصدقات: الخوال والخالات، والعمام والعمات، وأولادهم وهَلُمَّ جَرَّا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1687","text":"شهر الصيام محطة تغيير إيجابي، يسمو فيها الإنسان إلى التقوى والكمال.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1688","text":"لا تجعلوا النصيحة في الوتساب، مكرورةً كل جمعة، فإن التكرار بلا تجديد جمودٌ للبيان، وليس من الابتكار، ولا من شأن أهل العرفان، ولا من شِيَم الأحرار والفرسان.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1689","text":"كثير مما يعجّ به الواتساب ترهاتٌ ونفايات، وتكرارٌ ومعادات، ودردشاتٌ هزيلة، ومضيعة للأوقات الثمينة. انقلوا من الكلمات ما هو دررٌ نفيسة، ومن قراضات الذهب ما هو خالصٌ مصفى، ومن الحكم ما هو نورٌ يستضاء به، ومن الأمثال ما هو نادرٌ بليغ، ومن القصص القصيرة ما يحوي العبر والمواعظ، ومن الأخبار ما هو مهمٌّ ومستجدّ.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1690","text":"شغل دماغك قبل ما تشغل أعضاءك وذراعك.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1691","text":"إذا أردت حسن التدبير، فعليك أن تبدأ بالتفكير. إذا أردت النجاح، فعليك بالجد والسعي والكفاح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1692","text":"الله أرحم بعبده من الأم بوحيدها","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1693","text":"لا تبكِ على اللبن المسكوب","kind":"mathal","topic":"الصبر والشدائد","note":"أي أن الشخص يجب ألا يُضيع وقته وجهده في التحسر على ما فات، بل ينبغي له أن يتقبل الواقع كما هو ويمضي قدمًا.","source":"شذرات (ملف وورد)"},{"id":"m1694","text":"قبل أن تخطو الخُطوة، فكر بالعقبى.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1695","text":"لن تنال الرفعة والمجد إلا ببذل السعي والجَهد.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1696","text":"لا تُسابق بلا تدبر واتزان، فلن تنال إلا الخسران.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1697","text":"عامل صهرك بالمودة والإكرام، لا بالخشونة وعدم الاحترام، لأن ما تفعله معه ينعكس على ابنتك، فِلْذَةُ فؤادك، وزهرة بستانك.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1698","text":"يمتاز الفقه الإسلام بالتيسير، وينفر من التعسير، لأن التيسير أحرى بالدوام، والتعسير أحرى بالانفصام.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1699","text":"من حكمة الله الحكيم الرحيم، أنه لولا حَرُّ الشمس لهلك من على الأرض، جميع الأحياء، لأن الله جلت حكمته وقدرته ورحمته، جعل حرها سببا في تكوين السحاب ثم هطول الأمطار، وجريان الأنهار، ونمو الأشجار والأزهار، والحبوب والثمار، فالله جعل من الماء كل شيء حي، فالحمد والشكر لله على هذه النِّعم الجليلة العظيمة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1700","text":"أساليب تربوية ناجحة للأطفال: اسلوب العرض والاختيار والحوار، لتنشيط الفكر، والاعتماد على النفس، وحرية القرار: تريد تلبس القميص الأبيض أو الأصفر. تريد تحمل حقيبة الجلد أو القماش. تريد تأكل بيضة أو جبنة. تريد نذهب الحديقة أو البحر. تعامل معه على هذا المنوال، وافتح معه مناقشة وحوارا، لتقوي شخصيته، وتشعره بأهميته واستقلاليته، وتجعله يُعمل فكره، ويرجح رأيه، فيسبق أقرانه وعصره.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1701","text":"الحوار المناسب والدائم مع الأطفال هو بوابة النجاح ومفتاح تطور العقل، فمن خلاله يتعلم الطفل كيف يفكر، وكيف يبني الجمل البسيطة، وكيف يرد ويُقنع، وكيف يفهم ويجيب، بل وكيف ينتصر بالحجة والمنطق. وبهذا الأسلوب، يتدرب على التفكير العميق، وصياغة العبارات، وإتقان فنون النقاش، إلى جانب اكتسابه مهارات شتى، وكل ذلك يؤهله للنجاح والتفوق، أولًا في دراسته، ثم في حياته الخاصة والعامة.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1702","text":"من رفع رأسه عن الوسادة، نال الرفعة والسيادة. من تجافى جنبه عن النوم، تقدم على القوم. من اجتهد في العمل، حقق الأهداف والأمل.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1703","text":"جنِّبوا الواتساب ما يزرع الشقاق ويؤجِّج النزاع، وما يفسد الودَّ ويمزِّق الوفاق، من سبابٍ وعنفٍ وسوء أخلاق، وألفاظٍ جافيةٍ غليظة، ومعانٍ سقيمةٍ ووضيعة، وخشونةٍ رعناء، ورعونةٍ عمياء، وسفاهةٍ هوجاء، وأظافرَ هرٍّ عابثة، وكلماتٍ هزيلةٍ وهابطة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1704","text":"التوازن مطلوب، فالإخفاء يعزز الإخلاص، والإظهار ينشر الخير إذا خلت النية من الرياء.","kind":"hikma","topic":"الإيمان والعبادة","note":"خلاصة مقارنة بين الإسرار والإظهار في الطاعات","source":"شذرات (ملف وورد)"},{"id":"m1705","text":"متاع الدنيا قليل، والذي بقي منها قليل، والذي لك منها قليل، وقليلك أقل القليل، فأشغل نفسك بما قال الله وقال الرسول، ودع عنك القال والقيل، فكله ضئيل، وإلى زوال يفنى ويزول.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1706","text":"إن الله تعالى أمرنا بالصلاة والسلام على نبيه محمد صلى الله عليه وسلم، والنبي بين لنا كيف نصلي عليه، فليس من المعقول في العقول، أن ندع الفاضل ونأخذ بالمفضول.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1707","text":"عصر الوتساب عصر يُحير أُولي الألباب، لأن الأخبار تأتيك من كل الجهات والأبواب، ولا تخلو من الاختلاف والتناقض والاضطراب، فالعاقل من يميز بين الغث والسمين، وكلام المزور وكلام الصادق الأمين.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1708","text":"أقيلوا ذوي المروءات عثراتهم، فإن قطرة بول الطفل الرضيع، لا تنجس المحيط الهادي الفظيع.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1709","text":"الرجل يقوم بأعمال شاقة: كالحفر والبناء وحمل الحجارة وغير ذلك، من أجل أن يوفر لأهل بيته: الضروريات والحاجيات وبعض الكماليات، ويضمن لهم حياة كريمة وسعيدة، فهو يشعر بسعادة غامرة، عندما يسعد أولاده وأهل ببته.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1710","text":"فيا ابن آدم لا تغتر، فالأيام دُوَل، فيوم لك ويوم عليك، يوم صحة ويوم سقم، يوم نشاط ويوم فتور، يوم اجتهاد، ويوم كساد، وخير الناس للناس، من بذل خيره للناس، وكف شره عن الناس.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1711","text":"نظرية التدافع تعني التوازن بين القوى المتعارضة في الدول أو في المجتمع، لمنع الفساد والاستبداد، وتحفيز التطور والإصلاح، التدافع يحدث في القوة والفكر والسياسة والاقتصاد، وسائر مجالات الحياة، وهو سنّة كونية تحفظ الاستقرار وتدفع نحو التقدم والازدهار.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1712","text":"من السنن الشرعية والآداب الاجتماعية مراعاة خواطر الناس، وإدخال السرور عليهم، عند زيارات ولقاءات الأقرباء والأصدقاء، فيحسن عدم المبادرة بصيام الست من شوال في أول الشهر، حتى يجتمع الأقرباء والأصدقاء على مائدة الطعام والشراب، فإن المؤاكلة تعدل أُخوة الرضاعة، لما فيها من المواددة والمؤانسة، وتجاذب أطراف الحديث، وتبادل الحوار، وإدخال السرور والحبور على ربِّ الدار وذويه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1713","text":"ذهب شبابٌ في رحلةٍ إلى الخفجي لصيد السمك، فوجدوا شبكاً وبوابةً يحرسها رجل بدويٌّ مسنّ، فمنعهم من الدخول إلا بتصريحٍ من المسؤول. أرسلوا اثنين منهم، فعادا بورقةٍ مكتوبٍ فيها: “يُسمح لهم بالدخول.” أخذها الحارس يقلّبها، ينظر فيها، ولا يعرف قراءتها. فناولها أحدهم وقال: “اقرأها.” قرأها الشاب بصوتٍ واضح: “يُسمح لهم بالدخول.” نظر إليهم الحارس وقال بحزم: “ما أفتح!” تعجّبوا وسألوه: “لماذا؟” قال بثقة: “ما فيها: دخل الرجاجيل، قلط الرجاجيل! شنو يعني: يُسمح لهم؟” فرجعوا بخفي حنين، وضاعت رحلتهم بسبب اختلاف اللهجتين، وتفاوت الثقافتين.","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1714","text":"أيها الإنسان خذ حذرك، فسوف ترحل وحيدًا مجردا، تاركًا الدنيا وهمومها، لتلقى الله سبحانه وتعالى بإيمانك وعملك. عندها ستدرك يقينا، أن كثيرًا مما شغلك كان وهمًا زائلا وعرضا فانيا، فطوبى لمن أدرك ذلك مبكرًا، واستعد بالإيمان والأعمال الصالحة، ليلقى الله تعالى بقلب سليم، وعمل صالح ويقين، ولسان طاهر من أعراض المسلمين، ويد نظيفة من أموال العالمين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1715","text":"إذا أخطأ الزوج على الزوجة تبكي الزوجة فيعتذر الزوج، وإذا أخطأت الزوجة على الزوج يغضب الزوج فتبكي الزوجة فيعتذر الزوج، فدموع المرأة سلاح خفي، لها آثار قوية على قلب الرجل الوفي.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1716","text":"ينبغي لك ألا تحتقر الفقير، ولا الغريب، ولا عامل النظافة؛ فهم بشر مثلك، لهم كرامتهم وإن تفاوتت المقامات. عاملهم بما يليق بإنسانيتهم، لا بما تراه من هيئتهم أو حالهم. وأنزِلِ الناس منازلهم، فليس لزامًا أن تعاملهم كما تعامل أباك أو صاحب الجاه والرفعة، ولكن بما تقتضيه المروءة ويأمر به العدل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1717","text":"كل ما تفلَّس، وَدَعْ ما تملَّس.","kind":"mathal","topic":"الصحة والنفس","note":"أي: كل من السمك ما عليه صفاط مثل الفلوس، ودع ما تملَّس مثل اليربور أو الجرجور، لأن الأول أطيب من الثاني في الأكل.","source":"شذرات (ملف وورد)"},{"id":"m1718","text":"سُوسُوا السَّفِلَ بالمخافة.","kind":"mathal","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1719","text":"سلطان غشوم خير من فتنة تدوم.","kind":"mathal","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1720","text":"سُوء الخُلُق يُعدِي","kind":"mathal","topic":"التربية والأسرة","note":"فانظروا مَنْ أصدقاء أولادكم.","source":"شذرات (ملف وورد)"},{"id":"m1721","text":"سماع الغناء يبعدك عن ذكر الله.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1722","text":"السُّكوت أخو الرضا","kind":"mathal","topic":"الكلام والصمت","note":"فأنكروا الباطل برفق، فإن لم تفعلوا فانكروه بقلوبكم.","source":"شذرات (ملف وورد)"},{"id":"m1723","text":"سيد القوم أشقاهم","kind":"mathal","topic":"السياسة والقيادة","note":"لكثرة مسؤولياته وأعماله.","source":"شذرات (ملف وورد)"},{"id":"m1724","text":"سوقنا سوق الجنة","kind":"mathal","topic":"المال والاقتصاد","note":"كناية عن الكساد، لأن سوق الجنة ليس فيه بيع وشراء.","source":"شذرات (ملف وورد)"},{"id":"m1725","text":"سفير السوء يُفسد العلاقات.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1726","text":"الاستقصاء فُرقة","kind":"mathal","topic":"العلاقات والناس","note":"إذا بالغت في المطالبة والمحاسبة، نَفَر منك الناس.","source":"شذرات (ملف وورد)"},{"id":"m1727","text":"لو أطاع الله الناسَ في الناسِ لهلك كل الناسِ","kind":"mathal","topic":"الإيمان والعبادة","note":"لأن كل قوم يدعون على أعدائهم بالهلاك.","source":"شذرات (ملف وورد)"},{"id":"m1728","text":"إذَا العَجُوزُ ارْتَجَبَتْ فَارْجُبْهَا.","kind":"mathal","topic":"العلاقات والناس","note":"رَجَبْتُه إذا هِبته وعظَّمته؛ ومعنى المثل إذا خَوَفَتْكَ العجوز فَخَفْها، لأنها تعلم النواقص والعيوب التي في أهلك وأقاربك، فتعيرك بها فتُخرسك وتُنكس رأسك.","source":"شذرات (ملف وورد)"},{"id":"m1729","text":"واجبنا تجاه كبار السن باختصار: احترامهم، تقديمهم، توقيرهم، مساعدتهم، الاستماع إليهم، تلبية حاجاتهم، الدعاء لهم، وطلب الدعاء منهم، وعدم رفع الصوت عليهم أو تجاهلهم. فبرّهم خُلُقٌ، وخدمتهم طاعة، وكلامهم خبرة وعبرة وتجارب.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1730","text":"يطوف بأمّه في الحج، يحملها على ظهره إحسانًا وبرًّا، فيسأله أحد الصالحين: أتبرّها حقًّا؟ قال: نعم. قال: زوّجها. فدُهش، وإذا بالأم تهمس بحنوّ: يا ولدي، أطع عمّك.","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1731","text":"الزوجان لا يكتملان إلا ببعضهما، كما اكتملت حواء مع آدم عليهما السلام.","kind":"hikma","topic":"الحياة الزوجية","note":"عبرة قصة الابن الذي يحمل أمه في الحج","source":"شذرات (ملف وورد)"},{"id":"m1732","text":"حب الزوجة لزوجها يزدهر بالإعجاب، ويبهت بالعتاب. حب الزوجة لزوجها ينمو بالاهتمام، ويذبل بالإهمال. حب الزوجة لزوجها يزداد باللين والعطف، وينقص بالشدة والعنف. حب الزوجة لزوجها يزداد بالهدايا والسخاء، وينقص بالبخل والجفاء.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1733","text":"جاء. رجل إلى الشيخ الألباني يدَّعي علم الغيب ويطلب مناظرته . فقال الشيخ: أناظرك ولكن بشرط . فقال الرجل : ما هو شرطك؟ قال الشيخ: كيف تعلم الغيب ولا تستطيع معرفة شرطي؟ فانتهت المناظرة .","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1734","text":"الحق أبلج، والباطل لجلج.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1735","text":"الحق يعلو ولا يُعلى عليه.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1736","text":"الحق سيف قاطع، ونور ساطع.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1737","text":"الوتساب ليس قناة إخبارية، أو محطة رياضية، الوتساب سوق أو مجمع تجاري أو جمعية، فيه العطور والذهب، وفيه الفحم والحطب، وفيه الخوخ والرمان وفبه البصل والباذنجان، فالوتساب لجميع الآراء والأحباب، باللين والحب والآداب، وليس للهجاء والسباب، وسوء الأخلاق والآداب، والتعالى ورعونة العتاب.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1738","text":"لا تُسلِّموا قلوبكم لكلِّ بليغ يتكلَّم، ولا تُخدعوا ببريقِ الألفاظِ وزُخرفِ العبارات؛ فكم من كلمةٍ عذبةٍ تُغوي، وكم من نبرةٍ رخيمةٍ تُضلّ. زِنوا القولَ بميزانِ العقل، واعرضوه على نورِ الفطرة، وتعاليم الشرع، فإن وافقها فهو الحق، وإن ناقضها فدعوه، وإنِ التبسَ عليكم الأمر، فالصمتُ وقار، والتبيُّنُ نجاة واعتبار.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1739","text":"من بسط يده بالبذل في مواطن البِر والعطاء، ومواقف الخير والسخاء، ومواسم المعروف وإغاثة المكروب والملهوف، فقد ركب سفائن الشرف، وأدرك معادن الظفر، وعرف من أين تُغنم الغنائم، وكيف تُؤكل الكتف. فطرق أبواب الجنان، وربح تجارةً لا تبور، وأحرز صفقةً لا تغور. وصان أمواله عن أيدي اللصوص، وإفساد السوس، وأثقال المُكوس، وكيد الحسود المنحوس، ونكد الشريك المنكود، فاستراح من غموم القلق، وسِلم من غوائل الغرق، وطاب له الرزق، واطمأن له السبق.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1740","text":"يابن آدم لا تُعاهد الله أبدا، ولا تطلب من أحد أن يُعاهد الله، فإن اُضطُررت فعاهد غير الله، فلأن تغدر بعهد غير الله، خير لك من أن تغدر بعهد الله، لأن ابن آدم متقلب الأطوار، في الليل والنهار، ولا يثبت على حال.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1741","text":"إذا أحسنت فلا تتباها، وإن أسأت فأحسن.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1742","text":"أحسن في الوعد والإنجاز، وليكن إنجازك فوق وعدك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1743","text":"وفاء الكريم فوق وعده، وعقابه دون وعيده، ووفاء اللئيم دون وعده، وعقابه فوق وعيده.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1744","text":"ذُبُّوا عن أعراضكم بأموالكم.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1745","text":"ذَبْحُ الرجلِ المبالغة في مدحه وتزكيته في وجهه.","kind":"hikma","topic":"الكلام والصمت","note":"حتى لا يُصاب بالغرور ويُفتن بالقول المعسول","source":"شذرات (ملف وورد)"},{"id":"m1746","text":"شفيع العاصي توبته. شفيع المذنب استغفاره. شفيع المخطئ إعتذاره.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1747","text":"الرجل الصالح كالشجرة المثمرة، تُرمى بالحجر فترمى بالثمر.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1748","text":"المؤمن كالشمعة تحرق نفسها، لتُضيء ما حولها.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1749","text":"المؤمن كالنخلة، أصلها ثابت، وظلها دائم، وثمرها طيب، ومنافعها متعددة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1750","text":"تُوفي النبي عليه الصلاة والسلام وعامة أُمرائه على الأمصار من بني أُمية، وليسوا من بني هاشم، لأن سيرة النبوة تشريع وليست تنفيعا، وهكذا ينبغي أن تكون سيرة الملوك والأمراء. فتوزيع المناصب حسب الكفاءات لا حسب القرابات. لأن المجتمع مثل الجهاز الكبير، المكون من قطع وأجزاء كثيرة ومتنوعة، فلا يعمل الجهاز بانتظام وجودة وكفاءة، حتى تكون كل قطعة في موضعها الصحيح.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1751","text":"العلماء يطالبون الأمراء أن يكونوا مثل أُمراء السلف الصالح، لكن الناس في زمنهم ليسوا مثل السلف الصالح، وكذلك العلماء ليسوا مثل علماء السلف الصالح، فما هو الحل؟ المسؤولية تقع على عاتق الجميع، فينبغي أن يتعاون الأمراء والعلماء والعقلاء والصالحون، على التناصح والتعاون في الأمر بالمعروف والنهي عن المنكر، بالأساليب الشرعية النافعة والملائمة للعصر والبيئة. ويكون الهدف العملي الواقعي هو: تقليل الشر والفساد، وتكثير الخير والصلاح، فهو أحرى للديمومة وعدم اليأس والانقطاع. فشعارهم: سددوا وقاربوا، وتعاونوا ولا تنافروا، وكونوا عباد الله إخوانا. فمن أراده كله، تركه كله، ومن أراد بعضه، حقق بعضه، وطمع في الزيادة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1752","text":"لا تَشْكُ مَن يرحمك إلى مَن لا يرحمك، فإن الله إذا أحب عبدًا ابتلاه، وقد قال النبي صلى الله عليه وسلم: “أشدُّ الناس بلاءً الأنبياء، ثم الأمثل فالأمثل”. فالبلاء يمسّ أحباب الله؛ ليمحّصهم، ويرفع درجاتهم، ويسمع دعاءهم، ويضاعف أجورهم، وليكونوا قدوة لغيرهم في الصبر والثبات.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m1753","text":"إذا أردت أن تعرف الحقيقة الكاملة، فاسمع من الطرفين المتناقضين، أما الاستماع من طرف واحد، فهو اعراض عن استماع الحقيقة الكاملة، وسوف يصدر عنك التصور الناقص، والحكم الجائر.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1754","text":"لولا اختلاف الأذواق لبارت السلع في الأسواق، ولولا اختلاف الأذواق لبارت بعض النساء، ولولا اختلاف الأذواق لكسدت التجارة في الأسواق، وفي اختلاف الأذواق توسيع دائرة الأرزاق، وليس من الذوق مناقشة الذوق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1755","text":"الأطفال يبتسمون عندما يكونون سعداء، والأُم تبتسم عندما تراهم سعداء، ولو كانت حزينة، فسعادة الوالدين مرهونة بسعادة أولادهما، وسعادتهما أعظم من سعادتهم. فإن من عناية الله بالأطفال، أن جعل في قلوب الوالدين الرحمة والرأفة والحنان، لصالح أولادهم، وهذا عام في الكائنات ذوت الأرواح.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1756","text":"إذا أردت أن تُحَوِّل العدو الشديد، إلى صديق حميم مفيد، فعامله بالتي هي أحسن، ادفع جهله بحلمك، ورعونته بعفوك.","kind":"hikma","topic":"العلاقات والناس","note":"تحت عنوان: كيف تصنع من العدو صديقا","source":"شذرات (ملف وورد)"},{"id":"m1757","text":"أصعب ما في العبودية ليس تقييد الجسد، بل استعباد العقل والروح؛ إذ إن من وُلد في القيد، وتربّى على الذل، قد يفقد القدرة على تخيّل نفسه حرًّا. والخطر الأكبر أن يعتاد الإنسان عبوديته حتى يراها قدَره، ويخشى من الحرية. وهذا حال كثير من شعوبنا الإسلامية اليوم؛ أُقعدت عن التفكير والعمل، ونسيت أن في دينها، ووحدتها وجهادها، سرّ القوة والعزة والانتصار.","kind":"hikma","topic":"العقل والحكمة","note":"تعليق على قول هاريت توبمان","source":"شذرات (ملف وورد)"},{"id":"m1758","text":"العاقل يتعلم من أخطائه ومن أخطاء غيره، والسفيه لا يتعلم من أخطائه ولا من أخطاء غيره. العاقل يتعلم من تجاربه ومن تجارب غيره، والسفيه لا يتعلم من تجاربه، ولا من تجارب غيره. العاقل يفكر قبل أن يعمل أو يتكلم، والسفيه يعمل ويتكلم قبل أن يفكر. العاقل يعرف خطأه إذا أخطأ فيعتذر، والسفيه لا يعرف خطأه إذا أخطأ فلا يعتذر. صادق العاقل لتتعلم منه، وجالس السفيه لتعلمه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1759","text":"إرضاء الناس غاية لاتُدرك.","kind":"mathal","topic":"العلاقات والناس","note":"خلاصة قصة الرجل وابنه والحمار، تحت عنوان: لن تسلم من الانتقاد فكن صبورا ولا تحزن","source":"شذرات (ملف وورد)"},{"id":"m1760","text":"خير الساسة من يسوس شعبه وبلده بما ينفعهم في الحاضر والمستقبل، ويوجد لهم موارد للرزق وفرصا للكسب، ويحقق لهم الرخاء وطيب البقاء، ويدفع عنهم الأحزان والشقاء، فيحبونه في حياته، ويدعون له بعد وفاته، وهم شهداء الله له أو عليه في أرضه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1761","text":"من حسن اختيار الرجل زوجة له، أن يختارها أصغر منه، لأنه إذا جاوز الستين، احتاج في شؤونه إلى المرافق والمعين، فزوجته خير من تقوم بهذا الدور، وهي تشعر بالسعادة، لأنها بهذا العمل تعبر عن حبها وتقديرها لزوجها، وأن هذا سوف يزيد في قربه وتقديره وحبه لها.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1762","text":"المشاعر ليست مجرد مناسك، بل منازل تهذيب، ومواقف تطهير، ومدارس توحيد وطاعة وأخلاق، وذكر للصالحين الموحدين.","kind":"hikma","topic":"الإيمان والعبادة","note":"من كلامه في حكمة مشروعية الحج","source":"شذرات (ملف وورد)"},{"id":"m1763","text":"رأي الشيخ يبدو خطأ في عين الشاب في الحاضر، ثم يتبين له أن رأي الشيخ صواب، ورأيه هو الخطأ، في المستقبل. لأن رأي الشيخ غالبا مبني على تجارب، والتجارب لا تكذب، ونتائجها يقينية. أما رأي الشاب فغالبا هو مبنى على العواطف والمشاعر الآنية، والتأثيرات السطحية، والحماسات الاندفاعية.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1764","text":"من سكتَ سلِم، ومن قالَ ندم.","kind":"mathal","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1765","text":"كثرةُ الكلام تُذهبُ الهيبة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1766","text":"العينُ تُبصر، والقلبُ يحفظ.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1767","text":"من جادَ ساد، ومن بَخِلَ جفاه الفؤاد.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1768","text":"التأني سلامة، والعجلةُ ندامة.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1769","text":"الرفيق يُخفف مشقة الطريق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1770","text":"حسنُ الظن راحة، وسوء الظن مشقة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1771","text":"من لم يُحسن، لم يُؤتمن.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1772","text":"القلب صندوق واللسان مفتاحه.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1773","text":"الرجل الصالح كلما زاد علمه، زاد تواضعه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1774","text":"ما هي المعاملة الأمثل مع زوجتك: أكرمها في نفسها وأهلها. استوصِ بها خيرًا، فهي أمانة. عاملها باللين، واحتمل تقصيرها. امدح، ولا تكثر اللوم. أشعرها بالأمان، تُعطيك الحنان. تذكّر: أن حسن الخُلق أثقل ما يوضع في ميزان العبد يوم القيامة. وأولى الناس بحسن أخلاقك، من يسكن معك في بيتك.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1775","text":"إذا وافق الهوى الهدى كان كالسمن على العسل","kind":"mathal","topic":"العقل والحكمة","note":"وأتبعه بقوله: والعق العسل ولا تسل فإن فيه الشفاء من الأمراض والكسل","source":"شذرات (ملف وورد)"},{"id":"m1776","text":"الحاج في شُغل شاغل بالمناسك وذكر الله والدعاء والطواف والصلاة، والوقوف بعرفة، والمببت بمزدلفة، والتلبية والتكبير وجميع المناسك، حتى إذا ما طاف الوداع، رقّ قلبه، وهدأ بدنه، فاستيقظ الشوق، وتجدد الحنين، وتذكر أهله، وقد أتمّ نسكه، وعاد من عالم الأيمان والروحانية، إلى عالم الحياة وهموم الدنيا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1777","text":"جمال الرجل في عقله، وعقل المرأة في جمالها. فالمرأة كثيرًا ما تفكر في الجماليات: جمال الشخصية، والهندام، والرشاقة في الحركات والتصرفات، وجماليات الملبوسات، والمفروشات، والمسكونات، والأثاث، وجمال الأواني وطرق التقديم، وتفكر كثيرًا في الجماليات بأنواعها، والذوقيات الراقية. ولولا النساء لكانت الحياة باهتة الألوان، خاملة الأشكال، خالية من مباهج الزينة، وجمال الزخرفة. فلو كانت الحياة بستانًا فالنساء هن الورود والزهور. ولو كانت الحياة غابة، فالنساء هن طيور الحب، الملونة، والعصافير الجميلة، والفراشات الناعمة الرقيقة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1778","text":"من آمارات الضعيف الذي لا ينوى الرد أن يقول: نُحمل الفاعل المسؤولية، ونرد عليه في الوقت المناسب والظرف المناسب والمكان المناسب، هذا رد الضعيف، لحفظ ماء الوجه، ومسح عرق الجبين. أما القوي فيكتم ويستعد ويُنيم العدو، ثم يباغته بضربة مفاجئة مُربكة حاسمة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1779","text":"العالِم يُغرِّد في تخصصه فقط، بينما المثقف يغرد في تخصصه وفي غير تخصصه. فالعلم توسع عمودي عميق، أما الثقافة فهي توسع أفقي شامل. ومن جمال الكمال أن يجمع الرجل بين العمق العلمي والاتساع الثقافي. فإن خرج العالِم عن تخصصه، أتى بالعجائب والغرائب، وعرّض نفسه للنقد والمعايب. وإن تعمق المثقف في غير تخصصه، زلت قدمه وكثر ندمه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1780","text":"قال الديك للدجاجة : أنت اليوم نشيطة وجميلة . قالت الدجاجة : كأنك تغازلني . قال: ليس هذا قصدي قالت : إذن ما قصدك؟ قال : لي عندك حاجة قال : وما هذه الحاجة ؟ يا أبا المنذر قال: حاجة الديك إلى الدجاجة، يا أم حفصة أريد أن أتقدم لخطبتك . قالت: أنت متزوج عدد من الدجاجات . قال : يعني جاءت عليَّ أنا لوحدي ، كل الديوك معددون . قالت : كلامك صحيح عطني مهلة أفكر . ما غابت الشمس إلا وهي من نسائه ، نائمة بجواره في العشة .","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1781","text":"سبحان الله! الرجل يلعن أخاه المسلم، فإذا سألته: متى عهدك بلعن فرعون وقارون؟ قال: ها ها لا أدري! لا أذكر أني لعنتهما، قال: سبحان الله يسلم منك عرض عدوك الكافر، ولا يسلم منك عرض أخيك المسلم!","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1782","text":"الحب ثمرة الإحسان، فذكِّروا الناس بإحسان الله إليهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1783","text":"أعِنِّي على حُبٍّك بالإحسان إليَّ.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1784","text":"حُبُك على قدر إحسانك، وبُغضك على قدر إساءتك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1785","text":"اشتر قلوب الناس بالإحسان إليهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1786","text":"من أحسنت إليه فقد دعوته إلى حبك. من أسأت إليه فقد دعوته إلى بغضك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1787","text":"البغضاء ثمرة الإساءة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1788","text":"لا تتوقع المحبة ممن أسأت إليه. لا تتوقع الكره ممن أحسنت إليه. توقع المحبة ممن أحسنت إليه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1789","text":"لك في قلوب الناس من المحبة، على قدر احسانك واحترامك لهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1790","text":"الإحسان يُنمي المودة، والإساءة تمحقها.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1791","text":"إذا جَفَّ الثرى بينك وبين أصدقائك، فابلُلْه بالإحسان إليهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1792","text":"إذا استشنَّ ما بينك وبين زوجتك، فأزله بالإحسان والهدايا وكلمات الغزل، فإنها ترفع المعنويات، وتزيل الحزازات.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1793","text":"يبدو أن الظلم والقمع والقتل والحروب المدمرة التي تجتاح العالم هي من صناعة الحكومات التي تدّعي الديمقراطية، والدول المتقدمة التي تملك القوة العسكرية، والأسلحة الفتاكة، والجيوش المدربة، والتي تتنافس في اختراع الأسلحة المبيدة، تلك الدول التي تتغنى بقيم الحرية والعدالة، وحرية التعبير والعيش السلمي، لكنها في الواقع تُسهم بقوة في إشعال النزاعات وتدمير الشعوب، والتدخل في شؤونها الداخلية بالقهر والسيطرة، والتاريخ شاهد على ذلك، والحاضر يُصدقه ويُؤكده.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1794","text":"الفلوس تغير النفوس والخيانةُ تنكس الرؤوس وضرب الأرض بالفؤوس يجلب الطعام والفلوس.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1795","text":"قيادة السيارة: فن وذوق وأدب وأخلاق، وتطبيق لقوانين المرور واحترامها. وتتطلب التركيز والانتباه، واغتنام الفرص بأمان ووعي. والمهارة في التعامل مع المركبة، والتصرف بأخلاق حسنة مع السائقين والمشاة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1796","text":"عينك على حلالك لا يضيع مالك","kind":"mathal","topic":"المال والاقتصاد","note":"إذا أهملته ضاع.","source":"شذرات (ملف وورد)"},{"id":"m1797","text":"علة ما تِنحكى ولا تِنشكى","kind":"mathal","topic":"الصبر والشدائد","note":"لأنها شديدة عليه، ويخاف أو يستحي أن يبوح بها.","source":"شذرات (ملف وورد)"},{"id":"m1798","text":"حمار موالف ولا غزال مخالف","kind":"mathal","topic":"العلاقات والناس","note":"لأن الحمار مريح والغزال متعب.","source":"شذرات (ملف وورد)"},{"id":"m1799","text":"القلب دكان وكل له فيه مكان","kind":"mathal","topic":"العلاقات والناس","note":"القلب الكبير الذي يسع الناس ويلبي حاجتهم.","source":"شذرات (ملف وورد)"},{"id":"m1800","text":"كل شيء يضيق إذا ما ملأته، إلا عقل الإنسان، فكلما ملأته يتسع. فعقل الإنسان صندوق فارغ، إلا من التوحيد فهو فطرة مغروسة فيه. فالإنسان يملأ عقله عن طريق حواسه، وأهمها ما يسمعه وما يقرأه، فاسمعوا أفضل ما يُقال، واقرأوا أفضل ما يُكتب، فإذا أنتم علماء، لكم مكانتكم وفضلكم فيما أقلت الغبراء وأظلت الخضراء.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1801","text":"لن يفلح من شذَّ عن سرب المسلمين الموحِّدين، فقد ضل الطريق وفقد الرفيق.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1802","text":"الجماعة لا تُقدِّس الفرد، إنما تُقدِّسه أفعاله، فالرجل قيمته بما اكتسب لا بما انتسب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1803","text":"من لم يأخذ الحذر، أوقع نفسه في المهالك والحُفر.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1804","text":"الإحسان إلى الناس أمارة التوفيق، والإساءة إليهم دليل الخذلان. فلا تندم على إحسان قدمته، ولا تفتخر بإساءة صدرت منك. ما أقبح المنّ بعد العطاء، وما أبشع التباهي بعد الإيذاء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1805","text":"المال عديل الروح، وشقيق النفس، وصنو الحياة، وفوق هذا هو دعوة مستجابة، وهو اليد العليا، واليد العليا خير من اليد السفلى، تُدرك به نعيم الدنيا ونعيم الآخرة إذا أنفقته في الطاعات، ونعم المُعين على خصال المروءة المال، به تملأ بطن الجائع وتكسي ظهره، وتُقرض المحتاج، وتفكّ العاني، وبه تصل الأرحام، وتكفل الأيتام، وتُغيث المستغيث وتفرج كربة المكروب، فالمال يصنع المروءات ويرفع الهامات، ويجلب في الآخرة الكرامات.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1806","text":"والكريم يشبه الناقة الكريمة، التي تدر ثلاث حلبات في اليوم: الصبوح، والقيل والغبوق.","kind":"hikma","topic":"الأخلاق والآداب","note":"في سياق الحديث عن كرم حاتم الطائي","source":"شذرات (ملف وورد)"},{"id":"m1807","text":"الأيام بنا تجري ونحن لا ندري، أو ندري وكأننا لا ندري. ولو أدرك خروف العيد مصيره في الذبح، لما أكل البرسيم، لا القديم ولا الجديد.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1808","text":"إذا أردت الصلاة، فاستقبل الكعبة، وإن أردت بناء جيل صالح، فاستقبل العلم والإيمان والأخلاق.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1809","text":"تعاليم الإسلام السمحة هي البوصلة الهادية إلى مكارم الأخلاق في الدنيا، وطريق الجنة في الآخرة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1810","text":"النشاط والسعي والإنجاز سمات الأحياء، أما الخمول والكسل والتسويف، فهي من صفات الأموات.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1811","text":"بالحماس يغيب العقل وتقوى الانفعالات. فالحرب تشتعل بالحماس، والسلام يتحقق بالعقل.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1812","text":"الشجار وليد الحماس، والتصالح ابن الحكمة، والحكمة بنت العقل.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1813","text":"الطلاق خطوة حماسية، والرجعة مسار عقلاني.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1814","text":"يسارع الناس إلى علاج الأمراض الجسدية الخطيرة، لكنهم يغفلون عن علاج الأمراض النفسية الخطيرة مثل الكذب، والخيانة، والغش. مع أن هذه الأمراض النفسية أنكى خطورة وأشد عاقبة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1815","text":"المنافق كالمعدِن المطلي بالذهب، ظاهره برَّاق جديد، وداخله أسود حديد.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1816","text":"لا تنكش الجاهل ولا تناقشه، وإن ناقشك فلا تحتد ولا تشتد، وكن لينا في النقاش والردِّ.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1817","text":"الناس لا يهمهم قصرك الواسع، لكن يهمهم صدرك الواسع، وقلبك الناصع.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1818","text":"كلما استحدث الناس جريمة، استحدث المعنيون بالأمن وقايةً وقانوناً وعقوبة. ثم يأتي المجرمون بحيلةٍ ومخرجٍ لها. إنها لعبة شدٍّ مستمرة، بين حفظ الأمن والتملص من القانون.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1819","text":"لا تفتحوا على الناس أبواب الوسوسة والشك، ولا تسلكوا بهم سبيل التنطع والتكلف. ما كان واضحاً من الأمور فدعوه كما هو، وما كان غامضاً فلا تتعمقوا فيه بلا حاجة. تمسكوا بالدين الوسط، بلا غلو ولا تقصير.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1820","text":"إذا التقيت بغير المسلم، فابدأه بالسلام والابتسام، ثم ادعه إلى الإسلام برفق وإقناع، مبينًا أنه دين التوحيد والعدل. شجعه على التفكر في القرآن وسيرة النبي، وامنحه كتيبًا ليتأمل. ادع له بالهداية، فأنت تزرع بذرة قد تنبت شجرة طيبة بحسنات في ميزانك. فهذا جهاد الكلمة والأخلاق، وهو واجب الجميع، أنقذوا العالم ولو بالنية والدعاء، فهذا دوركم كخير أمة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1821","text":"عاقبة الحروب خسارة الطرفين، فالمهزوم خسارته أعظم من المنتصر. عاقبة السلام سلامة الطرفين.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1822","text":"المتشائم يُغلِّب جانب الخسارة، فلا يتقدم، والمتفائل يُغلَّب جانب الربح فيتقدم.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1823","text":"القانون هو ابن الجريمة، فالمجرمون هم الذين يدفعون أهل القانون لكتابته. كلما ظهرت جريمة جديدة، اضْطُرَّ القضاة إلى سن قانون جديد يردعها. فالجرائم هي التي تشكل حدود القانون وتوسع إطاره، لتظل العدالة في مواجهة دائمة مع فوضى المخالفات والتجاوزات والجرائم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1824","text":"احذروا الوحوش الأليفة، فحبهم ثقيل، ومزاحهم خطير، وغدرهم غير مأمون، ولا تدري متى يصير.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1825","text":"عندما تغسل أطرافك في الوضوء، فإنك تطهرها من الذنوب.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1826","text":"أكثروا من الدعاء، فهو مفتاح خزائن رب الأرض والسماء.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1827","text":"كم هم كثيرون الناس، وكم هي قليلة الإنسانية.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1828","text":"تُقاس قيمة الاختراع بقدر الحاجة إليه، فإذا انتفت الحاجة، انتفت قيمته. فالاختراع الذي لا يحتاجه الناس لا قيمة له ولا مستقبل.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1829","text":"على المسلم أن يحاور غير المسلم بالحكمة واللين والحجة والبرهان، لا بالشدة والعنف والثوران، لا ابتداءً ولا ردًّا، ليعكس صورة مشرقة عن الإسلام وأخلاق المسلمين، أمام المؤيدين والمعاندين والمحايدين، فهو يؤجر على المجهود، والهداية من الربِّ المعبود.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1830","text":"مَنْ أمِنَ العقوبة أساء الأدب، أليس من العجب! مؤاخذة المجرم الضعيف! والتغاضي عن المجرم القوي صاحب الرتب؟","kind":"hikma","topic":"السياسة والقيادة","note":"يبدأ بمقولة مشهورة: من أمن العقوبة أساء الأدب","source":"شذرات (ملف وورد)"},{"id":"m1831","text":"يمر الإنسان بمراحل تطوره: يبدأ حياته زاحفًا على بطنه كالثعبان، ثم يمشي على أربع كالغزلان، حتى يقف على قدميه إنسانًا كرمه الله، الوهاب المنّان.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1832","text":"استأسد الحَمَل، لما استنوق الجمل","kind":"mathal","topic":"العلاقات والناس","note":"الحَمَلُ: ولد النعجة. المعنى: لما ضعف القوي قوي الضعيف.","source":"شذرات (ملف وورد)"},{"id":"m1833","text":"منهج القرآن في الخطاب، وفي عرض الأحكام، منهجه تصاعديا، يبدأ قويا ويختم بالأقوى.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1834","text":"ينبغي للخطيب أن يكون مثل مروحة الطاولة، يوزع وجهه ونظره بالتساوي على جميع المستمعين.","kind":"hikma","topic":"الكلام والصمت","note":"تتبعها قصة الخطيب والتاجر","source":"شذرات (ملف وورد)"},{"id":"m1835","text":"إن سقيت الأشجار أثمرت لك خيراً، وإن سقيت الأزهار فاحت لك عطراً، فالحصاد هو ثمرة الاجتهاد، فالزم عمل الخير والاجتهاد يلزمك النجاح والسداد، والمنزلة الرفيعة في السماء وعند العباد، ورَبِّ العباد.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1836","text":"القضاء والفتوى والمقارنة وبيان الراجح لا تكون إلا لراجح العقل. فهو يُفتي نفسه عند تعارض الأقوال واختلاف الآراء، إذ يرى البعيد قريبا، والخفي واضحا، والمشتبه بينا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1837","text":"لتحيا سعيداً تخلَّ عن خصال الشر: الكفر والظلم والعدوان والغرور والبخل وما شاكلها. وتمسَّك بخصال الخير: الإيمان والعفو والإحسان والقناعة والكرم والتواضع وما شاكلها. فصفات الخير تجلب السعادة وتطرد الشقاء، وصفات الشر تجلب الشقاء وتطرد السعادة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1838","text":"من المهم جدا أن يكون تفسير القرآن مبنياً على العلم والمنهجية الصحيحة، ولذلك يجب على من يريد التفسير أو الاستشهاد بآية، فعليه أن يعود إلى كتب التفسير المعتمدة مثل تفسير ابن كثير، الطبري، القرطبي وغيرهم من العلماء المشهود لهم بالدقة والعلم، وإلا كان كحاطب ليل، أو كمجروف سيل.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1839","text":"الاختراع الذي لا يُثمر ربحاً مادياً يُدفن في مهده، فلا يُخَلَّد إلا ما يُحقق منفعة حقيقية، سواء أكانت مادية أو معنوية أو أخروية. فالنفع هو سِرُّ بقاء الاختراع ودوامه.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1840","text":"الإنسان نِتاج بيئته وأسير عاداته. التردد والتذبذب ينشآن من الخوف من العواقب السلبية، بينما الإقدام والمبادرة يُولدان من التوقعات الإيجابية.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1841","text":"خير الناس من كف فكه وفك كفه.","kind":"mathal","topic":"الكلام والصمت","note":"أورده بقوله: من جميل ما قيل، وعقّب: العرب لا تستحسن من الكلام تقارب الحروف والمخارج مع التكرار","source":"شذرات (ملف وورد)"},{"id":"m1842","text":"العلاقات بين البشر ترتكز أساسًا على المصالح والمنافع المتبادلة، وتزدهر بحسن التعامل، وصدق المودة، وجودة العطاء. أما الإيمان والتقوى، فهي علاقة خاصة بين العبد وربه، لا تتأثر كثيرا بما بين الخلق من معاملات دنيوية.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1843","text":"الجاهل يتكلم قبل أن يفكر فيقع في الأخطاء، أما العاقل فيفكر قبل أن يتكلم فيتجنب الأخطاء.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1844","text":"قبل أن تعزل وزيراً أو مديراً من منصبه، أعدّ البديل الأكفأ والأجدر، حتى لا يتعطل العمل أو يختل النظام.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1845","text":"وثقوا صلتكم بالله بصلة الأرحام، وهم الأقارب من جهة الأبوين.","kind":"hikma","topic":"التربية والأسرة","note":"تحت عنوان: فضل صلة الأرحام","source":"شذرات (ملف وورد)"},{"id":"m1846","text":"رُبَّما تفوق الأدنى على الأعلى، طُلب من كبير المهندسين، أن يُمهد لهم طريقا يُمكنهم من الصعود إلى الجبل، فشرع يطوف بالجبل ليختار المكان الأنسب للطريق، فلفت نظره إلى الأغنام التي تأتي كل صباح تصعد الجبل لترعى، فتبين له بعد الدراسة، أن أفضل طريق هو طريق الأغنام، فشرع في تمهيده وإصلاحه للناس.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1847","text":"الآراء تُعرض ولا تُفرض","kind":"hikma","topic":"الكلام والصمت","note":"من قائمة آداب الجدال","source":"شذرات (ملف وورد)"},{"id":"m1848","text":"الأمهات الوالدات معراج الدعوات ومهبط الرحمات وعنوان التضحيات وأيقونة العطاءات وأساس التربيات ومفتاح التوفيقات ودليل النجاحات ومهدُ البركات ونبع الخيرات فبِرُّوا بالأُمهات فإنَّ الجنة عند رِجْلِ الأُمهات.","kind":"hikma","topic":"التربية والأسرة","note":"خاتمتها مقتبسة من حديث: الزمها فإن الجنة عند رجلها","source":"شذرات (ملف وورد)"},{"id":"m1849","text":"سبعة أدواء لا رجاء في الشفاء منها: الحماقة التي تُعمى البصيرة، والغباء الذي يُعجز العقل، والكسل الذي يُقيد الهِمَّة، والهَرَم الذي يُضعف الجسد، والتردُّد الذي يُبدد القرار، والتلون الذي يهدم الثقة، والوسواس الذي يُعكر صفو النفس.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1850","text":"جالس الحكماء تكن واحدا منهم. جالس العقلاء تكن واحدا منهم. جالس الأدباء تكن واحدا منهم. لا تجالس الأغبياء فتكن واحدا منهم. لاتجالس الأشقياء، فتكن واحدا منهم. لاتجالس الضالين فتكن واحدا منهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1851","text":"آخرتك هي حصاد حياتك، وحياتك انعكاس لاختياراتك. فاختر دائمًا الأفضل الأيسر، لتضمن الاستمرار، ولتثبت على الطريق المستقيم، وتنال رضوان الله وجنات الخلود وأنهار النعيم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1852","text":"كونك على الحق لا يمنحك مبررًا لمخاشنة أخيك الذي ضلّ الطريق. بل كن معه كما يكون الطبيب مع المريض، ولا تُغلق الأبواب المفتوحة بينكما. فدعوة الأخلاق أبلغ وأعمق تأثيرًا من دعوة الأقوال، وهي التي تُمهد الطريق لقبول الأقوال. والشيطان يسعى دائماً إلى إثارة الفتنة بينكم، فلا تنساق وراءه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1853","text":"يتلونون مثل الحِرباء، فيلبسون الثوب الذي يجلب لهم المنافع، ولا يُبالون بالحق والمبادئ.","kind":"hikma","topic":"الأخلاق والآداب","note":"تعليق على حديث ذي الوجهين","source":"شذرات (ملف وورد)"},{"id":"m1854","text":"اطلبوا العلم من المهد إلى اللّّحد، ومن المَحْبَرة إلى المقبرة، ومن الطفولة إلى الكهولة، ومن نزغة الشباب إلى رزانة الشياب، فالعلم نور والجهل ظلمات، وفضل العالم على العابد كفضل القمر على الكواكب، العالم في قومه كالنبي في أُمته، وكالبصير في العميان، والسراج المنير في الظلام المستطير.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1855","text":"لو كان كل الناس عقلاء وعلماء، لخربت الدنيا. انظر إلى مدينة يبنيها مهندس واحد وألف عامل، بينما لا يُقيم ألف مهندس وعامل واحد حمامًا واحدًا. فالبسطاء والغوغاء هم من يُطفئون الحرائق، ويُشيّدون العمارات، ويُنقذون الغرقى، ويُمهّدون الأرض ويُرصّفون الطرق، ويذودون عن الأوطان، وينصرون الخِلان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1856","text":"قِيل لحكيم: ما كمال العقل؟ قال : ما رأيته كاملا في أحد حتى أصفه .","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1857","text":"قِيل لحكيم: ماعدد المجانين عندكم؟ قال: هذا يطول، ولكني أعد لك العقلاء.","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1858","text":"ألف رجل كتابا، وعرضه على عالم، ثم قال له بعد ما قرأه: علِّم على الخطأ لأُصلحه، فقال: أُعلم على الصواب فهو أيسر .","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1859","text":"راحة البدن في قلة الطعام، وراحة الروح في قلة الآثام.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1860","text":"الشباب حجة التصابي وقلة الصواب.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1861","text":"الشباب مظنة الانحراف عن الصواب.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1862","text":"استجيدوا الخال فإن العرق دساس، يسري في الظلام لا يضل ولا ينام.","kind":"hikma","topic":"الحياة الزوجية","note":"مبني على المثل: العرق دساس","source":"شذرات (ملف وورد)"},{"id":"m1863","text":"من قلت سيئاته وكثرت حسناته هان عليه الموت.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1864","text":"هون على نفسك ملاقاة الموت بكثرة الصدقات والحسنات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1865","text":"انظر في أي وعاء تضع نطفتك فإن العرق ينزع في خفاء، يسري في النهار وفي الظلماء.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1866","text":"من اقتصد في المؤونة وافته المعونة، ومن أسرف في المؤونة فاتته المعونة.","kind":"hikma","topic":"المال والاقتصاد","note":"المؤونة: القوت وما يدخر","source":"شذرات (ملف وورد)"},{"id":"m1867","text":"أغنى الناس الراضي برزقه، وأحب الناس إلى الله أكثرهم له ذكراً، وأحكم الناس الذي يحكم على نفسه بما يحكم على غيره.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1868","text":"اجعل يومك خيراً من أمسِك، وغدك خيراً من يومك.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1869","text":"خاب من كان يومه شراً من أمسه، وغدُه شراً من يومه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1870","text":"الصحابة رضي الله عنهم، أكثر علما، وأقل تكلفا، وأبعد تعصبا وأكثر تطبيقا لأحكام الإسلام.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1871","text":"دخل سعيد بن مُرَّة على معاوية رضي الله عنه، فقال له: من أنت؟ فقال: أنت سعيد وأنا ابن مُرَّة .","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1872","text":"قال السفاح للسيد الحميري: أنت السيد؟ قال: أنا ابن أبي، وأمير المؤمنين السيد .","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1873","text":"إذا قال العالم في المسأئل التي لا يعرفها: لا أدري! فهو ثقة فخدوا عنه العلم، والعكس صحيح.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1874","text":"من حاز نصف العلم، مع قول لا أدري، فهو بمنزلة من حاز العلم كله.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1875","text":"قول: (لا أدري) نصف العلم، وهي المنجية للعلماء.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1876","text":"العاقل من عقَل نفسه عن المحارم والمظالم والمآثم والمخاطر.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1877","text":"العاقل من يهديه عقله إلى الهدى، ويردعه عن الردى.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1878","text":"العقل يهدي صاحبه إلى السلامة، والحُمق يهديه إلى الندامة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1879","text":"من قال في القرآن برأيه فأصاب فقد أخطأ، أصاب في جزئية وأخطأ في المنهج. قبل أن يتكلم في الآية عليه أن يرجع إلى كتب التفسير المعتمدة المشهورة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1880","text":"أكرم ضيفك بما تجود به نفسك، فالجود من الموجود، فمن تكلَّف لضيافة ضيفه أثقلته الزيارة، ومن أكرمه بلا تكلُّف أحبَّ لقاءه ولم يستثقل حضوره.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1881","text":"من أسمى معاني الأخوة أن يكون الأخ سندًا وعونًا، يشد عضد أخيه حين تشتد عليه الخطوب، ويقف إلى جانبه في دفع الظلم ورفع المعاناة، مواسيًا ومخففًا عنه ما يثقل كاهله.","kind":"hikma","topic":"التربية والأسرة","note":"تسبقها آيتا: سنشد عضدك بأخيك، وإني أنا أخوك فلا تبتئس","source":"شذرات (ملف وورد)"},{"id":"m1882","text":"الطب لصحة الأبدان، الفقه لصحة الأديان، لو لم أكن فقيها لتمنيت أن أكون طبيبا. وكل علم فيه موارد اتفاق وموارد اختلاف، فلما نسمع من أكثر من واحد، تبرز مكامن القوة والضعف، والصواب والخطأ، والراجح والمرجوح، هذا لأهمية العلمين.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1883","text":"الرجل راعٍ في أهل بيته ومسؤولٌ عن رعيته، وكذلك المرأة راعية في بيت زوجها ومسؤولةٌ عن رعيتها. فالحياة الزوجية تقوم على التعاون والتفاهم، وقد جعل الله بين الزوجين مودةً ورحمة. ومن خلال توزيع المسؤوليات بينهما، يُصبح رأي الرجل مرجحاً عند اختلاف الآراء، فتستقيم أحوال الأسرة، ويعمّها الوئام والسلام والمودة.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1884","text":"إذا رغبت في أن تُطاع، فامنحهم بعضاً من الطموحات والأطماع، فقد جاد الله على الناس بنعم لا تُحصى، قبل أن يطالبهم بالعبادات والطاعات.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1885","text":"من جاءكم مِمَّن ترضون خَلْقَهُ وخُلُقَهُ ودينه وراتبه فزوجوه، ولا تُأخروا الأَيِّمَ عن نصيبها، فتأخيرها ليس في صالحها.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1886","text":"الذين يُحكِمون قبضتهم على توجيه الرأي العام في الانتخابات، لا ينحازون لمصلحة الوطن، بل يميلون إلى مصالحهم الخاصة، فيرجحون منفعتهم الشخصية على الصالح العام.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1887","text":"خير أصحاب الرسل، أصحاب خير الرسل","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1888","text":"اختلاف وجهات النظر من عادات البشر، ولولا اختلاف الأذواق، لبارت النساء والأسواق، وليس من الذوق مناقشة الأذواق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1889","text":"في المقارنة بين العالم وغير العالم في بعض المسائل التي لها جوانب شرعية. نجد أن العالم ينطق بلغة العقل، متكئاً على أُسس الشرع، فيزن الأمور بميزان الحكمة، ويوازن بين المنافع والمضار. فحديثه يتسم بالاتزان والهدوء. ويخاطب المخالفين بأدب واحترام، يعكس سعة صدره، ورجاحة عقله وقوة تعليلاته. أما غير العالم، فيُدفع بعواطفه ويتغافل عن العواقب، فيتسم حديثه بالتسرع والحماس، ويبالغ في التشنيع على من يُخالفه، فيظهر ضيق الأفق وقلة الفطنة وركاكة الرطنة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1890","text":"قدِّم لضيفك الطعام الفاخر الشهي، فإن الطعام اللذيذ يمد اليد، ويحرك الفك والخد، ويطلق اللسان بالحمد، ويزيل ما بين القلوب من وحشة وصد. فبالطعام تُروض الفيلة والأسود، والنمور والفهود، فكيف بالإنسان العاقل الودود! أطعم الفم تستحِ العين، وينطق اللسان بأجمل الكلام الزين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1891","text":"لأن آكل تُميرتي، وأترشف مُويهتي، وأحتسي قُويهتي وأحلب عُنيزتي وأرعى شُويهتي وأغلق علىَّ خيمتي ولا أمد يدي، سارقا ولا سائلا، لأحفظ ديني وكرامتي.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1892","text":"إن لهذه النفوس نشاطا وخمولا: فإذا نشطت فخذوها بالنوافل والقربات، وإذا خملت فألزموها بالفرائض والواجبات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1893","text":"الغرب قد حقق إنجازات علمية هائلة، فكشف أسرارًا عظيمة عن الطبيعة وألغازها، واستطاع أن يخترق أعماق البحار ويسبر غور الفضاء ويحلل المادة في أدق تفاصيلها. لكنه رغم كل هذه الاكتشافات العجيبة ما زال عاجزًا عن إدراك حقيقة واحدة واضحة: أن عيسى بن مريم عليهما السلام إنسانان مخلوقان، نبيٌّ كريم وأمه الصدّيقة، وليسا إلهين معبودين. فهذه الحقيقة الجلية، التي أقرّ بها الوحي السماوي منذ قرون، تبقى برغم تطور العلم وقوة الفكر في الغرب غير قابلة للتسليم، فمعارف الإنسان العلمية بلغت ما بلغت، ولكنها لم تستطع تجاوز حجب الشرك والضلال. ليبقى العقل في قيد الغفلة عن أعظم الحقائق، وهي وحدانية الله الخالق وأنبيائه بشر مكرمون، مُرسلون بدعوة توحيد الخالق الواحد الأحد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1894","text":"لتكون الدولة قوية وتحمي نفسها، يجب أن ترتكز على ثلاث دعائم متينة، بعد الإيمان بالله تعالى والتوكل عليه: 1. اقتصاد قوي: يعزز الاكتفاء الذاتي. 2. جيش متطور: بتكنولوجيا حديثة. 3. وحدة وطنية: تعزز التعاضد والتماسك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1895","text":"على مهلكم في تربية أولادكم، قدروا أعمارهم، ولا تسفهوا أفكارهم، بالترغيب والتحبيب، لا بالإكراه والتعذيب، بالتأني والعرض، لا بالتعسف والفرض، بالهدايا والجوائز، والمنح والحوافز.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1896","text":"ما يُدرك بالحيلة لا يُطلب بالقوة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1897","text":"العالِم يُقدّم الفتوى للعامة مختصرة، ليسهل عليهم فهمها وحفظها، ولو دخل معهم في التفاصيل لأربكهم. أما إذا كان السائل طالبَ علم، أفاض له في الأدلة وأصول المسألة، ليبني فهمًا راسخًا مبنيًا على الدليل والبرهان.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1898","text":"لتتحقق مقاصد الشريعة العظمى، لإخراج الناس من ظلمات الشرك إلى نور الإسلام، يجب على المسلمين أن يتصالحوا ويتعاونوا فيما بينهم، لنشر دعوة الله في العالم، فاجتماعهم يزيد من قوتهم في دعوتهم، وتفرقهم يضعفهم ويوهنهم","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1899","text":"ذبح مزارع دجاجته التي كانت تضع له بيضة من ذهب يوميًا، طمعًا في أن يستخرج منها جميع الذهب كله، فلم يجد فيها ذهبا. فالقناعة كنز لا يفنى.","kind":"hikma","topic":"المال والاقتصاد","note":"بعنوان: عاقبة الطمع","source":"شذرات (ملف وورد)"},{"id":"m1900","text":"بحسن التفكير والتدبير حَوِّل المصاعب إلى فرص للنجاح.","kind":"hikma","topic":"النجاح والإبداع","note":"عبرة قصة الحمار الذي سقط في البئر","source":"شذرات (ملف وورد)"},{"id":"m1901","text":"التفوق في إنجاز مهام المواطنين، ومراعاة مصالحهم والتيسير عليهم، تجده في بعض الحكومات، ورغم أن جميع الحكومات في العالم لا تخلو من وجود الفساد والتقصير، إلا أنها بنسب متفاوتة، فأفضلها أقلها تقصيرا وفسادا.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1902","text":"أكثر الخطأ في موافقة الهوى، وأكثر الصواب في مخالفة الهوى.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1903","text":"ربما كان الخير فيما تكره النفس، وربما كان الشر فيما تُحب النفس.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m1904","text":"إن كنت في معرض الاختيار، ولم يتبين لك ماذا تختار، فخالف هواك ترشد.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1905","text":"تغير الفصول موسم لأمراض تجول وتصول","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1906","text":"اتقوا البرد، فإن أوله يحرق، وآخره يورق. ويفعل في الأبدان، ما يفعله بالنبات والأغصان.","kind":"mathal","topic":"الصحة والنفس","note":"أثر مشهور","source":"شذرات (ملف وورد)"},{"id":"m1907","text":"البرد كالسِرحان (الذئب) يهجم على الأبدان، في غفلة الإنسان.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1908","text":"البرد سريع الدخول بطيء الخروج، سريع الدخول في الأبدان بطئ الخروج منها، فاتقوا البرد في أوله ولا تهابوه في آخره.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1909","text":"احذر ممن لا تعرفه، وثق بمن تعرفه رويدا رويدا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1910","text":"ادع الناس إلى الخير والمعروف رويدا رويدا، ولا تُثقل عليهم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1911","text":"الاقتصاد شطر المعيشة، وحسن الخلق شطر الإيمان.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1912","text":"في الخطأ الأول وقاية من تكراره.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1913","text":"العاقل لا يعيد أخطاءه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1914","text":"الباب الذي يجيء منه الريح والعجاج، سِدَّه واسترح من الإزعاج.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1915","text":"النقاش الذي يُولد الخصام، دعه واكسب محبة الأنام.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1916","text":"المكان الذي فيه تُهان، اهجره وابحث عن المكان الذي فيه تُصان.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1917","text":"كثرة طلب الحوائج من الناس والأصدقاء، يسلب منك فضيلتين: العزة والحياء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1918","text":"أربع أشياء لا يُستحيا من طلبها: الملح والماء، والبندول والدعاء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1919","text":"ثلاثة أمور لا يقبل الملك فيها الشفاعة: المساس بشرف نسائه وقريباته، وزعزعة عرشه، وإفشاء أسراره، فذلك يفسد عليه إدارة مملكته.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1920","text":"رجل أوروبي غني في الخمسين تقدم لخطبة فتاة في العشرين، لكنها صدته. أخبرها أن عمره سبعون عامًا، فوافقت. بعد الزواج، اكتشفت كذبه، وأنه في الخمسين، فبكت غاضبة وطلبت الطلاق.","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1921","text":"إذا قطعت الإساءة عن غيرك، فابدأه بالإحسان. فكل إحسان تبادر به إلى الناس هو في المآل إحسان إلى نفسك، وكل إساءة تبتدر بها غيرك هي في الحقيقة إساءة إلى نفسك. وإذا أحسنت، فتواضع، وإذا أسأت، فبادر بالاعتذار والاستغفار. فما أبهى أن تبدأ بالإحسان وما أجمل أن تنتهي بالتواضع.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1922","text":"فالإسلام دين الفطرة والإنسانية، والأخلاق السنية، التي تأسر القلوب النقية، والعقول السوية.","kind":"hikma","topic":"الإيمان والعبادة","note":"خاتمة قصة","source":"شذرات (ملف وورد)"},{"id":"m1923","text":"الإنسان تحت عين الرحمن، يستر ويغفر، ويرحم ويُمهل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1924","text":"ننتقد أحيانًا ما لا نستطيع الوصول إليه، رغم أن العيب في الجهد المبذول لا في الشيء المأمول.","kind":"hikma","topic":"الصحة والنفس","note":"مغزى قصة الثعلب والعنب","source":"شذرات (ملف وورد)"},{"id":"m1925","text":"احذر من وهج الطرح الحماسي، ومن إصرار المتحدث على غرس قناعاته في ذهنك بسحر البلاغة، وعذوبة العبارة، وبراعة الإيماءة والإشارة. الأجدر بك أن تسمع لمن يخالفه الرأي، أو تستمع لثلاثة ممن يشاطرونه الاختصاص، ليكتمل لديك التصور، وينشرح صدرك، ويطمئن قلبك. فالعقل ليس مخزناً يستوعب كل ما يُلقى فيه بلا تمييز، بل ميزان يزن الحجة والمنطق. كم هم كثيرون أولئك المتحدثون والمحللون، وكم هم قليلون من أصابوا الحق وأدركوا الصواب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1926","text":"الصاحب ساحب، والمشاكلة أُخوة، والتوافق في الأهواء والهوايات صداقة، والأرواح جنود مجندة ما تعارف منها ائتلف، وما تناكر منها اختلف، فاصحب الأخيار وكن مع الأبرار، وادعُ للأشرار وانصحهم بالخفاء والإسرار، ولا تفضحهم بالإجهار.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1927","text":"يا ابن آدم اعرف أصلك تعرف نفسك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1928","text":"دع من الحلال حاجزا بينك وبين الحرام، فمن استوعب الحلال كله، تاقت نفسه إلى الحرام.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1929","text":"أحيانا لنموت وأماتنا لنحيا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1930","text":"أعظم من الذنب اليأس من المغفرة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1931","text":"ألا تستحون من طول ما لا تستحون.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1932","text":"احذروا مجانيق الضعفاء، الدعاء في السحر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1933","text":"قال جلساء معاوية رضي الله عنه: متى تحب أن ننفض من مجلسك ؟ قال: أمارة ذلك إذا قلت : إذا شئتم . وقال يزيد: إذا قلت: على بركة الله. وقال عبدالملك: إذا ألقيت الخيزرانة . وقال رجل من كبار العسكر: إذا قلت: يا غلام الغداء . وقلت أنا: لا تحرمونا من زيارتكم .","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1934","text":"لذة الصيد في المطاردة","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1935","text":"مآلات الإحسان تعود إلى المحسن. مآلات الإساءة تعود على المُسيء","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1936","text":"الأسواق موائد الله في أرضه، فإذا دخلتموها فاحمدوا الله على الأرزاق، واستعيذوا بالله من الفساق، ومن فتنة النساء.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1937","text":"المساجد أسواق الآخرة، وسلعها الأعمال الصالحة، فاعمروها بالصلاة والإيمان، ودراسة الحديث والقرآن.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1938","text":"لا تعاهدوا الله بل عاهدوا أنفسكم، فلأن تنقضوا عهدكم، خير لكم من أن تنقضوا عهد الله سبحانه وتعالى.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1939","text":"فابن آدم فيه من خصال أبيه آدم عليه السلام، فالإنسان متقلب الأحوال، ولا يثبت على حال.","kind":"hikma","topic":"الصحة والنفس","note":"يتبعها حديث: فجحد آدم فجحدت ذريته","source":"شذرات (ملف وورد)"},{"id":"m1940","text":"الحمد لله الذي فضلنا بنعمٍ جعلت غيرنا يسعى إلينا طلبًا للعمل وخدمتنا، بينما لا نحتاج إلى السعي لخدمتهم. وهذه نعمة منسية، تستوجب شكر الله بالقول والعمل والنية، مع تقوى الله في معاملتهم بالإحسان بعيدًا عن التكبر والتضييق، والفوقية.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1941","text":"الحقُّ مُرٌّ، فامزجوه بشيء من حلاوة لعاب النحل.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1942","text":"إذا ناقشت صديقك، فاختم النقاش بلمسة ودٍّ تمحو أثر الخلاف.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1943","text":"كان صديقي يودّني طبعًا، فلما نصحته، صار يودّني تصنّعًا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1944","text":"كثرة العتاب تفتُّ أوتار الصداقة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1945","text":"كثرة المناكفة تُفضي إلى المشاحنة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1946","text":"الجدال المُفرِط يعكر صفو القلوب.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1947","text":"الأعمال الذهنية التي تُنشط العقل وتزيده حيويةً وفاعلية، مثل: القراءة، والكتابة، وحفظ القرآن الكريم وتلاوته، تعد من أعظم الوسائل للوقاية من النسيان وأمراض الذاكرة كألزهايمر. وأسمى هذه الأعمال حفظ القرآن وتلاوته، إلى جانب قراءة الأحاديث النبوية، فهي تغذي العقل والروح معًا، وتُبقي الذهن في حالة يقظةٍ ونشاط دائم.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1948","text":"اعتمدوا المقارنات الإيجابية، فاجعلوا نظركم إلى من دونكم في الدنيا، وإلى من فوقكم في الدين، واحذروا العكس.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1949","text":"العطاء لا يُقاس بكثرته دائما، بل بصدق النية وصفاء الطوية؛ فرُبَّ ابتسامة صادقة تُنعش قلب الحزين وتُفرّج كرب المكروب، فتكون أحيانا أبلغ من العطاء المحسوب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1950","text":"الخطأ سبيل إلى الصواب، والإخفاق بداية النجاح. فالصواب ابن التجربة، والنجاح وليد المحاولة. هكذا تمضي سنن الله في التطور، حيث لا يأتي الكمال من أول مرة. الكعكة الأولى محروقة، والثانية معطوبة، والثالثة غير مرضية، حتى تصل إلى الخامسة لذيذة ومطلوبة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1951","text":"بين كسب القلوب وكسر القلوب، خيط دقيق يُسمى حُسن التعامل ولطف الأسلوب، فمن أتقنه ملك القلوب، ومن أهمله أوحش القلوب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1952","text":"إن لم تقدر أن تتصدق بالدولارات، وتُكرم الأصدقاء وذوي القرابات، فتصدق بالكلمات الطيبات والابتسامات: فالابتسامة نور للقلب، وبلسم للروح، تُزيل الكدر، وتزرع لك في النفوس المودة على مَرِّ الأيام والدهر.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1953","text":"المعروف المنتظم قد يراه بعضهم حقًا مكتسبًا، لا كرمًا تطوعا.","kind":"hikma","topic":"العلاقات والناس","note":"عبرة قصة الرجل والفقير","source":"شذرات (ملف وورد)"},{"id":"m1954","text":"الطفل الصغير يرى ما يلقاه من تأديب أبويه قسوةً وحرمانًا من حريته، فينظر إليه بعين السلبية، ولا يدرك حقيقته إلا حين يكبر وينضج. وكذلك الإنسان قد يظن أن تعاليم الدين قيدٌ على حرياته، وحرمانٌ من شهواته، أو أن ما يصيبه من أمراض وابتلاءات شرٌ محض. لكنه، إن صبر واحتسب، سيدرك أن كل ذلك خيرٌ مخبوء له، يُثمر سعادة في المآل ورفعة في الحال.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m1955","text":"الطلاق يكسر القوب، ويمزق الشمل، وهو شطر اليُتم للأطفال، ويحرمهم من عطف أبيهم، ودفئ العائلة، ويثير التشاحن بين العائلتين. فأُمُّ العيال لا تُطلق إلا فيما لا بُدَّ منه، فعلى الأبوين المياسرة والتنازلات، مراعاة لمصلحة الأطفال، ليعيشوا في ظِلِّ أسرة، ودِفئ عائلة.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1956","text":"أصحاب المهن والحرف التي يجهل المواطن أسرارها وأسعار أدواتها، كإصلاح الأجهزة الكهربائية والتقنية وغيرها، يجدون فرصة سانحة للغش والخداع، مستغلين جهل الطرف الآخر. فإياكم أن تغتروا بالكلام المعسول، إذ يصعب الاحتراز من مكرهم وخداعهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1957","text":"لم أعرف الغم قط حتى صحبت الأغنياء؛ إذ بدأتُ أرى ما يفوقني: ثيابهم أفخر من ثيابي، مركباتهم أبهى من مركبتي، وحياتهم تبدو أكثر راحة وبذخًا، فصار قلبي يضيق بما عندي، ويشقى بما لديهم. لكن حينما صحبت المساكين، تبدل الحال؛ رأيت قلة حيلتهم وعظيم رضاهم، فعاد السرور إلى نفسي، وزال الغم عن قلبي، وتعلمت أن السعادة ليست فيما نملك، بل في الرضا بما قسم الله لنا.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1958","text":"نعمة الإسلام أعظم النعم، بها يتحقق الإيمان بالله والهداية إلى دينه، تليها الصحة، إذ بها يستطيع الإنسان القيام بواجباته الدينية والدنيوية. ثم نعمة المال الصالح، في يد العبد الصالح وسيلة لتحقيق الخير الخاص والعام في الدنيا والآخرة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1959","text":"الإيجاز فَنُّ التعبير بأقل الكلمات، مع بقاء المعنى قويًا وواضحًا. فالكلمات المختصرة إذا صِيغت بدقة، تحمل أثرًا أعمق وتعلق في الأذهان أطول. إن اختصار المعاني دون إثقالها بالتفاصيل هو سِرُّ الإقناع ومفتاح التأثير.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1960","text":"كم من الأحاديث والأخبار، والقصص والتقارير والأسرار، التي لا رأس لها ولا ذنب، ولا نسب ولا حسب، فلا يلزمك أن تُصدق كل ما يُقال، ولكن يلزمك ألا تقول إلا الصدق.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1961","text":"دموعُ الأطفالِ، تُحرِّكُ الرجالَ، للسعيِ في طلبِ الأعمالِ، لجلبِ المالِ، ليملؤوا بطونَهم، ويكسوا ظهورَهم، في الحالِ والمآلِ، حتى لا يُلجَؤوا إلى مدِّ الأيدي للسؤالِ، الذي يجلبُ عليهم الذلةَ والعارَ، أمامَ الصغارِ والكبارِ.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1962","text":"عدل القاضي يُعرف بقبول الناس لحكمه وارتياحهم له، مقرونًا بمدحهم الجهري. وجور القاضي يظهر في سخطهم وعدم ارتياحهم، يتبع ذلك قدحهم همسًا. فاتفاق كلمة الخلق أمارة على الحق.","kind":"hikma","topic":"السياسة والقيادة","note":"بعنوان: أمارة العدل والجور","source":"شذرات (ملف وورد)"},{"id":"m1963","text":"خير الرزق ما يُغنيك ولا يُطغيك، ويُعينك على خصال البِرِّ ولا يُلهيك.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1964","text":"يبدو أن الظلم والبطش والدمار في العالم هو نتاج بعض الحكومات التي تتستر بشعارات الديمقراطية، والدول التي تستغل قوتها وسلاحها لنهب خيرات الدول المستقرة. هذه القوى تعيش على الفوضى، وتزدهر وسط الدمار، بلا وازعٍ من ضمير أو رادعٍ من حدود، فهي لا تفهم إلا لغة الهيمنة، ولو على حساب أمن الشعوب وكرامة الأمم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1965","text":"التعايش والتكيُّف والتلاؤم، من موجبات تيسير الحياة، وتخفيف المعاناة، واكتساب القوة النفسية والحسية التي تُعين على التحمل والتصبر، واستمرار دوران عجلة الحياة، لتحقيق مصالح ومنافع الإنسان، واتقاء المفاسد والمضار.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m1966","text":"قالت وضحوه: حُصُّوه يرحم الله امج وبوج ، أهلي بزوجوني واحد غصبن عني ، وأنا ما اشتهيه بعيشة الله ، شوفيلي حل بسرعة . حصوه: حلج عندي ! وضحوه: اشلون ؟ حصوه: صوريلي ويهج أول ما تقعدين من النوم ، قبل ما تنزلين من السرير ، وأنا أفكج منه ، لا تشيلين هم ، كل مشكله ولها حل . وضحوه: فعلا اعتذر ، وقال : يبي يسافر بره يكمل دراسته . اشسويتي فيه ؟ حصوه: ما سويت شي ، بس دزيتله صورتج .","kind":"tarfa","note":"قصة باللهجة الكويتية","source":"شذرات (ملف وورد)"},{"id":"m1967","text":"إذا كانت الناقة كريمة، تكون لها ثلاث حلبات: الصَّبوح والقِيل والغبوق. وكذلك الرجل التقي الغني الكريم، يُكثر من بذل المعروف، وإنعاش المكروب والملهوف، وبالصدقات على الأرملة واليتيم يطوف.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1968","text":"بعض تغريدات الواتساب مثل الأثاث القديم، إما أن يُرحل إلى الياخور أو الشاليهات، أو اللجان الخيرية أو المحرقة، لا فائدة تُرجى، ولا عائدة تُقتنى.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1969","text":"وجود الأُلفة بين الأفراد يُعزز الروابط ويُعمق التواصل، ففي المشاركات بركات تعود بالنفع على الجميع، وفي التعاضد تساند يقوي بعضنا بعضًا، والتعاون يجلب النشاط ويطرد التهاون، وفي الاجتماع قوة، وفي التفرق ضعف، ويد الله فوق يد الجماعة، فالعمل الجماعي يُحقق ما قد يعجز الفرد عن تحقيقه بمفرده، ويزيد من التلاحم والإنتاجية الإيجابية.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1970","text":"كثرة الوعود والكلام المعسول لا تدل على أنه مأمون ولا يخون.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1971","text":"لا تُبادر بتصديق من له مصلحة في تصديقك: كالبائع والخاطب والمرشح نفسه للمناصب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1972","text":"اعزموا الدعاء، من غير إن شاء الله أو بإذن الله، لأن الله كريم، ولا مُكره له، ورحمته واسعة.","kind":"hikma","topic":"الإيمان والعبادة","note":"يتبعها حديث: ليعزم المسألة فإنه لا مكره له","source":"شذرات (ملف وورد)"},{"id":"m1973","text":"طاح الحطب","kind":"mathal","topic":"العلاقات والناس","note":"عند اشتعال النار يجمعون الحطب على هيئة هرم، فإذا بدأ يتساقط على بعضه فتلك بداية خمود النار، أي بدأ يخف الشجار وتخمد النار ويقل الشرار","source":"شذرات (ملف وورد)"},{"id":"m1974","text":"إذا أردت أن تُحاضر في الأجيال القادمة بعد رحيلك، فألِّف لهم تأليفات مهمة ونافعة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1975","text":"إن الله ليثيب عبده على نية الخير، وإن لم يفعله. إن الله ليُثيب عبده على نية الشر إن تركه لله تعالى.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1976","text":"عِشْ رَجَباً تَرَ عَجَبا","kind":"mathal","topic":"الحياة والزمن","note":"مثل عربي شائع يبدو جاهليًا؛ كان أهل الجاهلية يؤخرون مظالمهم إلى رجب فيدعون عند الكعبة على من ظلمهم، لأن رجب من الأشهر الحرم فيأمنون فيه الطريق والسفر","source":"شذرات (ملف وورد)"},{"id":"m1977","text":"الناس يرحلون وتبقى ذكرياتُهم، فأحسنوا أعمالَكم وأخلاقَكم، تحسن ذكرياتُكم، والمسلمون شهداء الله في أرضه، وقول الحق على لسان الخلق، فمن أثنى عليه المسلمون خيرا فقد وجبت، ومن أثنى عليه المسلمون شرا فقد وجبت.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1978","text":"التغيرات التي تطرأ على ظاهر الإنسان وباطنه مع مرور العمر هي جزء من سنن الحياة الدنيا، حيث يترك الزمن أثره على الجسد والعقل. أما في الجنة، فلا يطرأ تغير ولا يعكر صفو النعيم، إذ يبقى الإنسان في أكمل صورة وأفضل حال، مما يجسد كمال النعيم ودوام الوعد الإلهي للمؤمنين.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1979","text":"إئْتِ الناس ما تُحبه من الناس، وتجافَ عما لا تُحبه من الناس.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1980","text":"تودد للأصدقاء، ولا تُخاشن الغرباء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1981","text":"من جمع الحكمة في صدره صار حكيما، ومن جمع الحكمة في كتاب، صار ألف حكيم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1982","text":"الرجال بأفعالها وإنجازاتها، لا بأقوالها وادعاءاتها.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1983","text":"يُقاس الرجل بإنجازاته لا بأُمنياته.","kind":"hikma","topic":"النجاح والإبداع","note":"له صيغ أخرى","source":"شذرات (ملف وورد)"},{"id":"m1984","text":"تحقيق الأهداف ليس بالاندفاع والمغامرة والحماس، وإنما بالعلم والتجارب وسؤال الخبراء والمجربين من الناس، والتجارب لا تكذب، لأن نتائجها يقينية.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1985","text":"طوبى لملك تشهد له رعيته بالعدل والإحسان، وحسرة وندامة لملك تشهد عليه رعيته بالظلم والعدوان، فرعية الملك شهداء الله له أو عليه عند الله مالك الملك، فالظلم يُوبقه، والعدل يرفعه، والإحسان يقربه من الله ويدنيه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1986","text":"الحصيف يرى بعقله، ويسمع بأُذُنه، ويتعامى بعينه، ويتباكم بلسانه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1987","text":"ادخلوا بيوت الناس عُمياً صُمًّا، واخرجوا بُكما.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1988","text":"الجليس مؤتمن فلا يحلُّ له نقل الحديث على سبيل الإفساد.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1989","text":"ميدان الحروب يزخر بالإرجافات، والإشاعات، والتزوير، والافتراء، فلا تُصدقوا كل ما تسمعون، ولا تُكذبوا كل ما يُنشر، ولا تنشروا كل ما يُقال، حتى تستبينوا الحق وتتحققوا من اليقين.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1990","text":"احتسبوا الأجر والثواب، واطلبوا البركة في المال والعمر بصلة الأرحام. اجعلوا لقاء الأرحام الأسبوعي عادة محمودة، واغرسوا في نفوس أولادكم حب الحضور، ولو كان للحظات قليلة، ففي ذلك الخير العظيم، والثواب الجزيل.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1991","text":"من أكل أكثر من حاجة جسمه زاد وزنه. من أكل أقل من حاجة جسمه نقص وزنه. من أكل على قدر حاجة جسمه، لم يزد وزنه ولم ينقص.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1992","text":"حين كان المسلمون أمة واحدة، تجمعهم راية التوحيد، وقلوبهم متحدة كقلب رجل واحد، كانت لهم قوةٌ وهيبةٌ وسلطانٌ بين الأمم. ولكن لما تفرقوا إلى سبعٍ وخمسين دولة، وتنازعتهم الخلافات، وأشعلت بينهم النزاعات والحروب، ضعفت شوكتهم وذهبت ريحهم. ولن تعود لهذه الأمة عزتها إلا بما أعزَّ به سلفها: وحدة الكلمة، وثبات العقيدة، والعمل بشرع الله.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1993","text":"(اللهم لا تُحوجنا لأحد غيرك) فيها نكهة رهبانية، ولا رهبانية في الإسلام. لا تستقيم حياة الناس إلا بالتعاون، وتبادل المصالح والمنافع. فتصويب الدعاء: (اللهم لا تحوجنا لشرار خلقك)","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1994","text":"التواصل يزيد في المودة، والمودة تزيد في التواصل.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1995","text":"توق الإفراط في كل شيء، فإن غاية الإفراط التقصير.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1996","text":"من أكثر العتاب ثقُل على الأصحاب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1997","text":"تثمير الأموال يسد الخِلال- الفقر والحاجة- ويُصلح الأحوال، ويُسكن البال. تضييع الأموال، يَفتق الخِلال، ويُفسد الأحوال، ويشغل البال.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1998","text":"كُن لأعدائك كما تكون لأصدقائك، يكن لك أعداؤك، كما يكون لك أصدقاؤك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1999","text":"ليس العاقل من ترك الدنيا، بل العاقل من آثر الآخرة على الدنيا. لأن ترك الدنيا رهبانية، ولا رهبانية في الإسلام.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2000","text":"ابتعد عن حرام الدنيا، واستعن بحلالها على طاعة الله.","kind":"hikma","topic":"الإيمان والعبادة","note":"تعليق منه على قول: تعلق بالله تعالى وابتعد عن الدنيا فإنها فانية","source":"شذرات (ملف وورد)"},{"id":"m2001","text":"من يستطيع أن يخلق السموات والأرض وما بينهما في ستة أيام، يستطيع أن يأتي بمثل القرآن، لأن الخالق هو القائل، والقائل هو الخالق، فإن كان الإنسان لا يستطيع أن يخلق ذبابة، فهو لا يستطيع أن يأتي بسورة من مثله، ولو كانت ثلاث آيات فقط.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2002","text":"بادروا الزمان قبل فوات الأوان، فنحن في موسم الزراعة، والدنيا مزرعة الآخرة. أكثروا من بذور الخير: صدقات، وقفيات، وأفعال بر، ولا تُهدروا الأوقات، فقليل دائم خير من كثير منقطع. وأحب الأعمال إلى الله أدومها وإن قلّ.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2003","text":"الذكاء ينمو بقراءة الكتب النافعة، واستماع الحكمة، ومجالسة العقلاء والعلماء والأدباء واستشارتهم، فمن شاور الرجال شاركها عقولها.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2004","text":"العدل ميزان الحياة، به تُؤدى الحقوق، وتُرد المظالم، وتطمئن النفوس. والوفاء بالعهد شرف الأخلاق، وسرُّ الثقة بين الناس، به تُحفظ المواثيق، وتدوم العلاقات على أسس راسخة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2005","text":"الشهادات والتوثيقات ضمان لحفظ الحقوق، ولردع النزاعات.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2006","text":"السلام مفتاح الأمان، وطمأنينة تُطفئ نار المخاوف، به تستقيم الحياة، وتتعايش الأمم في ظل الاطمئنان والاستقرار.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2007","text":"طاعة ولي الأمر حصنٌ يحمي الجماعة والأفراد، وأساسٌ لوحدتها وقوتها، فهي طاعة تُقيم النظام، وتردع الفوضى، وتحفظ الأمن.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2008","text":"الإيمان يُنير القلب بطهارة التوحيد، والوضوء يغسل الجوارح من أدران الصغائر، والتوبة تمحو آثار الكبائر وترفع قدر النفس. والصلاة مقام الخضوع لله، وميدان التواضع، وسر النظام. والزكاة تزكية للروح وتحريرها من أغلال الشح، والصيام تدريب على الإخلاص وصفاء النية. والجهاد رفعة للأمة وعزة لكلمتها، والحج اجتماع على التوحيد ورمز لوحدة المسلمين. أما الأمر بالمعروف والنهي عن المنكر، فهما حصن يحمي الشريعة من التحريف، ويحفظ السنن من الاندثار، ويقي المجتمع شر العادات الدخيلة، ليبقى الدين منارة للحق، وهادياً للعباد إلى الصراط المستقيم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2009","text":"اختلاف الأذواق والآراء سنة كونية، وطبيعة إنسانية، فلا بد أن تسمو المناقشات بروح الود، وتنضبط بأساليب راقية، بعيدًا عن الألفاظ الجارحة والكلمات السوقية.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2010","text":"من طبيعة البشر المبالغات في المدح والقدح، والثناء والازدراء، والافتخار والإنكار. فلا تصدق كل ما تسمع، ولا تقل إلا الصدق.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2011","text":"مراهق الستين كالشمعة، تسطع لحظة قبيل أن تنطفئ، ثم تخمد، تاركة خلفها سحابة دخان سوداء.","kind":"hikma","topic":"الحياة والزمن","note":"تذييل على قصة زميل استشاره في الزواج بثانية وهو في الستين","source":"شذرات (ملف وورد)"},{"id":"m2012","text":"الدنيا إذا أعطت سلبت، إذا أسعدت أتعست، إذا أضحكت أبكت، إذا أكملت أنقصت، إذا رفعت وضعت، الدنيا خداعة غرارة.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2013","text":"الإدراك الجزئي لا يصف الحقيقة، وأن الأدراك الكلي أقرب إلى الحقيقة.","kind":"hikma","topic":"العقل والحكمة","note":"مغزى قصة العميان الثلاثة والفيل","source":"شذرات (ملف وورد)"},{"id":"m2014","text":"يا ابن آدم، يا ابن الطين، يا ابن التراب، يا ميت ابن ميت، ولك في الموت نسب عريق، إن الله عَزَّ وجَلَّ قد وهبك مفاتيح الجنات، فلا تضيعها، المفاتيح هي (الإيمان والعمل الصالح)","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2015","text":"صلة الأرحام هي جسر يمتد بالمودة بين الأقرباء، ومفتاح يفيض بالبركة في الرزق وطول البقاء.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2016","text":"القصاص هو ميزان العدالة الذي تُصان به الحقوق، وتُشفى به صدور المظلومين وذويهم، وهو سياج رادع لكل نفس أغواها شيطانها إلى الظلم أو الجريمة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2017","text":"الدنيا رحلة قصيرة، والآخرة إقامة طويلة.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2018","text":"الدنيا وقت محدود، والآخرة خلود ممدود.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2019","text":"الدنيا زائلة، والآخرة باقية.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2020","text":"الدنيا دار المشقة والعناء، والآخرة دار النعيم والرخاء.","kind":"hikma","topic":"الحياة والزمن","note":"له صيغ أخرى","source":"شذرات (ملف وورد)"},{"id":"m2021","text":"الدنيا زيارة، والآخرة إقامة.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2022","text":"الدنيا أمد، والآخرة أبد.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2023","text":"الدنيا تفنى والآخرة لا تبلى.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2024","text":"فاز من اشترى الباقي بالفاني، وخسر من اشترى الفاني بالباقي.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2025","text":"دخلت امرأة كبيرة في السن فصول محو الأمية، وتعلمت كتابة اسمها: منيرة سعد. دمعت عيناها وقالت: “ما يصير أكتب اسمي قبل اسم أبي.” فوجدوا لها حلاً: سعد بنته منيرة.","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2026","text":"تعجبني فلسفة الماء في الحياة: إذا اعترض سبيله عائق غيَّر مجراه. بعض الأحيان يقتلع الصخر العائق، ويعلو التل الشاهق، ويدهده الجلمود بمائه الدافق.","kind":"hikma","topic":"النجاح والإبداع","note":"الجملة الثانية تعقيب منه","source":"شذرات (ملف وورد)"},{"id":"m2027","text":"من إكرام الضيف الترحيب الحار، وإظهار السرور بقدومه، والاهتمام به بسؤاله عن إنجازاته واهتماماته، وإفساح المجال له ليحدثنا عما يحب، مع الإصغاء بإعجاب وتقدير. كما نحسن وفادته ونُشعره بالمودة والاحترام، فنكرمه بأفضل مما نحب أن نُكرم به لو كنا في ضيافته، امتثالًا لقوله تعالى: “فحيوا بأحسن منها”.","kind":"hikma","topic":"الأخلاق والآداب","note":"بعنوان: إكرام الضيف","source":"شذرات (ملف وورد)"},{"id":"m2028","text":"المال يرفع الرؤوس، ويُبهج النفوس، ويُقرِّب العروس، ويُزيل العُبوس، وبه تُفتح لك الأبواب وعلى عتبات القصور تدوس، وفي مجالس الكبار تُقَبَّل وتبوس، وبين الولائم تحوس، لكن احذر أن يُنسيك الأصول فتكون بلا إحساس ولا خُلُقٍ ملموس.","kind":"hikma","topic":"المال والاقتصاد","note":"بعنوان: مزايا المال والفلوس","source":"شذرات (ملف وورد)"},{"id":"m2029","text":"من بلغ السبعين اشتكى من غير علة.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2030","text":"من لم يكن عقله أكبر خصال الخير عنده، كان حتفه في أكبر خصال الخير عنده، فكرمه يصير إسرافا، وشجاعته تصير تهورا، وكلامه يصير هذرا، وصمته يصير عِيًّا، وهلم جرًّا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2031","text":"إذا اتهمت نفسك فكن معتدلا، وإذا أحسنت الظن بها فكن مقتصدا.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2032","text":"إذا شاع الاستهتار بقوانين المرور، جاز سَنُّ قوانين أشد، لحمل السائقين على احترام القوانين، مع الجدية في إيجاد حلول مناسبة: كالأنفاق أو الجسور مثلا، لتيسير المرور، مع المحافظة على سلامة المواطنين.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2033","text":"قبل أن تنصح الشباب تذكر أيام شبابك ونزغك وعنفوانك وشطحاتك وتهوراتك، وأن الشباب شُعبة من الجنون، فقدر لهم أعمارهم وقلة تجاربهم، حتى لا تُبالغ في تعنيفهم وتأنيبهم وتسفيههم وتُحقيرهم، فتُطفئ شمعتهم، وتُخمد نشاطهم، وتطأ وردتهم، وتغمهم وتُهَجِّرَ ابتسامتهم، فكن ناصحا لطيفا، وواعظا خفيفا، ومؤدبا لا معنفا ولا مؤنبا ولا مثربا.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2034","text":"الجمال جمال الروح، الحلاوة حلاوة اللسان، الزينة زينة الأخلاق، البياض بياض القلب، الرقة رقة الآداب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2035","text":"كُلْ في بعض بطنك تصح، ولا تأكل في كل بطنك فتَسْقُم.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2036","text":"درهم حظ خير من قنطار اجتهاد.","kind":"mathal","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2037","text":"كيف تحمي نفسك من القدر وقد رُفعت الصُحف وجفَّت الأقلام، فعليك بالصبر والشكر والذكر، فلن تعدم خيرا من رَبٍّ رحيم حليم كريم، لَلَّه أرحم بعبده من الأم بوحيدها.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2038","text":"لا تُخَزِّنُوا في بيوتكم الطعام والشراب، اعتبروا أن جميع ما في الجمعيات والمخازن التموينية، ملككم وتحت تصرفكم، وهي مخازنكم، ادفع وخذ قدر حاجتك، ولا تُخَزنوا في بيوتكم، فأصبحت البيوت بمثابة جمعيات صغيرة، واللذة على قدر الحرمان، وكل مبذول مملول، والقناعة كنز لا يفنى، ولا تنصاعوا لشهوات الشراء والتخزين، نحن لسنا في حرب لتخزين التموين.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2039","text":"لما خالطتُ الناس عرفتُ قدرَ كلبي، ولما اقتنيتُ كلبا لم أرضَ نفسي للناس، ولم أرضَ الناس لنفسي.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2040","text":"أسرع طريق للصعود أن تُعَقِّب على عالم مشهور مُبدع، بدليل واضح مُقنع، بقول ظريف، وأُسلوب لطيف، وأدب شريف، وتتكرر الانتقادات الإيجابية، مشفوعة بالثناء على صاحب القول، بإسلوب فصيح، وبرهان صحيح، وقول نصيح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2041","text":"رأيت عالما عابدا يمتحن طالبات منتقبات، يُولِّيهن ظهره، ويتجه نحو السَّبُّورة طول فترة الامتحان، ويقرأ في كتاب الله، وكان بوسعه أن يستقبلهن وهو ينظر في المصحف، فلقد ضيع الأمانة من حيث بالغ في الورع والصيانة، فالعلم نور ساطع، والفهم ضياء لامع، والعقل للترجيح نافع.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2042","text":"فإذا أردت أن تُقَيِّم قولا فلا تنظر للقائل، بل تجرد وتحرر، وركز على القول لا على القائل.","kind":"hikma","topic":"العقل والحكمة","note":"عبرة قصة الدكتور الذي عكس الأقوال على طلابه","source":"شذرات (ملف وورد)"},{"id":"m2043","text":"ذمته نظيفة لأنه لا يستعملها.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2044","text":"إذا رأيت الوعول ترعى في السهول، والجمال ترعى فوق الجبال، فانتظر الساعة.","kind":"hikma","topic":"الحياة والزمن","note":"كناية عن انقلاب الموازين","source":"شذرات (ملف وورد)"},{"id":"m2045","text":"إذا الرؤوس نامت والعصائص قامت فانتظر الساعة.","kind":"hikma","topic":"الحياة والزمن","note":"كناية عن انقلاب الأحوال","source":"شذرات (ملف وورد)"},{"id":"m2046","text":"لو كانت البومة تُؤكل ما تركها الصياد.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2047","text":"رُبَّ لحظ أبلغ من لفظ.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2048","text":"رُبَّ دموع تُحرك ما بين الضلوع أشد من خُطَبٍ بليغة في الموضوع.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2049","text":"لكل عمل ثواب، ولكل سؤال جواب، ولكل بيت باب، ولكل معصية توبة أو عفو أو عقاب.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2050","text":"(الإسلام هو الحل) ليس الإسلام الذي في الكتب والمكتبات، لأنه كلام نظري، إنما الإسلام العملي التطبيقي الذي في ميادين حياة المسلمين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2051","text":"لا تُحسن الثقة بالوحش المدرَّب، لأن غريزته قد تغلب عليه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2052","text":"لا عتاب بعد الموت، ولا يأس قبل الموت.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2053","text":"لا تُصدِّق كل ما يُقال، ولا تُحدث بكل ما تسمع.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2054","text":"الزواج لا يُبنى على الحُبِّ وحده، بل يُبنى على الحُبِّ ومكارم الأخلاق وشرف الأعراق، فإذا خمدت جَذوة الحُبِّ تبقي مكارم الأخلاق، وشرف الأعراق، فهذا ضمان لبقاء الحياة الزوجية السعيدة الهنية.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m2055","text":"فسلاح الأخلاق الحميدة هو الذي يُحقق النهايات السعيدة.","kind":"hikma","topic":"الحياة الزوجية","note":"خاتمة قصة بعنوان: تأثير الأخلاق الحميدة على الآراء والمواقف العنيدة (الفقرتان)","source":"شذرات (ملف وورد)"},{"id":"m2056","text":"من كرامة المؤمن عند الله، أنَّ الله أمره وأَذِن له أن يقف بين يديه في اليوم خمس مرات، يستقبل اللهَ بوجهه، ويستقبله اللهُ بوجهه، ويسأل الله ما يريد من خير الدنيا والآخرة، فيجيب الله دعاءه حالا أو مآلا، أو يدفع عنه من البلاء بقدره، ودعاء المؤن لا يُرد، تفضلا لا واجبا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2057","text":"لا يُعجبني نشر النكت والتعليقات التي تُثير الشعوب، وتزيد في اتسعاع الشرخ الواقع بينها.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2058","text":"العبث بتغيير خِلقة الله في الظاهر أو الباطن؛ الأصل فيه عدم الجواز عقلا وشرعا وصحة، إلا للضرورة القصوى، وزيادة الوزن علاجها بتقليل الوجبات كما وكيفا، واتباع القواعد الصحية في عادات الطعام والشراب، لا بالعبث بخلقة الله، طمعا في تحقيق الهدف السريع، والكسب السريع.","kind":"hikma","topic":"الصحة والنفس","note":"بعنوان: زيادة الوزن","source":"شذرات (ملف وورد)"},{"id":"m2059","text":"المسافر يوم السفر كأنه أُم العروسة فاضية ومشغولة، ومن حرصه ألا ينسى شيئا قد ينسى بعض الأشياء، وابن الستين والسبعين يشبه المسافر يوم السفر، فعليه أن يُكثر من الصدقات والأعمال الصالحات، ويؤدي الزكاة ويحج","kind":"hikma","topic":"الحياة والزمن","note":"حُذفت الآية التي في آخر","source":"شذرات (ملف وورد)"},{"id":"m2060","text":"يا فتيات ويا فتيان اطلبوا رضوان الله، والبركة في الأرزاق والأعمار، بطاعة الوالدين والبر بهما. إن الله وهبكم بهما بابين من أبواب الجنة، فلا تضيعوهما.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2061","text":"تعلمت في بيتي الكلام، وتعلمت في مدرستي النقاش، وتعلمت في مجتمعي الجدال، ثم وجدت الصمت رخيصا فاشتريته، ثم شرعت أقرأ كتب الحكماء والأدباء والعلماء، فاصبحت حكيما، فالعلم بالتعلم، والجهل بالعزلة والإنطواء، وعدم مجالسة العلماء والحكماء والمجربين والأدباء.","kind":"hikma","topic":"العلم والثقافة","note":"بعنوان: كيف تكون حكيما، وصدّرها بقوله: قال حكيم","source":"شذرات (ملف وورد)"},{"id":"m2062","text":"إن بعض الشجاعة قلة أدب، وبعض التسامح ذلة، وبعض الصمت ثقل دم، وبعض طلاقة اللسان هذيان، وبعض الجود إسراف، وبعض الاقتصاد بخل، فالأخلاق الحميدة لها موازين محمودة، والطرفان مذمومان.","kind":"hikma","topic":"الأخلاق والآداب","note":"بعنوان: الأخلاق الحميدة","source":"شذرات (ملف وورد)"},{"id":"m2063","text":"التحديث والتجديد المبني على العلم والمصلحة، أمر إيجابي، وطبيعة بشرية، ومنهج عقلي مقبول ومطروق.","kind":"hikma","topic":"العقل والحكمة","note":"من مقالة: مشروعية مراجعة الدستور","source":"شذرات (ملف وورد)"},{"id":"m2064","text":"أقوى عامل لبناء الذات، أن تستعين بالله على طلب العلم والمعرفة والثقافة، بكثرة القراءة والسماع. أقوى عامل لهدم الذات، عدم طلب العلم والمعرفة والثقافة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2065","text":"اجتهد في طلب الدنيا لتقي نفسك مذلة السؤال، واجتهد في طلب الآخرة لتقي نفسك خسارة المآل.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2066","text":"بعض الفنانين يَهَبُون زهرة شبابهم للفنِّ، ويَهَبُون شيخوتهم لِلَّه، بالتوبة والإقبال على الله، والله أرحم بهم من أنفسهم بأنفسهم، فيتقبلهم ويُبدل سيئاتهم حسنات، فالله واسع الرحمة عظيم الهبات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2067","text":"راكبو البحار دود على عود، فكبروا الله واذكروه في ثَبَجِ (وسط)البحر، تجلبوا الملائكة عليهم السلام، وتطردوا الشياطين، وذاكر الله جليس الرحمن، وجليس الرحمن أرجى أن يكون في أمان واطمئنان.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2068","text":"لا تدعوا للشيطان فرجة ليفرق بينكم، فإن الشيطان يدخل بين الفرجات، ليُحرش فيما بينكم، فإن ما تكرهون في الجماعة خير مما تُحبون في الفرقة، فيد الله فوق الجماعة، ويد الشيطان بين يد الفرقة.","kind":"hikma","topic":"العلاقات والناس","note":"تعليق على حديث: تعافوا الحدود فيما بينكم","source":"شذرات (ملف وورد)"},{"id":"m2069","text":"لا يزال الناس بخير ما تواصلوا، وأعان غنيهم فقيرهم، ودعا فقيرهم لغنيهم، وعطف كبيرهم على صغيرهم، ووقر صغيرهم كبيرهم، وإذا تواصل ذوو الأرحام فيما بينهم وتراحموا، عمهم الله برحمته، وبارك لهم في أرزاقهم وأعمارهم، وإذا تقاطعوا وتدابروا، فقد حرموا أنفسهم من بركات الله في التواصل.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2070","text":"بعض الناس يغلب عليهم الطيش وروح الانتقام، ويبطشون ويتجاوزن العدل والصواب في تصرفاتهم الهوجاء، ثم إذا ما كبروا وخارت قواهم، وخمدت شمعتهم، وذبلت زهرتهم، يندمون على تصرفاتهم الخرقاء، التي ارتكبوها مع أقاربهم وضعفة الناس والأصدقاء، هلا كان هذا وهم في عنفوان شبابهم وقوة بطشهم، فالعاقل لا يرتكب حماقات، تجر له الويلات، ويندم عليها بعد الفوات.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2071","text":"من الأفضل أن يكون في الثلاجة نوعان من الفاكة ( لا عشرة أنواع ) هذه ثلاجة وليست فرضة أو جمعية.","kind":"hikma","topic":"المال والاقتصاد","note":"بعنوان: نصيحة لربة المنزل","source":"شذرات (ملف وورد)"},{"id":"m2072","text":"الإنسان يسعد ويزهو ويتشرف عندما يقف بجوار أمير أو وزير أو ملياردير كبير، فما ظنُّك بمن يقف بين يدي رَبِّ العالمين، في اليوم خمس مرات، يا له من فضل كبير، وتكريم عظيم، إنه رَبٌ كريم بالمؤمين رؤوف رحيم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2073","text":"السعي مفتاح الرزق، فمن سعى رُزق، ومن لزم البيت حُرم من الخبز والتمر والزيت.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2074","text":"من ترك الشبهات، عاش نقي الثوب إلى الممات.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2075","text":"من أجاد الاحتراف ضمن الاعتلاف.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2076","text":"الصمت وقت الثرثرة بلاغة، الصمت وقت الشهادة خيانة، الصمت وقت الغضب قوة، الصمت وقت سماع الباطل جبن، الصمت وقت الفوز تواضع، الصمت وقت الحزن صبر، الصمت وقت القرار تردد، الصمت وقت الفتنة حكمة، الصمت وقت سماع النصيحة أدب، الصمت وقت الحاجة عزة، الصمت وقت التفكير تدبير.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2077","text":"الوتساب ينقل الزهرة، والبعرة والتمرة والجمرة، والذهب والحطب، والخيار والصَّبَّار، فلا تُبادروا بالنشر والتصديق إلا بعد التحقيق والتدقيق، حتى لا تقعوا في القدح والتقريع.","kind":"hikma","topic":"الكلام والصمت","note":"العنوان (الوتساب) مدمج في أول النص","source":"شذرات (ملف وورد)"},{"id":"m2078","text":"كانت رياضة المسلم في صلاته وصيامه وحجه وعمرته، وفي سباقه وركوب خيله، ورميه بسهامه، رياضة تخدم مقاصده العظمى: لنشر الإسلام وللحفاظ على بيضة المسلمين، ولإخراج الناس من ظلمات الشرك والجهل إلى نور الإيمان والإسلام والعلم، رياضة لها أهداف سامية، لا رياضة التباهي بالقوة والعافية والجوائز الزاهية، وفي بعضها مخاطرات جسيمة، وعاهات مستديمة.","kind":"hikma","topic":"الإيمان والعبادة","note":"بعنوان: الألعاب الرياضية","source":"شذرات (ملف وورد)"},{"id":"m2079","text":"كان إذا تفشى الشرك، وعمَّ الظلم والفساد، يُرسل الله نبيا، ليقوم بمهمة الإرشاد والإصلاح، وببعثة محمد عليه الصلاة والسلام، انقطع الوحي، وخُتمت النبوات، فأصبحت مهمة الإرشاد والإصلاح والتدخل على عاتق أتباع خاتم النبيين عليهم السلام، والله معهم بنصره وتأييده، ولن يخذلهم، ما تمسكوا بإسلامهم، ونصروا دين ربهم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2080","text":"أُصيب والده بجلطة، فمات في المستشفى، فخرج سبب الوفاة مرض الكورونا، فانزعج ابنه، فقال : هو مات بالجلطة، فقال الطبيب : وما سبب الجلطة؟ قال : اصيب بحزن شديد واكتآب حاد، فقال الطبيب: وما هو السبب ؟ قال : خسر أمواله الكثيرة، قال: ولماذا خسر أمواله ؟ قال : بسبب الكورونا ، فقال الطبيب : ونحن ماذا قلنا : مات بسبب الكورونا .","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2081","text":"البخيل يعطيك زبيبة ويأخذها تمرة. الكريم يمنحك البعير، ويشكرك على صاع من شعير.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2082","text":"لا يجوز شرعا ولا عقلا ولا أخلاقا، الإيحاء بالتقصير العام بسبب التقصير الخاص.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2083","text":"أجرأ من ذُبابة","kind":"mathal","topic":"الأخلاق والآداب","note":"من الأمثال العربية؛ لأنها تقع على أنف الملك، وعلى وجنتي الأسد","source":"شذرات (ملف وورد)"},{"id":"m2084","text":"الخطأ في العفو خير من الخطأ في العقوبة ، والخطأ في براءة المجرم خير من الخطأ في عقاب البرىء ، والخطأ في الحكم بإسلام الكافر خير من الخطأ في تكفير المسلم ، والخطأ في زيادة درجة الطالب خير من الخطأ في نقص درجته.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2085","text":"أول ما يبدأ الفساد في رأس السمكة، ثم يسري رويدا رويدا حتى يبلغ ذيلها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2086","text":"لو عاقبنا الأول لما تجرأ الثاني.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2087","text":"فساد العامة يتحمله الخاصة، وفساد الخاصة يتحمله خاصة الخاصة، وهلمَّ جرّا، لأنهم قصروا في الحزم والعزم في عقاب وردع المُفسدين أولا بأول، فتفشى الفساد في الواقع، فاتسع الخُرق على الراقع.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2088","text":"اللغة العربية: لغة الضاد والتضاد.","kind":"hikma","topic":"العلم والثقافة","note":"وأتبعها بأمثلة للتضاد كالسُّدفة والصريم والصارخ","source":"شذرات (ملف وورد)"},{"id":"m2089","text":"الأصل في الرجال الاقتصاد، والأصل في النساء الإسراف، فالإسراف في الرجال أقل من النساء، والاقتصاد في النساء أقل من الرجال. ولولا النساء لبارت السلع، أعطني عشر نسوة، أبني لك مجمعا تجاريا ناجحا.","kind":"hikma","topic":"المال والاقتصاد","note":"بعنوان: مقارنة بين النوعين","source":"شذرات (ملف وورد)"},{"id":"m2090","text":"مجالسة العلماء مفارقة للجهلاء. مرافقة العقلاء مفارقة للسفهاء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2091","text":"من افتقر هان على أهله، ومن استغنى كرم على أهله.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2092","text":"من الأدب ترك التكلف بالأدب بين الأصدقاء، فيمزحون ولا يتزمتون.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2093","text":"إحدى مصائب المجتمع، بأن قليل الأدب الأرعن، يظن بأن شخصيته قوية، وهو لا يعلم بأنه في أعين الناس، سفيه أحمق، سيء الخلق قليل المروءة، وشر الناس من اتُقي لفحشه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2094","text":"المعادلة اليقينية للأبدان الحية: أكل زائد عن حاجة الجسم= وزن زائد، أكل ناقص عن حاجة الجسم= وزن ناقص.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2095","text":"السينما صناعة غربية، تنشر العادات والسلوكيات والأخلاق الغربية، لتحل محل السلوكيات والآداب والأخلاق المحلية ( الإسلامية ) بأساليب ناعمة ندِيَّة، فهي مثل الحيَّة، ناعم ملمسها والسم في أنيابها.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2096","text":"يُفضل التغريدات القصيرة، كأنك تقطف زهرة حمراء وتلقيها على الأصدقاء، ولا يُفضل الرسائل الطويلة، كأنها ليلة شتاء، طويلة وباردة وظلماء.","kind":"hikma","topic":"الكلام والصمت","note":"بعنوان: نداء للأصدقاء، الواتس آب؛ له صيغة أخرى","source":"شذرات (ملف وورد)"},{"id":"m2097","text":"لا تحزن ولا تحتار. كُلُّ مشكلة ولها حَلٌّ. كُلُّ عُقدة ولها فَلٌّ.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2098","text":"استعن بالله ولا تيأس، فتدبير الله لك خير من تدبيرك لنفسك.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2099","text":"الحب في الشباب مثل النار تحت الكباب. العشق بعد الستين مثل المشي في الطين.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2100","text":"اللقمة ما تحلو ولا تطيب، الا مع وجود الصديق أو الحبيب أو القريب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2101","text":"ابن آدم إذا طعن في العمر، وأصبح من الشباب الكبار، لم يبق لدية من النشاط إلا النصيحة والانتقاد.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2102","text":"من أيقن بالخلف المضاعف من الله الكريم، جاد بالصدقات والوقفيات وأعمال البِرِّ والخيرات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2103","text":"من لم يصُن نفسه ويكرمها أهانه الناس.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2104","text":"من لم يُكابد المشقة والأهوال، لم يُحقق الأماني والآمال.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2105","text":"نعم الشفيع بين يدي الحاجة الهدية.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2106","text":"الصدقات صابون الذنوب، وبذل المال صابون القلوب.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2107","text":"إن كانت نفسك التي بين جنبيك لا تستجيب لك في كل ما تريده منها، فكيف تريد من ابنك أن يستجيب لك في كل ما تريده منه. فعليك بالرفق واللين، والتجاوز والتسامح، ولا تُكثر اللوم والعتاب، فكثرة العتاب تفرق الأهل والأحباب.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2108","text":"من لم يصبر على كلمة الأحمق سمع كلمات.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2109","text":"الصين لا تزال تفاجئ العالم بمعرفة أسرار الطبيعة الخفية، وخواص المخلوقات الغامضة المطوية، وعجزوا أن يكتشفوا حقيقة الألوهية، ووحدانية الله سبحانه وتعالى مع كثرة الأدلة الكونية والوجدانية والعقلية والفطرية.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2110","text":"فقد الإخوان تصدُّع في البنيان. فقد الأصدقاء شق في البناء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2111","text":"ما أهون المرضُ على العُوَّادِ، وما أشده على من هو متمدد في المِهاد، فلا يُطل المكث عنده العُوَّاد.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2112","text":"مقدورات العبد يطلبها بالسعي والدعاء، كطلب الرزق. وما لم يكن من مقدورات العبد فيطبها بالدعاء، كطلب المطر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2113","text":"قال: تزوجت، وزوجتي نفور مثل المُهرة غير المعسوفة، وتأبى أن أدنو منها، فتجادلت معها، فاحتدَّ النقاش، فضربتني كفًّا بلا تفكير، فتمالكت نفسي وكظمت غيضي، فسكتُّ ولم أفعل شيئا، فأخذتْ طِيلة اليوم تسعى لخدمتي وتطلب رضاي، وبتنا في خير ليلة، لدرجة أنني تمنيت لو ضربتي كل يوم كفًّا ! لأن مردوده أرباح وفيرة، كثيرة ومثيرة .","kind":"tarfa","note":"عنوانها: قصة طريفة غريبة","source":"شذرات (ملف وورد)"},{"id":"m2114","text":"مائدة البخيل وادٍ غير ذي زرع. مائدة الكريم وادٍ فيه الأشجار والثمار والأنهار","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2115","text":"نِعّم لباس المرء العافية","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2116","text":"من طلع الوات ساب وأصبح كثير من الناس بتشبهون بالصحفيين، يرصدون ويتابعون ويحللون ويننقدون ويرسلون ويعلقون ويجادلون ويتحمسون، وهم عالة على مهنة الصحافة، وما أكثر حاطب الليل فيهم، فعلى المرء أن ينتبه ويحذر ويتحقق قبل أن ينشر ويُرسل أوهاما وأكاذيبا وفتنة وإثما.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2117","text":"هلك من اتبع هواه، فأعرض عمن خلقه فسواه، وهو ربه ومولاه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2118","text":"الهوى صنم معبود، يُورد صاحبه المهالك والطريق المسدود.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2119","text":"علاج حوادث الدهر، بالصلاة وقوة الصبر.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2120","text":"نَحِ الجهل عنك بكثرة طلب العلم وكثرة السؤال.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2121","text":"نِعْمَة الوقاية من الشهوات غض البصر.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2122","text":"نِعْم العون على المروءة المال.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2123","text":"الإنسان مخترق من الشيطان، فليُحصن نفسه، بالذكر والدعاء، وأذكار الصباح والمساء، ومخالفة الشهوات والهوى، ولعله يسلم من شره ووسوسته.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2124","text":"لا تُقحموا القرآن في نقاشاتكم، إلا ما كان واضحا كوضوح الشمس في رابعة النهار، فالقرآن حمَّال ذو وجوه، فمن قال بالقرآن برأيه فأصاب فقد أخطأ، أصاب في جزئية وأخطأ في المنهج، دعوها للراسخين في العلم والتفسير، ومن تكلم في غير تخصصه، أتى بالعجائب والغرائب، وجرأ على نفسه المُنتقد والمُفند والعائب.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2125","text":"سوء الظن بالأعداء من الفِطَن، وحسن الظن بهم من الغفلة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2126","text":"كونوا كنبيكم عليه الصلاة والسلام لقومه، عندما قال لهم: إذهبوا فأنتم الطلقاء، ولا تكونوا كقومه له. كونوا كيوسف عليه السلام لأخوته، ولا تكونوا كأُخوة يوسف لأخيهم.","kind":"hikma","topic":"الأخلاق والآداب","note":"حُذفت الآية التي في آخر","source":"شذرات (ملف وورد)"},{"id":"m2127","text":"النار إذا لم تجد شيئا تأكله، أكل بعضها بعضا.","kind":"mathal","topic":"العلاقات والناس","note":"تعليق على أبيات الحطيئة في هجاء نفسه","source":"شذرات (ملف وورد)"},{"id":"m2128","text":"النظر في جمال الطبيعة وجمال الزوجة والأولاد، يُسعد النفس ويُنطق اللسان بالتسببح والحمد.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2129","text":"السلطان ظِلُّ الله في أرضه، يأوي إليه المظلوم والمكلوم والمحروم.","kind":"hikma","topic":"السياسة والقيادة","note":"صدرها مأثور: السلطان ظل الله في الأرض","source":"شذرات (ملف وورد)"},{"id":"m2130","text":"أعظم السعادة طول العمر في طاعة الله تعالى والعافية.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2131","text":"الغم والخوف والحزن، من الانفعالات الطبيعية، وهي نتائج وانعكاسات لظروف غير ملائمة، وهي في أصلها غير اختيارية، ولها دور إيجابي في الحياة، ليأخذ الإنسان حذره ويقي نفسه من المكروه، فإذا كانت بالاعتدال، فالمقصود من النهي عنها عدم المبالغة والتهويل بها، ومحاولة تخفيفها بالأسباب المناسبة: كالصبر والصلاة والذكر والدعاء، والخروج في النزهة والسفر، والسير في أحضان الطبيعة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2132","text":"بعض المتقاعدين مثل الملح، إن غاب عن البيت، أصبح البيت هادئا، وإن حضر البيت رفع ضغطهم، فلا تكن منهم. بعض المتقاعدين مثل السكر، إن غاب عن البيت أصبح البيت مُرًّا، وإن حضر أصبح البيت حلوا، فكن أنت منهم. فأهل بيتك أولى الناس ببرك ومعروفك وإحسانك.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2133","text":"كان رجل بقارا، يُحسن معاشرة عقيلته ، ويتغزل بجمالها وفتنتها ، فإذا أصبح يُغرد بحسنها وبهائها : صباح الخير يا قشطة صباح الخير يا زبدة صباح الخير يا لبنة صباح الخير يا حليب صباح الخير يا لبن صباح الخير يا روب فاستيقظ مرة متأخرا ، فخرج من البيت مسرعا ، فلم يتمكن من التغزل بها ، وشق عليه ألا يُسمعها مُعَلَّقة الغزل ، فاختصرها بكلمة واحدة وهو خارج فقال : صباح الخير يا بقرة . لقد بالغ في الإساءة من حيث يظن أنه قد أحسن، ولكن الأعمال بالنيات .","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2134","text":"الموت نهاية معاناة المؤمن، وبداية معاناة الكافر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2135","text":"إنَّ عليك من الله عيونا تحفظك وتراك، فاحذر أن تراك حيث نهاك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2136","text":"احرص على العلم تُوقرك الرجال، واحرص على الأعمال يأتيك المال.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2137","text":"السؤال المُحبط: ماذا أنجزت في حياتك؟ الجواب: أعظم إنجاز أنجزته في حياتك الدنيوية والبرزخية والأُخروية، هو أنك آمنت بالله وكفرت بالطاغوت، وفاظت نفسك وأنت على هذه العقيدة الصحيحة.","kind":"hikma","topic":"الإيمان والعبادة","note":"علّق: يجوز فاظت وفاضت","source":"شذرات (ملف وورد)"},{"id":"m2138","text":"البرهان العملي أقوى من البرهان العقلي، لأن له دلالتين: دلالة عقلية ودلالة حسية، وهذا مثل استدلال إبراهيم - عليه السلام - على قومه في ابطال آلهتهم بتحطيمها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2139","text":"بعد البحث والتقصي إن لم تجد المعلومة، ولم تستطع فَكُّ الألغاز المطوية المضمومة، فلا تحمل همَّها، فارمها فوق الكوم الأكبر، كوم المجهولات، لأن كوم المجهولات أكبر من كوم المعلومات بكثير جدا.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2140","text":"السياسيون لهم مصطلحات ومفردات وتعريفات وتحليلات وتخويفات وتطمينات، من خلالها يستطيعون أن يدعموا آراءهم واستنتاجاتهم، ويؤثروا على المستمعين، حتى يقبلوا كلامهم كله أو أكثره أو بعضه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2141","text":"إن الله سبحانه قرن وعده بوعيده، وآيات الترغيب بآيات الترهيب، ليكون العبد راغبا راهبا، مقبلا على الطاعات، مدبرا عن المعاصي، وإن ألَمَّ بشيء من المعاصي فأبواب التوبة مُفَتَّحة بوجه الكافر والملحد والعاصي، ويُبدل الله سيئاته حسنات، إن تاب قبل الممات، ولو قبل الغرغرة، فتقبض روحه ملائكة الرحمة البررة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2142","text":"بِرُّ الوالدين مفتاحه بيد الأبوين، فيربيان أولادهما منذ نعومة أظفارهم على مكارم الأخلاق: توقير الكبير والعطف على الصغير، وعلى بِرِّ الوالدين وصلة الأرحام والشفقة على الأيتام، فالراحمون يرحمهم الرحمن، فتصبح لهم مكارم الأخلاق طبيعة وعادة، لا يعانون ولا يتكلفون في مزاولتها.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2143","text":"العمر يجري ويجري، ونحن ندري ولا ندري، بل ندري، ولكن الكسل في عروقنا يجري، هلا تسابقنا في فعل الصالحات والخيرات بدري، واستعذنا بالله من الوسواس الذي يجول في النفس والصدري.","kind":"hikma","topic":"الحياة والزمن","note":"حُذف الدعاء الذي في آخر","source":"شذرات (ملف وورد)"},{"id":"m2144","text":"يا أيها الشباب يا طلبة العلم: لا تُشددوا على الناس، ولا تُقنطوهم من رحمة الله، فالناس ليسوا من السابقين الأولين، ولا من القرون المفضلة الأُولى، ولا من الذين اتبعوهم بإحسان من العصور المتقدمة، فادعوهم بالحكمة والموعظة الحسنة، وتجنبوا الفحش والتفحش، والغلظة والتبجح، والاستعلاء والتكبر، في دعوتهم وتذكيرهم وموعظتهم، وادخلوا عليهم من باب الإكرام والاحترام والجود والإنعام، فهذه بوابة قلوب الأنام، فالله جلَّت حكمته أكرم العباد بعظيم الهبات، قبل أن يأمرهم وينهاهم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2145","text":"نحن نؤكد على أهمية التعايش والتكيُّف مع الظروف المحيطة، مع الحفاظ على أركان الإيمان والقيم الأخلاقية، ومحاولة تحسين الظروف، فالتعايش والتكيُّف ليسا فقط وسيلتين لتيسير الحياة وتخفيف المعاناة، بل هما أيضًا مصدر للقوة النفسية والجسدية التي تُساعد الإنسان على التحمل والصبر، كما أن هذا التوازن يضمن استمرارية الحياة بيسر وبشكل يُسهم في تحقيق المنافع للإنسان ويقيه من المفاسد والأضرار، بقدر الإمكان.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2146","text":"الإنسان قد يلجأ أحياناً إلى تبرير أفعاله غير الأخلاقية أو الباطلة عبر استخدام مبررات زائفة أو أيديولوجيات وهمية، ليقنع بها الآخرين وحتى نفسه. ويستغل بذلك ضعف عقول بعض الناس أو سذاجتهم، متوهماً أنه على طريق الحق، بينما في الواقع يتبع أهواءه ورغباته الشخصية الباطلة، فهو يخدع نفسه من حيث لا يدري.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2147","text":"اتقوا من تُبغضه قلوبكم، وتنفر منه عيونكم، فإن القلوب على القلوب شواهد، والأرواح جنود مجندة، ما تعارف إئتلف وما تناكر منها اختلف، والقلب كتوم والعين نمامة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2148","text":"الصادق يقول الحقيقة ولو كانت مُرة، فيكسب ثقة الناس به، بينما الكاذب يُخفي الحقيقة لتحقيق مصلحة أو دفع مضرة فتسقط ثقة الناس به إلى الأبد، كما تسقط البعرة من اسْتِ البعير.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2149","text":"الحرية المطلقة قد تؤدي إلى الفوضى المطلقة، لأنها تفتقر إلى القيود التي تحافظ على النظام والعدالة، فالحرية هي مفهوم نسبي يتأثر بالثقافة والقوانين والمجتمع، ولهذا فإن ما يُعتبر حرية في بلد ما قد يكون مُقيدًا أو مختلفًا في بلد آخر، فالتوازن بين الحرية والنظام هو ما يضمن الاستقرار والعدالة في المجتمعات المثقفة الراقية الواعية.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2150","text":"الفرق بين المقالة القصيرة والمقالة الطويلة، كالفرق بين الدينار القديم والدينار الجديد، فالدينار القديم أكثر تداولا من الدينار الجديد. الوتساب ( والتويتر ) يحب المقالات القصيرة أكثر من المقالات الطويلة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2151","text":"أفضل الانتصارات التي يحققها الإنسان هي تلك التي تُنجز بلا إراقة دماء، ولا هدم بناء، ولا إفساد غذاء، ولا مصادرة دواء، ولا ظلم للفقراء، أو إقصاء المستضعفين، أو تسلط بالاستعلاء. إنما هو انتصار المرء على نفسه الأمارة بالسوء، حيث يهزم أهواءها، ويسمو بروحه فوق شهواتها، ليحقق بذلك أعظم انتصار يمكن أن يعرفه الإنسان.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2152","text":"مفهوم حرية التعبير عند الدول القوية مثل البعير، إن كان في مصلحتهم أثاروه وطبقوه، وإن كان ضد مصلحتهم عقلوه وعطلوه، القضية مصلحية وليست مبدأية، فهي تُستغل بطريقة انتقائية، بناء على المصلحة، لا المبادئ المعتبرة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2153","text":"الطعن في تعاليم السنة والقرآن، أمارة على النفاق والكفران، إلا أن يتوب ويرجع إلى حضيرة الإيمان.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2154","text":"اجعل لنفسك ووالديك سهما في كل مشروع بار، وفي كل وقف بالحسنات دار، فإنها تجارة مع الله الغفار، تُنور قلوبكم وقبوركم وتُنجيكم من أهوال يوم القيامة ومن عذاب النار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2155","text":"إن نسيت ما فقدت، ضعف إهتمامك بما أخذت.","kind":"hikma","topic":"الصبر والشدائد","note":"تعقيب على قول: إن عوض الله إذا حل أنساك ما فقدت","source":"شذرات (ملف وورد)"},{"id":"m2156","text":"تخيروا لنطفكم، فإن العرق دساس، يسري في الظلام لا يضل ولا ينام، وكما قيل: \"ثلثا الولد على خاله\"، فالطباع والصفات تنتقل من الأصول إلى الفروع. حتى في الحيوانات، نجد البغل يشبه خاله الحصان، والنغل يشبه خاله الحمار. إنها سنة الحياة، أن يحمل العرق بصماته عبر الأجيال، ومن وراء البحار والجبال.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2157","text":"حق الوالدين يلي حق الله ورسوله مباشرة، إذ أمر الله ببرهما بعد توحيده. هما بابان إلى الجنة، فمن برهما نال رضا الله. ومع ذلك، لا طاعة لهما في الشرك أو المعصية، مما يعزز أهمية برهما في كل ما سوى ذلك.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2158","text":"حلاوة التعريدة أن تُشبه الغفوة، لا ليلة شتوية ( باردة وطويلة)","kind":"hikma","topic":"الكلام والصمت","note":"في معنى","source":"شذرات (ملف وورد)"},{"id":"m2159","text":"إن الناس ينقسمون في إدراكهم إلى ثلاث فئات: الفئة الأولى: يدركون بحواسهم فقط. الفئة الثانية: يدركون بحواسهم وعقولهم. الفئة الثالثة: يدركون بحواسهم وعقولهم وقلوبهم معًا، وهم الملهمون الذين يمثلون منارة للفكر والإبداع، ووضوح الحجة والإقناع.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2160","text":"المرأة الصالحة هي صانعة المستقبل، ومربية الأجيال، فهي وعاء للطفولة، وحواء لها تحويها، هي المربية، والمؤدبة، والمعلمة، والمهذبة، من خلالها يُصنع الجيل الذي يجمع بين الآداب والأخلاق المجيدة، والعادات الحميدة، والسلوكيات النافعة المفيدة، وهو لا يزال عودا لدنا، وغصنا لينا، فينشأ مستقيما صالحا مهذبا، وعلى مثل هذا تنشأ الحضارات، وترقى سلم الدرجات.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2161","text":"لا تُخاطب الصغار بخطاب الكبار، ولا تُخاطب العامة بخطاب الخاصة، ولا تُخاطب الدهماء بخطاب العلماء، ولا تُخاطب النساء بخطاب الرجال، ولا تُخاطب الحزين بخطاب السعيد.","kind":"hikma","topic":"الكلام والصمت","note":"بعنوان: أهمية مراعاة الحالة النفسية والاجتماعية والآنية للمخاطب؛ جُمعت الجمل من","source":"شذرات (ملف وورد)"},{"id":"m2162","text":"قبل أن تنبس ببنت شفة، يجب عليك أن تراعي حال المخاطب، حتى لا تغمَّه أو تجرحه.","kind":"hikma","topic":"الكلام والصمت","note":"خلاصة","source":"شذرات (ملف وورد)"},{"id":"m2163","text":"كل كلمة تهب على مسامعك، اجعلها فوق ركام الإشاعات حتى يأتيك اليقين، فحينئذ تمسَّك به بنواجذك. فنحن في زمن كَثُرَت فيه الأراجيف والإشاعات، وقلّت فيه الحقائق.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2164","text":"استقوا من المنابع الصافية، وإياكم والمنابع الكدرة. فعلم الحلال والحرام والأحكام يُؤخذ عن العلماء الأتقياء المشهود لهم بالصلاح والورع. أما الوعظ والإرشاد والترغيب في فضائل الأعمال، والترهيب من رذائلها، وعلم التاريخ والسِّير فيؤخذ عن المشايخ وطلبة العلم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2165","text":"المسلم حامل لراية العدل، ذو مبدأ سامٍ، يحب الخير للغير.","kind":"hikma","topic":"الأخلاق والآداب","note":"من","source":"شذرات (ملف وورد)"},{"id":"m2166","text":"المواطن أمين بفطرته ونشأته، لكن الفرصة وأمن العقاب قد يدفعانه للاختلاس. إذاً، الخلل في النظام الوقائي. يجب حماية الإنسان من ضعفه أمام المغريات بسنّ القوانين ووضع المحترزات التي تمنع من فرص الاختلاس. كذلك، الحزم في العقاب ضروري؛ فمعاقبة مختلس واحد تردع مائة. لو عُوقب الأول لما تجرأ الثاني.","kind":"hikma","topic":"السياسة والقيادة","note":"خاتمتها صيغة أخرى لل","source":"شذرات (ملف وورد)"},{"id":"m2167","text":"استعيذوا بالله من جار المُقامة، أما جار البادية فإما أن ترحل عنه، أو يرحل عنك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2168","text":"رقية الجار الطالح: اللهم أسعده وأبعده. رقية الجار الصالح: اللهم أسعده ولا تُبعده.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2169","text":"معاقبة الأول تردع الثاني.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2170","text":"الحزم في معاقبة المجرم الأول حصن من انتشار الجريمة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2171","text":"لو أطفأت عود الثقاب، لما اشتعل مخزن الأخشاب.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2172","text":"رَبِّ أكبر أبنائك تستعن به في تربية الباقين.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2173","text":"ابدأ بتربية نفسك لتُحسن تربية أهل بيتك.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2174","text":"إصلاح نفسك هو مفتاح إصلاح من حولك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2175","text":"عند تشكيل الوزراء، ليكن أول مهامهم تنظيف وزاراتهم وتطهيرها وتنشيطها وإصلاحها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2176","text":"الضعيف الذي لا ينوي الرد يكتفي بقول: \"نُحمل الفاعل المسؤولية، وسنرد في الوقت والمكان المناسبين.\" هذا كلام لتبرير العجز وحفظ ماء الوجه. أما القوي، فيكتم ويستعد، ثم يباغت خصمه بضربة حاسمة ومفاجئة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2177","text":"الأم معراج الدعوات ومهبط الرحمات فتشعر بالفخر والحزن، تختلط مشاعرها عند فراقها لابنها لطلب العلم خارج الوطن، فهي تفخر بسعي ابنها للتعلم وتحقيق مستقبل مشرق، لكنها تحزن وتقلق بسبب الابتعاد والحنين له. فمشاعرها تجمع بين الحب العميق، وأحزان القلب الرقيق، متمنية له النجاح والسلامة، ولا يزال قلبها فارغا، حتى تلمُّه في المطار، وقلبها يخفق، وعينا تتدفق، ولسانها يلهج بالحمد والشكر على سلامته ونجاحه.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2178","text":"من سعادة المرء أن يصلي الفجر في المسجد القريب المتاح، ثم يحرك قدميه في أحضان الطبيعة يستنشق عبير الصباح، ويحرك شفتيه بالتسببح والدعا بالتوفيق والفلاح.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2179","text":"حياة الوتساب ونشاطه بالمناقشات العلمية والأدبية، والتداولات في القضايا الاجتماعية، واختلاف وجهات النظر حول المواقف السياسية، فاختلاف الآراء ظاهرة طبيعية وصحية، بشرط أن يكون مستوى النقاش راقٍ، وخالٍ من التعصب والتطرف، والتجربح والتوبيخ، بل يكون تحت قبة الاحترام والوئام، بروح رياضية، وأخلاق حريرية.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2180","text":"المشروعات الكبيرة تحتاج ألى قوة كبيرة، والقوة الكبيرة تتحقق من المجموعات البشرية الكثيرة، التي تعمل بنظام واحد، يكمل بعضه بعضا.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2181","text":"تقدمُ المجموعةِ مرهون برئيسها، إذا كان يمتلك عقلا إيجابيا، ونظرة مستقبلية، ويتحاشا السلبيات.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2182","text":"الصبر والمثابرة من الأركان المهمة لإنجاح المشروعات الصعبة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2183","text":"العلم نور والجهل ظلمات، فأفضل سلاح لمحاربة الجهل والسلبيات هو العلم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2184","text":"الاعتدال والتوازن هما اللذان يعصمان العقل من الانحراف والميل.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2185","text":"الأم معراج الدعوات، ومهبط الرحمات، وموطن المسرات، وحبل المودات، ومنبع الابتسامات، ومصدر الاهتمامات، ومصنع الشخصيات، وموئل التجمعات، وموتها يُحزن البنين والبنات، ويفرق التجمعات","kind":"hikma","topic":"التربية والأسرة","note":"يتقاطع مطلعها مع","source":"شذرات (ملف وورد)"},{"id":"m2186","text":"من الحكمة أن نتعاون مع العرب والمسلمين ونقوي العلاقات والروابط بيننا وبينهم، وأن نبتعد عما يثيرهم ويضعف العلاقات والروابط التي بيننا وبينهم، وتعاونوا على البر والتقوى والخير والمعروف.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2187","text":"الصانع أعلم بصنعته، والزارع أعلم بزرعه، وهَلُمَّ جراً، والخالق أعلم بخلقه، فأفضل رياضة المشي إلى المساجد، وحركات الصلاة، وأفضل نظام غدائي للصحة والتخسيس الصيام وتقليل الطعام.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2188","text":"علموا أولادكم وأدبوهم وأحسنوا تربيتهم وأخلاقهم وألفاظهم: بالاستهواء السلوكي، والقدوة العملية، والعشرة الصالحة، فهم صفحة بيضاء، يقتبسون منكم: بالمحاكاة والتقليد والاقتباس والاقتداء، فكونوا قدوة صالحة لأولادكم، فتربية المعايشة والمصاحبة أقوى وأيسر من تربية التعليم والتلقين والمراقبة والمتابعة، والتربية الثانية متممة ومكملة عند الحاجة، والبيت هو أول مدرسة، وأقوى مدرسة، وأقدم مدرسة، وأهم مدرسة.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2189","text":"الأقوال التي لا رأس لها ولا ذنب، ولا مفاهيم جيدة ولا عبارات بليغة عجب، الخوض فيها مضيعة وتعب، وتركها مكسب وذهب، وذكر الله خير مكتسب، له ثواب عظيم مُرتقب.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2190","text":"قيمة الوعاء من قيمة ما فيه، وقيمة الوقت من قيمة ما تعمل فيه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2191","text":"المال الذي لا يُستثمر مصيره للزوال.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2192","text":"العمل المتقن هو السبيل لإنجاز المشاريع الناجحة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2193","text":"الخطأ في التخطيط، تخطيط للخطأ.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2194","text":"اكتب ما يستحق القراءة والاطلاع، واعمل ما يستحق المدح والثناء.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2195","text":"العاقل ينتفع بالتجارب والتصيحة، والأحمق يكرر الأخطاء والفضيحة","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2196","text":"التفكير الكثير يُفوِّت الفرص، ويُؤخر تنجيز الأعمال، ويزيد في نفقات إنجازاتها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2197","text":"التقدم في صناعة الأسلحة مصدر مهم من مصادر القوة المادية.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2198","text":"أفضل نسبة أرباح تحصل عليها من الصدقات وأعمال البر، الحسنة بعشرة أمثالها أو أضعاف مضاعفة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2199","text":"اغتنام الفرص أسرع طريق للنجاح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2200","text":"بالقناعة يبدو الفقير غنيا، وبالطمع يبدو الغني فقيرا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2201","text":"الرغبة في التعليم بوابة العلم، وعدم الرغبة في التعليم بوابة الجهل.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2202","text":"من أفضل ما يقدمه الوالدان لأولادهما: التشجيع والرغبة في طلب العلم، وتيسير سبله، وما ضاع من مالك ما أنفقته على تعليم عيالك.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2203","text":"في القديم كان بعض العوئل الكبيرة عندهم حوش البقر، الآن مواشينا في جمعياتنا، وبقرتنا في ثلاجتنا","kind":"hikma","topic":"الحياة والزمن","note":"حُذف الدعاء الذي في آخر","source":"شذرات (ملف وورد)"},{"id":"m2204","text":"نعيم الدنيا وبُؤسها زائل، فلا تغتر ولا تغتم.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2205","text":"الغريب للغريب نسيب.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2206","text":"الهرم عدو الطبيعة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2207","text":"تعلم بكل عقلك، وكل ببعض بطنك.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2208","text":"لقد جف القلم بالأقدار، فعليك بالصبر والاستغفار.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2209","text":"حسبك شرفا أن تُعَدَّ عيوبك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2210","text":"العادات قاهرات، وليس من عادات العادات قهر العادات.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2211","text":"تُكتسب العادات بالتدرج والاستمرار، والتخلص منها يتم بالتدرج والاستمرار.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2212","text":"المعروف عرفا كالمشروط شرطا.","kind":"mathal","topic":"العقل والحكمة","note":"قاعدة فقهية مشهورة","source":"شذرات (ملف وورد)"},{"id":"m2213","text":"القوانين أعراف مكتوبة، والأعراف قواني غير مكتوبة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2214","text":"لكل داء دواء، إلا أربعة أدواء في الناس: الهرم والبخل والحماقة والوسواس.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2215","text":"كل الرؤوس فيها عقل وعينان، لكن رؤوس العباقرة فيها عقل كبير، ينظر بتدبر وتفكير، وينطق بحكمة وتقدير، وعينان يتصفان بنظر ثاقب، يستوعب الحاضر ويستشف الغائب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2216","text":"الوتساب واصف جيد لكنه طبيب سيئ، لا تأخذوا منه الوصفات الصحية والطبية والعلاجية، حتى تتوثقوا من علماء الاختصاص الموسمين بالخبرة والتجربة والدراية.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2217","text":"كثرة الأعمال الطيبة تُكسبك سمعة طيبة، وعمل واحد غير طيب في العلن يُكسبك سمعة غير طيبة، فاستر على نفسك، فهي أولى بالستر من غيرك، ومن ستر مسلما ستره الله في الدنيا والآخرة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2218","text":"الناس شركاء في المرافق العامة، فلا يجوز الإستيلاء عليها، ومنع الناس من حقهم فيها.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2219","text":"الرجل الكبير الهرم مثل البيت القديم: أنوار طافية، أبواب تصرصر، طابوقات ساقطة، حوائط مائلة، شبابيك مكسورة، مواسير تسرب، أثاث قديم، ستائر رثة، بيت هدام","kind":"hikma","topic":"الحياة والزمن","note":"حُذف الدعاء الذي في آخر","source":"شذرات (ملف وورد)"},{"id":"m2220","text":"أظن أن نشر الانتقادات الفردية المتبادلة بين الشعوب العربية في الوسائل الإعلامية ظاهرة غير صحية، وثمراتها سلبية، لأنها تصنع الكراهية والوحشة في القلوب بين الشعوب، ونحن في حاجة شديدة للؤلفة والمودة، بين الشعوب العربية والإسلامية، لأن التآلف قوة والتنافر ضعف.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2221","text":"احذروا هذه الكلمات: الله لا يوفقك، الله ياخذك، الله يلعنك، الله يقطعك، وما شاكلها من الدعاء. واستبدلوها بكلمات: الله يوفقك، الله يهديك، الله يصلحك، الله يبارك فيك، وما شاكلها.","kind":"hikma","topic":"الكلام والصمت","note":"استدل بعده بحديث: لا تدعوا على أنفسكم","source":"شذرات (ملف وورد)"},{"id":"m2222","text":"لا شك ولا ريب أن الهداية والتوفيق للصراط المستقيم، تفضل من الله العظيم، ولكن على العبد أن يسأل الله الهداية، ويستعيذ به من الغواية، ويلازم الصالحين، ويهجر الطالحين، ويستعين على ذلك بكثرة الذكر والاستغفار، والله يقول: فاستهدوني أهدكم، فعلى العبد أن يسعى ويطلب الهداية.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2223","text":"نحن نُثْني على اليابانيين لأنهم صنعوا السيارات والمركبات الكبيرة العملاقة، مع أنهم لم يصنعوها بأيديهم، بل صنعوها بواسطة الآلات الألكترونية، ونحن لا نُثني على الآلات الألكترونية، والسبب لأنهم هم الذين صنعوا الآلات الألكترونية، وبالقياس نفسه يجب أن نحمد الله سبحانه، لأنه هو الذي خلق اليابانيين، ووهبهم العقول والحواس والجوارح، فالله أحق بالحمد، وأولى بالثناء والمجد، فكل حمد في الوجود أحق به خالق الوجود، المتصف بكمال الجود.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2224","text":"إذا شرع الناس يُعظمون الصناعات والاختراعات، ويعظمون من صنعها، فاشرع بتعظيم الله جَلَّ في علاه. وقل: لخلق الذبابة والنملة وما لهما من المهارات والقدرات والكيفيات، لأعظم من صناعة الطيارات والمركبات وسائر الصناعات. ولولا أن الله وهب الإنسان العقل والحواس والجوارح، لما استطاع أن يصنع إبرة أو عود ثقاب. فالفضل العظيم لله العظيم، فالله أحق بالتعظيم، فهو عظيم بذاته وصفاته وأفعاله.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2225","text":"من أعظم نِعَمِ الله على عبده بعد نعمة الهداية، نعمة الخلق والحياة ونعمة الصحة، ونعمة الجوارح والحواس، فلا يجوز شرعا ولا عقلا ولا فطرة، التفريط بها، والتهور في تعريضها للفناء والخراب والدمار، عن طريق مزاولة اللعب والأنشطة التي فيها خطورة كارثية عظيمة عليها.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2226","text":"حنانيك حنانيك، رويدا رويدا، كيف تريد من زوجتك وولدك أن ينقادا إليك في كل ما تريد؟ً وأنت لا تنقاد إلى ربك سبحانه في كل ما يريد منك! ونفسك التي بين جنبيك لا تنقاد إليك في كل ما تريد! فتحلى بالصبر والتيسير، والرفق واللين، فأهلك أولى الناس بجودك وكرم أخلاقك.","kind":"hikma","topic":"التربية والأسرة","note":"في معنى","source":"شذرات (ملف وورد)"},{"id":"m2227","text":"إذا عُرف السبب بطل العجب، وإذا عُرفت الحيلة بطلت الوسيلة، عليكم الحذر والتثبت والبصر.","kind":"hikma","topic":"العقل والحكمة","note":"بعنوان: الذكاء الاصطناعي والخداع والتزوير؛ صدره مثل سائر","source":"شذرات (ملف وورد)"},{"id":"m2228","text":"كن مع جلسائك مثل مُكعب السكر في الشاي، يُزيل عنه المرارة، ويمنحه الحلاوة ثم يختفي، فاجعل مجلسك حلوا بالعلم والحكمة والموعظة، والنوادر والأمثال والشذرات وقراضات الذهب، من غير أن تُظهر نفسك وتتميز عليهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2229","text":"عندما نام التكييف في السطح، أصبحنا داخل البيوت ننام ونمبطح، فلا نراقب النجوم وقد كانت النحوم قناديل بيتنا، ولا نسمع نداءات الأذان وصياح الديوك وهي تصطبح.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2230","text":"الفرق بين الطالب النشيط والطالب الكسلان، الطالب النشيط مستعد للامتحان، والطالب الكسلان لا يراجع إلا ليلة الامتحان. فالوقت كالوعاء، فالأول يعرف قيمة الوقت فيملؤه بما ينفعه، والثاني لا يعرف قيمة الوقت فيملؤه بالترهات والسخافات.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2231","text":"إن الله جلت حكمتُه وعظمت قدرتُه وعمت رحمتُه، خلق الملائكة لا يعصون، وخلق الشياطين لا يطيعون، وخلق الإنس يطيعون ويعصون، فيستغفرون فيغفر الله لهم، فرحمتُه غلبت غضبَه، وعفوُه غلب عقابَه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2232","text":"خير الهوايات ما نفعك في الحياة وبعد الممات: هواية الرياضات البدنية والعقلية، هواية السفر مع اللجان الخيرية، التي تعين المنكوبين، وذوي الأمراض العصية، والاحتياجات الضرورية، وهواية نشر الدعوة الإسلامية في البلاد الأجنبية، وجميع الهوايات، التي لها ثمرات في الحياة، وبعد الممات.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2233","text":"الجود بما تيسر من الموجود، ولا تبالغ في المجهود، فليس من المعهود، لدى أهل الكرم والجود، المبالغة بالمجهود في الجود، فأدوم الجود أيسره، وأقطعه أشنعه وأفظعه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2234","text":"من قرأت كتابه أو تتبعت أقواله وآراءه؛ فقد رطلت عقله، وسبرت غوره، وعرفت طوره، وتنبأت بقولِه قبل ما يُبدي قولَه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2235","text":"إن الله يعامل عباده بالفضل لا بالعدل، ولو عاملهم بالعدل لهلكوا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2236","text":"أحسنوا الظن بالله الغفور الرحيم، فالتوبة تجب ما قبلها، واجتناب الكبائر يكفر الصغائر، والحسنات يُذهبن السيئات، والوضوء والصلاة تكفر السيئات، وفضل الله أعظم، ورحمته أقرب وأوسع.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2237","text":"من تكلم في غير تخصصه أتى بالعجائب والغرائب، فالفقيه لا يُفتي في الطب، والطبيب لا يُفتي في الفقه، والأفضل أن يتباحثا ويتشاورا، وكل واحد منهما يُفتي في تخصصه، فهذا أسلم وأصوب.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2238","text":"ترك الغيبة تجارة عجيبة، تحفظ حسناتك، وتضاعفها ممن يغتابك، والاشتغال بالغيبة خسارة، لأنك تمنح حسناتك لغيرك أحوج من تكون إليها لنفسك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2239","text":"السلوكيات المهذبة والأخلاق المشذبًة والتصرفات المؤدبة، يقتبسها الصغار بالاستهواء السلوكي والتوجيه النصحي، المباشر وغير المباشر من الكبار، في محيط الأسرة، فتربية الصغار منوطة بتربية الكبار، فأدبوا صغاركم بتأديب أنفسكم، فتُسقطون عن كاهلكم شطر معاناة التربية.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2240","text":"اتقوا الله في، المرأة واليتيم، والضعيف والصغير، والغريب والفقير، والخادم والأسير، والمريض والغفير، والمعاق والكبير، والسائق والأجير، والحيوان والكسير، وارحموا من في الأرض يرحمكم من في السماء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2241","text":"دين الله يسر، إذا أتيت بالفرائض واجتنبت النواهي، فأنت حر فيما سوى ذلك من المباحات والنوافل والسنن، وكذلك أوقات الصلوات موسعة، وكذلك قضاء رمضان موسع، واجتناب الكبائر يُكفر الصغائر، وكذلك الوضوء والصلاة يكفران الصغائر، وفوق هذا وذاك رحمة الله الواسعة، ومغفرته العظيمة.","kind":"hikma","topic":"الإيمان والعبادة","note":"صدّرها بحديث: اتق المحارم تكن أعبد الناس","source":"شذرات (ملف وورد)"},{"id":"m2242","text":"المال إن كسبته بالمباحات، وأنفقته في الطاعات، فهو يُحقق لك السعادة المادية والمعنوية في الحياة، وبعد الممات، والمال عديل الروح، وشقيق النفس، وصنو الحياة، والمال دعوة مستجابة، به تُوصل الأرحام، ويُنعش الفقير والمسكين والأيتام، ويُكسى العاري ويُطعم الجَوعان، ومن قُتل دون ماله فهو شهيد.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2243","text":"العقل المفتوح لا يبادر بالرفض أو القبول، حتى تتبين له الحقائق بوضوح.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2244","text":"التعلم من الأخطاء هو باب من أبواب العلم اليقيني.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2245","text":"التعاون هو السبيل لتحقيق الأهداف الكبيرة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2246","text":"الأنسان يفكر بطريقة جمعية تقوم على الحوار والنقاش بينه وبين نفسه، أو بينه وبين غيره، ثم الاستنتاج والترجيح والإقدام.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2247","text":"الإنسان يستعين بالله أولا، ثم يستعين بالناس، ويشكر الله أولا ثم يشكر الناس، هذا هو الصواب، أن تجمع بين التوكل على الله أولا، ثم تأخذ بالأسباب، فتجمع بين عمل القلب من ناحية، وعمل العقل والجوارح من ناحية ثانية.","kind":"hikma","topic":"الإيمان والعبادة","note":"صدّرها بآية وحديث","source":"شذرات (ملف وورد)"},{"id":"m2248","text":"الفقر ليس عيبا، لكن الفقر نتيجة الإهمال والكسل هو العيب.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2249","text":"الوقت إذا استثمرته في شيء نافع فهو يساوي الأرباح، وإذا لم تستثمره فهو خسارة لهذه الأرباح.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2250","text":"الوقت القصير الذي تُنجز فيه عملا نافعا خير من الوقت الطويل الذي لا تنجز فيه عملا نافعا.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2251","text":"الابتكارات النافعة تدفع عجلة التقدم نحو الأمام","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2252","text":"النجاح والتفوق لهما مردودان إيجابيان: مادي ونفسي.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2253","text":"الثقة بالقدرة والمهارة تدفع الإنسان إلى العمل النافع.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2254","text":"احذروا الغضب، فعاقبة الغضب الندم والعطب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2255","text":"النشاط يجعل الصعب سهلا، والكسل يجعل السهل صعبا.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2256","text":"الكسل بوابة الفقر والنشاط بوابة الغنى.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2257","text":"الاستثمار في العلم يفتح أبواب الرزق.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2258","text":"من يتصف بالصبر يستطيع أن يحقق أهدافه.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2259","text":"إذا أراد الله أن يهدي عبده ألهمه طلب الهداية من الله تعالى. إذا أراد الله أن يغفر لعبده ألهمه الاستغفار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2260","text":"ما تريده من الله افعله مع عباده، ارحم تُرحم، اغفر يُغفر لك، تجاوز يتجاوز الله عنك، وهلمَّ جرا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2261","text":"لولا السلبيات ما عرفنا قيمة الإيجابيات. لولا المرض ما عرفنا قيمة الصحة. لولا الجهل ما عرفنا قيمة العلم. لولا الخوف ما عرفنا قيمة الأمن. لولا الموت ما عرفنا قيمة الحياة. وبضدها تتميز الأشياء.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2262","text":"رمضان يُطهر الإنسان من الذنوب والأدران.","kind":"hikma","topic":"الإيمان والعبادة","note":"بعنوان: جائزة رمضان المبارك، بعد حديث: من صام رمضان إيمانا واحتسابا","source":"شذرات (ملف وورد)"},{"id":"m2263","text":"قاعدة: الأذكار كثيرة وشاملة، فحسب المؤمن أن يداوم على بعضها، أو عليها كلها بالتناوب، والتوزيع على الأيام.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2264","text":"الحزم في تنفيذ المشاريع يقضى على السلبيات وينجز المشاريع بالجودة والتسريع.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2265","text":"لأن تنام طاويا من غير عشاء، أعز لك من أن تمد يديك للأغنياء.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2266","text":"النوم المبكر والاستيقاظ المبكر عنوان الصحة والنشاط.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2267","text":"بادر بإصلاح العيوب الصغيرة، فبعض العيوب الصغيرة لها نتائج خطيرة، فالثقب الصغير قد يُغرق المركب الكبير.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2268","text":"الاجتهاد والعرق يطردان الهموم والأرق.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2269","text":"كثير الأدب لا يكون كثير الغضب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2270","text":"كنز الحكمة الاستفادة من تجارب من سبقك.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2271","text":"الأفعال تُصدِّق الأقوال، والأقوال لا تصدِّق الأفعال.","kind":"hikma","topic":"الأخلاق والآداب","note":"في معنى","source":"شذرات (ملف وورد)"},{"id":"m2272","text":"كثرة الانتقادات والاتهامات والشكاوَى بضاغة العاجزين.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2273","text":"العقل المفتوح ينتفع من كل المعارف النافعة، والعقل المغلق لا ينتفع من كل المعارف النافعة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2274","text":"العاقل يتعلم من أخطائه، والغبي يُكرر أخطاءه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2275","text":"التعارف مفتاح التعاون، والتعاون هو بوابة تحقيق الأهداف الكبيرة","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2276","text":"الجيل الذي قبلنا كان رمضان ثلاثين يوما، صيام قيام قرآن، والجيل الذي بعدنا صار رمضان ثلاثين حلقة، مسلسلات حلقات، لا حول ولا قوة إلا بالله","kind":"hikma","topic":"الحياة والزمن","note":"حُذف الدعاء الذي في آخره","source":"شذرات (ملف وورد)"},{"id":"m2277","text":"عليكم بالسحور فإن بالسحور بركة، تعينكم على النشاط والحركة والفوز بالتنافسات الإيجابية والأعمال المشتركة","kind":"hikma","topic":"الصحة والنفس","note":"صدره من حديث نبوي","source":"شذرات (ملف وورد)"},{"id":"m2278","text":"شهادة الأفعال أقوى من شهادة الأقوال، لأن شهادة الأفعال يقينية، وشهادة الأقوال ظنية، فلا تكن من الذين يقولون ما لا يفعلون، فلا تثق الناس بأقوالك، ولو كانت حقيقية.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2279","text":"لصاحب الحق مقال يلج الآذان ويستقر في الجَنان","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2280","text":"ما هو الهُدهُد وما مرقته، وقف أمام النبي الملك سليمان عليه السلام أمام الملأ، وخاطبه بيقين وثبات: ( فقال أحطت بما لم تحط به... ) فلم يُنْكَِرْ عليه، وفي هذا تواضع نبي الله سليمان عليه السلام، ودرس بليغ وعبرة عظيمة للسلاطين والملوك والأمراء","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2281","text":"إن الله خلق الناس ليرحمهم لا ليعذبهم، وليدخلهم الجنة لا ليقذفهم في النار، وأرسل لهم رسلا يرشدونهم لطريق الجنة، ويحذرونهم من طريق النار، فمن أطاعهم دخل الجنة برحمة الله، ومن عصاهم دخل النار بسوء اختياره وطاعته للشيطان.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2282","text":"الملكات والصفات الذاتية تُوَرَّث لا مظاهرها، فقد يكون الأب شجاعا لكنه مجرم، ويخرج من صلبه ابن شجاع لكنه قوي في نصرة الحق والمظلوم، فوَرِث من أبيه صفة الشجاعة، ولم يرث منه مظاهرها، فالأنبياء عليهم السلام ورثوا من آبائهم وأجدادهم الملكات والصفات الإيجابية، ولم يرثوا منهم مظاهرها السلبية، لعناية الله بهم القدرية.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2283","text":"أقبح هزيلين الفرس والمرأة.","kind":"mathal","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m2284","text":"الرجل في بيته صبي يمزح ويمرح، وفي الجَدِّ يصول ويجول.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2285","text":"التاجر الجبان محروم والجسور مرزوق.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2286","text":"ما تريده من الله افعله مع أخيك المسلم، فالجزاء من جنس العمل","kind":"hikma","topic":"الإيمان والعبادة","note":"في معنى","source":"شذرات (ملف وورد)"},{"id":"m2287","text":"اختلاف وجهات النظر ظاهرة طبيعية، وفي الوقت نفسه ظاهرة صحية، إذا كانت في إطار أدب الحوار، والبحث عن الحقيقة، من غير تشنج وتعصب. يا حبذا لو كان هذا مبدأ القروبات.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2288","text":"قائد اسد ويتبعه نعاج ينتصر بإذن الله، قائد نعجة ويتبعه اسود يُهزم بإذن الله. الذي لا يُهزم بإذن الله أسد يتبعه أُسود.","kind":"hikma","topic":"السياسة والقيادة","note":"حُذف الدعاء من آخر؛ والجملة الأخيرة تعقيب منه","source":"شذرات (ملف وورد)"},{"id":"m2289","text":"إن صادفت شابا أحمق، أو رجلا سفيها، أو مراهقا طائشا، وبيده شفرة حادة، أو سكينة طريرة، فلا تجادله، ولا تضيق عليه في الحوار، فخذ حذرك منه، وهاوده ولاينه وياسره، حتى تسلم من شره وسوء تصرفه، وبذاءة لسانه، فالكلب العقور إذا حُوصر عقر.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2290","text":"الأصل في الأخلاق أنها حزم ومجموعات لا أفراد وأفذاذ، فإذا وجدت في رجل خصلة صالحة فتوقع أخواتها، والعكس صحيح، فإن كان صادقا فهو مخلص وأمين وثقة، وهلم جَرًّا، وإن كان كاذبا فهو مداهن ومراوغ وغير أمين ولا ثقة، وهلمَّ جرًّا، فنظام الأخلاق جمعي لا فردي.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2291","text":"التوقعات أبلغ من الواقع، لأن التوقعات تخيلات، والواقع حقائق محسوسات، والتوقعات غير محدودات، والواقع محدود بالحواس.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2292","text":"من ظلمك أو أساء إليك كمن كتب لك حوالة لتأخذ من رصيد حسناته، يوم القيامة بقدر مظلمته، أحوج ما تكون إليها، إن أنت كظمت غيظك، ولم تقتص منه في الدنيا، وعفوت عنه فأجرك على الله الكريم، فطوبى للكاظمين الغيظ والعافين عن الناس، والله يحب المحسنين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2293","text":"إذا اختلف الزوجان أو الأَخوان أو الصديقان، فلا تقدح بينهما الكبريت، فهذا من عمل العفاريت، ولكن كن كرجل الإطفاء، يهدئ النفوس ويزيل الشحناء فهذا من عمل الملائكة والأتقياء","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2294","text":"لا ينبغي للعبد الضعيف أن يُشهد ربه، أو يُعاهد ربه ونحو ذلك، لأنه أن يغدر بعهده أو عهد غيره أهون من أن يغدر بعهد الله تعالى.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2295","text":"لا تحزنوا على من فارقكم من الأصحاب، لقد رحل إلى رب الأرباب، من هو خير له من والديه وأولاده والأحباب، من يغفر السيئات للمؤمنين ويُضاعف لهم الثواب، غفور رحيم، عفو حليم، غني كريم، يضاعف الحسنات، ويتجاوز عن السيئات، ويرحم الأحياء والأموات، وهو رب العرش والأرض والسموات.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2296","text":"الحكيم مثل الطِّيب إن أثرته عبقت منه روائح طيبة أفنان وألوان، وذاع شذاه في الآفاق والأركان، وتكلم بالحكمة ونطق بفصيح البيان، ونبه العقول وشنف الآذان، وحرك الجَنان، بالمحبة والخوف من الرحمن.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2297","text":"من يمدح نفسه مثل البائع الذي يقول لك: هذا عسل طبيعي، لا تبادره بالتصديق، حتى تتأكد بالتحقيق، والتجربة والتدقيق، فلا تنخدع بالمظاهر، فربما كانت المظاهر خلاف السرائر، والله عالم بما تُكنه القلوب والضمائر.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2298","text":"كُفَّ شرك عن غيرك صدقة منك على نفسك.، إن لم تنفع فلا تضر.، إن لم تُسعد فلا تُحزن.، إن لم تمدح فلا تقدح.، إن لم تتصدق فلا تثبط غيرك عن الصدقة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2299","text":"الصاحب ساحب والمرافقة من الموافقة والتآلف والوئام من الابتسامة وإطعام الطعام","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2300","text":"التقدم المستدام يتطلب التطور المستمر. النجاح المستدام يتطلب الابتكار المواكب","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2301","text":"تحقيق النجاح ليس النهاية، بل هو بداية دافعة لمواصلة سلسلة النجاحات.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2302","text":"أغلب الناس يتعاطفون مع الأرملة والأيتام، ويتناسون الأُسر الفقيرة ولو كانوا من الأرحام، أيها الناس تفقدوا الفقراء من الأقارب والغرباء، ولو كان آباؤهم من الأحياء.","kind":"hikma","topic":"العلاقات والناس","note":"بعنوان: تنبيهات قويمة للقلوب الرحيمة؛ مستخلص من قصة","source":"شذرات (ملف وورد)"},{"id":"m2303","text":"أمران لا يتعلمهما الطفل، بل هما من الإلهام، ولولا ذلك لهلك فور خروجه من بطن أُمه. التنفس والرضاعة: الهواء والغذاء. والثالث: تَعَرُّفه على مصدر غذائه، وهذه في البهائم أًوضح، وفي علم الطب لو وضعت الأم وليدها على بطنها لزحف إلى صدرها.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2304","text":"لا يصيب الرامي غرة الهدف إلا بعد تكرار الخطأ، فالصواب ابن الخطأ، والتكرار باب من أبواب تعليم الصغار والكبار، ومن تردد في شيء آتاه الله حكمته، وكشف له أسراره وعلته، والتعليم توسع عمودي، والثقافة توسع أُفقي.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2305","text":"المؤمنون هم أوتاد الأرض، فإذا خليت الأرض منهم قامت القيامة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2306","text":"العلم زينة، والأدب حُلة جميلة، والحلم سيد الأخلاق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2307","text":"بكلام السفهاء أصبح الصمت فضيلة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2308","text":"من كان كلامُه لا يوافق فعلَه فإنما يجلب لنفسه الانتقاد الحاد.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2309","text":"انشروا الإسلام بأخلاقكم وأعمالكم قبل أن تنشروه بأقوالكم وأقلامكم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2310","text":"الجنة دار السرور والحبور، والدنيا دار الهموم والغموم، وما كان فيها من سرور فهو عارض زائل.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2311","text":"بادروا بالتصدق من أموالكم، فإن لكم فيها شريكان: الحوادث والوارث.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2312","text":"النظام الديمقراطي مبني على الكم لا الكيف، وعلى عامة الناس، ومن يسعون للمكاسب الخاصة، لا على أهل العلم والخبرة والحكمة والتجربة، ومن يسعون لتحقيق المصالح العامة. ونظام الشورى أصل إسلامي ( وَأَمْرُهُمْ شُورَى بَيْنَهُمْ ) ومبدأ عقلي، وهو مبني على طرح الآراء ودراستها، من قِبل أهل الاختصاص، ثم اختيار الأفضل منها لسياسة الدولة وشؤونها، وحاضرها ومستقبلها، ولا بد من تحقق القوة والآمانة والكفاءة.","kind":"hikma","topic":"السياسة والقيادة","note":"بعنوان: مقارنة لاختيار الأصلح لسياسة الدولة","source":"شذرات (ملف وورد)"},{"id":"m2313","text":"لا تكن رأسا، فالرأس كثير الأوجاع، إن أحسنت إليهم حسدوك، وإن أخطأت لن يعذروك، وإن عاملتهم باللين استضعفوك، وإن عاملتهم بالحزم كرهوك، وإن كثر مالك اتهموك، ثم يوم القيامة ستُسأل عنهم إن خاصموك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2314","text":"من أُعجب برأيه زَل، ومن تكبر ذَل، ومن هجر أقوال الفقهاء ضَل، ومن أكثر من شيء مَل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2315","text":"كل مَلِكٍ يُحب دوام ملكه، لكنه لو دام لمن قبلك ما وصل إليه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2316","text":"إن عصاك الناس فلا تحزن، فإنهم قد عصوا الله خالقهم سبحانه، وعصوا رسله عليهم السلام.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2317","text":"إذا حدثك ابنك الصغير بمسألة علمية بسيطة، أو فائدة أدبية مشهورة، فاستمع إليه باهتمام، ولو كنت تعرفها، حتى تُشعره بحلاوة نشر العلم، فيدعوه ذلك إلى طلب العلم ونشره.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2318","text":"إن الله تعالى قَصَّ علينا قصة يوسف عليه السلام عبرة وعظة، لنكون لآبائنا وأُخوتنا كيوسف لأبيه وإخوته، ولا نكون لآبائنا وأُخوتنا كإخوة يوسف لأبيهم وأخيهم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2319","text":"المدح والقدح يشوبهما الكذب، المادح يذكر المناقب ويُعظمها ويُخفي المثالب ويدفنها، والقادح يُبرز المثالب ويعظمها ويُخفي المناقب ويدفنها، فكن يقظا حصيفا متنبها منهما، ولا تنخدع ببلاغة اسلوبهما، وحلاوة كلامهما، ورونق بيانهما.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2320","text":"الوتساب صندوق لا يسلم من الكذب والارتياب، فيه الزهرة والبعرة، والحقير والأمير، والحق والباطل، والصالح والعاطل، فلا بد من التأني والتحقيق، قبل النشر والتصديق.","kind":"hikma","topic":"الكلام والصمت","note":"في معنى","source":"شذرات (ملف وورد)"},{"id":"m2321","text":"كن كالنهر، ماؤه يجري بين الروابي والوديان، يسقي النباتات ويملأ الغدران، ويغتسل فيه الناس بأمان، ويصطادون منه أسماك أشكال وألوان، ويتجدد في كل وقت وأوان، لأنه يجري ولا يقف في مكان، فكن كالنهر تنشر الخير والمعروف في كل مكان وزمان.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2322","text":"المطر يُنظف الأجواء من الغبار وذرات الدخان، ويستبشر به الرجال والولدان، ويشعر الناس بالسعادة والأمان، ويسقي النباتات والأشجار في الروابي والوديان، ويملأ الغدران، ويغسل الشوارع وسطوح العمارت والبنيان، فالمطر نعمة عظيمة من الله سبحانه، يُحي به الأراضي، ويُنعش به المواشي، ويُنبت به الأشجار، ويُجري به الأنهار، فإذا بكت السماء تبسمت الأرض، وأرجى ما تكون السماء إذا احتجبت.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2323","text":"نِعْمَ الإدام الجوع","kind":"mathal","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2324","text":"الفقراء يتلذذون بطعامهم أكثر من الأغنياء، لأن اللذة على قدر الحرمان، والاشتياق على قدر الفراق.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2325","text":"قارئ القرآن ملياردير حسنات في تجارة الآخرة، فإن فاتتك تجارة الدنيا فلا تفوتك تجارة الآخرة، فهي خير وأبقى.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2326","text":"المرأة في أصل الخلقة لم تخلق من التراب، وإنما خُلقت من الرجل، فهي خلقت من التراب في المرحلة الثانية، فلذلك بينهما فروق مآلاتها إيجابية لا سلبية، والرجل المتسلط يريد أن يجعل عقلها وطبيعتها مثل عقله وطبيعته، وهذا عسير يشبه المستحيل، فعليه أن يُقلل من اللوم والعتاب، والذم والقدح، والتأنيب والتثريب، والنصائح والدروس، وأن يقدر لها طبيعتها وسجيتها وفطرتها، ويتعامل معها باللين حتى لا يكسرها، وكسرها طلاقها، ويُدخل على أولاده سلبيات شطر اليتم.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m2327","text":"الوتساب حاطب ليل، فقد يكون بين الحطب عقارب وخنافس وثعابين. فلا تصدقوا الوتساب من أول وهلة، فالنظرة الأولى حمقاء، والرأي الأول أحمق.","kind":"hikma","topic":"الكلام والصمت","note":"بعنوان: تحذير خطير","source":"شذرات (ملف وورد)"},{"id":"m2328","text":"الأخبار الهامة، والأسرار الطامة، والتحركات السرية، والمشاورات الخفية، والتخطيطات الليلية، والأحداث الدوية، والأخبار الدولية، أول من يشعر بها ويعلمها الأمراء والرؤساء والمقربون من هؤلاء، ثم تنتشر في الآفاق والفضاء.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2329","text":"من طلب ما يستحق أدرك أو كاد، ومن طلب ما لا يستحق لم يُدرك ما أراد.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2330","text":"لا تطلب حاجتك من بخيل، إن ردك كان رده عليك عيبا، وإن أجابك كانت إجابته عليك دينا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2331","text":"البخل وسوء الخُلق وكثرة طلب الحوائج من أمارات السفهاء والثقلاء","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2332","text":"الكريم إذا وهبك نسي أو تناسى، والبخيل إن لم يذكرك بشفتيه، ذكرك بنظرات عينيه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2333","text":"الاستماع من طرف واحد مزلة أقدام، ومضلة أفهام، وعرضة للآثام، أما الاستماع من الطرفين، فأهدى سبيلا، وأوضح قِيلا، وأظهر تعليلا، وأصح دليلا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2334","text":"إذا أردت أن يصحبك الله في سفرك، فاذكره بلسانك وقلبك، فإن الله يذكر من ذكره، وذاكر الله المنان جليس الرحمان.","kind":"hikma","topic":"الإيمان والعبادة","note":"بعنوان: نصيحة للمسافر؛ وشرح: المنان: كثير العطايا والهبات","source":"شذرات (ملف وورد)"},{"id":"m2335","text":"عجبت من ابن آدم يشتري النار بالأموال والأثمان، ويزهد بالجنة وهي بالمجان، فالفجور والخمور بالدراهم والدينار، وطاعة الرحمان والصلاة أرباح وفوز بلا أثمان ولا خسران.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2336","text":"حياة العلم بالمراجعة والمذاكرة والمناقشة والمجادلة والمواثبة والمساءلة والمجاوبة ويكون في إطار الإيجابيات والأدبيات والأخلاقيات ولين الجانب، بلا تجريح، لا بالتلميح ولا بالتصريح، ويكون في الأمور العلمية والمعرفية والثقافية.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2337","text":"يحسن بمن يمد يد العون بالغذاء للمحتاجين والمعدمين أن يمدوهم بكميات كبيرة من التمر، لما له من الخواص والمميزات، فهو أطعم حلاوة، وأطول أمدا، وأكثر عددا، وأقوى سندا، وأكثر مددا، وهو طعام الصغير والكبير، وينعش الضعيف ويُرمم الهزيل.","kind":"hikma","topic":"الأخلاق والآداب","note":"تعليق على حديث: بيت لا تمر فيه جياع أهله","source":"شذرات (ملف وورد)"},{"id":"m2338","text":"ما أفضل انفاق المال لو كان في بطن جوعان، أو في سقي عطشان، أو على ظهر عُريان، أو في تدفئة بردان، أو في إيواء إنسان، أو في علاج أبدان، أو في طلب الجنان، واتقاء النيران، أو في سبيل الرحمان.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2339","text":"الوعود المستقبلية الثابتة بالنصوص الشرعية الصحيحة لا تتخلف، أما التفاصيل في وقوعها فهذه اجتهادات واستنباطات ظنية، قد تحدث وقد تتخلف، وفهم هذه النصوص يتضح بالمأثور مع رجاحة العقول، لا بالحماسة في البيان والمقول.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2340","text":"من كان رحيما وعقله كبيرا يتعب كثيرا، لأنه دائما يُقدم الإرشادات والتوجيهات والنصائح، والناس تُجادل وتناقش وتستثقل النصا ئح، فيحاول أن يُقنعها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2341","text":"من يزرع خيرا يجني خيرا، ومن يزرع شرا يجني شرا، فطوب لمن يزرع خيرا، وحسرة وندامة لمن يزرع شرا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2342","text":"أخبار الوتساب مثل أحاديث الإسرائيليات لا تُصدقوهم ولا تُكذبوهم حتى يتبين لكم الحق الأبلج، والصدق الأفلج، المؤيد بالأدلة والحجج.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2343","text":"عمل وقفيات مستدامة متنوعة، بدل عمل وقفية واحدة، فتنويع المصادر أبعد من المخاطر.","kind":"hikma","topic":"المال والاقتصاد","note":"جاءت في سياق اقتراح","source":"شذرات (ملف وورد)"},{"id":"m2344","text":"مقارنة لاختيار الأصلح لسياسة الدولة: النظام الديمقراطي مبني على الكم لا على الكيف، وغالب الناس يسعون للمكاسب الخاصة. والنظام الشوري مبني على الكيف لا على الكم: لاختيار الأصلح والأكفأ والأقوى لسياسة الدولة","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2345","text":"احذروا من اتخاذ القرار في شدة الغضب أو الفرح أو الحماس، لأن الإنسان ليس في كامل اتزان عقله، بل متأثر بالموقف الذي هو فيه، فتصبر حتى تعود إلى سابق عهدك الطبيعي المتوازن.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2346","text":"محاسن الأغنياء مساوء الفقراء: كرم الفقير تبذير، شجاعته تهور، عفوه جُبن، تواضعه ذلة، وقاره ثقل دم، نشاطه تصابي، صمته رخامة، حديثه هَذَر.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2347","text":"الإسلام دين وسط بين الإفراط والتفريط، بين رهبانية النصارى وعبادة نبيهم عيسى عليه السلام، وبين تمرد اليهود وقتلهم أنبياءهم عليهم السلام.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2348","text":"أغلب الغش والخداع والنصب يروج مع البُله والمغفلين والبريئين ومن يبالغون في حسن الظن.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2349","text":"إذا استمعت أو قرأت فركز، فإن أغلب الناس لا يستمعون ولا يقرؤون بتركيز.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2350","text":"إذا عرفنا أسباب الفشل، فقد عرفنا طريق النجاح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2351","text":"إذا أردت أن تعرف أن فلانا ثقة، فثق به فيما ينفعه ولا يضرك، حتى يتبين لك أمره، فإذا قصَّر فيما ينفعه، فكيف لا يُقصر فيما ينفعك، فالاختيار بعد الاختبار.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2352","text":"من حدَّث اللَّاهين كمن قدَّم طعامه للمُتخمين.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2353","text":"لا تمنع العلم أهله فتأثم، ولا تُحدث به غير أهله فتندم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2354","text":"لا تُجادل جاهلا ولا عالما، فالجاهل يُغضبك، والعالم يغلبك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2355","text":"الصفات المجبول عليها الإنسان تُوَرَّث لا مظاهرها، فقد يكون الأب شجاعا مجرما، فيكون ابنه شجاعا في قول الحق ونصرة المظلوم، فورث من أبيه صفة الشجاعة ولم يرث منه مظاهرها (الإجرام ) لأنه تربى في وسط صالح، فوظف شجاعته في الإيجابيات لا في السلبيات.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2356","text":"من السذاجة والضحالة أن تُبادر بتصديق كل ما يُقال، من غير دليل صادق، أو برهان ساطع، أو علم ناطق.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2357","text":"الفجار أزهد من المتقين، لأن الفجار يزهدون في الجنة الباقية، والمتقون يزهدون في الدنيا الفانية.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2358","text":"التوكل على الله جيش لا يُهزم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2359","text":"غضب العشاق سحابة صيف، سريعة الزوال.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2360","text":"غضب الجبان في أقواله، وغضب الشجاع في أفعاله.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2361","text":"غُبار العمل من أطيب الطيب، ويمنحك عزة النفس والسعادة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2362","text":"الحب المكنون يظهر في نظرات العيون، وكذلك البغض، فالعين نمامة والقلب كتوم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2363","text":"الحركات العضلية في أثناء الصلاة، والمشي إلى المساجد في النهار والظلمات، تحافظ على الصحة النفسية، واللياقة البدنية، وتزيد في التقرب إلى رب البرية، وتضاعف في الحسنات، وترفع الدرجات، وتكسب بها رضا رب الأرض والسماوات، وتدخل بها نعيم الجنات الخالدات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2364","text":"جاهل يطلب العلم خير من عالم يتباهى بالعلم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2365","text":"السمعة الطيبة ثمر العمل الكثير الطيب، والسمعة غير الطيبة ثمرة عمل واحد غير طيب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2366","text":"تسربات الهواء القليلة توقف الشاحنات الكبيرة، وتسربات المياه القليلة تُغرق السفن الكبيرة، فلا تهمل العيوب الصغيرة، حتى لا تتفاحش، فلا ينفع معها القوة ولا الحيلة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2367","text":"السعي والمجهود يحققان الأمل المنشود، ويقربان الأمل المفقود.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2368","text":"الجوع لا يلج بيت العامل طيلة الأسبوع.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2369","text":"الغضب لا يكون بدون سبب، لكن غالب أسبابه غير مقنعة، ولا متوقعة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2370","text":"خسارة الجهل أكثر من خسارة ما تبذله في طلب العلم.","kind":"hikma","topic":"العلم والثقافة","note":"له صيغ قريبة","source":"شذرات (ملف وورد)"},{"id":"m2371","text":"صدق ما تراه ولا تصدق ما تسمعه حتى تراه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2372","text":"لاستدامة صحتك أكثر نشاطك وقلل طعامك.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2373","text":"بسيوني وحسنين يعملان مع والدهما في الحقل، بسيوني نظيف ظريف متألق متأنق، وحسنين خلاف ذلك، فسُئل بسيوني عن سِرِّ التناقض بينهما؟ فقال: أنا لما أرجع إلى المنزل أغتسل وأتنظف وأتعطر، وأخي ينام ولا يغتسل ولا يتعطر، فهذا هو الفرق بين من يلزم الاستغفار وبين من يغفل عن الاستغفار، فالاغتسال تطهير مادي، والاستغفار تطهير معنوي.","kind":"hikma","topic":"الإيمان والعبادة","note":"قصة قصيرة","source":"شذرات (ملف وورد)"},{"id":"m2374","text":"لسلامة العلاقات الاجتماعية ودوامها لا بد من التسامح والتنازل من الطرفين، لأن ابن آدم خطَّاء، وكثير الغفلة والنسيان، فلا بدَّ من التغاضى والتغافل من الجانبين، للمحافظة على التواصل الاجتماعي وعدم القطيعة، وبالأخص في العلاقات الأسرية، وأهمها العلاقات الزوجية.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2375","text":"النقد مطلب كل فرد في الهزل والجد، ومن لا يملك النقد دمعته تسيل عل الخد، ويرى الأبواب مغلقة والطرق فيها شوك وسد. ومن يمتلك النقد، وأمواله لا تُعد، يرفع الهامة وصوته يمتد، وأقواله أفعال تُنفذ فورا قبل الغد، والأبواب في وجهه مفتوحة ليس دونها رَدّ ولا صدّ ولا سدّ.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2376","text":"النقد مادة المروءة، يستطيع الإنسان به أن يبر والديه، ويصل رحمه، ويوسع على أهل بيته، ويكفل اليتيم، ويطلق السجين، ويداوي المريض... ويعين على نوائب الدهر، ويترك لأولاده ما يقيهم ذل السؤال، ومشقة البحث عن المال. فالمال دعوة مستجابة، به تُحقق مقاصد الدنيا والآخرة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2377","text":"الخلاف في الرأي لا يفسد للود قضية، ولا يحول بين الاجتماع على طبق الكنافة والملوخية، وتجاذب أطراف الأحاديث الشيقة والندية.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2378","text":"أكثر الذين ينصحون غيرهم بنصائح فيها تكاليف لا يعملون بنصيحة أنفسهم، وكذلك الذين ينشرونها، لأن النصيحة مجرد كلام، لكن تطبيقها فيه مجهود وقيود، ومواقيت وحدود، والتزام على الدوام، في جميع الأيام.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2379","text":"الصبر مفتاح النجاح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2380","text":"إذا أردت أن يُحسن الله إليك فأحسن إلى خلقه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2381","text":"بعض الحكومات لا تهتم بمعاناة شعوبها باهتمام وجدية. بعض الحكومات تحلب شعوبها حلبا جائرا. أفضل الحكومات التي أهم أولوياتها مصالح شعوبها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2382","text":"لا تربط مصيرك بفتاة لا تُحسن الطبخ بالكلية، فإن الحب لا يصنع التبولة ولا الملوخية.","kind":"tarfa","note":"من «حكمة اليوم»","source":"شذرات (ملف وورد)"},{"id":"m2383","text":"لا تبحثوا عن الشخص الذي عنده خير وليس فيه خير، ولا تبحثوا عن الذي فيه خير وليس عنده خير، ولكن ابحثوا عن الذي عنده خير وفيه خير. أما الذي فيه خير وما عنده خير يكفي أن تلقاه بالصدفة من غير بحث عنه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2384","text":"من أهم العناصر لتحقيق الأهداف الصبر، فاصبر لتحقق أهدافك.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2385","text":"رُبَّ إهمال قليل تولد منه هَمٌّ كثير وتعب كبير، فبادر بالإنجاز ودع الإهمال.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2386","text":"اكتب همومك على صفحة الماء، وانقش نجاحاتك على الصخرة الصماء.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2387","text":"المجتمع كالجسد الواحد، فنجاح المجتمع مرهون بنجاح أفراده، بأن كل فرد من أفراده يقوم بأداء عمله، بحسب قدرته ومهارته، وهذا ديدن كل عمل جماعي.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2388","text":"نصحت قلمي بألا يخالف عقلي، ونصحت عقلي بألا يخالف ضميري، ونصحت ضميري بألا يخالف الحق والصواب وديني.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2389","text":"الخطأ في الخطة فشل في الإنجاز.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2390","text":"أول نجاح المشروع نجاح الخُِطة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2391","text":"كن اجتماعيا مع الجميع، ومحسنا مع الصديق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2392","text":"أول واجب على الطبيب أن يرفع المعاناة والآلام عن المريض، وأول واجب على الحكومة الجديدة أن ترفع الآلام والمعاناة عن الشعب، وتشرع بتوفير الضروريات ثم الحاجيات، ثم بعض الكماليات، وتبدأ بالفقراء، وبهذا سوف تكسب محبة الشعب وتأييده ودعاءه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2393","text":"يجب على الحكومة أن تُوجد فرص عمل لأفراد شعبها، فيها منافع للبلد والمجتمع، برواتب تغطي الضروريات والحاجيات، حتى يعيشوا بكرامة، وحتي يستتب الأمن، وتقل معدلات الجريمة، ومنها: السرقة والغش والرشوة والاختلاس.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2394","text":"هدية سمك الزبيدي تُكسبك الأصدقاء، وتُطفئ نار الأعداء.","kind":"hikma","topic":"العلاقات والناس","note":"من «حكمة اليوم»","source":"شذرات (ملف وورد)"},{"id":"m2395","text":"الصبر والمثابرة عمود النجاح والفلاح لعالم الذرة والفلاح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2396","text":"لا يتحقق النجاح إلا بعد تجارب فاشلة، فالنجاح ابن الفشل.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2397","text":"الحرية تبدأ بالعدالة والمسؤولية، لا بالادعاءات والكلمات العسلية.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2398","text":"هدية سلة الربيان، تزرع لك في قلب الإنسان، المحبة والعرفان، على مَرِّ الأيام والزمان، ولا يعتريها النسيان.","kind":"hikma","topic":"العلاقات والناس","note":"من «حكمة اليوم»","source":"شذرات (ملف وورد)"},{"id":"m2399","text":"من لا يستطيع أن ينهى نفسه عن الهوى لا يستطيع أن يسيطر عليها، والعكس صحيح.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2400","text":"القراءة النافعة بوابة العلم النافع، والعلم النافع بوابة النجاح والتقدم والرقي.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2401","text":"الكتابة مفتاح شخصية الكاتب، فمن قرأت كتابه فقد رطلت عقله، وسبرت غوره.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2402","text":"إن المؤمن ليؤجر على نفقاته على من يعول، ليوفر لهم الضروريات والحاجيات وبعض الكماليات، وهذا أولى من إنفاقه في القربات، فالنفقات الواجبة مقدمة على النفقات المندوبة.","kind":"hikma","topic":"المال والاقتصاد","note":"أعقبها بحديث رواه مسلم","source":"شذرات (ملف وورد)"},{"id":"m2403","text":"من أولويات بعض الحكومات أن تحمي نفسها، وأن تزيد من مزاياها المادية والمعنوية، أما حل مشاكل شعوبها ورفع ومعاناتهم، فهذه ليست من أولوياتها، بل هذه من النوافل، التي يمكن ترحيلها إلى الحكومات التي تأتي بعدها، والتملص من همومها ومتاعبها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2404","text":"مكاسب العلم المادية والمعنوية تفوق ما أنفقته في طلب العلم. وخسارة الجهل المادية والمعنوية تفوق ما خسرته في طلب العلم. وما ضاع من مالك ما أنفقته في تعليم عيالك.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2405","text":"اطلبوا عون الله وتوفيقه بعون الوالدين، ( والله في عون العبد ما كان العبد في عون أخيه ) مسلم، فكيف إذا كان العبد في عون والديه. الله أكبر.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2406","text":"التجارب هي المعلم الأول، الذي يلازمك طول حياتك، والذي يعطيك الحقائق اليقينية.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2407","text":"العقل المفتوح يتقبل الأفكار الجديدة، ثم يقوم بدراستها قبل أن يحكم عليها. والعقل الضيق هو الذي يبادر بإنكارها قبل أن يدرسها ويستوعب أبعادها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2408","text":"من الحماقة أن تُكرر الخطأ وتتوقع الصواب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2409","text":"إذا كان الفشل يزيدك حماسة وتحديا فأنت سوف تنجح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2410","text":"دع الخمول جانبا واعمل، فليس هناك بديل عن العمل.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2411","text":"من طبيعة الإنسان أنه لا يستفيد استفادة كاملة من جميع مهاراته وهواياته وقدراته، بل يُؤثر الراحة والتسويف، فجاهد نفسك لتتفوق.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2412","text":"الأولاد ثمرة الفؤاد.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2413","text":"بر الوالدين دين، تراه في أولادك رأي العين.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2414","text":"حاجب الشهوات غض البصر.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2415","text":"نعم الشفيع الهدية بين يدي الحاجة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2416","text":"من نزل على بخيل فقد نزل بواد غير ذي زرع.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2417","text":"البخيل نظيف القِدر صغير القَدر.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2418","text":"الزواج يروي العطشان، ويُطفئ نار حب الولهان.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m2419","text":"الهدايا الثمينة تغسل الأحقاد الدفينة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2420","text":"النصيحة في العلن فضيحة، والنصيحة في السر أو التعريض مليحة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2421","text":"يقول الأب المربي: لولا ربي ما عرفت ربي، ولولا ربي ما عرفت كيف أُربي، فتأديبي لأولادي في عَقلي لا في عِقالي، ونصحي في لساني لا في يدي وأسناني، لا أُطفئ شمعته، ولا أجرح سُمعته، ولا أدعس وردته، ولا أُشوه فطرته، ولا أكسر شوكته، بل أُوجهه كيف ومتى يشكها.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2422","text":"اليد العاطلة طويلة وكذلك التي لا تكسب ما يفي بضرورياتها، فقد تمتد لأموال غيرها، عن طريق السرقة والغش والتزوير والرشوة والاختلاس والخداع، وهي من أكثر أسباب الجرائم إنتشارا في المجتمع، فيجب على الحكومة أن تُوجد لهم أعمالا نافعة، ولو أن يقطعوا الحجارة من قمم الجبال، أو يستخرجوها من قاع البحار، حتى يشعروا بأهميتهم ورجولتهم، فالمساعدات بمقابل أفضل وأعز من مساعدات من دون مقابل، في حق الأقوياء القادرين على الكسب، حتى لا يركنوا للوهن والتراخي، ويكونوا عالة على المجتمع، وحتى لا يُصابوا بداء العجزة، وبمثل هذا تقل معدلات الجريمة، وترتفع معدلات الأمن والسكينة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2423","text":"أبخل البخل، البخل بالكلمة الطيبة، ورد السلام، والنصيحة في السرِّ، والدعاء في الخفاء، والتحية الحلوة، والابتسامة اللطيفة، والنظرة بالمودة، وشكر الجميل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2424","text":"الوتساب ينقل الباطل والصواب","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2425","text":"لقد تفشى التزوير، في الترجمة والتصوير، ولم يسلم منه الوزير ولا الأمير، ولا الصغير ولا الكبير، فلا تتعجلوا باللوم أو التبرير، حتى يتبين لكم الحق المبين من الباطل والتشهير.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2426","text":"نوم الصباح من الأمر المباح، لكن النشاط والعمل فيها أفضل من النوم والانبطاح، وأبواب الرزق تنفرج فيها للإنفتاح.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2427","text":"ياابن أدم يومك وعاؤك إن ملأته بالخير وجدته، وإن ملأته بالشر وجدته، فاملأه بالخير، فهو أهنأ وأمرأ وأبرأ، وأجود وأحمد وأمجد، وأحسن وأزين وأطمن.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2428","text":"من مدح نفسه فقد شجع الناس على البحث عن عيوبه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2429","text":"من تكبر على الناس بقوته أو ماله، وقروه في حضرته وحقروه في غيبته.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2430","text":"من تواضع مع قوته وغناه، أحبه الناس وأثنوا عليه في وجوده وغيابه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2431","text":"القناعة رداء العزة، والطمع رداء الذلة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2432","text":"لا تزال شابا ما دمت نشيطا، فإذا تركت النشاط فأنت كهل.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2433","text":"أفضل استثمار هو الإستثمار في تنمية العقل بالعلم والمعرفة والثقافة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2434","text":"من فكر بالعواقب سلم، ومن اندفع بحماس ولم يفكر بالعواقب ندم.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2435","text":"بُغض العدوِ المشترك يُكَوِّن صداقات وتعاونا بين المتباعدين.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2436","text":"أينما كنت فكن ذا أخلاق حميدة، وآداب مجيدة، وآراء سديدة، وكلمات مفيدة، وأفكار جديدة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2437","text":"إن أردت أن يكُف عدوك شرَّه عنك، فعامله معاملة صديق، لتُطفئ نار حقده الشديد.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2438","text":"راعوا كباركم في الأعمار كما تراعون أطفالكم الصغار، فهم في حالة ضعف ووهن ومرض، ولم تعُد حواسهم وذاكرتهم ونشاطهم وصحتهم، مثل ما كانوا في ريعان شبابهم، فلا تُكثروا نقاشهم وجدالهم وعتابهم، فلا تغتروا بالرجل الكبير، فهو غير مرتاح صحيا ومهزوز نفسيا وذهنيا، وقد يتظاهر بالتماسك حتى لا يُحزن من حوله، ولكي يحافظ على هيأته وهيبته وهالته.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2439","text":"النقاش في الوتساب ينشط الأحباب، ويُبرز العلل والأسباب، ويفتح النوافذ والأبواب، ويُثري الوتساب بآراء الخبراء وذوي الألباب، ولا يُعطي ثمرته إلا إذا كان بالطراوة والنداوة والآداب، والخلاف في الرأي لا يفسد للود قضية، ولا يحول بين الاجتماع على طبق الكنافة والمحلبية، وتجاذب أطراف الأحاديث الشيقة والندية والعفوية.","kind":"hikma","topic":"الكلام والصمت","note":"تتضمن صيغة أخرى لل","source":"شذرات (ملف وورد)"},{"id":"m2440","text":"فقد الإخوان تصدع الأركان، وهدم البنيان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2441","text":"فقد الأصحاب غربة في الزمان، ووحشة في المكان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2442","text":"موت الأشرار راحة للأخيار، وبركة في الأقطار.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2443","text":"موت الظالم لا يستدر الدموع، ولا يُحزن ما بين الضلوع.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2444","text":"خذوا النشاط والدأب والنظام والتعاون من النملة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2445","text":"الأنبياء عليهم السلام هم الذين أرسوا مكارم الأخلاق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2446","text":"قبل أن تُخالط الناس، أخفِ الهموم والغموم والأحزان، وأبدِ البِشر والتفاؤل والابتسام للأنام.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2447","text":"تقليل كمية الوجبات زياد في الصحة، وتكثير الحركات زيادة في النشاط.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2448","text":"مجهود النهار يجلب النوم المريح، والنوم المريح يجلب النشاط بالنهار.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2449","text":"الجوع يزيد في لذة الطعام، ونِعم الإدام الجوع.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2450","text":"كثرة الاعتذارات من قلة المروءات.","kind":"hikma","topic":"الأخلاق والآداب","note":"له صيغ قريبة","source":"شذرات (ملف وورد)"},{"id":"m2451","text":"التوافق التام بين المفاهيم الفطرية والإنسانية والعقلية والحقائق العلمية من ناحية، والمفاهيم الإسلامية من ناحية، فهذا نور ساطع، وبرهان قاطع، ودليل واقع، على صحة المفاهيم الإسلامية، وسلامتها من الانتقاد والقدح، والجدال والردح. لأن المفاهيم الفطرية والإنسانية والعقلية والحقائق العلمية خلق الله. والمفاهيم الإسلامية قول الله، وقولُه لا يخالف فعلَه، وفعلُه لا يخالف قولَه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2452","text":"إن عحزت عن الصدقة فلا تعجز عن الابتسامة، فَتَبَسُّمك في وجه أخيك صدقة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2453","text":"إرضاء جميع الناس غاية لا تُدرك، فوسِّع صدرك، واذكر ربك، واصبر واحتسب.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2454","text":"كل ممنوع مرغوب وكل مبذول مملول، فكن مع أولادك، ومن هم تحت يدك، بين البذل والمنع، فالمنع يزيد في قيمته ولذته، والبذل يُزهد فيه ويقلل من لذته.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2455","text":"الوتساب على وشك الانفجار، من كثرة الأحداث والأخبار، وما فيها من الإرجافات والأسرار، ومنها الصريح ومنها خلف الأستار، ولا يلزمكم التصديق بكل ما يُقال، وعليكم التثبت والتحري مما يثار، ومما يُقال في الأخبار.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2456","text":"لا أعرف قواعد النجاح، لكني أعرف أن السعي الجاد المتواصل، والإصرار على محاولة النجاح، مع الخطأ والتجارب الفاشلة، هي بداية طريق النجاح، فالكعكة الأُولى محروقة، والثانية معطوبة، والثالثة كأنها طوبة، والرابعة طيبة ومطلوبة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2457","text":"اشتغل ولو في الجمعة والأعياد، ولا تمد يديك إلى الأسياد.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2458","text":"ذو اليد العاملة يملأ بطنه وبطن من يعول.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2459","text":"من تسامح مع الذئاب فقد ظلم الأغنام.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2460","text":"المجالسة من المؤانسة، والمصادقة من الموافقة، والمعاشرة من طيب المباشرة، والزيارات على قدر الترحيبات.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2461","text":"ينبغي على الناس أن يتعاونوا ويتكاتفوا ويتعاضدوا، في دفع الشر وهو في مهده، قبل أن يتفاقم الشر، ثم يعمهم الشر ويصل إليهم، فيصعب عليهم القضاء عليه، أو تغييره أو تقليله.","kind":"hikma","topic":"العلاقات والناس","note":"العبرة من قصة العصفور والفخ","source":"شذرات (ملف وورد)"},{"id":"m2462","text":"من كان خطؤه نادرا أو قليلا، فامنحه العفو والتقديرا، ومن كان خطؤه فاحشا أو كثيرا، فاهجره هجرا جميلا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2463","text":"النساء مِدْفَأَةُ الشتاء، إذا اشتد برد الشتاء فليلتصق الزوجان تحت الغِطاء.","kind":"hikma","topic":"الحياة الزوجية","note":"بعنوان «حكمة الشتاء»","source":"شذرات (ملف وورد)"},{"id":"m2464","text":"صاحب الصالحين، فالصالح مع الصالح: إن غبت افتقدوك، إن مرضت جاؤوك، إن نجحت هنؤوك، إن فترت نشطوك، إن نسيت ذكروك، إن دعوا أشركوك، إن افتقرت أغنوك، إن احتجت أعانوك، إن أصبت شكروك، إن أخطأت سامحوك، إن دعوت أجابوك، إن سافرت ودَّعوك، إن حضرت استقبلوك، إن استنصرت نصروك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2465","text":"من الغلطة والورطة أن تسمع من توجيه واحد، ثم تُكَوِّن فكرة وقناعات يقينية، عليك أن تسمع من الفريقين المتناقضين، والحزبين المختلفين، بتعقل وتفكر وتأمل، والاستعانة بأهل العلم والعقل والفهم، للواقع والمتوقع، وطلب الهداية والتوفيق من الله سبحانه، قبل أن تُكون فكرة صحيحة أو أقرب إلى الصواب، ورأيا صائبا أو أقرب، ومع ذلك اتهم رأيك ولا تغتر، واطلب من الله الهداية الصواب والسلامة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2466","text":"إرضاء جميع الناس غاية لا تُدرك، وإرضاء المنصفين منهم غاية يمكن أن تُدرك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2467","text":"من طبيعة الإنسان أن حبه للممنوع أشد من حبه للمبذول.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2468","text":"الصبر والمثابرة مفتاح تحقيق الإرادات.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2469","text":"إذا رفعت كريما فوق قدره رفعك، وإن رفعت لئيما فوق قدره أهانك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2470","text":"في الحروب تكثر الإشاعات والإرجافات والخداعات والافتراءات، والكذب والاحتيال والمكر، فالعاقل لا يبادر بالتصديق أو التكذيب، حتى يتبين له القول الحقيق من القول المريب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2471","text":"الكلام الحماسي في العالب لا يسلم من الشطط بخلاف الكلام العقلاني المتوارن. فمع الانفعال تخرج كلمات نشاز، تسبق التفكير المتأني الممتاز، فلا تُبادر بالأحكام القاطعة قبل التدبر بالعاقبة، فالإستعجال في إصدار الأحكام يجلب الندامة، والتأني يجلب السلامة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2472","text":"بعض الناس لا يملكون ما يقلونه أو يفعلونه، مما يجلب الإقناع أو الاستماع، فيثبتون حضورهم بالصراخ والعج، أو يُبرزون شخصيتهم بالتأييد الفج، أو بالاعتراض بالجدال واللجج، أو بطول اللسان المعوج، فهؤلاء لا ينفع معهم الجدال بالحجج.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2473","text":"الجسد ينمو بالغذاء، والعقل ينمو بمجالسة العلماء والعقلاء والأدباء والحكماء والخبراء والأذكياء، وذوي الحنكة والحيلة والسياسة والدهاء.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2474","text":"أكرموا غوغاءكم، فإنهم يُنقذون الغريق، ويرصفون الطريق، ويُطفئون الحريق، ويسدون البثوق، ويحفرون الآبار، ويحملون الأحجار، ويبنون الدار. إن اجتمعوا ضروا وإن تفرقوا نفعوا، كل يذهب لحرفته وصنعته ومهنته وعمله، أكرموهم واحذروهم فإنهم يسيرون خلف كل ناعق، فأكرموهم ولا تسيروا خلفهم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2475","text":"إدارة ذكية وموارد طبيعية قليلة وغير نقية، خير من إدارة غبية وموارد طبيعية كثيرة ونقية.","kind":"hikma","topic":"السياسة والقيادة","note":"من «حكمة اليوم»","source":"شذرات (ملف وورد)"},{"id":"m2476","text":"ما أفلح من أفلح إلا بصحبة من أفلح، وما خسر من خسر ألا بصحبة من خسر. فالصاحب ساحب، والصديق مثل المصعد إما تصعد به، وإما أن تهوي به. فصاحب ذا الأخلاق الحميدة، ولا تصاحب ذا الأخلاق الرديئة، فإن الطباع تُعدي.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2477","text":"الاقتباس من تجارب من سبقك باب كبير من أبواب العلم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2478","text":"من الحكمة الترتيب العلمي للأولويات.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2479","text":"مَنْ عادته كثرة الاعتذار لا يشارك الرجال، ولا يتقدم في انجاز المهام الكبار.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2480","text":"ليس من مكارم الأخلاق، ولا صفات النبلاء، ولا شيم العلماء، الحجر على الآراء، التي ليس فيها ظلم ولا اعتداء، ولا إثارة للدهماء، ولا تشويش للصفاء، ونشر الجفاء بين الأصدقاء، ولا خير في الإرهاب الفكري، كما لا خير في الإرهاب الجسدي.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2481","text":"حسن الأخلاق من طيب الأعراق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2482","text":"عامل الناس بالاحترام كما تُحب أن يعاملوك بالاحترام.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2483","text":"من اغتاب الناس في ديوانك، اغتابك في ديوانهم، فحاول أن تصرفه عن الغيبة، بطريقة لطيفة، خالية من الجفاء والكبرياء، فقد تُدرك بلين الكلام ما لا تُدركه بوخز الملام.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2484","text":"إذا قصدت لحاجة، فاقصد لقريب أو صديق أو مُحب أو لبيب أو أريب، فإنه إذا ما قضاها دلك على من يقضيها.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2485","text":"البخيل يحرم نفسه ليُمتع ورثته وهو لا يشعر.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2486","text":"الأخلاق الحميدة تقوي الصداقات القديمة، وتصنع الصداقات الجديدة، وعوائدها من السمعة الطيبة والمديح عديدة ومفيدة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2487","text":"من رضي بما قسم الله له، اطمأن قلبه، ورضيت نفسه، وفارقته الهموم، وانقشعت عنه الغموم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2488","text":"أفضل الجود بالمال، ما كان قبل السؤال، وصادف حاجة الرجال، في الحال والمآل.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2489","text":"لا تُجادل المتعصب لرأيه، لأنه لا يبحث عن الحق والصواب، بل يبحث عن الانتصار لرأيه على الأصحاب، ولو أدرك أن رأيه خراب، خالي من الصواب.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2490","text":"عِظوهم ولا تُقنطوهم، رَجُّوهم ولا تُجَرئوهم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2491","text":"رُبَّ شربة ماء لكلب عطشان تجلب مغفرة الرحمن فتجب ما قبلها.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2492","text":"آراء الشباب حماسية، واندفاعاتهم نارية، ونظراتهم شرارية، وألسنتهم حديدية، وتخيلاتهم غير سوية، وتجمعاتهم غوغائية، وتنقصهم التجارب الواقعية فيحتاجون إلى نصائح وتوجيهات عملية، من الكبراء والخبراء، والحكماء والعلماء. والأتقياء","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2493","text":"من أدب العلماء النبلاء، وكبار السن الأتقياء، اختيار الألفاظ التي لا تجرح الحياء، وترتفع عن أساليب السفهاء، ولا تُحجر على الآراء، ولا تُثير البغضاء، ولا تنفر الأصدقاء، ولا تُشمت الأعداء، ولا تُعير الأغبياء، ولا تحتقر البلهاء، ولا تُهيج الدهماء، ولا تُشجع الغوغاء، وفيها هداية لأهل الأرض ورضا لمن في السماء.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2494","text":"اجعل التوقيع ملاصقا للسطر الأخير، من غير تأخير، لتسلم من التزوير.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2495","text":"إن كان من أساء الظن بك منصفا، فمن الأفضل أن توضح له الحقيقة، بأفضل طريقة","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2496","text":"اللحية الكثة لا تصنع الفيلسوف الفلتة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2497","text":"اللحية والشعر المنكوش لا يصنعان فنان الرسم والنقوش.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2498","text":"الكرسي المستدير لا يصنع الوزير.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2499","text":"اللحية والعمامة البيضاء لا يصنعان العلماء.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2500","text":"كثرة النجوم والنياشين، لا تدل على أنه خاص في الحروب والميادين.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2501","text":"الغيبة هدية واردة، وغنيمة باردة، وحسنة من صاحبها شاردة، لحسناتك زائدة، فطب نفسا، وقر عينا، أراد أن يحط من قدرك، فوهبك خير ما يملك، فرفع من قدرك، وهو لا يدرك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2502","text":"استمع إلى جميع الآراء المعتبرة، ثم تبنى أصحها وأنفعها في الدنيا والآخرة، فإذا رأيت ما هو أصوب وأنفع فقدمه ولا تجعله في المؤخرة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2503","text":"الوتساب ليس جامعة ولا كلية أكاديمية ولا معهدا لإلقاء المحاضرات والدروس الطويلة، إنما هو للشذرات وقراضات الذهب، وهات يدك والحقني، وهات وخذ على المختصر السريع، النافع المفيد، وهو مثل السوق، كل مشارك يعرض فيه أجود ما لديه، مما له نفع وقبول لدى الناس، ومن آدابه أن يبتعد عن الخشونة والرعونة ومخالب البزونة، وعن الهواش في الحوار والنقاش.","kind":"hikma","topic":"الكلام والصمت","note":"بعنوان «عقيدة الوتساب والتويتر»","source":"شذرات (ملف وورد)"},{"id":"m2504","text":"الحماسة في طرح الأفكار، بدافع الانتصار، لا بدافع ترجيح الرأي المختار، مزلة في ميزان الاعتبار، إلا من غلب عقلُه هواه وهذا قليل في الرجال.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2505","text":"ما جاع أهل بيت فيه الزيت والخبز.","kind":"mathal","topic":"المال والاقتصاد","note":"ختم بها كلامه عن زيت الزيتون","source":"شذرات (ملف وورد)"},{"id":"m2506","text":"التغريدة التي لا تطول، لها حظ أكبر من القبول، والتغريدات المكررة، أو كلماتها كثيرة، ليس لها حظ عند الجموع الغفيرة، فعليكم بالإيجاز فهو عمود الإعجاز.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2507","text":"حياة القروب بالتغريدات، وحياة التغريدات بالتعليقات، وحياة التعليقات بالمناقشات، وحياة المناقشات بحسن الآداب وعدم التجريحات، والابتعاد عن الخشونة والرعونة في الاحتجاجات، والتحلى بالرزانة واختيار الكلمات، وحسن النية والتماس الأعذار لمن يخالفنا في الأُطروحات، وموت القروب بخلاف هذه التوجيهات.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2508","text":"لا مانع عقلا ونقلا وعادة وعرفا، من تقديم النصيحة والمشورة للحاكم التي فيها مصلحته ومصلحة الرعية والوطن، بالقول اللين الصريح، وعدم التشهير والتجريح، مع التوقير والتقدير، فصلاح الحاكم صلاح للرعية، وغش الحاكم غش للرعية.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2509","text":"من كثرت أمجاده كثر حساده.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2510","text":"كثرة الحساد تدل على كثرة الأمجاد، وكثرة الأمجاد تدل على كثرة الاجتهاد.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2511","text":"الخامل الجامد ليس له في الناس حاسد.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2512","text":"الماء عنوان الحياة، فإذا وجدت ماء فثم حياة.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2513","text":"إذا شعرت أن أحدا يناقشك بحدة وشدة، وحماسة ونحاسة، واستخفاف ليس معه استلطاف، فدخن عليه حتى يهدأ، تعامل معه كتعامل النَّحال مع النحل، كلمه بلين كما كلم موسى عليه السلام فرعون، فلعله يثوب إليه عقله، فتلين عريكته، وتسهل طبيعته، ولا تخاشنه ولا تغالظه، فحلمك عليه يُكثر أنصارك عليه، فتعظم في عيونهم ويصغر في عيونهم، وحلمك عنوان عقلك وأخلاقك، والحلم سيد الأخلاق.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2514","text":". استعينوا بنومة الليل على نشاط النهار، وبنشاط النهار على نومة الليل واستعينوا بالقيلولة على قيام الليل","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2515","text":"إذا لم تجد حَطَبَةً كبيرة تحت قدرك فسوف تسعى لجمع الأعواد الصغار، وكذلك من ليس لديه دليل قوي يؤيد رأيه، فسوف يسعى لإيراد كثرة الإستدلالات الضعيفة، والشواهد الواهية والقرائن, وتكرارها باألفاظ مختلفة وأساليب متنوعة، ليُؤيد رأيه، فربما تكون هذه أمارة على ضعف القضية المُستدل عليها، وهذه من الحيل العقليه في الإقناع، وتنطلي على الغوغاء والدهماء.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2516","text":"همسة عتاب: ما أكثر في الوتساب من يُوصي بمكارم الأخلاق، وما أقلهم في البيوت والشوارع والأسواق","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2517","text":"الأم كنز الحنان ومعدِن الأمان في كل الزمان من غير ملل ولا توان ولا كلل","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2518","text":"العرق دساس يسري في الظلام لا يضل ولا ينام يجتر الصفات الخَلقية والخُلقية من الآباء إلى الأولاد ومن الأجداد إلى الأحفاد فتخيروا لنطفكم قبل زواجكم تسعدوا في ذرياتكم وتُغبطوا في أولادكم","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2519","text":"لا تفرط بحسناتك، فمن يغتاب الناس في الدنيا، فسوف يأخذون من حسناته في الآخرة، الكثير بالكثير والقليل بالقليل، فطوبى لمن صان لسانه عن أعراض الناس، فقد حافظ على حسناته من الضياع، وعدم الثواب والانتفاع.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2520","text":"لا تفتح كل الأبواب لصديقك، ولا تُغلق كل الأبواب لعدوك، لأنك لا تضمن تبدل الأيام، وتغير الزمان، وتحول الإنسان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2521","text":"لا يعرف المؤمن فضيلة الإيمان حتى يعرف ماذا أعد الله للمؤمنين في الجنان. لا يعرف الكافر خطر الكفران، حتى يعرف ماذا أعد الله للكافرين من العذاب في النيران.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2522","text":"اختلاف وجهات النظر قديم من لدن آدم عليه السلام، عندما اختلف قابيل وهابيل. والنتائج تتفاوت بحسب القسمة المنطقية: - أحدهما مصيب والثاني مُخطئ. - كلاهما مصيب: لكن أحدهما أصوب من الآخر. - كلاهما مُخطئ: لكن أحدهما أكثر خطأ من الآخر. - وقد تتفرع المسائل بحسب التصورات الممكنة عقلا. فالمهم أن الاختلاف في الرأي لا يُفسد في الود قضية، ولا يمنع الابتسامة والتحية، والمشاركة في اللقمة الهنية.","kind":"hikma","topic":"العقل والحكمة","note":"تتضمن صيغة أخرى لل","source":"شذرات (ملف وورد)"},{"id":"m2523","text":"طوبى لمن شغله ذكر الله عن الإكثار من متابعة الأخبار، لأنها تسرق الأعمار، ولما فيها من الإشاعات والإرجافات والكذب والأسرار، وما فيها من الاختلاف والنزاع بين الصغار والكبار، والمخاشنة من أجل الانتصار، واقتصر على المهم منها من غير إكثار، واكتفِ بالدعم والعون وبالدعاء لنصرة المسلمين وخذلان الكفار.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2524","text":"الفضيلة بين رذيلتين، والحسنة بين سيئتين، لا إفراط ولا تفريط.","kind":"hikma","topic":"الأخلاق والآداب","note":"جاءت في سياق نصيحة لرواد الوتساب","source":"شذرات (ملف وورد)"},{"id":"m2525","text":"لا يوجد شيء سهل في البدايات: المشي صعب الكلام صعب، جميع الأنشطة في بدايتها صعبة، وبالتدريب والممارسة والمداومة، تصبح سهلة وتتحول إلى ملكة وطبيعة وتلقائية، في غاية السهولة والمهارة والاتقان، فكل صعب في البدايات سهل في النهايات، فما عليك إلا أن تبدأ وتحاول وتستمر وتثابر، لتحقق أهدافك المرجوة، فإصرار الطفل على المشي يجعله يمشي في غاية السهولة والتلقائية.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2526","text":"من سعادة الحياة الزوجية، أن يتعامل الزوج مع زوجته كما يتعامل مع مرقة البامية، يحركها ويقلبها ويغرفها برفق ورقة ولطافة، فالمرأة ريحانة وليست بقُهرمانة.","kind":"hikma","topic":"الحياة الزوجية","note":"القُهرمان: وكيل الملك أو رئيس التجار يراقب السوق، كثير الغضب والصخب (من شرحه","source":"شذرات (ملف وورد)"},{"id":"m2527","text":"احشوا الوتساب بالفوائد النافعة، والشذرات اللامعة، والحكم الجامعة، والقراضات الناصعة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2528","text":"قيدوا العلم بالكتابة، وقيدوا النِّعَم بالشكر.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2529","text":"إذا خاض الناس بالغيبة فقد أفلح الساكت الصموت.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2530","text":"السيف القاطع يحتاج إلى قلب شجاع وذراع.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2531","text":"قد تُبتلى الحسناءُ بالطلاق.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m2532","text":"الجَزَّار لا يهاب من كثرة الأغنام.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2533","text":"إذا كثُر الذباب أغلقوا النوافذ والأبواب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2534","text":"كُلْ في بعض بطنك تسلم من الداء وتستغني عن الدواء.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2535","text":"الشك في محله وقاية، وفي غير محله نِكاية.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2536","text":"كيف تسلم من الأحداث الشِداد، وقد جف القلم بما أراد، فعليك بالصبر والاستغفار ودعاء رب العباد.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2537","text":"عقيدة الوتساب أن الآراء تُعرض ولا تُفرض، والنقاش يكون باللين والآداب، لا بالعنف والسباب، وبالرفق لا بالإرهاب، وكن من المؤلفين لا من المنفرين، ولا تجعلوا بينكم فرجة يدخل منها الشياطين، لتُفسد عليكم الأُخوة في الدين.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2538","text":"من وهبك الصحة فقد وهبك النشاط، ومن وهبك النشاط فقد أعانك على العمل، ومن أعانك على العمل فقد رزقك، ومن رزقك فقد ملأ بطون أولادك وكسى ظهورهم، فالصحة نعمة منسية، وهي أعظم نعمة بعد الإيمان.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2539","text":"كثرة الضحك تُذهب الهيبة، وكثرة العُبُوس تجلب الوحشة والخيبة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2540","text":"أكرموا كباركم قبل أن يموتوا فتندموا على تقصيركم وإهمالكم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2541","text":"أكرموا شبابكم فإنهم أعوانكم وسندكم في شيبتكم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2542","text":"إذا قرأت ما ينفع فسوف تستطيع أن تكتب ما يُقرأ.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2543","text":"زلة اللسان تُصيب القلب، وزلة القدم تُصيب البدن.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2544","text":"معرفتنا بالمخلوقات تبدأ بالحواس، وتنتهي بمعرفة خالقها، والإقرار له بالوحدانية والعبادة والطاعة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2545","text":"لو راقبت النملة في تصرفها، لوعظتك دون أن تنطق ببنت شفة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2546","text":"خسائر الإهمال الصغير كبيرة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2547","text":"السعي وراء اللذات عاقبته وخيمة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2548","text":"صِلوا أرحامكم، ولا يكن أحدكم كالقبر المهجور، لا يُزار ولا يَزور.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2549","text":"إذا أنعم الله عليك بوفرة المال، فاجعل ديوانك كالكعبة، يرد إليك الحبيب والقريب والغريب، فيجدون عندك الإكرام والترحيب","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2550","text":"افتح ديوانك، واستقبل إخوانك، يُكثر الله أحبابك وأنصارك وأعوانك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2551","text":"لا تثق بوعود الإنسان المتلون، فكلامه بالليل يمحوه النهار، وكلامه بالنهار يمحوه الليل.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2552","text":"كن كالمِغزل يكسو نفسه وغيره، ولا تكن كالإبرة تكسو غيرها وهي عُريانة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2553","text":"الكفالة ندامة، والشركة شجار، وكفالة اليتيم تُورث الجنة، ومن مسح دموع اليتيم مسح الله سيئاته.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2554","text":"الأفراد يحتاجون إلى مجتمع، والمجتمع يحتاج إلى نظام، والنظام، والنظام يحتاج إلى قانون، والقانون يحتاج إلى سُلْطة، والسُلْطة تحتاج إلى هيبة، والهيبة تحتاج إلى ملك، والملك يحتاج إلى حِجاب وحُجَّاب، فعلى الملك أن لا يظهر كثيرا لعامة الرعية، حتى لا تسقط هيبته، فتضعف سلطته، وتلين شوكته، فلا يهابه المفسدون والمستهترون.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2555","text":"نصف الحقيقة خُدعة كاملة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2556","text":"التسريب الصغير فد يُغرق المركب الكبير، فلا تستهن بصغائر الذنوب، ويتوب الله على من يتوب.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2557","text":"ما بدأ بالغضب انتهى بالخصام والعطب.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2558","text":"النشاط يُسَهِّل انجاز المهمات، والكسل يصعبها، فعليك بالنشاط ودع الكسل والانحطاط.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2559","text":"الصدق من صفات الأبرار، ويمنحك الثقة عند الأخيار.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2560","text":"من يُكثر الأعذار لا يعتمد عليه الرجال.","kind":"hikma","topic":"الأخلاق والآداب","note":"له صيغ قريبة","source":"شذرات (ملف وورد)"},{"id":"m2561","text":"خسارة الجهل تفوق خسارة الإنفاق على طلب العلم بمراحل، لأن الجهل نقص في العقل، والعلم زيادة في العقل.","kind":"hikma","topic":"العلم والثقافة","note":"له صيغ قريبة","source":"شذرات (ملف وورد)"},{"id":"m2562","text":"توقعات اختلاف وجهات النظر أرجح من توقعات اتفاق وجهات النظر، والقريب من الأحداث يرى ما لا يراه البعيد، واتفاق الناس على رأي واحد غاية لا تدرك، فلتتسع صدورنا، وليعذر بعضنا بعضا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2563","text":"العين تُصدق ما تراه، والأُذن لا تُصدق كل ما تسمعه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2564","text":"الإنسان يبحث عن العيوب أكثر مما يبحث عن المميزات، فهو يميل إلى القدح أكثر مما يميل إلى المدح.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2565","text":"من سلبيات الحديث عن عيوب الناس وتقصيراتهم؛ يُطفئ فيك روح الحماس نحو الترقي والتقدم. ومن إيجابيات الحديث عن مزايا الناس وتفوقهم؛ يُشعل فيك روح الحماس نحو الرقي والتقدم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2566","text":"السمعة الطيبة كبناء العمارة تحتاج وقتا طويلا، والسمعة السيئة كهدمها لا تحتاج وقتا طويلا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2567","text":"الطموح النشيط يُبادر لإنجاز الأعمال، ولا يلوذ بالاعتذار.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2568","text":"الماهر في اختراع الأعذار، فاشل في التقدم والاستمرار.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2569","text":"العمل الشاق في النهار أفضل وسادة للمنام.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2570","text":"القروب يحوي الرسائل والآراء والفديوهات والتغريدات، لا يستطيع المشارك أن يتابع كل الآراء والمقولات، لكن أهم شيء أن يكون الحوار والنقاش في ظل الأدب والاحترام، وبعيد عن الخشونة والاتهام، فلا يلوح بالفزاعة، فيعكر صفو الجماعة، فإنها بئست البضاعة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2571","text":"لا تَتَبَنَّ رأيا حتي تسمع من الطرفين، وتقارن بين القولين، وتوازن بين الحجتين، فإذا تبين لك مستقبلا أن الحق مع الطرف الآخر، فدع رأيك وخذ بالرأي الآخر، فالرجوع إلى الحق فضيلة، والتمادي في الباطل رذيلة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2572","text":"شجاعة اللسان تحتاج إلى الحجة وقوة البيان، وشجاعة الأبدان تحتاج إلى قوة العضلات والجَنان.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2573","text":"التعلم الدائم طريق التفوق الدائم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2574","text":"الاختراعات هي عجلة التقدم وحَلُّ المشكلات","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2575","text":"التفكير إذا زاد، لا يخلو من الترددات، فيكون مُعوقا عن الإنجازات.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2576","text":"المبالغة في التفكير، قد تكون من الوسواس والتكدير، فتُؤثر على المبادرة في التدبير.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2577","text":"قبل الاختيار استشر المجربين الكبار الأخيار.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2578","text":"النجاح يجلب السعادة كما تجلب الزهرة النحلة، والشجرة الخضراء الجرادة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2579","text":"العمران الكبير البناء، أو الشاهق في السماء، يخلدان ذكر الملوك والأمراء.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2580","text":"الفُرص لا تدوم، فهي للمبادرة لا لطول التفكير وكثرة المشاورة","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2581","text":"نجاح المشاريع الكبيرة، ثمرة الهمم الكبيرة، والتخطيطات العلمية الجديرة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2582","text":"نَوِّرْ عقلك بالمداومة على القراءة النافعة والاستماع النافع، من غير ملل ولا كلل.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2583","text":"من عوامل النجاح المهمة، الترتيب السليم في الأولويات، لتحقيق الأهداف المقصودة من أجل إنجاز العمل النافع.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2584","text":"إياكم والتغريدات المعادَة، فالتغريدة إذا أُعيدت كالطعام البائت إذا سُخِّن، لا لون ولا طعم ولا رائحة تفتح النفس، إلا التغريدات القوية، فهي مثل المحشي أو مرق البامية، بائتهما ألذ من حاضرهما.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2585","text":"اصلاح البلد مثل غسيل الدرج، يبدأ من الأعلى مثل غسيل البدن يبدأ بالرأس وينتهي بالقدم مثل اصلاح الأسرة يبدأ من الأب","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2586","text":"لا توجد مكاسب وأرباح، من غير أتعاب وكفاح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2587","text":"الكسلان يعيش في الأمنيات، والمجتهد يحقق المكتسبات.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2588","text":"من يتحلى بالصبر والاجتهاد يحقق ما أراد.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2589","text":"العلم هو السلاح الأقوى لمحاربة الجهل والخرافات.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2590","text":"من اجتهد في العمل وابتعد عن الوسادة قرب من السيادة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2591","text":"من أهمل العمل، وآثر النوم سبقه القوم.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2592","text":"من عاش بالآمال قصَّر في الأعمال.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2593","text":"من آثر الراحة والرقاد، عجز عن تحقيق المراد.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2594","text":"التواضع يقربك من الناس، ويزرع لك المحبة في قلوبهم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2595","text":"التخطيط الجيد يرسم لك طريق النجاح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2596","text":"طور نفسك بمواصلة القراءة والتعلم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2597","text":"أول سِرِّ من أسرار النجاح أن تستعين بربك في جميع أعمالك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2598","text":"لا تكافح من أجل النجاح فقط، ولكن من أجل النجاح ونفع الناس.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2599","text":"النجاح يتحقق لمن يسعى لتحقيق النجاح، ولا يتحقق لمن لا يسعى لتحقيق النجاح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2600","text":"إذا أردت أن تكون سعيدا في حياتك وبرزخك وآخرتك فارض بأقدار الله، فإن كانت موافقة لهواك فاركب لها مطية الشكر، وإن كانت مخالفة لهواك فاركب لها مطية الصبر.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2601","text":"لا يزال المرء محترما بين الناس ما كانت أسراره مكتومة، وعيوبه مردومة، فإذا ما شاعت أسراره، وذاعت عيوبه، سقط من أعين الناس سقوط البعرة من است البعير.","kind":"hikma","topic":"الأخلاق والآداب","note":"أعقبها بدعاء","source":"شذرات (ملف وورد)"},{"id":"m2602","text":"إذا أردت أن تختار زوجة لتُسعدك، فاختر زوجة لتُسعدها، فإذا أسعدتها فسوف تُسعدك.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m2603","text":"الحياة قصيرة فلا تُفرِّط فيها، فاستبدل الشجار بالاستغفار، والخصام بالصيام، والخناق بالاتفاق، وهَلُمَّ جرا.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2604","text":"لا تقتنِ الأشياء التي لا تُناسب ميزانيتك، حتى لا تحمل ديونا فتذل نفسك وأهلك.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2605","text":"ترك ما حرم الله خير من الاجتهاد في التوبة، فالثوب الجديد خير من الثوب المغسول.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2606","text":"لا تُظهر بُغضك ولا تُبالغ في إظهار حُبِّك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2607","text":"لا فقر مع اقتصاد ولا غنى مع تبذير.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2608","text":"إذا لم يستجب الله دعاءك، ولم يتحقق مرادك، فلا ترتدِ رداء الأحزان، فلعل الله يريد أن يدفع عنك شرا أو يجلب لك خيرا، أو يدَّخر لك أجرا.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2609","text":"لا ترفس حمارا رفسك ولاترد على سفيه أساء إليك","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2610","text":"علاج الجاهل التجاهل.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2611","text":"من ظلمك فقد وهبك حسناته أحوج ما يكون إليها.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2612","text":"من لا يندم على الذنب لا يتوب من الذنب.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2613","text":"من لا يشعر بوخز الضمير على من أساء في حقه، لا يفكر في الاعتذار منه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2614","text":"ابن آدم إذا ولَّتْهُ الستونَ ذنبها أدرك أن قيمة الحياة في طاعة خالقها.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2615","text":"صيام رمضان صحة للأبدان، ومغفرة للإنسان.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2616","text":"الصيام أحد الشفائين.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2617","text":"صوم رمضان جهاد الأبدان والعادات والشهوات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2618","text":"نوم الصائم عبادة، لأنه نائم على نية صالحة، وجميع أعضائه متلبسة بأعمال عبادة الصيام.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2619","text":"ما ألين اللسان في حالة الرضى، وما أقسىاه في حالة الغضب.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2620","text":"باب الكريم مفتوح وجوده ممنوح.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2621","text":"عودوا أولادكم عادات الكرام، فإنها ترفع شأنهم عند الأقوام، وتجلب لهم محبة الأنام.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2622","text":"بعض النشاط يكون بدافع الكسل، يَعمل بسرعة من غير إتقان، كي يذهب ليستريح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2623","text":"إهانة الإنسان حرام، وتقديسه حرام، واحترامه على قدر صلاحه ومنزلته.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2624","text":"الإسلام جمع بين العلم والدين بخلاف الديانات الأخرى، فهو أحرى أن يقود العالم نحو شاطئ السلام وبر الأمان.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2625","text":"لا تُجادل الأحمق حتى لا يلتبس على بعض الحاضرين أيكما الأحمق.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2626","text":"سِرُّ الحيوية أن تحتفط بنشاط الشباب أطول مدة ممكنة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2627","text":"كلما كثر أصدقاؤك كثرت الواجبات الاجتماعية عليك، فقلل من الأصدقاء وأكثر من المعارف.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2628","text":"طفولة الفقراء قصيرة، لأنهم يباشرون الحِرف والمِهن وهم صغار، أما طفولة الأغنياء فطويلة لأن آباءهم ينفقون عليهم حتى يكملوا دراساتهم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2629","text":"العدل اقوى جيش، والأمن اهنى عيش.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2630","text":"المتصفح للكتاب ابصر بمواقع الخلل من منشئه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2631","text":"من حسن التدبير مراعاةالمقادير: فالذبائح على قدر الضيوف، والقدور على قدر الذبائح والطبيخ، والنار على قدر القدور، مراعاة المقادير عنوان العقل الكبير.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2632","text":"لن يشتهر الرجل بالجود، ويُعد من الاجاويد، ويحتفل به التاريخ، ولا يمحو ذكره كرُّ الليالي والايام، حتى يطأ جوانب الاسراف. ولن يشتهر الرجل بالشجاعة، ويقوم له فيها سوق، حتى يجول في حواشي التهور.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2633","text":"حد الكرم عند العقلاء، الا تبخل بالموجود، ولا تتكلف المفقود.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2634","text":"مثل الاصدقاء كالنار قليلها متاع، وكثيرها بوار، فقلل من الأصدقاء وأكثر من المعارف.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2635","text":"أحسن الكلام ما قرَّط الآذان، واسعد الاذهان.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2636","text":"من طال عمره أخذ الزمان من جسمه ثم من حواسه، ثم من عقله.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2637","text":"من طال عمره خانه الثقتان: السمع والبصر.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2638","text":"لا تُقاس الحياة بالكم، ولكن تُقاس بالكيف، فحاول أن تقضيها بفعل الخيرات وترك المنكرات، وارحموا من في الأرض يرحمكم من في السموات.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2639","text":"لو أن أحداً إذا اغتاب أحداً خُصم من حسابه بقدر غِيبته، ثم وُضع في حساب من اغتابَه، لما اغتابَ أحدٌ أحداً قط.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2640","text":"الحرية أن تفعل ما تشاء بشرط ألا تخالف النقل والعقل.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2641","text":"تحقيق النجاح الأول حافز لتحقيق النجاح الثاني.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2642","text":"بالمقاومة والإصرار ستجعل الفشل حافزا لتحقيق النجاح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2643","text":"حاول أن تستفيد من صفات صديقك الإيجابية، وتقي نفسك من صفاته السلبية.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2644","text":"التربية والتعليم أقوى وسيلة لبناء الأُمة القوية.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2645","text":"الإنجازات الكبيرة تتطلب ميزانية كبيرة، وجهدا كبيرا، ووقتا طويلا، وإدارة خبيرة حازمة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2646","text":"اذا توقع الانسان المكروه تصوره في اشد حالاته، فاذا وقع وجده دون ما تصوره، فاحدث ذلك له سرورا.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2647","text":"احق الناس بمعروفك اهلك، وافضل ما رجعت اليهم به نفسك، فاحرص على ان ترجع اليهم سليما ذا عافية.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2648","text":"من خُلعت عليه ولاية تشرئب اليها الاعناق، فقد عُرِّض للبلاء، ان اتقى الله مقتوه، لأنه لا يلبي طلباتهم، وان سايرهم ورَّطوه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2649","text":"ذو الهمة العالية يسعى لتحقيق أهدافه، وذو الهمة الفاترة يتمنى أن يحقق أهدافه.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2650","text":"الذكي يحل المشكلة والغبي يُعقدها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2651","text":"العلم فضيلة ذاتية للمتصف بها، والمال فضيلة خارجية لمن يبذلها في الخير.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2652","text":"لا مريحة خير من نعم متعبة.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2653","text":"الوفاء من سجايا الكرام.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2654","text":"خير الكلام ما نفعك جِدُّه وابهجك هزله.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2655","text":"الآمال ممدوده والايام معدودة.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2656","text":"كتاب المرء عنوان علمه، وميزان عقله، وامارة رأيه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2657","text":"اذا بنيت فوسع الممرات، وأكثر المرافق، فهي عشك وفيها عيشك.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2658","text":"ينبغي للشباب ان يتقدموا الشيوخ في ثلاث: اذا ساروا ليلا، او واجهوا خيلا، او خاضوا سيلا.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2659","text":"إذا رأيت الزوج يستمع لزوجته باهتمام وشغف وهي تتحدث عن أُمور تافهة، فاعلم أنه قريب عهد بزواج. وإذا رأيته يستمع إليها ظاهرا وهو مشغول بما هو فيه، وهي تتحدث عن أُمور هامة، فاعلم أنه بعيد عهد بزواج. بالنهاية لازم تسمع وتطيع","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m2660","text":"لا تكن في المناسبات كالسراج يُضيء حوله وتحته ظلام، أكرموا السواق والخدام والضعفاء والفقراء، فهذه من خصال الإسلام، وسنة المبعوث رحمة للأنام.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2661","text":"الكاذب لا يُصَدَّق ولو صَدَق، والصادق لا يُكَذَّب ولو صدر منه كَذِبٌ بالخطأ.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2662","text":"لا تُبالغ في حسن الظن، ولا تُبالغ في سوء الظن، وكن حذرا فطنا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2663","text":"توكل على الله، فلا تُبالغ في الندم على الماضي، ولا في الحزن على الحاضر، ولا في الخوف من المستقبل.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2664","text":"نأتي الدنيا ومعنا أعظم شيء نأتي ومعنا فطرة الإيمان والتوحيد ونذهب ومعنا فطرة الإيمان والتوحيد بفضل الله تعالى","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2665","text":"بعض الصائمين يبالغ في الاحتراز من دخول ماء المضمضة أثناء الوضوء، ولكنه لا يُبالي في أكل اللحم! لحم أخيه عندما يغتابه، ولعله يهبه ثواب صيامه وهو لا يعلم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2666","text":"يا أهل النور إذا رأيتم جهازا أو نورا يعمل من غير حاجة فأطفئوه، نوَّر الله قبوركم وقلوبكم ووجوهكم بنور الإيمان وطاعة الرحمن، فالطاقة الكهربائية؛ في أصلها نعمة وهبية، فاشكروا الله عليها، ولا تُسرفوا فيها، فإنه لا يحب المسرفين.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2667","text":"إذا عضك كلب فلا تعضه، وإذا رفسك حمار فلا ترفسه.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2668","text":"كلما تعلم العاقل شيئا حديثا بادر في تعلم غيره حثيثا.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2669","text":"الصبر والإصرار هما طريق تحقيق النجاح والإنتصار.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2670","text":"نقص الثقة بالنفس احجام عن الممكن فهو عجز زيادة الثقة بالنفس اقتحام غير الممكن فهو ورطة","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2671","text":"من أمارات العقول النيرات حسن التقديرات","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2672","text":". الإسلام دين الفطرة السليمة، والأخلاق القويمة، والموازين السليمة، والحقائق الرصينة، والمبادئ الكريمة،","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2673","text":"هم يدافعون عن حرية التعبير لكنهم يحاربون حرية الاعتقاد هم يشددون على الرأفة بالحيوان لكنهم بصنعون أسلحة تبيد الإنسان هم يدافعون عن حقوق المرأة لكنهم يحاربون الشعوب فيبيدون الرجال ويجعلون النساء أرامل والأطفال أيتام هذا ديدنهم ومكرهم في قلب الحقائق، وهلم جراً.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2674","text":"أصحاب الاعتقادات الباطلة التي نشأوا عليها وورثوها عن آبائهم، لا يُحبون أن يسمعوا الحق لأنه يهدم اعتقاداتهم التي اعتنقوها منذ نعومة أظفارهم، فلا بد من تأليف قلوبهم وملاطفتهم والحكمة في اقناعهم، بالأدلة العلمية والبراهين العقلية.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2675","text":"النيات اكثر من المأتيات، فالإنسان ينوي أكثر مما يعمل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2676","text":"ائتلاف النفوس ينمي البركة، واختلافها يمحقها.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2677","text":"مداخلة الملوك اخطر من ركوب البحار، والسباحة ضد التيار.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2678","text":"العدل اوتاد المُلك، والظلم معاوله.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2679","text":"شرُّ المال ما قارنه الحرام في اكتسابه وانفاقه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2680","text":"العدل أمارة اقبال الدولة، والجور أمارة إدبارها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2681","text":"لا يُخاطب الملوك بما يقتضي جوابا، لانهم ان اجابوكم شقَّ عليهم، وان لم يجيبوكم شقَّ عليكم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2682","text":"الاعمال بنياتها، والاعمار بخواتيمها، والمشاريع باتمامها، والباقيات الصالحات باستدامتها.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2683","text":"استعن على تحقيق رجاءك في ربك، بتحقيق رجاء عبيده فيك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2684","text":"بالاقلام تُساس الاقاليم","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2685","text":"لولا الشروط لضاعت الحقوق.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2686","text":"حسن الخط يُظهر جمال الحق. وحسبك خطوط القرآن.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2687","text":"الشهوات تُترك ولا تكره. والجهاد يكره ولا يُترك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2688","text":"احق الناس بالفضل اهل الفضل، لان التفضل عليهم يعم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2689","text":"من اكرم كريما فقد اكرم عشرة، ومن اكرم بخيلا فقد اكرم واحدا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2690","text":"من تكلم في غير تخصصه سرح في بحر الخيال، وعوَّل على انطباعاته النفسية وما يختلج في البال، وشرَّق وغرَّب في صنوف المقال، خذوا العلم من أهله ومعدِنه، واحذروا من أنصاف العلماء، فإن الناس تنخدع بحسن عرضهم، وبهرجة كلامهم، فهم أخطر من الجهال في ترويج باطل المقال، وجرأتهم على الدين لا تخلو من الخبال.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2691","text":"اختيار الله لعبده خير من اختيار العبد لنفسه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2692","text":"جنت على أهلها براقش","kind":"mathal","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2693","text":"لولا تفريط الكويتيين لما برزت ظاهرة المزورين","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2694","text":"في كل مجتمع منافقون وهم أُسُّ الفساد والمجون","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2695","text":"الجيفة تجلب النسور والأموال السائبة تجلب أهل الفجور","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2696","text":"لو عاقبت الأول لما تجرأ الثاني","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2697","text":"لا صلاح ولا تعمير إذا تفشت الرشوة والتزوير","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2698","text":"حاربوا الفساد قبل سقوط عماد البلاد","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2699","text":"جشع التجار يزيد في معدلات جرائم الأشرار","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2700","text":"النصائح إذا لم تجد آذانا واعية أصبحت كلماتها لاغية","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2701","text":"رئيسك في العمل لا تجادله ولا تخاشنه بل حاول أن تكسب رضاه وإعجابه بأخلاقك ونشاطك ولينك من غير أن تخالف مبادئك ودينك ، حتى يثق بك ويذكرك في المناسبات الإيجابيه فيُؤثرك ويقدمك ويتسامح معك ولا يُخاشنك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2702","text":"زوجك أبُو أولادك هو رئيس البيت وعمود الخيمة ، فلا تخاشنيه ولا تشاجريه ولا تُكثري الجدال ولا تُطيلي النقاش ، وحاولي أن تكسبي ودَّه ورضاه ، وتنالي إعجابه وتوافقي هواه ، حتى يُحافظ على حبك واحترامك والاهتمام بك ، فالمرأة العاقلة الرزينة تكسب وُدَّ زوجها بجميل طبعها وحسن أخلاقها وحلاوة لسانها.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m2703","text":"البركة في البقر لأنها عجلة انتاج ودوائر استنتاج ، نتغذي من ألبانها ومنتجات ألبانها ، ونستصلح بحرثها وبمخلفاتها أراضينا الزراعية ، ونستفيد من جلودها ، فالحمد لله على نعمة بهيمة الأنعام.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2704","text":"من ستر على نفسه ستره الله تعالى ، ومن فضح نفسه فضحه الله تعالى . من ستر على غيره ستره الله تعالى ، ومن هتك ستر غيره هتك الله ستره","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2705","text":"إذا أدناك أمير أو وزير أو سفير أو مدير أو مشير من نفسه فقد جعلك شافعا عنده ، وذريعة لقضاء حوائج الناس لديه ، فرُبَّ صدقة جاه خير من صدقة مال.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2706","text":"أنواع الأزواج ثلاثة : بصري يهتم بجمال الشكل والهندام . سمعي يهتم بجمال الصوت ومعاني الكلمات . ذوقي يهتم بجودة الأكلات والمطهيات . ومن الأفضل للزوجة أن تجمع بين الثلاثة أنماط","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m2707","text":"طفولة الفقراء قصيرة ، لأنهم يباشرون الحِرف والمِهن والأعمال الشاقة وهم في ميعة صباهم ، ليساعدوا آباءهم على تكاليف الحياة الباهظة ، أما طفولة الأغنياء فطويلة لأن آباءهم ينفقون عليهم حتى يستكملوا دراساتهم : الابتدائية والمتوسطة والجامعية.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2708","text":"الأصل في الأشياء والتصرفات الإباحة والجواز ، فلا يجوز التضييق على الناس.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2709","text":"المهم في قراءة القرآن التدبر والتفكر والتعقل ، ولا يبالغ في التفكر ويطيل ، حتى لا يجور الكيفُ على الكَمِّ ، وإذا لمعت بفكره خاطرة استنباطية فلا ينشرها حتى يتأكد من أهل الاختصاص ، أو يرجع إلى كتب التفسير ويتأكد من صوابها وصحتها ، حتى لا يجلب لنفسه الإثم والذم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2710","text":"إن الله سبحانه أودع في الأرض كنوزا لعباده ، ووهبهم مفاتيحها ، فبالعقل والجهد يستخرجون منها أنواع المعادن ، وأنواع الحبوب والثمار ، متى شاؤوا ، وكم شاؤوا ، على حسب حاجاتهم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2711","text":"أهم رسالة يُؤديها المعلم لطلابه ، أن يقوم بغرس حب القراءة والمعرفة والعلم والثقافة في عقول طلابه ، منذ المراحل الأولى ، لتُصبح لهم عادة وطبيعة ، فهذا هو سِرُّ تقدم الدول ، ومفتاح رُقي الشعوب.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2712","text":"مهما قال الناس والعلماء ، من الأذكار والدعاء ، في الصباح والمساء ، تبقى الأذكار المأثورة عن سيد الأنبياء ، عليهم الصلاة والسلام هي الأولى في الاقتداء ، والأفضل في جلب الخير ودفع البلاء ، فقد أُوتي جوامع الكلم وفواتحه وخواتمه من رب السماء.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2713","text":"لا تلتفت للفتاوى الشاذة ، ولا يهولنك براعة العرض واللفظ ، والتصوير والتعبير ، حتى تأتيك الفتوى من المجامع الفقهية المعتبرة ، وأقوال كبار العلماء والفقهاء المشتهرة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2714","text":"لا تُبالغ في الجِدِّ ولا تُبالغ في الهزل ، وعليك بالنمط الأوسط.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2715","text":"الناس قد يتشابهون في الآراء والأقوال ، لكنهم عند التطبيق يتباينون في المواقف والأفعال.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2716","text":"كثير من الناس يُخطئون ، وقليل منهم الذين يستغفرون ويعتذرون.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2717","text":"الفشل هو بوابة النجاح للصابرين المثابرين الذين لا يثبطهم الفشل العارض عن الاستمرار في تحقيق النجاح ، فمن جاهد لتحقيق النجاح أو لمعرفة الصواب فسوف تفتح له الأبواب ، ويُعان من رب الأرباب.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2718","text":"كلام العلماء تحليل وتأويل ، وتعبير وتفسير ، وبيان وتنوير ، وتبيين وتحرير ، واستنباط وانضباط ، ودراية ورواية ، وتوضيح وهداية ، فهو يصلح للنشر إلى يوم الحشر. وكلام العامة انطباعات نفسية ، وتخيلات وجدانية ، وتأويلات سطحية ، وعبارات سوقية ، وتخبطات عشوائية ، لا تصلح للنشر على الخاصة والرعية.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2719","text":"الناس يشتكون من كثرة العنوسة ، فإذا جاءكم من ترضون دينه وخَلقه وخُلقه وراتبه فزوجوه.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m2720","text":"العرف مصدر من مصادر التشريع ، وكذلك هو معتبر في القانون ، والمعروف عرفا كالمشروط شرطا.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2721","text":"من تكلم فيما لا يعنيه لقي ما لا يرضيه","kind":"mathal","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2722","text":"من تكلم في غير تخصصه أتى بالعجائب والغرائب ، وترك الرأي الصائب وتمسك بالرأي الخائب.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2723","text":"قبل أن تقوم بالواجب فكر في العواقب","kind":"hikma","topic":"العقل والحكمة","note":"عبرة قصة الحصان والخروف","source":"شذرات (ملف وورد)"},{"id":"m2724","text":"بشروا ولا تنفروا ، يسروا ولا تعسروا ، تآلفوا ولا تنافروا ، اجتمعوا ولا تتفرقوا ، واعلموا أن الإسلام ليس مثل حدِّ السيف ، ولا يأمرك أن تشق الشعرة طولا شعرتين ، ولا أن تعقد بين شعيرتين ، وإنما فيه تيسير ورخص ، ويحث على اختيار الأيسر ، ومن فقه الرجل أن يفتي بالبسير لا بالعسير.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2725","text":"صفات الإنسان مدفونة ، فإذا دُفن ظهرت.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2726","text":"من كثرت محاسنه كُذِّب ذامُّه ، ومن كثرت مساوئه كُذِّب مادحه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2727","text":"الإيمان والكفر لا يجتمعان فإذا دخل نور الإيمان في القلب خرجت ظلمان الشرك من القلب.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2728","text":"من جد وجد ، ومن زرع حصد ، ومن سعى علا ومجد ، والتجارب لا تكذب ، ومن سهر الليالي ، وعزف عن اللهو والتسالي ، حقق المجد والأماني.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2729","text":"لا تُقنطوا الناس من رحمة الله الواسعة ومغفرته العظيمة ، فالحسنة بعشرة أمثالها وزيادة ، والسيئة بمثلها أو يغفر ، وإن الحسنات يُذهبن السيئات ، وإن رحمة الله غلبت وسبقت غضبه ، لا بد من الاعتدال في الترغيب والترهيب ، وترجيح الترغيب على الترهيب.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2730","text":"نريد أن ننتخب من لا يزيد رصيده ولا يشتري عمارة جديدة ولا مزرعة وياخور ولا طراد وقرقور ولا رواتب استثنائية ولا أوراق نقدية ولا مميزات خفية","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2731","text":"جربنا الديمقراطية نفعها فقط للأقلية نريد نظاما يعود نفعه على الجميع والأكثرية","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2732","text":"نريد الكفاءات والأمانات يتولون المهمات","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2733","text":"رُبَّ نصيحة جرت إلى فضيحة","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2734","text":"لا تترك عملك حتي تمسك عملا خيرا من عملك","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2735","text":"من أراد أن يغتسل وينظف نفسه فليبدأ من الرأس ومن أراد أن يغسل الدرج فليبدأ من أعلاه فإذا أردت أن تنظف وزارة أو شركة فابدأ من رأسها","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2736","text":"الوزارة كالسمكة يبدأ عطبها من رأسها","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2737","text":"كون الإنسان مخلوق هذا أصل وجوده ، أما منزلته فهي أين وضع نفسه ، والمكانة التي نزل بها : في الإيمان أو الكفر ، في العلم أو في الجهل ، . . . إلى آخر الصفات المكتسبات ، فيكون عِصاميا لا عظاميا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2738","text":"ضرب الأمهات للبنات للتأديب لا للتعذيب وضرب الآباء للأبناء للتصليح لا للتجريح وضرب المعلم للطالب للرعاية لا للنكاية فيجب أن يكون الضرب برفق تأديبا لا تعذيبا","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2739","text":"صاحب المركز التجاري والعاملون قال : هذا الإسبوع أول فصل الشتاء ، فسوف يكثر الزبائن ، فمن يبذل مجهودا كبيرا في البيع والترويح فسوف أُضاعف له الراتب ، فشرع العاملون بجد ونشاط وحماس لاستقبال الزبائن والبيع بشتى الوسائل المتاحة ، فهكذا مواسم العبادة والطاعة ينبغي التنافس فيها ، وبذل الاجتهاد والنشاط ، لما فيها من الأحر العظيم المضاعف","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2740","text":"عليكم بكثرة الصدقات والوقفيات، للآباء والأُمهات ، في هذه الأيام المباركات ، فإنها من أيسر الطاعات ، وأنفعها للفقراء وضعفة العائلات ، وثوابها عظيم ومن المضاعفات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2741","text":"المعاملة الحسنة هي سِرُّ نجاح العلاقات الزوجية والاجتماعية.","kind":"hikma","topic":"العلاقات والناس","note":"خلاصة قصة","source":"شذرات (ملف وورد)"},{"id":"m2742","text":"من فقه الرجل ألا يسأل عمَّا سكت عنه المُشرع.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2743","text":"الشحرة المثمرة تُرمي بالأحجار ، والرجل الناجح ينتقده الحساد والفجار.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2744","text":"الاعتدال ميزان لرجاحة عقل الإنسان.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2745","text":"قطرات المطر إذا تكاثرت أغرقت ، وصغائر الذنوب إذا تكاثرت أهلكت.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2746","text":"من يسير في الحياة بدون نور العلم والبينات ، كمن يسير في الظلمات.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2747","text":"الحق يبني أركان الدولة ، والباطل يزلزل أركانها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2748","text":"الغضب جنون عارض ، وعلاجه تجرعه وكتمانه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2749","text":"الفرد الواثق بقوته وأمانته وكفاءته جدير بأن يقود الجماعة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2750","text":"غلاء الشيء من ندرته لا من كثرة منافعه ، فالحديد أنفع من الذهب ، لكن الذهب أغلى من الحديد.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2751","text":"احترس من الكلمة النابية ، فإذا خرجت من الشفتين لا يُمكن نسيانها ولو بعد عامين.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2752","text":"إذا أردت أن تتربع على قمة الهرم في التميز ، فعليك ألا تتوقف عن طلب العلم والقراءة والسؤال.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2753","text":"العلم يرفع من شأن الرجال ، والجهل يحط من قدرهم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2754","text":"كل مصنوع نافع صنعه إنسان يحب الخير للناس ، مثل صناعة الدواء المفيد ، وكل مصنوع ضار صنعه إنسان لا يحب الخير للناس ، مثل الحشيش المبيد.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2755","text":"اغتنموا هذه الأوقات الأيام العشر المباركات للصدقات والوقفيات للآباء والأمهات الأحياءمنهم والأموات بها تضاعف الحسنات وتُكفر السيئات قبل الفوات","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2756","text":"الشدائد تدفع العقول لإيجاد الحلول ، فتكشف الشدائد عن العقول العبقرية التي كانت خفية.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2757","text":"الكلمة في صدرك كالعصفور في القفص ، فلا تخرجها إلا في وقتها المناسب ، والندم على حبسها أيسر من الندم على إخراجها.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2758","text":"الهدف الأسمى من وجودنا على ظهر الأرض هو ، أن نحقق الإيمان بالله تعالى ، وأن نعمل الصالحات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2759","text":"العاقل يستفيد من تجارب أصدقائه وأعدائه ، والغبي لا يستفيد من تجارب أعدائه ولا حتى من أصدقائه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2760","text":"ليس من شرط النجاح عدم الأخطاء ، ولكن من شرط النجاح عدم تكرار الأخطاء.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2761","text":"لا تُنجز شيئا لا يحتاج الناس إليه ، أو ليس بمقدورهم شراؤه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2762","text":"إذا أردت أن تُنجز شيئا ، فأنجز شيئا يحتاجه السوق ، وثمنه في مقدور الناس.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2763","text":"من الجهد والمال الضائعين أن تُنجز شيئا لا يحتاجه الناس ، أو لا يقدرون على ثمنه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2764","text":"الصديق الصالح في الدنيا ينفع، وفي الآخرة يشفع ، إذا اقترب منك منح، وإذا ابتعد عنك مدح، وإذا أخطأت صفح ، ينصحك دون جروح ، ويحبك دون طموح . الصديق الصالح نعمة معجلة، وذخيرة مؤجلة ، ونعمة لا تقدر بأموال مكدسة ، فالأخوة في الله مصباحك حين تظلم دنياك ،وسرك حين تفيض شكواك ، وسندك حين تنهار قواك ، وهو الرفيق في الطريق ، والصديق وقت الضيق ، والمواسي والشفيق ، يلقاك وهو صبوح ، وهو من قرابة الروح.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2765","text":"الإسلام لم يأمرنا أن نمشي على الجمر ، ولا على حدّ السيف ، ولا على الشوك ، ولا على العقارب والثعابين ، الإسلام أمرنا بالإيمان والعمل الصالح ، ونهانا عن الكفر والكبائر ، وشرع لنا عبادات تقربنا منه ، وتكفر الصغائر ، كالوضوء والصلاة والحسنات ، واجتناب الكبائر يُكفر الصغائر ، وشرع لنا قبول التوبة من الكفر والكبائر ولو قبيل الغرغرة ، فيسروا ولا تعسروا ، وبشروا ولا تنفروا ، وتعاونوا ولا تختلفوا ، ولا تُقنطوا الناس من رحمة الله ، ولا تُدخلوهم في المتاهات والاختلافات ، ولا تلجوا بهم في بنيات الطريق وتدعوا المحجة البيضاء ، ولا تسألوا عن أشياء سكت الله عنها رحمة بكم ، ولا تُكثروا القيل والقال وكثرة السؤال والجدال ، فإن هذا يُضعف اليقين وأُخوة الدين ، ويشتت أمر المسلمين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2766","text":"لا تهدروا أعماركم ، وتطأوا زهرة شبابكم ، في الجدل العقيم ، والنقاش السقيم ، وتدخلوا في الدهاليز المظلمة ، والكهوف المعتمة ، وتخوضوا في بحار لم يلجها سلفكم ، من أصحاب نبيكم وأتباعهم ، وكهوف لم يفتح أبوابها من سبقكم من خياركم ، ألا يسعكم ما وسعهم ، فقد سلكوا الطريق. ، وساروا في المحجة البيضاء ، ليلها كنهارها ، وتحنبوا بُنيات الطريق ، وكل واد متشعب سحيق ، فالعلم كثير والعمر قصير ، فخذوا روحه ودعوا ظروفه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2767","text":"غرور طالب العالم بعلمه يقتل طموحه في طلب العلم. شعور العالم بقلة علمه يحثه على طلب العلم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2768","text":"التمسك بالتقاليد الباطلة ، والعادات غير الفاضلة موت معنوي ، وطمس عقلي.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2769","text":"عوِّد نفسك على التجرد ، وأن تحكم على الأشياء بعقلك وعلمك ، لا بهواك وانطباعاتك الشخصية ، وميولك العاطفية ، حتى لا تشطح وأن تظن أنك على الحق المبين.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2770","text":"عملك إن أحسنته شهد لك ، وإن أسأته شهد عليك ، فاحرص على تحسينه وتجويده.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2771","text":"شهادة الأعمال لا تُرد ، وشهادة الأقوال المجردة عن الأعمال لا تعتمد.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2772","text":"الفرص لها إقبال وإدبار ، فاغتنمها في أول إقبالها ، كي تقطف ثمارها ، وإن لم تدركها فتهيأ للتي بعدها.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2773","text":"الفتنة كالنار إن لم يتداركها ولي الأمر بالقوة والحزم فهي دمار.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2774","text":"في المواقف الحرجة تَحَكَّم في أعصابك ، حتى لا تتهور ، فأدنى ثمرة التهور الندم والاعتذار.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2775","text":"طلب العلم بوابة الفضائل ونافذة الجمائل.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2776","text":"كثير من الناس يقيمون المواقف حسب المشاعر والعواطف ، لا حسب الحقائق والموازين.","kind":"hikma","topic":"العلاقات والناس","note":"عبرة قصة","source":"شذرات (ملف وورد)"},{"id":"m2777","text":"إذا اشتعلت النار فبادر بإطفائها وإخمادها قبل استفحالها وانتشارها ، وكذلك إذا بدرت فتنة فبادر باحتوائها واستئصالها قبل أن تستشري في الغوغاء والدهماء ، والمتربصين والمتحفزين.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2778","text":"القوة لها مظاهر متعددة ، فالحمار يهاجم بحوافره ، والذئب بأنيابه ، والثور بقرونه ، والعقاب بمخالبه ، والطفل بدموعه ، والمرأة بضعفها ورِقتها ، والرجل بعلمه وعقله ، وهذه القوة الأكثر تأثيرا ، والأقوى تدبيرا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2779","text":"الفرس تنقاد لفارسها ولو اقتحم بها معمعة المعارك ، واختلاف الرماح والسيوف ، فكان الأجدر بالإنسان العاقل أن ينقاد لأوامر ربه ، من انقياد هذا البهيم الأعجم لصاحبه ، فإن الحصان البهيم لصاحبه سميع مُطيع ، وإن الإنسان الفهيم لربه كنود عنيد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2780","text":"ما ذُكِر اسم الله علي صعب إلا هان ولا شديد إلا لان ولا خائف إلا اطمأن ولا مضطرب إلا سكن ولا همٍّ إلا خرج ولا ضيق إلا انفرج","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2781","text":"من خالط الأخيار واعتزل الأشرار ، فقد أحسن الاختيار ، وبالغ في جلب المنافع ودفع المضار ، فالمرافقة تمهد للموافقة ، والصاحب الصالح ساحب للفضائل والمصالح.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2782","text":"من أهم الأسباب ، للمحافظة على أخلاق أولادك الشباب ، أن تسعى وتحتال ، لإيجاد الفرص والأسباب ، لمصاحبتهم خيرة الشباب ، فالصاحب الصالح ساحب للفضائل والمصالح ، فالصحبة الصالحة مؤثرة ، أكثر من النصائح المتكررة.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2783","text":"ليست الفضيلة بالأعمار الطويل والمديدة ، إنما الفضيلة بالأعمال الصالحة وسلامة العقيدة ، فإذا اجتمعت الأعمار الطويلة والأعمال الصالحة ، كانا كالسمن مع العسل ، وتحقق الفوز والأمل.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2784","text":"عشرة أشياء كثيرها كثير وقليلها كثير : النار والمرض العدو والدَّين الملح والفلفل الخمر والإهانة الظلم والكفر.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2785","text":"العالِم في قريته كالنبي في أُمته ، العالم في قومه كالبصير في العميان ، استرشدوا بعلمائكم ، فالشيء الذي لا يفعلونه لا تفعلوه ولا تواظبوا عليه ، مثل بعض التغريدات التي يلتزم بها العامة يوميا أو اسبوعيا أو في المناسبات ، ولا يفعل مثلها العلماء ، فموافقة العلماء في الفعل والترك ، أقرب صوابا وأكثر ثوابا.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2786","text":"لن تعرف أقوال شيخك الضعيفة والمرجوحة حتى تجالس من هو أعلم منه أو مكافئا له.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2787","text":"إذا جالست عالما واحدا فقد تميل للتقليد والتعصب لأقواله وآرائه . إذا جالست أكثر من عالم ؛ فسوف تقي نفسك من مغبة التقليد والتعصب لأقواله وآرائه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2788","text":"المشركون يطالبون أنبياءهم بالمعجزات حتى يعبدوا الله وحده ويدعوا عبادة الأصنام ، ثم يكذبون بالمعجزات ولا يطالبون آباءهم بالمعجزات حتى يعبدوا الأصنان بل يعبدونها من غير معجزات مع أن عبادتها منافية للعقل","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2789","text":"يجتهد البخيل في جمع المال ، ويحرص على عدم انفاقه ، ثم يموت ويتركه لورثته ، فهم يتمتعون به ، وهو يُسأل عنه من أين اكتسبه ؟ وهل أخرج زكاته وحقوقه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2790","text":"من يشرع بعمل مهم قبل سؤال المجربين يهدر الوقت والجهد والتموين","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2791","text":"من يقبل النصيحة يقي نفسه من الندم أو الخسارة أو الفضيحة ، ومن لا يقبل النصيحة يقع في الندم أو الخسارة أو الفضيحة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2792","text":"إن لم يحضر الأجل فينجو الإنسان من أعظم الأخطار ، وإن حضر الأجل فيهلك من أهون الأخطار.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2793","text":"الحرية ممارسات يومية مشروعة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2794","text":"من الظلم أن نحكم على الجيل بأنه فاشل ، إذا لم نُمهد لهم سبل العلم والنجاح.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2795","text":"الابتسامة عند اللقاء عنوان المحبة والوفاء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2796","text":"ابتسم فأنت لا تزال على قيد الحياة ، فيمكنك أن تتوب وتتصدق وتكون من الصالحين.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2797","text":"لو وَجَد المظلومون من يُنصفهم لتركوا التذمر والشكوى.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2798","text":"لا تقع في فخ الحب إلا إذا كنت تنوي الزواج بها.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m2799","text":"العبقرية أن تصنع من النفايات تحفة فنية لها قيمة مادية ومعنوية وأن تجعل من أسباب الفشل دافعا قويا لتحقيق النجاح والفلاح","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2800","text":"غياب الأصدقاء يزيد في الاشتياق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2801","text":"لا تُؤذ ضعيفا فإن له ربا يدافع عنه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2802","text":"لما جاوزت سن المراهقة اكتشفت أن انفعالاتي وقراراتي تسبق أفكاري وتجاربي ، فالبتدريج عدلت الترتيب.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2803","text":"السياقة فن وذوق وأدب واغتنام فرص وتفعيل المرايات والإشارات والتوافق في السرعة مع السيارات واحترام قوانين المرور في الطرقات","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2804","text":"بيوتكم نظيفة وشوارعكم وسواحلكم غير نظيفة ، مجتمع لا يبالي بنظافة المرافق العامة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2805","text":"المخدرات قد تُسعدك ساعة ، ولكن تُشقيك دهرا ويوم قيام الساعة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2806","text":"جروح الجلود تبرأ قبل جروح القلوب.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2807","text":"صهرك ستر وغطاء لبنتك ، فأكرمه واحترمه ، ليحفظ لك ذلك في إكرام بنتك ، ولا تخاشنه أو تحتقره فينعكس وبال ذلك على بنتك.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2808","text":"علينا أن نتسامح ونلتمس لبعضنا بعضا الأعذار ، فنحن لسنا ملائكة عليهم السلام.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2809","text":"قولكَ لزوجتك أنتِ نحفانة تعدل كلمة أحبك ثلاث مرات.","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2810","text":"إن كنت تقيا أحبك الله وجبريل والملائكة والمؤمنون ، ووضع لك القبول في الأرض.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2811","text":"مع الصالحين يصير مُرُّ الحياة حلوا ، ومع الطالحين يصير حلو الحياة مُرًّا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2812","text":"دروس الحياة تمنحك التجارب والخبرات ، ولا تُكلفك الواجبات والامتحانات والمصروفات.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2813","text":"المؤمن رغم أحزانه وجروحه يلقاك مبتسما متهللا متفائلا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2814","text":"إذا كثرت الأقوال طال الجدال وقلت الأفعال وخابت الآمال وساءت الأحوال وانعدم النوال ووقع الوبال.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2815","text":"مرحلة الشباب مرحلة الإفراط والتفريط ، والحماس والإندفاع ، والنشاط والشطاط ، فعند المناقشة معهم وسعوا بالكم ، وراعوا حالهم ، عندما تفرط من أحدهم الكلمة العوراء ، والزلة الشنعاء ، والنظرة الشزراء.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2816","text":"رفع معنوياتك بما تنجزه من الأعمال الممتازة ، والتي تجعل الناس يثنون عليها فتزيد من رفع معنوياتك.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2817","text":"المقهور يستريح بالبكاء ، والمظلوم يستريح بالدعاء ، والمسجون يستريح بالخروج إلى الفضاء ، والحزين يستريح بالنظر إلى الماء والحدائق الغناء ، والأزهار الصفراء والحمراء ، والزوجة الحسناء ، ذات العيون النجلاء ، والإبتسامة الغراء ، وحركات السحر والإغراء.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2818","text":"من كان متغافلا ، عن الزلات والتقصيرات والهفوات ؛ أطيب عشرة ، وأدوم صداقة ، ممن يعاتب على الزلات والتقصيرات والهفوات.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2819","text":"سقطت عمامة الشوكاني وهو يصلى فحملها فأعادها ، فقال رجل : هذه لم تعد صلاة ، هذا لعب ، فقال الشوكاني بعد أن سلَّم : حمل العمامة أهون من حمل أُمامة ، يشير لحديث حمل النبي صلى الله عليه وسلم أُمامة بنت ابنته زينب وهو يصلى","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2820","text":"إذا كنت منفعلا وفي حماس شديد ، فلا تكثر الكلام ، لأن اللسان سوف يسبق العقل ، فيتكلم بكلام يُوجب عليك الندم ، وذل الاعتذار ، والتنصل من القصد المباشر ، وإن كان مع الزوجة فيلزمك هدية سمينة ثمينة ، أو ساعة أو عقد ذهب من الصاغة ، وإلا فسوف تنام في الصالة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2821","text":"في بعض البلدان يسير السارق دون قلق ويكسب السياسي المال دون عرق وينام المسؤول الفاشل دون أرق ويغادر المختلس البلد دون فَرَق ويتولى المناصب من دون شهادات وورق وتُنجز المعاملات بالرشوة والملق ويأكل الفقير الرز دون مرق لأن القانون فيها حبر على ورق.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2822","text":"الأجداد يصنعون التاريخ ، والآباء يصنعون الحاضر ، والأبناء يصنعون المستقبل ، فأعدوا الأبناء بالتربية والعلم والأخلاق ، ليصنعوا مستقبل التقدم والإشراق.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2823","text":"من عرف قدر نفسه أحسن التصرف.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2824","text":"من وضع نفسه فوق قدره فقد أساء لغيره ، ومن وضعها دون قدره فقد أساء لنفسه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2825","text":"إذا تجافيتم فلا تقطعوا السلام والعيادة عند الأسقام.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2826","text":"إن الله خلقنا من التراب ، وسنعود إلى التراب ، فطوبى لمن استغفر وأناب وتاب.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2827","text":"اضربني ولا تضرب ولدي ، فضربي يقع على جلدي ، وضرب ولدي يقع على قلبي وكبدي.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2828","text":"الأحلام كباب والواقع عدس","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2829","text":"الحياة زينة وقصور نهايتها تراب وقبور.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2830","text":"الحكومات للأغنياء أُم رؤوم ، وللفقراء امرأة أب غشوم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2831","text":"أحلامنا فوق السحاب وشوارعنا تراب ومستقبلنا سراب","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2832","text":"نحن أحسن من غيرنا عبارة مقبولة من المواطن ، وغير مقبولة من المسؤول المقصر الذي يُبرر لتقصيره","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2833","text":"صلة الأرحام تزيد في أعمار وأرزاق الأنام","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2834","text":"إذا كان الهواء يملأ كل الفراغات ، فاملأ حياتك بذكر الله تعالى","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2835","text":"الإنسان يحب الحياة ، ويتشبث بها ، إذا جمع بين الصحة والمال ، والشباب والجمال.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2836","text":"الطيور التي تفقس في القفص لا تعرف معنى الحرية ، وترضى بالحياة خلف القضبان الحديدية.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2837","text":"لستَ محروما ما دُمت تسعى في طلب الرزق مستعينا بالله تعالى.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2838","text":"اطلبوا الحظ بغعل الخير والأخلاق الحميدة ، وبطلب العلم والثقافة ، وقراءة الكتب النافعة ، واستماع الكلام النافع.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2839","text":"الأغنياء أولاد الحكومة من الحُرَّة ، والفقراء أولاد الحكومة من الأَمَة","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2840","text":"تعامل مع من دونك بالصفات الإنسانية لا بالصفات الحيوانات الوحشية . وتعامل مع من فوقك بالصفات الإنسانية لا بصفات الصَّغار والدونية . وتعامل مع والديك بالتواضع وخفض الصوت والجناح ، لا بالخشونة والصياح.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2841","text":"كيف يتلقى المؤمن المصيبة ، بقوله : الحمد لله على كل حال، ويحدث نفسه بأن الصبر عند الصدمة الأولى ، وأن مصيبتي كانت في دنياي لا في ديني ، وأنها في بعض دنياي ، وأنها ليست في أعظم دنياي ، وأن الله سيصبرني ، وأنه سيُخلفني خيرا منها ، وسوف يُثيبني عليها أجرا عظيما في الآخرة. والمؤمن يستعين بالله على تحمل المصيبة ، ويستعين بالصبر والصلاة ، وقول : إنا لله وإنا إليه راجعون ، وكثرة الاستغفار ، ويتأسى بمصائب المرسلين والصالحين وجمال صبرهم ، ولا ينطوي ولا يختفي بل يُخالط الصالحين الذين يواسونه وبصبرونه ، ويحاول أن يشغل نفسه وتفكيره بما ينفعه.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2842","text":"العلم فضيلة والجهل رذيلة ، فاطلب العلم ما دمت حيا.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2843","text":"ابتسم وتفاءل فالحياة قصيرة.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2844","text":"تقربوا إلى الله بكثرة الذكر والاستغفار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2845","text":"الفقير غريب في وطنه، والغني مواطن في غربته.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2846","text":"إذا أردت أن ترتقي فسر ضد النهر ، لأنه يسير من الأعلى إلى الأسفل.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2847","text":"كن منصفا مع نفسك ، ومتفضلا مع غيرك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2848","text":"من الفطانة والكياسة ألا يتكلم الإنسان في غير تخصصه ؛ حتى يرجع إلى ما قاله علماء التخصص ، فليس من رجاحة العقل أن يخوض المرء في القرآن والحديث قبل أن يقرأ ما قاله المفسرون وشراح الحديث.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2849","text":"أنفع أصدقائي لي ؛ من دلني على كتاب نافع ، فقد نور عقلي ، وحسن طبعي ، وجود لساني.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2850","text":"خير هدية تقدمها لصديقك كتاب مفيد ، يدعو إلى لرشاد والسداد ونفع العباد.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2851","text":"حاول أن تكون في كل المواقف محترما ومهذبا ، في كلماتك وتصرفاتك ، فتكسب تقدير الناس واحترامهم وتأييدهم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2852","text":"يا أهل الإسلام يا أهل الخير والسلام ، احذروا الرسائل الشيطانية التي ينشرها أعداء الإسلام والإنسانية ، التي فيها التشكيك بالغيبيات والمسلمات ، فاحذروا مكرهم ، تأمنوا شرهم ، ولا تمنحوهم الأمان فيصيبكم الخسران ، ولا تُعيدوا نشرها فيستشري أمرها.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2853","text":"لا تُلغوا الاحتفالات المندوبات والمباحات ، بل ألغوا الإسراف والمبالغات، في جميع المناسبات ، فالاقتصاد والاعتدال في الاحتفالات والعادات ، أقرب إلى أحكام العقول وسنة الرسول ، والصلاة والسلام عليه موصول ، على مَرِّ العصور.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2854","text":"سعادتنا تكمن في إسعاد من يُعانون من الشقاء ، وشدة البلاء ، بسبب نقص الضروريات والحاجيات وغير ذلك ، كالفقراء والغرباء والضعفاء ، والأطفال وكبار السن ومن نزل بهم البلاء ، فالجزاء من جنس العمل ، فالخلق عيال الله ، فمن أسعدهم أسعده الله ، ومن شدد عليهم شدد الله عليه ، في الدنيا والآخرة وعند الموت.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2855","text":"أكثروا من زراعة وغرس الشتلات المعمرة والموافقة لأرضكم ومناخكم ، كالسدر والنخيل ، فإن فيها ثواب كثير ومستدام ، ويمكنكم أن تهبوا ثوابها لأحيائكم وأمواتكم ، وامنحوها بالمجان لتزداد حسناتكم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2856","text":"إن أعظم درس تأخذه من الحياة ، أن الله خلق الكون بقدرته ، وأمرك بعبادته ، لينعمك بجنته، برحمته لا بعملك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2857","text":"إسلوب الحديث الراقي يشجعك على مواصلة الحديث ، وإسلوب الحديث الواطي يجعلك تقطع الحديث.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2858","text":"المغامرات لا تخلو من المخاطرات ، وفيها إظهار للمهارات ، وليس فيها حسنات.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2859","text":"من طلب شيئا وجده ، ومن سار على الدرب وصل ، وما أراده حصل ، وبالمقاومة والمصابرة يكون النجاح ابن الفشل.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2860","text":"لا تستسلم لليأس أبدا ، فإن النجاح والفلاح مع الصبر والمقاومة.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2861","text":"من لم يسمع نصيحة والديه ، فسوف يندم ولو بعد حين ، لأنه ينظر إلى الواقع ، وهما ينظران إلى الواقع والمتوقع.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2862","text":"مفاهيم الإسلام ليست بالحماس والعاطفة والاندفاع ، بل بالفهم والتعقل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2863","text":"طلب الدنيا والرزق مقصد شرعي وعقلي وفطري ، ولا يلحق الذمُّ إلا من يُؤثر الدنيا على الآخرة فقط ، لا مجرد طلب الدنيا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2864","text":"نصيحة لكل متزوج لا تزعل زوجتك لأنك سوف تضطر لتقديم هدية بنصف معاشك.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m2865","text":"أول العمل فهم المراد ، فالفهم الصحيح يسبق العمل النجيح.","kind":"hikma","topic":"العقل والحكمة","note":"النجيح: الصواب والظفر وإدراك الغاية","source":"شذرات (ملف وورد)"},{"id":"m2866","text":"الأصل في العمران أن التوسع الأُفقي خير من التوسع العمودي ، ليأخذ حظه من الغبراء والخضراء والهواء والضياء والنظر إلى نجوم السماء ومد البصر إلى الآفاق ، والنفس تسعد وتميل إلى الفضاء ، وتُصاب بالضيق والشقاء من شدة الزحام والاختناق . أما التوسع العمودي فللحاجة ، من غير المبالغة في علوه وأبراجه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2867","text":"التربية أساسها الرحمة ووسيلتا الرفق وهدفها تحقيق القرب من الكمال","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2868","text":"المرأة لها أيام في كل شهر ، تكون متوترة ومزاجها غير رائق ، وتشعر بضيق ، وهذا لا يعكس شخصيتها الحقيقية ، وعلى بعلها أن بقدر الظرف ، ويمنح اللطف.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m2869","text":"ليس من طبيعة الإنسان أن يكون سعيدا في جميع الأوقات.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2870","text":"الحياة ليست عسلا دائما ، ولا حنظلا دائما ، فيها الحلو وفيها المر ، فعلى الإنسان أن يتأقلم ويتكييف.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2871","text":". تجدون السعادة الزوجية بكلمة السر السحرية ببطاقة السحب الآلية من البنوك المصرفية","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m2872","text":"من ألهمه الله التوبة لم يُحرم من القبول.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2873","text":"من ألهمه الله الاستغفار لم يُحرم من المغفرة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2874","text":"من أراد الله أن يرحمه ، وفقه لرحمة عباده ورحمة كل ذي كبد رطبة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2875","text":"من سأل الله الهداية من قلبه ، هداه الله من فضله ، ولو كان كافرا أو ملحدا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2876","text":"لو كانت المعصية جبرا لا اختيارا ، لكانت العقوبة ظلما لا عدلا ، لكنها كانت اختيارا فكانت العقوبة عدلا ، والتجاوز فضلا ، والله ذو الفضل العظيم ، ويعفو عن كثير.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2877","text":"مرض حلاق الملك ، فأحضروا حلاقا ، فأخبروه ليحلق لحاجبه أولا ، فلما فرغ أعطوه مكافأة مجزية وودعوه ، فقال : لم تُعجب الملك حلاقتي ، قالوا : أنت حلقت للملك ، فارتعب الحلاق ، فعلوا ذلك احتياطا لسلامة الملك ، وكذلك ليحلق وهو متمكن ، حتى يُحسن الحلاقة ، فلا يرتجف فيجرح الملك","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2878","text":"الرجل المؤدب يحترم الناس ولو كان يُعاني من مشكلة خاصة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2879","text":"إن صلحت نيتك فلا يضرك طعن الحاسدين.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2880","text":"لا تُحاسب صديقك على كلمة فرطت منه وهو غضبان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2881","text":"العلم كثير والعمر قصير ، فخذوا روحه ودعوا ظروفه ، وخذوا من قليله ما يُغنيكم عن كثيره ، وخذوا من كل فن أحسنه ، ومن كل باب أجوده ، العالم في قومه بالبصير في العميان ، والعالم في قريته كالنبي في أُمته ، وقروا علماءكم ، فإن في قلوبهم القرآن ، وفي صدورهم سنة النبي العدنان ، عليه الصلاة والسلام.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2882","text":"الشاب المستهتر الطايش ، إذا الله هداه ، ونور عقله بهداه ، ودرس العلم والفقه ، يصير دمه خفيفا ودروسه شيقة ، ويميل إلى التيسير ، ويبتعد عن التزمت والتعسير ، ويصير متواضعا ، وقريبا من الناس ، ولا يرى له فضلا عليهم ، طيب المعشر ، صالح المخبر.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2883","text":"لا يعرف معنى السعادة ، وطُمَأْنينة القلب ؛ من لم يذكر الله كثيرا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2884","text":"براهين الأفعال أصدق من براهين الأقوال.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2885","text":"الطَّيِّب يراك طَيِّبا فيُحب أن يُصادقك ، والشِّرِّير يراك طَيِّبا فيُحب أن يخدعك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2886","text":"قال : كنت أُصلي في الحرم المكي ، وبسبب الازدحام أراد أحد أن يمرّ من أمامي ، فمددت يدي لكي أمنعه ، فقبض على يدي ، وصافحني بحرارة !","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2887","text":"إن قلت لرجل : ما شاء الله ! نصف قومك كرماء سيسعد ، وإن قلت له: مع الأسف، نصف قومك بخلاء سيغضب ، فالمعنى واحد ، فعلى العاقل أن يختار التعبير الأنسب للمعنى ، والأفضل للبيان ، والأجمل في الآذان والجَنان.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2888","text":"إن كنت لا تُحب أن تعتذر ؛ فلماذا تُخطئ على غيرك ؟","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2889","text":"العُلبة الفارغة أكثر ضجيجا ، وكذلك الرأس الفارغ أكثر جعجعة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2890","text":"إذا أبى صديقك أن يسمو إلى مستوى آدابك ، فلا تنزل إلى مستوى آدابه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2891","text":"المال إذا استُعمل الاستعمال الصحيح في كسبه وإنفاقه ، وابتُغي به وجه الله ؛ فهو باب من أبواب الجنة ، ومفتاح من مفاتيحها.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2892","text":"عوِّد نفسك على التغافل ، ليس كل قول يستحق الرد.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2893","text":"أسرع طريق لإصلاح الصديق أن تُكافئ من أساء إليك بالإحسان إليه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2894","text":"لا تُكثر العتاب فيهجرك الأحباب والأصحاب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2895","text":"كثرة الاعتراضات تُفسد الصداقات.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2896","text":"كثرة العتاب تفرق الأحباب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2897","text":"كثرة الانتقادات تُوحش النفسيات.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2898","text":"رأى ملك أن أسنانه قد وقعت ، فطلب معبرا ، فقال له : سوف يموت أقاربك ، فتشاءم من قوله ، وأمر بإخراجه وألا يدخل عليه ، فطلبوا له معبرا آخر ، فقال له : أبشر بطول العمر : فاستنارت أسارير وجهه ، وأمر له بجائزة قيمة . فمآل المعنى واحد ، لكن التعبير عنه مختلف ، فعلى العاقل أن يختار ألفاظه بعناية ودراية","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2899","text":"تَوِّجْ أعمالك الصالحة بنهايات صالحة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2900","text":"من تجمَّل بالصبر نال عظيم الأجر.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2901","text":"من سامحك مرارا سوف لن يقبل منك اعتذارا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2902","text":"الخمول والكسل يجعل الأشياء السهلة صعبة ، ويجعل النفس تفقد النشاط والانشراح ، ويجلب البلادة والكآبة ، ويُعجل بظهور أمارات الشيخوخة المبكرة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2903","text":"السياسة أن تعرض المشاريع والخدمات والأمنيات ؛ التي سوف تحققها للشعب ، بطريقة التأكيد والجزم والحزم ، ثم وقت المحاسبة تقدم المبررات التي منعتك من تقديمها بطريقة اكثر تأكيدا وتبريرا وتملصا.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2904","text":"الأسنان عنوان الشباب لأن الشباب قوة ونشاط ، والقوة تحتاج إلى طاقة ، والطاقة تحتاج إلى الأكل ، والأكل يحتاج إلى الأسنان ، فبريق الاسنان وترتيلها ؛ كأنها حبات لُؤْلُؤٍ منظوم ، والعناية بها هو عنوان الشباب ، وناهيك عن اشراقة الابتسامة وما لها من القبول في القلوب والنفوس والعقول.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2905","text":"أُم وليد كانت تحرص على استماع أخبار س٩ م في التلفاز ، تنتظر فقط آخر الأخبار ( انتقل إلى رحمة الله ) في يوم لم يذكروا من مات ، فقالت : اليوم ما في انتقل ! ثم بعد عمر وضعوها في أخبار انتقل !","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2906","text":"كم مرة يسمع الإنسان : انتقل … ثم يأتيه الدور ، فيكون هو انتقل!","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2907","text":"الطرق الممهدة المستقيمة ، لا تُكسب السائق المهارة والجدارة ، وكذلك الحياة السهلة الناعمة ، لا تُكسب الإنسان الخبرة والعبرة ، والفهامة والنباهة في شؤون الحياة وتقلباتها.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2908","text":"نحن نعيش في عصر اختلطت فيه التفاهة بالثقافة ، والنفاق بالسياسة ، والرشوة بالهدية ، والغش بالشطارة ، والفجور بالفن ، والإلحاد بالحرية الشخصية ، والخمور بالمشروبات الروحية ، وتزوير الشهادات العلمية للحصول على المراتب الاجتماعية.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m2909","text":"قال : رأيت رجلا يطوف وهو يستر وجهه ، فسألته عن سبب ذلك ، فقال : أنا أحج عن أُمي !","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2910","text":"إذا تَجادل وتَخاصم رجل وامرأة ، فلا يعلم من حضر أيهما الظالم وأيهما المظلوم ، حتى تبكي المرأة ، فيشعرون بأن المرأة مظلومة والرجل ظالم.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m2911","text":"إذا بكت المرأة فالحق معها عند أكثر من حضر.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2912","text":"دموع المرأة تشهد على صدقها عند أكثر الناس.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2913","text":"القاضي المُحَنَّك لا يعتد بدموع المرأة ، لأنه يقضي بالحقائق لا بالمشاعر.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2914","text":"حسن التدبير يُوفر عليك المال والجهد والوقت : فالبضاعة التي ستنقلها بعد شهر ضعها في آخر المخزن ، والتي ستنقلها بعد يومين ضعها في أول المخزن.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2915","text":"قل لي ماذا تأكل ؟ أقل لك من أنت ، فتأثير الغذاء على المُتغذي واضح.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2916","text":"وراء كل رجل عظيم تربية عظيمة.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2917","text":"حب الأم عاطفة ثم تربية ، وحب الأب تربية ثم عاطفة.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m2918","text":"لماذا تحفر عيوب الناس على النحاس ، وتكتب فضائلهم على قرطاس بقلم رصاص.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2919","text":"العرب في الجاهلية يتصفوة بمكارم الأخلاق : الشهامة والمروءة والسخاء والنجدة وحسن الجوار والشجاعة وإكرام الضيف وإغاثة الملهوف والتفريج عن المنكوب ، وفك العاني ، ولا شك أن في بعضهم صفات رديئة ، شأنهم كشأن أي مجتمع.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2920","text":"الإدمان على أكل ذي الناب والمخلب من الوحوش والجوارح يورث الوحشية والشراسة في الطباع ، فالشارع الحكيم حرمهما.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2921","text":"أكل الخبائث من الحشرات والمحَقَّرات يورث الدناءة والخسة في الطباع ، فحرمها الشارع.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2922","text":"الشارع الحكيم أحل أكل الطيبات وحرم أكل الخبائث ، لتأثيرهما الإيجابي والسلبي ، على صحة الأبدان ، وطبع الإنسان.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2923","text":"إذا قال لك صديقك المخلص : أُحبك مثل أخي ، فتذكر يوسف وبنيامين عليهما السلام . وإن قال لك جليسك المخادع : أُحبك مثل أخي ، فتذكر قابيل وهابيل.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2924","text":"أحسن ظنك بالناس واحترس منهم ، ولا تثق بأحد قبل التجربة ، ولا تنخدع بالمشاعر ، والانطباعات الأولية.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2925","text":"اصقلوا عقولكم بقراءة الكتب الجيدة المفيدة ، التي توسع مدارككم ، وتنمي فيكم المعرفة والخبرة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2926","text":"من اخترع الطائرة كان مبتكرا متفائلا ، ومن اخترع المظلة كان حريصا حازما.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2927","text":"ما زلت أتعلم من أخطائي الصواب ، فالصواب ابن الخطأ.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2928","text":"الأشرار ليسوا أقوى من الأخيار ، لكن صمت الأخيار جرأ الأشرار ، وجعل منهم أقوياء.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2929","text":"نوم الليل يُعين على نشاط النهار ، ونشاط النهار يُعين على نوم الليل ، فالنوم ليس وقتا ضائعا بل هو وقتا إيجابيا.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2930","text":"من يفعل الخير يرجو ثواب الله ، ويدع الشر خوفا من عقاب الله فهو مؤمن.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2931","text":"إذا ارتقى الإمام المنبر ، والتفت إلى المصلين ، بوجه عابس يابس آيس ، ونطح الخُطبة بقول : ( قل اللهم مالك الملك ، تؤتى الملك من تشاء ، وتنزع الملك ممن تشاء) فتوقع أن هذه آخر خُطبة ، وأن الوزارة قد أنهت خدماته","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2932","text":"الجود صابون العيوب","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2933","text":"الستر زينة النصيحة","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2934","text":"الذنوب داء ودواؤها الاستغفار الكبائر دواؤها التوبة الذنوب المتعلقة بالعباد دواؤها رد الحقوق وطلب العفو والاستغفار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2935","text":"أفضل علاج لمن يُحاول استفزازك التجاهل.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2936","text":"الإنسان العاقل صنع أسلحة فتاكة ليقتل بها بني جنسه ، لكن الحيوان غير العاقل لم يصنع أسلحة ليقتل بها بني جنسه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2937","text":"التعليم المدرسي يضمن لك راتبا ، أما التعليم الذاتي فسيجعل منك عبقريا.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2938","text":"قبل أن أُخالط الناس كنت أثق في نفسي ، فلما خالطت الناس أصبحت أثق في نفسي أكثر.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2939","text":"قبل أن أقرأ سورة يوسف كنت أُحسن الظن بالناس ، فلما قرأت قصة يوسف عليه السلام ؛ أصبحت أُحسن الظن بالناس ، لكن أحترس منهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2940","text":"كنت أُعايش أقاربي بالمحاققة والمماثلة ، فلما قرأت قصة نبي الله يوسف عليه السلام مع أخوته ، أدركت أن الله يُريد منا أن نعايش أقاربنا بالمسامحة والمحاسنة ، لا بالمحاققة والمماثلة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2941","text":"اقرأ مرة لتَفهم اقرأ مرتين لتُفهم اقرأ ثلاث مرات لتكتب اقرأ أربع مرات لتُناظر اقرأ خمس مرات لتحفظ اقرأ سِتَّ مرات لتُثَبِّت","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2942","text":"ثراء مُفاجئ مجهول المصدر شبهة قوية في أن يكون مصدره : - غسيل أموال - اختلاس أموال - عمولات صفقات - تهريب حشيش - تهريب خمور - تهريب سلاح - موافقات سياسية لمصلحة خاصة . - جاسوسية - رشوة - تزوير - وغيرها","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2943","text":"قال : رأيت رجلا يطوف ويدعو لأُمه فقط ، فسألته : لماذا لا تدعو لأبيك ، فقال : أُمي ضعيفة فأدعو لها ؛ لكن أبي رجل يُدبر أمر نفسه !","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2944","text":"خمسة من الأفضل أن لا تُصادقهم : من شره أقرب من نفعه من يشين سُمعتك من لا يبذل الندى ولا يكف الأذى من هو سريع الغضب بطيء الفيء من الذي كثير التلون متقلب المزاج","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2945","text":"يجب على كل دولة أن تراعي حقوق الوافدين ، وتعاملهم باحترام ، كما تُحب من الدول الأُخرى أن تُراعي حقوق مواطنيها وتعاملهم باحترام.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2946","text":"خير الجيران من بذل الندى وكف الأذى ، وشر الجيران من كف الندى وبذل الأذى.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2947","text":"الدعاء للجار، المشاكس، اللهم أسعدهم وأبعدهم ، وارزقهم جيرانا خير من جيرانهم ، وارزقنا جيرانا خيرا منهم","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2948","text":"الخسران المبين : الضلال بعد الهداية الإلحاد بعد التوحيد الكفران بعد الإيمان ثم سفك دماء الأبرياء","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2949","text":"وعد زملاءه بوليمة على الخروف الذي في حديقته ، عند نجاح ابنه ، فلما خرجت النتيحة سألوه عن نتيجة ابنه ، فقال : الخروف نجح","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2950","text":"غياب الأمن يصنع المجرمين ، وغياب العدل يصنع الظالمين.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2951","text":"مدرجات الجامعة تُنمي العقول ، ومدرجات الكرة تحشد الجمهور.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m2952","text":"قبل أن تُحدث الجائع عن المبادئ املأ بطنه أولا.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m2953","text":"عليكم بالرأي الخمير وإياكم والرأي الفطير ، ولا تتخذوا الرأي الخطير إلا بعد نومة وتفكير ، ومشاورة وتدبير ، وسؤال الناصح الخبير . فما أكثر حالات الطلاق التي تقع بناء على ردود الأفعال المتسرعة ، وكذلك ما أكثر الأفعال والمواقف السلبية التي تقع بناء على ردود أفعال متسرعة وغير مدروسة بعناية.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2954","text":"قال : رأيت رجلا يطوف ويدعو لأبيه فقط ، فقلت له : لماذا لا تدعو لأُمك ؟ قال هي ليست من قومنا","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2955","text":"من سُئلت بعد اسبوعها الأول من الزواج ، فصمتت ثم تنهدت ثم نظرت إلى السقف ، ولمعت عيناها من الدموع ، فقالت : كأني استعجلت ، فكأنما قالت : أنا تعيسة ، وحظي مائل، كأنه إشارة مرور ، أو عمود نور ، صدمه شاب أرعن متهور مغرور","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2956","text":"الخمر أم الكبائر ومفتاح المعاصي","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2957","text":"من جلس يذق الخمر ، ومن يذقها يشربها ، ومن يشربها يُدمن عليها ، ومن يُدمن عليها يخسر عقله ، ومن يخسر عقله يخسر كل شيء.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m2958","text":"الزراعة تُوفر لك الغذاء والدواء والكساء ، والصناعة تُوفر الاحتياجات والأدوات ، والتربية تصنع الآداب والأخلاق ، والتعليم يُنمي العقول والمدارك ، والإسلام يضمن لك العزة في الدنيا، والفوز بالجنة والنجاة من النار في الآخرة","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2959","text":"الفقر ليس عيبا إلا إذا كان بسبب الخمول والكسل.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2960","text":"الغنى إذا اقترن بالجود والتواضع والصدقات فهو فضيلة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2961","text":"الغنى إذا اقترن بالتبذير أو البخل والتباهي على الفقراء فهو عيبا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2962","text":"باب النجار مخلع.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2963","text":"الإسكافي يلبس حذاء مقطوعا.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2964","text":"الخَزَّاف يأكل في طبق مكسور.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2965","text":"طبيب الأمراض الجلدية أصلع.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2966","text":"خياط تزوج خياطة فرحهم القميص الجاي","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2967","text":"قال الأسد للحمار : ليه جاي فرحي ! قال الحمار : أنا كنت قبل الزواج أسدا","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2968","text":"طلب أبوها مهرا كبيرا قال الخاطب : ليه ! هو الكيلو بكم ؟","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2969","text":"ما اتصلح الشباك علشان جارنا ما يشوفني ، خليه يشوفك علشان اصلحه على حسابه","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2970","text":"أي شيء تريده من الناس بادر بفعله لهم","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2971","text":"عندما تراعي حق المتكلم ، وتستمع إليه باهتمام ، وهو يقص عليك قصة طويلة ، ليس لها رأس ولا ذنب ، ولا عبارات جميلة ولا أدب ، وناهيك لو كنت سامعها ، فقد تحملت حملا ثقيلا على نفسك ، وهذا يدل على حسن أدبك ، وجمال طبعك ،وروعة مشاعرك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2972","text":"لاحظ السُجناء أن واحدا منهم يُعامله السَّجَّان بشيء من الرفق واللين ، وكان السبب أنه إذا أرسل رسالة إلى أهله ، يذكر في آخرها ، أن السجَّان يُعامله معاملة حسنة ، لأنه يعلم أن السجَّان يقرأ رسالته ، بخلاف السُجَناء فإنهم يكتبون الذم والقدح في السَّجَّانين","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2973","text":"إذا لم تخسر نفسك فأنت رابح.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2974","text":"حافظ على سمعتك فإنها منزلتك عند الناس.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2975","text":"تُحب المرأة بأُذنيها ثم بقلبها. يُحب الرجل بعينيه ثم بقلبه.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m2976","text":"عندما فكر الشاب في الزواج ، شرع يهتم بنظافته وصحته وأناقته وهندامة ، واختيار كلماته ، ويتردد على عيادة الأسنان ، واشترك في نادي رياضي ، فطلب من المدرب أن يُرشده إلى التمارين التي تحسن من منظره ، لأنه في صدد الزواج ، وينشد السعادة الزوجية . فأخذ المدرب بيده ، وخرج به من النادي ، إلى أن ذهب إلى جهاز سحب آلي قريب ، فوضع يده عليه ، وهو يقول : من هنا تنبع السعادة الزوجية ، افتح يديك لزوجتك وأُمها ، فسوف تنزل عليك السعادة الزوجية ، نزول المطر على الأشجار والخضر","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2977","text":"بعض الناس يدخلون في حياتنا ، وبعض الناس ندخل في حياتهم ، فكن إيجابيا في الحالتين : انفع غيرك وانتفع من غيرك ، فخير الناس أنفعهم للناس ، وأعقل الناس أكثرهم انتفاعا من علم الناس وخبرتهم وتجاربهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m2978","text":"من يستطيع أن يجمع ست كلمات في كلمتين ؟ ازعاج - صراخ - أوامر تحكمات-نصايح-عتاب . الزوج متقاعد","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2979","text":"الإبداع من العبقرية ، والعبقرية من قوة الذكاء ، والذكاء من الشغف في المعرفة وكثرة القراءة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2980","text":"الضمير الحي حارس أمين ، والتوكل على الله من قوة اليقين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2981","text":"أمارة الذكاء أن تدع مالا يعنيك ، وتشتغل بما يعنيك.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2982","text":"س : متى يصبح شعر الزوجة فضيا ؟ ج : عندما يتقاعد الزوج","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2983","text":"سأل المدرس الطالب : دجاجة تبيض كل يوم بيضة ، في الأسبوع كم بيضة تبيض ؟ الطالب : تبيض خمس بيضات . المدرس : لماذا ؟ الطالب : لأن الجمعة والسبت عطلة الراحة","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2984","text":"لا تشتط فتقع في الشط مع النورس والبط","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2985","text":"ما ضاع من مالك ما أنفقته في سعادة عيالك وأُم عيالك","kind":"hikma","topic":"المال والاقتصاد","note":"بعنوان: العيدية","source":"شذرات (ملف وورد)"},{"id":"m2986","text":"حديث الناس مع الناس مطلقا ، خير من حديث الناس مع الناس عن عيوب الناس.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2987","text":"إذا شرع الإنسان في الحديث عن نفسه أو عدوه ؛ قد لا يسلم من الكذب وتهويل القليل ، والمبالغة في اليسير.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m2988","text":"إذا كان الحديث عن نماء المال ؛ وطريقة كسبه وربحه ، فجميع الناس على ملة واحدة في الاهتمام والانصات.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m2989","text":"من السعادة أن يكون لك أهداف نافعة تهواها تسعى لتحقيقها.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m2990","text":"إذا بلغتك هفوة عن أحد فاسترها ولا تتفوه بها.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2991","text":"خُلقت الدنيا للفناء ، وخُلقت الآخرة للبقاء ، فاصنع في فنائك ما ينفعك في بقائك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2992","text":"قال رجل هندي لزملائه : أنا تعلمت اللغة العربية في يوم واحد : فجحظت عيونهم ! كيف ذلك ؟ قال قعدت عند باب الحرم ، فكل من يمر عليَّ أحفظ منه ما يقول ، فقالوا له قل ما حفظته : فقال : افسح ، وسع ، تأخر ، اجتنب ، انقشع ، فارق ، ارحل ، قم ، انزح ، رح ، ابتعد ، انطلق … فقالوا : لا تُكمل ، هذه كلها مترادفات لمعنى كلمة واحدة ، تعجب فقال : هذه لغة غنية وثرية","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m2993","text":"المؤمن صبور ، يتألم ولا يشتكي ولا يتكلم.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2994","text":"المؤمن يبتسم للقريب والبعيد ، وفي طيات نفسه حزن شديد.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m2995","text":"التسامح من أفضل أخلاق الرجال.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2996","text":"العنصرية موجودة في بعض البشرية في كل المجتمعات الإنسانية ، وهي من الصفات الدنية.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m2997","text":"من أعجب العجب أنك ترى جميع وجوه الناس كفاحا ومواجهة ، وترى وجه البقرة والقِطة ، ووجه العنز والبطة ، ولا تستطيع أن ترى وجهك كفاحا ومواجهة ، ولو مرة واحدة في حياتك.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m2998","text":"إن الله قد وهبكم السمع والفؤاد والأبصار والعضلات من غير دعوات وأنتم في الظلمات فاشكروا رب الأرض والسموات","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m2999","text":"يقول الكريم : يفنى ما في القدور ويبقى ما في الصدور.","kind":"mathal","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3000","text":"ظَلِّمْ عليها تُنور عليك.","kind":"mathal","topic":"المال والاقتصاد","note":"يقوله البخيل، يعني: خَبِّئْ الأموال. له صيغة أخرى","source":"شذرات (ملف وورد)"},{"id":"m3001","text":"يأكل من عشبة التراب ولا يقف ذليلا عند الباب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3002","text":"العاقل يهدم قصرا ليبني مِصرا ، والجاهل يهدم مِصرا ليبني قصرا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3003","text":"نصيحة المخادع نصيحة القِط للفأر.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3004","text":"إذا ذهبت لخِطبة البكر الحسناء ، فضع على لسانك تمرة صفراء.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3005","text":"احرص على اختيار قرينك ، فهو عنوان أخلاقك ودينك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3006","text":"كُفَّ لسانك ، ولا تتمضض بذكر عيوب الناس.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3007","text":"يوم السفر يعدل نصف السفر لتزاحم الأشغال.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3008","text":"قلم رصاص مكسور وخطه باهت، خير من ذاكرة قوية ، ضع معك دائما قلما وورقة ، لتكتب بها الأفكار الإيجابية ، والإيحاءات النورانية ، وكل ما يخطر ببالك شيء مما يتعلق بدراستك أو تجهيزاتك للسفر ، أو غير ذلك ، سجله حتى لا تنساه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3009","text":"لا يخرج من الصندوق إلا ما كان فيه ، ولا يخرج من قلب المرء على لسانه إلا ما كان فيه.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3010","text":"إذا أكثر الكلب النباح ، صار نباحه لا معنى له . وإذا أكثر الرجل الوعود والأقوال ولم يُصدقها بالوفاء والأفعال ؛ كانت وعوده لا معنى لها ، وصار مثل الحكومات الفاشلة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3011","text":"لو كانت الرجولة بنكارة الصوت وخشونته لكان الحمار هو الأرجل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3012","text":"فأر يتجول في السقف ، وقِط يراقبه في الأرض ، فسقط الفأر فتلقاه القِط بيديه ، قائلا : بسم الله عليك ، فقال الفأر : دعك من هذا ، إذا عافاني الله منك فأنا بخير !! وهذه هي صفة المنافق والمخادع والمستعمر ؛ يُسمعك كلاما معسولا وهو ينوي القضاء عليك ، أو الإضرار بك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3013","text":"الحادث الذي تسيل فيه الدماء لا تنبت فيه شجيرات النسيان.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m3014","text":"الفقر ليس عيبا لكن يجب عدم اظهاره.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3015","text":"التخطيط الجيد يقلل من التكاليف ، ويقرب الأهداف.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3016","text":"رجل قدم العزاء ، ثم جلس قليلا ، ثم نهض وأثناء خروجه قال : أحسنُ عزاءٍ عزاؤُكم ، بدل : أحسنَ اللهُ عزاءَكم فحاول الجميع أن يُخفوا ابتسامتهم ويكتموا قهقهتهم","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3017","text":"لا تُناقش غبيا حتى لا يلتبس على الناس أيكما الغبي.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3018","text":"الحياة لا تخلو من الابتلاء ، فوطن نفسك على الصبر.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m3019","text":"ليس من الضروري أن يكون كلامك مقبولا عند الجميع ، لكن من الضروري أن يكون حقا لا باطلا.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3020","text":"من الظلم أن تُساعد الظالم على ظلم المظلوم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3021","text":"من قال إنه قد وصل فقد قتل الطموح ، وترك السعي والاجتهاد.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3022","text":"الأرض تحيا بعرق الرجال ، وتموت بدماء الرجال.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3023","text":"لا تفتش عن عيوب الناس ، فتكون كالذبابة التي لا تقع إلا على القاذورات ، ولكن انظر إلى فضائل الناس ، فكن كالنحلة التي لا تقع إلا على الزهرات.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3024","text":"الجمال يسحر العيون ، والأخلاق تجذب القلوب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3025","text":"إذا قابلنا الإساءة بالإساءة تحولت إلى مشاجرة وخناقة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3026","text":"إن طلبت الكمال سوف تكون أفضل ؛ ولو لم تصل إلى الكمال.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3027","text":"الناس يُعجبهم الثناء ، بحق أو بباطل. ولا يعجبهم الذم بحق أو بباطل.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3028","text":"امدح علنا وانصح سرا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3029","text":"لا تُسقط التكليف في الاجتماعات ، ولا تُكثر التكليف في النزهات.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3030","text":"ابن آدم لا يستطيع أن يقاوم القدر ، لكن يستطيع أن ينهض من جديد ليُعيد الأمجاد.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m3031","text":"حركوا القدر بتغيير ما بأنفسكم.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3032","text":"كن كالمطر أينما وقع نفع","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3033","text":"الماء قرين الغذاء والهواء","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3034","text":"كن مع الناس معتدلا بين الإفراط والتفريط ، مثل الملح في الطعام ، قليله يصلح الطعام ، ويزيد في لذته ، وكثيره يفسد الطعام ويسبب الضغط.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3035","text":"الناس ترسم صورة عنك من خلال أفعالك وأقوالك ، لا من خلال نواياك وأحلامك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3036","text":"جمع المال مثل شرب ماء البحر ، كلما شربت منه ازداد عطشك.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3037","text":"خذ العبرة من الماضي لتحقق النجاح في المستقل ، لا لتطيل الندم عليه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3038","text":"من المهم أن تعيش سعيدا، ومن الأهم أن تعيش شريفا، ومن أعظم الأهم أن تموت مسلما.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3039","text":"يلزمك أن تستمع باهتمام ، ولا يلزمك أن تُصدق كل الكلام.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3040","text":"إذا كنت تقدم خدمات للناس مجانا ؛ فأنت رجل طيب المعدِن.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3041","text":"قال للطبيب النفسي : كل ليلة أرى في المنام أن الحمير يلعبون كرة قدم ! قال الطبيب : جرب الليلة لا تنم . قال : لا أقدر الليلة بالخصوص ! قال له لماذا : قال : الليلة المباراة النهائية للدوري !","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3042","text":"كن مع نفسك ومع الناس معتدلا متوازنا ، في أُمور دينك ودنياك ، لا إفراط ولا تفريط ، مثل الفلفل في الطعام ، قليله يُصلح الطعام ، ويزيد في لذته ، ويفتح النَّفْس ، وكثيره يُفسد الطعام ، ويحرق الحلق ، ويجلب المَغَص.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3043","text":"من حسن التدبير ووصايا العقل الكبير أن نتخذ الاحترازات ونوقف الزيارات حتى تتبين الأمور وتبتعد الشرور وتنشرح الصدور وتذهب الهموم ويُقبل السرور والحبور","kind":"hikma","topic":"الصحة والنفس","note":"بعنوان: وباء الكورونا","source":"شذرات (ملف وورد)"},{"id":"m3044","text":"الاعتذار يجبر الانكسار.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3045","text":"الاستغفار شعار الأبرار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3046","text":"التواضع خير من الاستكبار.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3047","text":"الاعتذار خير من الإنكار.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3048","text":"الثبات خير من الفرار.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m3049","text":"التخلي عن الخطأ خير من الإصرار.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3050","text":"السلام عمار والحرب دمار.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3051","text":"التفرق هزيمة والتآلف انتصار.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3052","text":"السفر مراحل والجنين أطوار.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3053","text":"إن ظلمك أحد في نفسك أو مالك أو حلالك أو عيالك ، وأنت لا تستطيع أن تنتصف منه ، فلا تبالغ في الأحزان ، فتُتعب نفسك والجَنان ، فينعكس على العقل والأعضاء والأركان ، فإنك يوم القيامة سوف تأخد من حسناته ، وتضع عليه من سيئاتك ، بقدر مظلمته لك ، فأنت الرابح وهو الخسران ، وهو أولى منك بالأحزان ، والنقصان","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m3054","text":"لا تكن مع أهلك حامضا ومع أصدقائك حلوا ، ولكن كن مع أصدقائك حلوا ، وكن مع أهلك حلوا عسلا. أو على الأقل مربة تين.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3055","text":"لا يُوجد في الطبيعة قانون الجهود المهدورة ، ولكن الطبيعة مخلوقة ومبنية على قانون : ( الحكمة البالغة ) قد يبدو لبادي الرأي أنها جهود مهدورة ، لكن في حقيقة الأمر ، تحكمها قوانين دقيقة صارمة ، قوانين التكامل والتبادل الإيجابي ، والتقديرات والموزونات لضمان البقاء والاستمرار والانتخاب والجودة. فالجهود المهدورة في الأعمال البشرية ، لا في المخلوقات الربانية.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3056","text":"الإنسان يعرف الأشياء التي حوله أكثر مما يعرف عيوبه التي فيه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3057","text":"كن متغافلا فالمتغافلون أكثر سعادة من المدققين.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3058","text":"لن تعرف أصدقاءك إلا في الأوقات الصعبة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3059","text":"الاعتذار الودي أفضل من الموافقة من غير رغبة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3060","text":"اللين قوة الأقوياء والقسوة قوة الجبناء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3061","text":"سألت صاحب المكتبة عن كتاب ( الزوجان المثاليان ) قلت له : لم أجده في قسم الأسرة ، فقال : تجده في القسم الثامن ( كتب الخيال العلمي )","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3062","text":"أول الحزم المشورة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3063","text":"العتاب قبل العقاب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3064","text":"كثرة العتاب تفرق الأصحاب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3065","text":"لا تقل همومي عظيمة ولكن قل رحمة ربي عظيمة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3066","text":"تغيير الطباع لا يُستطاع.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3067","text":"إبرام الرأي يحتاج إلى العقل ، والعقل يحتاج إلى المشاورة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3068","text":"تجارب الكبار تُنير الطريق للصغار.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3069","text":"العقول مواهب والعلوم مكاسب.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3070","text":"يوم بدون ابتسامات يوم طويل. يوم فيه سعادة يوم قصير.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3071","text":"جمالك في أخلاقك فحافظ عليها.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3072","text":"الذهب الخالص لا تتغير قيمته وإن كان قديما أو مستعملا. قلب المؤمن كالذهب الخالص لا يتغير.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3073","text":"من اليسير أن تحرق الصور والرسائل ، لكن من العسير أن تحذفها من الذاكرة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3074","text":"من شاور الرجال شاركها في عقولها ، واستفاد من تجاربها ، من غير معاناة ومجهود.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3075","text":"إذا أردت أن تستمر الحياة الزوجية تحت مظلة المودة والتفاهم والتعاون ، فعليك أن تغض الطرف عن الهفوات والزلات والجهالات ، ولا تُكثر اللوم والذم والعتاب ، ولا تُغلق أبواب التسامح ، ولا تفتح أبواب الجدال والتعاتب ، واعلم أن الزوجة تُفضل الحب المعلن بالإعجاب والهدايا ، على الحب المستور في الصدور.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3076","text":"إذا كان في الثقة انكسار ؛ فلا ينفع الاعتذار.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3077","text":"الثقة كالقارورة إذا انكسرت انعدمت.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3078","text":"لا بديل عن الأم فحافط على برها وحبها والدعاء لها.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3079","text":"من لم يتعظ بالواعظ الناطق : القرآن والواعظ الصامت : الموت ، فلا واعظ له.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3080","text":"الوتساب سوق واقف فيه الأصلي والزائف الوتساب سوق الجمعة فيه الزهرة والبعرة الوتساب معرض فيه الإشاعات والتحقيقات","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3081","text":"شريحة من المتقاعدين يقضي ما بقي من حياته يتجول بين المستشفيات والمستوصفات والعيادات الخاصة ، والصيدليات ، والوصفات الشعبية ، والسفر للعلاج ، الله يرحم حالهم ، هؤلاء يكفر الله سيئاتهم بمرضهم ، ويضاعف حسناتهم بصبرهم وحمدهم وشكرهم ، فهؤلاء يُرجى لهم ، أنهم يرجعون إلى ربهم ؛ كالطبق الأبيض المغسول بالماء الحار والصابون ، ليس عليهم سيئات ولا تبعات.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m3082","text":"اتصل الحارس بسيده وقال له : لا تُسافر اليوم ، لأنى رأيت البارحة في المنام أن الطائرة سوف تقع ، فألغى رحلته ، ثم جاءت الأخبار بسقوط الطائرة ، فحمدالله ، ثم شكر حارسه وقدم له مكافأة جزلة ، ثم أنهى خدمته . س : لماذا أنهى خدمته ؟","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3083","text":"لا ينجح مجلس الأمة إلا بثلاثة شروط : انتخابات نزيهة ، وأعضاء نُزهاء ، وأعضاء أكفاء.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3084","text":"تعيش بعض الدول في عصر الرخاء والطاقة ، وتعيش بعض الدول في عصر النزاعات والفاقة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3085","text":"إذا مات القانون أصبح الفقراء والضعفاء والغرباء أيتاما.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3086","text":"مشاكل الشعوب ليست في عدم وجود الحلول ، ولكن في عدم رغبة الحكومات الحقيقة في حل مشاكل شعوبها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3087","text":"لا تضع بين أيامك ورقة كربون ، حاول أن تعمل شيئا جديدا ، لتكتسب خبرات ، وتزداد معلومات.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3088","text":"لا تجعلوا أمجادكم التليدة تصرفكم عن التقدم في ركب الحضارات الجديدة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3089","text":"لا تصدق كل الأخبار السياسية ، فإنها لا تخلو من المراوغات والمزايدات والزخرفات.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3090","text":"الفقر الاضطراري ليس عيبا ، لكن الفقر الاختياري بسبب الخمول والكسل عيب شنيع ، لأنه يظلم نفسه ومن يعول.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3091","text":"نهضة الدولة مرهونة بالتشكيل الوزاري ، إذا كان أعضاؤه تتوافر فيهم القوة والكفاءة والأمانة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3092","text":"من حقوق الوافد ألا يتم إهانته أو احتقاره أو مخاشنته.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3093","text":"إذا أردت أن تجتهد في الإصلاح والتغيير ؛ فعليك أن تتجافى عن الكسل والسرير.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3094","text":"إذا كان المسؤول جُزءاً من المُشكلة ؛ فكيف يُوكل إليه بحل المُشكلة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3095","text":"السياسة هي التغيير إلى الأفضل ، فتحتاج إلى طول البال وسعة الصدر.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3096","text":"رجل خليجي عَلَّم رجلا أجنبيا عمليا ، كيف يفحص البِطيخة ( الرقية ) بواسطة الطَبْطَبَة عليها قبل اختيارها ، فتعجب من مهارته ، فقال له : لماذا لا تُطبطبون على المسؤولين عندكم قبل اختيارهم ، فقال له : ما يصلح ، لأن البِطيخة تُخبرك بالحقيقة من غير خداع ولامراوغة ولا تزوير","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3097","text":"بعض المأكولات والمشروبات حلاوتها بحرارتها ، وبعضها ببرودتها ، وبعضها بطبيعتها . مع ملاحظة اختلاف عادات الشعوب ، وكذلك اختلاف الأذواق ، وليس من الذوق مناقشة الذوق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3098","text":"إن كنت نزيها ؛ فلن تستغني سريعا ، ولو تبوأت منصبا رفيعا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3099","text":"يجب عليك أن تحترم رأي صديقك ، لكن لا يجب عليك أن تقتنع به.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3100","text":"لكي تكون حكيما يجب عليك أن تقرأ كثيرا الكتب النافعة ، وتسمع كثيرا الكلام النافع ، فهذه بداية الحكمة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3101","text":"الوقاية هي الدرع الأول للمحافظة على الصحة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3102","text":"النظافة شطر الوقاية.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3103","text":"عيادة المريض تُذكرك بنعمة الصحة المنسية.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3104","text":"التواضع ثمرة الأخلاق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3105","text":"التواضع يؤلف بين طبقات المجتمع.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3106","text":"التواضع دليل الثقة بالنفس.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3107","text":"المرض قيد، والصحة انطلاق وحرية.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3108","text":"مع القناعة البيضة دجاجة ، واللبن لحمة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3109","text":"من أكثر من الطعام جلب لنفسه الأسقام.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3110","text":"فن السياسة المعاصرة القدرة على التملص من الوعود والمواثيق بطريقة مهذبة ولبقة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3111","text":"تعاليم الدين تعصم الإنسان من الخطأ ، فإذا فصَلْنا الدين عن أي شيء فقد عرضناه للتخبط والخطأ.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3112","text":"أصبحت لغة السياسة أن تعرض الباطل في صورة الحق ، والظلم في صورة العدل ، وتحاول أن تُقنع الناس.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3113","text":"لذة الحياة مرهونة بالصحة والشباب.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3114","text":"الدعاء والتفاؤل بالشفاء يُعينان مع الدواء على الشفاء.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3115","text":"مع الصحة تشعر بطعم الحياة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3116","text":"الصحة خير من المال ، والإيمان خير من الصحة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3117","text":"المرض شر من الفقر ، والكفر شر من المرض.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3118","text":"الهدوء والآداب والتواضع هذه الخصال ترفع شأنك عند العقلاء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3119","text":"من يسعى في النهار ينام في الليل ولو على الحصير ، والخامل في النهار لا ينام في الليل ولو على الحرير.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3120","text":"المصائب تأتي متواترة ، والبشائر تأتى آحادا.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m3121","text":"إذا أحسنا التربية والتعليم والإعلام ، فسوف نستغني عن كثير من السجون والمخافر والمحاكم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3122","text":"زوجة جيدة:أُمً جيدة، أم جيدة:تربية جيدة، تربية جيدة:تعليم جيد، تعليم جيد:وظيفة جيدة، وظيفة جيدة:راتب جيد، راتب جيد:زوجة جيدة، زوجة جيدة:أم جيدة، أُم جيدة:تربية جيدة، هكذا تكون:سعادة جيدة","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3123","text":"الشباب طاقة والطاقة تحتاج إلى وقود الطعام ، والطعام يحتاج إلى أسنان ، فالشباب يُقاس بقوة الأسنان الطبيعية وتماسكها وتكاملها.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3124","text":"الإسراف في الأكل يجلب الأمراض على المدى الطويل.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3125","text":"لا تجتمع الصحة والإسراف في الأكل.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3126","text":"الاقتصاد في الأكل باب من أبواب الصحة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3127","text":"استعينوا على دوام الصحة بالصيام والحِمْيَة","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3128","text":"من يغتني عن طريق الوظيفة سيُتهم بالفساد.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3129","text":"أصدقاء الغني أكثر من أصدقاء غير الغني ، لكن أصدقاء غير الغني أكثر إخلاصا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3130","text":"من عانى الفقر صغيرا ، عرف قيمة النعمة كبيرا ، والعكس صحيح.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3131","text":"إذا أردت أن تُصلح الناس فابدأ بنفسك ، لتكون قدوة عملية أولا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3132","text":"لولا الوحوش لماتت الحيوانات النباتية ، لأنها ستتكاثر لدرجة أن المراعي الطبيعية لن تكفيها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3133","text":"العدالة روح القانون ، ولا يطبِّق القانون بالجور إلا الظالم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3134","text":"عود لسانك على الأقوال الحسنة ، فلسانك هو الذي يعبر عن محتوى عقلك ، ومكنون قلبك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3135","text":"عندما تُدخل السعادة في قلوب الفقراء والضعفاء ؛ ستعرف السعادة عنوان بيتك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3136","text":"استمع للعلماء والحكماء كثيرا وتكلم قليلا.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3137","text":"إن أردت أن تعرف قيمة الوقت فَزُرْ المقابر. إن أردت أن تعرف قيمة الصحة فَعُدْ المرضى. إن أردت أن تعرف قيمة الحرية فَزُرْ السجناء. إن أردت أن تعرف قيمة البصر فَزُرْ معهد النور. إن أردت أن تعرف قيمة الأسرة فَزُرْ مأوى الأيتام ( اللقطاء ) وهلم جرا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3138","text":"لا تُعلم البطة السباحة ، ولا تعلم الزراع الفلاحة.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3139","text":"ألسنة غيرنا تُخبرنا عن عيوبنا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3140","text":"إذا أقبلنا عليهم ذكروا محاسننا ، وإن أدبرنا عنهم ذكروا عيوبنا ، حتى لا يُحزنونا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3141","text":"لا أُحب السجن ولو كان قصرا من ذهب ، ولا أُحب القيد ولو كان سلاسل من ذهب ، ولا أُحب الحرية المطلقة من قيود الإيمان والأخلاق والأدب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3142","text":"بعض الأحيان نحن نعالج المشكلة ، ولا نبحث عن أسبابها لمعالجتها ، وهذا التصرف لا يحل أصل المشكلة.","kind":"hikma","topic":"العقل والحكمة","note":"مغزى قصة رجل يُنقذ الغرقى ولا يبحث عمن يدفعهم في النهر","source":"شذرات (ملف وورد)"},{"id":"m3143","text":"خطأ الطبيب قد يقتل نفسا ، وخطأ المهندس قد يقتل نفوسا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3144","text":"أعظم انتصار ؛ انتصار المرء على هواه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3145","text":"أَحْبِبْ أولادك بقلبك وأدبهم بلسانك قبل يدك.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3146","text":"الاستغفار صابون الذنوب ، والتوبة مصبغة السيئات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3147","text":"قلوب العباد مفطورة علي توحيد الله والإقرار بربوبيته.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3148","text":"من آثر الدنيا على الآخرة فقد اشترى الخسيس بالنفيس ، وباع الغالي بالرخيص.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3149","text":"أول كتاب في حياتي تصفحته ، وتأملته ، وقرأته ، وفهمته وحفظته ، واقتبست منه ، وتلقيت عنه ، وتلقنت منه ، وتعلمت منه ، هو وجه أُمي ، كانت أُمي حاضنتي وحضانتي ومدرستي ومربيتي ، أطال الله بقاءها بصحة وعافية وحسن عمل.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3150","text":"السفيه مثل الطبل صوت عالي من غير معاني ، والعاقل مثل العين العذبة ، تنساب في صمت تنفع الناس والنبتة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3151","text":"المؤمن يعمل الخير الكثير في صمت ، مثل السلحفاة تضع مائة بيضة في صمت ، والمنافق إذا عمل عملا واحدا أعلن عنه بالضجيج ، كالدجاجة تضع بيضة واحدة في كفاح وصياح.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3152","text":"تمكن العلمُ من معرفة ما في أعماق البحار ، ولم يتمكن من معرفة ما في قلوب الرجال.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3153","text":"يموت الكرام وما تموت مآثرهم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3154","text":"يموت الظالمون ودعوات المظلومين تُلاحقهم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3155","text":"ما رأيت علاجا أفضل للسفيه من الصمت.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3156","text":"دخل محل فاكِهاني فاختار من كل نوع أفضل ثمرة ، وهكذا ينبغي للعاقل أن يقتبس من كل أحد يلتقي به أفضل ما لديه من علم أو خُلق أو خبرة أو حكمة ، حتى يتكون لديه رصيد من المعرفة والثقافة ، فيكون رجلا بارزا مُميزا في العلم والثقافة ، واللياقة واللباقة والأناقة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3157","text":"إذا صُمْتَ فليصم لسانك وجوارحك عما حرم الله تعالى.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3158","text":"إذا صليت فليخشع قلبك وجوارحك لله تعالى.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3159","text":"لا ترفع صوتك فوق صوت والديك ، ولا فوق صوت معلمك ، ولا فوق صوت أميرك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3160","text":"قال الشيخ للجني : بعد القراءة اخرج منها ، قال الجني : أخرج منها بشرط أدخل في زوجها ، ارتاع الزوج وفزع ! فسأله الشيخ : لماذا تدخل في زوجها ؟ قال : لأنه لا يصلي ، قال الشيخ : راقبه إذا ما خرج إلى المسجد ادخل فيه ، ومن يومها وهو ما يترك فرضا ، وقد كانت العملية حيلة وتمثيلية من زوجته لأجل أن يصلي","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3161","text":"الأصل أن الخوف إيجابي ، لأنه يحمل الإنسان على الحذر ، وتوقي الخطر. أما إذا كان مبالغا فيه ، فيصبح سلبيا ، ومعوقا عن العمل ، ومحبطا للأمل ، ومثبطا عن النشاط ، وداعيا للتوتر والانحطاط.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3162","text":"تزودوا للآخرة ، فنعم الزاد ؛ التقوى والإحسان إلى العباد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3163","text":"اطلبوا البركة والإنعام بصلة الأرحام.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3164","text":"حسن الظن برب العالمين ؛ من أمارات المتقين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3165","text":"أفضل ما يُقدمه الأباء للأبناء ؛ أن يختاروا لهم أُمًّا صالحة ، وأخوالا صالحين ، وأن يُحسنوا تربيتهم وتعليمهم ، وأخلاقهم وعاداتهم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3166","text":"خير حكامكم لكم من تُحبونهم ويُحبونكم ، وتدعون لهم ويدعون لكم ، ويقومون بواجبهم نحوكم ، وتقومون بواجبكم نحوهم ، ويسعون لما فيه خيركم وصلاحكم في دنياكم وأُخراكم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3167","text":"ازرعوا لكم في قلوب الناس المحبة والاحترام ، والتقدير وحسن المقام ، بواسطة الابتسامة والمبادرة بالسلام ، وطيب القول والدعاء ولين الكلام.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3168","text":"ابدأوا سلامكم بابتسامة الشفتين ، ولمعان الحب في العينين ، والترحبيب باليدين ، وكلمات المحبة بين الفكين ، واضمار المودة في الذي بين الجنبين ، تنالوا محبة الناس بأسرع من طرفة عين.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3169","text":"ذكر الله المنان تسكين للحيران وتنوير للجَنان وتطهير للسان وتطمين للإنسان ودحرللشيطان وتقوية للإيمان ومحبة للرحمن ويجلب الأمان ويُدخل الجِنان ويُكسب الرضوان","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3170","text":"ذكر الله هداية للنفوس ، وقوت للقلوب.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3171","text":"دوام الذكر يُنير العقول ، ويُرشد الأفكار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3172","text":"من أكثر من الذكر ؛ حسنت أفعاله في الجهر والسر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3173","text":"من لزم الذكر والأذكار، والقرآن والاستغفار، فاز بالجنات والنجاة من النار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3174","text":"في ذكر الله حياة القلوب، وفي الغفلة موت القلوب","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3175","text":"من ذكر الله أحيا الله قلبه ، ونور عقله ولبه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3176","text":"من ساء خُلقه فارقه صديقه، وجفاه حبيبه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3177","text":"من حسُن خُلقه أحبه صديقه، واحترمه عدوه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3178","text":"حُسْن الخُلُق هو أصل التعايش السلمي.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3179","text":"المال يجلب لك أصدقاء المصلحة، والأخلاق تجلب لك أصدقاء المحبة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3180","text":"إذا فقدت المال فقدت نعيم الدنيا، وإذا فقدت الأخلاق فقدت نعيم الآخرة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3181","text":"الجمال الظاهر حسن الخِلْقَة، والجمال الباطن حسن الأخلاق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3182","text":"الأخلاق كالأرزاق فيها الأغنياءوفيها الفقراء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3183","text":"عامل الناس بأخلاقك الكريمة لا بأخلاقهم الذميمة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3184","text":"إذا جادلت من هو دون مستوى أخلاقك، فحاول أن ترفعه إلى مستوى أخلاقك ، ولا تجعله ينزل بك إلى مستوى أخلاقه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3185","text":"الذي ما عنده فلس ما يساوي فلسا.","kind":"mathal","topic":"المال والاقتصاد","note":"من شعار البخلاء","source":"شذرات (ملف وورد)"},{"id":"m3186","text":"فلس على فلس يصير كنزا.","kind":"mathal","topic":"المال والاقتصاد","note":"من شعار البخلاء","source":"شذرات (ملف وورد)"},{"id":"m3187","text":"منع الجميع أرضى للجميع.","kind":"mathal","topic":"المال والاقتصاد","note":"من شعار البخلاء","source":"شذرات (ملف وورد)"},{"id":"m3188","text":"لو أنفقت شطر مالك على أقاربك ، لكان الساخط عليك أكثر من الراضي عنك.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3189","text":"حلاوة التغريدة في الآذاني ، أن تكون كثيرة المعاني ، قليلة المباني تُكسبك علما ومعرفة وثقافة في ثواني","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3190","text":"بذكر الله تطمئن القلوب بذكر الآخرة تنشط لفعل الخيرات وترك الذنوب. بذكر الموت تزهد في زهرة الدنيا وترغب في ترك المنكرات وتتوب. بذكر معاناة تربية الوالدين لأولادهم نجتهد في بر الآباء وطاعتهم. بذكر نعيم الجنة نسعى إليها بعمل الحسنات بذكر عذاب النار نهرب منها بترك فعل السيئات","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3191","text":"ليس المفلس من فقد الفضة والذهب، بل المفلس من فقد الأخلاق والأدب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3192","text":"من أراد طريق الجنة فليسك طريق تقوى الله وحسن الخلق.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3193","text":"الحكومة أُم الغني ، وامرأة أب الفقير.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3194","text":"الخسران من باع جنة نعيمها لا ينقطع بمعصية شهوتها لا تدوم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3195","text":"احذروا الأعمال التي تذهب لذاتها وتبقى تبعاتها.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3196","text":"اتقوا معاصي الخلوات فإن الله مطلع على الخفيات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3197","text":"من لزم الاستغفار وقاه الله من عذاب النار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3198","text":"ترك الذنب خير من التوبة ، والثوب الجديد خير من الثوب المغسول","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3199","text":"نظفوا ثيابكم بالماء والصابون ، وطهروا نفوسكم بالاستغفار ودموع العيون.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3200","text":"الوحوش يتفاهمون بقانون القوة ، والبشر يتفاهمون بقانون الأخلاق ، فإذا تفاهم البشر بقانون القوة ، وهجروا قانون الأخلاق ، فهذا هو المسخ الأخلاقي","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3201","text":"يا شباب ويا صبايا بر الوالدين دين ، وبركم بآبائكم تجدون ثمرته بالدنيا في أبنائكم ، وبالآخرة عند بارئكم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3202","text":"لا تُعلق جميع أثقالك على مسمار واحد ، ولا كل آمالك على عمل واحد ، ولا كل أموالك على مشروع واحد.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3203","text":"المشي إلى المساجد والقيام والركوع والسجود يمنحك استدامة المرونة والقوة والنشاط","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3204","text":"من عيوب الديمقراطية الفاشلة ؛ أن التعصب العائلي والطائفي والحزبي والقبلي غلب السعي لتحقيق الهدف السامي ، لتحقيق مصلحة الوطن والمواطنين ، التي تتحقق بالكفاءة ، التي تتطلب : القوة والأمانة والعلم والنزاهة والشفافية.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3205","text":"أيها الناس اسمعوا صوت الحكمة بجميع الحواس ، أول ما يبدأ في السمكة العطب والخياس ، في الخاشيم والراس ، ثم يسرى إلى سائر جسدها بالتماس ، فاختاروا رؤساءكم من المشهورين بالكفاءة والأمانة ، والصدق والرزانة ، والأخلاق والديانة ، والنشاط في أوانه ويزن الحق بميزانه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3206","text":"إذا فسد الزمان ؛ كثر الظلم والطغيان ، وقل العدل والأمان ، وتولى أصحاب الفسق والصبيان ، ونُحي أهل العلم والعمل والإيمان.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3207","text":"حاجة التربية إلى الرحمة حاجة المريض إلى الدواء ، والعليل إلى الشفاء ، والعطشان إلى الماء ، فالله سبحانه عندما أثنى على نفسه بالربوبية أتبعها بصفة الرحمة في أول سورة الفاتحة ، فالملاينة في التربية خير من المخاشنة ، والمياسرة خير من المعاسرة.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3208","text":"لا تُحدثني عن صلاته وصيامه؛ ولكن حدثني عن صدقه وأمانته.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3209","text":"ادع إلى الله بأخلاقك وسلوكك؛ قبل أن تدعو إليه بلسانك وكلماتك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3210","text":"تعلموا الأخلاق والآداب قبل أن تُخالطوا الناس والأصحاب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3211","text":"أكرم الناس أعراقا أحسنهم أخلاقا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3212","text":"لا تفسد جمال العفو بالعتاب فيقل الثواب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3213","text":"ذكر الله يُجدد الإيمان ، ويُوهي كيد الشيطان.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3214","text":"سامع القارئ والذاكر شريكهما في الثواب.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3215","text":"الصمت خير من اللغو ، والذكر خير من الصمت.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3216","text":"في السياحات تقل القيود وتتسع الحريات ، وتزيد المزاحات وتنقص المجاملات ، وتتفتق الأذهان والقرائح بالأفكار البديعات ، والكلمات الموزونات.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3217","text":"الاستعانة بالآلات من خصائص الإنسان فالحقل الذي يحتاج مائة عامل،مع التقدم العلمي أصبح يحتاج إلى عشرة فقط فبرزت مشكلة الأيدي العاملة فبعض الأحيان التقدم العلمي يحل مشكلة ثم ينشأ من حل المشكلة؛ مشكلة جديدة تحتاج إلى حل.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3218","text":"من تتبع رُخَص المذاهب ، وزَلَّات العلماء ، والأحاديث الشاذة ، أتى منه رجل فاسق.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3219","text":"بعض التجار فجار يجعلون الأسعار كالنار","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3220","text":"اتصل رجل بحكيم فسأله : ما سِرُّ السعادة الزوجية التي تستمتع بها ؟ فقال : انتظرني قليلا حتى أُنُظِّف يديَّ من غسيل الأطباق والقدور ثم أُخبرك ، فلما رجع وجد الخط مغلقاً","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3221","text":"لا يستقيم أمر العامة حتى يُطبق القانون بحزم وعزم على الخاصة وخاصة الخاصة ، فعقاب وزير واحد مختلس يصلح مائة وزير ، وهكذا تصلح الأمور ، لمن أراد الإصلاح جادا صادقا.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3222","text":"من صفات المؤمن صفاء القلب وسلامة النية وبراءة الطوية وحسن الظن في البرية والأخلاق السنية والآداب الذهبية","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3223","text":"صاحب من حسنت أخلاقه ولو كان فاسدا في نفسه ، ولا تُصاحب من ساءت أخلاقه ولو كان صالحا في نفسه ، فأخلاق الأول لك وفساده عليه ، وصلاح الثاني له وسوء أخلاقه عليك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3224","text":"النقاش مع العالم المتواضع يُكسبك أدب الجدال والحوار ، وطريقة المنطق في عرض الأدلة والبراهين ، وكيفية التفهيم باللين والدليل ، من غير تعنيف وتوبيخ وتجهيل ، أما العالم الحازم الزِّمِّيت فيخاطبك بأخي الزجر والتسكيت.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3225","text":"إذا نُحِّيت الكفاءات وقُرِّبت القرابات والصداقات ضاعت الأمانات وكثرت الاختلاسات فعجزت الميزانيات من كثرت العمولات والهدر والمناقصات","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3226","text":"س: كيف تكون قدوة لأهل بيتك ، وجيرانك وأصدقائك ، ولمجتمعك وللناس جميعا؟ ج : إذا جعلت النبي محمدا صلى الله عليه وسلم قدوتك في أقواله وأفعاله وأخلاقه وآدابه وعاداته ودعوته ، بقدر استطاعتك ، فقد أصبحت أنت قدوة حسنة لكل من تقدم ذكرهم ، بقولك وفعلك وأخلاقك وآدابك وعاداتك ودعوتك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3227","text":"استدامة الزواج ليست مرهونة بشعلة الحب وعنفوان المودة ، لأن غالبا ما يكون ذلك في سنة أُولى حب ، لكن استدامة الزواج مرهونة بالاهتمام والاحترام ، وحسن المعاشرة وكرم الأخلاق ، وطيب الحديث وابتسامة اللقاء ، وندرة العتاب ، وترك الخشونة والسباب.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3228","text":"حاول أن تُسعد نفسك في جميع مراحل حياتك ، فلا تُعلق سعادة المرحلة التي أنت فيها على المرحلة التي تليها.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3229","text":"بكرم أخلاقك وحسن تعاملك ستجعل جميع علاقاتك ناجحة ، والعلاقات الناجحة تُخفف عنك من عبء الحياة وثقلها.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3230","text":"أهم علاقاتك علاقتك مع الله بطاعته ، ثم علاقتك مع نبيه باتباعه ، ثم علاقتك بأصحابه بحبهم وتوقيرهم ، ثم علاقتك بالناس بحسن اللقاء وكرم الأخلاق.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3231","text":"إذا أردت أن تعيش سعيدا مع عقيلتك ، طيلة حياتك ، فكن نبيها قوي الملاحظة صقري النظر ، فأي تغيير تفعله في لبسها حقيبتها نظاراتها تسريحتها قصة شعرها لون شعرها خاتمها حذائها ساعتها سوارها الخ عليك أن تبادر بالانبهار ، وتقول : ما شاء الله لا قوة إلا بالله ، ما هذا الجمال الساحر ! ما هذا الذوق الباهر ، لايق لايق جدا جدا عليك ، أظهر جمالَك وسِحرَك . لأنها وهي تشتريه تفكر فيك وفيما يُعجبك ويجذبك ، لأن ما يُعجبك هو الذي يُعجبها ، فلا تكن بخيلا بالكلمات الجميلات ، فالمرأة تُفضل الحب المعلن على الحب المكنون.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3232","text":"الطفل يولد حواسه نظيفة ، وعقله صفحة بيضاء ، فننقش فيها أفضل الكلام وأجوده.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3233","text":"إذا عاش الزوجان أربعين عاما ؛ تحت سقف واحد ، خمدت نار الحب ، وبقي الرماد الحار ؛ ودفء المودة ، واللطف وحسن العشرة والجوار ، وجمال الذكريات والأخبار.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3234","text":"دايما كنا نسمع مقولة صندوق الأجيال القادمة ونحن في طفولتنا كنا أجيالا قادمه وعمرنا ما شفنا صندوقنا ولا أعطانا حتى عيدية","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3235","text":"صلوا علي النبي باللسان وأحبوه بالجَنان واتبعوه بالأركان عليه الصلاة والسلام","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3236","text":"طوبى لمن طَوَّع نفسه لطاعة الله ، وتدرج معها في فعل الخيرات وترك المنكرات ، وحب المساكين ، والعطف على اليتيم ، فانقادت له بعد امتناع ، وتبعته عن اقتناع ، وويل لمن قادته نفسه لطاعة هواه والشهوات ، وفعل المحرمات والمنكرات ، وترك الطاعات والصلوات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3237","text":"أشياء قليلها كثير وكثيرها قليل النار والمرض والعدو والدَّين والملح والفلفل والسم والشرك والإهانة والعقوق وغدر الصديق والبوز على الريق","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3238","text":"إن الله سبحانه وتعالي بث عباده في الأرض ، على حسب منابع المياه ومواردها ، فنشأت المدن الكبيرة والعواصم على ضفاف الأنهار ، ونشأت الحضارات ، وقامت العمارات ، وتواصل الناس بالرحلات والمواصلات ، لتبادل المنافع والثقافات ، فسبحان المدبر العظيم مدبر المخلوقات ، رب الأراضين والسموات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3239","text":"يمكن أن نُطفئ النار بماء قذر أو غير صالح للشرب ، كما يُمكن أن ندحر شَرَّ المجرم بالمجرم ، والعدو بالعدو ، والكافر بالكافر ، بحسن دهاء السياسة ، وجودة التدبير ، وخدعة التفكير.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3240","text":"إن أردت أن تقهر امرأة وتُحزن قلبها ، فامدح أمامها امرأة أُخرى : امدح شعرها أو عينيها أو حاجبيها أو كفيها أو ساعديها أو ساقيها ، أو تسريحة شعرها أو حلاوة منطقها ، أو لذة طعام طهيها ، أو سيارتها أو خادمتها أو قطتها أو كلبها ، أو أي شيء منسوب لها ، فإن مدحك لها يفت المرارة ، ويرفع درجة الحرارة ، ويجعلها تبحث عن النظارة وهي لابسة النظارة ، فحذاري أن تمدح امرأة بين يدي عقيلتك.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3241","text":"مشاعر المرأة أكثر رقة وعاطفة من الرجل في مسائل الحب والعاطفة ، فغالبا تتجنب أن تمدح رجلا في حضرته ، حتى لا تستثير زعله وغضبه ، إذا علمت من طبعه أنه يغار عليها كثيرا ، وهذا شيء يُعجبها ويُسعدها ، أعني أنه يغار عليها ، فهذه أمارة الحب والإعجاب.","kind":"hikma","topic":"الحياة الزوجية","note":"جواب عن سؤال: ماذا يحدث إذا مدحت المرأة رجلا آخر أمام زوجها؟","source":"شذرات (ملف وورد)"},{"id":"m3242","text":"ما أكثر المتعهدين ما أكثرالمخادعين ما أكثر المتربصين ما أكثر الحاسدين ما أكثر المُثبطين ما أكثر الخاملين ما أكثر الغاشين ما أكثر الشامتين ما أكثر المقاولين ما أكثر الواعدين ما أكثر الغادرين ما أكثر المتكبرين ما أكثر المتذمرين ما أكثر المدَّاحين ما أكثر المتزلفين ما أكثر المصفقين فاستعن بالله رب العالمين","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3243","text":"العالم آلة كبيرة ، فكن تُرْسا نافعا في أُسرتك ، وأُسرتك تُرْسا نافعا في عائلتك ، وعائلتك تُرْسا نافعا في قبيلتك ، وقبيلتك تُرْسا نافعا في شعبك ، وشعبك تُرْسا نافعا في اقليمك ، واقليمك تُرْسا نافعا في العالم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3244","text":"إن أردت أن تعرف عيوب امرأة فامدحها أمام امرأة أُخرى فسوف تُخرج فيها ألف عيب وعيبا ، وتذكر عيوبها بالتفصيل : من مَفْرِق رأسها إلى أخْمَص قدميها ، بمنهجية وطريقة امتيازية ، وترقيمات عددية أو حروف أبجدية.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3245","text":"كانت زوجته كبيرة ومريضة ، وهو له رغبة في الزواج ، لكنه لا يُريد أن يُحزن عقيلته ، فلما اشتد عليها المرض ، أخذ تفكيره بالزواج يزداد ، بحسب ظنه وأن الأعمار بيد الله ، وسوف تستريح من مرضها ، وفي ليلة من الليالي افتقدها ، فنهض من سريره فكاد أن يقع عليها ، فوجدها ساجدة وهي تقول : يا ربي لا تقبض روحي حتى تغفر لي ذنبي ، فقال في نفسه : أظنها مطولة ، فترك الأفكار والخطط التي في رأسه ، ورضي بالأمر الواقع","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3246","text":"حياة الفرد تُشبه الخزان - تانكي - يمكنك تملأه بالذهب أو الخشب ، فاحرص على أن تملأه بالذهب الذهب الخالص ذكر الله بإخلاص","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3247","text":"طوبى لمن امتلأت صحيفته بذكر الله تعالى وخلت من الغيبة والنميمة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3248","text":"طوبى لمن حضر أجله ، والملائكة يُبشرونه وهو يضحك ، وأولاده يبكون على فراقه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3249","text":"طوبى لمن أسعده الله بطاعته ، وأنار قلبه بذكره ، وشرح صدره بهدايته ، وأضاء عقله بحكمته.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3250","text":"لن يدخل معك في قبرك إلا عملُك ، فحاول أن تصلح عملَك قبل فوات الأوان.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3251","text":"لن تعيش في الحياة إلا مرة واحدة ، فاغتنم هذه الفرصة الوحيدة ، فاملأ حياتك بالإيمان والعمل الصالح ، والبهجة والتفاؤل.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3252","text":"لا تخشَ من الفشل، لأن الفشل هو أول طريق النجاح ، إذا كان مع الحماس والمثابرة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3253","text":"الحظ يطوف على الخاملين واليائسين والمتذمرين والمتسلقين ؛ يرفرف عليهم ولا يقع ، ويطوف على المجتهدين والمتفائلين والساعين ، فيرفرف عليهم ثم يقع ، فحظك ثمرة تربيتك وتعليمك وأخلاقك وآدابك ، وسعيك واجتهادك وطموحك.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3254","text":"تجدون السعادة الزوجية حب إعجاب لهفة بكلمة السر السحرية ببطاقةالسحب الآلية من البنوك المصرفية وبالهدايا الذهبية والمنح النقدية","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3255","text":"الزواج غريزة فطرية ، وحاجة نفسية ، وضرورة اجتماعية، وسنة شرعية ، وهو من سجايا الأنبياء عليهم السلام ، وفعل الصالحين والأولياء ، ويتحقق بزوجة واحدة ، ويجوز التعدد بشروطه المعروفة","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3256","text":"ينبغي للعبد أن يعلق قلبهه بالله أكثر مما سواه ؛ في جميع أُموره : في السراء والضراء ، والشدة والرخاء ، لأن الله تعالى بيده مقاليد السموات الأرض ، وهو على كل شيء قدير ، وتدبيره خير التدبير ، فعليه أن يجمع بين السعى والدعاء ، ويتوكل على الله رب الأرض والسماء.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3257","text":"الحياة لا تُعلمك كل شيء منفردا ، فلا بد أن تتعلم ممن هو أكثر منك علما ، وممن هو أكثر منك تجربة ، وممن هو أكثر منك ممارسة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3258","text":"إذا أيقنت بأن الله تعالى هو الذي يُدبر أمر الكون وما فيه ؛ وهو الذي يُدبر أمر حياتك ، فما عليك إلا أن تقوم بعمل ما تقدر عليه ، ودع الباقي على الله ، ولا تفكر فيه كثيرا ، ولا تحمل همه ، فهذا سوف يريح عقلك وقلبك ونفسك وبدنك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3259","text":"الإنسان بطبيعته يميل إلى المبالغة والتهويل في المدح والقدح فاحذروا من المبادرة بالتصديق أو التكذيب حتى يتبين الصواب ويذهب الارتياب","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3260","text":"بعض الأحيان تكون البنت مرضية لربها ثم لوالديها،فلا تتم خطبتها للأوائل فلا تحزن لأن الله مدخر لها من هو الأفضل والأنسب وهذا من حسن تدبير ربها لها","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3261","text":"ليس المشيمة وغشاؤها فقط لو اجتمع العلماء ما استطاعوا أن يصنعوا مثلها ، بل كل جزئية وخلية في الجنين وأُمه لو اجتمع كل العلماء ما استطاعوا أن يصنعوا مثلها ، فالله هو الخالق والخلاق العظيم ، فليخلقوا ذبابة أو بعوضة أو نملة أو حبة قمح أو شعير ، فسبحان الله العظيم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3262","text":"إن الله سبحانه وتعالى قد مَكَّنَّا من اختيار المستقبل الصالح ، وجعله في مقدورنا ، فإذا أصلحنا أحوالنا في الحاضر ؛ فالله يُصلح أحوالنا في المستقبل ، ( إن الله لا يُغير ما بقوم حتى يُغيروا ما بأنفسهم ) فلنبادر بإصلاح أحوالنا الحاضرة ؛ ليتحقق لنا وعد الله ، والله لا يُخلف الميعاد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3263","text":"بعض الرؤساء في المناصب والمراكز والشركات والوزارات والحكومات والهيئات والجمعيات وغيرها ؛ مثل الضرس الذي نخر السوس في جذوره ، فبلغ العطب إلى العصب ، فبقاؤه آلام وإزعاج ، وخلعه راحة وانفراج ، فما له علاج إلا الخلع بعد التخدير والبنج.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3264","text":"حل التسيب والفوضى العارمة بالحزم والعزم مع الخاصة وخاصة الخاصة","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3265","text":"إذا عاقبت الكبير يرتدع الصغير وإذا عاقبت الصغير وتركت الكبير يرتع الكبير ويتجرأ الصغير","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3266","text":"إن الله جلت حكمته وعظمت رحمته ؛ مَكَّنَ عبده من تغيير الماضي السيء إلى حسن : بالإيمان بعد الكفران ، وبالتوبة والاستغفار ، والكفارات والقضاء ورد الحقوق لأهلها . فالبدار البدار قبل فوات الأوان ، وانقضاء فترة الزمان، وحلول مَنِيِّة الإنسان.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3267","text":"القصص يشوبها المبالغات والتهويلات ، وفي الغالب ليس لها أسانيد معتبرة ، ولا تخلو من الوهن والضعف ، وقد يكون في طياتها مخالفات شرعية أو عقلية، فلا تتحمسوا في قبولها وتصديقها، وحسبكم أن تأخذوا منها العبرة والموعظة ، وعليكم بالقصص القرآنية ، والقصص الثابتة بالسنة النبوية.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3268","text":"كون الإنسان يُولد من أبوين مسلمين وفي مجتمع مسلم ، ويتربي في حضانة مسلمة، وبيئة مؤمنة ، هذه نعمة عظيمة، ومِنَّة كريمة، وهي من النعم المنسية التي لا يُستهان بها.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3269","text":"اتصل همام بحارث يستشيره أين يسافر ؟ إلى لندن أو باريس ، حتى تهدأ الموجة ، لأنه انفضح بغسيل الأموال . فقال حارث : أفضل مكان تسافر إليه استر اليا","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3270","text":"لا تكن عبدا لنفسك وهواك ، فتُبالغ في تتبع الملذات والشهوات ، ولكن كن عبدا لمولاك ، الذي خلقك وعلى موائده رباك ، فاجتهد بالعبادات والطاعات ، ومكارم الأخلاق والعادات ، وتحلى بخير السجايا والصفات ، لتكون من أهل البر والمروآت.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3271","text":"املأ قلب عقيلتك بحبك عن طريق هدايا اليدين ، وحلاوة ما يخرج من الشفتين ، وحُسن الاستماع إليها بالأُذنين ، والسعي في مساعدتها بالساقين ، فإن لم تفعل الأربع ، فافعل الأنفع ، فخيركم خيركم لأهله.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3272","text":"لا تقل اللهم لا تُحوجني إلى خلقك أنت تحتاج إلى الزراع لتألكل تحتاج للبناء لتسكن تحتاج للطبيب للعلاج وهلمَّ جرَّا قل : اللهم لا تُحوجني إلى شرار خلقك","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3273","text":"السفر يُوسع الأُفق والمدارك ، ويجعل الإنسان أكثر اجتماعيا ، ويُذهب عنه التعصب والتقوقع ، والعالِم إذا سافر يتسع تفكيره ، وييسر في آرائه وفتاواه ، ويترك التشدد والتزمت ، ويصبح يراعي الواقع والمتوقع في نظرته الفقهية والعلمية.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3274","text":"سأل المُفتي : أنا هاجر فراش زوجتي منذ شهرين . المُفتى : لماذا ؟ الزوج : يأتيني الشيطان ويُوسوس لي : بأني قد طلقت زوجتي . المفتي : نعم أنت حضرت عندي ، وبحضور الشهود أنت طلقت زوجتك . الزوج : لا والله العظيم ما أتيتك ، وما طلقت زوجتي . المفتي : سبحان الله ! إذا جاءك الشيطان ، وقال لك : أنت طلقت زوجتك ، فقل له مثل ما قلت لي . أخذ الزوج بنصيحة المُفتى فذهب عنه الوسواس ، فرجع إلى فراش زوجه","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3275","text":"اعتقادك في نفسك سواء أكان إيجابيا أم سلبيا ؛ هو رسائل خفية ومؤثرة ترسلها لمن حولك. كلما تبحرت في العلم ، وتزينت بالأدب ، سوف تكون رسائلك الخفية قوية ومؤثرة إيجابيا فيمن حولك.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3276","text":"استمتع بما أنت فيه لا بما تتمناه ، حتي لا تزهد وتكره ما أنت فيه ، فاستمتع بحياتك لا بالحياة التي تتمناها.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3277","text":"قال لأصدقائه في الديوانية : أنا ترقيت في الجيش ملازم ملازم أول نقيب رائد مقدم عقيد عميد لواء، فريق، فريق أول ثم تقاعدت ، أنا الآن لا شيء ، يقولها بحسرة وندامة، بعد غياب الأُبهة والمركز والطنطنة ، وكان يجلس في طرف الباب رجل فقير يخدم الرواد ، ولم يسمعوا صوته من قبل ، فقال للمتقاعد : أنت بعد رحلة الحياة الطويلة صرت لا شيء ، أنا من الآن لا شيء ، أنا وصلت هذه الرتبة من أول حياتي","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3278","text":"فصل الشتاء موسم إيماني تجاري ، تكثر فيه الحسنات ، وتزيد فيه أعمال الصالحات ، قصر نهاره فصامه ، وطال ليله فقامه ، لمن أراد صيام النوافل وقضاء صيام رمضان ، وكذلك قيام الليل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3279","text":"الأُمة ينقصها الرغبة في طلب العلم والسعي لطلبه ، والعمل بمقتضاه ، أما الكتب والمراجع والمخطوطات موجوده ومحفوظة. لأن هذا الدين تكفل الله بحفظه إلى يوم القيامة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3280","text":"كن طيبا متواضعا ولا تتباهى بأنك طيب متواضع.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3281","text":"الغبي يقع في المشاكل ولا يستطيع الخروج منها، والذكي إن وقع فيها يخرج منها ، والحكيم لا يقع فيها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3282","text":"الأيادي المتسخة تدل على أن المال نظيف ، لأنه يكسب المال بعمل يديه وعرق جبينه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3283","text":"تنافس عالمان في أيهما يكتب رسالة أكثر اختصارا إلى الآخر : فأرسل الأول رسالة من عشرة كلمات . فأرسل الثاني تسع كلمات . ففي كل مرة يُنقص الواحد منهما كلمة من الرسالة ، حتى قال الأول : كَيْفَكَ فقال الثاني : كَكَ . فغلبه وانتصر عليه","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3284","text":"قال الوتساب: لو تكرمتم يا فضلاء لا تعزوا عن طريقي عزوا مباشرة على أهل البلاء وليس على المعارف والأصدقاء شكرا للوتساب على النصيحة الفصيحة","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3285","text":"إن الله فطر المخلوقات على حب من أحسن إليها وأعظم إحسان وصل إلى الإنسان من خالقه سبحانه وتعالى","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3286","text":"قاعدة مهمة في التربية: أنت قدوة لأولادك؛ ومثل أعلى لأحفادك، فأظهر لهم من نفسك: حاضرك وماضيك ما تُحب أن يحاكوك به، واخف عنهم ما تكره أن يُحاكوك به، لترفع من معنوياتهم، وتعزز من همتهم وطموحهم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3287","text":"الواتساب مثل سوق الجمعة به الحرير وبه القصدير به الذهب وبه الحطب به الزهرة وبه البعرة سَلْ الخبراء والعلماء والمُجربين الأذكياء قبل ما تعتمد ما فيه من الأقاويل والأنباء","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3288","text":"الاستغفارصابون الذنوب التوفيق هداية الدروب التغريدات سيل القروب السعادة بالزوجة العروب الدعاء يفرج الكروب الذِّكر نور القلوب","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3289","text":"الوتساب محرج يعرض النقيضين عن شخص واحد في وعاء واحد، ويجرد الإنسان من المكانة الكبيرة، والهالة المستنيرة، فيُطفئ شمعته، ويُلطخ سمعته.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3290","text":"إذا تخلى الناس عنك في ضائقة؛ فاعلم أن الله يريد أن يسمع مناجاتك، ويبتلى صبرك، ويُعظم لك أجرك، فاصبر فإن فرج الله قريب، وإن مع العسر يسرا.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m3291","text":"كثرة الخلافات والنزاعات الداخلية تُطمع الأعداء المتربصين في الخارج، فَصَفُّوا النفوس، ورصوا الصفوف، ووحدوا الصف والكلمة، واتفقوا ولا تختلفوا، واجتمعوا ولا تتفرقوا، فيد الله فوق يد الجماعة، والجماعة قوة وشجاعة ومناعة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3292","text":"مناحي عنده تيس ، وجاره مرزوق عنده غُنَيْمَات ، فطلب مرزوق من مناحي أن يستضيف تيسه عند غُنَيْمَاته ، فوافق مناحي ، ثم حدث بينهما سوء تفاهم ، فسحب مناحي سفيرة","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3293","text":"صدقتكم عن ميتكم خير له من بكائكم وحزنكم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3294","text":"وهو راجع من عمله في حَمَّارة القيْظ : شدة حره ، وجد دجاجة في الزُّقَاق ، فأمسك بها ، ووضع الماء على النار ، وجهز التوابل والسكين ، ثم أخرج رأسه من الباب ، فنادي يمينا ويسارا : من ضايع له فهمس: دجاجة ، ولا يُوجد أحد في الزُّقَاق ، فقال: ليس لها صاحب ، فدخل وأغلق الباب ، ثم تغدى بالدجاجة واحتسى مرقتها","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3295","text":"عمل الصالحات كالصلاة والذكر والتلاوة وغيرها في البيت، يُعتبر من أعمال السِّرِّ، ولو اطلعت عليها الزوجة والأولاد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3296","text":"إذا رأيتم الرجل يصل رحمه، ويُحسن إليهم ويبرهم، ويبذل لهم نداه، يكف عنهم أذاه، فتوقعوا له أن الله سوف يبسط له في رزقه، ويمد له في أجله.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3297","text":"من وقَّر الكبار وهو صغير؛ وقَّره الصغار وهو كبير، فالجزاء من جنس العمل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3298","text":"سوف تكون ناجحا ومحبوبا عندما تُساعد المساكين والمحرومين والمضطهدين.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3299","text":"إذا أردت أن تُقَيِّم أخلاق إنسان فانظر إلى تصرفاته مع من دونه لا مع من فوقه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3300","text":"حقوق العباد لا تسقط إلا بعفو صاحب الحق، فإن قبل الله توبة الظالم، يسترضي الله المظلوم، بأن يُعرض عليه نعيم عظيم، فيقول: لمن هذا يا ربي؟ فيقال له: للعافين عن الناس، فيقول: قد عفوت عنه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3301","text":"جودة المنتج مقدمة على تقليل كلفة المنتج، فليس من الحكمة الاقتصادية أن يكون الإهتمام بتقليل كلفة المُنتج مُقدم على جودة المُنتج.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3302","text":"كفاءة الموظف أهم من اسمه ومركزه الوظيفي.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3303","text":"عند الاختيار والترجيح فكفاءة الموظف العلمية والعملية مقدمة، ولو كان غيره أكثر صلاحا في نفسه، لكنه أقل كفاءة في علمه وعمله.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3304","text":"غير الصالح في نفسه العبقري في قراراته أكثر نفعا للشركة؛ من الصالح في نفسه الضعيف في قراراته، لأن الأول يجلب لها الأرباح الرابحة، والثاني يجلب لها الخسارة الفادحة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3305","text":"ربما غلب الضعيفُ ذو العقيدة القتالية القوية؛ القويَّ ذا العقيدة القتالية الضعيفة","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3306","text":"لا بأس للخبير الناصح أن يرصد ما فيك من الصفات، ويستشف ما فيك من المميزات وأنت في مقتبل العمر فيُرشدك إلى ما ينفعك من التخصصات، ويدع لك الاختيار من غير إكراه واصرار لتختار طريق مستقبلك","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3307","text":"إذا رأيت الشاب في خدمة والديه، وطوع أمرهما، ويسعى في مصالحهما، ويبادر في طاعتهما، بارا محتسبا، من غير تضجر ولا تأفف، فبشره بتوفيق الله ورضوانه، وأن الله سبحانه، سييسر أمره في شؤون حياته وبرزخه وآخرته.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3308","text":"اطلبوا سعة الأرزاق وفسحة الآجال وبركة الأيام، ببر الوالدين وصلة الأرحام ورحمة الأيتام.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3309","text":"السياسة ليست ماذا تريد؛ وماذا لا تريد، السياسة ماذا تستطيع أن تحققه، وماذا لا تستطيع أن تحققه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3310","text":"التفاؤل ليس بالتوهمات والتخرصات وإنما هو بالدراسات والاستعدادات.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3311","text":"التوكل ليس بترك العمل وحسن الظن، وإنما التوكل بالسعي والاجتهاد وحسن الظن.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3312","text":"اختلاف الرأي عند ذوي النفوس السوية؛ لا يُفسد للود قضية.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3313","text":"لما رأيتك في العلوم نهرا؛ صاحبتك لأشرب منك دهرا.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3314","text":"ديكه قفز على الحائط ثم قفز على السطح ، وما زال يقفز ويطير حتى فقده ، فرفع طرفه إلى السماء وقال : اللهم لا تجعله في يد عالم ولا يد فاجر ، فتعجبوا من دعائه ، فقال : العالم يُحَلِّلُها ، والفاجر يَسْتَحِلها","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3315","text":"الزواج حاجة فطرية، ورغبة نفسية، وحالة اجتماعية، وسنة نبوية، وفيه أحكام شرعية، وآداب عرفية، والعازف إما من عجز مادي أو معنوي، وهو معذور، والزواج شطر الدين، لأنه يُعين على حفظ الفرج، وغض البصر، وفيه تكثير للنسل والأمة المحمدية، وفيه يعول الزوج زوجته وأسرته، ففيه ثواب عظيم، وهو الوضع الطبيعي في الأحياء عموما، وتكوين الأسرة نعمة عظيمة.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3316","text":"أفضل حكومة في العالم: هي أقل دولة فيها اختلاسات وعمولات ومحسوبيات وتزوير جنسيات ومشروعات فاشلة وغسيل أموال واستئثار بالمميزات والتفاف على القوانين ومصادرة الحريات، لأنه لا توجد حكومة خالية من العيوب والتقصيرات، ولا يوجد شعب راضيا عن حكومته تمام الرضا، فالحكومة كالثومة ماكولة ومذمومة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3317","text":"الدنيا عناء آخرها فناء، غنيها مفتون وفقيرها محزون.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3318","text":"الدنيا صالة اختبار، ينجح فيها الأخيار، ويسقط فيها الأشرار.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3319","text":"الدنيا سوق قائمة، يربح فيها المؤمنون، ويخسر فيها الكافرون.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3320","text":"اكسب رضا الناس بحسن أخلاقك وتواضعك وكرم طباعك، من غير أن تتنازل عن المبادئ والقيم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3321","text":"إن الله خلقنا في الدنيا للآخرة، وجعل لنا فيها طريقين: طريقا يُوصل إلى القصور والحور، والأنهار والأشجار، والأزهار والثمار، وطريقا يُوصل إلى العذاب والعقاب، والسعير وسوء المصير، والنار وسوء القرار، وجعل للإنسان حرية الاختيار، ووهبه العقل والمهلة، وجعل له الحسنة مضاعفة، والسيئات يبدلها حسنات إن تاب منها وأناب، فالسعيد من وفقه الله للإيمان والتوحيد، والشقي العنيد من خالف التوحيد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3322","text":"القضاء العادل ما تواطأت على تأييده الخاصة والعامة، ولم تُنكره النفوس، وانشرحت له الصدور، ورضيه العلماء والدهماء، ولم يستوحشه العقلاء، وكان مرضيا للأتقياء، ولم يتنافى مع مكارم الأخلاق، والقضاء الجائر ما خالف كل ذلك، والمؤمنون شهداء الله في الأرض، وكلام الحق على لسان الصالحين من الخلق.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3323","text":"من المروءة العطف على الصغير، وتوقير الكبير، وتفقد اليتيم والفقير.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3324","text":"الاقتصاد ينمي القليل ويزرع، والإسراف يحصد الكثير ويمحق.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3325","text":"نعم معين رب الأسرة على العيش: الستر والاقتصاد.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3326","text":"كن كريما ولا تكن مبذرا، وكن غنيا ولا تكن متكبرا، وكن مقتصدا ولا تكن بخيلا، وكن حازما ولا تكن متزمتا، وكن جادا ولا تكن زِمِّيتا، وكن متكلما ولا تكن مهذارا، وكن مازحا ولا تكن مكثرا، وكن متواضعا ولا تكن ضعيفا، وكن حليما ولا تكن ذليلا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3327","text":"بعض الناس يعضون اصابع الندم، ويتحسرون على ما فاتهم من الغنائم والنعم، حيث إنهم لم يشتروا العقارات والقسيمات، في زمن الرخص والتسهيلات، وكذلك الإنسان سوف يتحسر ويتذمر على ما فاته من تحصيل الحسنات قبل الفوات، وتجرع كأس الممات.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3328","text":"اتقوا مذلة الدَّيْنِ والسؤال، بالاقتصاد في الإنفاق والأموال.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3329","text":"إن وهبك الله نعمة مادية أو معنوية؛ فاستصلحها ونمها ولا تُهملها فتهدمها وتفقدها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3330","text":"القراءة الجيدة، والاستماع الجيد، والتدريبات الجيدة، تُصقل الطبيعة، وتقوي المهارات، وتُبرز الهوايات، وتُكسب الملكات، وتُحسن العادات.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3331","text":"الحكيم يملأ ثوبه برزانته، ويملأ عقول الناس بحكمته.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3332","text":"الحكيم يرحل من الدنيا ببدنه، ويبقى في عقول الناس بحكمته.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3333","text":"من عَوَّد نفسه على الصبر والتحمل، ضمن النجاح في سائر أعماله.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m3334","text":"لن تجدوا أرحم بكم ولا أبر بكم من ربكم خالقكم، فأطيعوه واستغفروه، فإنه يرحمكم ويغفر لكم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3335","text":"يجلسان متجاوران في آخر القاعة ، وهما شابان ملتزمان بتعاليم الإسلام وآدابه ، لاحظ مراقب الاختبار أنهما يغشان ، فسحب منهما كراستي الاختبار ، وطلب منهما مغادرة القاعة ، فعند الباب قال أحدهما للآخر : من السنة أن يتقدم من على اليمين ! فقال المراقب : يا حلاوة ! أما علمتما أن من الواجب الأمانة وعدم الغش !","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3336","text":"الطالب وعاء وشمعة؛ فعلى المُعلم أن يملأ وعاءه بالعلم والحكمة، ويُنير شمعته بالنور والضياء، فيعينه على الحفظ والفهم والاستنباط.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3337","text":"شككت في طالب يغش ، فقلت : في طالب واحد يغش وأنا عارفه ، فكل الطلاب رفعوا رؤوسهم ونظروا إلى ما عدا هذا الطالب ، لأن العين نمامة والقلب كتوم","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3338","text":"الشورى ضياء العقل، ونور البصيرة، وهداية الطريق، ومفتاح التوفيق، وبشارة الفلاح، ووقاية من الندم، وبها الآراء الرشيدة، والتوجيهات السديدة، والعاقبة الحميدة، والخاتمة السعيدة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3339","text":"لولا الراعي لعاثت الذئاب في الغنم فسادا، ولولا السلطان لعاث المجرمون في الرعية فسادا.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3340","text":"من لم يسعد بحديثك فأسعده بصمتك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3341","text":"لا تمكث في مجلس يُقلل من قدرك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3342","text":"نعم الجليس الكتاب النفيس، الذي يحمل المعاني الصحيحة، والألفاظ الفصيحة، والأفكار السديدة، والمواعظ المفيدة، والأمثال الراقية، والنصائح الواقية.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3343","text":"الحكيم يتعلم من حماقات السفيه، والسفيه لا يتعلم من ارشادات الحكيم.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3344","text":"ما لا تعرفه لا تشتهيه ولا تشك فيه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3345","text":"إن كنت غنيا فأكثر من الصدقات، وإن كنت فقيرا فأكثر من الاستغفار، فإن الاستغفار يجلب الأرزاق والأمطار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3346","text":"سأل حكيما: كيف أجد الزوجة المناسبة؟ قال: ابحث عن زوجة تماثلك بكرم الأخلاق. قال: وضح يا حكيم. قال: لا بد أن تكون أولا أنت زوجا مناسبا.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3347","text":"الوزارة نعمت المرضعة وبئست الفاطمة عاقبة الوزارة ندامة وخسارة إلا من جمع بين القوة والأمانة والكفاءة","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3348","text":"‏الفرق بين العقل والمروءة: العقل يُرشدك لاختيار الأفضل، والمروءة تحملك على فعل الأفضل.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3349","text":"قال لي طالب علم : لا تقل : جعله الله في ميزانك ، ولكن قل : جعله الله في ميزان حسناتك ، فقلت له ( فأما من ثقلت موازينه فهو في عيشة راضية ) ولم يقل : موازين حسناته","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3350","text":"سأل حكيما: كم مقدار ما آكل؟ قال: ما يقمع ألم الجوع ولا يبلغ حد الشبع.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3351","text":"تجميل الأخلاق بلا إنفاق؛ أهم من تجميل الأشكال بالأموال.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3352","text":"الدنيا مزرعة، ما تزرعه في الدنيا تحصده في الآخرة، فازرع الأفضل ولا تزرع الحنظل.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3353","text":"الدنيا دار بلاء، من طال عمره فيها فقد الأحباءَ، ومن قصر عمره فقده الأحباءُ.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3354","text":"لا تُبالغ بالانغماس في الشهوات، فإن ملذاتها فانية، وآثارها السلبية باقية.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3355","text":"الاقتصاد يقيك من ذل الدَّين من العباد.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3356","text":"العاقل يجتهد ويقتصد وعلى ربه يعتمد.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3357","text":"بالاقتصاد تدوم النعم، وبالشكر تزيد النعم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3358","text":"ما مضى من الدنيا تبعات، وما بقي أُمنيات، فاستغفروا الله لما مضى، وأحسنوا النية فيما بقى.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3359","text":"رعي الأغنام يُؤَهل العظماء لقيادة الدهماء","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3360","text":"لا تُبالغ في المجاملات والترحيبات؛ فتبدوا أنها متكلفة، ولكن كذلك لا تكن خشنا وحشيا، فعليك بالاعتدال.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3361","text":"عبارة: أنا من طرف فلان، تيسر لك الموافقة بأمان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3362","text":"كن مثيرا للنقاش العلمي، والجدال المعرفي، ولكن بأدب واحترام، لأن حياة العلم بالمناقشة والمذاكرة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3363","text":"عامل الناس معاملة من يثق بهم ولكن احترس منهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3364","text":"أفضل مكياج للتجميل؛ الابتسامة الرقيقة؛ والكلمة الرشيقة؛ والطلة الأنيقة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3365","text":"لا يسأل عنك إلا من يسعد بلقائك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3366","text":"لا تبحث عن المشاكل، المشاكل تعرف عنوان المنازل.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3367","text":"توافقُ شرائحِ المجتمع يجلب التعايش والاستقرار، والاستقرار يجلب الاستثمار.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3368","text":"اختلاف شرائح المجتمع يجلب التفرقة والانتشار، والانتشار يطرد الاستثمار ويجلب والاستعمار.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3369","text":"الفقر ليس من المعايب لكنه ليس من المناقب.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3370","text":"الفقر إذا كان بسبب الكسل والخمول؛ فهو من المعايب عند ذوي العقول.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3371","text":"إذا نزلت الوعول في السهول؛ وتسلقت الجمال قمم الجبال، فقد ساءت الأحوال؛ وتغيرت الرجال، وأقبل النقص وأدبر الكمال.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3372","text":"بعض الحكومات تُؤجل مشروعات هامة بحجة أن كلفتها باهظة؛ ثم تُضطر لتنفيذها بعد أن تتفاقم كلفتها أضعافا مضاعفة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3373","text":"الحكومة تمثل دور الأب بالنسبة للشعب؛ فلا يجوز للأب أن يُفضل بعض أولاده على بعض، فيجب على الحكومة ألا تفضل بعض شرائح الشعب على بعض.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3374","text":"‏إن لم يكن في جيبك نقود، فليكن في لسانك عسل، وفي كلامك أمل، وعلى شفتيك ابتسامة، وفي وجهك بِشر، وفي قلبك سلامة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3375","text":"الوتساب رُبما يكون واصفا جيدا أحيانا لكنه طبيب سيئ، فلا تبادروا بأخذ الوصفات الصحية ولا الخلطات العلاجية منه، حتى تتوثقوا من علماء الاختصاص الموسومين بالتجربة والخبرة والدراية.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3376","text":"من يحلم بالنهوض والتغيير، وهو يُطيل التفكير، ولم يُغادر السرير، فهو في أحلام اليقظة يطير، من غير أدنى تقدم وتأثير","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3377","text":"قال : أول ما مُنحت شهادة الدكتوراه ؛ كان كلما سمعت كلمة - دكتور - تلفت ظننت أني أنا المقصود ، فكنت في زيارة في أحد المزارع ، فسمعت من يقول : دكتور دكتور ، فالتفت وقلت : نعم ، فإذا هو يقول : ثور ثور ويشير إلى ثور ! فعندها خجلت من نفسي ، وأقلعت عن عادتي السخيفة","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3378","text":"غبار العمل نور في وجوه الرجال، وبخور في أبدانهم.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3379","text":"الرجل العاطل ذليل في نفسه؛ ومحتقر في عيون الناس.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3380","text":"خداع عقول الرجال يظهر في صفحات الوجه وفلتات اللسان.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3381","text":"لا تظلم نفسك بالمبالغة بالأحزان على من هجرك.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3382","text":"استعينوا بالنظر إلى عيون من يُخاطبكم لتدركوا ما يُريد أن يخفيه عنكم، لأن العين نمامة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3383","text":"المبالغة في التفاؤل سذاجة، والمبالغة في الثقة بالنفس غرور، والمبالغة في الثناء نفاق، والمبالغة في الجَدِّ وخامة، والمبالغة في المزاح سخافة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3384","text":"السجون العشوائية التي ليس لها أهداف إصلاحية؛ معاهد لتعليم الجريمة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3385","text":"إذا أيس الشيطان من الرجل الصالح استعان عليه بالمرأة الجميلة، فالمرأة الجميلة فخ الشيطان للرجل الصالح.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3386","text":"الضمير هو حضور خشية الله في قلبك، فتحول بينك وبين اقتراف الإثم والخطأ.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3387","text":"كن قويا شجاعا فإن الفُرَص الجيدة؛ لا تُتاح للضعيف الخائف المتردد.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3388","text":"سوف تفقد مكانتك وهيبتك وسمعتك إن كنت تعمل ضد مصلحة وطنك وشعك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3389","text":"العينان تعترف بالحب أو البغض قبل اللسان؛ لأن العين نمامة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3390","text":"ذهبت أُم سقراط بسقراط إلى مُدَرِّسَته كي تنصحه بالاستيقاظ مبكرا ، فقصت عليه قصة فيها أن العصافير التي تسيقظ مبكرا تجد حشرات تأكلها وتطعم صغارها ، والعصافير التي تستيقظ متأخرا لا تجد حشرات تكفي لتأكلها وتطعم صغارها، ثم سألته : ماذا استفدت من القصة ؟ فقال : أن الحشرات التي تستيقظ مبكرا تأكلها العصافير","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3391","text":"لا تحكم على الكتاب من غلافه؛ ولا على الموضوع من عنوانه، ولا على الإنسان من هندامه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3392","text":"أحيانا يكون التجاهل أفضل رد على السفيه.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3393","text":"من أفضل مشاعر السعادة في الحياة أن تُسعد المساكين والمحرومين والمُضطهدين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3394","text":"التواضع معراج الرفعة، ويجلب المودة والوفاء، والاستعلاء يجلب السخط والبغضاء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3395","text":"الفشل الذي يزيد في الحماس هو بوابة النجاح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3396","text":"الزوجة الصالحة الوفية؛ هي التي تبادر في هوى زوجها وهي عروب تقية.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3397","text":"إذا قَدُمَ الإخاء سمج الثناء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3398","text":"ترك الأدب مع الأصدقاء أدب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3399","text":"من الآداب ترك التكلف مع الأصحاب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3400","text":"شكا رجل لزوجته سوء حفظه للقرآن فأقسمت له لو حفظ القرآن كاملاً خلال سنة سوف تُزوجه بنفسها زوجة ثانية، فحفظ القرآن كاملاً في ستة أشهر، فَكَفَّرت عن يمينها واحتفظت ببعلها","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3401","text":"بعض التجار فجار يرتكبون جرائم لا يُعاقب عليها القانون في عِزْ النهار، يُبالغون في الأسعار، مبالغة تدعو للإنكار، ويمتصون دم الفقراء الصغار والكبار، فلا يطلبون رحمة الله ولا يخشون عذاب النار، بسبب الفحش بالغلاء والأسعار، ولا يراعون المساكين وأم اليتامى الصغار.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3402","text":"اللغة العربية توصف بأنها لغة شجاعة، والعربي القُح إذا تكلم في الحوار والمحادثة؛ لا يتعقر ويتنطع ويتكلف ويتشدق؛ بل يُلقي الكلام على عواهنه، بالحذف والخطف والاختلاس، تعويلا على فطانة السامع، واستعانته بالسياق والسباق والفحوى العام.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3403","text":"كانت الوصيفة الخاصة بالأمير واقفة بجنبه ، وبين يديه وزيره الجديد ، وفُتُحت أمامه صرتان هدية ، إحداهما فيها أدوات زينة ومجوهرات ، والأُخرى ملابس حرير فاخرة ، فقال لوصيفته : اختاري ، فقالت : أُريد الصرتين ، فقال : واحدة فقط ، فنظرت للوزير تستشيره ، فغمز بعينه للصرة اليمنى ، فلمحه الأمير ، فخدم الأمير عشرين عاما وهو يغمز بعينه ، ليُوهم الأمير أنها حركة غير إرادية","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3404","text":"المعاملة الطيبة تفتح لك أبواب القلوب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3405","text":"من أمارات السفيه أنك إذا زدته احتراما ازداد غرورا ومباهاة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3406","text":"لا تبالغ في المدح حتى لا يُعد نفاقا.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3407","text":"هل تريد أن تستمر علاقتك الحميمة مع الناس؟ فعليك أن تتصف بمكارم الأخلاق: الاحترام الاهتمام الإكرام السلام الإنسجام الوئام وعدم الاصطدام على الدوام.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3408","text":"من يمتلك مواهب وهوايات وابداعات يحتاج إلى جرأة وشجاعة حتى يُظهرها ويُبرزها.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3409","text":"اقتبسوا التجارب من التاريخ ومن كبار السن.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3410","text":"المتفائل يستسهل الصعب، والمتشائم يستصعب السهل.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3411","text":"قال : مالي أراك سعيدا ؟ قال : لأن أعظم إنجازاتي تحققت اليوم، أقنعت زوجتي بأن نوفر هذا العام مصاريف السفر ، فوافقت على أن أعطيها قيمةالتذاكر والفنادق","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3412","text":"كل عمل ناجح وراءه رجل يمتلك إرادة قوية.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3413","text":"التاريخ يعيد نفسه لأن أغلب الناس لا يتعلمون من التاريخ.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3414","text":"الذي يتعض بالتاريخ لا يُعيد أخطاء السابقين.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3415","text":"إذا حضرت العِقبان هربت الصقور والغِربان.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3416","text":"التاريخ خِزانة خبرات وتجارب.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3417","text":"هيبة الدولة تُعرف من هيبة جنديها البسيط.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3418","text":"الطيور التي تُولد في القفص لا تعرف طعم الحرية؛ فهي لا تبحث عنها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3419","text":"السفينة في المرفأ آمنة؛ لكنها لا تكسب المال حتى تخرج من المرفأ، وكذلك الرجل لا يكسب المال حتى يغادر منزله.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3420","text":"الميل غير محمود إلا الميل إلى الحق والصواب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3421","text":"بعض الناس يفتقرون إلى الأموال، وفي الحقيقة أن أكثرهم إنما يفتقرون إلى معرفة الخطوات التي ينبغي لهم أن يسلكوها، كي تُعينهم على كسب المال الحلال، الذي فيه القُنية والبركة وحسن المآل، أو لا تُوجد أمامهم فرص للعمل، فينبغي لحكومتهم أن تيسر لهم الطرق والفرص التي تعينهم على كسب المال بعرقهم ومجهودهم، لتحفظ لهم كرامتهم في وسط مجتمعهم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3422","text":"ليس القَوِيُّ من يبطش ويظلم ويعتدي؛ لكن القوي من يُدافع عن المظلوم، ويُطالب بحقوق المحروم، وينصر الضعيف المكلوم، ويُكسب المعدوم، وعلى المبادئ يُحافظ ويدوم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3423","text":"إن الله سبحانه خلق ما ينفع الناس كالعنب، ولكن بعض الناس صنعوا مما خلق الله ما يضر الناس؛ صنعوا من العنب خمرا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3424","text":"طريق النجاح: الخطوات الأولى متعثرة، والأخيرة مبدعة، وما بينهما مترقية.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3425","text":"هناك كثير من الأعمال النافعة المتاحة التى يمكن للإنسان أن يحققها؛ لكن تنقصه قوة الإرادة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3426","text":"طريق النجاح لا يخلو من العثرات والصعوبات؛ لكن مع المثابرة والمصابرة سوف تُحقق النجاح والفلاح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3427","text":"التواضع من سجايا الأنبياء","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3428","text":"إذا أنا أمير وأنت أمير فمن يسوق الحمير","kind":"mathal","topic":"السياسة والقيادة","note":"وأتبعه بقوله: فجاء اللص فساقها بما تحمله من الأموال","source":"شذرات (ملف وورد)"},{"id":"m3429","text":"شطر السعادة عدم مراقبة الناس.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3430","text":"شطر الحكمة ترك ما لا يعنيك.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3431","text":"شطر الندى كف الأذى.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3432","text":"شطر النشاط الصحة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3433","text":"شطر الصحة الوقاية.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3434","text":"شطر الوقاية النظافة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3435","text":"شطر النظافة الوضوء","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3436","text":"شطر الإيمان الصبر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3437","text":"شطر الهيبة الصمت.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3438","text":"شطر المعيشة الاقتصاد.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3439","text":"شطر الحب الاهتمام.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3440","text":"شطر الضيافة حسن الاستقبال.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3441","text":"شطر الاستقبال الابتسامة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3442","text":"شطر الوفاء تذكر الأصدقاء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3443","text":"إذا قدمت خدمة للناس فأنت رجل طيب المعدِن.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3444","text":"‏أعظم الناس قدراً من ظهر اسمه في أعمال الخير، وخفي شخصه، وأعظم منه من خفي اسمه وشخصه في أعمال الخير؛ عن أهل الأرض، وعرفه من في السماء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3445","text":"تحصيل العلم بطلبه ومجالسة العلماء والحكماء، وقراءة الكتب النافعة، ولا يثبت ويرسخ العلم إلا بالتعليم والتدريس، والتأليف والمناقشة والمحاورة والمذاكرة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3446","text":"من سار خلف العلماء رشد، ومن سار خلف السفهاء فسد.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3447","text":"من جالس العقلاء شاركهم في عقولهم، ومن جالس الدهماء صار واحدا منهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3448","text":"إذا أراد الله بقوم خيرا وقاهم من كثرة الجدل، ووفقهم للعمل.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3449","text":"إذا أراد الله بقوم الخذلان فتح عليهم أبواب الجدل، ولم يُوفقوا للعمل.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3450","text":"إذا أردت أن تُكلم الله تعالى فاذكر الله، فإن الله يسمعك ويذكرك، وإذا أردت أن يكلمك الله تعالى؛ فاقرأ القرآن فإن الله يكلمك، والقرآن أفضل الذكر، وفي كلا الحالين استحضر بقلبك أنك تكلم الله، وأن الله يكلمك، فإن هذا يُعينك على الخشوع، ويُبعد عنك الوساوس وغياب الوعي والغفلة، ويملأ قلبك نورا وطمأنينة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3451","text":"عَظَمة الفرد ليست بِعِظم جسده وطول قامته، ولكن بصفاء نيته وكثرة علمه، وجمال طبعه وأدبه، وكذلك عظمة الدولة ليست بكثرة سكانها، وكبر مساحتها؛ ولكن بكثرة علمائها ومفكريها، وعدالة قوانينها والالتزام بتطبيقها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3452","text":"المرأة السلفع: السليطة الجريئة على الرجال، الخراجة الولاجة، التي تزف العمال بالصوت الجهوري، المرأة الحديدية ذات الشخصية القوية، الجادة الحازمة، فاشلة في حياتها الزوجية، لما فيها من صفات الرجال وخصال الذكورة، في التصرفات والطباع والصورة.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3453","text":"بشروا من لزم الشكر والاستغفار فبالشكر تزيد النعم وبالاستغفار تزيد النعم وتندفع النقم","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3454","text":"بعض الكلمات مثل بُنيات النخلة، وبعض الكلمات مثل شوك النخلة، فالأولى تمنح الغذاء والحلواء، والثانية تُثير الألم وتُسيل الدماء، فتوخى الكلمات العذبة المهذبة المذهبة، وتجافى عن الكلمات النابية المنافية الجافية.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3455","text":"العبادات والأذكار التي فيه عَدٌّ وحساب وضبط واستحضار، مثل الطواف والسعي والوضوء وعدد الركعات، والأذكار في الصلاة، والتي بعد الصلاة، والتي في الصباح والمساء، وغير ذلك. تقوي في الإنسان ملكة الذاكرة والحفظ والضبط والإحصاء والاستحضار، ومع المداومة تُبعد عنه ضعف الذاكرة والنسيان والخطأ والذهول.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3456","text":"استخر ربك واسلك دربك واتبع سِربك وانشر حُبَّك وانثر حَبَّك وأوقد شَبَّك وأرح جنبك وقرب كلبك واحذر ذئبك","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3457","text":"داري على شمعتك وحافظ على سمعتك واحرص على لمعتك واستمر على رفعتك واستر على دمعتك وتقدم على دفعتك","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3458","text":"إذا أردت أن تعرف مستوى الأخلاق في مجتمع ما؛ فانظر إلى الفقراء والضعفاء والغرباء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3459","text":"الرجل العاقل إذا أراد أن ينصح الناس يبدأ بنفسه وأهل بيته.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3460","text":"تعامل مع الإنسان كما هو الآن لا كما كان في سابق الزمان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3461","text":"لو وصفت لي بستانك سوف أنسى، ولو رأيت بستانك يمكن أنسى، ولو تمشيت بين أشجاره، وقطفت من ثماره، وخطفت من أزهاره، وتعشيت في ليله وتغديت في نهاره فلن أنسى.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3462","text":"لو كان بالإمكان جمع دول الخليج ثم العرب ثم المسلمين؛ على قلب رجل واحد، وكلمة واحدة؛ لتغيرت أحوال العالم إلى الأفضل والأحسن؛ لأن المسلمين هم حراس الفضيلة وأعداء الرذيلة، ومعهم الحق وصواب البيان، والتوحيد والإيمان.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3463","text":"المناقشات العلمية والمناظرات الأدبية؛ تصقل الأذهان، وتُنير الجَنان.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3464","text":"لا تفتح محفظة نقودك وفقير ينظر إليك؛ إلا إذا كنت تريد أن تتصدق عليه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3465","text":"لا يُولد المولود عظيما، وانما يكون عظيما بالتربية الجيدة والتعليم الجيد.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3466","text":"من قتل غيره فقد ساعد على قتل نفسه؛ في يوم من الأيام.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3467","text":"رُبما أذلَّ الله القويَّ بالضعيف؛ حتى الأسد لا يستطيع أن يحمي نفسه من الذباب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3468","text":"الفأس آلة حياة ونماء، والسيف آلة موت وفناء.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3469","text":"لا يكون طالب العلم عالما حتى ينظر إلى الأقوال والآراء، ولا ينظر إلى القائلين والمفتين، ولا يتأثر بهم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3470","text":"إذا جادلت صديقك فاحرص على ألا تخسره، أكثر من حرصك على الانتصار عليه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3471","text":"من يملك صفة الصبر والصمت لن يخسر أصحابه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3472","text":"لا شيء يدوم في هذه الحياة، إلا ذكر الله وما والاه من الطاعات، فاحرص على المواظبة عليها.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3473","text":"المسلمون عندهم تجارة عظيمة وبضاعة عظيمة تجارة الإيمان وبضاعة الرحمان فعليهم أن يجتهدوا في تبليغها وتوصيلها فإن عزهم ومجدهم وفوزهم ونجاتهم في دينهم وإسلامهم","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3474","text":"الصواب ابن الخطأ، والنجاح ابن الفشل.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3475","text":"إذا تكرر الفشل فلا تيأس؛ فإن الفشل هو التجارب التي تسبق النجاح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3476","text":"أحسن تربية أبنائك؛ فلولا الجذور لما أثمرت الغصون.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3477","text":"الضمير الحي هو الذي يميز بين الخير والشر، فإذا عمل خيرا حمد الله وشكر، وإذا عمل شرا اعتذر واستغفر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3478","text":"اختر زوجة صالحة مناسبة لك؛ فإنها تمثل لك شطر سعادتك، وأنت تمثل لها شطر سعادتها.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3479","text":"العمر أقصر من أن تهدره في الخلافات والنزاعات والعداوات.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3480","text":"التواضع يرفع من شأنك؛ والتعاظم يُحقر من شأنك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3481","text":"الأم حضانة وروضة ومدرسة وجامعة الأم معراج الدعوات ومهبط الرحمات وباب من أبواب الجنة ودعاؤها يصعد إلى السماء بطرفة عين والأم كنز من كنوز الرحمة والتوفيق","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3482","text":"تغريدات الوتساب الصحية، بالوصفات والتركيبات العلاجية لها تأثير كبير على القناعات النفسية وربما تكون عديمة الجدوى والنفعية لكن لها جاذبية قوية والسبب هو للحاجة الطبيعية، والوصفة غير كيميائية","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3483","text":"كل علم أو فن أو صناعة أو مهنة أو حرفة يُسأل عنها أهلها وعلماؤها وخبراؤها؛ فما قال عنه علماء الحديث بأن هذا الحديث صحيح فهو صحيح، وما قالوا عنه بأنه ضعيف فهو ضعيف.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3484","text":"إذا تبين لك أن تحقيق الهدف مُحال فأنت بالخيار: إما أن تجرب طريقة أُخرى لتحقيق الهدف؛ أو تغير الهدف، اختر أيسرهما، المهم أن لا تعيش بدون تحقيق هدف يعود عليك بالخير في الدنيا والآخرة؛ أو في أحدهما، فإن انشغالك بتحقيق أهداف نافعة في الدنيا أو الآخرة؛ يجعلك تشعر بقيمة العمل وقيمة نفسك، وهذا الشعور يجعلك تشعر بالسعادة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3485","text":"الخلاف في الرأي لا يفسد للود قضية عند ذوي عقول نيرة ونفوس نقية ويجمعنا على مائدة واحدة فيها الكنافة واللحمة المشوية","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3486","text":"إذا ذكرت الله تعالى غِبَّ كل خسارة أو بلاء، فما ربحته أكثر مما خسرته، فواسِ نفسك غِبَّ كل خسارة أو بلاء بذكر الله تعالى، مع رجاء أن يعوضك الله خيرا منها.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m3487","text":"ما دام الفساد ينخر في البلاد فلا مفر من تدهور الاقتصاد ومعاناة العباد من الغلاء والكساد وعصور الأجيال مُهددة بالشقاء والإجهاد لم يترك لهم الأجداد قوة اقتصاد في البلاد وخارج البلاد","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3488","text":"السعي لتحقيق هدف إيجابي سوف يكون له مردود إيجابي على النفس، قبل المردود المادي النفعي، ولو أن تعمل بيوتا للحمام، أو أقفاصا للعصافير، فمن الأفضل للسعادة النفسية أن يكون لك دائما هدف إيجابي تسعى لتحقيقه، فتشعر بقيمة العمل وقيمة نفسك.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3489","text":"لا تستحوذ على الحديث في المجلس؛ ودع الحديث مشاركة ومجاذبة بين الحضور، فهو أنجع وأمتع، وللسآمة والملل والكلل أدفع.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3490","text":"ناقش الأحباب، مع مراعاة الآداب، لبيان الصواب، لا للإنتصار على الأصحاب.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3491","text":"الطالب شارب والمعلم حالب، فعلى قدر شغف الطالب بالمعرفة والتفهيم؛ يجود المعلم بالشرح والتعليم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3492","text":"إن الله تعالى أرحم بعبده من الأُم بوحيدها، فعلى العبد المؤمن أن يتقرب إلى الله بالنوافل؛ حتى يُحبه الله تعالي، فإذا أحبه الله تعالى هداه ووفقه وسدده واستجاب دعاءَه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3493","text":"رُبَّ أكلة حرمتك من أكلات.","kind":"mathal","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3494","text":"لكل حي داء، ولكل داء دواء، ولكل دواء شفاء، ولكل شفاء حمد لرب السماء.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3495","text":"من كتم الطبيب مرضه أساء إلى نفسه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3496","text":"من لم يتجرع مرارة الدواء؛ لم يظفر بحلاوة الشفاء.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3497","text":"اجبروا الخواطر، وغضوا النواظر، وراعوا المشاعر، فمن جبر للضعفاء الخواطر؛ نجاه الله تعالى من المخاطر، وعمروا المساجد، واصطلحوا فالتصالح خير من التفاضح، ولا تدخلوا في المخافر، وانشروا الخير واهجروا الفظ المُكابر، وقدموا العون للوافد والعابر والمسافر، تنالوا رحمة ربكم، وهو للذنب غافر.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3498","text":"لا يلزمك أن تُسعد كل الناس؛ ولكن يلزمك ألا تُؤذ أحدا من الناس.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3499","text":"الذي ما تتعب فيه يداك، ما تبكي عليه عيناك.","kind":"mathal","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3500","text":"امْلِكْ من الدنيا كل ما شئت؛ ولكنك ستغادرها كما جئت.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3501","text":"لن تكون قدوة لأبنائك؛ إلا إذا أخفيت عنهم كل عيوبك وأخطائك.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3502","text":"من لم يتوقف عن مزاولة الرياضة فلا يزال شابا ولو كان كبيرا، ومن توقف عن مزاولة الرياضة فهو كبير ولو كان شابا، فالمقياس العملي للشباب هو الحيوية والحركة والنشاط، والسباحة والسياحة في أحضان الطبيعة وأرجائها.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3503","text":"التوكل على الله أن تكون ثقتك بالله أعظم من ثقتك بنفسك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3504","text":"من قصد الخير لن يعدم الخير.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3505","text":"لو تذكرنا آجالنا لأصلحنا أعمالنا.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3506","text":"الوتساب شارع جسر نفق تمر عليه شاحنات اللبن والحليب شاحنات الزور والتكذيب شاحنات الباطل والتهريب فاحذروا شر الوتساب واخذوا منه ما طاب ودعوا ما خاب","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3507","text":"الضمير الحي هو النور الذي يميز به الإنسان الخير من الشر، فيعمل الخير ويدع الشر، وأساس الضمير الحي يتبلور من حسن التربية الإيمانية والمدوامة على الصلاة، والتعليم النافع، والعادات الحميدة، والأخلاق المجيدة والأفكار السديدة، ومراقبة الله سبحانه وتعالى، واستحضار الموت والآخرة والحساب؛ للتغلب على كيد الشيطان والهوى والنفس الأمارة بالسوء.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3508","text":"التسويف سيف من سيوف الشيطان، ليصد به الإنسان عن التوبة وفعل الخيرات، حتى يبغته الممات، فيدخل النار ويخسر الجنات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3509","text":"بعض التجار فجار يُبالغون في الأسعار ويخادعون بالدينار ويغشون بالميزان ولا يخشون الديان فلا يرحمون الفقراء ولا يراعون الغرباء هَمُّهُم جمع المال ويظلمون أبا العيال لأن من أمن العقاب وسلم من العتاب أساء بجملة الآداب","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3510","text":"جاري غني وأنا فقير اشترى تلفزيون 65 بوصة وأعطاني القديم، اشترى جوال أيفون جديد وأعطاني القديم، اشترى أثاث جديد وأعطاني القديم، وقبل اسبوع تزوج ثانية وإلى الآن أنا منتظر وما أدري لماذا تأخر !","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3511","text":"لا يُمكن أن تكون دولة عظمى راعية للسلام وداعية له، وهي من أعظم الدول التي تصنع الأسلحة المتطورة الفتاكة، وتزود بها الدول المتخاصمة والمتحاربة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3512","text":"لا تسأل عما لا ينفعك فيشغلك عن أن تسأل عما ينفعك.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3513","text":"من أضمر خيرا ظهر في فلتات لسانه وحركات نظراته ومحياه، ومن أضمر شرا ظهر في فلتات لسانه وحركات نظراته ومحياه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3514","text":"الحريص محروم، والحاسد مغموم، والبخيل مذموم، والمسرف ملوم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3515","text":"أركان الحب أربعة: الاهتمام، الاحترام، العطاء، الوفاء","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3516","text":"نحن لا نجرب المستجدات الحديثة ليس لأنها صعبة، بل هي صعبة لأننا لا نجربها.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3517","text":"لا تذكر الخير الذي قدمته للناس؛ بل اذكر الخير الذي قدمه لك الناس.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3518","text":"من الغبن العظيم أن تتمسك بِدِين أنك تعلم أنه باطل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3519","text":"بعض السعادة مصدرها شعور الإنسان بأنه سعيد، وبعض التعاسة مصدرها شعور الإنسان بأنه تعيس، فحاول أن تُقنع نفسك بأنك سعيد، واستعن بالنظر إلى من هو دونك في الدنيا، ولا تنظر إلى من هو فوقك في الدنيا.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3520","text":"من يجعل تعاليم الشريعة خلف ظهره كمن يسير ليلا في أرض وعرة، ويجعل النور خلف ظهره، فلا يأمن من العثار، وكذلك هو لا يأمن من عذاب النار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3521","text":"في بعض البيوت قد يكون بين الزوجين طلاق صوري، يعيشان في بيت واحد ولكن لا يتكلمان ولا يتراءان، وآثرا هذه الكيفية على الطلاق، للمحافظة على كيان الأسرة، ولستر أحوالهما الخاصة، ونحن نُفضل لهما الإبقاء على الحد الأدني من التواصل، مثل السلام والسؤال عن الصحة، وما شابه ذلك، ولو عن طريق الهاتف أو الأولاد، ولا يكون انقطاعا تاما، لأن المقاطعة بين المسلمين لا تحسن شرعا ولا عقلا ولا أخلاقا.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3522","text":"إذا أردت أن تجني بُنيات النخلة فاحذر من شوكها. إذا أردت أن تجني لعاب النحلة فاحذر من لسعها. إذا أردت أن تجني حنان زوجتك فاحذر أسَلَة لسانها","kind":"hikma","topic":"الحياة الزوجية","note":"أسَلَة لسانها: طرفه أو شوكته","source":"شذرات (ملف وورد)"},{"id":"m3523","text":"أينما وجدت الجيفة وجدت النسور تتنافس وتتنازع عليها، وأينما وجدت المال ففثَمَّ التنافس والاستئثار والاختلاس والرشاوَى والسرقات والنزاعات والاتهامات، فليسوا على قلب رجل واحد، واهتمامهم ينصب على مصالحهم الشخصية لا على الوطن والمواطنين والمستهلكين، فلا يهتمون بالإصلاح والتطوير والتقدم، ولعل هذا مثال لحال بعض البلدان المتخلفة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3524","text":"إن الله يرفع عبده بقدر تواضعه له.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3525","text":"الفشل هو التجارب التي تتعلم منها طريق النجاح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3526","text":"الزوجة الذكية هي التي تعرف ماذا يريد زوجها قبل أن ينطق ببنت شفة.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3527","text":"الإفراط بالتواضع مهانة، الإفراط بالمجاملة نفاق، الإفراط بالوقاية خوف، الإفراط بالشجاعة تهور، الإفراط بالحلم ذلة، الإفراط بالاعتزاز كبرياء، الإفراط بالعقوبة ظلم، الإفراط بالتسامح تسيب، الإفراط بالعتاب قطيعة، الإفراط بالنصيحة تنفير، الإفراط بالاعتزال توحش، الإفراط بالأكل مرض، الإفراط بالبخل شح، الإفراط بالإنفاق تبذير، الإفراط بالشدة قسوة، الإفراط باللين ضعف، الإفراط بالحذر وسواس، الإفراط بالراحة خمول، الإفراط بالضحك خفة، الإفراط بالعبوس مقت، الإفراط بالطعام تُخمة، الإفراط بالجوع هزال، الإفراط بالكلام هذر، الإفراط بالصمت ثقل دم، الإفراط بالزيارة ملل، الإفراط بالهجران نسيان.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3528","text":"إن لم تكن في عجلة من أمرك فسوف تنجز عملك بإتقان.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3529","text":"إن أردت الفوز فتحول من حالة الدفاع إلى حالة الهجوم.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3530","text":"الحياة هي مدرسة التجارب واكتساب الخبرات، وهي مرحلة ما بعد اكتمال الدراسة النظامية.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3531","text":"العباقرة لا يُولدون عباقرة، بل بالتربية والتعليم والتجارب، والمثابرة والمصابرة على التحصيل والتنوير، وشيء من الإلهام، ثم يصبحون عباقرة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3532","text":"بعض مشاكل الدول مثل الأورام غير الحميدة: كزيادة الهدر المالية، والرَشاوَى السرية، والاختلاسات المليونية، والمناقصات الصورية، وغسيل أموال مجهولة الهوية، والتساهل في تطبيق المواد القانونية، مع المختلسين والحرامية، إذا لم تُكتشف في بداياتها، وتُعالج باستئصالها، سوف تستفحل وتنتشر، ثم يصعب علاجها، فتكون نهايتها الخراب والدمار، والموت نهاية المسار.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3533","text":"الدنيا صالة المسافرين وبوابة العابرين.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3534","text":"الدنيا موسم الزراعة والآخرة موسم الحصاد.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3535","text":"الدنيا دار الابتلاءات والآخرة دار الجزاءات.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3536","text":"العاقل يُنظم إنفاقه على حسب دخله لا على حسب شهوته؛ حتى لا يُضطر للإقتراض.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3537","text":"من رتب إنفاقه على حسب دخله عاش عزيزا مرفوع الهامة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3538","text":"استنارة العقل للتمييز بين الحق والباطل باب من أبواب الهداية.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3539","text":"دخل أعرابي مكتبة كبيرة فيها كتب كثيرة تنطح السقف، فعجب من كثرة الكتب، ثم قال:أنا أعرف كل ما في هذه الكتب، فتعجب الناس فقالوا له ما فيها: فقال: فيها أيها الإنسان كن إنسانا صالحا ولا تكن إنسانا فاسدا","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3540","text":"فصاحة كلماتك وبلاغة عباراتك واختيار موضوعاتك؛ أمارة على مستوى ثقافتك ورفعة أخلاقك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3541","text":"إن الله يبتلي عبده المؤمن في الدنيا ليرفع درجته في الآخرة، ويزيد في حسناته ويكفر من سيئاته على إيمانه وصبره، وليسمع دعاءه وابتهاله في صلاته وسجوده.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m3542","text":"إن شعرت بآلامك فأنت على قيد الحياة، وإن شعرت بآلام غيرك فأنت تمتلك مشاعر إنسانية.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3543","text":"سألتْ بعلها في سنة أُولى حب: أيهما أجمل أنا أم القمر؟ فقال: إذا نظرت إلى مُحياك نسيت القمر، وإذا نظرت إلى القمر تذكرتك","kind":"ghazal","source":"شذرات (ملف وورد)"},{"id":"m3544","text":"لأن تكون ساعتك من نحاس بدينار ووقتك من ذهب، خير من أن تكون ساعتك من ذهب بألف دينار ووقتك من نحاس.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3545","text":"سأل القاضي المتهم : ما هي تهمتك ؟ قال : سرقت حبلا باليا طوله مترين من هذا الرجل ، فقال القاضي : هل اشتكيته لأجل الحبل ، فقال : نعم ! لكن كان في طرف الحبل بقرة","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3546","text":"رأيت الناس يمدحون الجود والكرم باللسان ولا يفعلونهما بالكف والبنان، ورأيتهم يذمون الشح والبخل باللسان ويفعلونهما بالكف والبنان، ورأيت الجود والكرم في الكتب والمكتبات أكثر مماهي في الأفراد والجماعات.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3547","text":"معاول هدم الدولة سياسة الرشوة وفنجان القهوة سياسة هذا ولدنا وهذا يُؤيدنا سياسة اخمط وسافر وهدد وعافر سياسة النفط والشفط سياسة الواسطات والمحسوبيات سياسة الاختلاسات وعمولات المناقصات سياسة المناصب مكاسب سياسات المشاريع الكبيرة بالنصب والحيلة من معاول هدم الدول","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3548","text":"الله خالق عظيم رحيم والشيطان مُضل رجيم، فمن آمن بالله العظيم وكفر بالشيطان الرجيم فاز الفوز العظيم، وكان من أصحاب اليمين وجنة النعيم، ومن آمن بالشيطان الرجيم وكفر بالله العظيم فقد خسر الخسران المبين، وكان من أصحاب الجحيم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3549","text":"أنت اليوم ذاهب للخِطبة فإذا سألوك : ما مذهبك؟ قل: حنفي ولا تقل: شافعي، فهم متعصبون ، فلما سألوه نسي الجواب فقال: حنفشعي","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3550","text":"إن خفت من المخلوق فررت منه، وإن خفت من الخالق فررت إليه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3551","text":"ركوب الأخطار من غير اضطرار عنوان حماقة الصغار.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3552","text":"تجنب العار من سجايا الأبرار.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3553","text":"لكل حسنة ثواب ولكل سيئة عقاب، ويتوب الله على من تاب.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3554","text":"ما تستحي أن تفعله جهرا فلا تفعله سرا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3555","text":"أول درجات الكمال أن تتخلى عن النقص.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3556","text":"حفظ التجارب خِزانة العقل.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3557","text":"رأيُ المجربِ أقرب إلى الصواب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3558","text":"التجارب علوم متجددة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3559","text":"موعظة التجارب يقينية.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3560","text":"كفى بالتجارب زاجرا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3561","text":"المودة قرابة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3562","text":"الأيام أوعية الأحداث.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3563","text":"التجارب علوم مستفادة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3564","text":"أكثركم علما أكثركم تجاربا.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3565","text":"الخبرة بنت التجارب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3566","text":"الحقائق بنات التجارب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3567","text":"الحياة الزوجية هي النواة الأولى لإنشاء وبناء الحياة الجماعية، تجمع بين قرابة الزوج وقرابة الزوجة، فأقارب الزوج أعمام أطفاله، وأقارب الزوجة خوال أطفاله، بل تجمع ببن العائلتين والفخذين والقبيلتية، وابن اخت القوم منهم، ومن هذه القرابات والعلاقات تتكون المجتمعات والشعوب.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3568","text":"استر فقرك وانشر فضلك.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3569","text":"إذا وعظت فابدأ بنفسك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3570","text":"من تعلم من التجارب أمن من شرِّ العواقب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3571","text":"من لم يتعلم من التجارب لم يسلم من المتاعب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3572","text":"كثرة التجارب تقيك من المعاطب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3573","text":"جميع من في الديوانية استقبلوا أبا فهد بالتبريكات والمعانقات، بهنئونه بالزواج بالثانية، تعجب منهم وقال ما حصل ، قالوا : شايفينك مع واحدة صغيرة في السوق أمس ، قال هذه أم فهد عملت لها إعادة تدوير ، قالوا : كيف ؟ قال : سفرتها مع أخيها إلى منتجع صحي","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3574","text":"اللغة اكتساب وليست فطرة","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3575","text":"خير تجاراتكم تجارتكم مع الله، فأكثروا من ذكر الله، فذكر الله خفيف على اللسان، ثقيل في الميزان، ينير الجَنان، ويجلب الاطمئنان، وفيه ثواب عظيم على مَرِّ الزمان.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3576","text":"من أهان السلطان تولى أمره السجان.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3577","text":"منازعة السلطان تسلب الأمان","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3578","text":"السجن قبر الأحياء، والقبر سجن الأموات؛ فنوروه بكثرة ذكر الله وكثرة الحسنات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3579","text":"اعرف صديقك عندما يتبوأ منصبا محمودا، أو عندما تحتاج إليه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3580","text":"شهادة الأعداء على الأعداء لا تسلم من الافتراء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3581","text":"الخروج على السلطان أجل مستعجل.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3582","text":"لا تظلم من هو دونك فإن الله أقدر عليك منك عليه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3583","text":"إذا أردت أن يكون فراغك أفضل من عملك فاملأه بذكر الله تعالى.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3584","text":"أفضل الذكر ذكر الله، وأفضل الشكر شكر الله، فأكثر من ذكر الله وشكره.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3585","text":"أفضل الأعمال ذكر الله تعالى، والذكر هو روح العبادات، وما شُرعت العبادات إلا لذكر الله تعالى","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3586","text":"(ادخلوا بالمهاف واخرحوا باللحاف)","kind":"mathal","topic":"الصحة والنفس","note":"كان القدماء ينامون شتاء في الحجرات، وصيفا خارج الحجرات وعلى السطوح، ففي آخر الحر يدخلون الحجرات ويستعينون بالمهاف، حتي يتوقوا نسمة باردة ليلا فتمرضهم، وفي آخر البرد يخرجون مع اللحاف، لأن البرد في ادباره لا يضر ولا يُمرض، بخلاف البرد في اقباله","source":"شذرات (ملف وورد)"},{"id":"m3587","text":"استعينوا على أعدائكم بالدعاء، فإن الدعاء سلاح الأولياء.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3588","text":"أكثروا من الدعاء فإن الله يحب من يسأله لجلب الرخاء ودفع البلاء.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3589","text":"من سأل الله أعطاه، ومن توكل عليه كفاه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3590","text":"طوبى لمن قدَّم العمل قبل حضور الأجل، ولم يغتر بطول الأمل.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3591","text":"الموت أقرب إليكم من شسع نعالكم، فاستعدوا له بصالح أعمالكم.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3592","text":"لكل أجل حضور، والله يعلم ما في الصدور.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3593","text":"نوروا بذكر الله القبور، وتطهير ما في الصدور.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3594","text":"هنيئا لمن بادروا آجالهم بإصلاح أعمالهم وإخلاص نياتهم.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3595","text":"عجبت لمن يغفل عن الموت وهو يشهد الأموات.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3596","text":"ما أفلح من نسي الأجل وغره طول الأمل.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3597","text":"الشيء حلو في محله، الفلفل حلو في محله، الملح حلو في محله، القهوة حلوة في محلها، الحار حلو في محله، البارد حلو في محله، الابتسامة حلوة في محلها، العبسة حلوة في محلها، كلمة لينة حلوة في محلها، كلمةجافة حلوة في محلها، الحلو مُرٌّ في غير محله والمرُّ حلو في محله.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3598","text":"لا بأس في صرف النفقات الكبيرة على انجاز المشروعات الكبيرة التي سوف تُحقق أرباحا كبيرة ومصالح كثيرة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3599","text":"أينما كنت فكن رجلا صالحا مهذبا مؤدبا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3600","text":"لا يزال الرجل مستورا حتى تُرافقه في سفر، أو يأتيه ثراء مفاجئ، أو يتبوأ منصبا كبيرا، أو تُشاركه في تجارة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3601","text":"أكثر أصدقائي لهم فضل علي: من يمنحني أو يُرشدني إلى كتاب يزيد في عقلي عمقا، وفي علمي فهما.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3602","text":"لا تجعل المشاجرات والمشاحنات تحول بينك وبين تحقيق أهدافك السامية.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3603","text":"عندما أنقذ الراعي النعجة من براثن الذئب وأنيابه، ظنت أنه يحافط على حياتها، لكنه سارع في ذبحها حتى لا تموت من جراحات الذئب، مسكينة النعجة إن سلمت من فكي الذئب لم تسلم من فكي الإنسان.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3604","text":"في تقلب الظروف والأحوال تظهر معادن الرجال.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m3605","text":"لا تعتادوا العادات السيئة فالفطام شديد.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3606","text":"الفضل للمبتدي ولو أجاد المقتدي.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3607","text":"من سجايا الأنبياء عدم الإسراف في جميع الأشياء حتى الماء والكهرباء","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3608","text":"لا تُجاهد من أجل تحقيق النجاح فقط، بل من أجل تحقيق النجاح الذي ينفعك وينفع الناس في دينهم ودنياهم، وبهذا سوف تُحرز النجاح والفلاح في الدارين: الدنيا والآخرة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3609","text":"لا تهدر وقتك في الماضي، حسبك أن تأخذ منه الدروس والعبر.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3610","text":"من أجل أن ترتقي تحتاج إلى شيء من الأمل والمغامرة والتغيير، لكن من غير تهور.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3611","text":"من التفاؤل أن تنظر إلى الفشل على أنه تجارب وخبرات.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3612","text":"الصيام تقوية لإرادة الإنسان وتذكيره بالفقير والمحروم والجوعان ودروس تقوية للتقوى والإيمان","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3613","text":"وراء كل نجاح جهاد ومثابرة وصبر ومغامرة وزوجة متعاونة لا تُشعل مناورة بل تسانده في الرأي والمحاورة وتُشجعه على النشاط والمصابرة","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3614","text":"أفضل ما وعظك تجاربُك.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3615","text":"دواء الأحمق الإعراض.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3616","text":"أضاع أدبَه من طاوع غضبَه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3617","text":"من اعتاد شيئا هان عليه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3618","text":"إذا أردت أن تُقَيِّم أداء حكومة؛ أو أداء نواب عن شعبهم، فاسمع ما يقوله الناس عنهم في مساجدهم وأسواقهم ودواووينهم فهو نبض وشعور شعبهم الصادق.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3619","text":"قال همام:، سألت رجلا مخضرما وخبيرا بالسياسة وشؤون البلد. ما هي انجازات مجلس الأُمة؟، قال لي: انظر إلى واقع الشعب وأنت تعرف انجازات مجلس الأُمة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3620","text":"عندما كنت صغيرا وذاكرتي خالية كنت أحفظ كل شيء بالتدريج، فلما ترعرعت وكبرت؛ عرفت أشياءكثيرة ومهمة، ثم بدأت أنساها بالتدريج، فذاكرة الإنسان صغيرة تكبر ثم كبيرة تصغر، فهي مثل دورة القمر كبير بين صغيرين.","kind":"hikma","topic":"الحياة والزمن","note":"على لسان حارث","source":"شذرات (ملف وورد)"},{"id":"m3621","text":"من طلبه السلطان فارقه المنام والأمان.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3622","text":"الذكر الجميل تزكية عامة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3623","text":"الرفقة الصالحة جنة الدنيا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3624","text":"غِبَّ كل عجلة ندامة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3625","text":"إذا رفسك الحمار فلا ترفسه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3626","text":"لا تُقارن الحسن بالأحسن حتى لا تزهد في الحسن.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3627","text":"مَرَّ الشباب بالنشاط فاصطحبا، ومَرَّت الشيخوخة بالخِبرة فاصطحبا.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3628","text":"إذا أراد الله بأُمة خيرا وبِرًّا جعل القناعة في حكامهم وجعل النزاهة في نوابهم وجعل التعاون فيما بينهم لصالح شعبهم ووطنهم","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3629","text":"انتصار الإنسان على نفسه هو أعظم انتصار، وهو الجهاد الأكبر.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3630","text":"ارحموا ضعفاءكم فإن الله ينصركم ويرزقكم بضعفائكم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3631","text":"من أمارة العاقل أنه يُكرر الصواب ولا يُكرر الخطأ.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3632","text":"تعريف المصطلحات وتحديد المفاهيم هما بوابة الحكمة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3633","text":"أيها السائقون: أكثروا من استعمال إشارات السيارة والنظر في المرايات عند الحاجة، فإن بهما وقاية من الحوادث والإصابة، ولا تتجاوزوا المائة والعشرين فإن بها كسور أو موت باليقين.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3634","text":"الأجدر بالعالم قبل أن ينصح الناس ويعظهم أن يطبق ذلك على نفسه وأهل بيته، حتى يخرج الكلام من قلبه على لسانه، لا من لسانه فقط.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3635","text":"من أسباب تأخر المجتمع أن ذوي الكفاءات يشكون في كفاءتهم، فلا يبحثون عن المناصب، وإن رُشحوا لها لا يوافقون عليها. أما فاقدي الكفاءات فهم واثقون من أنفسهم، فهم يبحثون عن المناصب ويحرصون عليها، فيتولون المناصب.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3636","text":"بعض الناس يجب أن تتعامل معهم بالتقييد والتحديد والصراحة","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3637","text":"صدقات السِّرِّ من أفضل البر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3638","text":"الصدقات تجلب الرحمات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3639","text":"اطلبوا البركات بالصدقات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3640","text":"غض البصر هداية وإرساله فتنة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3641","text":"الاستغفار صابون الذنوب، والذكر نور القلوب.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3642","text":"يفنى ما في القدور يبقى ما في الصدور.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3643","text":"أُمنيات الإنسان أحلام اليقظان.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3644","text":"معاناة تربية الأطفال شديدة، لكن نتائجها سعيدة.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3645","text":"الاستمتاع بالعمل يرفع عنك مشقة العمل.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3646","text":"حب العامل لعمله يدعوه لتحسينه وتطويره.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3647","text":"خير أموالكم ما كانت في بطون فقرائكم وعلى ظهور أيتامكم وفي مرضات ربكم","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3648","text":"اهتبلوا الفرصة الحلاق الآن ينش الذباب وليلة العيد الطوابير على الأبواب","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3649","text":"لا ترتبط بفتاة لا تُجيد الطبخ فالحب لا يصنع الملوخية","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3650","text":"المرافق العامة لمن سبق ولا يجوز الحجز فيها فالناس شركاء في المرافق العامة","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3651","text":"يوم السفر نصف السفر","kind":"mathal","topic":"الحياة والزمن","note":"لتزاحم الأشغال.","source":"شذرات (ملف وورد)"},{"id":"m3652","text":"يَسْتَفُّ التراب ولا يقف على الأبواب.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3653","text":"يبني قصرا ويهدم مِصرا.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3654","text":"يأكل الفيل ويَغْتَصُّ بالجرجير.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3655","text":"يتمضمض بالغِيبة.","kind":"mathal","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3656","text":"العادة أُخت الطبيعة.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3657","text":"اجتهدوا في طلب الجنة، أما النار فقريبة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3658","text":"من أراد أن يسكن بيتا جديدا يسعى مبادرا لفرشه وتأثيثه، فيبدأ بالضروريات فالحاجيات فالكماليات، فبادروا في تأثيث قبوركم بالإيمان والأعمال الصالحات، وصلة الأرحام والصدقات","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3659","text":"حارث : والله ما عرفتك! ضاعف . همام : صدقت، رمضان أخذ مني حِتَّة . حارث : لا تحمل همَّا ، إن كان رمضان أخذ منك حتة ، فإن العيد سوف يُعطيك حِتَّتَين . همام : الله يُبشرك بالخير . فضحكا ثم تفرقا","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3660","text":"كلمات الحكمة لوحات إرشادية على طريق الحياة الموصل للنجاح في الدنيا والفوز في الآخرة","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3661","text":"رونق المعايدة وزهرتها وبهجتها وفرحتها بعد صلاة العيد لا قبلها","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3662","text":"قُبيل أي نشاط أو مشروع تجاري استشر الخبراء ثم صَلِّ الاستخارة ثم ابذل المجهود المطلوب ثم فوض أمرك لله تعالى والله خير الرازقين","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3663","text":"إذا سبقك الأبرار في أعمال البر، فلا يسبقك التائبون بالتوبة والاستغفار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3664","text":"من تطاول على السلطان سوف يتولى أمره السجَّان.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3665","text":"لو خُير إنسان بين دينار أول الشهر أو ألف دينار آخر الشهر، سوف يختار الألف آخر الشهر، فكيف لو خير بين نعيم دنيوي ناقص زائل، وبين نعيم أُخروي كامل دائم، فالعاقل سوف يختار النعيم الأُخروي على النعيم الدنيوي.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3666","text":"الفقراء يمشون ليجلبوا الطعام لأطفالهم، والأغنياء يمشون ليهضموا الطعام الذي في بطونهم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3667","text":"الحرية المطلقة فساد مطلق، فلا بد أن تُقيد الحرية بقيدين: بأن لا تتعارض مع المصالح الدنيوية والدينية.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3668","text":"لا يستطيع السياسي أن يُكَوِّنَ ثروة طائلة إلا إذا كان منافقا.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3669","text":"لا يستطيع الموظف الحكومي أن يُكَوِّنَ ثروة طائلة إلا إذا كان مرتشيا أو مختلسا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3670","text":"المتواضع هو الذي يمتلك أسباب الكبرياء لكنه لا يتكبر.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3671","text":"لن تُحقق هدفك إذا كُنت تُؤثر الراحة والخمول.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3672","text":"التاريخ يُمليه المنتصر ويكتبه المنافق، وينطلي على الشعوب، ويفضحهم العالم المحقق.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3673","text":"إذا تفشى الغش والخداع فمن السذاجة أن تثق بأحد قبل أن تجربه وتمحصه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3674","text":"من عيوب الديمقراطية أن الذين يحصون الأصوات هم الذين يُقررون من الفائز؛ لا من يُصوتون.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3675","text":"أكثر مشاكل سكان الأرض من الإنسان، وهذا بسبب العقول وتعارض الآراء، وبسبب النفوس وتعارض المصالح.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3676","text":"أكثر الخلافات العربية قائمة بين الحكومات والنُّظُم لا بين الشعوب.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3677","text":"عريش من حطب خير من سجن من ذهب.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3678","text":"نتيجة الحروب الخسارة، لكن خسارة المنتصر أقل من خسارة المغلوب.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3679","text":"سألت أمين المكتبة : أين أجد كتاب الزوج المثالي ؟ فقد بحثت عنه في قسم علم الاجتماع فلم أجده ! فقال : تجده في قسم الخيال العلمي ، بلعت ريقي ومشيت","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3680","text":"من تزوج امرأةعندها طفل فقد تزوج نصف امرأة ومن تزوج امرأة عندها طفلان فقد تزوج ثلث امرأة، ومن تزوجت رجلا متزوجا فقد تزوجت نصف رجل ومن تزوجت رجلا متزوج زوجتين فقد تزوجت ثلث رجل","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3681","text":"إذا احتاج اللئيم انكسر وإذا استغنى استكبر.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3682","text":"العقل هو القدرة الذهنية على اتخاذ القرار المناسب في الوقت المناسب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3683","text":"التواضع بذرة الرفعة، والتكبر بذرة الإهانة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3684","text":"من تقرب من التواضع تقرب من الرفعة، ومن تقرب من التكبر تقرب من المقت.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3685","text":"المتواضع يتعلم ممن حوله؛ كالأرض المنخفضة تشرب ماءها وماء جاراتها.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3686","text":"المرء بالأخلاق يبلغ الآفاق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3687","text":"إذا جاريت في الأخلاق الفساق؛ فأنت وهم سواء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3688","text":"إن الله جعل مكارم الأخلاق بابا من أبواب الدخول في الإسلام لجميع الأنام.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3689","text":"في مناخ الحروب تكثر الإشاعات والإرجافات والتخويفات فلا تُصدقوا كل ما يُقال","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3690","text":"من يمدح نفسه بالمكارم والنفائس؛ يُهين نفسه في المجالس.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3691","text":"اطلبوا الرفعة المحمودة بالتواضع؛ فمن تواضع لله رفعه الله.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3692","text":"إذا اجتمع الرجال مع النساء تزيد الآداب وتقل الفضيلة","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3693","text":"من لانت كلمته وجبت محبته، وطابت عشرته.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3694","text":"كفى بالمرء فضلا أن تُعد معايبه، وتصفو مشاربه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3695","text":"من تكلم في غير تخصصه أتى بالعجائب والغرائب وعدل عن الرأي الصائب وأخذ بالرأي الخائب، نحن لا نقبل رأي المهندس في الطب ولا رأي الطبيب في الهندسة ولا نقبل رأي عالم الكيمياء في الفقه ولا رأي الفقيه في علم الكيمياء، احترام التخصصات العلمية واجب عقلي وفريضة دينية","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3696","text":"العقل الفارغ كالوعاء الفارغ، أكثر ضجة وأقل حجة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3697","text":"العقل يحتاج إلى عاطفة للتسويق، والعاطفة تحتاج إلى عقل للتدقيق.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3698","text":"العقل قوة وتفكير والقلب عاطفة وضمير، فإذا اجتمعا حسن التقدير والتدبير.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3699","text":"من يتحلى بالتواضع؛ يكرم نفسه في المواضع.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3700","text":"بالأخلاق الحميدة تنال محبة الناس وثقتهم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3701","text":"الأخلاق الحميدة شجرة طيبة ثمارها حلوة، والأخلاق القبيحة شجرة خبيثة ثمارها مرة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3702","text":"الاعتراف بالخطأ فضيلة والإصرار على الخطأ رذيلة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3703","text":"أينما كنت فانثر بذور الخير فإن لم تنبت في مكان ما فسوف تنبت في أماكن كثيرة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3704","text":"لا تبخل بأن تقول صوابا أو تشهد بحق.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3705","text":"الشريف إذا استغنى تواضع ، والوضيع إذا استغنى تكبر.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3706","text":"لا تبادر بالشيء قبل أوانه، ولا تتراخَ عنه في إبانه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3707","text":"التقصير في إنجاز الأعمال المهمة يجلب الهمَّ والغُمَّة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3708","text":"توريث الأبناء الأخلاق والآداب خير من توريثهم الدنانير والعقارات والدواب.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3709","text":"دع كبرك واهجر فخرك واذكر ربك ولا تنس قبرك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3710","text":"من ستر عيوب الناس ستر الله عيوبه، ومن أفشى عيوب الناس أفشى الله عيوبة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3711","text":"اطلبوا الأمطار والانتصار بالعطف على الضعفاء الصغار والكبار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3712","text":"عامل خالقك بطاعته، عامل رسولك باتباعه، عامل الصحابه بالتوقير، عامل التابعين بالتقدير، عامل المسلمين بالتعاون، عامل الناس بالأخلاق، عامل أهلك بالإكرام، عامل أصدقاءك بالوفاء، عامل الصلاة بالمدوامة، عامل القضاءوالقدر بالرضا، عامل العلماء بالاحترام، عامل الأطفال بالعطف، عامل المريض باللين، عامل النعمة بالشكر، عامل المصيبة بالصبر، عامل نفسك بالمجاهدة، عامل أميرك بالطاعة، عامل القوانين بالتنفيذ، عامل الضعيف بالرحمة","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3713","text":"المتقاعد هو الرجل الكُنْتِي نسبة إلى كان، لأنه دائما يتحدث عن الماضي","kind":"hikma","topic":"الحياة والزمن","note":"طرفة","source":"شذرات (ملف وورد)"},{"id":"m3714","text":"القدوة الحسنة نصيحة صامتة، أينما حلت وعظت.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3715","text":"رجل بلا آداب وحش يلبس الثياب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3716","text":"كن مُوَصِّلاً جيدا للثقافة والمعرفة، فجالس من هم أعلم منك لتستفيد، وجالس غيرهم لتُفيدهم، ولتُثَبِّت المعلومات التي استفدتها.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3717","text":"لا تترك الرياضة البدنية لأنك كبرت، ولكنك كبرت لأنك تركت الرياضة البدنية.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3718","text":"أولادك سوف يعيشون محترمين مبجلين بسبب ما ربيتهم على الأخلاق والآداب والرغبة في طلب العلم والمعرفة والثقافة.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3719","text":"دراسة الماضي في الزمان، تُعينك على تخطيط المستقبل بإتقان.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3720","text":"النهوظ بعد السقوط من أمارات النجاح المضبوط.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3721","text":"كثير من الفاشلين كانوا قريبين من النجاح لكنهم عندما سقطوا لم يحاولوا النهوض.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3722","text":"إذا كان كلام الناس لا يُحبطك بل يزيد من حماسك، فأنت قد سلكت طرق النجاح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3723","text":"إذا كانت الحياة على وتيرة واحدة فسوف تكون مملة.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3724","text":"من يتكلم باستعلاء لن يجد لكلماته إصغاء.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3725","text":"من يتكلم بتواضع وانتقاء بجد لكلماته إصغاء.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3726","text":"المبادرة لتحقيق الأهداف أمر هام،إذا كانت بالاتقان والاتزان","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3727","text":"إذا كان الحاكم فرعونيا يكون قول الحق عملا إرهابيا، يستحق صاحبه أن يكون في سجن مؤبد، أو في حبل مشنقة ممدد.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3728","text":"التغابي مع السفيه الشرير نوع من الذكاء المستنير.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3729","text":"رُبَّ ثائر على حاكم ظالم فلما صار حاكما صار أشد ظلما، حتى أصبح الناس يترحمون على الحاكم الظالم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3730","text":"نمو الأشجار المثمرة يحتاج إلى عناية مستدامة، ووقت طويل لتنمو وتزهر وتثمر، ثم يصفار ويحمار جناها حتى يطيب طعمه ولونه ورائحته، وهكذا الأعمال الناجحة تحتاج إلى اهتمام وصبر، ورعاية وعناية مستدامة، حتى تنمو وتكبر وتظهر ثمرتها وفائدتها وربحها.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3731","text":"تجدون السعادة الدنيوية في كل أمر مُلائم للنفس ليس له عاقبة وخيمة، وتجدون الشقاء الدنيوي في كل أمر مُخالف للنفس وليس له عاقبة حميدة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3732","text":"لا يستطيع الإنسان أن يكون طيبا في حالة الغضب كما كان طيبا في حالة الرضا، إلا العاقل الحليم الرزين الصبور، وقد يطيش أحيانا.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3733","text":"الرجل يستطيع أن يرى نجوم السماء الغابرة في الأُفق، ولا يستطيع أن يرى ما تُقدمه له زوجته من الأعمال الجليلة: مشقة الحمل ومعاناة الولادة، ومكابدة الرضاعة وتعب تربية الأولاد وغيرها كثير.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3734","text":"الجود يقربك من البعداء والبخل يُبعدك عن الأقرباء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3735","text":"دراسة العلم والأدب يرفعان خامل النسب.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3736","text":"ليس من شرط النجاح عدم السقوط ولكن من شرط النجاح المبادرة بالنهوض بعد كل سقوط.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3737","text":"من أراد الفوز والكرامة فليلزم التقوى والاستقامة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3738","text":"من لان قلبه سالت دمعته ومن قسا قلبه جفت دمعته.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3739","text":"من أراد السعادة المستدامة فليسلك طريق الاستقامة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3740","text":"إذا أردت أن تُقلل نسبة الجريمة فأوجد فرص عمل للعاطلين، ورواتب تسدحاجة المستضعفين","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3741","text":"تخيروا لبناتكم الصهر الصالح فإذا كانت ابنتك سعيدة مع زوجها فقد زادت سعادتك، وإن كانت تعيسة معه فقد زادت تعاستك.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3742","text":"الكمال الإنساني أمر نسبي لم يتحقق إلا في الأنبياء عليهم السلام، ثم يليهم أصحاب الأنبياء ثم التابعين، ثم الصالحين المتقين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3743","text":"رُبَّ رجل فقير ينام على ظهر الحصير؛ أسعد حالا ومآلا من رجل أمير ينام على فراش من حرير فوق ذهب السرير.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3744","text":"من استبد برأيه ضل، ومن استشار المجربين أخذ بالرأي اليقين.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3745","text":"من عوامل نجاح السياسة: الفطانة والكياسة، وسعة الصدر والمشاعر الحساسة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3746","text":"من أضمر شيئا في قلبه ظهر في نظرات عينيه وفلتات شفتيه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3747","text":"سألت أمين المكتبة : أين أجد كتاب ( اتفاق الأُمة العربية ) ؟ فإني لم أجده في قسم الكتب السياسية والاجتماعية ! قال : تجده في قسم كتب الخيالات العلمية ! قالها وهو يبتسم ابتسامة صفراوية","kind":"tarfa","note":"سخرية سياسية خفيفة","source":"شذرات (ملف وورد)"},{"id":"m3748","text":"تربية التلقين وتعليم اليقين وهداية الدين والخلق القويم والصراط المستقيم للأطفال الطيبين مثل غرس في الطين للثمار والعنب والتين والحبوب واليقطين","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3749","text":"حسناتك كنزك الذي لا يأكله السوس ولا ينهبه اللصوص إذا حفظته من الغيبة والنميمة والطعن في أعراض النفوس.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3750","text":"مشقتك في الدنيا في أعمال الخير والبر، تُبلغك الجنة مع الأبرار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3751","text":"حلمك في ساعة الغضب يقيك من شَرٍّ قريب مرتقب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3752","text":"تعاملوا مع الوافدين معاملة إنسانية، تبدأ من السفارات ثم المطارارت والموانئ والحدود البرية والبحرية، في الدخول والخروج، وفي الحياة الاجتماعية. فتوظفوهم بالمجان للدعاية الإيجابية، فينشرون الانطباعات السوية والتعاملات الإنسانية إذا رجعوا لأوطانهم والأهلية، وتبقى في نفوسهم ذكريات جميلة ندية، عن الحكومة والشعب الكويتي ذوي الأخلاق الطيبة والنفوس الزكية.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3753","text":"عندما سكت أهل الحق عن بيان الحق، توهم أهل الباطل أنهم على حق.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3754","text":"من نسي طيشه واستهتاره في شبابه استعظم طيش الشباب واستهتارهم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3755","text":"من تذكر طيشه واستهتاره في شبابه لان ورفق بنصيحة الشباب على طيشهم واستهتارهم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3756","text":"أكثرو من الحسنات فإنها سفينة النجاة بعد الممات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3757","text":"أكثروا من الصدقات فإنها تُكفر السيئات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3758","text":"أكثروا من كفالة الأيتام فإنها تُقربكم يوم القيامة من سيد الأنام.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3759","text":"حلاوة النجاح تمحو مشقة الكفاح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3760","text":"كثرة الكلام تُورث السآمة، وكثرة الزيارة تُورث الملالة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3761","text":"فاز بالجِنان من نجا من شر نفسه والشيطان.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3762","text":"من يبتغي السعادة المستدامة، فليلزم طاعة الله ويعاشر عباده بالرحمة والابتسامة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3763","text":"الإفراط في الملذات والشهوات تُثقل على المرء التزود من الطاعات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3764","text":"مسلم اشتر نفسك من ربك بالطاعات القلبية واللسانية والبدنية والمالية؛ لتربح من الله رضوانه وجنته وخلودا أبديا في النعيم المقيم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3765","text":"إذا كثر الفساد في العباد فحسن الظن من الغباء وسوء الظن من الذكاء","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3766","text":"أكثر الناس حبا لله أكثرهم له ذكرا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3767","text":"رأي الشيخ يخرج من تجاربه والتجارب لا تكذب، ورأي الشاب يخرج من حماسه، والحماسة مظنة الزلل.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3768","text":"لا تأخذ رأي البائع في بضاعته لأنه يريد أن يروجها، فيذكر محاسنها ويخفي مساوئها.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3769","text":"من كفارات الذنوب العظام اغاثة المنكوبين والأيتام.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3770","text":"ذهب الشباب فما له من رجوع، وأتى المشيب بالبياض والسطوع.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3771","text":"الناس أصدقاء ما عرفوا، وأعداء ما جهلوا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3772","text":"شطر طعامك في بطن فقيرك خير لك من كل طعامك في بطنك.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3773","text":"العامِل بين مُحامِيين كعصفور بين قِطتين.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3774","text":"المجتمع مثل السجادة الكبيرة؛ يحتاج إلى نفضات قوية كل فترة، لتنقيته وتجديدة وتنشيطة، فلا بُدَّ من مراقبة ومحاسبة ومساءلة الأُمراء والوزراء والمدراء والرؤساء والمسؤولين الكبار، لأن من أمن المُساءلة والمحاسبة أمن المعاقبة، ومَن أمِن المعاقبة أساء الأدب، وفي هذا إصلاح للمعوج، ووقاية للمستقيم الذي يُراوده الشيطان على أن يعوج، وحفظ لثروات الشعب والأجيال القادمة من الضياع والدمار.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3775","text":"فالمرأة العصرية خدعة بصرية لها جاذبية قوية، وتضاريس وهمية، صناعية لا طبيعية، وشكلية لا فطرية.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3776","text":"الماهر في فَنِّ الاعتذار لا يكون ماهرا في أي فَنٍّ آخر.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3777","text":"كسب المال من ثمار الوقت.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3778","text":"قبل أن تُخالط الناس تدرب على إخفاء همومك وإبداء ابتساماتك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3779","text":"من مقاصد الشيطان السعي الحثيث لإثارة الفتنة بين المسلمين، ونشر بذور التفرقة والعداوة والشقاق بين المجموعات والطوائف والأحزاب والشعوب والأوطان، ليُضعفهم ويسلط أعداءهم عليهم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3780","text":"لا تُكرروا الكذب والإشاعات حتى لا تصبح حقائق مسلمات.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3781","text":"في المباحات سِرْ مع التيار، وفي المبادئ سِرْ مع المبادئ ولو ضد التيار.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3782","text":"بناء الرجال أصعب من بناء الجبال.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3783","text":"الرزق مكتوب والحرمان مكتوب، والسعي مفتاح الرزق، والخمول والكسل مفتاح الحرمان، ولكل مجتهد نصيب، وكل خامل يخيب، والحقائق تُدرك بميران العقول لا بحماس غير معقول، والله وهب الرجل آلة الكسب فطلب منه قدرا وعقلا وشرعا أن يسعى على نفسه ومن يعول، وكفى بالمرء إثما أن يُضيع من يعول.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3784","text":"عقل الطالب وعاء يملأه المعلم بالمفاهيم الصحيحة، وشمعة يُنيرها المعلم بالأفكار السليمة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3785","text":"البشر لن يجدوا أرحم بهم من خالقهم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3786","text":"من أسعد الضعفاء أسعده الله تعالى فإن الجزاء من جنس العمل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3787","text":"أركان الحرب أربعة:، المال والرجال والسلاح والعقيدة القتالية.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3788","text":"علمتني التجارب أن أُعامل الناس بالحسنى؛ إن كان عاقلا سيعاملني بالمثل، وإن كان سفيها سيكف عني شره.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3789","text":"لو نظر ابن آدم إلى الجنة لاحتقر عمله لها، ولو نظر إلى النار لاحتقر هروبه منها.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3790","text":"لا تغفل عن ذكر الله فتحرم نفسك من ثواب الله.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3791","text":"الغفلة من الغباء والتغافل من الذكاء.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3792","text":"الحزن العارض أمر طبيعي، أما التمادي في الحزن فأمر سلبي.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3793","text":"إذا سلكت الطريق الصحيح فسوف تصل إلى هدفك ولو بعد حين.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3794","text":"كن كالنملة تعلمك الكثير في دأبها ونشاطها ونظامها وعملها وعزمها وجدها وتعاونها، في صمت دون أن تنطق ببنت شفة، ودون أن تأمرك أو تنهاك","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3795","text":"الفرق بين العاقل والسفيه، العاقل لا يُكرر أخطاءه، أما السفيه فهو يُكرر أخطاءه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3796","text":"يقول الفقير: لو كان عندي أموال لكنت سعيدا، ويقول الغني: عندي أموال ولكني لست سعيدا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3797","text":"العاقل يفكر ثم يعمل، والسفيه يعمل ثم يندم.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3798","text":"لن تصل إلى تحقيق هدفك إذا توقفت لتجادل كل من ينتقدك.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3799","text":"إذا وجدت دولة فستجد نظاما، وإذا وجدت نظاما فلن تجد حرية مطلقة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3800","text":"أحسن ظنك بالناس واحترس منهم، ولا تكن أهبلا يمتخط بكمه، فبعض حسن الظن ورطة، وبعض سوء الظن من الفِطَن، فإذا عمت الأمانة والصدق فسوء الظن إثم، وإذا تفشى الكذب والخيانة فسوء الظن من الحزم والعزم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3801","text":"لا تنخدع بجمال المظهر فبعض الأزهار الجميلة ليس لها رائحة جميلة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3802","text":"قبل أن تُفكر في إصلاح غيرك أصلح نفسك أولا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3803","text":"إذا أردت أن تغير مَنْ حولَك فابدأ بتغيير نفسك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3804","text":"كلما زادت أموالنا زادت همومنا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3805","text":"إن أردت أن تُحقق النجاحات، فاغتنم الفرص المُتاحات.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3806","text":"اكتب همومك على الرمال وانقش انجازاتك على حجارة","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3807","text":"أفضل الأرباح العقلية تأتي من الاستثمار في العلم والمعرفة والثقافة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3808","text":"يُولد الطفل خال من العلم والمعرفة، فعلى الوالدين أن يأخذا بيديه نحو العلم والمعرفة بالتدريج.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3809","text":"أفضل استثمار في الأولاد أن تزرع فيهم حب العلم والمعرفة والثقافة، والأخلاق الحميدة والعادات المجيدة.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3810","text":"أي مصلحة تجارية ولو كانت مهنتها مثالية وإنسانية، كالمستشفيات والعيادات، يكون عمود خيمتها، ونظام عملها، وتنظيم إجراءاتها، وعقيدة هدفها، هي الربحية والمبالغة في جمع المال وتكثيرة، ثم يتفاوتون في درجات الطمع والجشع، هذا هو الأصل العام، وقد يكون هناك استثناءت طفيفة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3811","text":"زلة اللسان أشد من زلة القدم، لأن زلة اللسان تُصيب الجَنان.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3812","text":"الأفعال أبلغ من الأقوال، لأن الأفعال ثمرة مجهود ونصب.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3813","text":"عندما يتأخر المطر يعرف الناس قيمة نعم الله.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3814","text":"القوانين الجيدة هي التي تجمع بين النظام والمنفعة العامة ويقبلها عامة المواطنين.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3815","text":"إذا أردت أن تكتب فاكتب شيئا يستحق القراءة وفيه منفعة للقارئ.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3816","text":"الحقيقة الناقصة أخت الكذب.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3817","text":"تَجَرُّعُ الغضبِ يقيك من الندم.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3818","text":"الأُم ترى ابنها الأهبل فيلسوفا.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3819","text":"قبل أن تبدأ بأي عمل تعلم كل ما يتعلق بهذا العمل، فالعلم قبل العمل.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3820","text":"النجاح في مجلس الأُمة بالكم لا بالكيف، النجاح يحتاج إلى قبيلة أو حزب أو طائفة","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3821","text":"نور الشمعة يُبدد الظلام، ونور العلم يُبدد جهل الأنام.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3822","text":"ليس في مقدور الإنسان أن لا يُذنب لكن في مقدورة أن يستغفر كلما أذنب.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3823","text":"ابحثوا عن الفضيلة بين الرذيلتين، بين الإفراط والتفريط، بين الإسراف والتقتير، بين الغلو والتسيب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3824","text":"خسارة قليلة قريبة خير من مكسب بعيد، لأن المكسب البعيد يحبس المال، أما الخسارة القليلة فتحرر المال، فتقلبه فيجلب أرباحا تعوض الخسارة وزيادة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3825","text":"بحسن الأخلاق تُستدر الأرزاق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3826","text":"أفضل النوال العطاء قبل السؤال.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3827","text":"العفو من سجايا الكرام، والفجور في الانتقام من سجايا اللئام.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3828","text":"نصف طبيب يهدم صحتك، نصف مهندس يهدم بيتك، نصف فقيه يهدم دينك، نصف عالم يهدم عقلك، نصف تاجر يهدم أموالك، نصف طباخ يهدم لذتك، نصف سائق يهدم سيارتك، احذروا الأنصاف فإنهم ينشرون الزهرة والبعرة","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3829","text":"لا تيأس من فرج الله فلكل ليل نهار، ولكل صيف شتاء، ودوام الحال من المحال.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m3830","text":"اللسان لا يجرح جلد الإنسان، لكنه يجرح الجَنان، وجرح الجَنان أنكى من جرح جلد الإنسان.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3831","text":"من يأكل وهو شبعان لا يشعر بلذة الطعام، مثل ما يشعر بها الجوعان.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3832","text":"خير أصحاب الرسل، أصحاب خير الرسل،كان أصحاب النبي صلى الله عليه وسلم، أعمق علما، وأقل تكلفا، وأكثر أفعالا، وأقل أقوالا، وأجمع دعاء، وأقل تطويلا، وأسمح دينا، وأبعد تعصبا، ولا يخوضون فيما لا يعنيهم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3833","text":"هذه ضريبة الدراسة في الغربة، الشاب والشابة يتعارفان ويتآلفان، وتنمو بينهما شجرة التفاهم والحب، فيتفقان ويخططان للمستقبل، من غير علم أهليهم، لأن الأهل لهم دور مهم في التوجيه والإرشاد.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3834","text":"اكره معصية أخيك، واحمد الله على الهداية والوقاية، وادع لأخيك بالهداية والتوبة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3835","text":"ابتسامة المهزوم تدفع عنه شطر الشماتة.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m3836","text":"هجران مَنْ شره أقرب مِنْ نفعه خير مِن الانتقام منه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3837","text":"في صعودك إلى الدرجات المرموقة في سلم العمل سيعرف أصدقاؤك من أنت، وفي نزولك ستعرف أنت من هم أصدقاؤك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3838","text":"لا تُعلق كل آمالك على أنك ستنجح من أول مرة، حتى لا تفقد الأمل والحماس، فلا بد أن تعلم أن الكعكة الأولى محروقة، ثم ستتحسن بالتدريج.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3839","text":"الرسالة القصيرة كالوردة الجميلة تجذب القارئ، والرسالة الطويلة كالوردة الذابلة تطرد القارئ","kind":"hikma","topic":"الكلام والصمت","note":"على لسان الواتساب","source":"شذرات (ملف وورد)"},{"id":"m3840","text":"الدين بالعلم والاتباع والدليل والإقناع، لا بالحماس والاندفاع والمبالغات والتهويلات، اتبعوا ولا تبتدعوا، اتبعوا هدي نبيكم عليه الصلاة والسلام، وفهم الصحابة والتابعين والسلف الصالح من القرون الثلاثة الأُولى المهديين المُفضلين، فليس البر بالتكلف والاندفاع، إنما الدين بالتيسر والاتباع، فقليل متصل خير من كثير منقطع، وأحب الأعمال إلى الله أدومها وإن قَلَّ.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3841","text":"جمال الأخلاق يزيد الجميل جمالا، وقبح الأخلاق يزيد القبيح قبحا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3842","text":"عامل الناس بأخلاقك ولو ساءت أخلاقهم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3843","text":"معاملة الناس بالأخلاق الكريمة تجلب المدح للوالدين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3844","text":"معاملة الناس بالأخلاق القبيحة تجلب القدح للوالدين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3845","text":"من يسعى في خدمة والديه وبالأخص الأُم يُبارك له في رزقه، ويُفسح له في أجله، وهو يسعى في أقرب طريق وأيسر سبيل إلى رضوان الله وجنة الفردوس العليا.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3846","text":"مُقَصِّرٌ حَسَنُ الأخلاق طيب العشرة واللقاء؛ أخف على الناس من عابد سيئ الأخلاق عابس اللقاء، لأن الأول تقصيره على نفسه، وحُسن أخلاقه للناس، والثاني عبادته لنفسه، وسوء أخلاقه على الناس، فكن صالحا حسن الأخلاق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3847","text":"ازرع الخير بأفعالك وأخلاقك قبل أن تزرعه بأقوالك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3848","text":"بعض المجانين في عصورهم هم عباقرة في عصور المستقبل، لأنهم عباقرة سبقوا عصورهم فلم يُكتشفوا ويُفهم كلامهم إلا بعد عصورهم، فهم مجانين الحاضر عباقرة المستقبل.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3849","text":"فكرت فخططت فنفذت ففشلت فحزنت فتألمت فتعلمت من أخطائي، فتحمست فتحديت فسعيت فاجتهدت فاتقيت أخطائي، فنجحت فحققت أهدافي، ولو أهملت وتوانيت وتكاسلت، وفقدت ثقتي بمهاراتي وخبراتي لما أنجزت آمالي، وحققت أهدافي.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3850","text":"إساءة المرء إلى نفسه أكثر من إساءة غيره له، بسبب طول الملازمة، والنفس الأمارة بالسوء.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3851","text":"شيئان لا تستطيع التحديق إلى عينيهما: عين الشمس وعين مَن أقرضك مالا فتأخرت عن سداده.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3852","text":"مهما كانت الدنيا واسعة فلا يسعك إلا بيتك.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3853","text":"خوف العبد من الله ثمرة معرفته بالله.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3854","text":"زهد العبد في زينة الدنيا على قدر شوقه لنعيم الآخرة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3855","text":"من عمل بما علمه الله زاده الله علما.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3856","text":"من ساء خلقه جفاه أصدقاؤه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3857","text":"من حسُن خلقه وقره أعداؤه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3858","text":"قل كلمة الحق فإن لم تستطع فاصمت ولا تقل كلمة الباطل، وأنكرها بقلبك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3859","text":"التربية الأخلاقية المجيدة، والنشأة على العادات الحميدة، تمنحان الأولاد مناعة قوية ضد الفساد والانحلال والتصرفات غير الرشيدة.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3860","text":"وجدت أرخص هدية تُسعد الزوجة وتعتبرها أغلى هدية هي: المدح والثناء والإعجاب والتغزل والشكر، وجدتها أرخص هدية فاشتريتها.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3861","text":"فيتامينات الحب:، وجهكِ منور، بشرتكِ ناعمة، وزنك نازل، اشتقتُ إليك، كنتُ أفكر فيك، مشكورة، ما قصرتي، تعبناكِ، ثم سِرْ على هذا المنوال.","kind":"ghazal","source":"شذرات (ملف وورد)"},{"id":"m3862","text":"المعلم يفتح الأبواب للطلاب ويمهد لهم الطريق، ثم هم ينطلقون في طريق العلم والمعرفة والثقافة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3863","text":"العاقل يجعل المشكلة الكبيرة صغيرة، والسفيه يجعل المشكلة الصغيرة كبيرة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3864","text":"لقاء الزوجين بعد فراق طويل زواج جديد.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3865","text":"دموع الأطفال تستدر عطف النساء والرجال.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3866","text":"إذا أردت أن تفقد صديقك فكلمه بصراحة من غير مجاملة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3867","text":"بالحبوب تصيد الأطيار، وبالمال تصيد الرجال.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3868","text":"إذا أصبح كل الناس تجارا فمن يبني لنا دارا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3869","text":"يكون الإنسان مغفلا إذا اعتقد أن كل الناس طيبون.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3870","text":"لا تبحث عن صديق ليس فيه عيب، ولكن ابحث عن صديق صلاحه أكثر من عيوبه، وخيره أكثر من شره،وعلى لسانه تمرة","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3871","text":"كلمة واحدة عوراء تخسر بها الأصدقاء، ومائة قول رقيق لتكسب به الصديق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3872","text":"لن تكسب المعالى إلا بسهر الليالي.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3873","text":"إذا أردت أن تكسب الأمجاد فعليك بالنصب والاجتهاد.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3874","text":"عندما ذهبت إلى العين استصغرت البئر، وعندما ذهبت إلى النهر استصغرت العين، وعندما ذهبت إلى البحر استصغرت النهر، وهكذا العلماء، ولن تتعصب للعالم وتعرف أخطاءه حتى تُجالس عالما غيره، وفوق كل ذي علم عليم، والله بكل شيء عليم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3875","text":"لا يمكن أن تلعب بالوحل وتحافظ على نظافة ملابسك، فلا تُخالط المشبوهين والمتهمين.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3876","text":"دع الغضب واستبدله بالحلم، فَغِبَّ كل غضب مندمة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3877","text":"اجعل مزاحك في كلامك كالملح في الطعام، فإذا زاد مزاحك نقصت هيبتك، وإذا قَلَّ مزاحك زاد ثقل دمك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3878","text":"إذا كثر المجتمعون كثرت الآراء، وإذا كثرت الآراء كثر النقاش، وإذا كثر النقاش طال الوقت ولم نتفق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3879","text":"اكْرَهْ الذنب، وانصح المذنب سرا، وادع له بظهر الغيب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3880","text":"صُنْ لسانك، فأكثر ذنوب الانسان من اللسان.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3881","text":"كن مؤدبا مع:، الكبير والصغير، الغني والفقير، العزيز والحقير، الوزير والغفير، القريب والغريب، العدو والحبيب","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3882","text":"من الغباء أن تُناقش الغبي كما تُناقش الذكي.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3883","text":"لو أطعمت كلبا يوما لأحبك دوما ، ولو أطعمت إنسانا دوما رُبما أنكرك يوما.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3884","text":"لو رصدت تصرف كلب باهتمام ؛ لعرفت كيف تتصرف الكلاب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3885","text":"النقاش العلمي غربال لاكتشاف الحقيقة المجردة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3886","text":"المُبعد من بلاده، محروم من سعادة أهله وأصدقائه وأولاده.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3887","text":"أحبب أولادك بقلبك ، وأدبهم بأخلاقك الحميدة، وعاداتك المجيدة، وآرائك السديدة، وكلماتك المفيدة ، وقدوتك الرشيدة.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3888","text":"انصح صديقك سِرًّا وامدحه علنا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3889","text":"الأدب خير من الذهب والمال ، والتعامل به أخلاق وكمال.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3890","text":"كلما سنَّت الحكومة قانونا ؛ اخترع المخالفون طريقة للتحايل عليه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3891","text":"من واجب رب الأسرة أن يُوفر لأسرته الضروريات والحاجيات ، من غير إسراف ولا تقتير ، أما الكماليات والجماليات والزينات فتدخل في باب المكارمة والمواددة بطيب نفس من غير وجوب أو إلزام ، وأُم العيال أولى بالمكارمة وإنفاق والمال ، وخيركم خيركم لأهله.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3892","text":"راقب أقوالك وأفعالك واحرص على ألا تجرح أحدا بقول وقِيح، أو فعل قبيح، أو نقد صريح، أو كلام غير مليح ، فإذا فعلت صرت قدوة لغيرك، وداعيا للخير بصمتك ، فانهالت عليك الحسنات ، ونلت المحبة والاحترام من الأفراد والجماعات ، وناهيك عما تكسب من الخيرات.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3893","text":"قلب الأُم يتسع لجميع أولادها على حسب احتياجاتهم لها ، فالصغير والسقيم والمسافر يتربعون في محراب قلبها، وفي بُؤرة عقلها.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3894","text":"طموح من يجمع المال ليس له غاية ، فلو كان له وادي من ذهب لتمنى ثانيا ، ولو كان له واديان لتمنى ثالثا ، وهلمَّ جرَّا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3895","text":"من لا يتعظ من أخطائه سوف يُكررها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3896","text":"من تباها بنجاحه رُبما فوَّت على نفسه نجاحا آخر ، ومن شكر الله على نجاحه مظنة أن يُوفق لنجاح آخر.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3897","text":"كثرة العتاب تُوحش الأصحاب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3898","text":"ازرع لحياتك أشجارا مثمرات ، وازرع لمماتك أعمالا صالحات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3899","text":"تمام التحية خمس كلمات ( السلام عليكم ورحمة الله وبركاته ) وكذلك ردها.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3900","text":"أول الحزم مشورة المجربين ، تأخذ عنهم العلم اليقين ، فالتجارب لا تُحابي ولا تكذب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3901","text":"لا تُبادر بالمدح والقدح ، فالمدح والقدح بعد التجربة ، فالحقيقة بنت التجربة ، والتجارب تنفي التخيلات والتوهمات.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3902","text":"اسْعَ على نفسك وأولادك ، بجدك واجتهادك ، فالأسد يصيد لنفسه ولأشباله ، والثعالب تأكل من فضلته ، وما تناثر من فُتاته.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3903","text":"لا تُسرفوا في تناول الطعام، فكثير من الأسقام، سببها الإسراف في تناول الطعام.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3904","text":"لتكن أخلاقك الحميدة قمرية، فهو ينشر نوره على جميع الناس بلا مقابل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3905","text":"لا تتكبر على الفقراء بالمال ، فسوف تندم في المآل ، ويتكبر عليك من هو أكثر منك في المال.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3906","text":"من يجد في نفسه الصَّغار ؛ يتكلف الكبرياء والاستكبار.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3907","text":"تجنب الأعمال التي لا تُحب أن تلقى الله عليها.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3908","text":"ترك الخطيئة خير من التوبة بعد اقترافها.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3909","text":"لا تحكم على أخلاق رجل حتى تذوق طبعه عند الغضب ، وأمانته عند المال والنَّشَب.","kind":"hikma","topic":"الأخلاق والآداب","note":"النَّشَب: المال والعقار.","source":"شذرات (ملف وورد)"},{"id":"m3910","text":"تناصحوا فيما بينكم لِينا لا تعنيفا ، وسرًّا لا جهرا ، وتلميحا لا تصريحا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3911","text":"اقتصدوا ولا تُسرفوا فإن الرخاء لا يدوم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3912","text":"من تمام العدل أن تُلَقِّن خصمك حجته ، وتبين له برهانه ومنهجة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3913","text":"التجارة بالأديان تزدهر في المناطق التي يفشو فيها الجهل ويقل فيها الإيمان.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3914","text":"إذا أراد الفاجر أن يخدع الجاهل دخل عليه من بوابة الدين ، والخلق المستقيم.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3915","text":"ما أجمل التراضي قبل التقاضي ، وما أقبح التقاضي قبل التراضي.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3916","text":"ما أجمل التغاضي قبل التقاضي ، وما أقبح التقاضي قبل التغاضي.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3917","text":"ما أقبح الهجران بين الإخوان ، وما أجمل التواصل بعد الهجران.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3918","text":"تنشأ الصداقات من التوافق في الهوايات والمهارات ، والسجايا والصفات ، فالتوافق أُخوة وتقارب ، والتخالف استيحاش وتباعد.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3919","text":"أعداء الإسلام خدعونا فانخدعنا لهم ، هم يرسلون لنا رسالة واحدة فيها الطعن بالإسلام ، والتشكيك في تعاليمه ، ثم نحن بدورنا ننشرها في جميع القروبات ، كل واحد يبادر بنشرها في عشرة قروبات وهو سعيد ، وفي حالة سباق ، فربما يتشكك بها ضعاف الإيمان وضعاف العقول ، فيالها من خدعة، فيها دهاء ومكر وبدعة","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3920","text":"أيها الخاطب لا تنخدع بالجمال الساحر ، والبياض الباهر ، والصدر النافر ، والخصر الخاسر ، والكَفَلِ الطافر،حتى تسأل وتستقصي ، فإن البساتين الجميلة لا تخلوا من العناكب والهامَّة ، والقوارض الطامَّة ، والثعابين السامَّة.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m3921","text":"إذا كانت القرية نائية عن العمران ، وليس فيها علماء بالفقه والقرآن ، وعقيدة التوحيد والإيمان ، انتشرت فيها الخرافات والجهالات والمحرمات ، وبعض الشائعات والشركيات ، فتكون في حاجة شديدة لوجود عالم فيها ، فالعالم في قريته كالنبي في أُمته ، والعالم في قومه كالبصير في العميان ، وحاجة الدهماء للعلماء ، كحاجة العطشان للماء.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3922","text":"ليس كل أبيض فضة، ليس كل أسود فحمة، ليس كل أصفر ذهبا، ليس كل أحمر لحما، ليس كل أحضر خيارا، ليس كل جميل طيبا، ليس كل قبيح شريرا، ليس كل طويل أهبلا، ليس كل قصير فتنة، ليس كل غني شاكرا، ليس كل فقير ناقما، ليس كل ملك ظالما، ليس كل عالم متكبرا","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3923","text":"اجعل كلماتك مثل لعاب نحلة البستان ، ولا تجعلها مثل بصاق الثعبان.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3924","text":"اسْعَ نهارا على الأطفال ، واسجد ليلا لله الواحد القهار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3925","text":"اطلب رزقك من الله بالعمل ، فإن الكلام لا يُسدد الديون ، ولا يملأ البطون.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3926","text":"رجل ضعيف عامل خير من رجل قوي خامل.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3927","text":"مهما كان تحصيلك العلمي واسعا وعميقا ، حاول أن تستفيد ممن هو أعلم منك ، فإن العلم لا حدود له.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3928","text":"عندما تسافر سوف تتعلم أشياء جديده ، وسوف يتسع أُفقك عن الحياة وعن الناس.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3929","text":"احترام الناس ومساعدة ضعفائهم تجعل حياتك أكثر سعادة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3930","text":"كافئ المجتهدين وامنح المقصرين فرصة ليجتهدوا.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3931","text":"أعظم رأس مال يجب عليك أن تنميه وتحافظ عليه هو حسناتك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3932","text":"الحياة مدرسة كبيرة ، تحوي جميع التخصصات العلمية ، أبوابها مفتوحة ٢٤ ساعة ، حاول أن تتعلم منها طوال حياتك.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3933","text":"حافظ على مبادئك النبيلة حتى لا تسقط من عيون الناس.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3934","text":"عَوِّدْ أطفالك العادات الحسنة ، فالعادات هي الطبع الثاني ، وهي التي سوف ترسم شخصيتهم مستقبلا.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3935","text":"عِشْ شبابك بنشاط وتفاؤل وأعمال صالحة وأفعال نافعة ، واستمر على ذلك ، لتحافظ على نشاطك وشبابك حتى في زمن شيخوختك.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m3936","text":"الإنسان يتعلم من فشله كيف ينجح ، لأن الفشل هو التجارب الأولى التي تسبق النجاح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3937","text":"جميع أفراد الأُسرة يجتمعون ليلة الجمعة في بيت الجدة ، وكل واحدة من بناتها تأتي بطبق أو طبقين ، مما لذَّ وطاب ، فيصبح بيت الجدة معول من معاول الرجيم ، فبيت الجدة مقبرة الرجيم ، فالرجيم يُولد يوم السبت ؛ ويدفن ليلة الجمعة ، وهكذا دواليك.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3938","text":"إذا أردت أن ترطل عقلك وتعرف مدى جهلك، وتخلفك وضحالة فهمك، وتفاهة تفكيرك وسخافة رأيك؛ فجالس العلماء والحكماء والأدباء، والعباقرة الأذكياء ، ولعل هذا يكون لك دافعا قويا لتتدارك ما فاتك من العلم والمعرفة والثقافة والقراءة ، فيكون وازعك نحو التعلم والتقدم والتنور والتطور والتحضر من داخلك من نفسك.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3939","text":"لا تستطيع أن تُكره إنسانا على حبك ، لكنك إن أحسنت إليه فسوف يُحبك طواعية.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3940","text":"لا توافق على من يريد أن تكون علاقتكما سرية من غير أن يبين لك الأسباب المُقنعة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3941","text":"حياتك سوف تكون أفضل إذا اقتصرت على الحاجيات ، ولم تُبالغ في الكماليات.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3942","text":"فالسعيد من واظب على فعل الحسنات وترك السيئات ولزم الأذكار والاستغفار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m3943","text":"لا يستطيع الإنسان أن ينهض بنفسه ، فلا بد أن يكون معه من يعضده ويساعده ويسانده ويرشده ، وأهم من يقوم بهذا الدور هما الأبوان ، وبالأخص الأم ، لطول ملازمتها له في المراحل الأُولى من حياته ، لسهولة تشكيله وإقناعه ، فالأم هي الحاضنة والمربية والمدرسة التي لها التأثير الكبير على عقيدته وقناعاته وأخلاقه وعاداته.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3944","text":"بذل الخير والمعروف ، والعطف على اليتيم وإغاثة الملهوف ، تجلب لك السعادة وتُحسن لك الظروف.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3945","text":"بوعدك بادر بالوفاء ، وبوعيدك امنحه فرصة ثانية للأداء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3946","text":"بادر بحل المشكلات التي تواجهك ، فالتأجيل يزيد في التصعيد والتعقيد.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3947","text":"ما زاد عن الكرم إسراف ، وما نقص عن الاقتصاد بخل ، وكلاهما مذموم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3948","text":"من حافظ على ماله فقد حافظ المروءتين : دينه وشرفه ، ومن ضيع ماله فقد ضيع المروءتين : دينه وشرفه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m3949","text":"خير الكلام ما كان قليله يُغنيك ، ومعناه يُرضيك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3950","text":"بعض الكلام خير من الصمت ، وبعض الصمت خير من الكلام ، فاختر الكلام المناسب للمقام المناسب.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3951","text":"الإنسان العادي يكتسب من كثرة القراءة العقل ، والعاقل يكتسب من كثرة القراءة استنارة العقل ثم العبقرية.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m3952","text":"المشورة تُنير العقل وتعينه على حسن الاختيار ، وتعصمه من الخطأ.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3953","text":"فاعرف أعداءك تسلم من كيدهم، وتنجو من مكرهم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3954","text":"مهمة العقل هي الفهم الصحيح للأشياء والعلاقات المادية والمعنوية ، واتخاذ الاختيار المناسب للتعامل معها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3955","text":"الحرية ضرورة اجتماعية للتقدم في ميادين العلوم ، بشرط ألا تُخالف القيود النقلية والعقلية والتنظيمية والعرفية السليمة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3956","text":"ينبغي أن يكون رُبَّان السفينة أكثر الملاحين علما وخبرة ، أو يكون هو ملازمه ومساعده الأول.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3957","text":"المسلمون يد واحدة على من عاداهم ، وكلمة واحدة على من ناوأهم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3958","text":"تواصل الأقرباء طبع أصيل ، وتقاطعهم عارض دخيل.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3959","text":"لا تحكم على الإنسان من الانطباع الأول ، فالنظرة الأولى حمقاء ، والرأي الأول أحمق.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3960","text":"مناخ الحروب ملوث بالشائعات والأراجيف والتهويلات والتخويفات لكسب المواقف واضعاف المخالف ، فلا تصدقوهم ولا تكذبوهم ، وكونوا منهم على حذر ، حتى يتبين لكم الصواب الذي لا يشوبه الارتياب ، ولا يُخفيه السحاب.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3961","text":"لا تفقد الأمل من تكرار الفشل فالفشل بالبدايات بوابة النجاح بالنهايات فالكعكة الأولى محروقة ثم تكون مرموقة","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m3962","text":"المستشير مُعان والمستبد مخذول.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3963","text":"بعض الناس استمِع لهم باهتمام : الأبوان والأطفال والمهموم والمظلوم والحزين والسقيم ، والناصح الأمين، وكذلك الخبير والمُجرب ، لأن كلامهم يخرج من قلوبهم أو عقولهم.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3964","text":"الصواب بين خطأين لا إفراط ولا تفريط ، لا تسيُّب ولا تشدد.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3965","text":"إذا الشعب يوما أراد الحياة ، فلا بد أن نُخَفِّض الأسعار ، ونحميه من القروض وجشع التجار ، ونضرب بيد من حديد على من يعبث بأمن الوطن من الفجار ، ونتناصح ببن الكبار ، ونحسن تربية الصغار ، ونتعاون من جميع الأعمار ، على البر والتقوى والتقدم والازدهار.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3966","text":"المدرس : هات جملة فيها ظرف مكان . الطالب : نام أبي البارحة تحت السرير . المدرس : هلا قلت : نام أبي البارحة فوق السرير . الطالب : لأن أُمي مدربة كاراتيه ، فهي قوية وسريعة الحركة ، فانتصرت على أبي في المعركة ، فنام تحت السرير ليحمي نفسه ، من لكمة أو رفسه","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m3967","text":"الديمقراطية نظام سياسي غير ناجح ؛ لأنها مبنية على الكم لا الكيف ، والقيادة في أي مجال تحتاج إلى من هو متميز بعلمه وتفكيره وأخلاقه ، فهو يحافط على مكانته وسمعته وسمعة عائلته ، فيتنزه عن كل ما يجرح نزاهته وأمانته ، فشروط القيادة مبنية على الكيف لا الكم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3968","text":"إن لم تستطع أن تنصر الحق فأظهر زيف الباطل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3969","text":"احذر من الأمين حتى تتأكد من أمانته بنفسك ، أما الخائن فأنت تحذره.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3970","text":"العفو يُصلح الشريف الصالح ، ويُفسد الوضيع الطالح.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3971","text":"لا تحاسبوا الصغار على الغفلة والنسيان كما تحاسبوا الرجال لأن عقولهم ضعيفة ، ولا تحاسبوا الشيوخ الكبار كما تحاسبوا الرجال لأن ذاكرتهم ضعيفة ، ولا تحاسبوا الرجال لأن أشغالهم كثيرة ، فالخلاصة : يسروا وسهلوا واقبلوا الأعذار ، على ما فيها من العوار ، واحفظوا مودة الصغار والرجال والشيوخ الكبار.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3972","text":"اتفاق الطبيبين أزكى من رأي الطبيب الفرد ، واتفاق الأطباء أزكى من اتفاق الطبيبين ، والأفضل أن لا يُؤخذ الرأي الطبي من طبيب فذ،وبالأخص في الأمراض النادرة والخطيرة ، بل يُؤخذ من اتفاق مجموعة أطباء خبراء مختصين.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3973","text":"الثراء الفاحش المفاجئ، مجهول الأسباب قرينة على وجود خيانة.","kind":"hikma","topic":"المال والاقتصاد","note":"يسبقه في الأصل: لكل أمة فتنة، وفتنة أمتي المال","source":"شذرات (ملف وورد)"},{"id":"m3974","text":"أسوس الساسة من يطرح أفكاره بحماسة ، ويجعل له في ضمنها مخرجا خفيا للتنصل منها عند الاضطرار ، وللفرار من الإنكار.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3975","text":"السياسي المحنك يبرر العدوان بالدفاع عن النفس ، ويبرر عدم انكار الظلم الفاحش بعدم التدخل في شؤون غيره.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3976","text":"القائد السياسي يطلب التأييد ، ويرضى بالصمت ، ويكره الإنكار.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3977","text":"بيت صغير مسكون خير من قصر كبير مهجور.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3978","text":"جامل الجميع وانصح من يقبل النصيحة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3979","text":"لن يشعر الفقير بشدة فقره إن كان يعيش في وسط عائلة تتواصل وتتراحم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3980","text":"قبل أن تنصح الشباب استحضر حالتك عندما كنت في مرحلة الشباب.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m3981","text":"إذا تكلمتم فتخيروا أطيب الكلام ، فإن اللسان ترجمان العقل.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3982","text":"الجار الصالح يُحببك في دارك ، والجار السيئ يُكرهك في دارك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3983","text":"عاقبة الظلم في الدنيا خراب ودمار ، وعاقبته في الآخرة عذاب النار.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3984","text":"لا تتكلم ولا تكتب ولا تُعاقب وأنت غضبان ، لأنك سوف تندم ثم سوف تعتذر.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m3985","text":"الرجل الثقة من شهدت أفعالُه بصحة أقوالِه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3986","text":"السياسة تحتاج إلى الصبر وسعة الصدر.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3987","text":"السياسة انتصارات سلمية ، والحرب انتصارات عدوانية.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3988","text":"السياسة الناجحة هي فن الممكن لحل المشكلات العالقة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3989","text":"السياسة السلمية تحقق المصالح المشتركة ، ولا تُفسد الأخلاق ، والسياسة العدوانية تُكسب المصالح للطرف الأقوى ، وتُفسد الأخلاق.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m3990","text":"يبتعد الإنسان عن حقيقة صواب التقدير ، بقدر غلبة العاطفة صواب التفكير.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3991","text":"العاقل يُرجح حكم العقل ، وغير العاقل يرجح حكم العاطفة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m3992","text":"لا يخلو الخوف من بعض الأمل ، ولا يخلو الأمل من بعض الخوف ، والغلبة للأرجح.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m3993","text":"احذروا الإفراط في الشهوات؛ فإنها تغلب العقول وتُفسد المروءات.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3994","text":"اخفض من صوتك ولا تحاكِ الغراب في صياحه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3995","text":"ليس الجمال بالثياب؛ إنما الجمال بحسن الأخلاق وكثرة الصواب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3996","text":"ليس الرجل بثوبه ومركبه ؛إنما الرجل بأخلاقه وعقله.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m3997","text":"لن يحمل أحزانك مثل نفسك؛ فهون عليها ففرج الله قريب.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m3998","text":"ليس في الحب والبغض اعتدال.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m3999","text":"السياسة فن الممكن فلتحقيق التوافق لا بد من التنازل من الطرفين من أجل المصلحة العامة ، ولتلافي الخلاف الذي قد يستفحل إلى صدام ، فيخسر الطرفان.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4000","text":"ليس في الحب مشورة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4001","text":"ليس للباطل أساس.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4002","text":"استشر المجرب الخبير.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4003","text":"إذا أردت السفر فاسلك طريقا فيه ماء وشجر.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4004","text":"لا تصاحب من لو ألقمته عسلا عضك ، ولو التفتَّ سرقك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4005","text":"لو كان في البومة خير ما تركها الصياد.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4006","text":"لكل عمل ثواب أو عقاب ، فصاحب أُولي الألباب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4007","text":"إن أردت الضياء والعلياء، والابتعاد عن الظلماء ؛ فجالس العلماء الأحياء ، واقرأ كتب العلماء القدماء.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4008","text":"العاقل من يعرف متى يتكلم ، وبماذا يتكلم ، ومتى لا يتكلم.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4009","text":"من استشار المجربين كان من الناجحين ، ولم يكن من النادمين.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4010","text":"الغيبيات الشرعية حقائق يقينية ، فلا تتعارض مع الحقائق العلمية اليقينية. فالقرآن قول الله والمخلوقات فعل الله ، فلا يوجد تعارض بين قوله وفعله سبحانه وتعالى.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4011","text":"أفضل هدية تقدمها لطالب علم؛ كتاب يستفيد منه في تخصصه العلمي.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4012","text":"أينما تكن فكن مفتاح خير مغلاق شَرٍّ.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4013","text":"صمت الجاهل يستر عيبه وحديثه يفضحه.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4014","text":"يُمكنك أن تُحول الأعداء إلى أصدقاء بالكلام الجميل والترحيب والتهليل.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4015","text":"لا تهدر وقتك في مشاحنات ونزاعات ، فحسبك أن تُكثر من الطاعات والحسنات.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4016","text":"لا تجعل انطباعاتك الأولية قناعات يقينية.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4017","text":"التميز يبدأ باتقان الفن المُراد ، ثم الإبداع بأدائه مع المحافظة على قواعده الأساسية.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4018","text":"إن الله جلت حكمته خلق المرأة على هيئة مميزة تعجب الرجل ، لتستمر الحياة إلى أجلها.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m4019","text":"مفتاح تعلم ما لا تعلمه ، هو الجرأة في البدايات للتعلم ، فالجرأة مفتاح التعلم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4020","text":"أُحب أن أعيش متواضعا ومعي أموال كثيرة أُساعد بها الفقراء والضعفاء ، ونية المؤمن خير من عمله.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m4021","text":"يُقاس الشباب بالقوة والنشاط والحيوية، والتفاؤل والمبادرة بالإنجاز.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m4022","text":"التَّميز يبدأ بتقليد المتميزين ومحاكاة المتفوقين ، ثم تتخذ أُنموذجا خاصا بك.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4023","text":"الطفل الصغير لا يُحسن الوقوف والمشي ، فما يزال يحاول ويحاول بلا ملل ولا كلل حتى يحسن المشي ثم يحسن مهارات المشي ، ثم يصبح المشي لديه عادة وملكة ، فحاول أيها الكبير أن تتعلم ما لا تحسنه بمثابرة وإصرار حتى تتعلمه ثم تكتسب مهاراته ثم يصبح عادة وملكة.","kind":"hikma","topic":"النجاح والإبداع","note":"بعنوان: تربية النفس","source":"شذرات (ملف وورد)"},{"id":"m4024","text":"الرجل يوضع له القبول بحسن الأخلاق ، ويسمو ذكره في الآفاق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4025","text":"صاحب ذا الأخلاق الحميدة ولا تصاحب ذا الأخلاق الرديئة ، فإن الطباع تُعدي.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4026","text":"إن المرء ليكسب الحسنات التي تُثقل ميزانه يوم الحساب ، بحسن الأخلاق والآداب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4027","text":"علمتني التجارب أنها طريق العلم اليقيني.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4028","text":"من السهل أن تكتشف الكاذب إذا كانت ذاكرته ضعيفة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4029","text":"قدرة الإنسان على نصيحة غيره أقوى من قدرته على نصيحة نفسه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4030","text":"كم سيفخر الآباء ويسعدون بأبنائهم؛ لو أنهم اهتموا بتربية إيمانهم وأخلاقهم وآدابهم وعاداته وعلمهم؛كما يهتمون بتربية أبدانه وهندامهم وصحتهم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4031","text":"إن لم تستطع أن تقول كلمة الحق بلسانك، فقلها بقلبك واستغفر لذنبك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4032","text":"احترام الناس لك يبدأ من احترامك لهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4033","text":"الفرق بين الأفعال الإيجابية والسلبية ، أن الأولي تستدعي الراحة النفسية ، أما الثانية فتستدعي التوتر والقلق.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4034","text":"أينما كنت فازرع الخير بحسن أخلاقك وجميل كلامك وصفاتك ، وفضائل طبعك وعاداتك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4035","text":"من فَنِّ الدعاء أن يكون بكلمات متآلفة ، وجمل قصيرة ، ويكوة جامعا ومختصرا ، ليسهل نشره وحفظه ، وخير الدعاء ما ورد في الكتاب والسنة، ثم ما نُقل عن الصحابة والتابعين رضي الله عنهم أجمعين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4036","text":"أفضل الجود بالمال، العطاء قبل السؤال.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m4037","text":"الاستغفار صابون الذنوب ، والجود بالمال يقرب القلوب.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4038","text":"بحسن الأخلاق تُكَفَّر الذنوب ، وبالجود تُستر العيوب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4039","text":"عند الشدائد الثقال تظهر مواقف الرجال.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m4040","text":"التاجر ذو الأخلاق تتسع عليه الأرزاق.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m4041","text":"الخشية من الله العظيم الأقوى ، دليل على التقوى.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4042","text":"أفضل المصانع أن تصنع الأبناء على تربية الإيمان والأخلاق ، وعلى عادات الشرفاء ، وآداب الأتقياء، وسخاء الكرماء، ومروءة النبلاء","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4043","text":"ما هجر القرآن من آمن به وعمل بما وجب عليه فيه","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4044","text":"كل جيل يرى أنه أفهم من الجيل الذي قبله وأطيب من الجيل الذي بعده","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m4045","text":"أعرف الناس بالله أشدهم له خشية ، وأحسنهم ظنا بالله تعالى.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4046","text":"الحلم سيد الأخلاق ، وبالسعي والاستغفار تطلب الأرزاق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4047","text":"الأقربون أولى بالمعروف ، وهم أول من يُنعشك إذا ساءت الظروف.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4048","text":"عامل السفهاء بأخلاقك العالية لا بأخلاقهم الواطية، فسوف يتأثرون بمعاملتك الراقية.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4049","text":"إن كنت غنيا فكن متواضعا ، وإن كنت فقيرا فكن قانعا ، وإن كنت قويا فكن هينا ، وإن كنت ضعيفا فكن عزيزا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4050","text":"الضحك بلا سبب من قلة الأدب ، ويجلب التسخط والعجب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4051","text":"ينقص من عقل الإنسان بقدر غضبه،وكذلك ينقص بالحماس لكن أقل من الغضب","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4052","text":"قبل أن تخالط الناس تعلم فن الابتسامة والتغافل وحسن الاستماع والاهتمام والاحترام.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4053","text":"المبادرة بحسن الظن ورطة ، والتريث وقاية من الغلطة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4054","text":"أفضل الرجال أكثرهم نفعا، وأعفهم طمعا ، وأحسنهم طبعا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4055","text":"من لانت كلمته؛ حسنت طَلَّتُه ، ووجبت محبته ، وحُمدت سيرته.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4056","text":"كفى بالمرء صلاحا أن تُعَدَّ زلاتُه ، وتُحصى هَنَاتُه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4057","text":"من لم يوقر العلماء والأتقياء؛ فهو من السفهاء والبلهاء.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4058","text":"قالوا لهمام : لماذا لا تتزوج ؟ قال : أنا ضد الزواج . قالوا : قد بلغت الأربعين . قال : لأني في الحالتين أنا خسران . قالوا له : كيف ذلك ؟ قال : إذا قسوت على زوجتي قالوا : ذيب ، وإذا صرت حبوبا قالوا : خروف . ففي كلا الحالتين أنا حيوان","kind":"tarfa","note":"نسخة أخرى في 7307-7312","source":"شذرات (ملف وورد)"},{"id":"m4059","text":"لا تعاهدوا الله تعالى وإن كان ولا بُد فعاهدوا أنفسكم فلأن تغدروا بأنفسكم خير لكم من أن تغدروا بعهد الله تعالى ، فكان عهد الله مسؤولا ، وكان الإنسان ظلوما جهولا كسولا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4060","text":"الفرق بين تقوية علاقة الحب بين الطالب والمدرسة ، وبين تقوية علاقة الكراهية بين الطالب والمدرسة ، فالأولى تشجع على طلب العلم ، والثانية تنفر من طلب العلم ، فمراعاة الحالة النفسية مهمة في طلب العلم وفي كل شيء.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4061","text":"من وهبك العقل والجوارح والمفاصل فقد أمرك قدرا بالسعي والاجتهاد والأخذ بالأسباب ، فإن الله جعل لكل شيء سببا ، فأينما وجدت الأسباب فثَمَّ قدر الله تعالى ، فتوكل على الله أولا، ثم اسع في تحقيق مصالحك الدينية والدنيوية.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4062","text":"الدعاء إما مجاب،أو لدفع مصاب ، أو ليوم الحساب","kind":"hikma","topic":"الإيمان والعبادة","note":"المُصابُ: الشدةُ النازلَةُ","source":"شذرات (ملف وورد)"},{"id":"m4063","text":"ما ينبغي الهجوم على ظواهر الآيات، واقتحام أبوابها، والتسلق على أسوارها ، والأخذ بما ينقدح في الذهن منها ، قبل الرجوع إلى كتب التفسير ، التي تُلقيت عن التابعين عن الصحابة عن رسول الله صلى الله عليه وسلم ، وبما أدركوا من معاني القرآن بما لدى الصحابة والتابعين من ملكة اللغة العربية الفصيحة الصافية النقية ، وكذلك من جهابذة علماء التفسير.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4064","text":"البيض الأحسن حسب العناية بتربية الدجاجة ونوع غذائها الحليب الأحسن حسب العناية بتربية البقرة ونوع علفها اللحم الأحسن حسب العناية بتربية الغنم ونوع علفها الإنسان الأحسن حسب العناية بتربيته ماديا وأخلاقيا وعلميا وإيمانيا","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4065","text":"الحذر الحذر الحذر من خدع غيره فقد خدع نفسه من غش غيره فقد غش نفسه من ظلم غيره فقد ظلم نفسه","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4066","text":"أكثروا من ذكر الله تعالي في جميع الحالات والأوان فذاكر الله جليس الرحمن وهو في الحفظ والأمان فلايخشى من تقلب الزمان فعاقبته روح وريحان","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4067","text":"لا تكتمل صفات الأمير نحو رعيته حتى تكون رعايته لهم كرعاية الأب لأبنائه ، فإن كان كذلك فسوف يكون حبهم وتقديرهم له كحبهم لآبائهم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4068","text":"القدوة الحسنة نصيحة فعلية عامة مستدامة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4069","text":"رجل بلا أخلاق سيارة بلا كابح تسير في الأسواق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4070","text":"شجع أولادك على طلب العلم ، وشجعهم على حب العلم ؛ ببيان فضائل العلم ، فالعلم نور في العقول ، وسبيل للتقدم والوصول.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4071","text":"لا تضع التفاحة الجيدة وسط التفاح المعطوب ، ولا تسمح لأولادك أن يرافقوا أولادا غير مهذبين ، فالصاحب ساحب ، المؤدب والمشاغب.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4072","text":"صمت الجاهل ستر جميل، يظنه بعض الناس أنه حكيم.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4073","text":"من جالس المشبوهين فلا يلومن من أساء الظن به.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4074","text":"إن العقول تمل كما تمل النفوس فابتغوا لها طرائف الحكمة ، وشذرات العلم ، لتستعيد نشاطها.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4075","text":"صديقك من واساك في الشدائد لا من تناساك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4076","text":"غضب الشجاع في أفعاله وغضب الجبان في أقواله.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4077","text":"احذر من مصاحبة المنافق ، فيغريك بالباطل ويصدك عن الحق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4078","text":"إذا أقبلت الدنيا فتنت ، وإذا أدبرت أحزنت.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m4079","text":"عدم الأدب يثير الشغب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4080","text":"من صبر ظفر ومن ضجر تأخر.","kind":"mathal","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m4081","text":"من عرف الحق عرف أهله ، ومن عرف الباطل عرف أهله.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4082","text":"عقل ابن آدم على طرف لسانه ورأس قلمه ، فيوزن عقل المرء من كلامه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4083","text":"من تعلم صغيرا ساد قومه كبيرا.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4084","text":"رغبتك في زاهد فيك مذلة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4085","text":"من طبيعة الإنسان أنه في أجواء الإنفعال والحماس يقول ويَعِد ويشترط على نفسه ، ثم يفتر ويبرد ويعتذر ويتعلل ويتوارى.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4086","text":"الاستكبار ليس من شيمة الأبرار.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4087","text":"الجهل بئس القرين.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4088","text":"العلم خير الأصحاب.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4089","text":"كن سمحا مع الناس، وكن حازما مع نفسك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4090","text":"تمسك بالحق فإن أهل الحق هم أهل السنة والجماعة وإن كانوا قليلا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4091","text":"استعينوا على الرخاء بالشكر ، وعلى البلاء بالصبر.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m4092","text":"إذا تُرك إنكار الباطل ظن أهل الباطل أنهم على حق.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4093","text":"رجل ارتكب فعلا فاضحا ، فأراد أن يسافر ليستر على نفسه ، فاستشار صديقه إلى أين يسافر ؟ فقال له : استراليا ، فقال : لماذا ؟ قال : لأن فيها : استر !","kind":"tarfa","note":"من رواية ابنه صلاح","source":"شذرات (ملف وورد)"},{"id":"m4094","text":"التجارب لا تكذب وهي أوثق طريق للعلم والمعرفة ، في جميع مجالات الحياة وميادينها ، وإذا لم تجرب لم تعرف ولم تتعلم ، ولم تكسب المهارات ، وتتفوق في الإنجازات والامتيازات.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4095","text":"المبالغة في الضحك تُجرِّئ السفهاء ، والمبالغة في الحزم تُنفرالأصدقاء ، فعليك بالنمط الأوسط نهج الحكماء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4096","text":"إذا اشتد الجوع فكل طعام لذيذ.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4097","text":"بيت صديقك وحديقته أجمل من بيتك وحديقتك لأن عينك شبعت وملت من بيتك وحديقتك ، وكذلك الأشياء الأُخرى.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4098","text":"إن كنت أمينا على أسرار غيرك ، فالأحرى بك أن لا تبوح بأسرارك ، ولا الشاذ من أفكارك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4099","text":"لا تبادر بتصديق الأخبار ، لعلها تكون من الشائعات الكبار.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4100","text":"لا تبالغ بالتحية والترحيب فتثير الشك في قلب الصديق والحبيب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4101","text":"إذا أذنبت فاستغفر ولا تتمادى ، وإذا أخطأت فاعتذر ولا تتكبر.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4102","text":"من كانت عادته التوبة والاستغفار، فقد هُدي إلى طريق الأبرار ، وأحرز مغفرة الرحيم الغفار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4103","text":"الإنسان يعرف أشياء كثيرة نافعة له في دينه ودنياه لكنه لا يعملها ولا يزاولها ، وإذا عملها لا يستمر عليها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4104","text":"أحسن ظنك بالناس إحسان عاقل لا إحسان أهبل يمتخط بكمه","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4105","text":"خيركم من إذا خرج أسد وإذا دخل فهد فهو في الخارج له هيبة ووقار، ومكانة وانتصاب قامة ، ورزة ومعزة ، وإذا دخل هين لين ، لطيف خفيف ، يمازح أهله ويداعب أطفاله","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m4106","text":"لا تُبَغِّضْ نفسك لأهلك فتكون بين أصحبك مبتسما وبين أهلك عابسا ولكن كن بين أصحابك مبتسما وبين أهلك أكثر ابتساما وسلاما","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m4107","text":"خير الكلام ما كثر إدامه وقل مأدومه ، والنصيحة إذا طالت أسأمت ، وأنسى أولُها آخرَها ، وخير الكلام ما دَلَّ قليلُه على كثيره.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4108","text":"قارن نفسك مع من دونك في الدنيا ، ومع من فوقك في الدين","kind":"hikma","topic":"العقل والحكمة","note":"بعنوان: القاعدة الذهبية","source":"شذرات (ملف وورد)"},{"id":"m4109","text":"تعلم من تجارب من سبقك ، وابدأ من حيث انتهوا.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4110","text":"اطلبوا الراحة بالعمل ، فمن يريد الراحة فليعمل.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4111","text":"تجنب الأعمال والأقوال والمواقف التي تجلب لك التهمة والشبهة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4112","text":"أحسن ظنك بالناس بقلبك واحترس منهم بعقلك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4113","text":"قبل أن تخرج من بيتك ضع على لسانك مِلْعَقَةَ عسل، وقبل أن تدخل في بيتك ضع على لسانك مِلْعَقَتَين عسل.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4114","text":"أيما ربح خرجت منه بخسارة من دينك أو بدنك فأنت خاسر ، وأيما خسارة خرجت منها بسلامة في دينك وبدنك فأنت رابح.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4115","text":"لزوم ما لا يلزم غير مرغوب لا تُلزم نفسك بتكرار تغريدات مكررات باردات لا تتضمن فائدة ولا عائدة لا نصيحة فصيحة ولا طرفة لطيفة ولا موعظة خفيفة ولا مسائل فقهية صحيحة ولا أخبار صادقة مريحة","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4116","text":"خير الكلام ما كثرت معانيه وقلت مبانيه","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4117","text":"خير الكلام ما كثرت فوائده وقلت زوائده","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4118","text":"خير الكلام الفصيح الصحيح الصريح وفيه ثناء ومديح وفيه بعض التلميح","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4119","text":"سألوا متشائما : لماذا تأخرت عن الزواج ؟ قال : أنا لا أنصح بالزواج ! قالوا له: لماذا لا تنصح بالزواج . قال : إذا صرت قويا على زوجتي ، قالوا : ذيب . وإذا صرت ضعيفا قالوا : خروف . فأنا في كلا الحالتين أصير حيوانا !!","kind":"tarfa","note":"نسخة أخرى من طرفة 7140","source":"شذرات (ملف وورد)"},{"id":"m4120","text":"الناس صنعوا أنواعا كثيرة من الأسلحة ليقتل بعضهم بعضا ، لكن الحيوانات لم تفعل ذلك.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4121","text":"الإبداع أوله تخيلات وآخره انجازات.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4122","text":"عقل الطالب وعاء فارغ علىك أن تملأه بالمعلومات النافعة ، وهو شمعة عليك أن توقدها بالمفاهيم الصحيحة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4123","text":"إن الله يبتلي عبده الصالح بالمرض، ثم يصبره ويفتح له باب الذكر والدعاء، والمرض للمؤمن صابون الذنوب ، وتطهير القلوب ، فإذا بدأ المرض يخف فأبشر بالصحة ، فالمرض يأتي متسارعا ، والصحة تأتي على مهل ، فإذا تَشَهَّى المريض الطعام فبشروه بالعافية ، والصحة من النعم العظيمة المنسية.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m4124","text":"السؤال مفتاح العلم وبوابة الفهم ومِغْرَفة التحصيل ، فلا تجعل الحياء يحول بينك وبين السؤال ، فكن صاحب لسان سؤول وقلب عقول.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4125","text":"كونك على الحق لا يبرر لك أن تُخاشن أخاك الذي على الباطل ، بل تعامل معه تعامل الطبيب مع المريض ، ولا تغلق الأبواب المفتوحة التي بينكما ، فدعوة الأخلاق أنجع من دعوة الأقوال ، وهي تمهد لقبول دعوة الأقوال.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4126","text":"احرص على أن تكون رجلا ناجحا صالحا فاهما عالما.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4127","text":"خالط الرجال الصالحين الذين تستفيد من أقوالهم وأفعالهم وأخلاقهم ، فسوف تكون منهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4128","text":"من أراد تحقيق التميز والتفوق والإبداع ؛ فعليه مواصلة طلب العلم من غير انقطاع.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4129","text":"إقرأ كثيرا وتكلم قليلا ، فكر طويلا قبل أن تُقرر ، اسمع كثيرا واحفظ أفضل ما تسمع ، وتحدث بأفضل ما تحفظ ، واعمل بأفضل ما تتحدث.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4130","text":"الرجل العاقل الصالح يُحسن ظنه بالناس ويحترس منهم ، والرجل الطالح يسيء ظنه بالناس حتى الصالحين منهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4131","text":"من يريد الصحة فليصبر على مُرِّ الدواء ، فإن المرض يأتي متسارعا بعكس الشفاء.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4132","text":"معرفة أسباب المرض نصف العلاج ، ومعرفة أسباب المشكلة نصف الحل،ومشكلة انحراف المراهق أو الشاب من الرفقة السيئة، فالحل يكمن في حرص الوالدين على عدم مرافقته لمجموعة شباب غير صالحين وغير مؤدبين وبهذا نغلق بوابة الشر ، ونحرص على أن ينضم إلى رفقة صالحة مهذبة مؤدبة ، تعينه على اكتساب الخصال الصالحة ، والأخلاق المهذبة.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4133","text":"من حفر تحت جداره يُوشك أن يسقط جدار جاره.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4134","text":"نعم الإدام الجوع ، وبئس الإدام الشبع.","kind":"mathal","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4135","text":"إذا كنت لا تستطيع الابتسامة فلا تفتح بقالة.","kind":"mathal","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m4136","text":"حسن الخط يزيد في جمال الحق ، ووضوح الخط حرز من الخطأ والاحتمالات المرجوحة","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4137","text":"كلٌ يحلم على قدر عمره واهتماماته.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m4138","text":"إذا اعتاد الإنسان الباطل المرجوح ينفر من الحق الراجح ، وهذه هي مشكلة الأنبياء عليهم السلام مع أقوامهم.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4139","text":"احذروا الوتساب فالوتساب خطير ولا يسلم من الخداع والتزوير","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4140","text":"الحديث باللغة العربية لغة قرآنية وسنة نبوية وشعيرة إسلامية،وأمارة قومية","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4141","text":"قبل أن تبدأ عملا لأول مرة فاطلب المؤازرة بالمشاورة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4142","text":"الجهاد باب من أبواب الجنة ، وأعظم الجهاد جهاد النفس.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4143","text":"من تواضع عزَّ ومن تكبر ذلَّ.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4144","text":"الصمت عن فضول الكلام هيبة ، والخوض في أعراض الناس خيبة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4145","text":"مكارم الأخلاق تجلب الوَقار ، وأراذل الأخلاق تجلب العار.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4146","text":"الغِنى في الغُربة مكانة ، والفقر في الوطن مهانة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m4147","text":"المال يستر عيوب الأغنياء ، والفقر يستر فضائل الفقراء.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m4148","text":"أعقل الناس من يسع بعقله الناس.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4149","text":"احذروا من آراء الدهماء ، وعليكم بآراء العلماء ، ولا تأخذوا بالرأي الذي يُخالف رأي العلماء.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4150","text":"إن الله تعالى خلق عباده للأبد ، ولكنهم آثروا دار الفناء على دار البقاء ، فانغمسوا في الشهوات ، وقصروا في الطاعات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4151","text":"من آتاه الله نعمة ثم ابتلاه بنزعا وعوضه منها الصبر والحمد والرضا ، كان ثواب الذي أعطاه خيرا من الذي أُخذ منه.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m4152","text":"لا ينفع نفسه من لا ينتفع بعلمه وتجاربه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4153","text":"أفضل العبادات أداء الواجبات واجتناب المحرمات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4154","text":"إذا مات الرجل الصالح استراح من عناء الدنيا ، وإذا مات الرجل الطالح استراح منه أهل الدنيا.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m4155","text":"الانبساط يُجرئ عليك الجاهل ، والانقباض يُنفر منك العاقل ، فلا تنبسط للجاهل، ولا تنقبض للعاقل.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4156","text":"لا تبالغ في الانبساط فيجلب لك قرين السوء ، ولا تُبالغ في الانقباض فيجلب لك المقت.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4157","text":"حافظ على صلة أرحامك بالسخاء والصبر على الجفاء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4158","text":"إن أردت كلامك أن يُسمع فقدم بين يديه طعاما يُبلع.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4159","text":"احذر مِمَّنْ عدَّدَ لك عيوب الناس فسوف يُعَدِّد عيوبك للناس.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4160","text":"الكوارث الطبيعية تحمل الإنسان على اكتشاف ما يُعين على تلافيها مستقبلا أو تقليل أخطارها","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4161","text":"احذر من مقدمة الثعبان ومن مؤخرة العقرب ، واحذر من مقدمة الثور ومن مؤخرة الحمار ، أما المرأة فكالنار الموقدة ، احذرها من جميع نواحيها، فهي فتنة وإغراء ، وفخ الشيطان للشاب الصالح","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4162","text":"إذا كثرت الدندنة والتكرار والأراء والأقوال والأفكار واختلاف علماء الأمصار فعليكم بالرأي الراجح قبل الاختيار","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4163","text":"نحن في زمان اختلط فيه الحابل بالنابل والوعول في السهول والجمال على رؤوس الجبال","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m4164","text":"السنة وعاء زمني مقدر ، وهو مرحلة عمرية ، وقابل لأن تملأه بالخير والمعروف والنشاط والعمل الصالح ، لنفسك وأهلك ووطنك وأُمتك والعالم أجمع ، وقابل لضد ذلك ، فاحرص واجتهد على أن تملأه بما ينفعك في دينك ودنياك،مستعينا بربك ومولاك ، واجعل شعارك : (خير الناس أنفعهم للناس)","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m4165","text":"جاهدوا أهواءكم في السلم ، كما تجاهدون أعداءكم في الحرب.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4166","text":"من أمارات حُبِّ المرء لرَبِّه ؛ أن يأنس بكلام الله وذكره أكثر مما يأنس بكلام الناس وأُنسهم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4167","text":"من غلب شهوات نفسه فهو عصيٌّ على شيطانه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4168","text":"بين العبد ورزقه القناعة والشكر ، فإن قنع وشكر بارك الله له في رزقه ، وإن جحد وتذمر لم يُبارك له في رزقه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m4169","text":"الدنيا دار زراعة والآخرة دار حصاد ، فبقدر ما تزرعون من الحسنات تحصدون من الخيرات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4170","text":"إذا سألت الله الرزق فقل : اللهم أعني على طلب الرزق ، ثم اجتهد وشمر عن ساعديك في طلب الرزق.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m4171","text":"حاورصغارك كما تحاور كبارك حاورهم بفويق مستواهم بطريقة سهلة ميسرة لتنمي قدراتهم الاستيعابية والحوارية والعقلية والنقاشية واللغوية هذه أساليب تربوية ناجحة","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4172","text":"إن المؤمن قلبه مطمئن بالإيمان ، فلا يسأل عن صفات الله بكيف ، ولا يسأل عن أقدار الله بلماذا ، فهو يؤمن بصفاته ويُسلم لأقداره.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4173","text":"لأن تمشي مع أخيك خطوات في إنجاز حاجته خير من أن تجول مسافات شاسعات للتنزه والفرجات.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4174","text":"إذا هجم عليك كلب فاستعن بصاحبه ليردعه عنك ، وإذا وسوس لك الشيطان فاستعذ بخالقه ليصرفه عنك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4175","text":"لا يجتاحك الغرور فتظن أن الثبات على الاستقامة من جهدك ونشاطك ، بل هو من توفيق الله لك ، فاستعن بالله على شكره وذكره.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4176","text":"من لم يحفظ لسانه عن أعراض الناس فقد ضيع حسنات صلاته وصيامه.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4177","text":"الجهاد الأكبر جهاد النفس فإن النفس أمارة بالسوء.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4178","text":"الزهد في الدنيا يرفع عنك تكاليف الحياة الباهظة.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m4179","text":"من علامة اعراض الله عن عبده أن يعرض العبد عن ربه ، فالجزاء من جنس العمل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4180","text":"خالط الناس على ثلاث طبقات : اجعل كبيرهم أبا وصغيرهم ابنا وأوسطهم أخا ، وعساك تسلم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4181","text":"إن لم تستطع أن تنفع أخاك فلا تضره ، وإن لم تستطع أن تعينه فلا تهنه ، وإن لم تستطع أن تشجعه فلا تخيبه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4182","text":"الناس على الاستقامة ما كانوا على التقوى ، فإن قصروا في التقوى فقد زلوا عن الاستقامة","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4183","text":"استعينوا على قضاء حوائجكم بالدعاء والصبر والكتمان.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4184","text":"قضاء حوائج الأيتام خير من التنفل بالاعتكاف والصيام.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4185","text":"الأيام أوعية زمانية تجري باستمرار ، فاملؤوها بذكر الله والاستغفار.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m4186","text":"خير مجالسكم ما أقام البدن وسافر النظر مجلس مرتفع وتنظر حولك الأشجار والثمار والأطيار والأزهار والحيوانات والأنهار والقمر والنجوم والغيوم.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4187","text":"إذا أردت أن تعرف بواطن أخلاقه فارصده عند الغضب لأن الأنسان في حالة الغضب لا يستطيع أن يتصنع فيظهر على حقيقته المخفية","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4188","text":"اسألوا الله الحكمة والرحمة، الحكمة تعصمكم من الخطأ، والرحمة تحفظكم من العذاب.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4189","text":"إنَّ عليك في علمك حقا أن تنشره، وإن عليك في مالك حقا أن تتصدق منه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4190","text":"كل كلمة نهتك عن قبيح أو حثتك على مليح فهي حكمة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4191","text":"اقتصاد في سُنَّةٍ صحيحة خير من اجتهاد في بدعة قبيحة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4192","text":"ثناء الناس على الميت بالخير بشارة بنجاته، وثناء الناس على الميت بالشر لا يُبشر بنجاته.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4193","text":"كلما تطورت الأقفال والتقنيات تطورت اللصوص والمافيات","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m4194","text":"الديمقراطية ابتدعها من عندهم شريعة سماوية محرفة، وسار عليها من ليس لديهم شريعة سماوية، أما المسلمون فحسبهم هدي ربهم وسنة نبيهم، فنظامهم الشورى وتكون بين عقلاء القوم وصالحيهم أهل الخبرة والدراية والكفاية والكفاءة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4195","text":"يا شباب يا نبلاء ارحموا من في الأقفاص السجناء يرحمكم من في السماء. نظفوا بيوتها لصحتها، وأخرجوها من حبسها للتريض، وشكلوا في علفها للتشهي والمتعة، وأخرجوها في الفضاء لتستمتع وتنتعش بجمال الأجواء، ولا تُهملوا السجناء فيشكوكم لرب السماء، واعلموا أن في كل كبد رطبة أجر وثواب، وفي ظلمها عقاب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4196","text":"خير موائد طعام الإنسان ما تنوعت فيه الألوان فهو موافق لصحة الأبدان","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4197","text":"خذوا من الرأي في الدين ما لا يُخالف الفقهاء، وفي الدنيا ما لا يُناطح العلماء.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4198","text":"اتقوا المحارم فإن أعبد الناس من اتقى المحارم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4199","text":"من لم يعلم أنه مُؤاخذ بما يقول فقد تفاقمت سيئاته.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4200","text":"من اغتبته فقد كفأت كِفَّةَ حسناتك في كِفَّةِ حسناته، وأنت أحوج ما تكون إليها.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4201","text":"بِرُّ الآباء بالأبناء انفعالات غريزية, وعاطفة فطرية، ومحبة نقية، وهي موجود في الكائنات الحية. وبِرُّ الأبناء بالآباء دِيانة ودَينا وجزاءً وانتماء وحبا.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4202","text":"إن الله جعل لكل شيء بابا ولكل باب مفتاحا، فالباب أن تأخذ بالأسباب، والمفتاح أن تطلب العون من الوهاب.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4203","text":"إن العقول مظلمة فأنيروها بذكر الله، والقلوب غافلة فذكروها بآيات الله، والنفوس شاردة فقيدوها بطاعة الله تعالى.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4204","text":"كفى بالموت اعتبارا، وبالتوكل على الله انتصارا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4205","text":"جاهدوا أنفسكم كما تجاهدون أعداءَكم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4206","text":"الصبر على طاعة الله عاقبته الجنة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4207","text":"من جاهد نفسه وأصلحها فقد صار قدوة لغيره وهو لا يعلم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4208","text":"من صفات الرجل الصالح أنه يأمر بالمعروف وينهى عن المنكر بنص القرآن الكريم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4209","text":"ربما قال الآباء للأبناء كلاما فيه النصائح والشفاء فلم يستوعبوها حتى يقعوا في البلاء فعلى الأباء أن يعذروا الأبناء لأن بعض مفاهيم الحياة لا تُفهم إلا بالتجارب والعناء","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4210","text":"أحبُّ الناسِ إلى الناس أنفعهم للناس. فالقلوب تتهافت على من يُكرمها وينفعها، ولو كان غير صالح في نفسه. ولا تتهافت القلوب على من لا يكرمها ولا ينفعها ولو كان صالحا في نفسه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4211","text":"إذا سمعت من أخيك كلمة تحتمل المدح والقدح، فاحملها على محمل المدح، حتى لا تدع للشيطان مدخلا ليُفسد العلاقة الحميمة التي بينكما.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4212","text":"من ابتلاه الله بمصيبة شنعاء، فألهمه الصبر والرضى بالقضاء، كان هذا العطاء خيرا من الذي أخذه منه بالابتلاء.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m4213","text":"إن الله جلت حكمته خلق الإنسان للبقاء لا للفناء، فإن أطاعه فقد ربح نفسه، وإن عصاه فقد خسر نفسه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4214","text":"عِشْ لتَتَعلم، وتعلم لتعمل، واعمل لتكسب المهارة، واكسب المهارة لتكسب الخبرة، واكسب الخبرة لتتوصل إلى المَلَكَة، وتوصل إلى الملكة لتكون مبدعا متميزا مخترعا.","kind":"hikma","topic":"النجاح والإبداع","note":"تحت عنوان: طريق الإبداع والاختراع","source":"شذرات (ملف وورد)"},{"id":"m4215","text":"كل شيء أو عمل ديني أو دنيوي فيه منفعة لا يعمل به صاحبه فقد خسر منفعته بإهماله وتقصيره.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4216","text":"العمل نشاط وعِزة والبطالة خمول وذلة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4217","text":"عليكم بالنشاط فإنه يُسَهِّل الأعمال الصعبة، واحذروا الكسل فإنه يُصَعِّب الأعمال السهلة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4218","text":"إذا تأخرت الأمطار، جفت العيون والآبار، بكثرة الذنوب والإصرار، فلنكثر من التوبة والاستغفار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4219","text":"كلما كثرت أموالنا كثرت أشغالنا وهمومنا، وقل اهتمامنا بآخرتنا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m4220","text":"من وسائل تحقيق السعادة الناجعة؛ أن نسعى لتحقيق سعادة من دوننا، ونُعينهم في الفاجعة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4221","text":"طريق النجاح هو عدم تكرار الخطأ، فيتعلم الإنسان من أخطائه. طريق الفشل هو تكرار الخطأ، فلا يتعلم الإنسان من أخطائه.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4222","text":"إن الخير ليُطفئ نار الشر كما يُطفئ الماء النار، فادفع الشر بالخير.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4223","text":"حلمك على السفيه يُكثر أنصارَك عليه","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4224","text":"سعادة المرء تزيد بمشاركة أحبائه وأصدقائه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4225","text":"القيام بالواجبات تعقبها السعادة، وإهمال الواجبات تعقبها التعاسة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4226","text":"السعادة في الدنيا ناقصة وفانية، والسعادة في الجنة كاملة ودائمة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4227","text":"من سالم الناس سلِم، ومن عاداهم ندِم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4228","text":"من أعان ظالما فهو أحد الظالمين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4229","text":"من كثر مزاحه قلت هيبته، ومن كثر تزمته كُرهت مجالسته.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4230","text":"الحمد لله على كل حال الزيادة بعد النقصان والأرباح بعد الخسران والأفراح بعد الأحزان ومن حمد الله بعد الخسران زادت حسناته في الميزان ونال من الله الرضوان","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m4231","text":"من علم أن ثواب فعل الخير يعود عليه، خف عليه فعل الخير، فداوم على فعل الخير. من علم أن إثم فعل الشر وبالا عليه كف عن فعل الشر.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4232","text":"من أبصر عيوبه عمي عن عيوب الناس، ومن عمي عن عيوبه أبصر عيوب الناس.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4233","text":"اشراقة براقة: من عمل الواجبات وترك المحرمات نجا من النار وفاز بالجنات والمكرمات","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4234","text":"ذاكرة المظلوم أقوى من ذاكرة الظالم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4235","text":"قد تبرأ من الزلة الرِّجْلان؛ ولا تبرأ النفس من زلة اللسان.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4236","text":"السعادة تبحث عمن يُسعد الناس.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4237","text":"من لم يكن له من نفسه واعظ؛ لم تنفعه المواعظ.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4238","text":"من ظلم الأيتام فقد أغضب رب الأنام.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4239","text":"اتقِ الآثام تكن من أفضل الأنام.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4240","text":"الأغنام تعيش في رعب من الذئاب، ثم يذبحها الذي يحميها في الحظائر خلف الأبواب.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4241","text":"لا تحكم على الأشياء قبل تجربتها، ولا على الرجال قبل معرفتها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4242","text":"طعنة الأعداء تُدمي الأبدان، وطعنت الأصدقاء تدمي الجَنان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4243","text":"من يتخذ قرارات شديدة في مقر عمله قرارات حماسية أكثر منها عقلانية ومباغتة لا تدريجية فإنما يُكَوِّنُ جبهة صُلبة ضده،تبحث عن أخطائه وتُفتش عن تقصيراته وقد تفتري عليه والكثرة تغلب الشجاعة","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4244","text":"فليس من الخير للبشر الاسترسال في مسائل القضاء والقدر، فهو مضلة أفهام ومزلة أقدام، وبوابة أوهام.","kind":"hikma","topic":"الإيمان والعبادة","note":"من مقالة عن الإيمان بالقضاء والقدر","source":"شذرات (ملف وورد)"},{"id":"m4245","text":"كتمان الأسرار من شيمة الأبرار، وإفشاء الأسرار من شيمة الفجار.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4246","text":"التسويف يُؤخر الأعمال ويصرف عن الكمال.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4247","text":"التصرف أثناء الغضب كالإبحار أثناء العطب.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4248","text":"لن تعرف حقيقة المرء حتى تسافر معه أو تساكنه أو تستغضبه أو تعامله بالدينار والدرهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4249","text":"عاشر الصالحين فإنهم يُعينونك على الطاعات وفضائل العادات.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4250","text":"السفر الشاق يُظهر مزايا الأصدقاء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4251","text":"من طبعه الجود يجود من قلة، ويصون وجه السائل عن المذلة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4252","text":"اطلبوا الأرزاق بالأرزاق، ارزقوا الفقراء يرزقكم رب السماء.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m4253","text":"من فقد الأمل فقدْ فقدَ بهجة الحياة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4254","text":"تخفيف الأحزان يُقرب من السعادة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4255","text":"ابكِ مع نفسك وابتسم مع الناس.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4256","text":"آثروا السلم ما أمكن واحذروا الحروب فإن خسائرها تمتد إلى فترات طويلة بعد الحروب، وربما يتحمل آثارها الأجيال اللاحقة بعد ذلك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4257","text":"من يسعون بشغف نحو تحقيق الملذات هم عبيد لها من حيث لا يشعرون.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4258","text":"القدح والذم والانتقاد بدون مبررات موضوعية علمية؛ بضاعة السفهاء والحمقى والأغبياء.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4259","text":"الجزاء من جنس العمل، فمن أسعد الفقراء والمساكين؛ أسعده الله رب العالمين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4260","text":"أفضل طريقة لبشاشة الوجه واستنارته الشعور بالسعادة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4261","text":"للشعور بالسعادة عوامل منها: البساطة وإسعاد المساكين وإنصاف المظلومين.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4262","text":"السعادة الدائمة الواضحة نتيجة الإيمان والأعمال الصالحة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4263","text":"استعن بذكر الله تعالى على نسيان أحزان الأمس وخوف الغد.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4264","text":"الحب مشاعر ملتهبة، والبغض مشاعر مشتعلة، فالعاقل من يتقي الله فيهما.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4265","text":"المؤمن إنسان يُحب الشهوات طبعا، لكنه يترك ما حرم الله منها إيمانا واحتسابا، وينفر من المكاره طبعا، لكنه يفعل ما يُحبه الله منها: كالجهاد والإنفاق إيمانا واحتسابا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4266","text":"تلاوة القرآن نور للفؤاد، وشرب العسل شفاء للأجساد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4267","text":"من أحب شيئا أكثر من ذكره، فمن أحب الله أكثر من ذكره جل وعلا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4268","text":"من علامات حب الله لعبده ومغفرته لذنوبه اتباع عبده لنبيه محمد عليه الصلاة والسلام.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4269","text":"إذا قبل القاضي منك الهدية صعب عليه أن يحكم بينكما بالسوية.","kind":"hikma","topic":"السياسة والقيادة","note":"له صيغ أخرى","source":"شذرات (ملف وورد)"},{"id":"m4270","text":"معرفة القاضي خير لك من المحامي والشهود.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4271","text":"الآراء تتبدل والأفكار تسوء أو تتعدل والحي لا تأمن عليه التغيير","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m4272","text":"قبل أن تظلم من دونك تذكر من فوقك سبحانه وتعالى.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4273","text":"زينة الرجل في عقله ولسانه، وزينة المرأة في حيائها وعفافها.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4274","text":"صادق من يخشى الله ويُحسن للناس.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4275","text":"انشر السرور واطوِ الأسرار.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4276","text":"لا تغضب، وإن غضبت فاجعل غضبك مثل القهوة، تُقدم في وقتها، وحلوة في مرارتها.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4277","text":"استعن على تفريج الهموم بالذكر والاستغفار، ومصاحبة الرجال الأخيار.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4278","text":"عاشر أخاك بالمعروف على عيوبه، وادع له واستر على ذنوبه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4279","text":"الصداقة مشاركة في الطباع، والزمالة مشاركة في العمل، والأخوة مشاركة في النسب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4280","text":"اتقِ دعوة المظاوم فإنها تصعد إلى الله مثل الشرارة، ليس بينها وبينه حجاب ولا ستارة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4281","text":"الإنسان يتعلم من أفعال النملة لا من أقوالها.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4282","text":"قد يتعلم الكبير من الصغير كما يتعلم الإنسان من النملة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4283","text":"من راقب أعمال النملة احتقر أعماله.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4284","text":"لا يحل لك أن تُؤذي حيوانا فكيف تُجيز لنفسك أن تُؤذي إنسانا","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4285","text":"رُب ذنب صغير صار كبيرا بالتباهي والاستهتار، ورب ذنب كبير صار صغيرا بالندم والاستغفار","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4286","text":"من عجز أن يُكابد قيام الليل وصيام النهار فليكثر من الذكر والاستغفار","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4287","text":"توكلوا على الله حق توكله فكونوا كالطير فالله وهبها آلات الكسب فهي تسعى على نفسها وفراخها فتغدوا خماصا وتروح بطانا","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4288","text":"الاختلاف في الأفكار والآراء والتوجهات الأصل فيها أنها ظاهرة اجتماعية صحية في البشر، ليتم بينهم تبادل الثقافات والمعارف والعروج في درجات العلم، فينبغي أن يتم النقاش بأدب الحوار وأخلاقيات الجدال بالتي هي أحسن، وإذا شَدَّ أحدهما فينبغي للطرف الآخر أن يُرخي، وإلا سوف يتفاقم الاختلاف، وتنقطع حبال المودة والتواصل والتفاهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4289","text":"السمعة الحسنة ثمرة الأعمال الحسنة المتكررة، والسمعة السيئة ثمرة عمل واحد سيئ.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4290","text":"اكتب همومك وفشلك على ساحل البحار، واحفر نجاحاتك وإنجازاتك على الأحجار.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4291","text":"تخيروا ألفاظكم لإخوانكم كما تتخيرون أطايب الثمار فإن الشيطان يلج من الفجوات ليُوغر الصدور ويُوحش النفوس بسبب كلمة عوراء أو لفظة شنعاء أو إشارة بلهاء أو نظرة استهزاء","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4292","text":"لا ترفس حمارا رفسك ولا تعض كلبا عضك ولا ترد على سفيه أساء إليك","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4293","text":"كيف يتم تزوير الألقاب وقلب الأخطاء إلى صواب. بعض المارقين الطامعين الذين يسفكون الدماء، يًصبحون من سادات المجتمع عن طريق القوة، والسيطرة على الأُمة فالثوار إذا فشلوا فهم مجرمون،يُسجنون ويُعدمون. وإذا نجحوا فهم من سادات المجتمع،يُوقرون ويُعظمون فالقوي يفرض الألقاب والمغلوب يُشدد عليه العقاب.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4294","text":"إذا تقربت إلى الناس بما يحبون من الاحترام والإكرام والإنعام والابتسام وطيب الكلام. والأخلاق الحميدة والعادات المجيدة والآراء السديد والمواقف الطيبة العديدة. أحبوك واحترموك وقدروك ونظروا إليك بإعجاب وإكبار.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4295","text":"الكتابة قَيْدُ العلم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4296","text":"الشكر قيد النِّعَم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4297","text":"صلة الأرحام تزيد في الأرزاق والأعمار.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4298","text":"السحاب عنوان الأمطار، والأمطار عنوان الألبان والثمار.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m4299","text":"لا ترجو الخير من العاق ولا من ذي النفاق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4300","text":"عبر موسى عليه السلام البحر بالإيمان، وغرق فرعون بالكفران، فالإيمان يُنجي، والكفر يُردي.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4301","text":"القول المعتمد في تربية الولد، هو مسؤولية الآباء تجاه الأبناء، ولا يكتفوا بالدعاء، فإن هذا تقصير بالأداء، فلا بد من التوجيه والنصيحة، بالأفعال والأقوال الفصيحة.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4302","text":"اتقوا التصرف في الغضب فإن الغضب جنون عارض.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4303","text":"اغرس شجرة الآن تنعم بظلالها وثمارها في مستقبل الزمان.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m4304","text":"اطلبوا الرفعة بالتواضع، واطلبوا الرزق بالاستغفار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4305","text":"رحلةُ الألفِ ميلٍ تبدأُ بخطوة.","kind":"mathal","topic":"النجاح والإبداع","note":"فالبدايات الصغيرة تصنع النهايات الكبيرة.","source":"شذرات (ملف وورد)"},{"id":"m4306","text":"لا تُعطِ الفقير سمكةً، بل علِّمه كيف يصطاد السمك.","kind":"mathal","topic":"المال والاقتصاد","note":"فالعطاءُ يُشبِع في الحال، أمّا التعليم فيُغني في الحال والمآل.","source":"شذرات (ملف وورد)"},{"id":"m4307","text":"من لم يسألَ ما يجهل بقيَ جاهلًا، ومن يسأل ما يجهل، صار عالما.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4308","text":"السؤال مفتاحُ العلم، والحفظ خِزانته.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4309","text":"إذا هبّتْ الرياح فاصنع طواحين، وإن سكنت الرياح فاصنع مراوح، اصنع ما يحتاجه الناس والسوق.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4310","text":"استثمار الواقع فيما ينفع خير من مقاومته.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4311","text":"أفضلُ وقتٍ لزرعِ شجرةٍ كان قبل عشرين عامًا، وثاني أفضل وقتٍ هو الآن.","kind":"mathal","topic":"النجاح والإبداع","note":"فما لا يدرك في الحال قد يدرك في المآل، فلا تجعل غير الممكن يزهدك في الممكن.","source":"شذرات (ملف وورد)"},{"id":"m4312","text":"لا تجعل ما فاتك من الفرص، يحبطك عن اغتنام ما أُتيح لك من الفرص.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4313","text":"من ملأ قلبه وعقله بأدب السلف صفا ذوقه، ورقّ سمعه، حتى تمجّ أذناه لغط الخلف؛ إذ ذاك كلامٌ نُقِع في ماء الحكمة فصار نورًا، وهذا لفظٌ غُمِس في زخرف القول فكان فتورًا. هي ثمرةٌ يانعة: تُزكّي النفس، وتُهذّب اللفظ، وتُقيم الميزان؛ فلا يقبل صاحبها إلا رصينًا، ولا يرضى إلا متينًا، قد استغنى بصفاء الموروث عن كدر المحدث، واكتفى بعيون التراث عن فضول الاصطلاح.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4314","text":"من اجتهد في مراعاة قواعد تجويد القرآن، وحسَّن صوته في الأداء والبيان، فقد أتى بالمطلوب المرغوب، الذي تتقبله العقول وتخشع له الجوارح والقلوب.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4315","text":"إذا أردت الانتشار فعليك بالإيجاز وبالاختصار وإذا أردت التنفير فعليك بالتمطيط وبالتطويل","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4316","text":"القويُّ حقًّا من ملك نفسه عند الغضب، لا من أخضع غيره بالقوة فقط.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4317","text":"السلام الذي يحفظ الأرواح، خيرٌ من عدلٍ تُراق في سبيله الدماء الكثيرة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4318","text":"أكثر الجموع ضجيجًا، ليست دائمًا أكثرها صوابا ولا أثرًا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4319","text":"إصدار الأوامر يسير، أمّا حمل تبعاتها فشاقٌّ ثقيل.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4320","text":"الحزم في موضعه حكمة وقوة، والتردد عند الحاجة إلى الحزم بابُ ضعفٍ وخسارة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4321","text":"لا يُقاس الرجال بما يقولون في زمن الرخاء، بل بما يصنعون ساعة الشدة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4322","text":"الأمة التي تنقسم على نفسها، تُضعف هيبتها قبل أن يُضعفها عدوها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4323","text":"النصر الحقيقي ليس في كسب المعركة فحسب، بل في تقليل الخسائر الباهظة بعدها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4324","text":"من اعتاد الانضباط في صغار الأمور، أُوتي الثبات في عظائمها.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4325","text":"القيادة ليست تشريفًا يطلبه المرء، بل أمانة يُحاسَب عليها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4326","text":"الزمن أغلى من الذهب؛ لأنه قطعة من عمرك وحياتك، فكل لحظة نضيعها هي فرصة لن تعود، ولو بذلنا لتحصيلها غاية الجهود.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m4327","text":"من يكتفي بما هو عليه لن يعرف التقدم، بل سيبقى في مكانه ثابتا لن ينفعه التندم.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4328","text":"الصبر هو مفتاح الحكمة، فمن صبر على الشدائد أدرك كنوز الفهم والفوائد.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m4329","text":"العلم هو نور العقل، فمن سلك دربه أضاء له طريقه في الحياة وما بعد الحياة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4330","text":"لا تنتظر الفرص لتطرق بابك، بل اصنعها بيديك، لأن من يزرع العمل الصالح يحصد النجاح الواضح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4331","text":"في بعض المعارك ساعةٌ يظن فيها الفريقان أن الهزيمة قد أحاطت بهما، فمن ثبت بعدها كان له الظفر.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m4332","text":"الاجتهاد الدائم يغلب الموهبة الخامدة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4333","text":"سلامٌ تُصان به الأرواح والحقوق، خيرٌ من نصرٍ تعقبه المآسي والجروح.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4334","text":"الصديق الصادق ثروةٌ لا تُقدَّر، وربَّ قريبٍ حميم لا يبلغ منزلة الصديق الصادق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4335","text":"أعظم الفتوح أن يفتح الإنسان باب الإيمان والأخلاق في قلوب الناس.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4336","text":"الشجاعة ثباتٌ عند الشدائد، لا اندفاعٌ عند الغضب السائد.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4337","text":"الأمم تُساد بالعدل والأمانة والانضباط، لا بضجيج الشعارات وكثرة الادعاءات والأمنيات.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4338","text":"الثبات عند اشتداد الخطوب، أول أبواب النصر في الحروب.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4339","text":"شجرة الحرية جذورها قوية.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4340","text":"النظام والانضباط دستور الجيش.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4341","text":"الصدق دعامة كل فضيلة، والكذب يهدم كل فضيلة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4342","text":"لا رقابة على التفكير حتي يتحول إلى التعبير أو التغيير.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4343","text":"الاستعداد للحرب يقيك الحرب ويحفظ السلام.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4344","text":"الصداقة القوية بطيئة النمو لكنها قوية الجذور.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4345","text":"السمعة الصالحة تُبنَى بالصدق والأمانة، وتُهدم بالكذب والخيانة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4346","text":"لا تُظهر للناس عيوبك فيكرهوك، ولا تُظهر لهم فضائلك فيحسدوك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4347","text":"الآمال تحقق الأعمال، واليأس يهدمها.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4348","text":"الحكومة ليست كلاما ووعودا، بل عملا وإنجازا.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4349","text":"الدستور الذي لا يخالف التعاليم الإسلامية، هو الدليل الذي نهتدي به.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4350","text":"خير ما يُقال الحكمة، وخير ما يُفعل تطبيقها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4351","text":"الحاكم العاقل من ساس شعبه بالرفق واللين، وصب جام غضبه علي الظالمين والمفسدين.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4352","text":"الحقيقة قد لا تظهر في الحال، لكنها لا تموت وإن طال الزمان.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m4353","text":"الأمة التي تُفرِّط في أخلاقها، تُفرِّط في مستقبلها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4354","text":"الاستقامة قوة خفية، يهابها الناس وإن قلَّ أصحابها.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4355","text":"كثرة الكلام أمارة على ضعف الحجة، أما صدق المعنى يستغني عن الإطالة والإسهاب.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4356","text":"لا تجعل غضب ساعة يُفسد ما بنيته في سنوات.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4357","text":"أعظم الانتصارات: أن ينتصر الإنسان على نفسه وشهوته.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4358","text":"من تعوَّد العدل في الأشياء الصغيرة، هان عليه العدل في الأشياء الكبيرة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4359","text":"الحكومات العادلة لا تميز بين الجماعات والأفراد، إلا بالأمانات والكفاءات.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4360","text":"لو أنصف الناس بعضهم، لما احتجنا لكثرة القضاة والمحامين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4361","text":"بقاء الدولة يقوم على ثلاث دعامات: القوة والأخلاق والعدالة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4362","text":"من أُعطي سلطة بلا رقيب، فالغالب أن هواه يقوده قبل عقله.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4363","text":"حرية الصحافة تُزعج المسؤولين، لكنها تحمي الأمة من الظلم والاستبداد والسلبيات.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4364","text":"التوسع في النفوذ بلا ضوابط ولا قيود، يُسخط العامة، ويمزق النسيج الوطني.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4365","text":"إذا اجتمع المال والسلطة وضعفت الأمانة، نشأت حضانة للفساد.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4366","text":"الشعب الواعي المثقف، هو الذي يحرس الحرية.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4367","text":"كثرة القوانين دليل على فساد الأخلاق وضياع الأمانة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4368","text":"أخطر ما دخل على الناس الفساد في ثوب المصلحة وعباءة الدين.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4369","text":"اختلاف الآراء لا يفسد المودة، وإنما يفسدها التعصب والتشنيع علي المخالف.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4370","text":"أعظم الانتصارات أن تحافظ الدولة على أمنها ووحدتها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4371","text":"الملك العادل يسمع من المخالف، ولا يستفزه الغضب والكبرياء.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4372","text":"إذا انشغل الناس بالخلافات الصغيرة، ضاعت المصالح الكبيرة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4373","text":"الاستقلال الحقيقي أن تملك الأمة امرها وقرارها، لا أن تكتفي برفع علمها وشعارها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4374","text":"أكثر من يطلبون السلطة، لا يفكرون بتحمل مسؤوليتها ولا أعبائها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4375","text":"السلام القائم على العدل والحكمة أبقى من نصرٍ يزرع الكراهية والأحقاد.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4376","text":"الأمم تُبنى بالصبر والعمل، لا بالشعارات والانفعالات.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4377","text":"غذاء العقل لا ينفد؛ فكل حكمة صادقة تفتح باب تأمل، وكل تجربة ناجحة تزيد الإنسان علما وبصيرة. وما أوتي الناس بعد التقوى والأخلاق خيرًا من عقلٍ راجح، ولسانٍ صادق، وقلبٍ ناصح، والله واسع الفضل والإحسان، وكل شيء عنده بتقدير وحكمة وميزان.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4378","text":"من تراخى في إطفاء الفتنة في بدايتها، شق عليه إطفاؤها في انتشارها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4379","text":"قوة الدولة في تعاون شعبها، لا في ارتفاع أصواتها وكثرة اقتراحاتها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4380","text":"الحرية بلا نظام فساد، والنظام بلا عدل استبداد.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4381","text":"إذا فقد القانون هيبته، كثرت الاعتداءات والمخالفات.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4382","text":"السياسة الحكيمة تقضي على الشر قبل أن يستفحل.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4383","text":"من أراد المجد لشعبه، بدأ بإصلاح الأخلاق والتعليم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4384","text":"لا يُصلح الأوطانَ شيءٌ مثل العدل، ولا يُفسدها شيءٌ مثل الظلم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4385","text":"الأمم لا تنهار فجأة، بل تتآكل حين يضعف فيها الصدق والأمانة والعدل، ويتفشى فيها الكذب الخيانة والجور.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4386","text":"إذا كانت أقوالك وأفعالك وتوجيهاتك، تُلهم السامعين والمشاهدين أن يفهموا أكثر، ويعملوا أكثر، ويتعلموا أكثر، فأنت قائد بطبعك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4387","text":"الصبر والثبات يذللان العوائق ويحققان الآمال.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m4388","text":"القيام بالواجب أوله مرّ وآخره حلو.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4389","text":"الحرية لا تُمنح لمن لا يحسن تطبيقها في محلها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4390","text":"الشجاعة ليست غياب الخوف، بل القدرة على حسن التصرف مع الخوف.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4391","text":"من اعتاد خدمة الحق، هان عليه مدح أهل الحق، وذم أهل الباطل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4392","text":"القوانين وحدها لا تحفظ النظام، بل لا بد من حسن التربية والأخلاق.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4393","text":"العلم يرفع صاحبه، والتواضع يهذب أخلاقه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4394","text":"أخلص لضميرك، وأنصف الحق من نفسك، ولو خالفك بعض المقربين منك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4395","text":"الإنسان القوي قد يُهزم، لكنه لا يسقط ما دام واثقا من سلامة مبدئه.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m4396","text":"الصبر على مرارة الإصلاح، خير من لذة الفساد العاجلة.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m4397","text":"خير القيادة ما قاد بالقدوة قبل الأوامر والقدرة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4398","text":"الملك يرى المملكة ميراثَ آبائه، وأمانةَ أسلافه، ومجدَ تاريخه، ومستقبلَ أبنائه؛ فلذلك يحرص على بنائها، ويجتهد في رُقيّها، ويصبر على إصلاحها، لأنه يعلم أن حسن أثره باقٍ في عقبه وذكره. أما رئيس الدولة المؤقت، فمدته محدودة، وولايته معدودة، فلا يستشعر في الغالب ذلك الامتداد العميق بين الماضي والمستقبل، ولا ذلك الارتباط المتجذر بالأرض والتاريخ والأسرة؛ ولذلك قد يغلب على بعضهم النظر القريب، والمصلحة العاجلة، والسياسة المرحلية. غير أن العبرة في النهاية بعدل الحاكم وحكمته وإخلاصه، لا بمجرد لقبه أو نوع نظامه؛ فكم من ملكٍ رفع الله به البلاد والعباد، وكم من رئيسٍ أخلص فأحسن السيرة والسداد، والله يؤتي الملك والحكمة من يشاء.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4399","text":"الإسلام دين إيجابي، يحب الخير للغير، ويكره الشر للبشر. فالإسلام دينُ بناءٍ ونماء، لا دينَ هدمٍ وعناء؛ يغرس الخير في الحياة حالًا، ويُثمر الأجر في الآخرة مآلًا. يحب للناس ما ينفعهم، ويحضُّ على أثرٍ يبقى بعد الرحيل: علمٍ يُهدي، وماءٍ يُسقي، وغرسٍ يُحيي، وولدٍ صالحٍ يدعو، ليظلَّ المؤمن مباركًا في حياته، ممتدَّ النفع بعد وفاته. فما أعظم دينًا يجعل الإحسان عبادة، والنفع صدقة، والأثر الطيب حياةً ثانية لصاحبه بعد الممات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4400","text":"دعاء المؤمن لأخيه بظهر الغيب، برهان الوفاء، وعنوان الصفاء، وجدير بالصعود إلى السماء، والقبول من أرحم الرحماء، فهو دعاءٌ تجرّد من الرياء، وفاض من قلبٍ نقيٍّ بالود والإخلاص والمحبة والإخاء.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4401","text":"العيدُ ليس ثوبا يُلبَس، بل شعورٌ يُلمَس، تصفو فيه القلوب، وتُغسَل الأحقاد والذنوب، وتُوصَل الأرحام والأيتام.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4402","text":"وما العيدُ بثوبٍ جديد، بل بقلبٍ لا يحملُ على أحد الحقد الشديد.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4403","text":"وفي العيد تُعرَف المعادن: فخيرُ الناس من كان عيدُه جبرًا لخواطر الضعفاء، ورحمةً للفقراء، وبِشرًا للغرباء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4404","text":"وكلُّ عيدٍ لا يزيدك قربًا من الله، ولطفًا بالخلق، فليس إلا عادةً تتكرر، لا عبادةً تُؤثِّر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4405","text":"إذا كانت أقوالك وأفعالك وأخلاقك تُلهم الناس أن يرقوا بأقوالهم وأفعالهم وأخلاقهم نحو الصالحات، فانت قدوة صالحة في الحياة، وسراج منير في الظلمات وبعد الممات.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4406","text":"الصبر مع العلم والبصيرة يجعل منك رجلا ملهما في الصغيرة والكبيرة.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m4407","text":"الواجبات أثقل من الشهوات، لكن عاقبتها أحمد وأزكى في الحياة وعند الممات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m4408","text":"من طوََع نفسه على قول الحق، سهل عليه قول الصدق والحق لله وعند الخلق.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4409","text":"القوانين تحفظ النظام والأمان، والأخلاق تحفظ القلوب والجوارح واللسان.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4410","text":"كل ما يُخالف الأخلاق من الحريات، يكون وبالا على الأفراد والجماعات.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4411","text":"العقل الذي لا يوافق الصواب، عقل لا يسلم من الخطأ والخطل والخراب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4412","text":"أفضل العقول، أن تملك نفسك عند الغضب، ورأيك عند الفتنة، ولسانك عندما تقول، وأثناء الحماس تصول.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4413","text":"الأمة التي تُعلي شأن العلم والعمل والأخلاق، أمة تجمع بين التقدم والرقي، وفي جميع الآفاق.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4414","text":"لا تُقاس قيمة الإنسان بما جمع، بل بما عمل وأصلح ونفع.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4415","text":"السياسة بلا مبادئ سريعة الإنحلال والفناء، والسياسة بالمبادئ اجدر بالثبات والبقاء.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4416","text":"من طلب الأمجاد بلا اجتهاد، كمن نصب خيمة بلا أوتاد.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4417","text":"السياسة بلا مبادئ ولا أخلاق، سوف تكون ثمرتها النفاق والشقاق.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4418","text":"التعليم قوة وحصن متين، والجهل قصر من تراب وطين.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4419","text":"رُبما كان تحقيق السلام، مع التنازل عن بعض الحقوق، أولى من إقامة عدلٍ تجرُّ عواقبه ضررًا أعظم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4420","text":"أعداؤك المتخفون بثياب الأصدقاء، أشد خطرًا من أعدائك المعلنين.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4421","text":"السمعة الطيبة أبقى من المنصب؛ فالمنصب يزول، والذكر الحسن يبقى ولا يزول.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4422","text":"خضراء الدِّمَن","kind":"mathal","topic":"الحياة الزوجية","note":"النبتة الخضراء الزاهية في روث البهائم: المراة الجميلة في الوسط السيء.","source":"شذرات (ملف وورد)"},{"id":"m4423","text":"عقيلة الملح","kind":"mathal","topic":"الحياة الزوجية","note":"اللؤلوة الناصعة في قاع البحر المالح: المرأة الفاتنة في البيئة السيئة.","source":"شذرات (ملف وورد)"},{"id":"m4424","text":"إذا أردتَ مفتاحَ قلبِ المرأة التي تنوي خِطبتها، فحدِّثها عن محاسنها الأخلاقية والآدابية، وأثنِ على فضائلها، وأظهر تقديرك لشخصيتها؛ فإن القلوب تُفتح بالمديح والتقدير، أكثر مما تُفتح بالوعود بالهدايا والتبشير.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m4425","text":"وبادروا بالزواج؛ فإن رُزقتَ زوجةً صالحةً سعدتَ بها وسَعِدتْ بك، وإن ابتُليتَ بأنَّانةٍ زنَّانةٍ، ثرثارةٍ سليطةٍ، ثم صبرتَ عليها، فإمّا أن تُصبحَ فيلسوفًا تُعلِّم الناس الحكمة، وإمّا صبورًا تُعلِّمهم فضيلة الصبر والتحمُّل!","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m4426","text":"إذا أردت أن تزن أخلاق رجل، فأَمِّرْه على فريق ثم انظر كيف يتصرف.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4427","text":"من يمشي بطيئا خير من الواقف، والواقف خير ممن يمشي إلى الوراء.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4428","text":"إذا أردت أن تستشرف المستقبل، فانظر إلى الماضي، فإن الأيام تتشابه، شبه التمرة بالتمرة، وكذلك الأجيال تتشابه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m4429","text":"إذا أردت أن تكون سعيدا، فانظر إلى من دونك، ولا تنظر إلى من فوقك.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4430","text":"الجهاز القوي الغالي أرخص من الجهاز الضعيف الرخيص.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m4431","text":"لا تبحث عن الأشرار فهم كثير، ولكن ابحث عن الأخيار فهم قليل.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4432","text":"إذا أردت أن تقطع شجرة في ساعتين، فاشحذ الفأس في ساعة، واقطع الشجرة في ساعة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4433","text":"البيت الذي يكثر فيه الصراع لا يدوم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4434","text":"ليس لديك من يمدحك أو يقدحك مثل ضميرك الحي.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4435","text":"لا تبحث عن النصر، بل ابحث عن الحق، فإن النصر مع الحق، عاجلا أم آجلا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4436","text":"ما أكثر الحكمة، وما أقل من يعمل بها، وما أقل من يداوم عليها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4437","text":"عيشوا على قدر الحاجة لا على قدر الرغبة، واتركوا هوس الماركات والكماليات والمباهات، فالقناعة تُغني، والتكلف يفقر ويردي.","kind":"hikma","topic":"المال والاقتصاد","note":"من مقالة: المشاكل العويصة والحلول الصحيحة","source":"شذرات (ملف وورد)"},{"id":"m4438","text":"كنا نطلب البركة ونقتصد، فأصبحنا نطلب المظاهر ونسرف؛ فثقلت المؤونة، وضاقت المعيشة، وتباعدت القلوب، ونفرت النفوس.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m4439","text":"إذا أغضبك أحد فاصمت قليلا وتعوذ من الشيطان، قبل أن تقول أو تفعل حتى لا تندم.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m4440","text":"لكل شيء ثمن، وثمن الحرية الجهاد بالقول والعمل.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4441","text":"خذ العبرة من الماضي، قبل أن تنطلق في المستقبل.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m4442","text":"احذر ممن يضمر لك العداوة، أكثر ممن يجاهرك بالعداوة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4443","text":"من عرف عدوه أخذ حذره، ومن لم يعرف عدوه يوشك أن يقع في شِراكه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4444","text":"لا تؤجل عمل اليوم إلى الغد، فإن لكل يوم عمله.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m4445","text":"أكثر الناس اعتبارًا بالتجارب، أكثرهم حذرا من العواقب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4446","text":"التحذير من تفسير القرآن بالرأي،فمن قال برأيه في القرآن فأصاب فقد أخطأ، أصاب في جزئية وأخطأ في المنهج. فلا بد من الرجوع إلى كتب التفسير المعتمدة للإسترشاد، قبل التفوه بالمعنى المراد.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4447","text":"السعادة ليست في الخمول والراحة، بل في لذّة العمل والإنجاز بإخلاص وصراحة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4448","text":"لا تُرهق نفسك بالحزن على ما فات، ولا بالخوف مما هو آت، فالعمر قصير فلا تضيعه بالتبذير ولا بالتقصير.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m4449","text":"التُّفَّاخَة لا ترتفع بجمال لونها ولا بزخرفة شكلها، وإنما ترتفع بما في جوفها من الغاز الخفيف، غاز الهيليوم، فإذا تسرّب الغاز الذي في داخلها هبطت إلى الأرض. وكذلك الإنسان؛ لا يرفعه مظهره: لا جماله ولا هندامه وأناقته، بل بما في داخل قلبه من إيمان وإخلاص، وما في عقله من فهم وعلم، وما في طبعه من أخلاق وفضائل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4450","text":"الملك أكثر اهتماما بالمملكة، لأنه يبني للأولاد وللأحفاد، أما الرئيس فيدبّر للأعوام المعدودة.","kind":"hikma","topic":"السياسة والقيادة","note":"تحت عنوان: مبررات من يفضل الحكم الملكي على غيره","source":"شذرات (ملف وورد)"},{"id":"m4451","text":"الملك ينظر إلى الدولة ميراثًا يتناقله الأبناء، والرئيس ينظر إليها ولايةً تنتهي بانتهاء مدتها.","kind":"hikma","topic":"السياسة والقيادة","note":"تحت عنوان: مبررات من يفضل الحكم الملكي على غيره","source":"شذرات (ملف وورد)"},{"id":"m4452","text":"الملك يحكم بعقل الأجيال، والرئيس يحكم في حدود الآجال.","kind":"hikma","topic":"السياسة والقيادة","note":"تحت عنوان: مبررات من يفضل الحكم الملكي على غيره","source":"شذرات (ملف وورد)"},{"id":"m4453","text":"الملك يُوَرِّث دولةً، والرئيس يسلّم إدارةً.","kind":"hikma","topic":"السياسة والقيادة","note":"تحت عنوان: مبررات من يفضل الحكم الملكي على غيره","source":"شذرات (ملف وورد)"},{"id":"m4454","text":"الملك يرى في ازدهار الدولة ازدهار إرثه، أما الرئيس فغالبًا ما يرى في نجاحها حصيلة عهده.","kind":"hikma","topic":"السياسة والقيادة","note":"تحت عنوان: مبررات من يفضل الحكم الملكي على غيره","source":"شذرات (ملف وورد)"},{"id":"m4455","text":"الملك يفكر بعمر السلالة، والرئيس يفكر بعمر الولاية.","kind":"hikma","topic":"السياسة والقيادة","note":"تحت عنوان: مبررات من يفضل الحكم الملكي على غيره","source":"شذرات (ملف وورد)"},{"id":"m4456","text":"عهد الملك فيه استقرار، وعهد الرئيس فيه تغيير، والاستقرار فيه تمكين وإعمار.","kind":"hikma","topic":"السياسة والقيادة","note":"تحت عنوان: مبررات من يفضل الحكم الملكي على غيره","source":"شذرات (ملف وورد)"},{"id":"m4457","text":"بعض الأحيان يكون الإنسان قريبا من تحقيق هدفه، فيغلب عليه اليأس فينصرف عن تحقيق هدفه، فيخسر مجهوده ووقته.","kind":"hikma","topic":"النجاح والإبداع","note":"له صيغ أخرى","source":"شذرات (ملف وورد)"},{"id":"m4458","text":"العبقرية: ومضة إلهام بعد تفكير عميق ومستمر، يتبعها جهد متواصل لتحقيق الهدف المراد.","kind":"hikma","topic":"النجاح والإبداع","note":"له صيغ أخرى","source":"شذرات (ملف وورد)"},{"id":"m4459","text":"لا قيمة للفرصة السانحة عند الخامل والكسلان والمتردد، لأنه لا يبادر في اغتنامها فتفوته تاركة له الحسرة والندامة.","kind":"hikma","topic":"النجاح والإبداع","note":"له صيغ أخرى","source":"شذرات (ملف وورد)"},{"id":"m4460","text":"حسبكَ من زوجتك أن تكون حسناتها أكثر من سيئاتها، وحسبكِ من زوجك أن تكون حسناته أكثر من سيئاته. وحسبك من صديقك أن يصدقك أكثر مما يجاملك، ويعينك أكثر مما يخذلك. وحسبك من جارك أن يكف أذاه، ويحفظ حقك، ويغض طرفه. وحسبك من قريبك أن يصلك إذا قطعت، ويذكرك إذا غفلت. وحسبك من شريكك أن يؤدي الأمانة، ويصدق في المعاملة. وحسبك من خادمك أن تكون حسناته أكثر من سيئاته، ونفعه أكثر من ضرره. وحسبك من الناس جميعًا أن يغلب خيرُهم شرَّهم، وإحسانُهم إساءَتهم. فالتمس الكمال لنفسك، واقبل من الناس غلبة الخير على الشر. فما حاز الكمال التام إلا الله جَلَّ وعلا، وما سَلِمَ من النقص إلا الله سبحانه وتعالى.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4461","text":"اذا التقت طائفتان في القتال، فالطائفة التي فيها شجعان هي الأغلبية، ولو كانت هي الأقلية عددا.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4462","text":"تمهَّل في التشاور، فإذا جاء وقت العمل فدع التفكير السلبي واشرع في العمل.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4463","text":"الأغنياء والأقوياء يستطيعون حماية أنفسهم، أما الفقراء والضعفاء فيحتاجون إلى عدالة القانون ونزاهة القضاء ولسان جماهير الشعب.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4464","text":"الرجل الشجاع ولد للمهام الصعبة، فيقتحم المخاطر ليدافع عن دينه ووطنه وينصر الحق، ويقف مع الضعيف والفقير والمظلوم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m4465","text":"المواطن الصالح هو الذي يهتم بمصالح الوطن والمواطنين.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4466","text":"لن يكون بيتك جنتك ما لم يكن معك زوجتك وأولادك وانت في أمان.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4467","text":"لا تشرع في الأعمال الكبيرة والمهمة قبل مشاورة الخبراء والمجربين، فإذا جاء وقت العمل فانطلق مستعينا بالله، ولا تلتفت إلى الوراء.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m4468","text":"الناس في الأمن سواء، فإذا جاء الخوف والفزع تباينوا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4469","text":"التماثل والتباين الناس يتماثلون في الطبائع؛ لأنها تنبع من الغرائز، ويتباينون في العادات؛ لأنها ثمرة البيئات، وصدى الأعمال، وأثر أنماط الحياة. فلأهل الجبال عادات غير عادات أهل السهول، ولأهل الصحارى طباع معيشة تخالف أهل السواحل، كما يختلف سكان البلاد الباردة عن سكان البلاد الحارة. وكذلك تختلف عادات التجار عن عادات الزراع، وعادات الزراع عن عادات الصناع، كما تبدو الفروق جلية بين رعاة الغنم ورعاة الإبل. فالغرائز توحد الطبائع، والبيئات تصوغ العادات.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m4470","text":"رَبِّ ولدك على الحق، يُرَبِّه الحق في غيابك.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4471","text":"التربية بالقدوة أبلغ من التربية بالموعظة.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4472","text":"ما زرعته بأولادك في صغرهم، يحصدون ثماره في كِبَرهم، فازرع فيهم: الدين والصلاة والأخلاق وطلب العلم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4473","text":"الحزم بلا رحمة قسوة، والرحمة بلا حزم تسيب.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4474","text":"أعظم ميراثك لأولادك: الدين، والأدب، والعلم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4475","text":"لا تؤدب ولدك بالغضب والقسوة، بل باللين والحكمة.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4476","text":"الاشتغال بالنافع عصمة من الاشتغال بالضار، فأشغل أولادك بالنافع.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4477","text":"الثناء على الصواب يُرَسِّخ الصواب، ويعصم من الوقوع في الخطأ.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4478","text":"الطفل متعطش للمعرفة والفهم، فليرى منك التصرفات النبيلة، وليسمع منك الكلمات الجميلة.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4479","text":"صلاح الوالدين من أقوى أسباب صلاح الأولاد.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4480","text":"امنح أولادك وقتا للنقاش والحوار، ومن خلاله تمنحهم الخبرات والتجارب النافعة التي اكتسبتها عبر السنين الطويلة.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4481","text":"علِّم ولدك كيف يفكر ويستنتج ويستدل ويناقش بأدب واحترام.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4482","text":"من أَمِنَ العقاب، تجرأ على الخطأ وجانب الصواب.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4483","text":"لا تُطفئ شمعة ولدك، بكثر العتاب والتأنيب والقسوة في التأديب.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4484","text":"أولادك أمانة الله عندك، وليست ملكية خاصة، فحافظ عليها، لا تضيعها ولا تهملها.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4485","text":"الأدب قبل العلم، والخُلُق قبل مخالطة الناس، والأمانة والابتسامة قبل فتح محل تجاري.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4486","text":"خير التربية: حبٌّ يُطمئن، وحزمٌ يُقوِّم، وقدوة صالحة تعلم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4487","text":"من صبر على تربية أولاده صغارا، قطف ثمارها كبارا.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4488","text":"البيت أول وأهم مدرسة، والوالدان أول وأهم معلمين.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4489","text":"ليست التربية أن يطيعك ولدك في حضورك، بل أن يستقيم صالحا إذا غبت عنه.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m4490","text":"الذاكرة كالعَضَلة: تقوى بالاستعمال، وتضمر بالإهمال.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4491","text":"الذاكرة لا تُوهَب؛ بل تُدرَّب.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4492","text":"العقل يصدأ بالإهمال، ويصفو بالمداومة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4493","text":"من هجر التفكير، هجرته الذاكرة وروعة التعبير.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4494","text":"من أهمل التفكير، ضعفت ذاكرته، وخانَه التدبير.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4495","text":"من توقف عن القراءة، توقف العقل عن اكتساب المعرفة، وتوقف اللسان عن الابداع في التعبير والتصوير.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m4496","text":"اتخذ كلبًا يحرس حقلك، وقطًّا يصيد فأرك، ولا تُودِع أحدًا أسرارك. واستر عن الناس أحوالك. وخذ حذرك من اثنين: جائعٍ جمع قرشين، وجاهلٍ حفظ سطرين؛ فهذا قد يشتري الناس بماله، وذاك يفتنهم بأقواله.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m4497","text":"لا تجعل أعراض الناس حديث مجالسك، ولا تكن وعاءً لكل خبر، ولا تُصدِّق كل ما يُقال.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4498","text":"فالكلمة قد تغيب عن الناس، لكنها لا تغيب عن الله، وأعراض العباد من أعظم الحقوق. فاحفظ لسانك؛ فإن الكلمة قد تراها هينة، وهي عند الله عظيمة، ولا يمحو تبعتها إلا عفو صاحبها، فلا تجلب لنفسك سخط الله، بسبب استهتارك وعدم مبالاتك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m4499","text":"الجسد لا يستقيم من غير رأس، والناس لا يستقيم أمرهم من غير ملك أو رئيس.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4500","text":"الملك الذي يظنه الناس في قمة الحرية والسعادة، قد يكون في الحقيقة أشقى الناس بالملك؛ فحيثما ذهب أحاطت به الحراسة، وحيثما جلس أحاط به الخوف.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4501","text":"فليس كل من ملك الناس ملك حريته؛ وربما كان أفقر الناس إلى الأمن من ظنوه أغناهم عن الخوف، ولأن تّقيم في كوخ وانت نائم آمن، خير من أن تّقيم في قصر وأنت خائف مذعور.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4502","text":"فالملك هو الرأس، والرأس كثير الأوجاع.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m4503","text":"المؤمن يقابل الناس بابتسامة، ويخفي في نفسه آلامه؛ كلامه لين، وطبعه هين، وفي محياه وسامة، وعلى شفتيه ابتسامة؛ مع ما في صدره من هموم، وفي هومه علوم. يضحك للناس، ولا يرسم على وجهه العبوس؛ يواسي الحزين، مع أنه حزين؛ ويمنح الأمل، وإن كان قلبه يتألم. فهو كالعسل في مذاقه، وكالبلسم في مرافقته؛ تراه طلق المحيا، وفي صدره أحزان مطوية طيا؛ يرجو من الله كشفها، ويحتسب عنده ثواب الصبر عليها.","kind":"hikma","topic":"الأخلاق والآداب","note":"تحت عنوان: صفات المؤمن الاجتماعية","source":"شذرات (ملف وورد)"},{"id":"m4504","text":"فالموت لا يطرق الباب، ولا يستأذن كبيرا ولا صغيرا، ولا غنيا ولا فقيرا؛ وكل حي سيذوق سكرات الموت، وكل نفس إلى ربها راجعة لا محالة، فطوبى ثم طوبى لمن اغتنم أيامه قبل انقضائها، وسنينه قبل انصرامها، وأصلح عمله قبل فوات الأوان، وأحسن إلى الناس قبل أن يصبح ذكرى الزمان.","kind":"hikma","topic":"الحياة والزمن","note":"من رثاء للأموات وتذكرة للأحياء","source":"شذرات (ملف وورد)"},{"id":"m4505","text":"فليس كل راتب كبير خسارة، ولا كل راتب قليل ربحا؛ فاليد التي تدر عليك الملايين، جديرة بأن تنال نصيبا منها. ادفع بسخاء لمن يزيد أرباحك، فالبخل على صانع الربح قد يكون أغلى من إكرامه.","kind":"hikma","topic":"المال والاقتصاد","note":"خلاصة قصة تحت عنوان: ادفع بسخاء لمن يحقق لك الأرباح الكثيرة","source":"شذرات (ملف وورد)"}];